	vector<edge>e[1000001];
	int seg[1000001*4];
	int mx,add;
	void build(int node,int l,int r)
	{
		if(l==r)
		{
			seg[l]=node;
			e[node].push_back(node+add);
			return;
		}
		int mid=(l+r)/2;
		e[node].push_back(edge(node*2,0));
		e[node].push_back(edge(node*2+1,0));
		e[node*2+add].push_back(edge(node+add,0));
		e[node*2+1+add].push_back(edge(node+add,0));
		build(node*2,l,mid);
		build(node*2+1,mid+1,r);
	}
	void init(int x)
	{
		for(int i=1;i<=add*2;i++)
			e[i].clear();
		mx=x;
		add=mx*4;
		build(1,1,mx);
	}
	void connect(int node,int st,int ed,int l,int r,int x,int ind)
	{
		if(st>r||ed<l) return;
		if(st>=l&&ed<=r)
		{
			e[seg[x]+add].push_back(edge(node,ind));
			return;
		}
		int mid=(st+ed)/2;
		connect(node*2,st,mid,l,r,x,ind);
		connect(node*2+1,mid+1,ed,l,r,x,ind);
	}
