int tot,cnt;
int dfn[1000001],low[1000001],vis[1000001],col[1000001];
stack<int>s;
void tarjan(int u)
{
	low[u]=dfn[u]=++cnt;
	s.push(u);
	vis[u]=1;
	for(int i=0;i<e[u].size();i++)
	{
		int to=e[u][i].to;
		if(!dfn[to])
		{
			tarjan(to);
			low[u]=min(low[u],low[to]);
		}
		else if(vis[to])
			low[u]=min(low[u],dfn[to]);
	}
	if(dfn[u]==low[u])
	{
		tot++;
		while(s.top()!=u)
		{
			col[s.top()]=tot;
			vis[s.top()]=0;
			s.pop();
		}
		col[u]=tot;
		vis[u]=0;
		s.pop();
	}
}
