typedef pair <int, int> pii;

int n;
int x[10010], y[10010];
vector <int> g[40010];
vector <int> t[40010];
vector <pii> col;

stack <int> s;
bool vis[40010];
int birth[40010];

void dfs(int x) {
	vis[x] = true;
	for(auto i : g[x]) {
		if(vis[i] == false) {
			dfs(i);
		}
	}
	s.push(x);
}
void transpose(int x, int mark) {
	birth[x] = mark;
	vis[x] = true;
	for(auto i : t[x]) {
		if(vis[i] == false) {
			transpose(i, mark);
		}
	}
}

void addEdge(int p, int q) {
	// cout << p << " " << q << endl;
	g[p].push_back(q);
	t[q].push_back(p);
}
bool good(int d) {
	for(int i = 0; i < (n << 2); i++) {
		g[i].clear();
		t[i].clear();
		vis[i] = false; 
	}
	for(int i = 0; i < n; i++) {
		int p = i << 1;
		int q = p | 1;
		addEdge((p << 1) | 1, q << 1);
		addEdge((q << 1) | 1, p << 1);
	}
	for(int i = 0; i < n+n; i++) {
		for(int j = 0; j < i; j++) {
			if(col[i].first - col[j].first < d) {
				int p = col[i].second;
				int q = col[j].second;
				addEdge(p << 1, (q << 1) | 1);
				addEdge(q << 1, (p << 1) | 1);
			}
		}
	}
	for(int i = 0; i < (n << 2); i++) {
		if(vis[i] == false) {
			dfs(i);
		}
	}
	memset(vis, false, sizeof vis);
	int cur = 0;
	while(!s.empty()) {
		int p = s.top();
		s.pop();
		if(vis[p] == false) transpose(p, ++cur);
	}
	for(int i = 0; i < n; i++) {
		int p = i << 1;
		int q = p | 1;
		if(birth[p << 1] == birth[(p << 1) | 1]) return false;
		if(birth[q << 1] == birth[(q << 1) | 1]) return false;
	}
	return true;
} 

int search(int b, int e) {
	if(b == e) {
		return b;
	}
	int m = (b + e + 1) >> 1;
	if(good(m)) return search(m, e);
	else return search(b, m-1);
}

