                }
                else{
                    query(1, 1, n, i, i, Q1);
                    query(1, 1, n, l, r, Q2);
                }
                for(int i=0;i<sz(Q2);i++) sat.nand((Q1[0]+4*n)*2, Q2[i]*2);
                for(int i=0;i<sz(Q3);i++) sat.nand((Q1[0]+4*n)*2, Q3[i]*2);
            }

            l = findLeft(1, p[1][i].fi - D + 1);
            r = findRight(1, p[1][i].fi + D - 1);
            if(l <= r){
                int idx = idx2[p[1][i].se];
                Q1.clear(), Q2.clear(), Q3.clear();
                if(l <= idx && idx <= r){
                    query(1, 1, n, i, i, Q1);
                    if(idx != l) query(1, 1, n, l, idx-1, Q2);
                    if(idx != r) query(1, 1, n, idx+1, r, Q3);
                }
                else{
                    query(1, 1, n, i, i, Q1);
                    query(1, 1, n, l, r, Q2);
                }
                for(int i=0;i<sz(Q2);i++) sat.nand((Q1[0]+4*n)*2, (Q2[i]+4*n)*2);
                for(int i=0;i<sz(Q3);i++) sat.nand((Q1[0]+4*n)*2, (Q3[i]+4*n)*2);
            }

            Q1.clear(), Q2.clear();
            query(1, 1, n, i, i, Q1);
            query(1, 1, n, idx2[p[0][i].se], idx2[p[0][i].se], Q2);

            sat.xoro(Q1[0]*2, (Q2[0]+4*n)*2);
        }
        int s = sat.two_sat();
        if(s == 1) ans = mid, lo = mid+1;
        else hi = mid-1;
    }
    printf("%d\n", ans);
}

