inline int ch(int n) {
	if (n <= 2 * IT_MAX) return n + 2 * IT_MAX;
	else return n - 2 * IT_MAX;
}

ll in[200050];
int u[400050];
vector <int> conn[140000];
vector <int> rconn[140000];
void epush(int a, int b) {
	conn[ch(a)].push_back(b);
	conn[ch(b)].push_back(a);
	rconn[a].push_back(ch(b));
	rconn[b].push_back(ch(a));
}
void getv(int st, int en, int S, int E, int n, vector<int>& Vu) {
	if (st > en) return;
	if (st == S && en == E) {
		Vu.push_back(u[n]);
		return;
	}
	int M = (S + E) / 2;
	getv(st, min(M, en), S, M, 2 * n, Vu);
	getv(max(M + 1, st), en, M + 1, E, 2 * n + 1, Vu);
}

bool dchk[140000];
int G[140000];
vector <int> Vstk;
void DFS1(int n) {
	dchk[n] = true;
	for (auto it : conn[n]) if (!dchk[it]) DFS1(it);
	Vstk.push_back(n);
}
void DFS2(int n, int g) {
	G[n] = g;
	for (auto it : rconn[n]) if (!G[it]) DFS2(it, g);
}

int main() {
	int N, i, j, k;
	scanf("%d", &N);
	for (i = 1; i <= N; i++) scanf("%lld %lld", &in[i], &in[N + i]);

	for (i = 1; i <= 2 * N; i++) u[i] = i;
	sort(u + 1, u + 2 * N + 1, [](int a, int b) {
		return in[a] < in[b];
	});
	for (i = 1; i <= 2 * N; i++) u[IT_MAX + i - 1] = u[i];
	for (i = 2 * N + 1; i <= IT_MAX; i++) u[IT_MAX + i - 1] = i;

	int st = 1, en = INF, mi, rv = 0;
	while (st <= en) {
		mi = (st + en) / 2;
		for (i = IT_MAX - 1; i >= 1; i--) {
			u[i] = 2 * IT_MAX - i;
			epush(u[i], ch(u[2 * i]));
			epush(u[i], ch(u[2 * i + 1]));
		}
		for (i = 1; i <= N; i++) {
			epush(i, N + i);
			epush(ch(i), ch(N + i));
		}

		vector <int> Vu;
		int p = 1;
		for (i = 1; i <= 2 * N; i++) {
			Vu.clear();
			while (p < 2 * N) {
				if (in[u[IT_MAX - 1 + p + 1]] >= in[u[IT_MAX - 1 + i]] + mi) break;
				p++;
			}
			getv(i + 1, p, 1, IT_MAX, 1, Vu);
			for (auto it : Vu) epush(ch(u[IT_MAX+i-1]), ch(it));
		}

		for (i = 1; i <= 4 * IT_MAX; i++) if (!dchk[i]) DFS1(i);
		reverse(all(Vstk));
		int gc = 0;
		for (auto it : Vstk) if (!G[it]) DFS2(it, ++gc);
		for (i = 1; i <= 2 * IT_MAX; i++) if (G[i] == G[i + 2 * IT_MAX]) break;
		if (i > 2 * IT_MAX) {
			rv = mi;
			st = mi + 1;
		}
		else en = mi - 1;

		for (i = 1; i <= 4 * IT_MAX; i++) {
			dchk[i] = 0;
			G[i] = 0;
			conn[i].clear();
			rconn[i].clear();
		}
		Vstk.clear();
	}
	return !printf("%d\n", rv);
}

#include<bits/stdc++.h>

using namespace std;

const int INF = 1 << 30;

int N, X[20000], Y[20000];
bitset< 20000 > graph[20000];

bool used[20000];
int cmp[20000];
int order[20000];
int ptr;

void dfs(int idx)
{
  if(used[idx]++) return;
  for(int i = 0; i < N * 2; i++) if(graph[idx][i]) dfs(i);
  order[ptr++] = idx;
}

void rdfs(int idx, const int cnt)
{
  if(~cmp[idx]) return;
  cmp[idx] = cnt;
  for(int i = 0; i < N * 2; i++) if(graph[i][idx]) rdfs(i, cnt);
}

bool cross(int s, int t, int g)
{
  if(s > t) swap(t, s);
  return (t - s < g);
}

bool check(int v)
{
  for(int i = 0; i < 2 * N; i++) graph[i].reset();

  for(int i = 0; i < N; i++) {
    for(int j = i + 1; j < N; j++) {
      if(cross(X[i], X[j], v)) {
        graph[i << 1][(j << 1) | 1] = true;
        graph[j << 1][(i << 1) | 1] = true;
      }
      if(cross(X[i], Y[j], v)) {
        graph[i << 1][j << 1] = true;
        graph[(j << 1) | 1][(i << 1) | 1] = true;
      }
      if(cross(Y[i], X[j], v)) {
        graph[(i << 1) | 1][(j << 1) | 1] = true;
        graph[j << 1][i << 1] = true;
      }
      if(cross(Y[i], Y[j], v)) {
        graph[(i << 1) | 1][j << 1] = true;
        graph[(j << 1) | 1][i << 1] = true;
      }
    }
  }
  memset(used, false, sizeof(used));
  memset(cmp, -1, sizeof(cmp));
  ptr = 0;
  for(int i = 0; i < 2 * N; i++) dfs(i);
  for(int i = ptr - 1; i >= 0; i--) rdfs(order[i], i);
  for(int i = 0; i < 2 * N; i += 2) if(cmp[i] == cmp[i + 1]) return (false);
  return (true);
}

int main()
{
  scanf("%d", &N);
  for(int i = 0; i < N; i++) {
    scanf("%d %d", &X[i], &Y[i]);
  }

  int ret = INF;
  for(int i = 0; i < N; i++) {
    for(int j = i + 1; j < N; j++) {
      int st = max({X[i] - X[j], X[i] - Y[j], Y[i] - X[j], Y[i] - Y[j]});
      st = max({st, X[j] - X[i], X[j] - Y[i], Y[j] - X[i], Y[j] - Y[i]});
      ret = min(ret, st);
    }
  }

  int low = ret - 1000, high = ret;
  while(high - low > 0) {
    int mid = (low + high + 1) >> 1;
    if(check(mid)) low = mid;
    else high = mid - 1;
  }

  cout << low << endl;
}

