const int MAX_N = 100005;

class SAT {
private:
	void _dfs(int u){
		used[u] = true;
		for(int v : G[u]){
			if(!used[v]){
				_dfs(v);
			}
		}
		post_order.push_back(u);
	}
	void _rdfs(int u, const int k){
		used[u] = true;
		cmp[u] = k;
		for(int v : rG[u]){
			if(!used[v]){
				_rdfs(v,k);
			}
		}
	}
	int _scc(){
		fill(used.begin(),used.end(),false);
		post_order.clear();
		rep(u,2*V){
			if(!used[u]){
				_dfs(u);
			}
		}
		fill(used.begin(),used.end(),false);
		int k=0;
		for(int i=2*V-1;i>=0;i--){
			if(!used[post_order[i]]){
				_rdfs(post_order[i],k++);
			}
		}
		return k;
	}

public:
	int V;	//頂点数
	vector<vector<int> > G,rG;
	vector<int> post_order; //帰りがけ順の並び
	vector<bool> used; //すでに調べたかどうか
	vector<int> cmp;	//属する強連結成分のトポロジカル順序
	set<P> es;

	SAT(int node_size) : V(node_size), G(2*V), rG(2*V), used(2*V), cmp(2*V){}
	inline void _add_edge(int from, int to){
		G[from].push_back(to), rG[to].push_back(from);
	}
    inline void add_edge(int from, int to){
		es.insert(P(from, to)), es.insert(P((to+V)%(2*V),(from+V)%(2*V)));
	}
	//充足可能性判定
	bool ok(){
		each(val, es){
			_add_edge(val.fi, val.se);
		}
	    _scc();
	    rep(i,V){
	        if(cmp[i] == cmp[V+i]){
	            return false;
	        }
	    }
	    return true;
	}
	//真のものは1,偽のものは0を返す(解の構成)
	void restore(vector<int>& ans){
		ans.resize(V);
	    rep(i,V){
			ans[i] = (cmp[i] > cmp[V+i]);
	    }
	}
};

int n, N, V;
vector<P> vec, num;

void query(const int id, int a, int b, SAT& st, int k = 0, int l = 0, int r = -1){
    if(r < 0) r = N;
    if(r <= a || b <= l){
        return;
    }
    if(a <= l && r <= b){
        st.add_edge(id, k+V);
        return;
    }else{
        query(id,a,b,st,2*k+1,l,(l+r)/2), query(id,a,b,st,2*k+2,(l+r)/2,r);
    }
}

bool possible(int d)
{
    SAT st(V);
    rep(i,n){
		st.add_edge(num[i].fi+N-1+V, num[i].se+N-1);
    }
    for(int i=N-2; i>=0; i--){
		st.add_edge(2*i+1, i), st.add_edge(2*i+2, i);
    }
    rep(i,2*n){
        int s = lower_bound(all(vec),P(vec[i].fi-d+1,-1)) - vec.begin();
        if(s < i) query(i+N-1, s, i, st);
        int e = upper_bound(all(vec),P(vec[i].fi+d-1,INF)) - vec.begin();
        if(i+1 < e) query(i+N-1, i+1, e, st);
    }
    return st.ok();
}

int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> n;
    vec.resize(2*n);
    N = 1;
    while(N < 2*n){
        N *= 2;
    }
    V = 2*N-1;
    num.resize(n, P(-1, -1));
    rep(i,n){
        int x,y;
        cin >> x >> y;
        vec[2*i] = P(x,i), vec[2*i+1] = P(y,i);
    }
    sort(all(vec));
    rep(i,2*n){
        int id = vec[i].se;
        if(num[id].fi < 0){
            num[id].fi = i;
        }else{
            num[id].se = i;
        }
    }
    int l = 0, r = vec.back().fi - vec[0].fi;
    while(r-l>1){
        int mid = (l+r)/2;
        if(possible(mid)){
            l = mid;
        }else{
            r = mid;
        }
    }
    cout << l << "\n";
    return 0;
}

