int dfs_scc(int u) {
    *sct++ = u; inst[u] = 1;
    dfn[u] = low[u] = ++dfc;
    for (int v : g[u]) {
        if (!dfn[v]) low[u] = min(low[u], dfs_scc(v));
        else if (inst[v]) low[u] = min(low[u], dfn[v]);
    }
    if (dfn[u] == low[u])
        for (++scc; *sct != u; --sct)
            bel[sct[-1]] = scc, inst[sct[-1]] = 0;
    return low[u];
}

bool check(int d, int n) {
    int m = 2 * n;
    nc = m;
    for (int i = 1; i <= m; ++i)
        g[i].clear();
    build(1, 1, m + 1);
    //cout << string(79, '-') << endl;
    for (int i = 1; i <= m; ++i) {
        int lx = pos[i].first - d, rx = pos[i].first + d;
        int l = upper_bound(pos + 1, pos + m + 1, piii(lx, pii(inf,inf))) - pos;
        int r = lower_bound(pos + 1, pos + m + 1, piii(rx, pii(0,0))) - pos;
        int x = pos[i].second.first;
        adde(l, i, x, 1, 1, m + 1);
        adde(i + 1, r, x, 1, 1, m + 1);
    }
    //cout << string(79, '=') << endl;
    scc_clr(nc);
    for (int i = 1; i <= nc; ++i)
        if (!dfn[i]) dfs_scc(i);

    for (int i = 1; i <= m; ++i) {
        if (i & 1) {
            if (bel[i] == bel[i + 1])
                return false;
        }
    }
    return true;
}

