vi g[8*N],rg[8*N],id[8*N],nodes;
int Not(int x){
	if(x<8*n)
		return x+8*n;
	return x-8*n;
}

void build(int u, int s, int e){
	nodes.pb(u);
	nodes.pb(Not(u));
	if(s==e){
		id[t[s].second].pb(u);
		in[s]=u;
		return;
	}
	build(u*2,s,(s+e)/2);
	build(u*2+1,(s+e)/2+1,e);
	g[u].pb(u*2);
	g[u].pb(u*2+1);
	rg[u*2].pb(u);
	rg[u*2+1].pb(u);
}

void addEdge(int x, int y){
	g[Not(x)].pb(y);
	g[Not(y)].pb(x);
	rg[y].pb(Not(x));
	rg[x].pb(Not(y));
}
int l,r;
stack<ii> un;
void update(int u, int s, int e, int x){
	if(s>r || e<l)
		return;
	if(s>=l && e<=r){
		g[Not(x)].pb(u);
		rg[u].pb(Not(x));
		un.push(ii(Not(x),u));
		return;
	}
	update(u*2,s,(s+e)/2,x);
	update(u*2+1,(s+e)/2+1,e,x);
}
bool vis[8*N];
int cmp[8*N];
stack<int> st;
void dfs(int u){
	vis[u]=true;
	for(int i=0; i<g[u].size(); ++i)
		if(!vis[g[u][i]])
			dfs(g[u][i]);
	st.push(u);
}
void dfs(int u, int cc){
	cmp[u]=cc;
	for(int i=0; i<rg[u].size(); ++i)
		if(cmp[rg[u][i]]==-1)
			dfs(rg[u][i],cc);
}
bool can(int d){
	while(!un.empty()){
		ii e=un.top();
		un.pop();
		g[e.first].pop_back();
		rg[e.second].pop_back();
	}
	for(int i=1; i<t.size(); ++i){
		l=lower_bound(all(t),ii(t[i].first-d+1,0))-t.begin();
		r=i-1;
		update(1,1,2*n,in[i]);
		l=i+1;
		r=upper_bound(all(t),ii(t[i].first+d-1,oo))-t.begin()-1;
		update(1,1,2*n,in[i]);
	}
	memset(vis,0,sizeof(vis));
	for(int i=0; i<nodes.size(); ++i)
		if(!vis[nodes[i]])
			dfs(nodes[i]);
	int cc=0;
	memset(cmp,-1,sizeof(cmp));
	while(!st.empty()){
		int u=st.top();
		st.pop();
		if(cmp[u]!=-1)continue;
		dfs(u,cc++);
	}
	for(int i=0; i<nodes.size(); ++i)
		if(cmp[nodes[i]]==cmp[Not(nodes[i])])
			return false;
	return true;
}
