		addEdge(x,y);
		addEdge(Not(x),Not(y));
	}
	int lo=0, hi=oo, md, bst=0;
	while(lo<=hi){
		md=(lo+hi)/2;
		if(can(md)){
			bst=md;
			lo=md+1;
		}else
			hi=md-1;
	}
	cout<<bst<<endl;
	return 0;	
}

