struct strongly_connected{
	vector<int> gph[MAXN];
	vector<int> rev[MAXN];
	vector<int> dfn;
	int vis[MAXN], comp[MAXN];
	void clear(){
		memset(vis, 0, sizeof(vis));
		memset(comp, 0, sizeof(comp));
		dfn.clear();
		for(int i=0; i<MAXN; i++){
			gph[i].clear();
			rev[i].clear();
		}
	}
	void add_edge(int x, int y){ 
		gph[x].push_back(y);
		rev[y].push_back(x);
	}
	void dfs(int x){
		if(vis[x]) return;
		vis[x] = 1;
		for(auto &i : gph[x]) dfs(i);
		dfn.push_back(x);
	}
	void rdfs(int x, int p){
		if(comp[x]) return;
		comp[x] = p;
		for(auto &i : rev[x]) rdfs(i, p);
	}
	int get_scc(int n){
		int piv = 0;
		for(int i=0; i<n; i++) if(!vis[i]) dfs(i);
		reverse(dfn.begin(), dfn.end());
		for(auto &i : dfn) rdfs(i, ++piv);
		return piv;
	}
};

struct twosat{
	strongly_connected scc;
	int n; // = number of clauses
	void init(int _n){ scc.clear(); n = _n; }
	int NOT(int x){ return x >= n ? (x - n) : (x + n); }
	void add_edge(int x, int y){ // input ~x to denote NOT
		if((x >> 31) & 1) x = (~x) + n;
		if((y >> 31) & 1) y = (~y) + n;
		scc.add_edge(x, y), scc.add_edge(NOT(y), NOT(x));
	}
	bool satisfy(vector<bool> &res){
		res.resize(n);
		scc.get_scc(2*n);
		for(int i=0; i<n; i++){
			if(scc.comp[i] == scc.comp[NOT(i)]) return 0;
			if(scc.comp[i] < scc.comp[NOT(i)]) res[i] = 0;
			else res[i] = 1;
		}
		return 1;
	}
}twosat;

