using namespace std;

using LL = long long;
using PII = pair<LL,LL>;
using VI = vector<int>;

int SCC(const vector<VI>& G, VI& group) {
  int N = G.size();
  VI order(N, -2), index(N);
  int num = 0;
  function<void(int,int)> dfs1 = [&](int u, int p)->void {
	order[u] = -1;
	for(int to: G[u]) {
	  if(to == p || order[to] != -2) continue;
	  dfs1(to, u);
	}
	index[num] = u;
	order[u] = num++;
  };
  for(int i=0;i<N;++i) {
	if(order[i] != -2) continue;
	dfs1(i, -1);
  }

  vector<VI> rG(N);
  for(int i=0;i<N;++i)
	for(int to: G[i])
	  rG[to].push_back(i);

  group.assign(N, -1);
  int gid = 0;
  function<void(int,int)> dfs2 = [&](int u, int p){
	group[u] = gid;
	for(int to: rG[u]) {
	  if(to == p || group[to] != -1) continue;
	  dfs2(to, u);
	}
  };

  for(int i=N-1;i>=0;--i) {
	if(group[index[i]] != -1) continue;
	dfs2(index[i], -1);
	++gid;
  }

  return gid;
}

// N variables
// [0,N) are positive literals
// [N,2N) are negative literals
bool sat2(int N, const vector<PII>& cl) {
  function<int(int)> neg = [=](int x) {
	if(x < N) return x + N;
	return x - N;
  };

  vector<VI> G(2*N);
  for(auto&& p: cl) {
	G[neg(p.first)].push_back(p.second);
	G[neg(p.second)].push_back(p.first);
  }

  VI gp;
  SCC(G, gp);
  for(int i=0;i<N;++i)
	if(gp[i] == gp[i+N])
	  return false;

  return true;
}

