    long long i;
    long long v;
    long long left;
    long long right;
};

class xxIntu {
public:
    bool operator()(const XX& riLeft, const XX& riRight) const {
        //第2条件
        if((riLeft.v) == (riRight.v)){
            return riLeft.i < riRight.i;//<:昇順(小さいものから順番)、>:降順(大きいものから順番)
        }
        //第1条件
        return (riLeft.v) < (riRight.v);
    }
};

class xxIntk {
public:
    bool operator()(const XX& riLeft, const XX& riRight) const {
        //第3条件
        if((max(riLeft.right,riLeft.left)) == (max(riRight.right,riRight.left))){
            return (riLeft.v) < (riRight.v);
        }
        //第2条件
        if((min(riLeft.right,riLeft.left)) == (min(riRight.right,riRight.left))){
            return (max(riLeft.right,riLeft.left)) < (max(riRight.right,riRight.left));
        }
        //第1条件
        return (min(riLeft.right,riLeft.left)) < (min(riRight.right,riRight.left));
    }
};


int ppar[200001];
int rrank[200001];

void init(int n){
    for(int i=1;i<=n;i++){
        ppar[i]=i;
        rrank[i]=0;
    }
}

int find(int x){
    if(ppar[x]==x){
        return x;
    }else{
        return ppar[x]=find(ppar[x]);
    }
}

void unite(int x,int y){
    x=find(x);
    y=find(y);
    if(x==y){
        return;
    }
    if(rrank[x]<rrank[y]){
        ppar[x]=ppar[y];
    }else{
        ppar[y]=x;
        if(rrank[x]==rrank[y]){
            rrank[x]++;
        }
    }
}
bool same(int x,int y){
    return find(x)==find(y);
}

//kruskal
struct edge{
    int u;
    int v;
    int cost;
};

bool comp(edge& e1,edge& e2){
    return e1.cost < e2.cost;
}

edge es[2000];
int V,E;
int ans=0;
int kruskal(){
    sort(es,es+E,comp);
    init(V);
    int res = 0;
    for(int i=0;i<E;i++){
        edge e = es[i];
        if(!same(e.u,e.v)){
            unite(e.u,e.v);
            res+=e.cost;
            ans++;
        }
    }
    return res;
}


