bool vis2[2 * MAX_N];
int comp[2 * MAX_N];

void dfs1(int u, vector<int> &sorted) {
    if (vis1[u]) return;
    vis1[u] = true;
    for (int v : adj[u]) {
        dfs1(v, sorted);
    }
    sorted.push_back(u);
}

void dfs2(int u, int c) {
    if (vis2[u]) return;
    vis2[u] = true;
    comp[u] = c;
    for (int v : adj[u]) {
        dfs2(v, c);
    }
}

inline int opposite(int i) {
    return i < n ? (i + n) : (i - n);
}

bool works(int val) {
    // printf("works(%d)\n", val);
    for (int i = 0; i < 2 * n; i++) {
        vis1[i] = false;
        vis2[i] = false;
        adj[i].clear();
    }

    deque<int> active;
    deque<int> rem_times;
    for (pair<int, int> event : events) {
        // printf("Event: <%d, %d>\n", event.first, event.second);
        while (!rem_times.empty() && event.first >= rem_times.front()) {
            // printf(" - Removing active item %d (expired at time %d)\n", active.front(), rem_times.front());
            active.pop_front();
            rem_times.pop_front();
        }

        for (int other : active) {
            // adj[opposite(other)].push_back(event.second);
            adj[event.second].push_back(opposite(other));
            // adj[opposite(event.second)].push_back(other);
            adj[other].push_back(opposite(event.second));
        }

        active.push_back(event.second);
        rem_times.push_back(event.first + val);
    }

    vector<int> sorted;
    for (int i = 0; i < 2 * n; i++) {
        if (!vis1[i]) {
            dfs1(i, sorted);
        }
    }

    int cc = 0;
    for (int i = 0; i < 2 * n; i++) {
        if (!vis2[sorted[i]]) {
            dfs2(sorted[i], cc++);
        }
    }

    for (int i = 0; i < n; i++) {
        if (comp[i] == comp[i + n]) {
            return false;
        }
    }

    return true;
}

