    for (int i = 1;i <= n;i++){
        for (int j = i + 1;j <= n;j++){
            int a = p[i].F,b = p[i].S,c = p[j].F,d = p[j].S;
            if (abs(a - c) < m){
                addedge(i,j + n);
                addedge(j,i + n);
                cnt++;
            }
            if (abs(a - d) < m){
                addedge(i,j);
                addedge(j + n,i + n);
                cnt++;
            }
            if (abs(b - c) < m){
                addedge(i + n,j + n);
                addedge(j,i);
                cnt++;
            }
            if (abs(b - d) < m){
                addedge(i + n,j);
                addedge(j + n,i);
                cnt++;
            }
            if (cnt >= 1e8) return 0;
        }
    }
    st.clear();
    for (int i = 1;i <= 2 * n;i++){
        if (vis[i] == 0){
            vis[i] = 1;
            dfsout(i);
        }
    }
    reverse(st.begin(),st.end());
    for (int i = 1;i <= 2 * n;i++) vis[i] = 0;
    int cscc = 0;
    for (int i = 1;i <= 2 * n;i++){
        int u = st[i - 1];
        if (vis[u] == 0){
            cscc++;
            vis[u] = 1;
            dfsin(u,cscc);
        }
    }
    for (int i = 1;i <= n;i++){
        if (scc[i] == scc[i + n]) return 0;
    }
    return 1;
}
