	T *a, *b, *c;
	int rnk = find(root, x[k][use[k]] + inf);
	split(root, rnk + 1, b, c);
	split(b, rnk - 1, a, b);
	// dbg(a); dbg(b); dbg(c);
	T *nw = new T(b -> sum);
	del_T(b); b = nw;
	root = merge(merge(a, b), c);
	// dbg(root);
}

void add(int k) {
	// cerr << "add " << k << endl;
	T *a, *b, *c;
	int rnk = find(root, x[k][use[k]] + inf);
	split(root, rnk, b, c);
	split(b, rnk - 1, a, b);
	// dbg(a); dbg(b); dbg(c);
	T *d = new T(x[k][use[k]] + inf - (a ? a -> sum : 0));
	T *e = new T((a ? a -> sum : 0) + b -> sum - x[k][use[k]] - inf);
	T *nw = merge(d, e);
	del_T(b); b = nw;
	root = merge(merge(a, b), c);
	// dbg(root);
