    tmp[i+n] = (data) {i+n,y[i]};
  }
  sort(tmp+1,tmp+(n<<1)+1);
  cur = n<<1;
  bas = cur<<1|1;
  int l = 1, r = tmp[n<<1].v, ans = 0, mid;
  while (l <= r) {
    mid = (l + r) >> 1;
    if (check(mid)) l = mid+1, ans = mid;
    else r = mid-1;
  }
  printf("%d\n",ans);
  return 0;
}

