using namespace std;

const int maxn = 100000, maxnv = maxn * 6;
const int inf = 1e9;

int n;
pair<int, int> point[maxn << 1];

int nv;
vector<int> g[maxnv];
int dfn[maxnv], clk;
int stk[maxnv], top;
int cntscc, sccid[maxnv];

int Tarjan(int u) {
  int low = dfn[u] = clk++;
  stk[top++] = u;
  for (int i = 0; i < g[u].size(); ++i) {
    int v = g[u][i];
    if (dfn[v] == -1) {
      low = min(low, Tarjan(v));
    } else if (sccid[v] == -1) {
      low = min(low, dfn[v]);
    }
  }
  if (low == dfn[u]) {
    while (true) {
      int v = stk[--top];
      sccid[v] = cntscc;
      if (v == u) {
        break;
      }
    }
    ++cntscc;
  }
  return low;
}

bool SolveSat(void) {
  memset(dfn, -1, nv * sizeof(int));
  memset(sccid, -1, nv * sizeof(int));
  clk = top = cntscc = 0;
  for (int i = 0; i < nv; ++i) {
    if (dfn[i] == -1) {
      Tarjan(i);
    }
  }
  for (int i = 0; i < n; ++i) {
    if (sccid[i << 1] == sccid[i << 1 | 1]) {
      return false;
    }
  }
  return true;
}

#define TREE(i) ((n << 1) + (i))
#define LEAF(i) ((n << 2) + (i))
#define POINT(i) (i)

void AddEdge(int i, int l, int r) {
  for (l += n << 1, r += n << 1; l < r; l >>= 1, r >>= 1) {
    if (l & 1) {
      g[POINT(i)].push_back(TREE(l++));
    }
    if (r & 1) {
      g[POINT(i)].push_back(TREE(--r));
    }
  }
}

bool IsValid(int d) {
  nv = n * 6;
  for (int i = 0; i < nv; ++i) {
    g[i].clear();
  }

  for (int i = 1; i < n << 1; ++i) {
    g[TREE(i)].push_back(TREE(i << 1));
    g[TREE(i)].push_back(TREE(i << 1 | 1));
  }
  for (int i = 0; i < n << 1; ++i) {
    g[LEAF(i)].push_back(POINT(point[i].second ^ 1));
  }

  for (int i = 0; i < n << 1; ++i) {
    int x = point[i].first;
    int l = upper_bound(point, point + (n << 1), make_pair(x - d, inf)) - point;
    int r = lower_bound(point, point + (n << 1), make_pair(x + d, -inf)) - point;
    AddEdge(point[i].second, l, i);
    AddEdge(point[i].second, i + 1, r);
  }

  return SolveSat();
}

int main(void) {
  scanf("%d", &n);
  for (int i = 0; i < n; ++i) {
    int pos1, pos2;
    scanf("%d%d", &pos1, &pos2);
    point[i << 1] = make_pair(pos1, i << 1);
    point[i << 1 | 1] = make_pair(pos2, i << 1 | 1);
  }
  sort(point, point + (n << 1));

  int low = 0, high = 1e9;
  while (low < high) {
    int mid = high - (high - low >> 1);
    if (IsValid(mid)) {
      low = mid;
    } else {
      high = mid - 1;
    }
  }

  printf("%d\n", low);
  return 0;
}

