		while(r < du && abs(P[r + 1].val - P[i].val) < cur) r ++;
		if(l <= i - 1)
		addtag(rt , P[i].id , l , i - 1);
		if(i + 1 <= r)
		addtag(rt , P[i].id , i + 1 , r);
	}
}

#define Foreachson(i , x) for(int i = fir[x];i;i = ne[i])
bool die = 0;

void dfs(int x) {
