vector<vector<int> > from;
deque<bool> used;
vector<int> c; // i-th vertex in g is in c_i-th vertex in scc-decomposed g
struct strongly_connected_components {
    static int decompose(vector<vector<int> > const & g) { // adjacent list
        strongly_connected_components scc(g);
        return scc.k;
    }
private:
    int n;
    vector<vector<int> > const & to;
    explicit strongly_connected_components(vector<vector<int> > const & g) : n(g.size()), to(g) {
        if (from.size() != n) from.resize(n);
        repeat (i,n) from[i].clear();
        repeat (i,n) for (int j : to[i]) from[j].push_back(i);
        decompose();
    }
    vector<int> vs;
    void dfs(int i) {
        used[i] = true;
        for (int j : to[i]) if (not used[j]) dfs(j);
        vs.push_back(i);
    }
    int k; // number of scc
    void rdfs(int i) {
        used[i] = true;
        c[i] = k;
        for (int j : from[i]) if (not used[j]) rdfs(j);
    }
    void decompose() {
        used.clear(); used.resize(n, false);
        repeat (i,n) if (not used[i]) dfs(i);
        used.clear(); used.resize(n, false);
        k = 0;
        c.resize(n);
        reverse(vs.begin(), vs.end());
        for (int i : vs) if (not used[i]) {
            rdfs(i);
            k += 1;
        }
    }
};

bool twosat(int n, vector<pair<int, int> > const & cnf) {
    // make digraph
    vector<vector<int> > g(2*n);
    auto i = [&](int x) { assert (x != 0 and abs(x) <= n); return x > 0 ? x-1 : n-x-1; };
    for (auto it : cnf) {
        int x, y; tie(x, y) = it; // x or y
        g[i(- x)].push_back(i(y)); // not x implies y
        g[i(- y)].push_back(i(x)); // not y implies x
    }
    // do SCC
    strongly_connected_components::decompose(g);
    vector<int> const & component = c;
    repeat_from (x,1,n+1) {
        if (component[i(x)] == component[i(- x)]) { // x iff not x
            return false;
        }
    }
    return true;
}

int main() {
    int n; scanf("%d", &n);
    vector<int> x(n), y(n); repeat (i,n) scanf("%d%d", &x[i], &y[i]);
    auto is_x = [&](int i) { return   i+1; };
    auto is_y = [&](int i) { return -(i+1); };
    vector<int> ps;
    repeat (i,n) {
        ps.push_back(is_x(i));
        ps.push_back(is_y(i));
    }
    auto dist = [&](int p) { return p > 0 ? x[p-1] : y[-p-1]; };
    whole (sort, ps, [&](int p, int q) { return dist(p) < dist(q); });
    vector<pair<int, int> > cnf;
    auto pred = [&](int limit) {
        cnf.clear();
        int l = 0;
        repeat (r,2*n) {
            while (dist(ps[l]) + limit <= dist(ps[r])) ++ l;
            repeat_from (i,l,r) {
                if (i == - r) return false;
                cnf.emplace_back(- ps[r], - ps[i]);
                cnf.emplace_back(- ps[i], - ps[r]);
            }
        }
        return twosat(n, cnf);
    };
    int l = 0, r = 1e9+7;
    repeat (i,n) {
        repeat (j,n) if (i != j) {
            int acc = 0;
            setmax(acc, abs(x[i] - x[j]));
            setmax(acc, abs(x[i] - y[j]));
            setmax(acc, abs(y[i] - x[j]));
            setmax(acc, abs(y[i] - y[j]));
            setmin(r, acc+1);
        }
    }
    while (l + 1 < r) {
        int m = (l + r) / 2;
        (pred(m) ? l : r) = m;
    }
    printf("%d\n", l);
    return 0;
}

