int findl(int ave) { // >=
	int l = 1, r = d[0], ret = d[0];
	for ( ; l <= r; ) {
		int mid = (l + r) / 2;
		if (d[mid] >= ave) ret = mid, r = mid - 1;
			else l = mid + 1;
	} 
	return ret;
}
int findr(int ave) { // <=
	int l = 1, r = d[0], ret = 0;
	for ( ; l <= r; ) {
		int mid = (l + r) / 2;
		if (d[mid] <= ave) ret = mid, l = mid + 1;
			else r = mid - 1;
	}
	return ret;
}
void pre() {
