void addedge(int x,int st,int en,int l,int r,int p)
{
	if (st==l&&en==r)
	{
		insert(p,x+n*2);
		return;
	}
	int mid=l+r>>1;
	if (en<=mid) addedge(x<<1,st,en,l,mid,p);
	else if (mid+1<=st) addedge(x<<1|1,st,en,mid+1,r,p);
	else addedge(x<<1,st,mid,l,mid,p),addedge(x<<1|1,mid+1,en,mid+1,r,p);
}

void tarjan(int x)
{
	DFN[x]=low[x]=++idx,st.push(x),exist[x]=1;
	for (int i=last[x],y;i;i=nxt[i])
		if (!DFN[y=tov[i]]) tarjan(y),low[x]=min(low[x],low[y]);
		else if (exist[y]) low[x]=min(low[x],DFN[y]);
	if (DFN[x]==low[x])
	{
		int y;++bcnt;
		do
		{
			exist[y=st.top()]=0,st.pop(),bid[y]=bcnt;
		}while (x!=y);
