struct TwoSAT
{
    int n;
    vector<int> G[MaxN*2];
    int S[MaxN*2],c;
    bool mark[MaxN*2];

    bool dfs(int x)
    {
        if(mark[x^1]) return false;
        if(mark[x]) return true;
        mark[x]=true;
        S[c++]=x;
        for(int i=0;i<G[x].size();i++)
            if(!dfs(G[x][i])) return false;
        return true;
    }

    void init(int n)
    {
        this->n=n;
        for(int i=0;i<n*2;i++) G[i].clear();
        memset(mark,0,sizeof(mark));
    }

    void add_clause(int x,int xval,int y,int yval)//这里做了修改,指x与y值有冲突
    {
        x=x*2+xval;
        y=y*2+yval;
        G[x].push_back(y^1);
        G[y].push_back(x^1);
    }

    bool solve()
    {
        for(int i=0;i<2*n;i+=2)if(!mark[i] && !mark[i+1])
        {
            c=0;
            if(!dfs(i))
            {
                while(c>0) mark[S[--c]]=false;
                if(!dfs(i+1)) return false;
            }
        }
        return true;
    }
}TS;
int N;
pair<int, int> loc[MaxN];
bool judge(int x)
{
    TS.init(N);
    for(int i=0;i<N;i++)
    {
        for(int j=i+1;j<N;j++)
        {
            if( abs(loc[i].first-loc[j].first) <x ) TS.add_clause(i,0,j,0);
            if( abs(loc[i].first-loc[j].second) <x ) TS.add_clause(i,0,j,1);
            if( abs(loc[i].second-loc[j].first) <x ) TS.add_clause(i,1,j,0);
            if( abs(loc[i].second-loc[j].second) <x ) TS.add_clause(i,1,j,1);
        }
    }
    if(TS.solve()) return true;
    else return false;
}

