	for(int i=1;i<=las;i++) vis[i]=dfn[i]=low[i]=0；
	for(int i=1;i<=las;i++) if(!dfn[i]) dfs(i);
	for(int i=1;i<=n+n;i++) if(bl[i]==bl[op[i]]) return 0;
	return 1;
}
