namespace Graph {
#define mid ((L + R) >> 1)
#define ID(L, R) ((L + R) | (L != R))
#define no ID(L, R)
#define lc ID(L, mid)
#define rc ID(mid + 1, R)
	struct edge {
		int nxt, to;
	} e[8000000];
	int fir[N << 2], cnt;
	int dfn[N << 2], low[N << 2], bel[N << 2], clo, cnt_bcc;
	int sta[N << 2], top;

	inline void addedge(int x, int y) {
		e[++ cnt] = (edge){fir[x], y};
		fir[x] = cnt;
	}

	inline void Addedge(int l, int r, int x, int L = 0, int R = m) {
		if (L == l && R == r) return (void)(addedge(x, no));
		if (r <= mid) Addedge(l, r, x, L, mid);
		else if (l > mid) Addedge(l, r, x, mid + 1, R);
		else {
			Addedge(l, mid, x, L, mid);
			Addedge(mid + 1, r, x, mid + 1, R);
		}
	}

	inline void tarjan(int x) {
		dfn[x] = low[x] = ++ clo;
		sta[++ top] = x;
		for (int i = fir[x]; i; i = e[i].nxt) {
			if (!dfn[e[i].to]) {
				tarjan(e[i].to);
				low[x] = min(low[x], low[e[i].to]);
			}
			else if (!bel[e[i].to]) low[x] = min(low[x], dfn[e[i].to]);
		}
		if (dfn[x] == low[x]) {
			int cur = -1;
			cnt_bcc ++;
			while (cur != x) {
				cur = sta[top --];
				bel[cur] = cnt_bcc;
			}
		}
	}

	inline void Build(int L = 0, int R = m) {
		if (L == R) return;
		Build(L, mid);
		Build(mid + 1, R);
		addedge(no, lc);
		addedge(no, rc);
	}

	inline bool check(int ans) {
		clr(fir); clr(dfn); clr(low); clr(bel); cnt = 0; cnt_bcc = 0; clo = 0;
		Build();
		int l, r;
		for (int i = 0; i <= m; i ++) {
			l = lower_bound(tab, tab + m + 1, x[i] - ans) - tab;
			r = upper_bound(tab, tab + m + 1, x[i] + ans) - tab - 1;
			if (l <= pos[i] && pos[i] <= r) {
				if (l < pos[i]) Addedge(l, pos[i] - 1, ID(pos[i ^ 1], pos[i ^ 1]));
				if (pos[i] < r) Addedge(pos[i] + 1, r, ID(pos[i ^ 1], pos[i ^ 1]));
			}
			else Addedge(l, r, ID(pos[i ^ 1], pos[i ^ 1]));
		}
		for (int i = 0; i <= ID(m, m); i ++)
			if (!dfn[i]) {
				top = 0;
				tarjan(i);
			}
		for (int i = 0; i <= m; i ++)
			if (bel[ID(pos[i], pos[i])] == bel[ID(pos[i ^ 1], pos[i ^ 1])]) return false;
		return true;
	}
