		add_edge(a, b + B);
		add_edge(b, a + B);
		add_edge(a + B, b);
		add_edge(b + B, a);
	}

	for (int i = 1; i < sz * 2 - 1; ++i) {
		add_edge(i, (i-1) / 2);
		add_edge((i-1) / 2 + B, i + B);
	}

	rep(i, vec.size()) {
