void inse(int x,int y){e[++et].x=y;e[et].nxt=h[x];h[x]=et;}

void add(int now,int l,int r,int x,int y,int st){
	if (x<=l&&r<=y){inse(st,tree[now].id);return;}
	int mid=(l+r)/2;
	if (x<=mid)add(tree[now].l,l,mid,x,y,st);
	if (y>mid)add(tree[now].r,mid+1,r,x,y,st);
}

void tarjan(int x){
	f[x]=dfn[x]=++u;
	pd[sta[++top]=x]=1;
	for(int p=h[x];p;p=e[p].nxt)
	if (!dfn[e[p].x]){
		tarjan(e[p].x);
		f[x]=min(f[x],f[e[p].x]);
	}
	else
		if (pd[e[p].x])f[x]=min(f[x],dfn[e[p].x]);
	if (dfn[x]==f[x]){
		t++;
		for(;sta[top+1]!=x;top--){
			pd[sta[top]]=0;
			be[sta[top]]=t;
		}
	}
}

bool check(int val){
	int qet=et;
	fo(i,1,n*2)h[i]=0;
	int l=1,r=1;
	fo(i,1,m){
		while(key[i].x-key[l].x>=val)l++;
		while(r<m&&key[r+1].x-key[i].x<val)r++;
		if (l<i)add(1,1,m,l,i-1,key[i].id);
		if (r>i)add(1,1,m,i+1,r,key[i].id);
	}
	u=t=0;
	fo(i,1,k)dfn[i]=be[i]=0;
	fo(i,1,k)
	if (!dfn[i])tarjan(i);
	et=qet;
	fo(i,1,n)
	if (be[id[i][0]]==be[id[i][1]])return 0;
	return 1;
}

void build(int &now,int l,int r){
	now=++tot;
	tree[now].id=++k;
	fo(i,l,r)inse(tree[now].id,key[i].tid);
	if (l==r)return;
	int mid=(l+r)/2;
	build(tree[now].l,l,mid);
	build(tree[now].r,mid+1,r);
}

