template<class T> bool chmin(T &a, T b) { return a > b ? (a = b, true) : false; }

typedef long long ll;

const int MAX_N = 10000 + 10;
int X[MAX_N];
int Y[MAX_N];

vector<int> g[MAX_N * 2];

void add_cond(int a, int b) {
    g[a].push_back(b^1);
    g[b].push_back(a^1); 
}


vector<int> S;
bool inS[MAX_N * 2];
int mark[MAX_N * 2];
int lowlink[MAX_N * 2];
int sccid[MAX_N * 2];
int sccnum;
void tarjan(int v, int &index) {
  mark[v] = lowlink[v] = index;
  index++;
  S.push_back(v); inS[v] = true;
  for(int i = 0; i < (int)g[v].size(); i++) {
    int w = g[v][i];
    if( mark[w] == -1 ) {
      tarjan(w, index);
      lowlink[v] = min(lowlink[v], lowlink[w]);
    } else if( inS[w] ) {
      lowlink[v] = min(lowlink[v], mark[w]);
    }
  }
  if( lowlink[v] == mark[v] ) {
    while( 1 ) {
      int w = S.back(); S.pop_back(); inS[w] = false;
      sccid[w] = sccnum;
      if( w == v ) break;
    }
    ++sccnum;
  }
}

void scc(int N) {
  S.clear();
  memset(sccid, -1, sizeof(sccid));
  memset(inS, 0, sizeof(inS));
  memset(mark, -1, sizeof(mark));
  sccnum = 0;
  int index = 0;
  for(int i = 0; i < 2*N; i++)
    if( mark[i] == -1 )
      tarjan(i, index);
}

bool possible(int N, int th) {
  REP(i, 2 * N) g[i].clear();
  REP(j, N) {
    REP(i, j) {
      // i -> j
      if ( abs(X[i] - X[j]) < th ) { add_cond(i * 2    , j * 2    ); }
      if ( abs(X[i] - Y[j]) < th ) { add_cond(i * 2    , j * 2 + 1); }
      if ( abs(Y[i] - X[j]) < th ) { add_cond(i * 2 + 1, j * 2    ); }
      if ( abs(Y[i] - Y[j]) < th ) { add_cond(i * 2 + 1, j * 2 + 1); }
    }
  }
  scc(2*N);
  for(int i = 0; i < 2 * N; i+=2) if( sccid[i] == sccid[i+1] ) return 0;
  return 1;
}

