            scc_cnt++;
            while (1) {
                int x = s.top();
                s.pop();
                sccno[x] = scc_cnt;
                if (x == u) break;
            }
        }
    }

    void add_edge(int x, int xval, int y, int yval) {
        g[x << 1 | xval].pb(y << 1 | yval);
    }

