    void find_scc() {
        dfs_clock = scc_cnt = 0;
        mem(sccno);
        mem(pre);
        for (int i = 1; i <= n2; i++) if (!pre[i]) dfs(i);
    }

    bool solvable() {//是否有解
        find_scc();
