        for(auto &i:temp){
            g[i].pop_back();
        }
        temp.clear();
    }

    int ql,qr,qs;
    void paint(int k,int l,int r){
        if (ql>r||qr<l) return;
        if (ql<=l&&r<=qr) {
            if (l==r) add_edge(qs,v[k-n1+1].second);
            else add_edge(qs,n1+k);
            temp.pb(qs);
        }
        else{
            int mid=r+l>>1;
            paint(k<<1,l,mid);
            paint(k<<1|1,mid+1,r);
        }
    }
}

