    stk[top ++] = u;
    low[u] = dfn[u] = ++ dfs_clock;

    for(int i = 0; i < int(G[u].size()); ++i) {
        int v = G[u][i];
        if(!dfn[v]) {
            dfs(v);
            chkmin(low[u], low[v]);
        }else if(!bel[v]) {
            chkmin(low[u], dfn[v]);
        }
    }

    if(low[u] == dfn[u]) {
        ++ scc_cnt;
        do {
            bel[stk[top - 1]] = scc_cnt;
        } while(stk[-- top] != u);
    }
}

bool scc_chk() {
    memset(bel, 0, sizeof bel);
    memset(dfn, 0, sizeof dfn);
    top = scc_cnt = dfs_clock = 0;

    for(int i = 0; i <= (N << 1); ++i) if(!dfn[i]) { dfs(i); }
    for(int i = 1; i <= n; ++i) if(bel[N - i] == bel[N + i]) return false;
    return true;
}

bool chk(int len) {
    for(int i = 0; i <= (N << 1); ++i) G[i].clear();
    for(int i = 0; i < cnt; ++i) {
        int K = 0;
        for(int j = i-1; j >= 0 && t[i].fst - t[j].fst < len; --j) {
            addedge(N + t[i].snd, N - t[j].snd);
            addedge(N + t[j].snd, N - t[i].snd);
            if(++ K >= 100) break;
        }
        K = 0;
        for(int j = i+1; j < cnt && t[j].fst -t[i].fst < len; ++j) {
            addedge(N + t[i].snd, N - t[j].snd);
            addedge(N + t[j].snd, N - t[i].snd);
            if(++ K >= 100) break;
        }
    }
    return scc_chk();
}

