                            con++;
                        }
                    }
                }
                if(con == 4) {
                    return false;
                }
            }
        }
        return ts.satisfiable();
    };

    ll l = 0;
    while(l + 1 < r) {
        ll m = l + r >> 1;
        if(check(m))
            l = m;
        else
