int flag = 1;

void dfs(int x) {
//	cout << "  dfs:" << x << endl;
	low[x] = id[x] = ++TOT;
	s.push_back(x), ins[x] = 1;
	vector <int> &g = from[x];
	for (int i = 0; i < g.size(); i++) {
		int v = g[i];
//		cout << "    edge:" << x << "->" << v << endl;
		if (!id[v]) dfs(v), low[x] = min(low[x], low[v]);
		else if (ins[v]) low[x] = min(low[x], id[v]);
	}
	if (id[x] != low[x]) return ;
	while (1) {
		int v = s.back(); s.pop_back(); ins[v] = 0;
		if (v >= N && v - N < all.size() && vis[all[v - N].se] == x) flag = 0;
		if (v >= N && v - N < all.size()) vis[all[v - N].se] = x;
		if (v == x) break;
	}
//	cout << "end:" << endl;
}

bool check(int mid) {
//	cout << "   check:" << mid << endl;
	for (int i = 0; i < N + N; i++) {
		from[i].clear();
	}
	seg.Build(1, 1, N);
	for (int i = 0; i < all.size(); i++) {
		int l = lower_bound(all.begin(), all.end(), mp(all[i].fi - mid, 0x3f3f3f3f)) - all.begin();
		int r = lower_bound(all.begin(), all.end(), mp(all[i].fi + mid, -1)) - all.begin();
//		cout << "     range:" << i << " " << l << " " << r - 1 << endl;
		if (l <= i - 1) seg.add_edge(1, 1, N, l + 1, i, N + sum[all[i].se] - i);
		if (i + 1 <= r - 1) seg.add_edge(1, 1, N, i + 2, r, N + sum[all[i].se] - i);
	}
	flag = 1, TOT = 0;
	memset(vis, 0, sizeof(vis)), memset(id, 0, sizeof(id));
	for (int i = N; i < N + all.size(); i++) {
		if (!id[i]) dfs(i);
	}
//	cout << "TOT:" << TOT << endl;
	return flag;
}

int main () {
	int n; scanf("%d", &n);
	for (int i = 0; i < n; i++) {
		int x, y; scanf("%d%d", &x, &y);
		all.push_back(mp(x, i)), all.push_back(mp(y, i));
	}
	sort(all.begin(), all.end());
	for (int i = 0; i < all.size(); i++) {
		sum[all[i].se] += i;
	}
	int l = 0, r = 1000000000;
	while (l < r) {
		int mid = l + r + 1 >> 1;
		if (check(mid)) l = mid;
		else r = mid - 1;
	}
	printf("%d\n", l);
	return 0;
}

