    // ts[i] = (i-th flag is located on x[i])
  int ok = 0, ng = 1e9+1;
  while(ng - ok > 1) {
    int d = (ng+ok)/2;
    two_sat t(n);

    for(int i=0; i<n-1; i++) {
        for(int j=i+1; j<n; j++) {
            if (abs(x[i] - x[j]) < d) {
                t.add_clause(i, false, j, false);
            }
            if (abs(x[i] - y[j]) < d) {
                t.add_clause(i, false, j, true);
            }
            if (abs(y[i] - x[j]) < d) {
                t.add_clause(i, true, j, false);
            }
            if (abs(y[i] - y[j]) < d) {
                t.add_clause(i, true, j, true);
            }
        }
    }

    if (!t.satisfiable()) {
      ng=d;
    } else {
      ok=d;
    }
  }
  cout<<ok<<endl;
}

#include <bits/stdc++.h>
