void tarjan(int x)
{
	dfn[x] = low[x] = ++ti, ins[x] = 1, s[++top] = x;
	for(int y:e[x]) if(!dfn[y]) tarjan(y), low[x] = min(low[x], low[y]); else if(ins[y]) low[x] = min(low[x], dfn[y]);
	if(low[x] == dfn[x]) 
	{
