bool chk(int d)
{
	memset(dfn+1, 0, sizeof(int)*t), ti = cnt = 0;
	for(int i = 1; i <= n<<1; ++i) e[i].clear();
	for(int i = 1, j = i; i <= n<<1; ++i)
