inline void build(int &v,int l,int r){
	v=++tot;
	if(l==r){
		ins(v,rev(c[l]));
		return;
	}int mid=l+r>>1;
	build(ch[v][0],l,mid);build(ch[v][1],mid+1,r);
	if(ch[v][0]) ins(v,ch[v][0]);
	if(ch[v][1]) ins(v,ch[v][1]);
}
inline void ins(int v,int l,int r,int x,int y,int z){
	if(x>y) return;
	if(x<=l && r<=y){ins(z,v);return;}
	int mid=l+r>>1;
	if(x<=mid) ins(ch[v][0],l,mid,x,y,z);
	if(mid<y) ins(ch[v][1],mid+1,r,x,y,z); 
}
