#include <bits/stdc++.h>
using namespace std;

const int inf = (int)1e9+7;

struct Task {
	int n;
	vector<int> a;
	vector<int> ord;
	vector<int> was;
	vector<int> comp;
	set<pair<int,int>> avail;

	Task(int n): n(2*n), a(2*n) {
		for (auto& item : a) {
			cin >> item;
		}
	}

	void dfs(int v, int d) {
		avail.erase({a[v^1], v^1});
		was[v] = 1;

		while (!avail.empty()) {
			auto up = avail.lower_bound({a[v]+d, 0});
			if (up == avail.begin()) break;
			--up;
			if (abs(up->first - a[v]) >= d) break;
			int to = up->second^1;
			if (to == (v^1)) break;
			if (!was[to]) dfs(to, d);
		}

		while (!avail.empty()) {
			auto down = avail.lower_bound({a[v]-d, inf});
			if (down == avail.end()) break;
			if (abs(down->first - a[v]) >= d) break;
			int to = down->second^1;
			if (to == (v^1)) break;
			if (!was[to]) dfs(to, d);
		}

		ord.push_back(v);
	}

	void dfsr(int v, int d, int color) {
		avail.erase({a[v], v});
		was[v] = 1;
		comp[v] = color;

		while (!avail.empty()) {
			auto up = avail.lower_bound({a[v^1]+d, 0});
			if (up == avail.begin()) break;
			--up;
			if (abs(up->first - a[v^1]) >= d) break;
			int to = up->second;
			if (to == (v^1)) break;
			if (!was[to]) dfsr(to, d, color);
		}

		while (!avail.empty()) {
			auto down = avail.lower_bound({a[v^1]-d, inf});
			if (down == avail.end()) break;
			if (abs(down->first - a[v^1]) >= d) break;
			int to = down->second;
			if (to == (v^1)) break;
			if (!was[to]) dfsr(to, d, color);
		}
	}

	bool check(int d) {
		avail.clear();
		ord.clear();
		comp.assign(n, 0);

		was.assign(n, 0);
		for (int i = 0; i < n; ++i) {
			avail.insert({a[i], i});
		}
		for (int i = 0; i < n; ++i) {
			if (!was[i]) {
				dfs(i, d);
			}
		}
		reverse(ord.begin(), ord.end());

		was.assign(n, 0);
		for (int i = 0; i < n; ++i) {
			avail.insert({a[i], i});
		}
		int compNum = 0;
		for (auto& ver : ord) {
			if (!was[ver]) {
				++compNum;
				dfsr(ver, d, compNum);
			}
		}
		for (int i = 0; i < n; ++i) {
			if (comp[i] == comp[i^1]) {
				return false;
			}
		}
		return true;
	}

	void run() {
		int l = -1, r = inf;
		while (r - l > 1) {
			int m = (l + r) / 2;
			if (check(m)) l = m; else r = m;
		}
		cout << l << '\n';
	}
};

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	int n;
	cin >> n;

	Task a(n);
	a.run();

	return 0;
}

