class range_tsort {
public:
    int n, sz, V;
	vector<vector<int> > G;
	vector<int> deg;
    void add_edge(const int from, const int to){
        G[from].push_back(to), ++deg[to];
    }
    vector<int> ord, low;
    stack<int> st;
    void dfs(const int u, int& tm){
        ord[u] = low[u] = tm++, st.push(u);
        for(int v : G[u]){
            if(ord[v] < 0){
                dfs(v, tm);
                low[u] = min(low[u], low[v]);
            }else if(cmp[v] < 0){
                low[u] = min(low[u], ord[v]);
            }
        }
        if(ord[u] == low[u]){
            while(true){
                const int v = st.top();
                st.pop();
                cmp[v] = cnt;
                if(v == u) break;
            }
            ++cnt;
        }
    }
    vector<int> cmp;
    int cnt;
	range_tsort(const int node_size) : n(node_size), sz(1){
        while(sz < n) sz *= 2;
		V = 3 * sz - 1;
		G.resize(V), deg.resize(V, 0);

        for(int i = 1; i < sz; ++i){
			add_edge(i, 2 * i), add_edge(i, 2 * i + 1);
			if(2 * i >= sz) add_edge(2 * i, V - i), add_edge(2 * i + 1, V - i);
			else add_edge(V - 2 * i, V - i), add_edge(V - 2 * i - 1, V - i);
		}
    }
    // [p, q) → [r, s)
    void add_edge(int p, int q, int r, int s){
		if(p >= q || r >= s) return;
        p += sz, q += sz, r += sz, s += sz;
		G.push_back({}), deg.push_back(0);
		while(p != q){
			if(p & 1) add_edge((p >= sz) ? (p++) : (V - p++), (int)G.size()  - 1);
			if(q & 1) add_edge((--q >= sz) ? (q) : (V - q), (int)G.size()  - 1);
			p >>= 1, q >>= 1;
		}
		while(r != s){
			if(r & 1) add_edge((int)G.size()  - 1, r++);
			if(s & 1) add_edge((int)G.size()  - 1, --s);
			r >>= 1, s >>= 1;
		}
    }
	int solve(){ // 強連結成分の数を返す
        V = G.size();
        ord.resize(V,-1);
        low.resize(V,0), cmp.resize(V, -1), cnt=0;

        int tm = 0;
        for(int i = 0; i < V; ++i){
            if(ord[i] < 0) dfs(i, tm);
        }
        for(int i = 0; i < V; ++i) cmp[i] = cnt - 1 - cmp[i];
        // rep(i,V){
        //     cerr << i << " " << cmp[i] << endl;
        // }

        return cnt;
    }
};

