struct aib {
    int n;
    vector<int> data;

    void init(int _n) {
        n = _n;
        data = vector<int>(n + 11, 0);
    }

    int zrs(int x) {
        return (x ^ (x - 1)) & x;
    }

    void add(int pos, int v) {
        while (pos <= n) {
            data[pos] += v;
            pos += zrs(pos);
        }
    }

    int sum(int pos) {
        int ans = 0;
        while (pos > 0) {
            ans += data[pos];
            pos -= zrs(pos);
        }
        return ans;
    }

    int cb(int x) {
        int ans = 0;

        for (int step = 1 << 15; step > 0; step >>= 1)
            if (ans + step <= n)
                if (data[ans + step] <= x)
                    ans += step, x -= data[ans];

        return ans;
    }
};

