#include <bits/stdc++.h>
using namespace std;

#define int long long

const int inf = 1e18;

struct T {
	int val, sum, mn;
	int fix, siz;
	T *lson, *rson;
	T(int v) {
		val = sum = mn = v;
		fix = rand(); siz = 1;
		lson = rson = NULL;
	}
};

void del_T(T *&x) {
	if (x -> lson) del_T(x -> lson);
	if (x -> rson) del_T(x -> rson);
	delete x; x = NULL;
}

void pushup(T *x) {
	x -> sum = x -> val;
	if (x -> lson) x -> sum += x -> lson -> sum;
	if (x -> rson) x -> sum += x -> rson -> sum;
	x -> mn = x -> val;
	if (x -> lson) x -> mn = min(x -> mn, x -> lson -> mn);
	if (x -> rson) x -> mn = min(x -> mn, x -> rson -> mn);
	x -> siz = 1;
	if (x -> lson) x -> siz += x -> lson -> siz;
	if (x -> rson) x -> siz += x -> rson -> siz;
}

void split(T *x, int k, T *&a, T *&b) {
	if (!x) {a = b = NULL; return ;}
	int lsiz = x -> lson ? x -> lson -> siz : 0;
	if (lsiz + 1 <= k) {
		a = x;
		split(x -> rson, k - lsiz - 1, a -> rson, b);
		pushup(a);
	} else {
		b = x;
		split(x -> lson, k, a, b -> lson);
		pushup(b);
	}
}

T *merge(T *a, T *b) {
	if (!a || !b) return a ? a : b;
	if (a -> fix < b -> fix) {
		a -> rson = merge(a -> rson, b);
		pushup(a);
		return a;
	} else {
		b -> lson = merge(a, b -> lson);
		pushup(b);
		return b;
	}
}

int find(T *x, int v) {
	int lsum = x -> lson ? x -> lson -> sum : 0;
	int lsiz = x -> lson ? x -> lson -> siz : 0;
	if (lsum >= v) return find(x -> lson, v);
	if (lsum + x -> val >= v) return 1 + lsiz;
	return 1 + lsiz + find(x -> rson, v - lsum - x -> val);
}

T *root;

void prt(T *x) {
	if (!x) return ;
	prt(x -> lson);
	cerr << x -> val << " ";
	prt(x -> rson);
}

void wait() {for (int i = 0; i < 1e8; ++ i) i <<= 1, i >>= 1;}
#define dbg(x) {cerr << #x << ": "; prt(x); cerr << endl; wait();}

const int N = 1e4 + 5;
int n, x[N][2], use[N];
int cur;

void del(int k) {
	// cerr << "del " << k << endl;
	T *a, *b, *c;
	int rnk = find(root, x[k][use[k]] + inf);
	split(root, rnk + 1, b, c);
	split(b, rnk - 1, a, b);
	// dbg(a); dbg(b); dbg(c);
	T *nw = new T(b -> sum);
	del_T(b); b = nw;
	root = merge(merge(a, b), c);
	// dbg(root);
}

void add(int k) {
	// cerr << "add " << k << endl;
	T *a, *b, *c;
	int rnk = find(root, x[k][use[k]] + inf);
	split(root, rnk, b, c);
	split(b, rnk - 1, a, b);
	// dbg(a); dbg(b); dbg(c);
	T *d = new T(x[k][use[k]] + inf - (a ? a -> sum : 0));
	T *e = new T((a ? a -> sum : 0) + b -> sum - x[k][use[k]] - inf);
	T *nw = merge(d, e);
	del_T(b); b = nw;
	root = merge(merge(a, b), c);
	// dbg(root);
}

void ch(int k) {
	del(k);
	use[k] ^= 1;
	add(k);
	cur = root -> mn;
}

signed main() {
	// freopen("in", "r", stdin);
	ios :: sync_with_stdio(0);
	cin.tie(0); cout.tie(0);
	cin >> n;
	for (int i = 0; i < n; ++ i)
		cin >> x[i][0] >> x[i][1];
	for (int i = 0; i < n; ++ i)
