	st.insert(-inf); st.insert(inf);
	for (int i = 0; i < n; ++ i)
		st.insert(x[i][use[i]]);
	for (set <int> :: iterator it = st.begin(), oit; it != st.end(); ++ it) {
		if (it != st.begin()) root = merge(root, new T(*it - *oit));
		oit = it;
	}
	// dbg(root);
	cur = root -> mn;
	int mx = 0;
	double T = 1e5;
	while (T >= 1e-35) {
		// cerr << T << endl;
		int k = rand() % n;
		int old = cur;
		ch(k);
		int delta = cur - old;
		if (delta <= 0 && exp(delta / T) * RAND_MAX <= rand()) ch(k);
		T *= 1.0 - 1e-4; mx = max(mx, cur);
		// dbg(root);
	}
	// dbg(root);
