    void link(int u,int v) {e[ne]= {v,hd[u]},hd[u]=ne++;}
    void link(int u,int v,int f1,int f2) {
        link(u<<1|f1,v<<1|f2);
        link(v<<1|(!f2),u<<1|(!f1));
    }
    void init(int _n) {
        n=_n,ne=tp=0;
        for(int i=0; i<=n; ++i)mk[i]=0,hd[i]=-1;
    }
    bool dfs(int u) {
        if(mk[u^1])return 0;
        if(mk[u])return 1;
        mk[u]=1,sta[tp++]=u;
        for(int i=hd[u]; ~i; i=e[i].nxt)if(!dfs(e[i].v))return 0;
        return 1;
    }
    bool check() {
        for(int i=1; i<=n; ++i)mk[i]=0;
        for(int i=1; i<=n; ++i)if(!mk[i<<1]&&!mk[i<<1|1]) {
                tp=0;
                if(!dfs(i<<1)) {
                    for(; tp; mk[sta[--tp]]=0);
                    if(!dfs(i<<1|1))return 0;
                }
            }
        return 1;
    }
