		if (T[x].l>r||l>T[x].r)return;
		if (T[x].l>=l&&T[x].r<=r){
			jb(z,T[x].id);
			return;
		}
		insert(x*2,l,r,z);
		insert(x*2+1,l,r,z);
	}
