const int MAX_N = 100005;

class TwoSAT {
private:
	const int V;
	vector<vector<int> > G, rG;
	vector<int> ps, cmp;
	void add_edge(int from, int to){
		G[from].push_back(to), rG[to].push_back(from);
	}
	void dfs(int u){
        cmp[u] = 0;
        for(int v : G[u]){
			if(cmp[v] == -1) dfs(v);
		}
		ps.push_back(u);
	}
	void rdfs(int u, int k){
		cmp[u] = k;
		for(int v : rG[u]){
			if(cmp[v] == -1) rdfs(v, k);
		}
	}
	int scc(){
		for(int i = 0; i < 2 * V; ++i){
			if(cmp[i] == -1) dfs(i);
		}
		fill(cmp.begin(), cmp.end(), -1);
		int k = 0;
		for(int i = 2 * V - 1; i >= 0; --i){
			if(cmp[ps[i]] == -1) rdfs(ps[i], k++);
		}
		return k;
	}

public:
	vector<int> ans;
	TwoSAT(const int literal_count)
	 	: V(literal_count), G(2 * V), rG(2 * V), cmp(2 * V, -1), ans(V){}
	void add_closure(int x, int y){
		add_edge((x + V) % (2 * V), y), add_edge((y + V) % (2 * V), x);
	}
	// 充足可能性判定
	// 真のものは 1,偽のものは 0 が ans に格納される(解の構成)
	bool satisfy(){
		scc();
		for(int i = 0; i < V; i++){
			if(cmp[i] == cmp[V + i]) return false;
			ans[i] = (cmp[i] > cmp[V + i]);
		}
		return true;
	}
};

int n, N, V;
vector<P> vec, num;

inline void query(const int id, int a, int b, TwoSAT& st, int k = 0, int l = 0, int r = -1){
    if(r < 0) r = N;
    if(r <= a || b <= l){
        return;
    }
    if(a <= l && r <= b){
        st.add_closure(id+V, k+V);
        return;
    }else{
        query(id,a,b,st,2*k+1,l,(l+r)/2), query(id,a,b,st,2*k+2,(l+r)/2,r);
    }
}

bool possible(int d)
{
    TwoSAT st(V);
    rep(i,n){
		st.add_closure(num[i].fi+N-1, num[i].se+N-1);
    }
    for(int i=N-2; i>=0; i--){
		st.add_closure(2*i+1+V, i), st.add_closure(2*i+2+V, i);
    }
    rep(i,2*n){
        int s = lower_bound(all(vec),P(vec[i].fi-d+1,-1)) - vec.begin();
        if(s < i) query(i+N-1, s, i, st);
        int e = upper_bound(all(vec),P(vec[i].fi+d-1,INF)) - vec.begin();
        if(i+1 < e) query(i+N-1, i+1, e, st);
    }
    return st.satisfy();
}

