{
  scanf("%d", &N);
  for(int i = 0; i < N; i++) {
    scanf("%d %d", &X[i], &Y[i]);
  }

  int ret = INF;
  for(int i = 0; i < N; i++) {
    for(int j = i + 1; j < N; j++) {
      int st = max({X[i] - X[j], X[i] - Y[j], Y[i] - X[j], Y[i] - Y[j]});
      st = max({st, X[j] - X[i], X[j] - Y[i], Y[j] - X[i], Y[j] - Y[i]});
      ret = min(ret, st);
    }
  }

  int low = 0, high = ret;
  while(high - low > 0) {
    int mid = (low + high + 1) >> 1;
    if(check(mid)) low = mid;
    else high = mid - 1;
  }

  cout << low << endl;
}

