void addedge(int s,int t){e[++tot]=(edge){s,t,h[s]},h[s]=tot;}

void build(int n,int l,int r)
{
	t[n]=++m;
	if (l==r)  {id[l]=t[n];  return;}
	int mid=(l+r)>>1;
	build(ls,l,mid),build(rs,mid+1,r);
}

void link(int n,int l,int r)
{
	if (l==r)  return;
	int mid=(l+r)>>1;
	addedge(t[n],t[ls]),addedge(t[n],t[rs]);
	link(ls,l,mid),link(rs,mid+1,r);
}

void link(int n,int l,int r,int L,int R,int x)
{
	if ((L<=l)&&(r<=R))  addedge(x,t[n]);
	else
		{
			int mid=(l+r)>>1;
			if (L<=mid)  link(ls,l,mid,L,R,x);
			if (mid<R)  link(rs,mid+1,r,L,R,x);
		}
}

void tarjan(int x)
{
	D[x]=L[x]=++tot,S[++top]=x,inS[x]=1;
	for (int i=h[x],y; y=e[i].t,i; i=e[i].n)
		if (!D[y])  tarjan(y),L[x]=min(L[x],L[y]);
		else  if (inS[y])  L[x]=min(L[x],D[y]);
	if (D[x]==L[x])
		{
			c[x]=++c[0],inS[x]=0;
			for (int y=S[top--]; y!=x; c[y]=c[0],inS[y]=0,y=S[top--]);
		}
}

