		{
			addedge(id[p=lower_bound(a+1,a+2*n+1,x[i])-a],i+n);
			addedge(id[q=lower_bound(a+1,a+2*n+1,y[i])-a],i);
			l=lower_bound(a+1,a+2*n+1,x[i]-d)-a,r=upper_bound(a+1,a+2*n+1,x[i]+d)-a-1;
			if (l<p)  link(1,1,2*n,l,p-1,i);
