int seg[4*N] , f[N];
void build(int v , int tl , int tr , int &cnt){
    if(tl == tr){
        seg[v] = f[tl];
        return;
    }
    seg[v] = cnt++;
    int mid = (tl + tr) >> 1 , v1 = v << 1;
    build(v1 , tl , mid , cnt);
    build(v1 | 1 , mid + 1 , tr , cnt);
    impli(seg[v] , seg[v1]);
    impli(seg[v] , seg[v1|1]);
}
void LineImpli(int v , int tl , int tr,  int l , int r , int V){
    if(tl == l && tr == r){
        impli(V , seg[v]);
        return;
    }
    int mid = (tl + tr) >> 1 , v1=  v << 1;
    if(l <= mid)
        LineImpli(v1 , tl , mid , l , min(r , mid) , V);
    if(r > mid)
        LineImpli(v1|1 , mid + 1 , tr , max(l , mid + 1) , r , V);
}

