#define whole(f,x,...) ([&](decltype((x)) whole) { return (f)(begin(whole), end(whole), ## __VA_ARGS__); })(x)
using namespace std;
template <class T> inline void setmin(T & a, T const & b) { a = min(a, b); }
template <class T> inline void setmax(T & a, T const & b) { a = max(a, b); }

struct strongly_connected_components {
    static pair<int,vector<int> > decompose(vector<vector<int> > const & g) { // adjacent list
        strongly_connected_components scc(g);
        return { scc.k, scc.c };
    }
private:
    int n;
    vector<vector<int> > to, from;
    explicit strongly_connected_components(vector<vector<int> > const & g) : n(g.size()), to(g), from(n) {
        repeat (i,n) for (int j : to[i]) from[j].push_back(i);
        decompose();
    }
    vector<bool> used;
    vector<int> vs;
    void dfs(int i) {
        used[i] = true;
        for (int j : to[i]) if (not used[j]) dfs(j);
        vs.push_back(i);
    }
    int k; // number of scc
    vector<int> c; // i-th vertex in g is in c_i-th vertex in scc-decomposed g
    void rdfs(int i) {
        used[i] = true;
        c[i] = k;
        for (int j : from[i]) if (not used[j]) rdfs(j);
    }
    void decompose() {
        used.clear(); used.resize(n, false);
        repeat (i,n) if (not used[i]) dfs(i);
        used.clear(); used.resize(n, false);
        k = 0;
        c.resize(n);
        reverse(vs.begin(), vs.end());
        for (int i : vs) if (not used[i]) {
            rdfs(i);
            k += 1;
        }
    }
};

vector<bool> twosat(int n, vector<pair<int, int> > const & cnf) {
    // make digraph
    vector<vector<int> > g(2*n);
    auto i = [&](int x) { assert (x != 0 and abs(x) <= n); return x > 0 ? x-1 : n-x-1; };
    for (auto it : cnf) {
        int x, y; tie(x, y) = it; // x or y
        g[i(- x)].push_back(i(y)); // not x implies y
        g[i(- y)].push_back(i(x)); // not y implies x
    }
    // do SCC
    vector<int> component = strongly_connected_components::decompose(g).second;
    vector<bool> valuation(n);
    repeat_from (x,1,n+1) {
        if (component[i(x)] == component[i(- x)]) { // x iff not x
            return vector<bool>(); // unsat
        }
        valuation[x-1] = component[i(x)] > component[i(- x)]; // use components which indices are large
    }
    return valuation;
}

int main() {
    int n; scanf("%d", &n);
    vector<int> x(n), y(n); repeat (i,n) scanf("%d%d", &x[i], &y[i]);
    int segtree_n = 2*pow(2, ceil(log2(n)));
    auto is_x = [&](int i) { return    2*segtree_n+i; };
    auto is_y = [&](int i) { return - (2*segtree_n+i); };
    auto dist = [&](int p) { return p > 0 ? x[p-2*segtree_n] : y[-p-2*segtree_n]; };
    vector<int> ps(2*n);
    repeat (i,n) {
        ps[2*i  ] = is_x(i);
        ps[2*i+1] = is_y(i);
    }
    whole (sort, ps, [&](int p, int q) { return dist(p) < dist(q); });
    auto pred = [&](int limit) {
        vector<pair<int, int> > cnf;
        auto implies = [&](int i, int j) { cnf.emplace_back(- i, j); };
        repeat_from (i,1,segtree_n) {
            int l = 2*i;
            int r = 2*i+1;
            implies(l, i);
            implies(r, i);
        }
        repeat (i,2*n) {
            implies(segtree_n+i, ps[i]);
            implies(ps[i], segtree_n+i);
        }
        int l = 0;
        vector<bool> disjoint(2*segtree_n);
        repeat_from (r,1,2*n+1) {
            while (dist(ps[l]) + limit <= dist(ps[r-1])) ++ l;
            vector<int> acc; {
                int il = l;
                int ir = r;
                for (il += segtree_n, ir += segtree_n; il < ir; il /= 2, ir /= 2) {
                    if (il % 2 == 1) acc.push_back(il ++);
                    if (ir % 2 == 1) acc.push_back(-- ir);
                }
            }
            repeat (j, acc.size()) {
                disjoint[acc[j]] = true;
                repeat (i, j) if (i != j) {
                    implies(acc[i], - acc[j]);
                    implies(acc[j], - acc[i]);
                }
            }
        }
        repeat_from (i,1,segtree_n) {
            if (disjoint[i]) {
                int l = 2*i;
                int r = 2*i+1;
                implies(l, - r);
                implies(r, - l);
                disjoint[l] = true;
                disjoint[r] = true;
            }
        }
        return not twosat(2*segtree_n-1+n, cnf).empty();
    };
    int l = 0, r = 1e9+7;
    repeat (i,n) {
        repeat (j,n) if (i != j) {
            int acc = 0;
            setmax(acc, abs(x[i] - x[j]));
            setmax(acc, abs(x[i] - y[j]));
            setmax(acc, abs(y[i] - x[j]));
            setmax(acc, abs(y[i] - y[j]));
            setmin(r, acc+1);
        }
    }
    while (l + 1 < r) {
        int m = (l + r) / 2;
        (pred(m) ? l : r) = m;
    }
    printf("%d\n", l);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

#define int long long

const int inf = 1e18;

struct T {
	int val, sum, mn;
	int fix, siz;
	T *lson, *rson;
	T(int v) {
		val = sum = mn = v;
		fix = rand(); siz = 1;
		lson = rson = NULL;
	}
};

void del_T(T *&x) {
	if (x -> lson) del_T(x -> lson);
	if (x -> rson) del_T(x -> rson);
	delete x; x = NULL;
}

void pushup(T *x) {
	x -> sum = x -> val;
	if (x -> lson) x -> sum += x -> lson -> sum;
	if (x -> rson) x -> sum += x -> rson -> sum;
	x -> mn = x -> val;
	if (x -> lson) x -> mn = min(x -> mn, x -> lson -> mn);
	if (x -> rson) x -> mn = min(x -> mn, x -> rson -> mn);
	x -> siz = 1;
	if (x -> lson) x -> siz += x -> lson -> siz;
	if (x -> rson) x -> siz += x -> rson -> siz;
}

void split(T *x, int k, T *&a, T *&b) {
	if (!x) {a = b = NULL; return ;}
	int lsiz = x -> lson ? x -> lson -> siz : 0;
	if (lsiz + 1 <= k) {
		a = x;
		split(x -> rson, k - lsiz - 1, a -> rson, b);
		pushup(a);
	} else {
		b = x;
		split(x -> lson, k, a, b -> lson);
		pushup(b);
	}
}

T *merge(T *a, T *b) {
	if (!a || !b) return a ? a : b;
	if (a -> fix < b -> fix) {
		a -> rson = merge(a -> rson, b);
		pushup(a);
		return a;
	} else {
		b -> lson = merge(a, b -> lson);
		pushup(b);
		return b;
	}
}

int find(T *x, int v) {
	int lsum = x -> lson ? x -> lson -> sum : 0;
	int lsiz = x -> lson ? x -> lson -> siz : 0;
	if (lsum >= v) return find(x -> lson, v);
	if (lsum + x -> val >= v) return 1 + lsiz;
	return 1 + lsiz + find(x -> rson, v - lsum - x -> val);
}

T *root;

void prt(T *x) {
	if (!x) return ;
	prt(x -> lson);
	cerr << x -> val << " ";
	prt(x -> rson);
}

void wait() {for (int i = 0; i < 1e8; ++ i) i <<= 1, i >>= 1;}
#define dbg(x) {cerr << #x << ": "; prt(x); cerr << endl; wait();}

const int N = 1e4 + 5;
int n, x[N][2], use[N];
int cur;

void del(int k) {
	// cerr << "del " << k << endl;
	T *a, *b, *c;
	int rnk = find(root, x[k][use[k]] + inf);
	split(root, rnk + 1, b, c);
	split(b, rnk - 1, a, b);
	// dbg(a); dbg(b); dbg(c);
	T *nw = new T(b -> sum);
	del_T(b); b = nw;
	root = merge(merge(a, b), c);
	// dbg(root);
}

void add(int k) {
	// cerr << "add " << k << endl;
	T *a, *b, *c;
	int rnk = find(root, x[k][use[k]] + inf);
	split(root, rnk, b, c);
	split(b, rnk - 1, a, b);
	// dbg(a); dbg(b); dbg(c);
	T *d = new T(x[k][use[k]] + inf - (a ? a -> sum : 0));
	T *e = new T((a ? a -> sum : 0) + b -> sum - x[k][use[k]] - inf);
	T *nw = merge(d, e);
	del_T(b); b = nw;
	root = merge(merge(a, b), c);
	// dbg(root);
}

void ch(int k) {
	del(k);
	use[k] ^= 1;
	add(k);
	cur = root -> mn;
}

signed main() {
	// freopen("in", "r", stdin);
	ios :: sync_with_stdio(0);
	cin.tie(0); cout.tie(0);
	cin >> n;
	for (int i = 0; i < n; ++ i)
		cin >> x[i][0] >> x[i][1];
	for (int i = 0; i < n; ++ i)
		use[i] = rand() % 2;
	multiset <int> st;
	st.insert(-inf); st.insert(inf);
	for (int i = 0; i < n; ++ i)
		st.insert(x[i][use[i]]);
	for (set <int> :: iterator it = st.begin(), oit; it != st.end(); ++ it) {
		if (it != st.begin()) root = merge(root, new T(*it - *oit));
		oit = it;
	}
	// dbg(root);
	cur = root -> mn;
	int mx = 0;
	double T = 100;
	while (T >= 1e-28) {
		// cerr << T << endl;
		int k = rand() % n;
		int old = cur;
		ch(k);
		int delta = cur - old;
		if (delta < 0 && exp(delta / T) * RAND_MAX <= rand()) ch(k);
		T *= 1.0 - 3e-5; mx = max(mx, cur);
		// dbg(root);
	}
	// dbg(root);
	cout << mx << endl;
	return 0;
}

