#define SIZE 20005
#define BT 1024*32*2
#define MX 1000005
#define INF 1000000005

using namespace std;

int sz;
vector <int> vec[MX];
vector <int> rvec[MX];
struct segtree
{
	int seg[BT];
	int mum;

	void init(int n)
	{
		mum=1;
		while(mum<n) mum<<=1;
		for(int i=0;i<mum*2;i++)
		{
			vec[sz].clear();
			seg[i]=sz++;
		}
		for(int i=0;i<mum-1;i++)
		{
			vec[seg[i]].push_back(seg[i*2+1]);
			vec[seg[i]].push_back(seg[i*2+2]);
		}
	}
	void add(int k,int x)
	{
		k+=mum-1;
		nw(k);
		vec[seg[k]].push_back(x);
	}
	void nw(int k)
	{
		vec[sz].clear();
		vec[sz].push_back(seg[k]);
		seg[k]=sz++;
		if(k>0)
		{
			nw((k-1)/2);
			vec[seg[(k-1)/2]].push_back(seg[k]);
		}
	}
	void update(int a,int b,int k,int l,int r,int v)
	{
		if(b<=l||r<=a) return;
		if(a<=l&&r<=b) vec[v].push_back(seg[k]);
		else
		{
			update(a,b,k*2+1,l,(l+r)/2,v);
			update(a,b,k*2+2,(l+r)/2,r,v);
		}
	}
	void update(int a,int b,int v)
	{
		update(a,b,0,0,mum,v);
	}
};
segtree seg;
int X[SIZE],Y[SIZE];
vector <int> vx;
vector <int> vs;
bool use[MX];
int cmb[MX];
int n;

void dfs(int v)
{
	use[v]=true;
	for(int i=0;i<vec[v].size();i++) if(!use[vec[v][i]]) dfs(vec[v][i]);
	vs.push_back(v);
}
void rdfs(int v,int k)
{
	cmb[v]=k;
	use[v]=true;
	for(int i=0;i<rvec[v].size();i++) if(!use[rvec[v][i]]) rdfs(rvec[v][i],k);
}
void scc()
{
	vs.clear();
	memset(use,false,sizeof(use));
	for(int i=0;i<sz;i++) if(!use[i]) dfs(i);
	memset(use,false,sizeof(use));
	int k=0;
	for(int i=sz-1;i>=0;i--) if(!use[vs[i]]) rdfs(vs[i],k++);
}
bool solve(int d)
{
	for(int i=0;i<2*n;i++) vec[i].clear();
	sz=2*n;
	seg.init(vx.size()+2);
	for(int i=0;i<n;i++)
	{
		//i*2 : Xを使うとき
		//i*2+1 : Yを使うとき
		int L=lower_bound(vx.begin(),vx.end(),vx[X[i]]-d+1)-vx.begin(),R=upper_bound(vx.begin(),vx.end(),vx[X[i]]+d-1)-vx.begin()-1;
		if(L<=R) seg.update(L,R+1,i*2);
		L=lower_bound(vx.begin(),vx.end(),vx[Y[i]]-d+1)-vx.begin(),R=upper_bound(vx.begin(),vx.end(),vx[Y[i]]+d-1)-vx.begin()-1;
		if(L<=R) seg.update(L,R+1,i*2+1);
		seg.add(X[i],i*2+1);
		seg.add(Y[i],i*2);
	}
	seg.init(vx.size()+2);
	for(int i=n-1;i>=0;i--)
	{
		int L=lower_bound(vx.begin(),vx.end(),vx[X[i]]-d+1)-vx.begin(),R=upper_bound(vx.begin(),vx.end(),vx[X[i]]+d-1)-vx.begin()-1;
		if(L<=R) seg.update(L,R+1,i*2);
		L=lower_bound(vx.begin(),vx.end(),vx[Y[i]]-d+1)-vx.begin(),R=upper_bound(vx.begin(),vx.end(),vx[Y[i]]+d-1)-vx.begin()-1;
		if(L<=R) seg.update(L,R+1,i*2+1);
		seg.add(X[i],i*2+1);
		seg.add(Y[i],i*2);
	}
	for(int i=0;i<sz;i++) rvec[i].clear();
	for(int i=0;i<sz;i++)
	{
		for(int j=0;j<vec[i].size();j++)
		{
			int to=vec[i][j];
			rvec[to].push_back(i);
		}
	}
	scc();
	//for(int i=0;i<n;i++) printf("%d %d\n",cmb[i*2],cmb[i*2+1]);
	for(int i=0;i<n;i++)
	{
		if(cmb[i*2]==cmb[i*2+1]) return false;
	}
	return true;
}
int main()
{
	scanf("%d",&n);
	for(int i=0;i<n;i++)
	{
		scanf("%d %d",&X[i],&Y[i]);
		vx.push_back(X[i]);
		vx.push_back(Y[i]);
	}
	sort(vx.begin(),vx.end());
	vx.erase(unique(vx.begin(),vx.end()),vx.end());
	for(int i=0;i<n;i++)
	{
		X[i]=lower_bound(vx.begin(),vx.end(),X[i])-vx.begin();
		Y[i]=lower_bound(vx.begin(),vx.end(),Y[i])-vx.begin();
	}
	//if(solve(2)) puts("YES");
	//return 0;
	int l=-1,r=INF/(n-1)+1;
	while(r-l>1)
	{
		int m=(l+r)/2;
		if(solve(m)) l=m;
		else r=m;
		//printf("%d %d\n",l,r);
	}
	printf("%d\n",l);
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
#define FOR(i,a,b) for(int i=(a);i<(b);i++)
#define REP(i,a) FOR(i,0,a)
typedef long long ll;

const ll INF=1e9;
const int MAX_N=1e5;

int N,X[MAX_N],Y[MAX_N];

vector<int> G[MAX_N*2],rG[MAX_N*2];

vector<int> vs;
int cmp[MAX_N*2];
bool used[MAX_N*2];

void add_edge(int from,int to){
	G[from].push_back(to);
	rG[to].push_back(from);
}

void dfs(int v){
	used[v]=true;
	REP(i,(int)G[v].size()){
		if (!used[G[v][i]]){
			dfs(G[v][i]);
		}
	}
	vs.push_back(v);
}

void rdfs(int v,int k){
	used[v]=true;
	cmp[v]=k;
	REP(i,(int)rG[v].size()){
		if (!used[rG[v][i]]){
			rdfs(rG[v][i],k);
		}
	}
}

int scc(){
	memset(used,0,sizeof(used));
	vs.clear();
	REP(i,N*2){
		if (!used[i]){
			dfs(i);
		}
	}
	memset(used,0,sizeof(used));
	int k=0;
	reverse(vs.begin(),vs.end());
	REP(i,(int)vs.size()){
		if (!used[vs[i]]){
			rdfs(vs[i],k++);
		}
	}
	return k;
}

bool C(ll d){
	REP(i,2*N){
		G[i].clear();
		rG[i].clear();
	}
	REP(i,N){
		FOR(j,i+1,N){
			if (i!=j){
				if (abs(X[i]-X[j])<d){
//					G[i].push_back(j+N);
//					G[j].push_back(i+N);
					add_edge(i,j+N);
					add_edge(j,i+N);
				}
				if (abs(X[i]-Y[j])<d){
//					G[i].push_back(j);
//					G[j+N].push_back(i+N);
					add_edge(i,j);
					add_edge(j+N,i+N);
				}
				if (abs(Y[i]-X[j])<d){
//					G[i+N].push_back(j+N);
	//				G[j].push_back(i);
					add_edge(i+N,j+N);
					add_edge(j,i);
				}
				if (abs(Y[i]-Y[j])<d){
		//			G[i+N].push_back(j);
			//		G[j+N].push_back(i);
					add_edge(i+N,j);
					add_edge(j+N,i);
				}
			}
		}
	}
	scc();
	REP(i,N){
		if (cmp[i]==cmp[i+N]){
			return false;
		}
	}
	return true;
}

int main(){
	scanf("%d",&N);
	REP(i,N){
		scanf("%d %d",&X[i],&Y[i]);
	}
	ll lb=0,ub=INF;
	while(ub-lb>1){

		ll mid=(lb+ub)>>2;
		if (C(mid)){
			lb=mid;
		}else{
			ub=mid;
		}
	}
	printf("%lld\n",lb);
	return 0;
}

#include<bits/stdc++.h>
#define N 40009
#define M 10000009
using namespace std;

int n,m,tp,cnt,trtot,tot,dfsclk,fst[N],pnt[M],nxt[M];
int q[N],b[N][2],p[N][2],pos[N],low[N],scc[N],id[N];
struct node{ int x,y; }a[N];
bool operator <(node u,node v){
	return u.x<v.x || u.x==v.x && u.y<v.y;
}
bool operator <=(node u,node v){
	return u.x<v.x || u.x==v.x && u.y<=v.y;
}
void dfs(int x){
	int i,y; low[x]=pos[x]=++dfsclk; q[++tp]=x;
	for (i=fst[x]; i; i=nxt[i]){
		y=pnt[i];
		if (!pos[y]){
			dfs(y); low[x]=min(low[x],low[y]);
		} else if (!scc[y]) low[x]=min(low[x],pos[y]);
	}
	if (pos[x]==low[x])
		for (cnt++; ; ){
			scc[q[tp]]=cnt;
			if (q[tp--]==x) break;
		}
}
void add(int x,int y){
	pnt[++tot]=y; nxt[tot]=fst[x]; fst[x]=tot;
}
void ins(int x,int y){ add(x,y); add(y^1,x^1); }
void build(int k,int l,int r){
	p[k][0]=++trtot; p[k][1]=++trtot;
	if (l==r){
		id[l]=k; return;
	}
	int mid=l+r>>1;
	build(k<<1,l,mid); build(k<<1|1,mid+1,r);
	ins(p[k][1],p[k<<1][1]); ins(p[k][1],p[k<<1|1][1]);
}
void ins(int k,int l,int r,node x,node y,int z){
	if (y<x || y<a[l] || a[r]<x) return;
	if (x<=a[l] && a[r]<=y){
		ins(p[z][0],p[k][1]); return;
	}
	int mid=l+r>>1;
	ins(k<<1,l,mid,x,y,z); ins(k<<1|1,mid+1,r,x,y,z);
}
bool check(int t){
	tot=0; memset(fst,0,sizeof(fst));
