	int i,x,y;
	for (i=1; i<=m; i++){
		ins(1,1,m,(node){a[i].x-t+1,-m},(node){a[i].x,a[i].y-1},id[i]);
		ins(1,1,m,(node){a[i].x,a[i].y+1},(node){a[i].x+t-1,m},id[i]);
	}
	for (i=1; i<=n; i++){
		x=id[b[i][0]]; y=id[b[i][1]];
		ins(p[x][0],p[y][1]); ins(p[x][1],p[y][0]);
	}
	memset(pos,0,sizeof(pos)); memset(scc,0,sizeof(scc));
	tp=cnt=dfsclk=0;
	for (i=2; i<=trtot; i++) if (!pos[i]) dfs(i);
	for (i=2; i<=trtot; i++) if (scc[i]==scc[i^1]) return 0;
	return 1;
}
int main(){
	scanf("%d",&n);
