	for(i=1 ; i<=2*n ; i++) // file complaints
	{
		ind=lower_bound(world+1, world+2*n+1, make_pair(world[i].first-X+1, -1LL))-world;
		if(ind<=i-1) add_seg(1, 1, 2*n, ind, i-1, i); // cout<<"LOW "<<i<<" "<<ind<<"\n";
		ind=upper_bound(world+1, world+2*n+1, make_pair(world[i].first+X, -1LL))-world; ind--;
		if(ind>=i+1) add_seg(1, 1, 2*n, i+1, ind, i); // cout<<"HIGH "<<i<<" "<<ind<<"\n";
	}
	for(i=1 ; i<=n ; i++)
	{
		u=wow[cv[2*i-1]]; v=wow[cv[2*i]];
		add_clause(u, ~v); add_clause(~u, v);
	}
	calc_scc();
	if(satisfy()) return true;
	return false;
}

