int dfn[maxn],low[maxn],stk[maxn],bel[maxn],top,tot,blocks;
inline void Tarjan(int u)
{
    dfn[u]=low[u]=++tot;
    stk[top++]=u;
    int v;
    for(int i=head[u];i!=-1;i=edge[i].next){
        v=edge[i].to;
        if(!dfn[v]){
            Tarjan(v);
            if(low[v]<low[u]) low[u]=low[v];
        }
        else if(!bel[v]&&dfn[v]<low[u]) low[u]=dfn[v];
    }
    if(low[u]==dfn[u]){
        ++blocks;
        do
        {
            v=stk[--top];
            bel[v]=blocks;
        }while(v!=u);
    }
    return;
}
struct Node
{
    int val,id;
    bool operator<(const Node&p)const
    {
        return val<p.val;
    }
}w[MAXN];
int h[MAXN],rh[MAXN],id[maxn],pos,n;
inline void build(int l,int r,int rt)
{
    id[rt]=pos++;
    if(l==r){
        Addedge(id[rt]<<1|1,rh[l]^1);
        Addedge(rh[l],id[rt]<<1);
        return;
    }
    int mid=l+r>>1;
    build(l,mid,rt<<1);
    build(mid+1,r,rt<<1|1);
    Addedge(id[rt]<<1|1,id[rt<<1]<<1|1);
    Addedge(id[rt]<<1|1,id[rt<<1|1]<<1|1);
    Addedge(id[rt<<1]<<1,id[rt]<<1);
    Addedge(id[rt<<1|1]<<1,id[rt]<<1);
    return;
}
inline void update(int L,int R,int u,int l,int r,int rt)
{
    if(L<=l&&R>=r){
        Addedge(u,id[rt]<<1|1);
        Addedge(id[rt]<<1,u^1);
        return;
    }
    int mid=l+r>>1;
    if(L<=mid) update(L,R,u,l,mid,rt<<1);
    if(R>mid) update(L,R,u,mid+1,r,rt<<1|1);
    return;
}
inline bool check(int d)
{
    if(!d) return 1;
    memset(dfn,0,sizeof(dfn));
    memset(bel,0,sizeof(bel));
    memset(head,-1,sizeof(head));
    pos=n;
    tol=top=tot=blocks=0;
    build(1,n<<1,1);
    for(int i=0;i<n<<1;i++){
        Node tmp;
        tmp.val=w[h[i]-1].val-d+1;
        int l=lower_bound(w,w+(n<<1),tmp)-w+1;
        tmp.val+=d+d-2;
        int r=upper_bound(w,w+(n<<1),tmp)-w;
        if(l<h[i]) update(l,h[i]-1,i,1,n<<1,1);
        if(r>h[i]) update(h[i]+1,r,i,1,n<<1,1);
    }
    for(int i=0;i<pos<<1;i++) if(!dfn[i]) Tarjan(i);
    for(int i=0;i<pos<<1;i+=2){
        if(bel[i]==bel[i^1]) return 0;
    }
    return 1;
}
inline int solve()
{
    int l=0,r=1e9+1;
    while(l<r)
    {
        int mid=l+r+1>>1;
        if(check(mid)) l=mid;
        else r=mid-1;
    }
    return l;
}
int main()
{
   // freopen("a.txt","r",stdin);
    while(~scanf("%d",&n))
    {
        for(int i=0;i<n;i++){
            scanf("%d%d",&w[i<<1].val,&w[i<<1|1].val);
            w[i<<1].id=i<<1,w[i<<1|1].id=i<<1|1;
        }
        sort(w,w+(n<<1));
        for(int i=0;i<n<<1;i++){
            rh[i+1]=w[i].id;
            h[w[i].id]=i+1;
        }
        printf("%d\n",solve());
    }
    return 0;
}

