void init(int x,int y)
{
    indexx[++cnt].to=y;
    indexx[cnt].next=head[x];
    head[x]=cnt;
}
struct lemon
{
    lint v;
    int id;
    lemon(){}
    lemon(lint v,int id):v(v),id(id){};
    bool operator<(const lemon &other)const
    {
        return v<other.v;
