struct segment_tree
{
    int l,r,lson,rson;
}tree[N*4];
void push_up(int now)
{
    init(now,tree[now].lson);
    init(now,tree[now].rson);
}
void build(int &now,int l,int r)
{
    now=++tot;
    tree[now].l=l,tree[now].r=r;
    if(l==r)
    {
        init(now,point[l].id<=n?point[l].id+n:point[l].id-n);
        return;
    }
    int mid=(l+r)>>1;
    build(tree[now].lson,l,mid);
    build(tree[now].rson,mid+1,r);
    push_up(now);
    return;
}
void add(int now,int l,int r,int p)
{
    if(l<=tree[now].l&&r>=tree[now].r)
    {
        init(p,now);
        return;
    }
    int mid=(tree[now].l+tree[now].r)>>1;
    if(l<=mid) add(tree[now].lson,l,r,p);
    if(r>mid) add(tree[now].rson,l,r,p);
}
int dfn[N],low[N],dfn_id,st[N],top,circs,belong[N];
bool used[N];
void tarjan(int u)
{
    dfn[u]=low[u]=++dfn_id;
    st[++top]=u;
    used[u]=1;
    for(int i=head[u];i;i=indexx[i].next)
    {
        int v=indexx[i].to;
        if(!dfn[v])
        {
            tarjan(v);
            low[u]=min(low[u],low[v]);
        }
        else if(used[v])
        {
            low[u]=min(low[u],dfn[v]);
        }
    }
    if(dfn[u]==low[u])
    {
        int v=-1;
        circs++;
        while(v!=u)
        {
            v=st[top--];
            used[v]=0;
            belong[v]=circs;
        }
    }
}
bool SAT()
{
    for(int i=1;i<=point_id;i++)
    {
        if(!dfn[i]) tarjan(i);
    }
    for(int i=1;i<=n;i++)
    {
        if(belong[i]==belong[i+n]) return 0;
    }
    return 1;
}
bool check(int mid)
{
    cnt=0;
    tot=point_id;
    memset(head,0,sizeof(head));
    memset(dfn,0,sizeof(dfn));
    memset(low,0,sizeof(low));
    memset(used,0,sizeof(used));
    top=0;
    circs=0;
    int root;
    build(root,1,point_id);
    int head,tail;
    head=tail=1;
    for(int i=1;i<=point_id;i++)
    {
        int op,p=point[i].id;
        if(p<=n) op=pos[p+n];
        else op=pos[p-n];
        while(tail<=i&&point[tail].v+mid<point[i].v) tail++;
        if(tail<i&&tail>=1&&point[tail].v+mid>point[i].v)
        {
            if(tail<=op&&op<i)
            {
                if(op<i-1) add(root,op+1,i-1,p);
                if(tail<op) add(root,tail,op-1,p);
            }
            else
            {
                add(root,tail,i-1,p);
            }
        }
        while(head<=point_id&&point[head].v-mid<point[i].v) head++;
        head--;
        if(head>i&&head<=point_id&&point[head].v-mid<point[i].v)
        {
            if(head>=op&&op>i)
            {
                if(op>i+1) add(root,i+1,op-1,p);
                if(head>op) add(root,op+1,head,p);
            }
            else
            {
                add(root,i+1,head,p);
            }
        }
    }
    return SAT();
}
