#include <bits/stdc++.h>

using namespace std;

typedef pair <int, int> pii;

set <pii> S;
vector <int> T;
int X[20202], C[20202];
bool chk[20202];
int n;

void dfs1(int p, int d)
{
	bool f = 0;

	chk[p] = 1;

	for(; ; ){
		auto it = S.lower_bound(pii(X[p] - d + 1, -1));
		if(f){
			if(it == S.end()) break;
			else it = next(it);
		}
		if(it == S.end() || it -> first >= X[p] + d) break;

		int t = it -> second;
		if(t == p) f = 1;
		else{
			S.erase(it);
			if(!chk[t ^ 1]) dfs1(t ^ 1, d);
		}
	}

	T.push_back(p);
}

void dfs2(int p, int d, int s)
{
	bool f = 0;

	chk[p] = 1; C[p] = s;

	for(; ; ){
		auto it = S.lower_bound(pii(X[p ^ 1] - d + 1, -1));
		if(f){
			if(it == S.end()) break;
			else it = next(it);
		}
		if(it == S.end() || it -> first >= X[p ^ 1] + d) break;

		int t = it -> second;
		if(t == (p ^ 1)) f = 1;
		else{
			S.erase(it);
			if(!chk[t]) dfs2(t, d, s);
		}
	}
}

bool check(int d)
{
	int i, s;

	S.clear();

	for(i=0; i<n+n; i++){
		S.insert(pii(X[i], i));
		chk[i] = 0;
	}

	for(i=0; i<n+n; i++){
		if(!chk[i]) dfs1(i, d);
	}

	S.clear();

	for(i=0; i<n+n; i++){
		S.insert(pii(X[i], i));
		chk[i] = 0;
	}

	for(s=0; !T.empty(); T.pop_back()){
		if(!chk[T.back()]) dfs2(T.back(), d, ++s);
	}

	for(i=0; i<n; i++){
		if(C[i << 1] == C[i << 1 | 1]) return 0;
	}

	return 1;
}

int main()
{
	int i, s, e;

	scanf("%d", &n);

	for(i=0; i<n+n; i++){
		scanf("%d", X + i);
	}

	for(s=0, e=1e9; s<=e; ){
		if(check(s + e >> 1)) s = (s + e >> 1) + 1;
		else e = (s + e >> 1) - 1;
	}

	printf("%d\n", s - 1);

	return 0;
}

