void solve(ll N){
    ll lo = 0,  hi = 0;
    REP(i, N) {
        ll xi = 2*i, yi = xi + 1;
        ll Pxi = POS[i][0], Pyi = POS[i][1];
        if(!Rec.count(Pxi)){
            Rec[Pxi] = vll(1, xi);
        }else{
            Rec[Pxi].push_back(xi);
        }

        if(!Rec.count(Pyi)){
            Rec[Pyi] = vll(1, yi);
        }else{
            Rec[Pyi].push_back(yi);
        }

        for(ll j = i+1; j < N; j++){
            ll xj = 2*j, yj = xj + 1;
            chmax(hi, abs(POS[i][0]-POS[j][0]));
            chmax(hi, abs(POS[i][0]-POS[j][1]));
            chmax(hi, abs(POS[i][1]-POS[j][0]));
            chmax(hi, abs(POS[i][1]-POS[j][1]));
        }
    }

    while(hi - lo > 1){
        ll mid = (lo + hi) / 2;
        ll isGood = check(mid, N);
        if(isGood) lo = mid;
        else hi = mid;
    }
    cout<<lo<<endl;
}

