		addedge2(fr, p + (n << 1 | 1));
		return ;
	}
	int mid = (l + r) >> 1;
	if (ql <= mid) query(fr, p << 1, l, mid, ql, qr);
	if (mid < qr) query(fr, p << 1 | 1, mid + 1, r, ql, qr);
}

int dfn[N * 33], low[N * 33], instk[N * 33], stk[N * 33], top, tim, scc, bel[N * 33];
void tarjan(int x) {
	dfn[x] = low[x] = ++ tim; stk[++ top] = x; instk[x] = 1;
	for (int i = hd[x]; i; i = e[i].nxt) {
		int y = e[i].to;
		if (!dfn[y]) {
			tarjan(y);
			low[x] = min(low[x], low[y]);
		} else if (instk[y]) low[x] = min(low[x], dfn[y]);
	}
	for (int i = hd2[x]; i; i = e2[i].nxt) {
		int y = e2[i].to;
		if (!dfn[y]) {
			tarjan(y);
			low[x] = min(low[x], low[y]);
		} else if (instk[y]) low[x] = min(low[x], dfn[y]);
	}
	if (dfn[x] == low[x]) {
		++ scc; int y;
		do {
			y = stk[top --];
			instk[y] = 0;
			bel[y] = scc;
		} while (y ^ x);
	}
}
