inline bool check(int mid) {
	cnt2 = 0;
	for (int i = 2; i <= (n << 1 | 1); ++ i) hd2[i] = 0;
	for (int i = 2; i <= (n << 1 | 1); ++ i) {
		query(i, 1, 1, n * 2, getupp(X[i] - mid), rnk[i] - 1);
		query(i, 1, 1, n * 2, rnk[i] + 1, getlow(X[i] + mid));
	}
	for (int i = 2; i <= (n << 1 | 1) + len; ++ i) dfn[i] = low[i] = instk[i] = bel[i] = 0; tim = top = scc = 0;
	for (int i = 2; i <= (n << 1 | 1) + len; ++ i) if (!dfn[i]) tarjan(i);
	for (int i = 1; i <= n; ++ i) if (bel[i << 1] == bel[i << 1 | 1]) return 0;
	return 1;
}

