class TwoSat {
private :
	vector<int> adj[N];
	int dfn[N], low[N], tim;
	int sta[N], top;
	int col[N], scc, n, tot;

	void tarjan(int x) {
		dfn[x] = low[x] = ++tim;
		sta[++top] = x;
		for (int to : adj[x]) {
			if (dfn[to]) {
				if (!col[to]) {
					upmin(low[x], dfn[to]);
				}
			} else {
				tarjan(to);
				upmin(low[x], low[to]);
			}
		}
		if (dfn[x] == low[x]) {
			++scc;
			do {
				col[sta[top]] = scc;
			} while (sta[top--] != x);
		}
	}
public :
	void init(int n, int tot) {
		memset(col, 0, sizeof(int) * (tot));
		memset(dfn, 0, sizeof(int) * (tot));
		rep (i, 0, tot - 1) adj[i].clear();
		this->n = n;
		this->tot = tot;
	}
	inline void addEdge(int x, int y) {
		adj[x].pb(y ^ 1);
		adj[y].pb(x ^ 1);
	}
	inline void tadd(int x, int y) {
		adj[x].pb(y);
	}
	bool check() {
		top = tim = scc = 0;
		rep (i, 0, tot - 1) {
			if (!col[i]) {
				tarjan(i);
			}
		}
		rep (i, 0, n - 1) {
			if (col[pt(i)] == col[nt(i)]) {
				return 0;
			}
		}
		return 1;
	}
} my;

