int h[N],cnt;

void adge(int f,int t){
	e[++cnt]=(E){f,t,h[f]};h[f]=cnt;
}

int pre[N],low[N],dfs_clock,ssc_cnt,sscno[N];
stack<int> s;

void dfs(int u){
    pre[u]=low[u]=++dfs_clock;
    s.push(u); 
    for(int i=h[u];i>-1;i=e[i].xt){
        if(!pre[e[i].t]){
            dfs(e[i].t);
            low[u]=min(low[u],low[e[i].t]);
        }else if(!sscno[e[i].t]){
            low[u]=min(low[u],pre[e[i].t]);
        }
    }
    if(low[u]==pre[u]){
        ssc_cnt++;
        for(;;){
            int x=s.top();s.pop();
            sscno[x]=ssc_cnt;
            if(x==u) break;
        }
    }
}
int mx,id[N],n,ct,ls[N<<2],rs[N<<2];
void build(int &o,int L,int R){
	o=++ct;
	if(L==R){ mx=max(mx,o);id[L]=o;return;}
	int M=L+R>>1;
	build(ls[o],L,M);
	build(rs[o],M+1,R);
	adge(o,ls[o]);
	adge(o,rs[o]);
}

void link(int o,int L,int R,int x,int l,int r){
	if(l>r) return;
	if(l<=L&&r>=R){
		adge(x,o);
	}else{
		int M=L+R>>1;
		if(l<=M) link(ls[o],L,M,x,l,r);
		if(r>M) link(rs[o],M+1,R,x,l,r);
	}
}

