struct Segment_Tree {
    struct node {
        int l, r, val;
        node *ch[2];
        node(int l, int r) : l(l), r(r) {
            val = 0;
            ch[0] = ch[1] = NULL;
        }
        inline int mid() { return (l + r) >> 1; }
    } *root;
    void build(node *&o, int l, int r) {
        o = new node(l, r);
        if(l == r) {
            o->val = e[l].second;
            return;
        }
        o->val = ++ node_cnt;
        build(o->ch[0], l, o->mid());
        build(o->ch[1], o->mid() + 1, r);
        add(o->val, o->ch[0]->val);
        add(o->val, o->ch[1]->val);
    }
    void link(node *o, int l, int r, int u) {
        if(r < l) return;
        if(l <= o->l && o->r <= r) {
            add(u, o->val);
            return;
        }
        if(l <= o->mid()) link(o->ch[0], l, r, u);
        if(r > o->mid()) link(o->ch[1], l, r, u);
    }
} tr;

inline void Tarjan(int x) {
