            low[x] = Min(low[x], low[to[i]]);
        }
        else if(scc[to[i]] == 0) {
        	low[x] = Min(low[x], dfn[to[i]]);
        }
    }
    if(dfn[x] == low[x]) {
    	int t; scc_cnt ++;
    	do {
    		t = sta[tp --];
    		scc[t] = scc_cnt;
    	} while(t != x);
    }
}

