            int r = upper_bound(e + 1, e + 2*n + 1,make_pair(a[k][i]+x-1, 2*n+1)) - e - 1;
            int m = lower_bound(e + 1, e + 2*n + 1,make_pair(a[k][i], (k^1)*n+i)) - e;
            tr.link(tr.root, l, m - 1, k * n + i);
            tr.link(tr.root, m + 1, r, k * n + i);
        }
