		Ry=upper_bound(e+1,e+2*n+1,(node){ry[i]+v-1,0})-e-1;
		if(Lx<=Rx)xtr->ade(i,Lx,g[i]-1),xtr->ade(i,g[i]+1,Rx);
		if(Ly<=Ry)xtr->ade(i+n,Ly,g[i+n]-1),xtr->ade(i+n,g[i+n]+1,Ry);
	}
