	memset(low,0,sizeof(low));
	memset(col,0,sizeof(col));
	tim=top=nc=0;
	for(int i=1;i<=num;i++)
		if(!vis[i]) tarjan(i);		
	for(int i=1;i<=n;i++)
		if(col[i]==col[i+n]) return 0;
	return 1;		
}
