{
	if(l > r) return;
	int ll = (l+B-1)/B*B, rr = r/B*B;
	if(ll <= rr){
		for(int i = ll/B; i < rr/B; i++){
			G[v].push_back(2*N+i);
		}
		for(int i = l; i < ll; i++){
			int u = vec[i].second.first + (1-vec[i].second.second)*N;
			G[v].push_back(u);
		}
		for(int i = rr; i < min(r+1, 2*N); i++){
			int u = vec[i].second.first + (1-vec[i].second.second)*N;
			G[v].push_back(u);
		}
	}
	else{
		for(int i = l; i <= r; i++){
			int u = vec[i].second.first + (1-vec[i].second.second)*N;
			G[v].push_back(u);
		}
	}
}

bool check(int d)
{
	for(int i = 0; i < V; i++) G[i].clear();
	for(int i = 0; i < 2*N; i++){
		int v = vec[i].second.first + (1-vec[i].second.second)*N;
		G[2*N+i/B].push_back(v);
	}
	int l = 0, r = 0;
	for(int i = 0; i < 2*N; i++){
		int v = vec[i].second.first + vec[i].second.second*N;
		while(vec[l].first < vec[i].first-(d-1)) l++;
		range(v, l, i-1);
	}
	for(int i = 0; i < 2*N; i++){
		int v = vec[i].second.first + vec[i].second.second*N;
		while(r < 2*N && vec[r].first <= vec[i].first+(d-1)) r++;
		range(v, i+1, r-1);
	}

	for(int i = 0; i < V; i++) revG[i].clear();
	for(int i = 0; i < V; i++){
		for(int j = 0; j < G[i].size(); j++){
			revG[G[i][j]].push_back(i);
		}
	}

	for(int i = 0; i < V; i++) used[i] = false;
	topo.clear();
	for(int i = 0; i < V; i++) if(!used[i]) tpsort(i, -1);
	reverse(topo.begin(), topo.end());

	for(int i = 0; i < V; i++) used[i] = false;
	for(int i = 0; i < topo.size(); i++){
		if(!used[topo[i]]) dfs(topo[i], -1, i);
	}

	for(int i = 0; i < N; i++){
		if(scc[i] == scc[i+N]) return false;
	}
	return true;
}

int main(void)
{
	ios::sync_with_stdio(0);
	cin.tie(0);

	cin >> N;
	for(int i = 0; i < N; i++) cin >> x[i] >> y[i];

	for(int i = 0; i < N; i++){
		vec.push_back(make_pair(x[i], make_pair(i, 0)));
		vec.push_back(make_pair(y[i], make_pair(i, 1)));
	}
	sort(vec.begin(), vec.end());

	B = sqrt(2*N), Bnum = (2*N+B-1)/B;
	V = 2*N + Bnum;

	int ub = 1e9+7, lb = 0, mid;
	while(ub - lb > 1){
		mid = (ub + lb) / 2;
		if(check(mid)) lb = mid;
		else ub = mid;
	}
	cout << lb << endl;
	return 0;
}

#include<iostream>
#include<cstdio>
#include<vector>
#include<cstring>
#include<stack>
#include<algorithm>

using namespace std;

struct data{
	int x,i;
	data():x(0),i(0){}
	data(int y,int j):x(y),i(j){}
	friend bool operator<(const data &dt1,const data &dt2){return dt1.x<dt2.x;}
};

stack<int> s;
int n,x[80001],idx,tot,id[80001],low[80001],dfn[80001],scc,cid[80001];
vector<data> vec;
vector<int> point[80001];

void build(int o,int l,int r){
	id[o]=++tot;
	if(o>1)point[id[o>>1]].push_back(tot);
	if(l==r){int v=vec[l-1].i;point[id[o]].push_back(v<=n?v+n:v-n);return;}
	int m=l+r>>1;
	build(o<<1,l,m),build(o<<1|1,m+1,r);
}

void update(int o,int l,int r,int a,int b,int x){
	if(a>b)return;
	if(l==a&&r==b){point[x].push_back(id[o]);return;}
	int m=l+r>>1;
	if(m>=b)update(o<<1,l,m,a,b,x);else if(m<a)update(o<<1|1,m+1,r,a,b,x);else update(o<<1,l,m,a,m,x),update(o<<1|1,m+1,r,m+1,b,x);
}

pair<int,int> get(int i,int m){
	pair<int,int> res;int l=1,r=i,mid;
	while(l<=r)if(vec[i-1].x-vec[(mid=l+r>>1)-1].x>=m)l=mid+1;else r=mid-1;
	res.first=r+1,l=i,r=n<<1;
	while(l<=r)if(vec[(mid=l+r>>1)-1].x-vec[i-1].x<m)l=mid+1;else r=mid-1;
	res.second=l-1;
	return res;
}

void dfs(int u){
	low[u]=dfn[u]=++idx;s.push(u);
	for(int v:point[u])if(!dfn[v]){dfs(v);low[u]=min(low[u],low[v]);}else if(dfn[v]>0)low[u]=min(low[u],dfn[v]);
	if(low[u]==dfn[u]){int x;++scc;while(x!=u)x=s.top(),s.pop(),dfn[x]=-dfn[x],cid[x]=scc;}
}

bool check(int m){
	memset(low,scc=idx=0,sizeof(low)),memset(dfn,0,sizeof(dfn));for(int i=1;i<=80000;++i)point[i].clear();
	build(1,1,tot=n<<1);
	for(int i=1;i<=n<<1;++i){int r=vec[i-1].i;pair<int,int> pr=get(i,m);update(1,1,n<<1,pr.first,i-1,r),update(1,1,n<<1,i+1,pr.second,r);}
	for(int i=1;i<=n<<1;++i)if(!dfn[i])dfs(i);
	for(int i=1;i<=n;++i)if(cid[i]==cid[i+n])return false;
	return true;
}

int main(){
	scanf("%d",&n);
	for(int i=1;i<=n;++i)scanf("%d%d",x+i,x+n+i),vec.push_back(data(x[i],i)),vec.push_back(data(x[i+n],i+n));
	sort(vec.begin(),vec.end());
	int l=0,r=1000000000,m;while(l<=r)if(check(m=l+r>>1))l=m+1;else r=m-1;
	printf("%d",l-1);
}

