	make(x<<1),make(x<<1|1);
}
void upd(int x,int l,int r,int t){
	if(l==p[x].l && r==p[x].r){
		if(l<r) v[t].push_back(x);
		else v[t].push_back(g[f[a[l].Y^1]]);
		return ;
	}
	int mid=p[x].l+p[x].r>>1;
	if(r<=mid) upd(x<<1,l,r,t);
	else if(l>mid) upd(x<<1|1,l,r,t);
	else upd(x<<1,l,mid,t),upd(x<<1|1,mid+1,r,t);
}
