#define mid ((l + r) >> 1)
void build(int v, int l, int r) {
	if (l > r) return;
	if (l == r) {
		int pos = z[l].second;
		pos_seg[l] = v;
		if (lst[pos]) add(-v, -lst[pos]), add(v, lst[pos]); else lst[pos] = v;
