	add(v, -(v << 1 | 1));
}

void join(int pos, int v, int l, int r, int L, int R) {
	if (l > r || R < l || L > r) return;
	if (L <= l && r <= R) { add(-pos, -v); return; }
	join(pos, v << 1, l, mid, L, R); join(pos, v << 1 | 1, mid + 1, r, L, R);
}
