class SCC {
	vector<vector<int>> graph;
	vector<vector<int>> revgraph;
	vector<int> vs;
	vector<bool> used;
public:
	vector<int> cmp;
	SCC(int n) {
		graph = revgraph = vector<vector<int>>(n, vector<int>());
		vs = cmp = vector<int>(n);
		used = vector<bool>(n);
	}
	void add_edge(int from, int to) {
		graph[from].push_back(to);
		revgraph[to].push_back(from);
	}
	void add_edge(int from, int a, int b, int s) {
		a += s; b += s;
		while (a < b) {
			if (a & 1) add_edge(from, s + (a++));
			if (b & 1) add_edge(from, s + (--b));
			a >>= 1; b >>= 1;
		}
	}
	void dfs(int v) {
		used[v] = true;
		for (int i : graph[v]) {
			if (!used[i]) dfs(i);
		}
		vs.push_back(v);

	}
	void rdfs(int v, int k) {
		used[v] = true;
		cmp[v] = k;
		for (int i : revgraph[v]) {
			if (!used[i]) rdfs(i, k);
		}
	}
	int solve() {
		int n = graph.size();
		for (int i = 0; i < n; i++) used[i] = false;
		vs.clear();
		for (int v = 0; v < n; v++) {
			if (!used[v]) dfs(v);
		}
		for (int i = 0; i < n; i++) used[i] = false;
		int k = 0;
		for (int i = n - 1; i >= 0; i--) {
			if (!used[vs[i]]) rdfs(vs[i], k++);
		}
		return k;
	}
};

