		r[check[i].second] = i;
	}
	int sz = 1;
	while (sz < n) sz <<= 1;
	SCC pre(6 * sz);
	rep(i, n) {
		pre.add_edge(r[2 * i] + 4 * sz, r[2 * i + 1]);
		pre.add_edge(r[2 * i + 1] + 4 * sz, r[2 * i]);
	}
	for (int i = 1; i < 2 * sz; i++) {
		pre.add_edge(i + 2 * sz, 2 * i + 2 * sz);
		pre.add_edge(i + 2 * sz, 2 * i + 1 + 2 * sz);
	}
