		addE(T[at].pos, T[at<<1].pos);
		Build((at<<1)|1, m+1, r);
		addE(T[at].pos, T[(at<<1)|1].pos);
	}
	int Pos;
	int L, R;
	int Findl(Pair v){
		if(!(v<Pa[N]))	return N+1;
		int l=1, r=N, m;
		while(l<r){
			m=(l+r)>>1;
			if(v<Pa[m])	r=m;
			else	l=m+1;
		}
		m=(l+r)>>1;
		return m;
	}
	int Findr(Pair v){
		if(!(Pa[1]<v))	return 0;
		int l=1, r=N, m;
		while(l<r){
			m=(l+r)>>1;
			if(Pa[m+1]<v)	l=m+1;
			else	r=m;
		}
		m=(l+r)>>1;
		return m;
	}
	bool Get(Pair vl, Pair vr){
		L=Findl(vl);
		R=Findr(vr);
		return L<=R;
	}
	void Link(int at){
		if(T[at].l>=L && T[at].r<=R){
			addE(Pos, T[at].pos);
			return;
		}
		int m=(T[at].l+T[at].r)>>1;
		if(L<=m)	Link(at<<1);
		if(R>m)	Link((at<<1)|1);
	}
} Tr[2];

