class SegmentTree {
#define ls (o << 1)
#define rs (o << 1 | 1)
private :
	int id[N];
	int n, tot;

	inline void build(int o, int l, int r) {
		id[o] = tot++;
		if (l == r) {
			my.tadd(id[o], nt(poi[l]));
			return ;
		}
		int mid = (l + r) >> 1;
		build(ls, l, mid);
		my.tadd(id[o], id[ls]);
		build(rs, mid + 1, r);
		my.tadd(id[o], id[rs]);
	}

	int L, R, from;
	inline void addEdge(int o, int l, int r) {
		if (L <= l && r <= R) {
			my.tadd(from, id[o]);
			return ;
		}
		int mid = (l + r) >> 1;
		if (mid >= L)  addEdge(ls, l, mid);
		if (mid < R)  addEdge(rs, mid + 1, r);
	}
public :
	inline void build(int n) {
		this->n = n;
		tot = n * 4;
		build(1, 1, n * 2);
	}
	inline void add(int fr, int l, int r) {
		from = fr, L = l, R = r;
		addEdge(1, 1, n * 2);
	}
