// O(V+E)
void get_scc() {
	vtime = 0;
	memset(visit, 0, sizeof(visit));
	scc_cnt = 0;
	memset(scc_idx, 0, sizeof(scc_idx));
	for (int i = 0; i < gn; ++i)
		if (visit[i] == 0) dfs(i);
}

