                else if (d1 >= d && d2 < d && d3 >= d && d4 >= d) {
                        add_edge(i, j);
                        add_edge(j + n, i + n);
                }
                else if (d1 < d && d2 >= d && d3 >= d && d4 >= d) {
                        add_edge(i, j + n);
                        add_edge(j, i + n);
                }
        }
        StronglyConnectedComponent();
        rep(i, n) if (cmp[i] == cmp[i + n]) return false;
        return true;
}

