		return x<b.x;
	}
}a[N];
void add(int x,int y)
{

	e[++cnt].to=y;e[cnt].nex=head[x];head[x]=cnt;
}
void build(int &x,int l,int r)
{
	if(l==r){
		x=(a[l].y<=n)?a[l].y+n:a[l].y-n;
		pos[a[l].y]=l;return;
	}x=++num;
	int mid=l+r>>1;
	build(t[x].l,l,mid);build(t[x].r,mid+1,r);
	add(x,t[x].l);add(x,t[x].r);
	return;
}
void change(int x,int l,int r,int L,int R,int p)
{
	if(L>R)return;
	if(l==L&&r==R)
	{
		add(p,x);return;
	}
	int mid=l+r>>1;
	if(mid>=R)change(t[x].l,l,mid,L,R,p);
	else if(L>mid)change(t[x].r,mid+1,r,L,R,p);
	else change(t[x].l,l,mid,L,mid,p),change(t[x].r,mid+1,r,mid+1,R,p);
	return;
}
void dfs(int x)
{
	dfn[x]=low[x]=++tmp;
	s[++top]=x;in[x]=1;
	for(int i=head[x];i;i=e[i].nex)
	{
		int y=e[i].to;
		if(!dfn[y])
		{
			dfs(y);
			low[x]=min(low[x],low[y]);
		}
		else if(in[y])low[x]=min(low[x],dfn[y]);
	}
	if(low[x]==dfn[x])
	{
		c++;int a=-1;
		do{
			a=s[top--];
			in[a]=0;
			col[a]=c;
		}while(a!=x);
	}
	return;
}
void init()
{
	memset(dfn,0,sizeof(dfn));
	memset(low,0,sizeof(low));
	memset(col,0,sizeof(col));
	tmp=c=0;
	return;
}
bool judge(int x)
{
	init();
	for(int i=1;i<=n*2;++i)head[i]=0;cnt=pre;
	for(int i=1;i<=n;++i)
	{
		int AL=lower_bound(a+1,a+1+2*n,(node){xx[i]-x+1,0})-a;
		int AR=upper_bound(a+1,a+1+2*n,(node){xx[i]+x-1,0})-a-1;
		if(AL<=AR)change(rt,1,n*2,AL,pos[i]-1,i),change(rt,1,n*2,pos[i]+1,AR,i);
		int BL=lower_bound(a+1,a+1+2*n,(node){yy[i]-x+1,0})-a;
		int BR=upper_bound(a+1,a+1+2*n,(node){yy[i]+x-1,0})-a-1;
		if(BL<=BR)change(rt,1,n*2,BL,pos[i+n]-1,i+n),change(rt,1,n*2,pos[i+n]+1,BR,i+n);
	}
	for(int i=1;i<=num;++i)
	if(!dfn[i])dfs(i);
	for(int i=1;i<=n;++i)
	if(col[i]==col[i+n])return 0;
	return 1;
}
int main()
{
	scanf("%d",&n);
	for(int i=1;i<=n;++i)
	{
		scanf("%d%d",&xx[i],&yy[i]);
		a[i*2-1].x=xx[i];a[i*2].x=yy[i];
		a[i*2-1].y=i;a[i*2].y=i+n;
	}num=n*2;
	sort(a+1,a+1+n*2);
	build(rt,1,n*2);
	int l=0,r=1e9;pre=cnt;
	while(l<=r)
	{
		int mid=l+r>>1;
		if(judge(mid))ans=mid,l=mid+1;
		else r=mid-1;
	}
	printf("%d\n",ans);
	return 0;
}

