std::vector<std::vector<int> > G;
int buildx(int l, int r)
{
	if (l == r)
		return idx[l]; // x 按 y 排序
	int mid = (l + r) >> 1;
	int node = mid + (n << 1);
	G[node].push_back(buildx(l, mid));
	G[node].push_back(buildx(mid + 1, r));
	return node;
}
int buildy(int l, int r)
{
	if (l == r)
		return l + n; // y 按 x 排序
	int mid = (l + r) >> 1;
	int node = mid + n * 3 - 1;
	G[node].push_back(buildy(l, mid));
	G[node].push_back(buildy(mid + 1, r));
	return node;
}
int g_Pos, g_L, g_R;
void linkx(int l, int r)
{
	int mid = (l + r) >> 1;
	if (g_L <= l && r <= g_R)
	{
		if (l == r) G[g_Pos].push_back(idx[l]);
		else G[g_Pos].push_back(mid + (n << 1));
		return;
	}
	if (g_L <= mid) linkx(l, mid);
	if (g_R > mid) linkx(mid + 1, r);
}
void linky(int l, int r)
{
	int mid = (l + r) >> 1;
	if (g_L <= l && r <= g_R)
	{
		if (l == r) G[g_Pos].push_back(l + n);
		else G[g_Pos].push_back(mid + n * 3 - 1);
		return;
	}
	if (g_L <= mid) linky(l, mid);
	if (g_R > mid) linky(mid + 1, r);
}
void linkx(int from, int l, int r)
{
	if (l > r) return;
	g_Pos = from;
	g_L = l;
	g_R = r;
