	REP(i,N){
		cin >> x[i*2] >> x[i*2+1];
		v.PB(pr(x[i*2],i*2));
		v.PB(pr(x[i*2+1],i*2+1));
	}
	sort(ALL(v));
	PQ qu;
	UnionFind uf(2*N);
	REP(i,N*2){
		qu.push(ppr(abs(v[0].first-v[i].first),pr(i,i+1)));
		qu.push(ppr(abs(v[N*2-1].first-v[i].first),pr(i,i-1)));
	}
	int nowd=INF;
	while(!qu.empty()){
		nowd=qu.top().first;
		int a=qu.top().second.first;
		int b=qu.top().second.second;
		qu.pop();
		if(min(a,b)==-1 or max(a,b)==N*2) continue;
		if(a>b) qu.push(ppr(abs(v[a].first-v[b-1].first),pr(a,b-1)));
		if(a<b) qu.push(ppr(abs(v[a].first-v[b+1].first),pr(a,b+1)));
		if(a^1==b) continue;

		uf.unite(v[a].second^1,v[b].second);
		uf.unite(v[a].second,v[b].second^1);
		if(uf.isFriend(v[a].second^1,v[a].second) or uf.isFriend(v[b].second^1,v[b].second)) break;

	}
	cout << nowd << endl;
	return 0;

}

