    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef pair<int,int> P;

#define fr first
#define sc second
#define rep(i,x) for(int i=0;i<x;i++)
#define pb push_back

const int N=20002;

int n,x[N],y[N];
vector<int> vs;
bitset<N> G[N],rG[N],al,nex,c,mask;
void dfs(int v){
	if(!al[v])return;
	al[v]=0;
	while(1){
		nex=al&G[v];
		int x=nex._Find_first();
		if(x==N)break;
		dfs(x);
	}
	vs.pb(v);
}
void scc(int v){
	if(!al[v])return;
	al[v]=0;
	while(1){
		nex=al&rG[v];
		int x=nex._Find_first();
		if(x==N)break;
		scc(x);
	}
	c[v]=1;
}
bool f(int d){
	vector<P> vec;
	rep(i,n){
		vec.pb(P(x[i],2*i));
		vec.pb(P(y[i],2*i+1));
	}
	sort(vec.begin(),vec.end());

	bitset<N> a,b;
	int l=0,r=0;
	for(P p: vec){
		while(r<2*n&&vec[r].fr<p.fr+d){
			a[vec[r].sc^1]=1;
			b[vec[r].sc]=1;
			r++;
		}
		while(l<2*n&&vec[l].fr<=p.fr-d){
			a[vec[l].sc^1]=0;
			b[vec[l].sc]=0;
			l++;
		}
		G[p.sc]=a;
		G[p.sc][p.sc^1]=0;
		rG[p.sc^1]=b;
		rG[p.sc^1][p.sc]=0;
	}

	vs.clear();
	al.set();
	rep(i,2*n){
		if(al[i])dfs(i);
	}
	reverse(vs.begin(),vs.end());
	al.set();
	for(int x: vs){
		c.reset();
		scc(x);
		c&=c<<1;
		c&=mask;
		if(c.any())return 0;
	}
	return 1;
}
int main(){
	rep(i,N)mask[i]=i&1;
	cin>>n;
	rep(i,n)cin>>x[i]>>y[i];
	int l=0,r=1e+9;
	while(l<r){
		int m=(l+r+1)/2;
		if(f(m))l=m;
		else r=m-1;
	}
	cout<<l<<endl;
}

