int low[N], dfs, cmp;
int comp[N];
bool vis[N];
vector<int> S;
int st;
bool DFS(int u) {
	low[u] = ++dfs;
	int idx = dfs;
	S.push_back(u);
	vis[u] = true;
	int v;
	for (int i = 0; i < g[u].size(); ++i) {
		v = g[u][i];
		if (low[v] <= st && !DFS(v))
			return false;
		if (vis[v])
			low[u] = min(low[u], low[v]);
	}
	if (idx == low[u]) {
		++cmp;
		while (true) {
			v = S.back();
			S.pop_back();
			vis[v] = false;
			comp[v] = cmp;
			if (comp[Not(v)] == cmp)
				return false;
			if (u == v)
				break;
		}
	}
	return true;
}
bool check(int d) {
	while (!S.empty()) {
		vis[S.back()] = false;
		S.pop_back();
	}
	g.clear();
	g.resize(n * 4);
	for (int i = 0; i < n; ++i)
		addEdge(i * 2, i * 2 + 1);
	for (int i = 0; i < n; ++i)
		for (int j = i + 1; j < n; ++j) {
			int cnt = 0;
			for (int a = 0; a < 2; ++a)
				for (int b = 0; b < 2; ++b)
					if (abs(p[a][i] - p[b][j]) < d) {
						addEdge(Not(i * 2 + a), Not(j * 2 + b));
						++cnt;
					}
			if (cnt == 4)
				return false;
		}
	++dfs;
	st = dfs;
	for (int i = 0; i < g.size(); ++i)
		if (low[i] <= st && !DFS(i))
			return false;
	return true;
}
