void ST_build(int u,int l,int r){
	if (l==r){
		addedge(u+2*n-1,id[a[l].id^1]);
		return;
	}
	int mid=(l+r)/2;
	ST_build(u*2,l,mid);
	ST_build(u*2+1,mid+1,r);
	addedge(u+2*n-1,u*2+2*n-1);
	addedge(u+2*n-1,u*2+1+2*n-1);
	return;
}

void ST_link(int u,int l,int r,int L,int R,int p){
	if (R<L){
		return;
	}
	if (L<=l && r<=R){
		addedge(p,u+n*2-1);
		return;
	}
	int mid=(l+r)/2;
	if (L<=mid){
		ST_link(u*2,l,mid,L,R,p);
	}
	if (R>mid){
		ST_link(u*2+1,mid+1,r,L,R,p);
	}
	return;
}

