using namespace std;
struct TwoSat {
    int n, nmark = 0; vector<vector<int> > adj;
    vector<int> preorderof, stack;
    vector<bool> instack; vector<int> result;
    TwoSat(int nvar): n(2*nvar), adj(n), preorderof(n, -1), instack(n, false), result(nvar, -1){}
    void add_or(int a, int b) { // 2 * a for "a" is true, 2*a+1 for "a" is false
        adj[a^1].push_back(b);
        adj[b^1].push_back(a);
    }
    bool solve(){ // result has size nvar = n / 2, result[i] == 1 means "i" is true
        for(int u = 0; u < n; ++u)
            if(preorderof[u] == -1) dfs(u);
        for(int u = 0; u < n;  ++u)
            for(int v : adj[u])
                if(result[u/2] == 1-(u&1) && result[v/2] != 1-(v&1))
                    return false;
        return true;
    }
    int dfs(int v){
        int reach = preorderof[v] = nmark++;
        stack.push_back(v); instack[v] = true;
        for(int u : adj[v])
            if(preorderof[u] == -1) reach = min(reach, dfs(u));
            else if(instack[u]) reach = min(reach, preorderof[u]);
        if(reach == preorderof[v]){
            int u;
            do{
                u = stack.back(); stack.pop_back();
                instack[u] = false;
                if(result[u/2] == -1) result[u/2] = 1 - (u & 1);
            } while(u != v);
        }
        return reach;
    }
};
