bool check(int d){
	int len = 2 * n;
	vector<int> ids(2 * len);
	int cnt = 0;
	for(int i = 0; i < len; i++) ids[i + len] = cnt++;
	for(int i = len - 1; i > 0; i--) ids[i] = cnt++;
	TwoSat s(cnt);
	auto connect = [&](int l, int r, int p){
		for(l += len, r += len + 1; l < r; l >>= 1, r >>= 1){
			if(l & 1){
				s.add_or(2 * ids[l] + 1, p);
				l++;
			}
			if(r & 1){
				r--;
				s.add_or(2 * ids[r] + 1, p);
			}
		}
	};
	int l = 0, r = 0;
	for(int i = 0; i < len; i++){
		while(l < i && all[i] - all[l] >= d) l++;
		while(r < len && all[r] - all[i] < d) r++;
		if(l < i){
			connect(l, i - 1, 2 * ids[i + len] + 1);
		}
		if(i < r - 1){
			connect(i + 1, r - 1, 2 * ids[i + len] + 1);
		}
	}
	for(int i = 0; i < n; i++){
		s.add_or(2 * ids[wh[0][i] + len] + 1, 2 * ids[wh[1][i] + len] + 1);
		s.add_or(2 * ids[wh[0][i] + len], 2 * ids[wh[1][i] + len]);
	}
	for(int i = len - 1; i > 0; i--){
		// -p ^ s
		s.add_or(2 * ids[i], 2 * ids[2 * i] + 1);
		s.add_or(2 * ids[i], 2 * ids[2 * i + 1] + 1);
	}
	return s.solve();
}
int main(){
	cin >> n;
	for(int i = 0; i < n; i++) cin >> x[i] >> y[i];
	vector<pair<int, int> > vals;
	for(int i = 0; i < n; i++){
		vals.push_back({x[i], i});
		vals.push_back({y[i], i});
	}
	vector<int> stk(n, 0);
	sort(vals.begin(), vals.end());
	for(int i = 0; i < 2 * n; i++){
		all[i] = vals[i].first;
		wh[stk[vals[i].second]++][vals[i].second] = i;
	}
	int lo = 0, hi = 1000000001, ans = 0;
	while(lo <= hi){
		int mid = (lo + hi)>>1;
		if(check(mid)) ans = mid, lo = mid + 1;
		else hi = mid - 1;
	}
	cout << ans << endl;
	return 0;
}

