void maketree(int a,int b,int nod){
	if(a==b){
		C[a]=nod;return;
	}
	int m = (a+b)/2;
	maketree(a,m,2*nod);
	maketree(m+1,b,2*nod+1);
	addEdge(2*nod+1,2*(2*nod)+1);
	addEdge(2*nod+1,2*(2*nod+1)+1);	
}

void gg(int a,int b,int nod,int l,int r,int p){
	if(b<l || a>r) return;
	if(l<=a && b<=r){
		addEdge(2*C[p],2*nod+1);
		return;
	}
	int m = (a+b)/2;
	gg(a,m,2*nod,l,r,p);
	gg(m+1,b,2*nod+1,l,r,p);
}

