bool Twosat(int n)
{
	memset(vis,false,sizeof(vis));
	for(int i=0;i<n;i+=2)
	{
		if(vis[i]||vis[i^1])continue;
		top=0;
		if(!dfs(i))
		{
			while(top)vis[S[--top]]=false;
			if(!dfs(i^1)) return false;
		}
	}
	return true;
}
bool judge(int now)
{
	init();
	for(int i=0;i<n;i++)
	{
		for(int j=i+1;j<n;j++)
		{
			int u,v;
			if(i==j)
			{
