template <typename T=int>
struct Segtree {
    int n; // leaf [n, 2n), view as original [0, n)
    int sz_v;
    vector<T> v; //tree

    TwoSat ts;

    int m;
    int d;
    vector<int> nop;

    Segtree(int _d): d(_d){
        n = a.size();
        sz_v = n<<1;
        m = n >> 1;
        v.resize(sz_v);
        nop.resize(n); // nop = I
        for (int i = 0; i < m; i++) {
            nop[i<<1] = ts.id(); // same effect as iota
            nop[i<<1|1] = nop[i<<1] ^ 1;
        }
        init();
        ts.init();
        build();
        make_exclude();
//dbg(a);
//dbg(nop);
//dbg(v);
dbg(ts.g.g);
    }
    void init() {// set leaf value
        for (int i = 0; i < n; i++) {
            v[i+n] = nop[a[i].second];
            v[i] = ts.id();
        }
    }
    void build() {
        for (int i = n-1; i > 0; i--) {
            //v[i] = ts.id();
            ts.imply(v[i], v[i<<1]);
            ts.imply(v[i], v[i<<1|1]);
        }
    }
    void make_exclude() {
        for (int i = 0; i < n; i++) {
            int x = a[i].first;
            int choose = a[i].second ^ 1;
            int j = lower_bound(a.begin(), a.end(), make_pair(x+d,-1)) - a.begin();
            update(i+1, j, choose);
            j = upper_bound(a.begin(), a.end(), make_pair(x-d,1<<30)) - a.begin(); // not -1
            update(j, i, choose);
        }
    }
    bool sat() {
        return ts.sat();
    }
    //inline void update(int p, T val) {
    //    assert(p>=0);
    //    for (v[p += n] = val; p >>= 1;) {
    //        v[p] = v[p<<1] + v[p<<1|1];
    //    }
    //}

    // Note only when range-assign, single-access not interfere. e.g max
    inline void update(int l, int r, int c) {
        for (l += n, r += n; l < r; l >>= 1, r >>= 1){
            //if (d==0) dbg(l,r,"into");
            if (l & 1) { ts.imply(c, v[l++]); }
            if (r & 1) { ts.imply(c, v[--r]); }
        }
    }
    //inline T query(int p){
    //    T res(ID);
    //    for (p += n; p > 0; p >>= 1) { res += v[p]; }
    //    return res;
    //}
};

