void build(int p, int l, int r) {
	tr[p] = ++ cnt; ++ cnt; 
	if (l == r) { add(tr[p], l<<1|1); return ; }
	int mid = (l + r) / 2;
	build(p << 1, l, mid), build((p << 1) + 1, mid + 1, r);
	add(tr[p], tr[p << 1]), add(tr[p], tr[(p << 1) + 1]);
}
void modify(int p, int l, int r, int lx, int rx, int fr) {
	if (l == lx && r == rx) { add(fr, tr[p]); return ; }
	int mid = (l + r) / 2;
	if (rx <= mid) modify(p << 1, l, mid, lx, rx, fr); else
	if (lx > mid) modify((p << 1) + 1, mid + 1, r, lx, rx, fr); else
	modify(p << 1, l, mid, lx, mid, fr), modify((p << 1) + 1, mid + 1, r, mid + 1, rx, fr);
}
void tarjan(int p) {
	dfn[p] = low[p] = ++ tot, vis[p] = false;
	st[++ top] = p, ins[p] = true;
	for (int i = lnk[p]; i; i = nxt[i]) {
		if (vis[ter[i]]) tarjan(ter[i]), low[p] = min(low[p], low[ter[i]]);
			else if (ins[ter[i]]) low[p] = min(low[p], dfn[ter[i]]);
	}
	if (low[p] == dfn[p]) {
		for ( ; st[top] != p; -- top) bel[st[top]] = p, ins[st[top]] = false;
		bel[st[top]] = p, ins[st[top]] = false, -- top;
	}
}
