void Add_Edge(int u, int v) { G[u].push_back(v); } 
#define lson (o << 1)
#define rson (o << 1 | 1) 
void build(int o, int l, int r) { 
	if (l == r) return (void)(id[o] = p[l].second); 
	id[o] = ++cnt; 
	int mid = (l + r) >> 1; 
	build(lson, l, mid), build(rson, mid + 1, r); 
	Add_Edge(id[o], id[lson]), Add_Edge(id[o], id[rson]); 
} 
void Link(int o, int l, int r, int ql, int qr, int x) { 
	if (ql <= l && r <= qr) return Add_Edge(x, id[o]); 
	int mid = (l + r) >> 1; 
	if (ql <= mid) Link(lson, l, mid, ql, qr, x); 
	if (qr > mid) Link(rson, mid + 1, r, ql, qr, x); 
} 
int low[MAX_N], dfn[MAX_N], stk[MAX_N], top; 
int col[MAX_N], scc, tim; 
void tarjan(int x) { 
	dfn[x] = low[x] = ++tim, stk[++top] = x; 
	for (auto v : G[x]) { 
		if (!dfn[v]) tarjan(v), low[x] = min(low[x], low[v]); 
		else if (!col[v]) low[x] = min(low[x], dfn[v]); 
	} 
	if (low[x] == dfn[x]) { 
		col[x] = ++scc; 
		while (stk[top] != x) col[stk[top--]] = scc; 
		--top; 
	} 
} 
bool check(int v) { 
	for (int i = 1; i <= N << 1; i++) G[i].clear(); 
	memset(low, 0, sizeof(low)); 
	memset(dfn, 0, sizeof(dfn)); 
	memset(col, 0, sizeof(col)); 
	scc = tim = top = 0; 
	cnt = N << 1; build(1, 1, N << 1); 
	for (int i = 1; i <= N; i++) 
		for (int op = 0; op < 2; op++) { 
			int l = lower_bound(&p[1], &p[N << 1 | 1], make_pair(X[i][op] - v + 1, 0)) - p; 
			int r = lower_bound(&p[1], &p[N << 1 | 1], make_pair(X[i][op] + v - 1, N << 1 | 1)) - p - 1; 
			int m = lower_bound(&p[1], &p[N << 1 | 1], make_pair(X[i][op], i + (op ^ 1) * N)) - p; 
			if (l <= m - 1) Link(1, 1, N << 1, l, m - 1, i + op * N); 
			if (m + 1 <= r) Link(1, 1, N << 1, m + 1, r, i + op * N); 
		} 
	for (int i = 1; i <= cnt; i++) if (!dfn[i]) tarjan(i); 
	for (int i = 1; i <= N; i++) if (col[i] == col[i + N]) return 0; 
	return 1; 
} 
