void dfs(int x) {
  bio[x] = low[x] = cnt++;
  st.push(x);
  on_stack[x] = 1;

  for (int y : ve[x]) {
    if (bio[y] == -1) {
      dfs(y);
      low[x] = min(low[x], low[y]); 
    } else if (on_stack[y]) {
      low[x] = min(low[x], bio[y]);
    }
  }

  if (low[x] == bio[x]) {
    while (st.size()) {
      int y = st.top();
      st.pop();
      on_stack[y] = 0;
      scc[y] = ind;
      if (y == x) break;
    }
    ind++;
  }

  return;
}

void tarjan(int N) {
  cnt = 1, ind = 0;
  memset(scc, -1, sizeof scc);
  memset(bio, -1, sizeof bio);

  REP(i, N) {
    if (bio[i] == -1) dfs(i);
  }

  return;
}

void connect(int a, int b, int k, int lo = 0, int hi = OFF, int x = 1) {
  if (b <= lo || hi <= a) return;
  if (a <= lo && hi <= b) {
    ve[k].push_back(x);
    return;
  }

  int mi = (lo + hi) / 2;
  connect(a, b, k, lo, mi, x * 2);
  connect(a, b, k, mi, hi, x * 2 + 1);

  return;
}

