    connect(l + 2 * n, i + 2 * n, i + OFF);
    connect(i + 1 + 2 * n, r + 2 * n, i + OFF);
  }

  REP(i, n) {
    int a = inde[2 * i];
    int b = inde[2 * i + 1];

    ve[a + OFF].push_back(b + 2 * n + OFF);
    ve[b + OFF].push_back(a + 2 * n + OFF);
    ve[b + 2 * n + OFF].push_back(a + OFF);
    ve[a + 2 * n + OFF].push_back(b + OFF);
