		next[++tot] = first[u], first[u] = tot, go[tot] = v;
}

void Tarjan(int u)
{
		Dfn[u] = Low[u] = ++Time_cnt;
		vis[u] = 1, stk[++top] = u;
		for(int e = first[u]; e; e = next[e])
		{
			int v = go[e];
			if(!Dfn[v])
			{
				Tarjan(v);
				Low[u] = min(Low[u], Low[v]);
			}
			else if(vis[v])
			Low[u] = min(Low[u], Dfn[v]);
		}

		int v;
		if(Low[u] == Dfn[u])
		{
			scc++;
			do
			{
				v = stk[top--];
				vis[v] = 0;
				F[v] = scc;
			}while(v != u);
		}
}

