int getedge(int at) {
	int l=lb[pos[at]],r=ub[pos[at]],a=pos[at],b=pos[other(at)];
	for(set<int>::iterator it=lft.lower_bound(l);it!=lft.end()&&*it<=r;++it) if(*it!=a&&*it!=b) return other(p[*it].idx);
	return -1;
}
int getredge(int at) {
	int l=lb[pos[other(at)]],r=ub[pos[other(at)]],a=pos[at],b=pos[other(at)];
	for(set<int>::iterator it=lft.lower_bound(l);it!=lft.end()&&*it<=r;++it) if(*it!=a&&*it!=b) return p[*it].idx;
	return -1;
}

void dfs1(int at,int dep=0) {
	been[at]=true; lft.erase(pos[other(at)]);
	//REP(i,dep) printf(" "); printf("dfs1(%d%c)\n",at%n+1,at<n?'A':'B');
	while(true) {
		int to=getedge(at);
		if(to==-1) break;
		dfs1(to,dep+1);
	}
	lst[nlst++]=at;
}
void dfs2(int at,int c,int dep=0) {
	comp[at]=c; lft.erase(pos[at]);
	//REP(i,dep) printf(" "); printf("dfs2(%d%c,%d)\n",at%n+1,at<n?'A':'B',c);
	while(true) {
		int to=getredge(at);
		if(to==-1) break;
		dfs2(to,c,dep+1);
	}
}

bool ok(int D) {
	REP(i,2*n) { int l=-1,h=2*n; while(l+1<h) { int m=l+(h-l)/2; if(p[m].x>p[i].x-D) h=m; else l=m; } lb[i]=h; } //p[?].x>p[i].x-D
	REP(i,2*n) { int l=-1,h=2*n; while(l+1<h) { int m=l+(h-l)/2; if(p[m].x<p[i].x+D) l=m; else h=m; } ub[i]=l; } //p[?].x<p[i].x+D
	//REP(i,2*n) printf("%d=%d (%d%c): %d..%d\n",i,p[i].x,p[i].idx%n+1,p[i].idx<n?'A':'B',lb[i],ub[i]);

	REP(i,2*n) been[i]=false,comp[i]=-1; nlst=ncomp=0;
	lft.clear(); REP(i,2*n) lft.insert(i);
	REP(i,2*n) if(!been[i]) dfs1(i);
	reverse(lst,lst+nlst);
	lft.clear(); REP(i,2*n) lft.insert(i);
	REP(i,2*n) if(comp[lst[i]]==-1) dfs2(lst[i],ncomp++);
	REP(i,n) if(comp[i]==comp[i+n]) return false;
	return true;
}

int solve() {
	REP(i,n) p[i].x=a[i],p[i].idx=i,p[i+n].x=b[i],p[i+n].idx=i+n; sort(p,p+2*n);
	REP(i,2*n) pos[p[i].idx]=i;

	//int tst=4; printf("ok(%d)=%d\n",tst,ok(tst)?1:0); exit(0);
	int l=0,h=1000000001;
	while(l+1<h) {
		int m=l+(h-l)/2;
		if(ok(m)) l=m; else h=m;
	}
	return l;
}

void run() {
	scanf("%d",&n); REP(i,n) scanf("%d%d",&a[i],&b[i]);
	printf("%d\n",solve());
}

int main() {
	run();
	return 0;
}

