Graph reverse_graph(const Graph &G){
  Graph revG(G.size());
  REP(i,G.size()){
    REP(j,G[i].size()){
      const Edge &e=G[i][j];
      revG[e.dst].push_back(Edge(e.dst,e.src));
    }
  }
  return revG;
}
// 強連結成分分解
void dfs(const Graph &G, vector<bool> &visit, vector<int> &order, int v){
  visit[v] = true;
  REP(i, G[v].size()){
    int dst = G[v][i].dst;
    if(!visit[dst])dfs(G, visit, order, dst);
  }
  order.push_back(v);
}

void rdfs(const Graph &G, vector<bool> &visit, vector<int> &comp, int v, int k){
  visit[v] = true;
  REP(i, G[v].size()){
    int dst = G[v][i].dst;
    if(!visit[dst])rdfs(G, visit, comp, dst, k);
  }
  comp[v] = k;
}
void add_edge(Graph &G, int src, int dst) {
  G[src].push_back(Edge(src, dst));
}
int scc(const Graph &G, vector<int> &comp){
  Graph revG = reverse_graph(G);
  comp = vector<int>(G.size());
  vector<bool> visit(G.size());
  vector<int> order;
  int k = 0;
  REP(i, G.size()) if(!visit[i])dfs(G, visit, order, i);
  reverse(order.begin(), order.end()); // トポロジカル順序を求める

  visit = vector<bool>(G.size());
  REP(i, order.size()){
    if(!visit[order[i]])rdfs(revG, visit, comp, order[i], k++);
  }
  return k;
}


