	tt++;
	b[tt]=y;
	nxt[tt]=fst[x];
	fst[x]=tt;
}
void tarjan(int x)
{
	sta[++st]=x;
	pd[x]=1;
	low[x]=dfn[x]=++td;
	for(int p=fst[x];p;p=nxt[p])
	{
		if (pd[b[p]]==2) continue;
		if (!pd[b[p]])
		{
			tarjan(b[p]);
			cmin(low[x],low[b[p]]);
		}else
			cmin(low[x],dfn[b[p]]);
	}
	if (dfn[x]==low[x])
	{
		tb++;
		while (sta[st+1]!=x)
		{
			pd[sta[st]]=2;
			bel[sta[st]]=tb;
			st--;
		}
	}
}
void clear()
{
	fo(i,1,n*2) sta[i]=pd[i]=fst[i]=bel[i]=low[i]=dfn[i]=0;
	td=tb=tt=0;
}
int judge(int mid)
{
	clear();
	fo(i,1,n*2-1)
		fo(j,i+1,n*2)
		{
			if (a[j].x-a[i].x>=mid) 
			{
				if (mid==25) printf("%d\n",j-1);
				break;
			}
			if (ref[a[i].y]==a[j].y) continue;
			cr(a[i].y,ref[a[j].y]);
			cr(a[j].y,ref[a[i].y]);
		}
	fo(i,1,n*2) if (!pd[i])
		tarjan(i);
	fo(i,1,n) if (bel[i*2-1]==bel[i*2]) return 0;
	// process 2
	return 1;
}
int main()
{
	scanf("%d",&n);
	l=0;
	fo(i,1,n) 
	{
		scanf("%d %d",&x,&y);
		a[++ta].x=x;
		a[ta].y=ta;
		ref[ta]=ta+1;
		a[++ta].x=y;
		a[ta].y=ta;
		ref[ta]=ta-1;
		cmax(r,max(x,y));
	}
	sort(a+1,a+1+ta,cmp);
	r/=n-1;
	while (l<r)
	{
		mid=(l+r+1)/2;
		if (judge(mid)) l=mid;
		else r=mid-1;
	}
	printf("%d\n",l);
}

