// d 以上の間隔で旗を立てられるなら true
bool check(int d) {
    two_sat ts(N);
    // X を選択 := true
    // Y を選択 := false 
    REP(i, N) {
        for(int j = i + 1; j < N; ++j) {
            if(abs(X[i] - X[j]) < d) {
                // この 2 つは同時に立てられない
                // -> どちらかは false にならなければいけない
                ts.add_clause(i, false, j, false);
            }
            if(abs(X[i] - Y[j]) < d) {
                ts.add_clause(i, false, j, true);
            }
            if(abs(Y[i] - X[j]) < d) {
                ts.add_clause(i, true, j, false);
            }
            if(abs(Y[i] - Y[j]) < d) {
                ts.add_clause(i, true, j, true);
            }
        }
    }
    return ts.satisfiable();
}

