		if(!visit[!y][j]) q.push(P(!y,j));
	    }
	  }
	}
	if(fff){
	  ff=1;
	  for(ll j=0;j<n;j++) used[j]|=visit[0][j]||visit[1][j];
	  break;
	}
      }
      f&=ff;
    }
    //cout<<m<<endl;
    if(f) l=m;
    else r=m;
  }
