void dfs(int cvor, int vel)
{
    while(1)
    {
        it = kopija.lower_bound(mp(vel - mid + 1, -1));
        if (it != kopija.end() && (*it).sec == cvor) it++;
        if (it == kopija.end() || (*it).fir >= vel + mid) break;
        int nextcvor = (*it).sec, nextvel = (*it).fir;
        kopija.erase(it);
        int novicvor = (nextcvor % 2) ? nextcvor - 1 : nextcvor + 1;
        dfs(novicvor, velicina [novicvor]);
    }
    stog.push(cvor);
    return;
}

void dfs2(int cvor)
{
    komp [cvor] = brojac;
    int drugi = (cvor % 2) ? cvor - 1 : cvor + 1;
    int drugivel = velicina [drugi];
    it = kopija.lower_bound(mp(drugivel - mid + 1, -1));
    if (it != kopija.end())
    {
        if ((*it).sec == drugi) it++;
        if (it == kopija.end()) return;
        if ((*it).fir < drugivel + mid)
