int LB(segment* &rt,int x,int s,int t)
{
	if(s>t) return 0;
	int l=rt->l,r=rt->r,mid=(l+r)>>1;
	if(s<=l&&r<=t) return add_edge(x,rt->id);
	if(s<=mid) LB(rt->ch[0],x,s,t);
	if(mid<t) LB(rt->ch[1],x,s,t);
	return 0;
}
