		f[x]=min(f[x],f[e[p].x]);
	}
	else
		if (pd[e[p].x])f[x]=min(f[x],dfn[e[p].x]);
	if (dfn[x]==f[x]){
		t++;
		for(;sta[top+1]!=x;top--){
