struct SCC{
  int n, k;
  mi G, rG;
  vi vs, cmp;
  vb used;
  void init( int size ){
    n = size;
    G = rG = mi( n , vi(0) );
    cmp = vi( n );
    vs.clear();
  }
  void add_edge( int a , int b ){
    G[a].pb( b );
    rG[b].pb( a );
  }
  void dfs( int x ){
    used[x] = true;
    YYS( w , G[x] ) if( !used[w] ) dfs( w );
    vs.pb( x );
  }
  void rdfs( int x ){
    used[x] = true;
    cmp[x] = k;
    YYS( w , rG[x] ) if( !used[w] ) rdfs( w );
  }
  int scc(){
    used = vb( n , false );
    REP( i , n ) if( !used[i] ) dfs( i );
    REVERSE( vs );
    k = 0;
    used = vb( n , false );
    YYS( w , vs ) if( !used[w] ) rdfs( w ), k++;
    return k;
  }
};


