template<typename T>
struct SCC{
    int n,now=0;
    const vector<vector<T>>& e;
    vector<bool> used;
    vector<int> ind,low,ord,st;//low:圧縮後の頂点番号になる ord:到達順 st:連結成分復元に使うstack
    vector<vector<int>> grps,G;

    void dfs(int v){
        low[v]=now;
        ord[v]=now;
        now++;
        st.push_back(v);
        used[v]=true;
        for(auto i:e[v]){
            if(ord[i]==-1){
                dfs(i);
                low[v]=min(low[v],low[i]);
            }else if(used[i]){//ループなどで到達済みに回ってきた場合
                low[v]=min(low[v],ord[i]);//iが既に到達した場所ならその頂点番号で更新して,戻っていく
            }
        }

        if(low[v]==ord[v]){//戻ってきた==強連結成分発見
            vector<int> gr;
            while(1){
                int u=st.back();st.pop_back();
                gr.push_back(u);
                if(u==v)break;
            }//帰りがけ順に強連結成分をgrに入れる
            for(int i:gr)used[i]=false;//?
            grps.push_back(gr);//強連結成分を入れる
        }
    }

    SCC(const vector<vector<T>>& _e):n(_e.size()),e(_e),used(n,false),low(n),ord(n,-1){
        ind=vector<int>(n,0);//
        for(int i=0;i<n;i++){
            if(ord[i]==-1)dfs(i);//順序未決定==未到達
        }
        reverse(grps.begin(),grps.end());
        for(int i=0;i<(int)grps.size();i++){
            for(auto&& x:grps[i]){
                ind[x]=i;
            }
        }//頂点圧縮

        /*G.resize(grps.size());
        for(int i=0;i<n;i++){
            for(int j=0;j<(int)e[i].size();j++){
                if(ind[i]!=ind[e[i][j]]){
                    G[ind[i]].push_back(ind[e[i][j]]);
                }
            }
        }*/
    }

    vector<vector<int>>& get_scc(){
      return G;
    }
};
//indがSCC後の頂点番号,grpが同成分の頂点をまとめたリストになっている

struct TwoSat{
  vector<vector<int>> e;
  vector<bool> res;

  //((a==aflag) || (b==bflag))
  //2*i+0==not(i)  2i+1 == (i)
  void add_edge(int a,bool aflag,int b,bool bflag){
    e[2*a+!aflag].push_back(2*b+bflag);
    e[2*b+!bflag].push_back(2*a+aflag);
  }

  bool judge(){
    SCC<int> scc(e);
    for(int i=0;i<(int)res.size();++i){
      if(scc.ind[2*i]==scc.ind[2*i+1]){
        return false;
      }
      res[i]=(scc.ind[2*i]<scc.ind[2*i+1]);
      //trueが後ろ→iは成立
    }
    return true;
  }
  TwoSat(int n){
    e=vector<vector<int>>(2*n);
    res=vector<bool>(n);
  }
};

signed main(){
  cin.tie(0);ios::sync_with_stdio(false);
  cout<<fixed<<setprecision(20);
  int n;cin>>n;
  VV<ll> v(n,V<ll>(2));
  rep(i,0,n)cin>>v[i][0]>>v[i][1];

  ll ok=0,ng=mod,mid;
  while(abs(ok-ng)>1){
    mid=(ok+ng)/2;
    TwoSat ts(n);
    rep(i,0,n){
      ts.add_edge(i,true,i,false);
      rep(j,i+1,n){
        if(abs(v[i][0]-v[j][0])<mid)ts.add_edge(i,false,j,false);
        if(abs(v[i][0]-v[j][1])<mid)ts.add_edge(i,false,j,true);
        if(abs(v[i][1]-v[j][0])<mid)ts.add_edge(i,true,j,false);
        if(abs(v[i][1]-v[j][1])<mid)ts.add_edge(i,true,j,true);
      }
    }
    if(ts.judge()){
      ok=mid;
    }else{
      ng=mid;
    }
  }
  cout<<ok<<ENDL;
}
