vector<int> stk;
int scc_idx[MAXN], scc_cnt;
int gn, n;
int perm[MAXN];

bool dfs(int nod) {
	up[nod] = visit[nod] = ++vtime;
	stk.push_back(nod);
	for (int next : graph[nod]) {
		if (visit[next] == 0) {
			if (dfs(next) == false) return false;
			up[nod] = min(up[nod], up[next]);
		}
		else if (scc_idx[next] == 0)
			up[nod] = min(up[nod], visit[next]);
	}
	if (up[nod] == visit[nod]) {
		++scc_cnt;
		int t;
		do {
			t = stk.back();
			stk.pop_back();
			scc_idx[t] = scc_cnt;
			if (t < n)
			{
				if (scc_idx[t + n] == scc_idx[t]) return false;
			}
			else
			{
				if (scc_idx[t - n] == scc_idx[t]) return false;
			}
		} while (!stk.empty() && t != nod);
	}

	return true;
}
// find SCCs in given directed graph
// O(V+E)
bool get_scc() {
	vtime = 0;
	memset(visit, 0, sizeof(visit));
	scc_cnt = 0;
	memset(scc_idx, 0, sizeof(scc_idx));
	for (int i = 0; i < 500; ++i)
		if (visit[perm[i]] == 0 && dfs(perm[i]) == false) return false;
	return true;
}

