			}

			if (abs(y[i] - y[j]) < t)
			{
				cnt++;
				graph[i + n].push_back(j);
				graph[j + n].push_back(i);
			}

			if (cnt == 4) return false;
			gt += cnt * 4;
		}
	}
	else
	{
		for (int i = 0; i < n; i++) for (int j = i + 1; j < max(n, i + 1000); j++)
