	void init(int m)
	{
		n=m;
		for(int i=0; i<2*n; i++)
		{
			g[i].clear();
		}
		memset(vis,0,sizeof(vis));
	}

	void add(int x,int y)
	{
		g[x^1].push_back(y);
		g[y^1].push_back(x);
	}

	bool dfs(int u)
	{
		if(vis[u^1])
		{
			return 0;
		}
		if(vis[u])
		{
			return 1;
		}
		vis[u]=1;
		s[cnt++]=u;
		int sz=g[u].size();
		for(int i=0; i<sz; i++)
		{
			if(!dfs(g[u][i]))
			{
				return 0;
			}
		}
		return 1;
	}

	bool solve()
	{
		for(int i=0; i<2*n; i+=2)
		{
			if(!vis[i]&&!vis[i^1])
			{
				cnt=0;
				if(!dfs(i))
				{
					while(cnt>0)
					{
						vis[s[--cnt]]=0;
					}
					if(!dfs(i^1))
					{
						return 0;
					}
				}
			}
		}
		return 1;
	}	
