// --- BEGIN SNIPPET MAX FLOW PUSH RELABEL ---

struct MaxFlow {
  struct Edge {
    lli from, to, cap, flow, index;
    Edge(lli from, lli to, lli cap, lli flow, lli index) :
      from(from), to(to), cap(cap), flow(flow), index(index) {}
  };

  lli N;
  vector<vector<Edge> > G;
  vector<lli> excess;
  vector<lli> dist, active, count;
  queue<lli> Q;

  MaxFlow(lli N = 0) : N(N), G(N), excess(N), dist(N), active(N), count(2*N) { }

  lli addNode() {
    N += 1;
    G.eb(); excess.eb(); dist.eb(); active.eb(); count.eb(); count.eb();
    return N-1;
  }

  void addEdge(lli from, lli to, lli cap) {
    G[from].push_back(Edge(from, to, cap, 0, G[to].size()));
    if (from == to) G[from].back().index++;
    G[to].push_back(Edge(to, from, 0, 0, G[from].size() - 1));
  }

  void enqueue(lli v) {
    if (!active[v] && excess[v] > 0) { active[v] = true; Q.push(v); }
  }

  void push(Edge &e) {
    lli amt = min(excess[e.from], e.cap - e.flow);
    if(dist[e.from] <= dist[e.to] || amt == 0) return;
    e.flow += amt;
    G[e.to][e.index].flow -= amt;
    excess[e.to] += amt;
    excess[e.from] -= amt;
    enqueue(e.to);
  }

  void gap(lli k) {
    FOR(v, N) {
      if(dist[v] < k) continue;
      count[dist[v]]--;
      dist[v] = max(dist[v], N+1);
      count[dist[v]]++;
      enqueue(v);
    }
  }

  void relabel(lli v) {
    count[dist[v]]--;
    dist[v] = 2*N;
    for(Edge& e : G[v]) if(e.cap - e.flow > 0) {
        dist[v] = min(dist[v], dist[e.to] + 1);
      }
    count[dist[v]]++;
    enqueue(v);
  }

  void discharge(lli v) {
    for(lli i = 0; excess[v] > 0 && i < (lli)G[v].size(); ++i) push(G[v][i]);
    if(excess[v] > 0) {
      if(count[dist[v]] == 1) {
        gap(dist[v]);
      } else {
        relabel(v);
      }
    }
  }

  lli flow(lli s, lli t) {
    count[0] = N-1;
    count[N] = 1;
    dist[s] = N;
    active[s] = active[t] = true;
    for(Edge& e : G[s]) {
      excess[s] += e.cap;
      push(e);
    }
    while (!Q.empty()) {
      lli v = Q.front();
      Q.pop();
      active[v] = false;
      discharge(v);
    }
    lli totflow = 0;
    for(Edge& e : G[s]) totflow += e.flow;
    return totflow;
  }
};

// --- END SNIPPET MAX FLOW PUSH RELABEL ---


