	if (v >= 4 * n) {
		LF = (v - 4 * n + 1) * 2 + 4 * n - 1;
	}
	int RG = v * 2 + 1;
	if (v >= 4 * n) {
		RG = (v - 4 * n + 1) * 2 + 4 * n;
	}
	g[v].pb(LF);
	gr[LF].pb(v);
	if (tl == tm) {
		vertex[tl] = LF;
	} else {
		buildST(LF, tl, tm, vertex);
	}
	g[v].pb(RG);
	gr[RG].pb(v);
	if (tm + 1 == tr) {
		vertex[tr] = RG;
	} else {
		buildST(RG, tm + 1, tr, vertex);
	}
}

void getX(vector<data>& v, ll a, ll b, int& l, int& r)
{
	if (a > b) {
		l = -1, r = -1;
		return;
	}
	int lf = -1, rg = n - 1;
	while (rg - lf > 1) {
		int md = (lf + rg) >> 1;
		if (v[md].x >= a) {
			rg = md;
		} else {
			lf = md;
		}
	}
	l = rg;
	lf = 0, rg = n;
	while (rg - lf > 1) {
		int md = (lf + rg) >> 1;
		if (v[md].x <= b) {
			lf = md;
		} else {
			rg = md;
		}
	}
	r = lf;
}

void getY(vector<data>& v, ll a, ll b, int& l, int& r)
{
	if (a > b) {
		l = -1, r = -1;
		return;
	}
	int lf = -1, rg = n - 1;
	while (rg - lf > 1) {
		int md = (lf + rg) >> 1;
		if (v[md].y >= a) {
			rg = md;
		} else {
			lf = md;
		}
	}
	l = rg;
	lf = 0, rg = n;
	while (rg - lf > 1) {
		int md = (lf + rg) >> 1;
		if (v[md].y <= b) {
			lf = md;
		} else {
			rg = md;
		}
	}
	r = lf;
}

void makeEdges(int u, int v, int tl, int tr, int l, int r)
{
	if (tl == l && tr == r) {
		g[u].pb(v);
		gr[v].pb(u);
		return;
	}
	int LF = v * 2;
	if (v >= 4 * n) {
		LF = (v - 4 * n + 1) * 2 + 4 * n - 1;
	}
	int RG = v * 2 + 1;
	if (v >= 4 * n) {
		RG = (v - 4 * n + 1) * 2 + 4 * n;
	}
	int tm = (tl + tr) >> 1;
	if (l <= tm) {
		makeEdges(u, LF, tl, tm, l, min(r, tm));
	}
	if (r > tm) {
		makeEdges(u, RG, tm + 1, tr, max(l, tm + 1), r);
	}
}

