namespace Graph
{
	int head[N], cnte, tim, top, scc, instk[N], stk[N]; 
	struct edge { int to, nxt; } e[N << 1]; 
	inline void adde(int u, int v) { e[++cnte] = (edge) { v, head[u] }, head[u] = cnte; }
	void tarjan(int u)
	{
		dfn[u] = low[u] = ++tim, instk[stk[++top] = u] = 1; 
		for(int v, i = head[u]; i; i = e[i].nxt)
		{
			v = e[i].to; 
			if(!dfn[v]) tarjan(v), low[u] = min(low[u], low[v]); 
			else if(instk[v]) low[u] = min(low[u], dfn[v]); 
		}
		if(low[u] >= dfn[u])
		{
			int x; scc++; 
			do { x = stk[top--], instk[x] = 0, bl[x] = scc; } while(x != u); 
		}
	}
	void clear()
	{
		for(int i = 1; i <= cnt; i++) dfn[i] = low[i] = bl[i] = head[i] = 0; 
		scc = tim = top = 0; 
	}
};
int op(int x) { return x >= n ? x - n : x + n; }
struct SegTree
{
	struct Tree { int l, r; } t[N << 2]; 
	void clear() { for(int i = 1; i <= cnt; i++) t[i].l = t[i].r = 0; }
	void build(int &o, int l, int r)
		{
			if(!o) o = ++cnt;
			if(l == r) return Graph :: adde(o, op(p[l].id)); 
			int mid = (l + r) >> 1; 
			build(t[o].l, l, mid), build(t[o].r, mid + 1, r); 
			Graph :: adde(o, t[o].l), Graph :: adde(o, t[o].r); 
		}
	void add(int p, int l, int r, int ql, int qr, int x)
		{
			if(ql <= l && r <= qr) return Graph :: adde(x, p); 
			int mid = (l + r) >> 1;
			if(ql <= mid) add(t[p].l, l, mid, ql, qr, x); 
			if(mid < qr) add(t[p].r, mid + 1, r, ql, qr, x); 
		}
} T; 

