	return it==lft.end()||*it>r?-1:*it;
}
int getedge(int at) {
	int l=lb[pos[at]],r=ub[pos[at]],a=pos[at],b=pos[other(at)]; if(a>b) swap(a,b);
	int ret=-1;
	if(ret==-1&&l<=a&&a<=r) ret=getedge(l,a-1);
	if(ret==-1&&l<=a&&b<=r) ret=getedge(a+1,b-1);
	if(ret==-1&&l<=b&&b<=r) ret=getedge(b+1,r);
	if(ret==-1&&a<l&&l<=b&&b<=r) ret=getedge(l,b-1);
	if(ret==-1&&b>r&&l<=a&&a<=r) ret=getedge(a+1,r);
	if(ret==-1&&(a<l||a>r)&&(b<l||b>r)) ret=getedge(l,r);
	return ret==-1?-1:other(p[ret].idx);
}
void update(int &ret,int l,int r) {
	if(l<=r) ret=min(ret,sget(l,r));
}
void update(int &ret,int at) {
	int l=lb[pos[at]],r=ub[pos[at]],a=pos[at],b=pos[other(at)]; if(a>b) swap(a,b);
	if(l<=a&&a<=r) update(ret,l,a-1);
	if(l<=a&&b<=r) update(ret,a+1,b-1);
	if(l<=b&&b<=r) update(ret,b+1,r);
	if(a<l&&l<=b&&b<=r) update(ret,l,b-1);
	if(b>r&&l<=a&&a<=r) update(ret,a+1,r);
	if((a<l||a>r)&&(b<l||b>r)) update(ret,l,r);
}

void tarjan(int at,int dep=0) {
	key[at]=minkey[at]=nkey++; stck[nstck++]=at; sset(pos[other(at)],key[at]); lft.erase(pos[other(at)]);
	//REP(i,dep) printf(" "); printf("tarjan(%d%c)\n",at%n+1,at<n?'A':'B');
	while(true) {
		int to=getedge(at);
		if(to==-1) break;
		tarjan(to,dep+1);
		if(minkey[to]<minkey[at]) minkey[at]=minkey[to];
	}
	update(minkey[at],at);
	if(minkey[at]==key[at]) {
		while(comp[at]==-1) { int to=stck[--nstck]; sset(pos[other(to)],INT_MAX); comp[to]=ncomp; } ++ncomp;
	}
}

bool ok(int D) {
	REP(i,2*n) { int l=-1,h=2*n; while(l+1<h) { int m=l+(h-l)/2; if(p[m].x>p[i].x-D) h=m; else l=m; } lb[i]=h; } //p[?].x>p[i].x-D
	REP(i,2*n) { int l=-1,h=2*n; while(l+1<h) { int m=l+(h-l)/2; if(p[m].x<p[i].x+D) l=m; else h=m; } ub[i]=l; } //p[?].x<p[i].x+D
	//REP(i,2*n) printf("%d=%d: %d..%d\n",i,p[i].x,lb[i],ub[i]);

	sinit();
	lft.clear(); REP(i,2*n) lft.insert(i);
	REP(i,2*n) key[i]=comp[i]=-1; nkey=ncomp=nstck=0;
	REP(i,2*n) if(key[i]==-1) tarjan(i);
	REP(i,n) if(comp[i]==comp[i+n]) return false;
	return true;
}

int solve() {
	REP(i,n) p[i].x=a[i],p[i].idx=i,p[i+n].x=b[i],p[i+n].idx=i+n; sort(p,p+2*n);
	REP(i,2*n) pos[p[i].idx]=i;

	//int tst=4; printf("ok(%d)=%d\n",tst,ok(tst)?1:0); exit(0);
	int l=0,h=1000000001;
	while(l+1<h) {
		int m=l+(h-l)/2;
		if(ok(m)) l=m; else h=m;
	}
	return l;
}

void run() {
	scanf("%d",&n); REP(i,n) scanf("%d%d",&a[i],&b[i]);
	printf("%d\n",solve());
}

int main() {
	run();
	return 0;
}

