#define REP(i,x) for(int i = 0; i < (int)x; i++) 
typedef int Weight;
const Weight INF=99999999;
struct Edge{
  int src,dst;
  Edge(int f, int t):src(f),dst(t){}
};
struct Node:public vector<Edge>{};
typedef vector<Node> Graph;

int N;
