// 逆辺グラフの構成
Graph reverse_graph(const Graph &G){
  Graph revG(G.size());
  REP(i,G.size()){
    REP(j,G[i].size()){
      const Edge &e=G[i][j];
      revG[e.dst].push_back(Edge(e.dst,e.src));
    }
  }
  return revG;
}
// 強連結成分分解
void dfs(const Graph &G, vector<bool> &visit, vector<int> &order, int v){
  visit[v] = true;
  REP(i, G[v].size()){
    int dst = G[v][i].dst;
    if(!visit[dst])dfs(G, visit, order, dst);
  }
  order.push_back(v);
}

void rdfs(const Graph &G, vector<bool> &visit, vector<int> &comp, int v, int k){
  visit[v] = true;
  REP(i, G[v].size()){
    int dst = G[v][i].dst;
    if(!visit[dst])rdfs(G, visit, comp, dst, k);
  }
  comp[v] = k;
}
void add_edge(Graph &G, int src, int dst) {
  G[src].push_back(Edge(src, dst));
}
int scc(const Graph &G, vector<int> &comp){
  Graph revG = reverse_graph(G);
  comp = vector<int>(G.size());
  vector<bool> visit(G.size());
  vector<int> order;
  int k = 0;
  REP(i, G.size()) if(!visit[i])dfs(G, visit, order, i);
  reverse(order.begin(), order.end()); // トポロジカル順序を求める

  visit = vector<bool>(G.size());
  REP(i, order.size()){
    if(!visit[order[i]])rdfs(revG, visit, comp, order[i], k++);
  }
  return k;
}


int X(int t) {
  return t;
}
int NOTX(int t) {
  return t + N;
}

int Y(int t) {
  return t + 2 * N;
}
int NOTY(int t) {
  return t + 3 * N;
}
int check(int d) {
  Graph G(N * 4);
  int edges = 0;
  for(int i = 0; i < N; i++) {
    for(int j = 0; j < i; j++) {
      int cnt = 0;
      if(abs(x[i] - y[j]) < d) {
        add_edge(G, X(i), NOTY(j));
        add_edge(G, Y(j), NOTX(i));
        cnt++;
      }
      if(abs(x[i] - x[j]) < d) {
        add_edge(G, X(i), NOTX(j));
        add_edge(G, X(j), NOTX(i));
        cnt++;
      }
      if(abs(y[i] - x[j]) < d) {
        add_edge(G, Y(i), NOTX(j));
        add_edge(G, X(j), NOTY(i));
        cnt++;
      }
      if(abs(y[i] - y[j]) < d) {
        add_edge(G, Y(i), NOTY(j));
        add_edge(G, Y(j), NOTY(i));
        cnt++;
      }
      if(cnt == 4) return false;
      edges += cnt;
    }
    if(edges > 10000 * 1000) return true;
  }
  for(int i = 0; i < N; i++) {
    // x[i]またはy[i]
    add_edge(G, NOTX(i), Y(i));
    add_edge(G, NOTY(i), X(i));
  }
  vector<int> comp;
  scc(G, comp);
  for(int i = 0; i < N; i++) {
    if(comp[i] == comp[i + N]) return false;
    if(comp[i + 2 * N] == comp[i + 3 * N]) return false;
  }
  return true;
}
