  int low = 0, high = 1000000002 / (N - 1) + 5;
  while(low + 1 < high) {
    int mid = (low + high) / 2;
    if(check(mid)) {
      low = mid;
    } else {
      high = mid;
    }
  }
  cout << low << endl;
}

