void dfs1(int q){
	visited[q] = 1;
	for(vector<int>::iterator it = path[q].begin() ; it != path[q].end() ; ++it){
		if(!visited[*it]) dfs1(*it);
		invpath[*it].push_back(q);
	}
	sta.push(q);
}

void dfs2(int q){
	visited[q] =1;
	SCC_ind[q] = SCC_num;
	for(vector<int>::iterator it = invpath[q].begin() ; it != invpath[q].end() ; ++it){
		if(!visited[*it]) dfs2(*it);
	}
}

void SCC(int n){
	fill(visited,visited+n,0);
	for(int i = 0 ; i < n ; ++i){
		if(!visited[i]) dfs1(i);
	}
	fill(visited,visited+n,0);
	SCC_num = 0;
	while(!sta.empty()){
		if(!visited[sta.top()]){
			dfs2(sta.top());
			++SCC_num;
		}
		sta.pop();
	}
}

