	}
	repp(i,2,CM*2){
		path[i*2].PB(i/2*2);
		path[i/2*2+1].PB(i*2+1);
	}
}

void put(int a , int b , int e , int s , int f , int q){
	if(e <= s || f <= b) return;
	if(s <= b && e <= f){
		path[q*2].PB(a*2+1);
		path[a*2].PB(q*2+1);
	} else {
		put(a*2,b,(b+e)/2,s,f,q);
		put(a*2+1,(b+e)/2,e,s,f,q);
	}
}

