//[L,R)にfromから辺を張る に相当する
void add_edge(int L,int R,int from,vector<vector<int>>& edge){
    for(int l=L+leaf_cnt, r=R+leaf_cnt; l<r; l>>=1, r>>=1){
        if(l&1) edge[from].emplace_back(l++);
        if(r&1) edge[from].emplace_back(--r);
    }
}

