struct SCC {
	vector<vector<edge>> g;
	ll N;
	ll M;

	vector<vector<edge>> graph;//分解してできるグラフ
	vll ver;//元のグラフとの頂点の対応
	vll ed;//辺の対応(同じ成分に入る場合は、-頂点番号)

	vll kaeri;

	void dfs(ll v) {
		ver[v] = -1;
		for (edge e : g[v]) {
			ll w = e.to;
			if (ver[w] == -1) { continue; }
			dfs(w);
		}
		kaeri.push_back(v);
	}

	vector<vector<edge>> grev;
	void dfsrev(ll v, ll c) {
		ver[v] = c;
		for (edge e : grev[v]) {
			ll w = e.to;
			if (ver[w] != -1) { continue; }
			dfsrev(w, c);
		}
	}

	SCC(vector<vector<edge>> g0) {
		g = g0;
		N = g.size() - 1;
		M = 0;

		ver.assign(N + 1, 0);

		repn(v, N) {
			if (ver[v] == -1) { continue; }
			dfs(v);
		}

		grev.resize(N + 1);
		repn(v, N) {
			for (edge e : g[v]) {
				grev[e.to].push_back({ e.ind,e.to,e.fr,e.d });
				M++;
			}
		}

		reverse(kaeri.begin(), kaeri.end());

		ll c = 0;
		for (ll v : kaeri) {
			if (ver[v] != -1) { continue; }
			c++;
			dfsrev(v, c);
		}

		ed.assign(M + 1, 0);
		ll ind = 0;
		graph.resize(c + 1);
		repn(v, N) {
			for (edge e : g[v]) {
				ll X = ver[v];
				ll Y = ver[e.to];

				if (X == Y) {
					ed[e.ind] = -X;
					continue;
				}
				ind++;
				ed[e.ind] = ind;
				graph[X].push_back({ ind,X,Y,e.d });
			}
		}
	}
};

