void dr(ll v, ll a, ll b, ll l, ll r, ll k, vector<vector<edge>> &g) {
	if (b <= l || a >= r) { return; }
	if (a <= l && b >= r) { g[v].push_back({ 1,v,k,1 }); return; }

	dr(v, a, b, l, (l + r) / 2, 2 * k, g);
	dr(v, a, b, (l + r) / 2, r, 2 * k + 1, g);
}

bool ch(ll d) {

	vector<vector<edge>> g(2 * M);
	repn(v, M - 1) {
		g[v].push_back({ 1,v,2 * v,1 });
		g[v].push_back({ 1,v,2 * v + 1,1 });
