		ll b = distance(pos.begin(), itr2);
		dr(v+M, a, very[i], 0, M, 1, g);
		dr(v + M, very[i]+1, b, 0, M, 1, g);

	}
	rep(i, N) {
		ll v = very[i];
		auto itr = upper_bound(pos.begin(), pos.end(), x[i] - d);
		ll a = distance(pos.begin(), itr);
		auto itr2 = lower_bound(pos.begin(), pos.end(), x[i] + d);
		ll b = distance(pos.begin(), itr2);

		dr(v+M, a, verx[i], 0, M, 1, g);
		dr(v + M, verx[i]+1, b, 0, M, 1, g);

	}

	//repn(v, 2 * M-1) {
