int pos(int d,int n){
	// printf("%d\n",cnt);
	REP(i,2*cnt) e[i].clear(),re[i].clear(),vis[i]=0,comp[i]=0;
	int in1 = 0,in2 = 0;
	REP(i,n){
		int a = lower_bound(all(A),mp(P[i].X,i))-A.begin();
		int b = lower_bound(all(A),mp(P[i].Y,i))-A.begin();
		addEdge(2*a,2*b+1);
		addEdge(2*a+1,2*b);
		// printf("%d %d\n",a,b);
	}
	REP(i,A.size()){
		while(in2<A.size() && A[in2].X-A[i].X<d) in2++;
		while(A[i].X-A[in1].X>=d) in1++;
		int p = in2-1 - i;
		// printf("%d %d %d\n",in1,in2,i);
		if(i+1<A.size() && in2-i>1){
			addEdge(2*i,2*B[i+1][LG[p]]+1);
			addEdge(2*i,2*B[in2-(1<<LG[p])][LG[p]]+1);
		}
		if(in1<i){
			p = i-in1;
			addEdge(2*i,2*B[in1][LG[p]]+1);
			addEdge(2*i,2*B[i-(1<<LG[p])][LG[p]]+1);
		}
	}
	REP(i,A.size()) REPP(j,1,LG[(int)A.size()]+2) addEdge(2*B[i][j]+1,2*B[i][j-1]+1),
							addEdge(2*B[i][j]+1,2*B[i+(1<<(j-1))][j-1]+1);
	REP(i, 2*cnt) dfs_ord(i);
    reverse(all(ord));
    REP(i, 2*cnt) vis[i] = 0;
    int cc = 0;
    for (int v=0;v< ord.size();v++) {
      //  printf("%d ",ord[v]);
        if (vis[ord[v]]) continue;
        dfs_mark(ord[v], cc++);
    }
    //printf("\n");
    bool ok = true;
    REP(i, cnt) ok &= comp[2 * i] != comp[2 * i + 1];
    if (!ok) {
        return 0;
    }
    // cout << "YES\n";
    return 1;
}

