			int z = st(pl, i);
			//cout << i << ": x != radius(x,d=" << d << ")[" << pl << "," << i-1 << "]: " << st[i] << " " << z << endl;
			g.implies(z, g.neg(st[i]));
			//cout << z << " => " << g.neg(st[i]) << endl;
		}
		while(ph<nn && srt[ph].f - srt[i].f <  d) ph++;
		if(ph > i+1) {
			int z = st(i+1, ph);
			//cout << i << ": x != radius(x,d=" << d << ")[" << i+1 << "," << ph-1 << "]: " << st[i] << " " << z << endl;
			g.implies(z, g.neg(st[i]));
			//cout << z << " => " << g.neg(st[i]) << endl;
		}
	}
	//cout << " " << sz(g.graph) << endl;
	auto r = g.solve();
	/*FOR(i,0,sz(r)) {
		cout << r[i] << " ";
	}	cout << endl;*/
	return sz(r);
}

