const int MAX_V = 3*(1<<15);

struct segment_tree{
    //[1,2^16)がoff,[2^16,2^16+2^15)がonの状態
    bool used[MAX_V];
    int topo[MAX_V];
    vector<int> Es[MAX_V], Rs[MAX_V], Vs;
    segment_tree(){
        rep2(i, 1, (1<<15)-1){
            Es[i].pb(i*2), Es[i].pb(i*2+1);
            Rs[i*2].pb(i), Rs[i*2+1].pb(i);
        }
    }
    void add_edge(int u, int v){
        Es[u].pb(v), Rs[v].pb(u);
    }
    void dfs(int now){
        used[now] = true;
        for(auto &e: Es[now]) if(!used[e]) dfs(e);
        Vs.pb(now);
    }
    void rdfs(int now, int k){
        used[now] = true;
        topo[now] = k;
        for(auto &e: Rs[now]) if(!used[e]) rdfs(e, k);
    }
    void scc(){
        fill(used, used + MAX_V, false);
        rep(i, MAX_V) if(!used[i]) dfs(i);
        fill(used, used + MAX_V, false);
        int k = 0;
        rep3(i, Vs.size()-1, 0){
            if(!used[Vs[i]]) rdfs(Vs[i], k++);
        }
    }
    //stから[a,b)に辺を張る
    void query(int a, int b, int st, int k = 1, int l = 0, int r = 1<<15){
        if(a >= r || b <= l) return;
        elif(a <= l && b >= r) Es[st].pb(k), Rs[k].pb(st);
        else{
            query(a, b, st, 2*k, l, (l+r)/2);
            query(a, b, st, 2*k+1, (l+r)/2, r);
        }
    }
};

int main(){
