        p[i] = pii(x, i), p[N+i] = pii(y, N+i);
    }
    sort(p, p+2*N);
    map<int, int> mp;
    rep(i, 2*N) mp[p[i].second] = i;
    int l = 0, r = 1e9;
    while(r-l > 1){
        int n = (l+r)/2;
        segment_tree seg;
        rep(i, N){
            seg.add_edge((1<<15)+mp[i], (1<<16)+mp[N+i]);
            seg.add_edge((1<<15)+mp[N+i], (1<<16)+mp[i]);
        }
        int now = 0;
        rep(i, 2*N){
            while(now < 2*N && p[now].first-p[i].first < n) now++;
            seg.query(i+1, now, (1<<16)+i); 
        }
        now = 2*N-1;
        rep3(i, 2*N-1, 0){
            while(now >= 0 && p[i].first-p[now].first < n) now--;
            seg.query(now+1, i, (1<<16)+i);
        }
        seg.scc();
        bool able = true;
        rep(i, N){
            if(seg.topo[(1<<16)+mp[i]] == seg.topo[(1<<16)+mp[N+i]]) able = false;
        }
        if(able) l = n;
        else r = n;
    }
    cout << l << endl;
}

