  void get(int a, int b, int x, int i, int l, int r){
    if (a <= l && r <= b) {
      q.pb(-sz(ps));
      ps.pb(P(i,x));
      return;
    }
    int c = (l+r)>>1;
    if (a < c) get(a,b,x,i<<1,l,c);
    if (c < b) get(a,b,x,i<<1|1,c,r);
  }
};
