    ps = vp(1);
    int ui = 1;
    for (int i : vs) if (!used[i]) {
      q.pb(i);
      while (sz(q)) {
        int v = q.back(); q.pop_back();
        if (v < 0) {
          v = -v;
          int di = ps[v].fi, x = ps[v].se;
          int& ei = d.e[di];
          bool ok = true;
          while (ei < sz(d.d[di])) {
            if (used[d.d[di][ei]]) ++ei;
            else if (d.d[di][ei] == (x^1)) {
              if (ei == sz(d.d[di])-1) {
                ok = false;
                break;
              }
              ++ei; d.d[di].pb(x^1);
            } else break;
          }
          if (!ok) continue;
          if (ei == sz(d.d[di])) continue;
          q.pb(-v);
          q.pb(d.d[di][ei++]);
          continue;
        }
        if (used[v]) continue;
        used[v] = ui;
        d.get(xs[a[v^1]-x+1],xs[a[v^1]+x],v);
      }
      ++ui;
    }
    // cout<<used<<endl;
  }
  rep(i,m) if (used[i] == used[i^1]) return false;
  return true;
}

