inline void tarjan(int x) {
    dfn[x]=low[x]=++tim;
    w[x]=1,v[++tp]=x;
    for(int i=head[x];i;i=nxt[i]) {
	int y=to[i];
	if(!dfn[y]) {
	    tarjan(y);
	    low[x]=min(low[x],low[y]);
	}
	else if(w[y])
	    low[x]=min(low[x],dfn[y]);
    }
    if(dfn[x]==low[x]) {
	int y;++gg;
	do c[y=v[tp--]]=gg,w[y]=0; while(x!=y);
    }
}
inline void lnk(int x,int y) {
    to[++tt]=y,nxt[tt]=head[x],head[x]=tt;
}
inline void insert(int l,int r,int p,int z,int &y) {
    if(!y) y=++cnt;
    if(l==r) {lnk(y,z);return;}
    int mid=(l+r)>>1;
    if(p<=mid) insert(l,mid,p,z,ls[y]);
    else insert(mid+1,r,p,z,rs[y]);
}
inline void query(int l,int r,int L,int R,int z,int x) {
    if(!x||L>R) return;
    if(L<=l&&r<=R) {lnk(z,x);return;}
    int mid=(l+r)>>1;
    if(L<=mid) query(l,mid,L,R,z,ls[x]);
    if(R>mid) query(mid+1,r,L,R,z,rs[x]);
}
