    for(int i=1;i<=n;i++) {
	insert(1,pt,a[i],i*2+1,rt);
	insert(1,pt,b[i],i*2,rt);
    }
    for(int i=1;i<=n;i++) {
	query(1,pt,find(st[a[i]]-k+1),a[i]-1,i*2,rt);
	query(1,pt,a[i]+1,find(st[a[i]]+k)-1,i*2,rt);
