	query(1,pt,b[i]+1,find(st[b[i]]+k)-1,i*2+1,rt);
    }
    for(int i=1;i<=cnt;i++) {
	if(ls[i]) lnk(i,ls[i]);
	if(rs[i]) lnk(i,rs[i]);
    }
    for(int i=2;i<=cnt;i++)
	if(!dfn[i]) tarjan(i);
    for(int i=2;i<=n+n;i+=2)
	if(c[i]==c[i+1]) return 0;
