mat path,path2;

int N,M,C;
const int MAX_N = 10005;
const int MAX_M = 100005;

pp a[MAX_N*2];
int rev[MAX_N*2],init_sz[MAX_M*2],init_sz2[MAX_M*2];
int s[MAX_M*2],sz;
bool vsi[MAX_M*2],isFirst;
int color[MAX_M*2];
void push_edge(int x,int y){
    path[x].push_back(y);
    path2[y].push_back(x);
}

void push_edge(int x,int L,int R){
    x+=C;
    L+=C;
    R+=C;
    while(L<R){
        if(L%2==1){
            push_edge(x,L+M);
            push_edge(L,x+M);
            L++;
        }
        if(R%2==0){
            push_edge(x,R+M);
            push_edge(R,x+M);
            R--;
        }
        L>>=1,R>>=1;
    }
    if(L==R){
        push_edge(x,L+M);
        push_edge(L,x+M);
    }
}

void dfs(int v){
    vsi[v] = 1;
    for(int u:path[v]){
        if(vsi[u])continue;
        dfs(u);
    }
    s[sz++]=v;
}

void dfs2(int v,int T){
    vsi[v] = 0;
    color[v] = T;
    for(int u:path2[v]){
        if(vsi[u]==0)continue;
        dfs2(u,T);
    }
}

void init(int d){
    if(isFirst){
        isFirst = false;
        path.assign(2*M,vec());
        path2.assign(2*M,vec());

        for(int i=0;i<N;i++){
            if(a[i].second%2)continue;
            int x = i+C;
            int y = rev[a[i].second+1]+C;
            push_edge(x,y+M);
            push_edge(x+M,y);
            push_edge(y,x+M);
            push_edge(y+M,x);
        }

        for(int i=1;i<C;i++){
            if(i*2<M)push_edge(i*2,i);
            if(i*2+1<M)push_edge(i*2+1,i);
            if(i*2<M)push_edge(i+M,i*2+M);
            if(i*2+1<M)push_edge(i+M,i*2+1+M);
        }

        for(int i=0;i<2*M;i++){
            init_sz[i] = path[i].size();
            init_sz2[i] = path2[i].size();
        }
    }else{
        for(int i=0;i<2*M;i++){
            path[i].resize(init_sz[i]);
            path2[i].resize(init_sz2[i]);
        }
    }

    int L=0,R=0;
    for(int i=0;i<N;i++){
        while(a[i].first-a[L].first>=d)L++;
        while(R<N&&a[R].first-a[i].first<d)R++;
        push_edge(i,L,i-1);
        push_edge(i,i+1,R-1);
    }
}

bool chk(int d){
    init(d);

    for(int i=0;i<2*M;i++){
        if(vsi[i]==0){
            dfs(i);
        }
    }

    int T=0;
    while(sz>0){
        int v = s[sz-1];
        if(vsi[v]){
            dfs2(v,T++);
        }
        sz--;
    }

    for(int i=0;i<M;i++){
        if(color[i] == color[i+M])return false;
    }
    return true;
}

int main(){
    ios::sync_with_stdio(false);

    cin>>N;
    N = N*2;
    for(C=1;C<N;C<<=1);
    M = C+N;
    for(int i=0;i<N;i++){
        cin>>a[i].first;
        a[i].second = i;
    }
    sort(a,a+N);
    for(int i=0;i<N;i++){
        rev[a[i].second] = i;
    }
    isFirst = true;

    int lo=0,hi=1e9,mid;
    while(lo+1<hi){
        mid = (lo+hi)/2;
        if(chk(mid)){
            lo = mid;
        }else{
            hi = mid;
        }
    }
    cout<<lo<<endl;
}

