bool ok(int m) {
  memset(head, -1, sizeof head);
  esz = 0;
  REP(i, n) for (int j = i + 1; j < n; ++j) {
    if (a[j][0] - a[i][1] >= m) break;
    bool f = false;
    REP(k, 2) REP(l, 2) {
      int d = abs(a[i][k] - a[j][l]);
      if (d >= m) {
        f = true;
      } else {
        add(i<<1|k, (j<<1|(l^1)));
        add(j<<1|l, (i<<1|(k^1)));
      }
    }
    if (!f) return false;
  }
  directed(n<<1);
  return !ed;
}

