#define Lson L,mid,lson
#define Rson mid+1,R,rson
void build(int L=0,int R=n*2-1,int o=1)
{
	if(L==R)
	{
		id[pt[L].id^1]=o;
		return;
	}
	int mid=L+R>>1;
	addedge(o,lson);
	addedge(o,rson);
	build(Lson);
	build(Rson);
}
void update(int l,int r,int p,int L=0,int R=n*2-1,int o=1)
{
	if(l<=L&&r>=R)
	{
		addedge(p,o);
		return;
	}
	int mid=L+R>>1;
	if(l<=mid) update(l,r,p,Lson);
	if(r>mid) update(l,r,p,Rson);
}
int dfn[maxn<<3], low[maxn<<3], bel[maxn<<3];
int ti, scc; //时间戳与联通分量计数
stack<int> st;
void dfs(int u, int fa)
{
    dfn[u] = low[u] = ++ti;
    st.push(u);
    for (auto v:G[u])
    {
        if (v == fa)
            continue;
        if (!dfn[v])
        {
            dfs(v, u);
            low[u] = min(low[u], low[v]);
        }
        else if (!bel[v])
            low[u] = min(low[u], dfn[v]);
    }
    if (dfn[u] == low[u])
    {
        scc++;
        while (1)
        {
            int t = st.top();
            st.pop();
            bel[t] = scc;
            if (u == t)
                break;
        }
    }
}
void SCC()
{
	memset(dfn,0,sizeof(dfn));
	memset(bel,0,sizeof(bel));
	ti=scc=0;
    for (int i = 1; i <= n; i++)
        if (!dfn[i])
            dfs(i, -1);
}
bool check(int x)
{
	if(!x) return true;
	for(int i=0;i<(n<<3);i++)
		G[i].clear();
	build();
	for(int i=0;i<n*2;i++)
	{
		int p=id[pt[i].id];
		int L=pt[i].val-x+1,R=pt[i].val+x-1;
		int lp=lower_bound(pt.begin(),pt.end(),Point{0,0,L})-pt.begin();
		int rp=upper_bound(pt.begin(),pt.end(),Point{0,0,R})-pt.begin()-1;
		if(lp<i)
			update(lp,i-1,p);
		if(rp>i)
			update(i+1,rp,p);
	}
	SCC();
	for(int i=0;i<n*2;i+=2)
		if(bel[id[i]]==bel[id[i^1]]) return false;
	return true;
}
