// spaghetti
int num[20000];
int low[20000];
bool inS[20000];
stack<int> S;
int tim;
int q[20000];
bool chch[20000];
bool dfs(int v){
  low[v] = num[v] = ++tim;
  S.push(v);
  inS[v] = true;
  for(int w : g[v]){
    if(num[w]==0){
      if(!dfs(w))return false;
      low[v] = min(low[v],low[w]);
    }else if(inS[w]){
      low[v] = min(low[v],num[w]);
    }
  }
  if(low[v]==num[v]){
    int tail = 0;
    while(true){
      int w = S.top(); S.pop(); inS[w] = false;
      q[tail++] = w;
      if(v==w)break;
    }
    // check
    REP(i,tail){
      int x = q[i];
      chch[x] = true;
      if(chch[x^1])return false;
    }
    REP(i,tail)chch[q[i]]=false;
  }
  return true;
}

bool ok(int d){
  REP(i,2*n)g[i].clear();
  REP(i,n)REP(j,i){
    int cnt = 0;
    if(abs(x[i]-x[j])<d){
      bid(2*i,    2*j);
      cnt++;
    }
    if(abs(x[i]-y[j])<d){
      bid(2*i,    2*j+1);
      cnt++;
    }
    if(abs(y[i]-x[j])<d){
      bid(2*i+1,  2*j);
      cnt++;
    }
    if(abs(y[i]-y[j])<d){
      bid(2*i+1,  2*j+1);
      cnt++;
    }
    if(cnt==4)return false;
  }
  REP(i,2*n)num[i]=low[i]=inS[i]=chch[i]=0;
  while(S.size())S.pop();
  tim = 0;
  REP(v,2*n)if(num[v]==0){
    if(!dfs(v))return false;
  }
  return true;
}

int main(){
  scanf("%d",&n);
  REP(i,n)scanf("%d%d",x+i,y+i);
  int low = 0, high = 1000000020;
  while(low+1<high){
    int mid = (low+high)/2;
    if(ok(mid)){
      low = mid;
    }else{
      high = mid;
    }
  }
  printf("%d\n",low);
  return 0;
}

