struct Variable {
	int tid, fid;
	Variable () {	};
};

Variable getvariable() {
	Variable res;
	res.tid = cnt;
	cnt++;
	res.fid = cnt;
	cnt++;
	return res;
}

Variable t[MAX * 4];

void clear() {
	cnt = 1;
	fi(0, MAX * 4 - 1) {
		e[i].clear();
		et[i].clear();
	}
}

void build(int v, int tl, int tr) {
	if (tl == tr) {
		t[v] = getvariable();
	} else {
		int tm = (tl + tr) / 2;
		build(v * 2 + 1, tl, tm);
		build(v * 2 + 2, tm + 1, tr);
		t[v] = getvariable();
	}
}

void place(int v, int tl, int tr, int l, int r, vector<Variable> &resp) {
	if (tl > r || l > tr) return;
	if (l <= tl && tr <= r) {
		resp.pb(t[v]);
		return;
	}
	int tm = (tl + tr) / 2;
	place(v * 2 + 1, tl, tm, l, r, resp);
	place(v * 2 + 2, tm + 1, tr, l, r, resp);
}

void godown(int v, int tl, int tr, int p, Variable x) {
	if (tl == tr) return;
	e[t[v].tid].pb(x.tid);
	e[t[v].fid].pb(x.fid);
	int tm = (tl + tr) / 2;
	if (p <= tm) {
		godown(v * 2 + 1, tl, tm, p, x);
	} else {
		godown(v * 2 + 2, tm + 1, tr, p, x);
	}
}

pii a[MAX];

