bool checkall(int v, int tl, int tr) {
	if (tl == tr) {
		return col[t[v].tid] != col[t[v].fid];
	}
	int tm = (tl + tr) / 2;
	bool res = (checkall(v * 2 + 1, tl, tm) && checkall(v * 2 + 2, tm + 1, tr));
	return res;
}

void dbg(int v, int tl, int tr) {
	err("tl = %d tr = %d tid = %d fid = %d\n", tl, tr, t[v].tid, t[v].fid);
	if (tl == tr) return;
	int tm = (tl + tr) / 2;
	dbg(v * 2 + 1, tl, tm);
	dbg(v * 2 + 2, tm + 1, tr);
}

bool can(int h) {
	clear();		
	build(0, 1, n * 2);
	fi(1, n * 2) {
		vector<Variable> cur;
		place(0, 1, n * 2, i, i, cur);
		godown(0, 1, n * 2, i, cur[0]);
	}

	memset(pos, 0, sizeof(pos));
	fi(1, n) {
		a[i] = mp(x[i], i);
		a[i + n] = mp(y[i], i);
	}

	sort(a + 1, a + n * 2 + 1);
	fi(1, n * 2) {
		int pt = a[i].second;
		if (pos[pt][0]) {
			pos[pt][1] = i;
		} else {
			pos[pt][0] = i;
		}
	}

	fi(1, n) {//!x_i -> y_i, !y_i -> x_i
		int a = pos[i][0];
		int b = pos[i][1];
		vector<Variable> va, vb;
		place(0, 1, n * 2, a, a, va);
		place(0, 1, n * 2, b, b, vb);
		e[va[0].fid].pb(vb[0].tid);
		e[vb[0].fid].pb(va[0].tid);
	}

	fi(1, n * 2) {
		int lx = a[i].first - h;
		int rx = a[i].first + h;
		int l = (int) (upper_bound(a + 1, a + n * 2 + 1, mp(lx, INF)) - a);
		int r = (int) (upper_bound(a + 1, a + n * 2 + 1, mp(rx, -INF)) - a);
		r--;
//		err("i = %d lx = %d rx = %d l = %d r = %d\n", i, lx, rx, l, r);

		vector<Variable> cur;
		place(0, 1, n * 2, i, i, cur);	

		vector<Variable> v;
		place(0, 1, n * 2, l, i - 1, v);
		for (auto z : v) {
			e[cur[0].tid].pb(z.fid);
		}
		place(0, 1, n * 2, i + 1, r, v);
		for (auto z : v) {
			e[cur[0].tid].pb(z.fid);
		}
	}

	findcomps();
	/*
	dbg(0, 1, n * 2);

	fi(1, cnt) {
		err("i = %d color = %d\n", i, col[i]);
	}
	*/
	return checkall(0, 1, n * 2);
}

void solve() {

	int l = -1;
	int r = INF;
	while (r - l > 1) {
		int h = (l + r) / 2;
		if (can(h)) {
			l = h;
		} else {
			r = h;
		}
	}
	assert(l >= 0);
	printf("%d\n", l);
}

