//					G[i+N].push_back(j+N);
	//				G[j].push_back(i);
					add_edge(i+N,j+N);
					add_edge(j,i);
				}
				if (abs(Y[i]-Y[j])<d){
		//			G[i+N].push_back(j);
			//		G[j+N].push_back(i);
					add_edge(i+N,j);
