    void Tarjan(int x) {
        low[x]=dfn[x]=++dx;
        s[++cnt]=x;
        ins[x]=1;
        for (int i=head[x];i!=-1;i=edge[i].next) {
            int kx=edge[i].num;
            if (dfn[kx]) {
                if (ins[kx]) low[x]=min(low[x],dfn[kx]);
                continue;
            }
            Tarjan(kx);
            low[x]=min(low[x],low[kx]);
        }
        if (low[x]<dfn[x]) return;
        ++now;
        while (s[cnt]!=x) {
            ans[s[cnt]]=now;
            ins[s[cnt]]=0;
            cnt--;
        }
        ans[x]=now;
        ins[x]=0;
        cnt--;
    }
    bool work() {
        for (int i=1;i<=n*2;i++) dfn[i]=ins[i]=ans[i]=0;
        for (int i=1;i<=n*2;i++)
            if (!dfn[i]) Tarjan(i);
        for (int i=1;i<=n;i++)
            if (ans[i*2-1]!=0&&ans[i*2-1]==ans[i*2]) return 0;
        return 1;
    }
