        return;
    }
    int mid=(l+r)/2;
    build1(x*2,l,mid);
    build1(x*2+1,mid+1,r);
    sat::Add((n+x)*2-1,(n+x*2)*2-1);
    sat::Add((n+x*2)*2,(n+x)*2);
    sat::Add((n+x)*2-1,(n+x*2+1)*2-1);
