    LL nowl=b[t1[i].l].x,nowr=b[t1[i].r].x;
    if (nowl>r||nowr<l) return;
    if (nowl>=l&&nowr<=r) {
        sat::Add(x,(n+i)*2-1);
        sat::Add((n+i)*2,y);
        return;
    }
    Add1(i*2,l,r,x,y);
    Add1(i*2+1,l,r,x,y);
}
