	s[++top]=x;in[x]=1;
	for(int i=head[x];i;i=e[i].nex)
	{
		int y=e[i].to;
		if(!dfn[y])
		{
			dfs(y);
			low[x]=min(low[x],low[y]);
		}
		else if(in[y])low[x]=min(low[x],dfn[y]);
	}
	if(low[x]==dfn[x])
	{
		c++;int a=-1;
		do{
			a=s[top--];
			in[a]=0;
			col[a]=c;
		}while(a!=x);
	}
	return;
}
