	template<typename T>inline bool check_max(T a,T &b){return a>b?b=a,1:0;}
	typedef std::vector<int>::iterator vit;

	struct node
	{
		int x,id;
		node (int a=0,int b=0){x=a,id=b;}
		bool operator < (const node &h) const {return x<h.x;}
	};

	const int N=10010,M=N*2;

	std::vector<int> G[M];
	node s[M];

	int n,m,lim;
	inline void add(int x,int y){G[x].push_back(y);}

#define id(i) (n+i)
#define dec(i) (i>n?i-n:i+n)

	int ins[M],stk[M];
	int col[M],dfn[M];
	int clk,tot,top;

	int tarjan(int p)
	{
		stk[++top]=p,ins[p]=1;
		int lowp=dfn[p]=++clk,lowq;
		for(vit it=G[p].begin();it!=G[p].end();it++)
		{
			int q=*it;
			if(dfn[q])
			{
				if(ins[q])check_min(dfn[q],lowp);
				continue;
			}
			check_min(lowq=tarjan(q),lowp);
		}

		if(lowp==dfn[p])
		{
			tot++;
			for(int x;;)
			{
				x=stk[top--];
				ins[x]=0;
				col[x]=tot;
				if(x==p)break;
			}
		}

		return lowp;
	}

	bool check()
	{
		static bool sel[M];
		static int his[M],cnt;

		for(int i=1;i<=n;i++)G[i].clear(),G[i+n].clear();

		memset(sel,0,sizeof(sel));
		for(int i=1;i<=m;i++)
		{
			cnt=0;
			int L=i-1,R=i+1,p=s[i].id,q;
			while(R<=m && s[R].x-s[i].x<lim)
			{
				if(R-i>200)break;
				q=dec(s[R].id);
				add(p,q);

				sel[q]=1;
				his[++cnt]=q;
				R++;
			}
			while(L>=1 && s[i].x-s[L].x<lim)
			{
				if(i-L>200)break;
				q=dec(s[L].id);
				add(p,q);

				sel[q]=1;
				his[++cnt]=q;
				L--;
			}
			for(int j=1;j<=cnt;j++)
				sel[his[j]]=0;

			cnt=0;
		}

		for(int i=1;i<=m;i++)
			ins[i]=col[i]=dfn[i]=0;
		top=clk=tot=0;

		for(int i=1;i<=m;i++)
			if(!dfn[i])tarjan(i);

		for(int i=1;i<=n;i++)
			if(col[i]==col[id(i)])return 0;
		return 1;
	}

	void initialize()
	{
		scanf("%d",&n),m=0;
		for(int i=1,x,y;i<=n;i++)
		{
			scanf("%d%d",&x,&y);
			s[++m]=node(x,i);
			s[++m]=node(y,id(i));
		}
		std::sort(s+1,s+m+1);
	}
	void solve()
	{
		initialize();
		int u=1000000000,d=0;
		while(u>d)
		{
//			fprintf(stderr,"%d--%d\n",d,u);
			lim=(u+d+1)>>1;
			if(check())d=lim;
			else u=lim-1;
		}
		printf("%d\n",d);
	}
}

