void update(int x,int L,int R){
	x+=sz,L+=sz,R+=sz;
	while(L<R){
		if(L&1)add_edge(x,(L++)+M);
		if(~R&1)add_edge(x,(R--)+M);
		L>>=1,R>>=1;
	}
	if(L==R)add_edge(x,L+M);
}

