	ID[v]=c;
	for(auto& u:rpath[v]){
		if(ID[u]>=0)continue;
		rdfs(u,c);
	}
}

bool chk(int len){
	init(len);
	vsi[0]=vsi[M]=1;
	for(int i=0;i<M*2;i++){
		if(vsi[i])continue;
