int get(int l, int r) {
	if (r <= l)
		return 0;
	l += (1 << 15);
	r += (1 << 15) - 1;
	if (seg[l].size())
		return *seg[l].begin();
	if (seg[r].size())
		return *seg[r].begin();
	while (l / 2 != r / 2) {
		if (l % 2 == 0 && seg[l + 1].size())
			return *seg[l + 1].begin();
		if (r % 2 == 1 && seg[r - 1].size())
			return *seg[r - 1].begin();
		l /= 2;
