void range_add(Graph<ll>& graph, ll a, ll b, ll from, ll l = 0, ll r = -1, ll k = 1) { // [a, b)
  if (r == -1) r = m;
  if (a <= l && r <= b) { graph.add_edge(from, k); return; }
  if (b <= l || r <= a) { return; }
  ll mid = (l + r) / 2;
  range_add(graph, a, b, from, l, mid, 2*k); range_add(graph, a, b, from, mid, r, 2*k+1);
}

