  for (ll i = 0; i < n; i++) {
    ll xnum = getNum(x[i], 2*i), ynum = getNum(y[i], 2*i+1);
    range_add(graph, getNum(x[i]-d+1, 0), xnum, xnum+2*m);
    range_add(graph, xnum+1, getNum(x[i]+d, 0), xnum+2*m);
    range_add(graph, getNum(y[i]-d+1, 0), ynum, ynum+2*m);
    range_add(graph, ynum+1, getNum(y[i]+d, 0), ynum+2*m);
  }
  vector<ll> ans = graph.scc();
  for (ll i = 0; i < n2; i++) if (ans[m+i] == ans[2*m+i]) return false;
