class SegmentTree{
private:
	inline void build(int x, int l, int r){
		ind[x] = tot++;
		g[ind[x]].clear();
		if(x != 1){
			if(tp == IN)
				g[ind[x >> 1]].PB(ind[x]);
			else
				g[ind[x]].PB(ind[x >> 1]);
		}
		int md = l + r >> 1;
		if(l == r)
			return;
		build(x << 1, l, md);
		build(x << 1 | 1, md + 1, r);
		return;
	}
public:
	int tp;
	int ind[siz << 1];
	inline int size(){return siz;}
	inline void init(int _tp){
		tp = _tp;
		build(1, 0, size() - 1);
		return;
	}
	inline void update(int x, int l, int r, int s, int t, int u){
		if(s > t)
			return;
		if(l >= s && r <= t){
//			printf("%d %s %d\n", u, (tp ? "->" : "<-"), ind[x]);
			if(tp == IN)
				g[u].PB(ind[x]);
			else
				g[ind[x]].PB(u);
			return;
		}
		int md = l + r >> 1;
		if(s <= md)
			update(x << 1, l, md, s, t, u);
		if(t > md)
			update(x << 1 | 1, md + 1, r, s, t, u);
		return;
	}
}segi, sego;

inline int id(int u, int i){
