namespace Tarjan{
	int clk, top, cnt;
	int dfn[siz << 2], ins[siz << 2], stk[siz << 2], low[siz << 2], col[siz << 2];
	inline void init(){
		clk = top = cnt = 0;
		memset(dfn, -1, sizeof(dfn));
//		memset(col, -1, sizeof(col));
		return;
	}
	inline void dfs(int u){
//		printf("u = %d\n", u);
		low[u] = dfn[u] = clk++;
		stk[++top] = u;
		ins[u] = true;
		FOR(i, 0, g[u].size()){
			int v = g[u][i];
//			printf("u = %d v = %d\n", u, v);
			if(!~dfn[v]){
				dfs(v);
				low[u] = min(low[u], low[v]);
			}
			else if(ins[v])
				low[u] = min(low[u], dfn[v]);
		}
		if(low[u] == dfn[u]){
			for(int v = stk[top]; top && v != u; v = stk[--top]){
				col[v] = cnt;
				ins[v] = false;
//				printf("%d ", v);
			}
//			printf("%d\n", u);
			col[stk[top--]] = cnt++;
			ins[u] = false;
		}
		return;
	}
	inline bool work(){
		init();
		FOR(i, 0, tot) if(!~dfn[i]){
//			printf("i = %d\n", i);
			dfs(i);
		}
//		printf("cnt = %d\n", cnt);
//		FOR(i, 0, vec.size())
//			printf("%d %d\n", col[id(i, 0)], col[id(i, 1)]);
		FOR(i, 0, vec.size()) if(col[id(i, 0)] == col[id(i, 1)])
			return false;
		return true;
	}
}

inline void OR(int u, int v){ // u or v = true
//	printf("u = %d v = %d (%d %d) (%d %d)\n", u, v, id(u, 0), id(u, 1), id(v, 0), id(v, 1));
	g[id(u, 0)].PB(id(v, 1));
	g[id(v, 0)].PB(id(u, 1));
	return;
}

inline void AND(int u, int l, int r){ // u and (l ... r) = false
	segi.update(1, 0, sego.size() - 1, l, r, id(u, 1)); //(u, 1) -> (l...r, 0)
	sego.update(1, 0, segi.size() - 1, l, r, id(u, 0)); //(l...r, 1) -> (u, 0)
	return;
}

