	int mid=l+r>>1;
	build(l,mid,ls);build(mid+1,r,rs);
	add(num[k][0],num[ls][0]);add(num[ls][1],num[k][1]);
	add(num[k][0],num[rs][0]);add(num[rs][1],num[k][1]);
