inline void get(int l,int r,int x,int y,int k,int p){
	if(x>y) return;
	if(x<=l&&r<=y){
		add(num[pp[p]][1],num[k][0]);
		add(num[k][1],num[pp[p]][0]);
		return;
	}
	int mid=l+r>>1;
	if(x<=mid) get(l,mid,x,y,ls,p);
	if(y>mid) get(mid+1,r,x,y,rs,p);
}
