	clr(vis,0);
	for(int i=m,j=0;i;i--)
		if(!vis[seq[i-1]]) dfs(seq[i-1],++j);
	for(int i=1;i<=cnt;i++)
		if(vis[num[i][0]]==vis[num[i][1]]) return 0;
	return 1;
}
