namespace two_sat
{
	struct edge{
		int la,b;
	};
	struct edges{
		edge con[N<<2];
		int tot,fir[N<<2];
		void add(int from,int to)
		{
			con[++tot].la=fir[from];
			con[tot].b=to;
			fir[from]=tot;
		}
		void aei(int a,int b)//add edges for the nodes which is independent from one another
		{
			add(a<<1,b<<1|1);
			add(a<<1|1,b<<1);
			add(b<<1,a<<1|1);
			add(b<<1|1,a<<1);
		}
		void aebt(int a,int b)//add edges for the nodes which can't be both true
		{
			add(a<<1|1,b<<1);
			add(b<<1|1,a<<1);
		}
		void aerf(int a,int b)//add edges for the node which is reasonable for one another
		{
			add(a<<1|1,b<<1|1);
			add(b<<1,a<<1);
		}
		void aesa(int a,int b)//add edges for the nodes which have the same condition as another
		{
			add(a<<1,b<<1);
			add(a<<1|1,b<<1|1);
			add(b<<1,b<<1);
			add(b<<1|1,a<<1|1);
		}
		void init()
		{
			memset(fir,0,sizeof fir);
			tot=0;
		}
	}cone,exe;//const edges ; extra edges
	#define travel(i,x,y) for(int i=(y).fir[(x)];i;i=(y).con[i].la)
	#define to(y,i) (y).con[i].b

	int color[N<<2],dfn[N<<2],low[N<<2],sta[N<<2],top,cnt;
	void dfs(int pos)
	{
		sta[++top]=pos;
		dfn[pos]=low[pos]=top;
		travel(i,pos,cone)
		{
			if(color[to(cone,i)]) continue;
			if(!dfn[to(cone,i)]) dfs(to(cone,i));
			low[pos]=min(low[pos],low[to(cone,i)]);
		}
		travel(i,pos,exe)
		{
			if(color[to(exe,i)]) continue;
			if(!dfn[to(exe,i)]) dfs(to(exe,i));
			low[pos]=min(low[pos],low[to(exe,i)]);
		}
		if(low[pos]==dfn[pos])
		{
			cnt++;
			while(top>=dfn[pos]) color[sta[top--]]=cnt;
		}
	}
	void tarjan()
	{
		for(int i=1;i<=totn;i++)if(!dfn[i])
			dfs(i);
	}
	bool solve()
	{
		cnt=0;top=0;
		memset(color,0,sizeof color);
		memset(dfn,0,sizeof dfn);
		tarjan();
		for(int i=1;i<=totn;i++)
		{
			if(color[i<<1]==color[i<<1|1]&&color[i<<1]!=0)
			{
//				cerr<<i<<' '<<color[i<<1]<<' '<<dfn[i]<<endl;
				return 0;
			}
			// the follow line prints the way
			// printf("%d ",color[i<<1]<color[i<<1|1]?0:1);
		}
		return 1;
	}
}
using namespace two_sat;
struct node{
	int l,r;
}tree[N<<2];
void buildtree(int lp,int rp,int pos)
//it's not real for building segment tree. exactly it's for building the graph
{
	totn=max(totn,pos+2*n);
	tree[pos]=(node){lp,rp};
	if(lp==rp){
		cone.aesa(2*n+pos,posi[lp].id);
		return;
	}
	int mid=(lp+rp)>>1;
	buildtree(lp,mid,pos<<1);
	buildtree(mid+1,rp,pos<<1|1);
	cone.aerf(2*n+(pos<<1),2*n+pos);
	cone.aerf(2*n+(pos<<1|1),2*n+pos);
}
void search(int lp,int rp,int pos,int now)
//this works for building the graph too
{
	if(tree[pos].l>rp||tree[pos].r<lp) return;
	if(tree[pos].l>=lp&&tree[pos].r<=rp)
	{
		exe.aebt(now,2*n+pos);
		return;
	}
	search(lp,rp,pos<<1,now);
	search(lp,rp,pos<<1|1,now);
}
bool check(int dis)
{
	exe.init();
	int t;
	for(int i=1;i<=2*n;i++)
	{
		t=lower_bound(posi+1,posi+2*n+1,posi[i].w-dis+1)-posi;
		if(t<=i-1) search(t,i-1,1,posi[i].id);
		t=lower_bound(posi+1,posi+2*n+1,posi[i].w+dis)-posi-1;
		if(t>=i+1) search(i+1,t,1,posi[i].id);
	}
	return solve();
}
int main()
{
	scanf("%d",&n);
	for(int i=1;i<=n;i++)
	{
		scanf("%d%d",&x[i],&y[i]);
		posi[i*2-1]=(avail){x[i],i*2-1};
		posi[i*2]=(avail){y[i],i*2};
		cone.aei(i*2-1,i*2);
	}
	sort(posi+1,posi+2*n+1);
	buildtree(1,2*n,1);
	int l=0,r=posi[2*n].w,mid;
	while(l<r)
	{
		mid=(l+r)>>1;
		if(check(mid)) l=mid+1;
		else r=mid-1;
	}
	if(!check(r)) r--;
	printf("%d\n",r);
	return 0;
}

