void SelectEdge(int d) {
  rep(i, N*2) {
    es[i].clear();
    res[i].clear();
  }

  if (toomany) {
    rep(i, d) {
      for (auto &p : evs[i]) {
        int u, v;
        tie(u, v) = p;
        es[u].eb(v);
        res[v].eb(u);
      }
    }
  } else {
    rep(i, N) {
      reps(j, i+1, N) {
        rep(k, 2) {
          rep(l, 2) {
            if (abs(X[j][l]-X[i][k]) < d) {
              es[i*2+k].eb(j*2+1-l);
              res[j*2+1-l].eb(i*2+k);
              es[j*2+l].eb(i*2+1-k);
              res[i*2+1-k].eb(j*2+l);
            }
          }
        }
      }
    }
  }
}

bool used[21451];
int belong[21451];
vector<int> vis;

void Dfs(int v) {
  used[v] = true;
  for (int u : es[v]) {
    if (used[u]) continue;
    Dfs(u);
  }
  vis.eb(v);
}

void RDfs(int v, int grp) {
  used[v] = true;
  belong[v] = grp;
  for (int u : res[v]) {
    if (used[u]) continue;
    RDfs(u, grp);
  }
}

bool DoScc() {
  vis.clear();
  fill(used, used+2*N, false);
  rep(v, 2*N) {
    if (!used[v]) Dfs(v);
  }
  reverse(all(vis));
  fill(used, used+2*N, false);
  int grp = 0;
  for (int v : vis) {
    if (!used[v]) RDfs(v, grp++);
  }

  rep(i, N) {
    if (belong[i*2] == belong[i*2+1]) return false;
  }
  return true;
}

bool check(int x) {
  SelectEdge(x);
  return DoScc();
}

