struct Segment{
	inline int Q(int l){
		if(l%2==0) return l-1;
		return l+1;
	}
	inline void build(int k,int l,int r){
		if(l==r){add(k+2*n,M[Q(g[l].id)]);return;}
		int mid=l+r>>1;
		add(k+2*n,(k<<1)+2*n),add(k+2*n,(k<<1|1)+2*n);
		build(k<<1,l,mid),build(k<<1|1,mid+1,r);
	}
