		if(x<=l&&r<=y) {add(u,k+2*n);return;}
		int mid=l+r>>1;
		if(x<=mid) ins(k<<1,l,mid,x,y,u);
		if(mid<y) ins(k<<1|1,mid+1,r,x,y,u);
