void build(ll l,ll r,ll &p){
	if (l==r){	p=a[l];	return;	}
	p=++cnt;
	ll mid=(l+r)>>1;
	build(l,mid,ls[p]);	build(mid+1,r,rs[p]);
	g[p].push_back(ls[p]);	g[p].push_back(rs[p]);
}
void clear(){
	For(i,1,cnt)dfn[i]=low[i]=bel[i]=0,g[i].clear();
	cnt=cogito=ind=0;
}
void AddEdge(ll l,ll r,ll p,ll s,ll t,ll id){
	if (s<=l&&r<=t){
		g[id].push_back(p);
		return;
	}ll mid=(l+r)/2;
	if (s<=mid)AddEdge(l,mid,ls[p],s,t,id);
	if (t>mid)AddEdge(mid+1,r,rs[p],s,t,id);
}
void tarjan(ll x){
	low[q[++top]=x]=dfn[x]=++ind;
	rep(i,0,g[x].size()){
		ll to=g[x][i];
		if (!dfn[to])	tarjan(to),low[x]=min(low[x],low[to]);
		lf (!bel[to])	low[x]=min(low[x],low[to]);
	}
	if (low[x]==dfn[x])	for(++cogito;q[top+1]!=x;)		bel[q[top--]]=cogito;
}
