			x2=upper_bound(q1+1,q1+n+2,q1[i]+len)-q1-1;
		if (x1<i)	AddEdge(1,n,Rt,x1,i-1,id1[i]);
		if (i<x2)	AddEdge(1,n,Rt,i+1,x2,id1[i]);

		ll	y1=lower_bound(q1+1,q1+n+2,q2[i]-len)-q1,
			y2=upper_bound(q1+1,q1+n+2,q2[i]+len)-q1-1;
		if (y1<=y2)	AddEdge(1,n,Rt,y1,y2,id2[i]+n);

	}
	For(i,1,n)	a[i]=id2[i];
	Rt=0;	build(1,n,Rt);
	For(i,1,n){
		ll	x1=lower_bound(q2+1,q2+n+2,q1[i]-len)-q2,
			x2=upper_bound(q2+1,q2+n+2,q1[i]+len)-q2-1;
		if (x1<=x2)	AddEdge(1,n,Rt,x1,x2,id1[i]);

		ll	y1=lower_bound(q2+1,q2+n+2,q2[i]-len)-q2,
			y2=upper_bound(q2+1,q2+n+2,q2[i]+len)-q2-1;
		if (y1<i)	AddEdge(1,n,Rt,y1,i-1,id2[i]+n);
		if (i<y2)	AddEdge(1,n,Rt,i+1,y2,id2[i]+n);
	}

	For(i,1,cnt)if (!dfn[i])tarjan(i);
	For(i,1,n)if (bel[i]==bel[i+n])return 0;
	return 1;
}
