namespace Tarjan{
	int pre[M],low[M],sccno[M],dfs_clock,scc_cnt;
	stack<int> S;
	struct Edge{
		int u,v,Next;
	} G[M*4];int head[M],tot;
	inline void init(int n){
		rep(i,1,n)pre[i]=low[i]=sccno[i]=0;tot=0;
		memset(head,-1,sizeof(head));
		//memset(pre,0,sizeof(pre));
		dfs_clock=scc_cnt=0;while(!S.empty())S.pop();
	}
	inline void add(int u,int v){
		G[++tot]=(Edge){u,v,head[u]};
		head[u]=tot; //printf("%d %d\n",u,v);
	}
	inline void dfs(int u){
		pre[u]=low[u]=++dfs_clock;
		S.push(u);
		for(int i=head[u];i!=-1;i=G[i].Next){
			int v=G[i].v;
			if(!pre[v]){
				dfs(v);
				low[u]=min(low[u],low[v]);
			} else if(!sccno[v]){
				low[u]=min(low[u],pre[v]);
			}
		}if(low[u]==pre[u]){
			scc_cnt++;
			for(;;){
				int x=S.top();S.pop();
				sccno[x]=scc_cnt;
				if(x==u)break;
			}
		}
	}
	inline void solve(int n){
		rep(i,1,n)if(!pre[i])dfs(i);
	}
}
