struct smt{
	int q[M*2];
	inline void build(int l,int r,int o,int cur){
		if(l==r){
			if(cur)q[o]=l;
			else q[o]=fri[l];
			return;
		} int mid=(l+r)/2;
		build(l,mid,2*o,cur);
		build(mid+1,r,2*o+1,cur);q[o]=++cnt;
		if(cur){
			Tarjan::add(q[2*o],q[o]);
			Tarjan::add(q[2*o+1],q[o]);
		}else{
			Tarjan::add(q[o],q[2*o]);
			Tarjan::add(q[o],q[2*o+1]);
		}
	}
	inline void change(int l,int r,int o,int x,int y,int z,int cur){
		if(x<=l&&r<=y){
			if(cur)Tarjan::add(q[o],z);
			else Tarjan::add(z,q[o]);return;
		}int mid=(l+r)/2;
		if(x<=mid)change(l,mid,2*o,x,y,z,cur);
		if(y>mid)change(mid+1,r,2*o+1,x,y,z,cur);
	}
	inline void init(int n,int cur){
		build(1,n,1,cur);
	}
} T,T_fri;
inline bool check(int n,int x){
	Tarjan::init(cnt);cnt=n+n;
	T.init(n+n,1);T_fri.init(n+n,0);
	int l=1,r=1;
