		while(r<n+n&&a[b[r+1]]<a[b[i]]+x)r++;
		if(i-l>0){
			T.change(1,n+n,1,l,i-1,fri[i],1);
			T_fri.change(1,n+n,1,l,i-1,i,0);
		}if(r-i>0){
			T.change(1,n+n,1,i+1,r,fri[i],1);
			T_fri.change(1,n+n,1,i+1,r,i,0);
		}
	} Tarjan::solve(cnt);
	rep(i,1,n+n)if(Tarjan::sccno[i]==Tarjan::sccno[fri[i]]){
		return false;
	} return true;
}
