struct RangeGraph{
  vector<vector<ll>>g;
  ll n,sz;
  ll cnt;
  RangeGraph(ll n,ll m):n(n){
    sz=1;
    cnt=0;
    while(sz<n)sz <<= 1;
    g.assign(3*sz+m,vector<ll>());
    for(ll i=1;i<sz;i++){
      g[i].EB(2*i);
      g[i].EB(2*i+1);
      if(2*i<sz){
        g[2*i+2*sz].EB(i+2*sz);
        g[2*i+1+2*sz].EB(i+2*sz);
      }
      else{
        g[2*i].EB(i+2*sz);
        g[2*i+1].EB(i+2*sz);
      }
    }
  }
  void add_edge(ll l1,ll r1,ll l2,ll r2){//[l1,r1)->[l2,r2)
    if(l1>=r1||l2>=r2)return;
    if(l1+1==r1&&l2+1==r2){
      g[l1+sz].EB(l2+sz);
    }
    else if(l1+1==r1){
      auto v=range(l2,r2);
      v=range(l2,r2);
      for(auto z:v)g[l1+sz].EB(z);
    }
    else if(l2+1==r2){
      auto v=range(l1,r1);
      for(auto z:v){
        if(z<sz)g[z+2*sz].EB(l2+sz);
        else g[z].EB(l2+sz);
      }
    }
    else{
      auto v=range(l1,r1);
      ll via=3*sz+cnt;
      for(auto z:v){
        if(z<sz)g[z+2*sz].EB(via);
        else g[z].EB(via);
      }
      v=range(l2,r2);
      for(auto z:v)g[via].EB(z);
      cnt++;
    }
  }
  vector<ll>range(ll l,ll r){
    vector<ll>ret;
    l+=sz,r+=sz;
    while(l!=r){
      if(l&1)ret.PB(l++);
      if(r&1)ret.PB(--r);
      l>>=1,r>>=1;
    }
    return ret;
  };
  ll add(){
    return sz;
  }
};

struct SCC{
  ll n;
  vector<vector<ll>>G,Gr;
  vector<ll>index;//各ノードが属する強連結成分の番号
  vector<ll>ret;//dfsに使う
  SCC(vector<vector<ll>>g):G(g),n(g.size()){
    index.assign(n,-1LL);
    build();
  }
  void build(){
    Gr.assign(n,vector<ll>());
    for(ll i=0;i<n;i++){
      for(ll j=0;j<G[i].size();j++){
        Gr[G[i][j]].push_back(i);
      }
    }
    for(ll i=0;i<n;i++)if(index[i]==-1)dfs1(i);
    fill(ALL(index),-1);
    ll cnt=0;
    reverse(ALL(ret));
    for(ll i=0;i<n;i++){
      if(index[ret[i]]==-1){
        dfs2(ret[i],cnt);
        cnt++;
      }
    }
  }
  void dfs1(ll k){
    index[k]=1;
    for(ll i=0;i<G[k].size();i++){
      if(index[G[k][i]]==-1)dfs1(G[k][i]);
    }
    ret.push_back(k);
  }
  void dfs2(ll k, ll idx){
    index[k]=idx;
    for(ll i=0;i<Gr[k].size();i++){
      if(index[Gr[k][i]]==-1)dfs2(Gr[k][i],idx);
    }
  }
  vector<vector<ll>>edges;
  void build_edges(){
    edges.assign(*max_element(ALL(index))+1,vector<ll>());
    for(ll i=0;i<n;i++){
      for(ll j=0;j<G[i].size();j++){
        if(index[i]!=index[G[i][j]]){
          edges[index[i]].push_back(index[G[i][j]]);
        }
      }
    }
  }
  vector<ll>output(){return index;};
};

