void dfs(ll x) {
	low[x]=dfn[x]=++d_cnt;sta[++top]=x;in[x]=1;
	for(re ll h=head[x];h;h=e[h].nxt) {
		re ll v=e[h].v;
		if(!dfn[v]) {dfs(v),low[x]=min(low[x],low[v]);}
		else if(in[v]) low[x]=min(low[x],dfn[v]);
	}
	if(dfn[x]==low[x]) {
		++s_cnt;
		while(sta[top]!=x) {bl[sta[top]]=s_cnt;in[sta[top]]=0;top--;}
		bl[x]=s_cnt;in[x]=0;top--;
	}
}
