			re ll l=lower_bound(Hash+1,Hash+2*n+1,K(peo[i][j]-x+1,0))-Hash;
			re ll r=upper_bound(Hash+1,Hash+2*n+1,K(peo[i][j]+x-1,2*n+1))-Hash-1;
			re ll m=lower_bound(Hash+1,Hash+2*n+1,K(peo[i][j],(j^1)*n+i))-Hash;
			add(1,1,2*n,l,m-1,j*n+i);
			add(1,1,2*n,m+1,r,j*n+i);
		}
	}
	top=d_cnt=s_cnt=0;
	memset(low,0,sizeof(low));
	memset(dfn,0,sizeof(dfn));
	memset(bl,0,sizeof(bl));
	memset(in,0,sizeof(in));
