void Add (int x, int l, int r, int ql, int qr, int d) {
	if (l == ql && r == qr) return V[d].emplace_back(x);
	int mid = (l + r) >> 1;
	if (qr <= mid) Add(L, l, mid, ql, qr, d);
	else if (ql > mid) Add(R, mid + 1, r, ql, qr, d);
	else Add(L, l, mid, ql, mid, d), Add(R, mid + 1, r, mid + 1, qr, d);
}

