piii pos[N]; int x[N], y[N];

vector<int> g[N]; int nc;
void adde(int u, int v) {
    //cout << u << "->" << v << endl;
    g[u].push_back(v);
}


int id1[1<<16], id2[1<<16];
void build(int p, int lb, int rb) {
    id1[p] = ++nc; g[nc].clear();
    id2[p] = ++nc; g[nc].clear();
    if (lb + 1 == rb) {
        adde(id1[p], pos[lb].second.second);
        adde(pos[lb].second.first, id2[p]);
    }
    else {
        int mid = (lb + rb) >> 1;
        build(p << 1, lb, mid);
        build(p << 1 | 1, mid, rb);
        adde(id1[p], id1[p << 1]);
        adde(id1[p], id1[p << 1 | 1]);
        adde(id2[p << 1], id2[p]);
        adde(id2[p << 1 | 1], id2[p]);
    }
}

int opp(int x) { return x & 1 ? x + 1 : x - 1; }

void adde(int l, int r, int x, int p, int lb, int rb) {
    if (l >= r) return;
    if (l <= lb && rb <= r) {
        adde(x, id1[p]);
        adde(id2[p], opp(x));
    }
    else {
        int mid = (lb + rb) >> 1;
        if (l < mid) adde(l, r, x, p << 1, lb, mid);
        if (r > mid) adde(l, r, x, p << 1 | 1, mid, rb);
    }
}

int dfn[M], low[M], bel[M], dfc, scc;
bool inst[M]; int scs[M], *sct = scs;
void scc_clr(int n) { scc = 0; fill(dfn + 1, dfn + n + 1, 0); }
int dfs_scc(int u) {
    *sct++ = u; inst[u] = 1;
    dfn[u] = low[u] = ++dfc;
    for (int v : g[u]) {
        if (!dfn[v]) low[u] = min(low[u], dfs_scc(v));
        else if (inst[v]) low[u] = min(low[u], low[v]);
    }
    if (dfn[u] == low[u])
        for (++scc; *sct != u; --sct)
            bel[sct[-1]] = scc, inst[sct[-1]] = 0;
    return low[u];
}

bool check(int d, int n) {
    int m = 2 * n;
    nc = m;
    for (int i = 1; i <= m; ++i)
        g[i].clear();
    build(1, 1, m + 1);
    //cout << string(79, '-') << endl;
    for (int i = 1; i <= m; ++i) {
        int lx = pos[i].first - d, rx = pos[i].first + d;
        int l = upper_bound(pos + 1, pos + m + 1, piii(lx, pii(inf,inf))) - pos;
        int r = lower_bound(pos + 1, pos + m + 1, piii(rx, pii(0,0))) - pos;
        int x = pos[i].second.first;
        adde(l, i, x, 1, 1, m + 1);
        adde(i + 1, r, x, 1, 1, m + 1);
    }
    //cout << string(79, '=') << endl;
    scc_clr(nc);
    for (int i = 1; i <= nc; ++i)
        if (!dfn[i]) dfs_scc(i);

    for (int i = 1; i <= m; ++i) {
        if (i & 1) {
            if (bel[i] == bel[i + 1])
                return false;
        }
    }
    return true;
}

