const int N = 20005;

int a[10005], b[10005];
vector<int> g[N], st;
int sta[N], dfn[N], low[N], lay, scc;

void init(int n)
{
  for (int i = 1; i <= n; i ++) g[i].clear();
  lay = scc = 0;
  memset(sta, 0, sizeof(sta));
  memset(dfn, 0, sizeof(dfn));
  memset(low, 0, sizeof(low));
  st.clear ();
}

void dfs(int u)
{
  sta[u] = 1;
  dfn[u] = low[u] = ++lay;
  st.push_back(u);
  for (auto v : g[u]) {
    if (sta[v] == 0) dfs(v);
    if (sta[v] == 1) low[u] = min(low[u], low[v]);
  } 
  if (low[u] == dfn[u]){
    scc ++;
    while (true) {
      int v = st.back();
      st.pop_back();
      low[v] = scc;
      sta[v] = 2;
      if (v == u) break;
    };
  }
}

int tarjan(int n)
{
  for (int i = 1; i <= n; i ++) {
    if (!sta[i]) dfs(i);
  }
  return scc;
}

int check(int mid, int n)
{
  init(2*n);
  for (int i = 1; i <= n; i ++) {
    for (int j = i+1; j <= n; j ++) {
      if (abs(a[i] - a[j]) < mid) {
        g[i].push_back(j+n);
        g[j].push_back(i+n);
      } 
      if (abs(a[i] - b[j]) < mid) {
        g[i].push_back(j);
        g[j+n].push_back(i+n);
      }
      if (abs(b[i] - a[j]) < mid) {
        g[i+n].push_back(j+n);
        g[j].push_back(i);
      }
      if (abs(b[i] - b[j]) < mid) {
        g[i+n].push_back(j);
        g[j+n].push_back(i);
      }
    }
  }
  tarjan(2*n);
  for (int i = 1; i <= n; i ++) {
    if (low[i] == low[i+n]) {
      return false;
    }
  }
  return true;
}

