void tarjan(int u)
{
	dfn[u]=low[u]=++ids;
	s.push(u);
	for(int i=head[u];i;i=nxt[i])
	{
		int v=to[i];
		if(!dfn[v])
		{
			int v=to[i];
			tarjan(v);
			low[u]=min(low[v],low[u]);
