const int mod = 1e9 + 7;

struct strongly_connected{
	vector<int> gph[MAXN];
	vector<int> rev[MAXN];
	vector<int> dfn;
	int vis[MAXN], comp[MAXN];
	void clear(){
		memset(vis, 0, sizeof(vis));
		memset(comp, 0, sizeof(comp));
		dfn.clear();
		for(int i=0; i<MAXN; i++){
			gph[i].clear();
			rev[i].clear();
		}
	}
	void add_edge(int x, int y){ 
		gph[x].push_back(y);
		rev[y].push_back(x);
	}
	void dfs(int x){
		if(vis[x]) return;
		vis[x] = 1;
		for(auto &i : gph[x]) dfs(i);
		dfn.push_back(x);
	}
	void rdfs(int x, int p){
		if(comp[x]) return;
		comp[x] = p;
		for(auto &i : rev[x]) rdfs(i, p);
	}
	int get_scc(int n){
		int piv = 0;
		for(int i=0; i<n; i++) if(!vis[i]) dfs(i);
		reverse(dfn.begin(), dfn.end());
		for(auto &i : dfn) if(!comp[i]) rdfs(i, ++piv);
		return piv;
	}
};

struct twosat{
	strongly_connected scc;
	int n; // = number of clauses
	void init(int _n){ scc.clear(); n = _n; }
	int NOT(int x){ return x >= n ? (x - n) : (x + n); }
	void add_edge(int x, int y){ // input ~x to denote NOT
		if((x >> 31) & 1) x = (~x) + n;
		if((y >> 31) & 1) y = (~y) + n;
		scc.add_edge(x, y), scc.add_edge(NOT(y), NOT(x));
	}
	bool satisfy(vector<bool> &res){
		res.resize(n);
		scc.get_scc(2*n);
		for(int i=0; i<n; i++){
			if(scc.comp[i] == scc.comp[NOT(i)]) return 0;
			if(scc.comp[i] < scc.comp[NOT(i)]) res[i] = 0;
			else res[i] = 1;
		}
		return 1;
	}
}twosat;

int n;
struct pnt{ int pos, idx; }a[MAXN];

struct seg{
	int vtx_cnt = 0;
	int lim;
	int tree[MAXT];
	void init(int n){
		for(lim = 1; lim <= n; lim <<= 1);
		vtx_cnt = n / 2;
		for(int i=1; i<2*lim; i++){
			tree[i] = vtx_cnt++;
		}
		twosat.init(vtx_cnt);
		for(int i=2; i<2*lim; i++) twosat.add_edge(tree[i/2], tree[i]);
		for(int i=0; i<n; i++) twosat.add_edge(tree[i + lim], ~a[i].idx);
	}
	void query(int src, int s, int e){
		s += lim;
		e += lim;
		while(s < e){
			if(s % 2 == 1) twosat.add_edge(src, tree[s++]);
			if(e % 2 == 0) twosat.add_edge(src, tree[e--]);
			s >>= 1;
			e >>= 1;
		}
		if(s == e) twosat.add_edge(src, tree[s]);
	}
}seg;

bool trial(int l){
	int s = 0;
	seg.init(n*2);
	for(int i=0; i<2*n; i++){
		while(s < 2 * n && a[s].pos <= a[i].pos - l) s++;
		seg.query(a[i].idx, s, i - 1);
	}
	vector<bool> ok;
	return twosat.satisfy(ok);
}


