void add(int beg, int end, int node, int lb, int ub, int pl)
{
	if (end < lb || ub < beg)return;
	if (beg <= lb&&ub <= end)
	{
		sat.adde(pl, false, node, false);
		return;
	}
	add(beg, end, node * 2, lb, (lb + ub) / 2, pl);
	add(beg, end, node * 2 + 1, (lb + ub) / 2 + 1, ub, pl);
}
bool isok(vector<pii>v, vector<pii>zat, int med)
{
	sat.init(80000);
	for (int i = 1; i < (1 << 15); i++)sat.adde(i * 2, false, i, true), sat.adde(i * 2 + 1, false, i, true);
	int lb = 0, ub = 0;
	for (int i = 0; i < zat.size(); i++)
	{
		for (;;)
		{
			if (zat[lb].first <= zat[i].first - med)lb++;
			else break;
		}
		for (;;)
		{
			if (ub == zat.size())break;
			if (zat[ub].first >= zat[i].first + med)break;
			else ub++;
		}
		add(lb, i - 1, 1, 0, (1 << 15) - 1, (1 << 15) + i);
		add(i + 1, ub - 1, 1, 0, (1 << 15) - 1, (1 << 15) + i);
	}
	for (int i = 0; i < v.size(); i++)
	{
		int l1 = lower_bound(zat.begin(), zat.end(), make_pair(v[i].first, i + 1)) - zat.begin();
		int l2 = lower_bound(zat.begin(), zat.end(), make_pair(v[i].second, -i - 1)) - zat.begin();
		sat.adde((1 << 15) + l1, true, (1 << 15) + l2, true);
	}
	sat.scc();
	return sat.issatisfiable();
}
