void dfs1(int v) {
    used[v] = 1;
    for(auto u: g[v])
        if(!used[u])
            dfs1(u);
    order.push_back(v);
}

void dfs2(int v, int col) {
    color[v] = col;
    for(auto u: gt[v])
        if(!color[u])
            dfs2(u, col);
}

bool check(int d) {
    for(int i = 0; i < 2 * n; i++) {
        g[i].clear();
        gt[i].clear();
    }
    used.assign(2 * n, 0);
    order.clear();
    for(int i = 0; i < 2 * n; i++) {
        for(int j = 0; j < 2 * n; j += 2) {
            if(i == j || i == j + 1)
                continue;
            bool ok1 = abs(a[i] - a[j]) >= d;
            bool ok2 = abs(a[i] - a[j ^ 1]) >= d;
            if(ok1 ^ ok2) {
                if(ok1) {
                    g[i].push_back(j);
                    gt[j].push_back(i);
                }
                else {
                    g[i].push_back(j ^ 1);
                    gt[j ^ 1].push_back(i);
                }
            }
            else if(!ok1 && !ok2) {
                g[i].push_back(i ^ 1);
                gt[i ^ 1].push_back(i);
            }
        }
    }
    for(int i = 0; i < 2 * n; i++)
        if(!used[i])
            dfs1(i);
    color.assign(2 * n, 0);
    int col = 1;
    reverse(order.begin(), order.end());
    for(auto x: order) {
        if(!color[x]) {
            dfs2(x, col);
            col++;
        }
    }
    for(int i = 0; i < 2 * n; i += 2) {
        if (color[i] == color[i ^ 1])
            return false;
    }
    return true;
}

