			low[x] = std::min(low[x], low[y]);
		}
		else if (u[y]) low[x] = std::min(low[x], dfn[y]);
	}
	if (low[x] == dfn[x]) {
		++col;
		for (; stack[top] != x; u[stack[top--]] = 0) c[stack[top]] = col;
		c[x] = col; u[x] = 0; top--;
	}
}
