void build(int o, int L, int R) {
	G[o].clear();
	be[o] = dfn[o] = low[o] = 0;
	if (o > 1) {
		G[o].push_back(o / 2);
		// cout << o << "->" << o / 2 << endl;
	}
	if (L + 1 == R) {
		g[h[L] ^ 1] = o;
		return;
	}
	build(ls, L, mid);
	build(rs, mid, R);
}
void update(int o, int L, int R, int l, int r, int v) {
	if (l <= L && R <= r) {
		G[o].push_back(v);
		// cout << o << "->" << v << endl;
		return;
	}
	if (l < mid) update(ls, L, mid, l, r, v);
	if (r > mid) update(rs, mid, R, l, r, v);
}
void trjan(int x) {
	// cout << x << " ";
	low[x] = dfn[x] = ++tim;
	st.push(x);
	in[x] = 1;
	for (auto &i : G[x]) {
		if (!dfn[i]) {
			trjan(i);
			low[x] = min(low[x], low[i]);
		} else if (in[i])
			low[x] = min(low[x], dfn[i]);
	}
	if (low[x] == dfn[x]) {
		int y;
		num++;
		do {
			y = st.top();
			st.pop();
			be[y] = num;
			in[y] = false;
		} while (x != y);
	}
}
