#include <bits/stdc++.h>

const int MAXN = 10010;
const int MAXP = 1000010;
const int MAXE = MAXP * 10;
int head[MAXP], nxt[MAXE], to[MAXE], tot;
void addedge(int b, int e) {
	nxt[++tot] = head[b]; to[head[b] = tot] = e;
}
int dfn[MAXP], st[MAXP], top, ins[MAXP], low[MAXP], bel[MAXP], t0t, txt;
void tarjan(int u) {
	dfn[u] = low[u] = ++txt;
	ins[st[++top] = u] = true;
	for (int i = head[u]; i; i = nxt[i])
		if (!dfn[to[i]]) {
			tarjan(to[i]);
			low[u] = std::min(low[u], low[to[i]]);
		} else if (ins[to[i]]) low[u] = std::min(low[u], dfn[to[i]]);
	if (low[u] == dfn[u]) {
		int v; ++t0t;
		do ins[v = st[top--]] = false, bel[v] = t0t; while (v != u);
	}
}
int idx, vs[2][MAXN];
int map[MAXN][2];
int n;
struct seg {
	int in[MAXN << 2], out[MAXN << 2];
	void build(int * rk1, int * rk2, int u = 1, int l = 1, int r = n) {
		in[u] = ++idx, out[u] = ++idx;
		if (l == r) return addedge(in[u], rk1[l]), addedge(rk2[l], out[u]);
		int mid = l + r >> 1;
		build(rk1, rk2, u << 1, l, mid); build(rk1, rk2, u << 1 | 1, mid + 1, r);
		addedge(in[u], in[u << 1]); addedge(in[u], in[u << 1 | 1]);
		addedge(out[u << 1], out[u]); addedge(out[u << 1 | 1], out[u]);
	}
	void mdf(int L, int R, int t, int b, int u = 1, int l = 1, int r = n) {
		if (L <= l && r <= R)
			return b ? addedge(out[u], t) : addedge(t, in[u]);
		if (L > R) return ;
		int mid = l + r >> 1;
		if (L <= mid) mdf(L, R, t, b, u << 1, l, mid);
		if (mid < R) mdf(L, R, t, b, u << 1 | 1, mid + 1, r);
	}
} sg, si;
int rk[MAXN], tmp1[MAXN], tmp2[MAXN], fin[MAXN];
int at[MAXN];
bool solve(int lim) {
	memset(dfn, 0, idx + 1 << 2);
	memset(head, 0, idx + 1 << 2);
	txt = t0t = tot = idx = 0;
	for (int i = 1; i <= n; ++i)
		for (int j = 0; j < 2; ++j)
			map[i][j] = ++idx;
	for (int X = 0; X < 2; ++X)
	for (int Y = 0; Y < 2; ++Y) {
		int * vl = vs[Y];
		for (int i = 1; i <= n; ++i) rk[i] = i;
		std::sort(rk + 1, rk + 1 + n, [vl] (int a, int b) { return vl[a] < vl[b]; });
		for (int i = 1; i <= n; ++i) fin[i] = vl[rk[i]], at[rk[i]] = i;
		for (int i = 1; i <= n; ++i) tmp1[i] = map[rk[i]][Y ^ 1], tmp2[i] = map[rk[i]][Y];
		sg.build(tmp1, tmp2);
		for (int i = 1; i <= n; ++i) {
			int V = vs[X][i], u = at[i];
			int l = std::lower_bound(fin + 1, fin + 1 + n, V - lim + 1) - fin;
			int r = std::upper_bound(fin + 1, fin + 1 + n, V + lim - 1) - fin - 1;
			if (l > r) continue;
			l = std::max(l, 1); r = std::min(r, n);
			if (l <= u && u <= r) {
				sg.mdf(l, u - 1, map[i][X], 0); sg.mdf(l, u - 1, map[i][X ^ 1], 1);
				sg.mdf(u + 1, r, map[i][X], 0); sg.mdf(u + 1, r, map[i][X ^ 1], 1);
			} else {
				sg.mdf(l, r, map[i][X], 0); sg.mdf(l, r, map[i][X ^ 1], 1);
			}
		}
	}
	for (int i = 1; i <= idx; ++i) if (!dfn[i]) tarjan(i);
	for (int i = 1; i <= n; ++i) if (bel[map[i][0]] == bel[map[i][1]])
		return false;
	return true;
}
int main() {
	std::ios_base::sync_with_stdio(false), std::cin.tie(0);
	std::cin >> n;
	for (int i = 1; i <= n; ++i) std::cin >> vs[0][i] >> vs[1][i];
	int l = 0, r = 1e9, ans = 0;
	while (l <= r) {
		int mid = l + r >> 1;
		if (solve(mid)) l = mid + 1, ans = mid; else r = mid - 1;
	}
	std::cout << ans << std::endl;
	return 0;
}

