            max(abs(b[i] - a[j]), abs(b[i] - b[j]))));
    }
  }
  while (low <= high) {
    int mid = (low + high)/2;
    if (check(mid, n)) {
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }  
  cout << high << endl;
  return 0;
}

