class InputReader {
public:
    InputReader() {
        input_file = stdin;
        cursor = 0;
        fread(buffer, SIZE, 1, input_file);
    }
    inline InputReader &operator >>(int &n) {
        while(buffer[cursor] < '0' || buffer[cursor] > '9') {
            advance();
        }
        n = 0;
        while('0' <= buffer[cursor] && buffer[cursor] <= '9') {
            n = n * 10 + buffer[cursor] - '0';
            advance();
        }
        return *this;
    }
private:
    FILE *input_file;
    static const int SIZE = 1 << 17;
    int cursor;
    char buffer[SIZE];
    inline void advance() {
        ++ cursor;
        if(cursor == SIZE) {
            cursor = 0;
            fread(buffer, SIZE, 1, input_file);
        }
    }
};

const int NMAX = 10005;

int N;
vector <pair <int, int> > graph[2 * NMAX];
vector <pair <int, int> > graph_inv[2 * NMAX];

#define graph (graph + NMAX)
#define graph_inv (graph_inv + NMAX)

void add_edge(int a, int b, int tmp) {
    graph[-a].push_back(make_pair(b, tmp));
    graph[-b].push_back(make_pair(a, tmp));

    graph_inv[a].push_back(make_pair(-b, tmp));
    graph_inv[b].push_back(make_pair(-a, tmp));
}

int h[2 * NMAX];

bool vis[3 * NMAX];
#define vis (vis + NMAX)

int pos;
int BOUND;

void dfs_inv(int node) {
    vis[node] = true;
    for (auto it: graph_inv[node])
        if (it.second < BOUND && !vis[it.first])
            dfs_inv(it.first);
    h[++ pos] = node;
}

int which_comp[2 * NMAX];
#define which_comp (which_comp + NMAX)

bool nasol;

void dfs(int node, int comp) {
    if (nasol)
        return ;
    vis[node] = true;
    which_comp[node] = comp;

    if (vis[-node] && which_comp[-node] == comp) {
        nasol = true;
        return ;
    }

    for (auto it: graph[node])
        if (it.second < BOUND && !vis[it.first])
            dfs(it.first, comp);
}

bool works(int cnt) {
    BOUND = cnt;
    nasol = false;
    for (int i = -N; i <= N; ++ i)
        vis[i] = 0;
    pos = 0;
    for (int i = -N; i <= N; ++ i)
        if (i && !vis[i])
            dfs_inv(i);
    for (int i = -N; i <= N; ++ i)
        vis[i] = 0;

    int comp = 0;
    for (int i = pos; i && !nasol; -- i)
        if (!vis[h[i]])
            dfs(h[i], ++ comp);
    return !nasol;
}

int x[NMAX];
int y[NMAX];

void build() {
    //clr();
    for (int i = 1; i <= N; ++ i)
        for (int j = i + 1; j <= N; ++ j) {
            add_edge(-i, -j, abs(x[i] - x[j]));
            add_edge(-i, j, abs(x[i] - y[j]));
            add_edge(i, -j, abs(y[i] - x[j]));
            add_edge(i, j, abs(y[i] - y[j]));
        }
}

