		}else if(instack[e[i].to]){
			if(dfn[e[i].to]<low[x]) low[x]=dfn[e[i].to];
		}
	if(dfn[x]==low[x]){
		++numc;
		while(S.top()!=x){
			instack[S.top()]=0;
			c[S.top()]=numc;
			S.pop();
		}
		instack[S.top()]=0;
		c[S.top()]=numc;
		S.pop();
	}
}

