	{
		add(w + 20000, pp[p[l].second][pp[p[l].second][0] == l]);
		return 0;
	}
	int mid = (l + r) / 2;
	mtree(2 * w, l, mid);
	mtree(2 * w + 1, mid + 1, r);
	add(w + 20000, 2 * w + 20000);
	add(w + 20000, 2 * w + 20001);
	return 0;
