int tadd(int w, int l, int r, int x, int y, int v)
{
	if (x <= l && r <= y)
	{
		add(v, w + 20000);
		return 0;
	}
	int mid = (l + r) / 2;
	if (x <= mid)tadd(2 * w, l, mid, x, y, v);
	if (y > mid)tadd(2 * w + 1, mid + 1, r, x, y, v);
	return 0;
