void build(int x = 1, int l = 1, int r = n << 1)
{
	if (l == r) return (void) (id[x] = t[l].second);
	int mid = (l + r) >> 1, ls = x << 1, rs = ls | 1; id[x] = ++cur;
	build(ls, l, mid), build(rs, mid + 1, r);
	G[id[x]].push_back(id[ls]), G[id[x]].push_back(id[rs]);
}

void Link(int ql, int qr, int t, int x = 1, int l = 1, int r = n << 1)
{
	if (ql > qr) return;
	if (ql <= l && r <= qr) return G[t].push_back(id[x]);
	int mid = (l + r) >> 1, ls = x << 1, rs = ls | 1;
	if (ql <= mid) Link(ql, qr, t, ls, l, mid);
	if (mid < qr) Link(ql, qr, t, rs, mid + 1, r);
}

void tarjan(int x)
{
	dfn[x] = low[x] = ++cnt, stk[++top] = x;
	for (auto i : G[x])
		if (!dfn[i]) tarjan(i), low[x] = std::min(low[x], low[i]);
		else if (!bel[i]) low[x] = std::min(low[x], dfn[i]);
	if (dfn[x] == low[x]) { ++col; do { bel[stk[top]] = col; } while (stk[top--] != x); }
}

int check(int mid)
{
	for (int i = 1; i <= cur; i++) G[i].clear();
	memset(dfn, 0, sizeof dfn), memset(low, 0, sizeof low), memset(bel, 0, sizeof bel);
	cnt = top = 0, cur = n << 1; build();
	for (int i = 1; i <= n; i++)
		for (int j = 0; j < 2; j++)
		{
			int l = std::lower_bound(t + 1, t + (n << 1) + 1, std::make_pair(A[j][i] - mid + 1, 0)) - t;
			int r = std::upper_bound(t + 1, t + (n << 1) + 1, std::make_pair(A[j][i] + mid - 1, n << 1 | 1)) - t - 1;
			int _ = std::lower_bound(t + 1, t + (n << 1) + 1, std::make_pair(A[j][i], i + (j ^ 1) * n)) - t;
			Link(l, _ - 1, i + j * n), Link(_ + 1, r, i + j * n);
		}
	for (int i = 1; i <= cur; i++) if (!dfn[i]) tarjan(i);
	for (int i = 1; i <= n; i++) if (bel[i] == bel[i + n]) return 0;
	return 1;
}

