	inline void pushup(int rt){size[rt]=size[son[rt][0]]+size[son[rt][1]]+1;}
	inline void split(int rt,int k,int &x,int &y)
	{
		if(!rt){x=y=0;return;}
		else if(val[rt]<=k)x=rt,split(son[rt][1],k,son[rt][1],y);
		else y=rt,split(son[rt][0],k,x,son[rt][0]);
