	{
		if(!a||!b)return a+b;
		if(rnd[a]<rnd[b]){son[a][1]=merge(son[a][1],b);pushup(a);return a;}
		else {son[b][0]=merge(a,son[b][0]);pushup(b);return b;}
	}
	inline int newnode(int k){size[++Size]=1;val[Size]=k;rnd[Size]=rand();return Size;}
