int build(int l , int r) {
	L[++ all] = l; R[all] = r;
	if(l == r) {
		link(lc(all) , P[l].id ^ 1);
		return all;
	}
	int cur = all;
	int mid = (l + r) >> 1;
	Lc[cur] = build(l , mid);
	Rc[cur] = build(mid + 1 , r);
	link(lc(cur) , lc(Lc[cur]));
	link(lc(cur) , lc(Rc[cur]));
	return cur;
}

void addtag(int no , int wh , int l , int r) {
	if(L[no] == l && R[no] == r) {
		link(wh , lc(no)); return;
	}
	int mid = (L[no] + R[no]) >> 1;
	if(l > mid) addtag(Rc[no] , wh , l , r);
	else if(r <= mid) addtag(Lc[no] , wh , l , r);
	else {
		addtag(Lc[no] , wh , l , mid); addtag(Rc[no] , wh , mid + 1 , r);
	}
}

