		if(i + 1 <= r)
		addtag(rt , P[i].id , i + 1 , r);
	}
}

#define Foreachson(i , x) for(int i = fir[x];i;i = ne[i])
bool die = 0;

void dfs(int x) {
	if(die) return;
	low[x] = dfn[x] = ++ dfs_clock; stk[++ top] = x;
	Foreachson(i , x) {
		int V = to[i];
		if(dfn[V]) {
			if(!scc_no[V])low[x] = min(low[x] , low[V]);
		}
		else {
			dfs(V); low[x] = min(low[x] , low[V]);
		}
	}
	if(low[x] == dfn[x]) {
		col ++;
		for(;;) {
			scc_no[stk[top --]] = col;
			if(scc_no[stk[top + 1]] == scc_no[stk[top + 1] ^ 1]) {
				die = 1; return;
			}
			if(stk[top + 1] == x) break;
		}
	}
}

bool SAT(void) {
	die = 0;
	memset(dfn , 0 , sizeof(dfn)); memset(low , 0 , sizeof(low)); memset(scc_no , 0 , sizeof(scc_no)); top = col = dfs_clock = 0;
	for(int i = 2;i <= rc(tot);i ++) {
		if(!dfn[i]) dfs(i);
		if(die) return 0;
	}
	for(int i = 1;i <= rc(tot);i ++) {
		if(scc_no[lc(i)] == scc_no[rc(i)]) return 0;
	}
	return 1;
}

bool pd(int x) {
	Build(x);
	return SAT();
