	for(int i = whe[l] + 1 - (l ==mi[whe[l]]);i <= whe[r] - 1 + (r == mx[whe[r]]);i ++) link(it , lc(i));
	if(l != mi[whe[l]])for(int i = l;i <= mx[whe[l]];i ++) link(it , P[i].id ^ 1);
	if(r != mx[whe[r]])for(int i = mi[whe[r]];i <= r;i ++) link(it , P[i].id ^ 1);
}

