		while(abs(P[l].val - P[i].val) >= cur && l < i) l ++;
		while(r < tot && abs(P[r + 1].val - P[i].val) < cur) r ++;
		addtag(P[i].id , l , i - 1);
		addtag(P[i].id , i + 1 , r);
	}
