int B, Bnum, V;
vector<int> G[25005];
vector<int> revG[20005];

bool used[25005];
vector<int> topo;
int scc[25005];

void tpsort(int v, int prev)
{
	used[v] = true;
	for(int i = 0; i < G[v].size(); i++){
		if(used[G[v][i]]) continue;
		tpsort(G[v][i], v);
	}
	topo.push_back(v);
}

void dfs(int v, int prev, int id)
{
	used[v] = true;
	scc[v] = id;
	for(int i = 0; i < revG[v].size(); i++){
		if(used[revG[v][i]]) continue;
		dfs(revG[v][i], v, id);
	}
}

void range(int v, int l, int r)
{
	if(l > r) return;
	int ll = (l+B-1)/B*B, rr = r/B*B;
	if(ll <= rr){
		for(int i = ll/B; i < rr/B; i++){
			G[v].push_back(2*N+i);
		}
		for(int i = l; i < ll; i++){
			int u = vec[i].second.first + (1-vec[i].second.second)*N;
			G[v].push_back(u);
		}
		for(int i = rr; i < min(r+1, 2*N); i++){
			int u = vec[i].second.first + (1-vec[i].second.second)*N;
			G[v].push_back(u);
		}
	}
	else{
		for(int i = l; i <= r; i++){
			int u = vec[i].second.first + (1-vec[i].second.second)*N;
			G[v].push_back(u);
		}
	}
}

bool check(int d)
{
	for(int i = 0; i < V; i++) G[i].clear();
	for(int i = 0; i < 2*N; i++){
		int v = vec[i].second.first + (1-vec[i].second.second)*N;
		G[2*N+i/B].push_back(v);
	}
	for(int i = 0; i < 2*N; i++){
		int v = vec[i].second.first + vec[i].second.second*N;
		int l = lower_bound(vec.begin(), vec.end(), make_pair(vec[i].first - (d-1), make_pair(-1, -1))) - vec.begin();
		int r = lower_bound(vec.begin(), vec.end(), make_pair(vec[i].first + d, make_pair(-1, -1))) - vec.begin() - 1;
		range(v, l, i-1);
		range(v, i+1, r);
	}

	for(int i = 0; i < V; i++) revG[i].clear();
	for(int i = 0; i < V; i++){
		for(int j = 0; j < G[i].size(); j++){
			revG[G[i][j]].push_back(i);
		}
	}

	for(int i = 0; i < V; i++) used[i] = false;
	topo.clear();
	for(int i = 0; i < V; i++) if(!used[i]) tpsort(i, -1);
	reverse(topo.begin(), topo.end());

	for(int i = 0; i < V; i++) used[i] = false;
	for(int i = 0; i < topo.size(); i++){
		if(!used[topo[i]]) dfs(topo[i], -1, i);
	}

	for(int i = 0; i < N; i++){
		if(scc[i] == scc[i+N]) return false;
	}
	return true;
}

int main(void)
{
	cin >> N;
	for(int i = 0; i < N; i++) cin >> x[i] >> y[i];

	for(int i = 0; i < N; i++){
		vec.push_back(make_pair(x[i], make_pair(i, 0)));
