typedef pair<int,int> pii;
int main(){
	int N;
	vector<pii> mp;
	SegTree<int> sg(20005);

	cin >> N;
	rep(i,N){
		int x, y;
		cin >> x >> y;
		mp.emplace_back( x, i+1 );
		mp.emplace_back( y, -(i+1) );
	}
	sort( mp.begin(), mp.end() );

	auto fn = [&](int m){
		//cout << "fn " << m << endl;
		sat.clear();
		sg.pRelation();
		rep(i, mp.size()) sg.cRelation(i, mp[i].second);
		// range relation
		rep(i, mp.size()){
			// down
			auto it = lower_bound(mp.begin(), mp.end(), pii(mp[i].first - m + 1, -INF));
			int pos = (it - mp.begin());
			sg.add( pos, i, i );
			// up
			it = lower_bound(mp.begin(), mp.end(),  pii(mp[i].first + m, -INF));
			pos = (it - mp.begin());
			sg.add( i+1, pos, i );
		}
		//cout << "setup finish" << endl;
		bool ret = sat.solve();
		//cout << "ret: " << ret << endl;
		return ret;
	};

	int l=0, r=1e9;
	while( r-l > 1 ){
		int m = (l+r) / 2;
		if( fn(m) ){
			l = m;
		}else{
			r = m;
		}
	}

	cout << l << endl;

	return 0;
}

