namespace SEGT
{

int bias, size, root;
int lc[SIZE], rc[SIZE];

void insert(int &u, int f, LL l, LL r, LL p, int x)
{
    if (!u) {
        u = ++size;
        // printf("newnode %d (%lld,%lld) (%lld, %d)\n", u, l, r, p, x);
        lc[u] = rc[u] = 0;
        G[bias + u].clear();
        if (f)
            G[bias + f].push_back(bias + u);
    }
    if (l == r) {
        G[bias + u].push_back(x);
        return;
    }
    LL mid = (l + r) / 2;
    if (p <= mid)
        insert(lc[u], u, l, mid, p, x);
    else
        insert(rc[u], u, mid + 1, r, p, x);
}

void link(int u, LL l, LL r, LL ql, LL qr, int x)
{
    // printf("link(%d,%lld,%lld,%lld,%lld,%d)\n", u, l, r, ql, qr, x);
    if (!u)
        return;
    if (ql <= l && r <= qr) {
        G[x].push_back(bias + u);
        return;
    }
    LL mid = (l + r) >> 1;
    if (ql <= mid)
        link(lc[u], l, mid, ql, qr, x);
    if (mid < qr)
        link(rc[u], mid + 1, r, ql, qr, x);
}

}

inline void insert(LL p, int i, int u)
{
    SEGT::insert(SEGT::root, 0, 0, N * RNG + N, N * p + i, u);
}

inline void link(int d, LL p, int i, int u)
{
    LL l = N * (p - d), m = N * p + i, r = N * (p + d) + N - 1;
    if (l < m)
        SEGT::link(SEGT::root, 0, N * RNG + N, l, m - 1, u);
    if (m < r)
        SEGT::link(SEGT::root, 0, N * RNG + N, m + 1, r, u);
}

bool check(int d)
{
    SEGT::size = SEGT::root = 0;
    SEGT::bias = N * 2 - 1;

    for (int i = 0; i < N * 2; ++i) {
        G[i].clear();
    }
    for (int i = 0; i < N; ++i) {
        insert(A[i].x, i, i * 2 + 1);
        insert(A[i].y, i, i * 2);
    }
    for (int i = 0; i < N; ++i) {
        link(d, A[i].x, i, i * 2);
        link(d, A[i].y, i, i * 2 + 1);
    }

    int V = N * 2 + SEGT::size;
    dfsclock = totscc = 0;
    std::fill(dfn, dfn + V, 0);
    std::fill(sccid, sccid + V, 0);

    for (int i = 0; i < V; ++i) {
        if (!dfn[i])
            dfs(i);
    }
    for (int i = 0; i < N; ++i) {
        // printf("%d %d\n", sccid[i * 2], sccid[i * 2 + 1]);
        if (sccid[i * 2] == sccid[i * 2 + 1])
            return false;
    }
    return true;
}

void solve()
{
    int l = -1, r = RNG / N + 5;
    while (l + 1 < r) {
        int mid = (l + r) >> 1;
        // printf("[%d %d), mid=%d\n", l, r, mid);
        if (check(mid))
            l = mid;
        else
            r = mid;
    }

    printf("%d\n", l + 1);
}

int main()
{
