struct rmq {
	int t[20010 * 4];
	rmq () {
		memset(t, 0, sizeof t);
	}
	void update(int x, int val, int c, int b, int e) {
		if(b == e) {
			t[c] = val;
			return ;
		}
		int m = (b + e) >> 1;
		int l = c << 1;
		int r = l + 1;
		if(x <= m) update(x, val, l, b, m);
		else update(x, val, r, m+1, e);
		t[c] = min(t[l], t[r]); 
	}
	int query(int x, int y, int c, int b, int e) {
		if(x <= b && e <= y) {
			return t[c];
		}
		if(y < b || e < x) return inf;
		int m = (b + e) >> 1;
		int l = c << 1;
		int r = l + 1;
		return min(query(x, y, l, b, m), query(x, y, r, m + 1, e));
	}
	int query(int x, int y) {
		if(x > y) return inf;
		return query(x, y, 1, 0, maxn);
	}
	void update(int x, int val) {
		update(x, val, 1, 0, maxn);
	}
