void transpose(int x, int mark) {
	birth[x] = mark;
	vis[x] = true;
	if(x % 2 == 0) {
		T.update(id[x >> 1], inf);
	}
	for(auto i : t[x]) {
		if(vis[i] == false) {
			transpose(i, mark);
		}
	}
	if(x & 1) {
		int idx = id[x >> 1];
		int bef = prev(idx, D);
		int aft = next(idx, D);
		if(bef < idx) {
			while(true) {
				int node = T.query(bef, idx - 1);
				if(node == inf) break;
				node <<= 1;
				transpose(node, mark);
			}
		}
		if(idx < aft) {
			while(true) {
				int node = T.query(idx + 1, aft);
				if(node == inf) break;
				node <<= 1;
				transpose(node, mark);
			}
		}
	}
}

