struct SCC {
    int V;
    vector<vi> G, rG;
    vector<int> vs, used, cmp;
    SCC(const vector<vi>& g) : V(g.size()), G(g), rG(V), used(V), cmp(V) {
        for (int i = 0; i < V; i++) for (int u : G[i]) rG[u].push_back(i);
    }
    void dfs(int v) {
        used[v] = 1;
        for (int u : G[v]) if (!used[u]) dfs(u);
        vs.push_back(v);
    }
    void rdfs(int v, int k) {
        used[v] = 1;
        cmp[v] = k;
        for (int u : rG[v]) if (!used[u]) rdfs(u, k);
    }
    int calc() {
        fill(used.begin(), used.end(), 0);
        vs.clear();
        for (int v = 0; v < V; v++) {
            if (!used[v]) dfs(v);
        }
        fill(used.begin(), used.end(), 0);
        int k = 0;
        for (int i = vs.size()-1; i >= 0; i--) {
            if (!used[vs[i]]) rdfs(vs[i], k++);
        }
        return k;
    }
};

const int MAXN = 11010;
int X[MAXN], Y[MAXN];

// 変数割り当ては 
// [0, N): Xi
// [N, 2N): not Xi
// [2N, 3N): Yi
// [3N, 4N): not Yi
// [4N, 6N): Si
// [6N, 8N): not Si
bool isOK(int x, int N) {
	vector<vi> G(8*N);
	for (int i = 0; i < N; i++) {
		G[i].push_back(i+3*N);
		G[i+2*N].push_back(i+N);
		G[i+N].push_back(i+2*N);
		G[i+3*N].push_back(i);
	}
	for (int i = 0; i < N; i++) {
		for (int j = i+1; j < N; j++) {
			if (abs(X[i]-X[j]) < x) {
				G[i].push_back(j+N);
				G[j].push_back(i+N);
			}
			if (abs(X[i]-Y[j]) < x) {
				G[i].push_back(j+3*N);
				G[j+2*N].push_back(i+N);
			}
			if (abs(Y[i]-X[j]) < x) {
				G[i+2*N].push_back(j+N);
				G[j].push_back(i+3*N);
			}
			if (abs(Y[i]-Y[j]) < x) {
				G[2*N+i].push_back(j+3*N);
				G[2*N+j].push_back(i+3*N);
			}
		}
	}
	SCC scc(G);
	scc.calc();
	for (int i = 0; i < N; i++) {
		if (scc.cmp[i] == scc.cmp[i+N]) return false;
		if (scc.cmp[i+2*N] == scc.cmp[i+3*N]) return false;
	}
	return true;
}

int main() {
	int N;
	cin >> N;
	for (int i = 0; i < N; i++) {
		cin >> X[i] >> Y[i];
	}
	int low = 0, high = 1e9+7;
	while (high-low > 1) {
		const int med = (low+high)/2;
		if (isOK(med, N)) {
			low = med;
		} else high = med;	
	}
	cout << low << endl;
	return 0;
}

