void addEdge(int a, int b) {
    adj2[b].pb(a);
    adj[a].pb(b);
}

void dfs(int v) {
    u[v] = 1;

    for (int to : adj[v]) {
        if (u[to]) {
            continue;
        }

        dfs(to);
    }

    order.pb(v);
}

void dfs2(int v) {
    comp[v] = cur;

    for (int to : adj2[v]) {
        if (comp[to] != -1) {
            continue;
        }

        dfs2(to);
    }
}

int n;

bool check(int d) {
    for (int i = 0; i < n * 4; ++i) {
        adj2[i].clear();
        adj[i].clear();
        comp[i] = -1;
    }

    for (int i = 0; i < n; ++i) {
        int a = mm[i].fi * 2;
        int b = mm[i].se * 2;

        addEdge(a, b ^ 1);
        addEdge(b, a ^ 1);

        addEdge(a ^ 1, b);
        addEdge(b ^ 1, a);
    }

    for (int i = 0; i < n * 2; ++i) {
        for (int j = 0; j < n * 2; ++j) {
            if (i == j) {
                continue;
            }

            if (abs(vv[i].fi - vv[j].fi) < d) {
                int a = i * 2, b = j * 2;
                addEdge(a, b ^ 1);
            }
        }
    }

    for (int i = 0; i < n * 4; ++i) {
        u[i] = 0;
    }

    order.clear();
    cur = 0;

    for (int i = 0; i < n * 4; ++i) {
        if (u[i]) {
            continue;
        }

        dfs(i);
    }

    for (int i = 0; i < n * 4; ++i) {
        int v = order[n * 4 - i - 1];

        if (comp[v] == -1) {
            dfs2(v); ++cur;
        }
    }

    for (int i = 0; i < n * 4; ++i) {
        if (comp[i] == comp[i ^ 1]) {
            return 0;
        }
    }

    return 1;
}

void solve() {
    scanf("%d", &n);

    for (int i = 0; i < n; ++i) {
        scanf("%d %d", &arr[i].fi, &arr[i].se);

        vv.pb(mp(arr[i].fi, i));
        vv.pb(mp(arr[i].se, i));
    }

    sort(vv.begin(), vv.end());

    for (int i = 0; i < n; ++i) {
        mm[i] = mp(-1, -1);
    }

    for (int i = 0; i < n * 2; ++i) {
        int id = vv[i].se;

        if (mm[id].fi == -1) {
            mm[id].fi = i;
        }
        else {
            mm[id].se = i;
        }
    }

    int l = 0, r = 1e9, ans = -1;

    while (l <= r) {
        int mid = (l + r) >> 1;

        if (check(mid)) {
            l = mid + 1;
            ans = mid;
        }
        else {
            r = mid - 1;
        }
    }

    printf("%d", ans);
}

