inline void tarjan(int x){
	dfn[x]=low[x]=++tim;vis[x]=1;sta[++top]=x; 
	for(int i=h[x];i;i=mp[i].next){
		int y=mp[i].to;
		if(!dfn[y]){
			tarjan(y);
			low[x]=min(low[x],low[y]);
		}else if(vis[y]) low[x]=min(low[x],dfn[y]);
	}
	if(dfn[x]==low[x]){
		belong[x]=++scc;vis[x]=0;
		while(x!=sta[top]){
			belong[sta[top]]=scc;
			vis[sta[top--]]=0;
		}--top;
	}
}
