			int r=min(totnum,(int)(lower_bound(b+1,b+totnum+1,a[i<<1|j]+x)-b-1));
			ins(root,1,totnum,l,id[i<<1|j]-1,i<<1|j);
			ins(root,1,totnum,id[i<<1|j]+1,r,i<<1|j);
		}
