		link(b[i+i-1][0],b[i+i][1]),link(b[i+i][1],b[i+i-1][0]);
		link(b[i+i-1][1],b[i+i][0]),link(b[i+i][0],b[i+i-1][1]);
	}
	fo(i,1,rtn-1) L[i]=1+rtn*(i-1),R[i]=rtn*i;
