void build(int k,int l,int r){
	id[k]=++cc;
	if(l==r) return;
	int mid=l+r>>1;
	build(k<<1,l,mid);
	build(k<<1|1,mid+1,r);
	add(id[k],id[k<<1]);
	add(id[k],id[k<<1|1]);
}
void insert(int k,int l,int r,int x,int v){
	if(l==r){
		add(id[k],v);
		return;
	}
	int mid=l+r>>1;
	if(x<=mid) insert(k<<1,l,mid,x,v);
	else insert(k<<1|1,mid+1,r,x,v);
}
void query(int k,int l,int r,int L,int R,int x){
	if(L<=l&&R>=r){
		add(x,id[k]);
		return;
	}
	int mid=l+r>>1;
	if(L<=mid) query(k<<1,l,mid,L,R,x);
	if(R>mid) query(k<<1|1,mid+1,r,L,R,x);
}
int s[N*100],T,top,dfn[N*100],mn[N*100],tot,fr[N*100];
bool ins[N*100];
void tarjan(int k){
	dfn[k]=mn[k]=++T;
	s[++top]=k;
	ins[k]=1;
	for(int i=home[k];~i;i=e[i].next){
		if(!dfn[e[i].k]){
			tarjan(e[i].k);
			mn[k]=min(mn[k],mn[e[i].k]);
		}else if(ins[e[i].k]) mn[k]=min(mn[k],dfn[e[i].k]);
	}
	if(mn[k]==dfn[k]){
		ins[k]=0;
		fr[k]=++tot;
		while(s[top]!=k){
			ins[s[top]]=0;
			fr[s[top]]=tot;
			top--;
		}
		top--;
	}
}
