struct edge {
  ll to,cost;
  edge(ll x,ll y):to(x),cost(y){};
};
struct RangeGraph{
  vector<vector<edge>>g;
  ll n,sz;
  ll cnt;
  RangeGraph(ll n,ll m):n(n){
    sz=1;
    cnt=0;
    while(sz<n)sz <<= 1;
    g.assign(3*sz+m,vector<edge>());
    for(ll i=1;i<sz;i++){
      g[i].EB(2*i,0);
      g[i].EB(2*i+1,0);
      if(2*i<sz){
        g[2*i+2*sz].EB(i+2*sz,0);
        g[2*i+1+2*sz].EB(i+2*sz,0);
      }
      else{
        g[2*i].EB(i+2*sz,0);
        g[2*i+1].EB(i+2*sz,0);
      }
    }
  }
  void add_edge(ll l1,ll r1,ll l2,ll r2,ll w){//[l1,r1)->[l2,r2)
    if(l1>=r1||l2>=r2)return;
    if(l1+1==r1&&l2+1==r2){
      g[l1+sz].EB(l2+sz,w);
    }
    else if(l1+1==r1){
      auto v=range(l2,r2);
      v=range(l2,r2);
      for(auto z:v)g[l1+sz].EB(z,0);
    }
    else if(l2+1==r2){
      auto v=range(l1,r1);
      for(auto z:v){
        if(z<sz)g[z+2*sz].EB(l2+sz,0);
        else g[z].EB(l2+sz,0);
      }
    }
    else{
      auto v=range(l1,r1);
      ll via=3*sz+cnt;
      for(auto z:v){
        if(z<sz)g[z+2*sz].EB(via,w);
        else g[z].EB(via,w);
      }
      v=range(l2,r2);
      for(auto z:v)g[via].EB(z,0);
      cnt++;
    }
  }
  vector<ll>range(ll l,ll r){
    vector<ll>ret;
    l+=sz,r+=sz;
    while(l!=r){
      if(l&1)ret.PB(l++);
      if(r&1)ret.PB(--r);
      l>>=1,r>>=1;
    }
    return ret;
  };
  ll add(){
    return sz;
  }
};

struct SCC{
  ll n;
  vector<vector<struct edge>>G,Gr;
  vector<ll>index;//各ノードが属する強連結成分の番号
  vector<ll>ret;//dfsに使う
  SCC(vector<vector<struct edge>>g):G(g),n(g.size()){
    index.assign(n,-1LL);
    build();
  }
  void build(){
    Gr.assign(n,vector<struct edge>());
    for(ll i=0;i<n;i++){
      for(ll j=0;j<G[i].size();j++){
        Gr[G[i][j].to].emplace_back(i,G[i][j].cost);
      }
    }
    for(ll i=0;i<n;i++)if(index[i]==-1)dfs1(i);
    fill(ALL(index),-1);
    ll cnt=0;
    reverse(ALL(ret));
    for(ll i=0;i<n;i++){
      if(index[ret[i]]==-1){
        dfs2(ret[i],cnt);
        cnt++;
      }
    }
  }
  void dfs1(ll k){
    index[k]=1;
    for(ll i=0;i<G[k].size();i++){
      if(index[G[k][i].to]==-1)dfs1(G[k][i].to);
    }
    ret.push_back(k);
  }
  void dfs2(ll k, ll idx){
    index[k]=idx;
    for(ll i=0;i<Gr[k].size();i++){
      if(index[Gr[k][i].to]==-1)dfs2(Gr[k][i].to,idx);
    }
  }
  vector<ll>output(){return index;};
};

