int dfn[N],low[N],tim=0,bl[N],scc=0,sta[N],in[N],top=0;
inline void tarjan(int u) {
    dfn[u]=low[u]=++tim,sta[++top]=u,in[u]=1;
    for (re int i=head[u];i;i=e[i].nxt) {
        int v=e[i].v;
        if (!dfn[v]) tarjan(v),low[u]=min(low[u],low[v]);
        else if (in[v]) low[u]=min(low[u],dfn[v]);
    }
    if (dfn[u]==low[u]) { ++scc;
        while (233) {
            int t=sta[top--]; bl[t]=scc,in[t]=0;
            if (t==u) break;
        }
    }
}

inline int check(int mid) {
    clear(head,0),ecnt=0;
    clear(dfn,0),clear(low,0),clear(bl,0),clear(in,0),tim=scc=top=0;
    ncnt=n<<1,build(1,1,n<<1);
    for (re int i=1;i<=n;++i)
        for (re int j=0;j<2;++j) {
            int l=lower_bound(a+1,a+n+n+1,mp(x[j][i]-mid+1,0))-a;
            int r=upper_bound(a+1,a+n+n+1,mp(x[j][i]+mid-1,n<<1|1))-a-1;
            int m=lower_bound(a+1,a+n+n+1,mp(x[j][i],i+(j^1)*n))-a;
            link(1,1,n<<1,l,m-1,i+j*n),link(1,1,n<<1,m+1,r,i+j*n);
        }
    for (re int i=1;i<=ncnt;++i) if (!dfn[i]) tarjan(i);
    for (re int i=1;i<=n;++i) if (bl[i]==bl[i+n]) return 0;
    return 1;
}

