		if(r > i) ql = i+1, qr = r, Modify(1, 1, nn, num[i].id);
	}
}

#define v G[now][i]

void Targan(int now){
	low[now] = dfn[now] = ++clk;
	st[++tp] = now;

	For(i, 0, G[now].size()-1)
		if(!dfn[v]){
			Targan(v); low[now] = min(low[now], low[v]);
		}else if(!sid[v]) low[now] = min(low[now], dfn[v]);

	if(low[now] == dfn[now]){
		sid[now] = ++sn;
		while(st[tp] ^ now) sid[st[tp--]] = sn;
		--tp;
	}
}

#undef v

bool Topsort(){
	queue<int> q;
	For(i, 1, sn) if(!dig[i]) q.push(i);

	int now, v;

	while(!q.empty()){
		now = q.front(); q.pop();

		if(val[now] == -1) val[now] = 1;

		if(val[now] == 1)
			For(i, 0, dif[now].size()-1) if(val[dif[now][i]] == 1){
				val[now] = 0; break;
			}

		if(!val[now]) For(i, 0, dif[now].size()-1)
				if(val[dif[now][i]] == 0) return false;

		For(i, 0, g[now].size()-1){
			--dig[v = g[now][i]];

			if(!val[now] && val[v] == 1) return false;
			if(!val[now]) val[v] = 0;

			if(!dig[v]) q.push(v);
		}
	}

	return true;
}

bool Check(int mxd){
	For(i, 0, nn+hn) G[i].clear();
	hn = 0; Build(1, 1, nn);

	AddEdges(mxd); an = nn + hn;

	sn = clk = tp = 0;
	For(i, 0, an) dfn[i] = low[i] = st[i] = sid[i] = 0;
	For(i, 2, an) if(!dfn[i]) Targan(i);

	int u, v;

	For(i, 1, sn) g[i].clear(), dif[i].clear(), dig[i] = 0, val[i] = -1;
	for(int i = 2; i <= nn; i += 2){
		u = sid[i], v = sid[i^1]; 
		if(u == v) return false;
		dif[u].pb(v); dif[v].pb(u);
	}

	For(i, 2, an) For(j, 0, G[i].size()-1)
		if(sid[i]^sid[G[i][j]]) g[sid[G[i][j]]].pb(sid[i]), ++dig[sid[i]];

//	printf("mxd = %d Here = true\n", mxd);
	return Topsort();
}

