void Build(int k, int l, int r)
{
	tot = max(tot, k);
	if(l == r)
	{
		pos[l] = k;
		return;
	}
	int mid = l + r >> 1;
	Ins(k, k << 1);
	Ins(k, k << 1 | 1);
	Build(k << 1, l, mid);
	Build(k << 1 | 1, mid + 1, r);
}
void Insert(int k, int l, int r, int x, int y, int p)
{
	if(x <= l && r <= y)
	{
		Ins(p, k);
		return;
	}
	int mid = l + r >> 1;
	if(x <= mid) Insert(k << 1, l, mid, x, y, p);
	if(y > mid) Insert(k << 1 | 1, mid + 1, r, x, y, p);
}
void Tarjon(int u)
{
	dfn[u] = low[u] = ++cnt;
	st[++top] = u;
	for(int i = fir[u]; i; i = nex[i])
	{
		int v = go[i];
		if(!dfn[v])
		{
			Tarjon(v);
			low[u] = min(low[u], low[v]);
		}
		else
			if(!col[v])
				low[u] = min(low[u], dfn[v]);
	}
	if(low[u] == dfn[u])
	{
		col[u] = ++color;
		while(st[top] != u)
			col[st[top--]] = color;
		--top;
	}
}
