inline bool Check(int e)
{
	Reset();
	Build(1, 1, n << 1);
	for(int i = 1; i <= n << 1; ++i)
	{
		int l = upper_bound(val + 1, val + 1 + (n << 1), val[i] - e) - val;
		int r = lower_bound(val + 1, val + 1 + (n << 1), val[i] + e) - val - 1;
		if(l <= i && i <= r)
		{
			if(l <= i - 1) Insert(1, 1, n << 1, l, i - 1, pos[par[i]]);
			if(i + 1 <= r) Insert(1, 1, n << 1, i + 1, r, pos[par[i]]); 
		}
		else Insert(1, 1, n << 1, l, r, pos[par[i]]);
	}
	for(int i = 1; i <= tot; ++i)
		if(!dfn[i])
			Tarjon(i);
	for(int i = 1; i <= n << 1; ++i)
		if(col[pos[i]] == col[pos[par[i]]])
			return false;
	return true;
}
inline int Divide()
{
	int l = 0, r = inf, mid, ans;
	while(l <= r)
	{
		mid = l + r >> 1;
		if(Check(mid)) l = mid + 1, ans = mid;
		else r = mid - 1;
	}
	return ans;
}
