	for(int i = 1 ; i <= pos[n<<1] ; ++i) L[i] = (i-1) * len + 1 , R[i] = min(i * len , n << 1 );
	int l = 1 , r = INF , ans = -1;
	while( l <= r )
	{
		int mid = (l + r) >> 1;
		if(check(mid)) ans = mid , l = mid + 1;
		else		   r = mid - 1;
	}
	cout << ans+1 << endl;
	fclose(stdin);
	fclose(stdout);
	return 0;
}
