int B, sz;

void build(int a, int b, int k, int l, int r, int p) {
	if (b <= l || r <= a) {
		return ;
	}

	if (a <= l && r <= b) {
		add_edge(p, k + B);
		add_edge(k, p + B);
		return ;
	}

	build(a, b, k * 2 + 1, l, (l + r) / 2, p);
	build(a, b, k * 2 + 2, (l + r) / 2, r, p);
}

bool ok(int d)
{
	sz = 1;
	while (sz < N * 2) sz *= 2;

	B = sz * 2;
	V = B * 2;

	rep(i, V) {
		G[i].clear();
		rG[i].clear();
	}

	rep(i, N) {
		int a = u[i][0] + sz - 1, b = u[i][1] + sz - 1;
		add_edge(a, b + B);
		add_edge(b, a + B);
		add_edge(a + B, b);
		add_edge(b + B, a);
	}

	for (int i = 1; i < sz * 2 - 1; ++i) {
		add_edge(i, (i-1) / 2);
		add_edge((i-1) / 2 + B, i + B);
	}

	rep(i, vec.size()) {
		int l = upper_bound(ALL(vec), mp(vec[i].fi - d + 1, -1)) - vec.begin();
		int r = lower_bound(ALL(vec), mp(vec[i].fi + d, -1)) - vec.begin();
		//[l, i), [i + 1, r)
		build(l, i, 0, 0, sz, i + sz - 1);
		build(i + 1, r, 0, 0, sz, i + sz - 1);
	}


	rep(i, B) {
		if (cmp[i] == cmp[i + B]) {
			return false;
		}
	}
	return true;
}

