int read()
{
    int x=0,f=1;char ch=getchar();
    while (ch<'0'||ch>'9'){if(ch=='-')f=-1;ch=getchar();}
    while (ch>='0'&&ch<='9'){x=x*10+ch-'0';ch=getchar();}
    return x*f;
}

void addedge(int u,int v)
{
    e[++cnt].to=v;e[cnt].next=last[u];last[u]=cnt;
}

void tarjan(int x)
{
    dfn[x]=low[x]=++tim;
    stack[++top]=x;inst[x]=1;
    for (int i=last[x];i;i=e[i].next)
        if (!dfn[e[i].to])
        {
            tarjan(e[i].to);
            low[x]=min(low[x],low[e[i].to]);
        }
        else if (inst[e[i].to]) low[x]=min(low[x],dfn[e[i].to]);
    if (dfn[x]==low[x])
    {
        tot++;int y=0;
        while (y!=x)
        {
            y=stack[top];top--;
            inst[y]=0;bel[y]=tot;
        }
    }
}

void build(int d,int l,int r)
{
    t[d].num=++sz;
    if (d>1) addedge(t[d/2].num,sz);
    if (l==r)
    {
        int id=w[l].second;
        id+=id<=n?n:-n;
        addedge(t[d].num,id);
        return;
    }
    int mid=(l+r)/2;
    build(d*2,l,mid);build(d*2+1,mid+1,r);
}

void ins(int d,int l,int r,int x,int y,int z)
{
    if (x>y) return;
    if (l==x&&r==y) {addedge(z,t[d].num);return;}
    int mid=(l+r)/2;
    ins(d*2,l,mid,x,min(y,mid),z);
    ins(d*2+1,mid+1,r,max(x,mid+1),y,z);
}

pair<int,int> get_lim(int x,int len)
{
    int l=1,r=x;
    pair<int,int> ans;
    while (l<=r)
    {
        int mid=(l+r)/2;
        if (w[x].first-w[mid].first<len) r=mid-1;
        else l=mid+1;
    }
    ans.first=r+1;
    l=x;r=n*2;
    while (l<=r)
    {
        int mid=(l+r)/2;
        if (w[mid].first-w[x].first<len) l=mid+1;
        else r=mid-1;
    }
    ans.second=l-1;
    return ans;
}

bool check(int len)
{
    for (int i=1;i<=n*2+n*4;i++) last[i]=low[i]=dfn[i]=0;
    sz=n*2;cnt=0;
    build(1,1,n*2);
    for (int i=1;i<=n*2;i++)
    {
        int id=w[i].second;
        pair<int,int> u=get_lim(i,len);
        ins(1,1,n*2,u.first,i-1,id);
        ins(1,1,n*2,i+1,u.second,id);
    }
    tot=tim=0;
    for (int i=1;i<=n*2;i++) if (!dfn[i]) tarjan(i);
    for (int i=1;i<=n;i++) if (bel[i]==bel[i+n]) return 0;
    return 1;
}

