template <typename T> inline void read(T &AKNOI)
{
	T x=0, flag=1;
	char ch = getchar();
	while(!isdigit(ch)){
		if(ch == '-') flag = -1;
		ch = getchar();
	}
	while(isdigit(ch)){
		x = (x<<1) + (x<<3) + ch - '0';
		ch = getchar();
	}
	AKNOI = flag*x;
}

int n, X[MAXN], x[MAXN], b[MAXN];
struct Sort
{
	int id, val;
	bool operator < (const Sort &rhs) const {
		return val < rhs.val;
	}
}s[MAXN];

int root, lc[MAXN], rc[MAXN], tot;
int dfn[MAXN], low[MAXN], num;
int stk[MAXN], top, instk[MAXN];
int scc, belong[MAXN];

struct Edge
{
	int v, nxt;
}e[MAXM];
int first[MAXN], eCnt;

inline void AddEdge(int u, int v)
{
	e[++eCnt].v = v;
	e[eCnt].nxt = first[u];
	first[u] = eCnt;
}

void Build(int &rt, int b, int e)
{
	rt = ++tot;
	if(b == e){
		AddEdge(rt, s[b].id+n);
		return;
	}
	int mid = (b+e) >> 1;
	Build(lc[rt], b, mid);
	Build(rc[rt], mid+1, e);
	AddEdge(rt, lc[rt]);
	AddEdge(rt, rc[rt]);
}

void Insert(int rt, int b, int e, int l, int r, int from)
{
	if(l > r) return;
	if(l <= b && e <= r){
		AddEdge(from, rt);
		return;
	}
	int mid = (b+e) >> 1;
	if(l <= mid) Insert(lc[rt], b, mid, l, r, from);
	if(r > mid) Insert(rc[rt], mid+1, e, l, r, from);
}

void Tarjan(int u)
{
	dfn[u] = low[u] = ++num;
	stk[++top] = u; instk[u] = 1;
	for(int i=first[u];i;i=e[i].nxt){
		int v = e[i].v;
		if(!dfn[v]){
			Tarjan(v);
			low[u] = min(low[u], low[v]);
		}else if(instk[v]){
			low[u] = min(low[u], dfn[v]);
		}
	}
	if(dfn[u] == low[u]){
		++scc; int x;
		do{
			x = stk[top--];
			instk[x] = 0;
			belong[x] = scc;
		}while(x != u);
	}
}

bool check(int mid)
{
	mset(dfn, 0); mset(low, 0);
	num = top = scc = 0;
	mset(first, 0); eCnt = 0;
	tot = (n<<1);
	Build(root, 1, n);
	for(int i=2;i<=n;i+=2){
		AddEdge(i+n, i-1);
		AddEdge(i-1+n, i);
	}
	for(int i=1;i<=n;++i){
		Insert(root, 1, n, upper_bound(b+1, b+n+1, X[i]-mid)-b, x[i]-1, i);
		Insert(root, 1, n, x[i]+1, lower_bound(b+1, b+n+1, X[i]+mid)-b-1, i);
	}
	for(int i=1;i<=tot;++i){
		if(!dfn[i]){
			Tarjan(i);
		}
	}
	for(int i=1;i<=n;++i){
		if(belong[i] == belong[i+n]){
			return false;
		}
	}
	return true;
}

void init()
{
	read(n); n <<= 1;
	for(int i=1;i<=n;++i){
		read(X[i]);
		b[i] = X[i];
		s[i].val = X[i]; s[i].id = i;
	}
	sort(b+1, b+n+1);
	sort(s+1, s+n+1);
	for(int i=1;i<=n;++i){
		x[s[i].id] = i;
	}
}

void solve()
{
	int L = 1, R = 1e9, ans = 0;
	while(L <= R){
		int mid = (L+R) >> 1;
		if(check(mid)){
			ans = mid;
			L = mid+1;
		}else{
			R = mid-1;
		}
	}
	printf("%d\n", ans);
}

int main()
{
	init();
	solve();
	return 0;
}

