void Tarjan(int x){
	dfn[x]=low[x]=++dfs_clock;
	sta[++top]=x;
	for (int i=0;i<(int)G[x].size();++i){
		int v=G[x][i];
		if (!dfn[v]) Tarjan(v),low[x]=min(low[x],low[v]);
		else if (!col[v]) low[x]=min(low[x],dfn[v]);
	}
	if (dfn[x]==low[x]){
		col[x]=++colnm;
		while (sta[top]!=x) col[sta[top--]]=colnm;
		--top;
	}
}

