const int inf=LLONG_MAX/3;

const int Nmax=114514;

struct SCC{
	vi belong;
	vector<vi> cmp,graph;
};
namespace StronglyConnectedComponents{
	int ord[Nmax],low[Nmax],ordI,cmpI,belong[Nmax],come[Nmax];
	stack<int> psh;
	bool inS[Nmax],used[Nmax];
	vi  cmp[Nmax];
	void dfs(int v,const vector<vi>& graph){
		ord[v]=low[v]=ordI++;
		inS[v]=true;
		psh.push(v);
		for(auto to:graph[v]){
			if(ord[to]==-1){
				dfs(to,graph);
				chmin(low[v],low[to]);
			}else if(inS[to])
				chmin(low[v],ord[to]);
		}
		if(low[v]==ord[v]){
			while(1){
				int t=psh.top();psh.pop();
				belong[t]=cmpI;
				cmp[cmpI].PB(t);
				inS[t]=false;
				if(t==v)
					break;
			}
			cmpI++;
		}
	}
	SCC BuildSCC(const vector<vi>& graph){
		int n=graph.size();
		memset(ord,-1,sizeof(ord));
		memset(low,-1,sizeof(low));
		memset(belong,0,sizeof(belong));
		memset(come,0,sizeof(come));
		memset(inS,0,sizeof(inS));
		memset(used,0,sizeof(used));
		REP(i,Nmax)cmp[i].clear();
		psh=stack<int>();
		REP(i,n)if(ord[i]==-1)
			dfs(i,graph);
		vector<vi> retCmp,retGraph(cmpI);
		vi retBelong(n);
		REP(v,n)
			for(auto to:graph[v])
				if(belong[v]!=belong[to])
					come[belong[to]]++;
		queue<int> q;
		REP(i,cmpI)
			if(come[i]==0)
				q.push(i);
		while(!q.empty()){
			int i=q.front();q.pop();
			for(auto v:cmp[i])
				retBelong[v]=retCmp.size();
			retCmp.PB(cmp[i]);
			for(auto v:cmp[i])
				for(auto to:graph[v])
					if(i!=belong[to])
						if(--come[belong[to]]==0)
							q.push(belong[to]);
		}
		REP(i,cmpI){
			for(auto v:retCmp[i])
				for(auto to:graph[v])
					if(i!=retBelong[to]&&!used[retBelong[to]]){
							retGraph[i].PB(retBelong[to]);
							used[retBelong[to]]=true;
					}
			for(auto to:retGraph[i])
				used[to]=false;
		}
		return SCC{retBelong,retCmp,retGraph};
	}
}

struct Flag{
