}

void add_clause(int x, int y) // x -> y - (if you want to use "not x" here use ~x)
{
//	cout<<x<<" "<<y<<"\n";
	if((x>>31)&1) x=(~x)+N;
	if((y>>31)&1) y=(~y)+N;
	add_edge(x,y); add_edge(NOT(y),NOT(x));
}

bool satisfy(void)
{
	for(int i=0 ; i<N ; i++) if(whi[i]==whi[NOT(i)]) return false;
	return true;
}

void build_seg(int index, int s, int e)
{
	int m=(s+e)>>1;
	if(s==e) { wow[m]=index; return; }
	add_clause(index<<1, index);
	add_clause(index<<1|1, index);
	build_seg(index<<1, s, m);
	build_seg(index<<1|1, m+1, e);
}

void add_seg(int index, int s, int e, int l, int r, int src)
{
	if(l>e || r<s) return;
	if(l<=s && e<=r) { add_clause(wow[src], ~index); return; }
	int m=(s+e)>>1;
	add_seg(index<<1, s, m, l, r, src);
	add_seg(index<<1|1, m+1, e, l, r, src);
}

