	if (x<=l&&y>=r) add(z,2*(k+t));
	else {
		int mid=(l+r)/2;
		if (x<=mid) insert(k,l,mid,x,y,z);
		if (y>=mid+1) insert(k,mid+1,r,x,y,z);
	}
}

bool travel(int x,int c1,int c2){
	h[x]=c2;
	if (h[x]&&h[x^1]) return false;
	for (int t=p[x];t;t=next[t])
		if (h[y[t]]==c1){
			if (!travel(y[t],c1,c2))
			return false;
		}
	return true;
}

