const int MAX_N = 81234;
vector<int> g[MAX_N], r[MAX_N];
void clear_edge() {
  REP(i, MAX_N) g[i].clear();
  REP(i, MAX_N) r[i].clear();
}
int vid(int id, int tf) { return 2 * id + tf; }
void add_edge(int a, int b) {
  // cout << "(" << a/2 << "," << a%2 << ")" << "->" << "("<<b/2 << "," << b%2 <<")" << endl;
  g[a].push_back(b);
  r[b].push_back(a);
}

int sccid[MAX_N];
int sccnum;
void dfs(int p, vector<int>& order) {
  if (sccid[p] != 0) return;
  sccid[p] = 1;
  for (int i : g[p]) dfs(i, order);
  order.push_back(p);
}
void rdfs(int p, int id) {
  if (sccid[p] != -1) return;
  sccid[p] = id;
  for (int i : r[p]) rdfs(i, id);
}
void scc(int N) {
  vector<int> order;
  CLR(sccid, 0);
  REP(i, N) dfs(i, order);
  CLR(sccid, -1);
  sccnum = 0;
  for (int i = (int)order.size() - 1; i >= 0; i--) if (sccid[order[i]] == -1) {
    rdfs(order[i], sccnum);
    sccnum++;
  }
}

void cover(int node, int a, int b, const int L, const int R, const int p) {
  if (R - L <= 0) return;
  if (L <= a && b <= R) {
    // ~(x AND y) <=> (~x OR ~y) <=> (x -> ~y) <=> (y -> ~x)
    add_edge(vid(node, 1), vid(p, 0));
    add_edge(vid(p, 1), vid(node, 0));
    return;
  }
  if (b <= L || R <= a) return;
  if (b - a <= 1) return;
  cover(node * 2,     a, (a+b)/2, L, R, p);
  cover(node * 2 + 1, (a+b)/2, b, L, R, p);
}

// 距離がD以上はなれていればOK 
bool possible(vector<pair<int,int>> z, vector<pair<int,int>> is, int D) {
  const int INF = 1001001001;
  clear_edge();

  int NN = (int)z.size();
  int K = 1;
  while (K < NN) K *= 2;

  for (int k = 2; k < K; k++) {
    add_edge(vid(k, 1), vid(k/2, 1));
  }
  REP(i, NN) {
    add_edge(vid(K+i, 1), vid((K+i)/2, 1));
  }

  REP(i, is.size()) {
    // ~(x AND y) <=> (~x OR ~y) <=> (x -> ~y) <=> (y -> ~x)
    add_edge(vid(K + is[i].first, 1), vid(K + is[i].second, 0));
    add_edge(vid(K + is[i].second, 1), vid(K + is[i].first, 0));

    // ~(~x AND ~y) <=> (x OR y) <=> (~x -> y) <=> (~y -> x)
    add_edge(vid(K + is[i].first, 0), vid(K + is[i].second, 1));
    add_edge(vid(K + is[i].second, 0), vid(K + is[i].first, 1));
  }

  // 距離 D より小さい点が同時に 1 を禁止
  REP(i, NN) {
    int pivot = z[i].first;
    int L = distance(z.begin(), upper_bound(ALL(z), make_pair(pivot - D, INF)));
    int R = distance(z.begin(), lower_bound(ALL(z), make_pair(pivot + D, -INF)));
    // [L, R) の範囲が禁止。
    cover(1, 0, K, L,   i, K+i);
    cover(1, 0, K, i+1, R, K+i);
  }

  scc((K+NN)*2);
  // pv(sccid, sccid + (K+NN)*2);
  for (int i = 0; i < (K+NN)*2; i += 2) {
    if (sccid[i] == sccid[i+1]) return false;
  }
  return true;
}

