}
void upd1(int u,int v,int f,int L,int R,int l=0,int r=nb-1) {
    if(l>=L&&r<=R) {twosat.link(v,u,f,0); return;}
    if(l>R||r<L)return;
    upd1(l(u),v,f,L,R,l,mid),upd1(r(u),v,f,L,R,mid+1,r);
}
