int n, comp[22000], vis[22000], vind[22000], l[11000], r[11000];
stack< int > s;
vector< pi > v;

void forward(int index, int d) {
	vis[index] = 1;
	int x = v[vind[index]].first;
	for (int i = vind[index]-1; i >= 0; i--) {
		if (x-v[i].first >= d)
			break;
		int neigh = v[i].second + (v[i].second > n ? -n : n);
		if (!vis[neigh]) {
			//cout<<index<<" "<<neigh<<" "<<v[i].second<<endl;
			forward(neigh, d);
		}
	}	

	for (int i = vind[index]+1; i < n; i++) {
		if (v[i].first-x >= d)
			break;
		int neigh = v[i].second + (v[i].second > n ? -n : n);
		if (!vis[neigh]) {
			//cout<<index<<" "<<neigh<<" "<<v[i].second<<endl;
			forward(neigh, d);
		}
	}	

	s.push(index);
}

void backward(int index, int d, int c) {
	comp[index] = c;
	index += (index > n ? -n : n);
	if (index == 0) index++;
	int x = v[vind[index]].first;
	for (int i = vind[index]-1; i >= 0; i--) {
		if (x-v[i].first >= d)
			break;
		int neigh = v[i].second;
		if (comp[neigh] == 0)
			backward(neigh, d, c);
	}

	for (int i = vind[index]+1; i < n; i++) {
		if (v[i].first-x >= d)
			break;
		int neigh = v[i].second;
		if (comp[neigh] == 0)
			backward(neigh, d, c);
	}
}

bool solve(int d) {
	memset(comp, 0, sizeof(comp));
	memset(vis, 0, sizeof(vis));
	int cnum = 1;

	for (int i = 1; i <= 2*n; i++) {
		if (!vis[i]) {
			forward(i, d);
		}
	}

	while (!s.empty()) {
		int curr = s.top(); s.pop();
		if (comp[curr])
			continue;
		backward(curr, d, cnum);
		cnum++;
	}

	for (int i = 1; i <= n; i++) {
		//cout<<i<<" "<<(i+n)<<" "<<comp[i]<<" "<<comp[i+n]<<endl;
		if (comp[i] == comp[i+n])
			return false;
	}

	return true;
}

