		int mid = avg(beg, end);
		bool ok = solve(mid);
		//cout<<mid<<" "<<ok<<endl;
		if (ok) {
			ans = mid;
			beg = mid+1;
		} else {
			end = mid-1;
		}
	}

	cout<<ans<<endl;

	return 0;
}

