struct TTree{
	int Flag;
	struct Tree{
		int l,r,id;
	}T[N];
	void build(int x,int l,int r){
		T[x].l=l;T[x].r=r;
		if (l==r){
			if (Flag)T[x].id=f1[l]+n;
			else T[x].id=f2[l];
			return;
		}
		T[x].id=++cnt;
		int mid=(l+r)/2;
		build(x*2,l,mid);
		build(x*2+1,mid+1,r);
	}
	void solve(int x){
		if (T[x].l==T[x].r)return;
		jb(T[x].id,T[x*2].id);jb(T[x].id,T[x*2+1].id);
		solve(x*2);solve(x*2+1);
	}
	void insert(int x,int l,int r,int z){
		if (T[x].l>r||l>T[x].r)return;
		if (T[x].l>=l&&T[x].r<=r){
			jb(z,T[x].id);
			return;
		}
		insert(x*2,l,r,z);
		insert(x*2+1,l,r,z);
	}
}T[2];
