		int l=i,r=n;
		while (l<r){
			int mid=(l+r+1)/2;
			if (y[f2[mid]]>=y[f2[i]]+dis)r=mid-1;
			else l=mid;
		}
		T[1].insert(1,i+1,l,f2[i]+n);
	}
	for (int i=1;i<=n;i++){
		int l1=1,r1=n;
		if (y[f2[n]]<=x[f1[i]]-dis)l1=n+1;
		while (l1<r1){
			int mid=(l1+r1)/2;
			if (y[f2[mid]]>x[f1[i]]-dis)r1=mid;
