vector<vll> POS(10010, vll(2));

struct SCC{
    vector<vll> G, revG; 
    vll postOrder; //* record post-order of dfs on G
    vll checked; 
    vll component;
    vector<set<ll> > reducedG;
    vll numVertex;
    ll num_component = -1;

    SCC(ll N){ 
        G.resize(N); revG.resize(N); 
        checked.resize(N, 0); component.resize(N);
    }
    void add_edge(ll a, ll b) { G[a].push_back(b); revG[b].push_back(a); }
    //* first round of dfs on G
    void dfs(ll v) {
        checked[v] = 1;
        for(auto u: G[v]) if(!checked[u]) dfs(u);
        postOrder.push_back(v);
    }
    //* second round dfs on revG
    //* k for recording strongly connected components id
    void rev_dfs(ll v, ll k){ 
        checked[v] = 1;
        component[v] = k;
        for(auto u: revG[v]){
            if(!checked[u]) rev_dfs(u, k);
        }
    }
    ll calculate_component(){
        //* 1. dfs on G
        fill(ALL(checked), 0);
        postOrder.clear();
        REP(v, G.size()){
            if(!checked[v]) dfs(v);
        }
        //* 2. dfs on revG
        fill(ALL(checked), 0);
        ll k = 0;
        for(ll i = postOrder.size() - 1; i >= 0; i--){
            if(!checked[postOrder[i]]) rev_dfs(postOrder[i], k++);
        }
        //* 3. get number of vectexes in each components
        numVertex.resize(k, 0);
        for(ll v = 0; v < G.size(); v++)  numVertex[component[v]]++;

        num_component = k;
        return k;
    }
    bool is_same(ll u, ll v){ return (component[u] == component[v]); }

    void reduce(){
        ll num_comp = calculate_component();
        reducedG.resize(num_comp);
        for(ll u = 0; u < G.size(); u++){
            for(ll v: G[u]){
                if(component[u] == component[v]) continue;
                reducedG[component[u]].insert(component[v]);
            }
        }
    }

    vector<vll> get_reduce_graph(){
        vector<vll> Gout(num_component);
        for(ll i = 0; i < num_component; i++){
            Gout[i] = vll(ALL(reducedG[i]));
        }
        return Gout;
    }
};

bool check(ll d, ll N){
    ll N2 = 2*N;
    SCC G(2*N2); //* 0~2N-1: take
    REP(i, N){
        ll xi = 2*i, yi = xi + 1;
        G.add_edge(xi, yi+N2);
        G.add_edge(yi+N2, xi);
        G.add_edge(yi, xi+N2);
        G.add_edge(xi+N2, yi);
    }
    REP(i, N) for(ll j = i+1; j < N; j++){
        ll Pxi = POS[i][0], Pyi = POS[i][1];
        ll Pxj = POS[j][0], Pyj = POS[j][1];
        ll xi = 2*i, yi = xi + 1;
        ll xj = 2*j, yj = xj + 1;
        if(abs(Pxi - Pxj) < d){
            G.add_edge(xi, xj + N2);
            G.add_edge(xj, xi + N2);
        }
        if(abs(Pxi - Pyj) < d){
            G.add_edge(xi, yj + N2);
            G.add_edge(yj, xi + N2);
        }
        if(abs(Pyi - Pxj) < d){
            G.add_edge(yi, xj + N2);
            G.add_edge(xj, yi + N2);
        }
        if(abs(Pyi - Pyj) < d){
            G.add_edge(yi, yj + N2);
            G.add_edge(yj, yi + N2);
        }
    }
    G.reduce();
    REP(i, N){
        ll xi = i*2, yi = xi + 1;
        if(G.is_same(xi, xi + N2)) return false;
        if(G.is_same(yi, yi + N2)) return false;
    }
    return true;
}

void solve(ll N){
    ll lo = 0,  hi = 1<<30;
    while(hi - lo > 1){
        ll mid = (lo + hi) / 2;
        ll isGood = check(mid, N);
        if(isGood) lo = mid;
        else hi = mid;
    }
    cout<<lo<<endl;
}

