// coordinate compression
struct X {
  typedef int T;
  vector<T> d;
  inline void add(T x) { d.pb(x);}
  void init() {
    sort(rng(d));
    d.erase(unique(rng(d)), d.end());
  }
  inline int size() { return sz(d);}
  inline int operator[](T x) { return upper_bound(rng(d),x)-d.begin()-1;}
};
//

// Segment tree (RMQ type)
vi used, q;
struct seg {
  vector<vi> d; int x2;
  seg(){}
  seg(int mx) {
    x2 = 1; while (x2 < mx) x2 <<= 1;
    d.resize(x2<<1);
  }
  void fil() {
    drep(i,x2) {
      d[i] = d[i<<1];
      d[i].insert(d[i].end(), rng(d[i<<1|1]));
    }
  }
  void add(int i, int x=0){
    i += x2;
    d[i].pb(x);
  }
  void get(int a, int b, int x) { return get(a,b,x,1,0,x2);}
  void get(int a, int b, int x, int i, int l, int r){
    if (a <= l && r <= b) {
      vi pd; swap(pd, d[i]);
      for (int v : pd) {
        if (used[v]) continue;
        if ((v>>1) == x) {
          d[i].pb(v);
          continue;
        }
        q.pb(v);
      }
      return;
    }
    int c = (l+r)>>1;
    if (a < c) get(a,b,x,i<<1,l,c);
    if (c < b) get(a,b,x,i<<1|1,c,r);
  }
};
//


int n;
vi a;

bool f(int x) {
  int m = n*2;
  X xs;
  rep(i,m) xs.add(a[i]);
  rep(i,m) xs.add(a[i]+x-1);
  xs.init();
  seg d(sz(xs)+1);
  rep(i,m) {
    d.add(xs[a[i]],i^1);
    d.add(xs[a[i]+x-1],i^1);
  }
  d.fil();
  seg pd = d;
  vi vs;
  {
    used = vi(m);
    q = vi();
    rep(i,m) if (!used[i]) {
      q.pb(i);
      while (sz(q)) {
        int v = q.back(); q.pop_back();
        if (v >= m) {
          vs.pb(v-m);
          continue;
        }
        if (used[v]) continue;
        used[v] = 1;
        q.pb(m+v);
        d.get(xs[a[v]],xs[a[v]+x-1]+1,v>>1);
      }
      // cout<<vs<<endl;
    }
  }
  {
    used = vi(m);
    q = vi();
    int ui = 1;
    for (int i : vs) if (!used[i]) {
      q.pb(i);
      while (sz(q)) {
        int v = q.back(); q.pop_back();
        if (used[v]) continue;
        used[v] = ui;
        pd.get(xs[a[v]],xs[a[v]+x-1]+1,v>>1);
      }
      ++ui;
    }
    // cout<<used<<endl;
  }
  rep(i,m) if (used[i] == used[i^1]) return false;
  return true;
}

int main() {
  scanf("%d",&n);
  a = vi(n*2);
  rep(i,n*2) scanf("%d",&a[i]);
  // cout<<f(1)<<endl; return 0;
  int l = 0, r = INF;
  while (l+1<r) {
    int c = (l+r)>>1;
    if (f(c)) l = c; else r = c;
  }
  cout<<l<<endl;
  return 0;
}

