void tarjan(int x) {
	dfn[x] = low[x] = ++t;
	in[x] = 1;
	sta[++top] = x;
	for (node *i = head[x]; i; i = i->nxt)
		if (!dfn[i->to]) {
			tarjan(i->to);
			low[x] = min(low[x], low[i->to]);
		} else if (in[i->to])low[x] = min(low[x], dfn[i->to]);
	if (dfn[x] == low[x]) {
