			in[sta[top]] = 0;
			top--;
		}
		belo[x] = cnt;
		in[x] = 0;
		top--;
	}
}
void build(int k, int l, int r) {
	if (l == r) {
		add(k + (n << 1), z[l].p <= n ? z[l].p + n : z[l].p - n);
		return ;
	}
	build(lson); build(rson);
	add(k + (n << 1), (k << 1) + (n << 1));
	add(k + (n << 1), (k << 1 | 1) + (n << 1));
}
void add(int k, int l, int r, int x, int y, int z) {
	if (x == l && y == r) {
		add(z, k + (n << 1));
		return ;
	}
	if (y <= mid)add(lson, x, y, z);
	else if (x > mid)add(rson, x, y, z);
	else add(lson, x, mid, z), add(rson, mid + 1, y, z);
}
bool check(int k) {
	t=tot = top = 0;
	memset(head, 0, sizeof(head));
	memset(dfn, 0, sizeof(dfn));
	build(1, 1, n << 1);
	int l = 1, r = 1;
	int opt, p;
	for (int i = 1; i <= (n << 1); ++i) {
		p = z[i].p;
		if (p <= n)opt = pos[p + n];
		else opt = pos[p - n];
		while (r <= i && z[r].v <= z[i].v - k)r++;
		if (r < i && r >= 1 && z[r].v > z[i].v - k) {
			if (opt >= r && opt <= i - 1) {
				if (opt > r)add(1, 1, n << 1, r, opt - 1, z[i].p);
				if (opt < i - 1)add(1, 1, n << 1, opt + 1, i - 1, z[i].p);
			}
			else add(1, 1, n << 1, r, i - 1, z[i].p);
		}
		while (l <= (n << 1) && z[l].v < z[i].v + k)l++;
		l--;
		if (l > i && l <= (n << 1) && z[l].v < z[i].v + k) {
			if (opt >= i + 1 && opt <= l) {
				if (opt > i + 1)add(1, 1, n << 1, i + 1, opt - 1, z[i].p);
				if (opt < l)add(1, 1, n << 1, opt + 1, l, z[i].p);
			}
			else add(1, 1, n << 1, i + 1, l, z[i].p);
		}
	}
	for (int i = 1; i <= (n << 1); i++)
		if (!dfn[i])tarjan(i);
	for (int i = 1; i <= n; ++i)
		if (belo[i] == belo[i + n])
			return 0;
	return 1;
}
