inline void ct(int u, int v) {
	++ccnt;
	nxt[ccnt] = home[u];
	home[u] = ccnt;
	to[ccnt] = v;
}

struct rec {
	int pos, id;
	bool operator<(const rec &f)const {
		return pos < f.pos;
	}
	rec(int pos = 0): pos(pos) {}
} flgs[MAXN * 2];

int n, T, root, id[MAXN * 5], cnt;

#define mid ((l+r)>>1)
#define ls (k<<1)
#define rs (k<<1|1)

inline void build(int k, int l, int r) {
	// if(!k)k = ++T;
	id[k] = ++cnt;
	if(l == r) {
		ct(id[k], op(flgs[l].id));
		return ;
	}
	build(ls, l, mid);
	build(rs, mid + 1, r);
	ct(id[k], id[ls]);
	ct(id[k], id[rs]);
}

void link(int k, int l, int r, int x, int y, int pt) {
	if(y < x)return ;
	if(l == x && y == r)ct(pt, id[k]);
	else if(y <= mid)link(ls, l, mid, x, y, pt);
	else if(x > mid)link(rs, mid + 1, r, x, y, pt);
	else link(ls, l, mid, x, mid, pt), link(rs, mid + 1, r, mid + 1, y, pt);
}
#undef mid

int dfn[MAXN * 5], low[MAXN * 5], tim;
int stk[MAXN * 5], tp;
int scc[MAXN * 5], sc;
bool in[MAXN * 5];

void dfs(int u) {
	in[u] = 1;
	dfn[u] = low[u] = ++tim;
	stk[++tp] = u;
	int v;
	for(int i = home[u]; i; i = nxt[i]) {
		if(!dfn[v = to[i]]) {
			dfs(v);
			low[u] = min(low[u], low[v]);
		} else if(in[v])low[u] = min(low[u], dfn[v]);
	}
	if(dfn[u] == low[u]) {
		++sc;
		do {
			scc[v = stk[tp--]] = sc;
			in[v] = 0;
		} while(v != u);
	}
}

bool check(int v) {
	tp = tim = sc = 0;
	memset(home, 0, sizeof(home));
	memset(dfn, 0, sizeof(dfn));
	memset(low, 0, sizeof(low));
	build(1, 1, cnt = 2 * n);
	// printf("%d?\n", v);
	int l, r;
	for(int i = 1; i <= 2 * n; ++i) {
		l = upper_bound(flgs + 1, flgs + 1 + 2 * n, rec(flgs[i].pos - v)) - flgs;
		r = upper_bound(flgs + 1, flgs + 1 + 2 * n, rec(flgs[i].pos + v - 1)) - flgs - 1;
		//找下
		link(1, 1, 2 * n, l, i - 1, flgs[i].id);
		link(1, 1, 2 * n, i + 1, r, flgs[i].id);
		//区间连边
	}
	for(int i = 1; i <= 2 * n; ++i)if(!dfn[i])dfs(i);
	for(int i = 1; i <= n; ++i)if(scc[i] == scc[i + n])return 0;
	return 1;//2sat
}

int main() {
	scanf("%d", &n);
	for(int i = 1; i <= n; ++i) {
		scanf("%d%d", &flgs[i].pos, &flgs[i + n].pos);
		flgs[i].id = i;
		flgs[i + n].id = i + n;
	}
	sort(flgs + 1, flgs + n * 2 + 1);
	int l = 0, r = flgs[2 * n].pos - flgs[1].pos + 1, mid, ans;
	while(l <= r) {
		mid = (l + r) >> 1;
		if(check(mid))l = mid + 1, ans = mid;
		else r = mid - 1;
	}
	printf("%d", ans);
	return 0;
}

