            r = lower_bound(all(y),y[i]+mid) - y.begin();
            RE.addedge(N+l,N+i,invx[idy[i]],invx[idy[i]]+1,1);
            RE.addedge(N+i+1,N+r,invx[idy[i]],invx[idy[i]]+1,1);
        }

        int M = RE.G.size();
        StronglyConnectedComponent scc(M);
        rep(i,M) {
            for (auto &e : RE.G[i]) {
                scc.add_edge(i,e.to);
            }
        }
        scc.build();

        rep(i,N) {
            int u = invx[i];
            int v = invy[i]+N;
            if (scc[u]==scc[v]) return false;
        }
        return true;
    };

    int ok = 0;
