namespace G
{
	const int Max_V(10050 * 10);
	const int Max_E(10050 * 100);
	int V, Head[Max_V], Total, To[Max_E], Next[Max_E];
	inline void Add_Edge(const int &s, const int &t)
	{
		++Total, To[Total] = t, Next[Total] = Head[s], Head[s] = Total;
	}
	inline int rev(const int &x)
	{
		return (x <= V) ? (x + V) : (x - V);
	}
	inline void Link(const int &a, const int &b)
	{
		Add_Edge(rev(a), b), Add_Edge(rev(b), a);
	}
	int dfsclock, Pre[Max_V], Lowlink[Max_V], scctot, sccno[Max_V];
	stack<int> S;
	void clear()
	{
		for (int i = 1;i <= (V << 1);++i)
			Head[i] = Pre[i] = Lowlink[i] = sccno[i] = 0;
		for (int i = 1;i <= Total;++i)
			To[i] = Next[i] = 0;
		Total = dfsclock = scctot = 0;
	}
	void Tarjan(const int &u)
	{
		int v;
		Pre[u] = Lowlink[u] = ++dfsclock, S.push(u);
		for (int i = Head[u];i;i = Next[i])
			if (!Pre[v = To[i]])
				Tarjan(v), Lowlink[u] = min(Lowlink[u], Lowlink[v]);
			else
				if (!sccno[v])
					Lowlink[u] = min(Lowlink[u], Pre[v]);
		if (Pre[u] == Lowlink[u])
		{
			++scctot;
			while (true)
			{
				v = S.top(), S.pop();
				sccno[v] = scctot;
				if (u == v)
					break;
			}
		}
	}
	bool check()
	{
		for (int i = 1;i <= (V << 1);++i)
			if (!Pre[i])
				Tarjan(i);
		for (int i = 1;i <= V;++i)
			if (sccno[i] == sccno[i + V])
				return false;
		return true;
	}
}

const int Max_N(10050);
const int Max_M(20050);

int N, M, X[Max_N], Y[Max_N], P[Max_M << 1];
