#define FOR(i, a, b) for(int i = a; i < b; ++i)
#define REP(i, n) FOR(i, 0, n)
#define _ << " " <<

typedef pair<int, int> point;

const int MAXN = 2e4 + 5;

set<point> s;
vector<int> nodes;

int n, D, comp[MAXN], x[MAXN], y[MAXN];
bool bio[MAXN];

void dfs(int v) {
	bio[v] = true;

	int val = x[v / 2];
	if(v & 1) val = y[v / 2];

	while(true) {

		auto it = s.lower_bound(point(val - D + 1, 0));
		if(it == s.end()) break;

		if((*it).second == v) it ++;

		if(it == s.end()) break;
		if((*it).first >= val + D) break;

		int w = (*it).second + 1;
		if((w & 1) == 0) w -= 2;

		s.erase(it);
		dfs(w);

	}

	nodes.push_back(v);
}

int cookie;
void rev_dfs(int v) {
	comp[v] = cookie;

	int val = y[v / 2];
	if(v % 2) val = x[v / 2];

	int vv = v + 1;
	if((vv & 1) == 0) vv -= 2;

	while(true) {
		auto it = s.lower_bound(point(val - D + 1, 0));

		if(it == s.end()) break;
		if((*it).second == vv) it ++;

		if(it == s.end()) break;
		if((*it).first >= val + D) break;

		int w = (*it).second;
		s.erase(it);
		rev_dfs(w);
	}
}

bool ok() {
	memset(bio, 0, sizeof bio);
	memset(comp, 0, sizeof comp);

	s.clear();
	REP(i, n) {
		s.insert(point(x[i], 2 * i)); 
		s.insert(point(y[i], 2 * i + 1)); 
	}
	nodes.clear();

	REP(i, n) {
		if(!bio[2 * i]) {
			s.erase(point(y[i], 2 * i + 1));
			dfs(2 * i);
		}
		if(!bio[2 * i + 1]) {
			s.erase(point(x[i], 2 * i));
			dfs(2 * i + 1);
		}
	}

	s.clear();
	REP(i, n) {
		s.insert(point(x[i], 2 * i)); 
		s.insert(point(y[i], 2 * i + 1)); 
	}

	reverse(nodes.begin(), nodes.end());

	cookie = 1;
	for(auto v: nodes) {
		if(!comp[v]) {
			int val = x[v / 2];
			if(v & 1) val = y[v / 2];

			s.erase(point(val, v));
			rev_dfs(v);
		}
		cookie ++;
	}

	REP(i, n) if(comp[2 * i] == comp[2 * i + 1]) return false;
	return true;
}

void solve() {
	int lo = 0, hi = 1e9;

	while(lo < hi) {
		D = (lo + hi + 1) >> 1;
		if(ok()) lo = D;
		else hi = D - 1;
	}
	cout << lo << endl;
}

int main() {
	cin >> n;
	REP(i, n) {
		cin >> x[i] >> y[i];
	}

	solve();
}

