    }

    for(int i = 1; i <= M; i++) ord[i] = i;
    sort(ord + 1, ord + M + 1,
         [](int a, int b) { return pos[a] < pos[b]; });

    B(1, 1, 2 * N);

    int p = 1;
    int u = int(1e9);
    int ans = 0;
    while(p <= u)
    {
        int mij = p + (u - p) / 2;

        if( can(mij) )
        {
            ans = mij;
            p = mij + 1;
        }
        else
            u = mij - 1;
    }

    printf("%d\n", ans);

    return 0;
}

