  }

  sort( x.begin(), x.end() );
  x.erase( unique(x.begin(), x.end()), x.end());

  vector<pair<int,int>> y;
  vector<pair<int,int>> z;
  for(int i=0; i<n; i++){
    y.emplace_back(
      lower_bound(x.begin(), x.end(), pos[i].first) - x.begin(),
      lower_bound(x.begin(), x.end(), pos[i].second) - x.begin()
    );
    z.emplace_back( pos[i].first, i+1 );
    z.emplace_back( pos[i].second, -(i+1) );
  }

  sort(z.begin(), z.end());

  vector<pair<int,int>> yy(n);
  for(int i=0; i<n; i++){
    int a = lower_bound(z.begin(), z.end(), pair<int,int>{pos[i].first, i+1}) - z.begin();
    int b = lower_bound(z.begin(), z.end(), pair<int,int>{pos[i].second, -(i+1)}) - z.begin();
    yy[i] = {a,b};
  }

  long long ans = 0;

  int k = 1;
  while(k < z.size()){
    k*=2;
  }

  auto check = [&](long long D){
    TwoSAT sat(k*2);
    for(int i=0; i<k-1; i++){
      sat.add( i+1, -(i*2+1+1));
      sat.add( i+1, -(i*2+2+1));
    }
    for(int i=0; i<n; i++){
      sat.add( -(yy[i].first + k), -(yy[i].second + k) );
      sat.add(  (yy[i].first + k),  (yy[i].second + k) );
    }

    // [lb,ub), [l,r)
    function<void(int,int,int,int,int,int)> rec = [&](int lb, int ub, int l, int r, int pos, int w){
      if( r<=lb || ub<=l ) return;
      if( lb<=l && r<=ub ){
        sat.add( -w, -(pos+1) );
        return;
      }
      rec(lb,ub, l, (l+r)/2, pos*2+1, w);
      rec(lb,ub, (l+r)/2, r, pos*2+2, w);
    };

    for(int i=0; i<z.size(); i++){
      int d_left = z[i].first - D;
      auto l_itr = upper_bound(z.begin(), z.end(), pair<int,int>{ d_left, +2*n} );
      int ll = l_itr - z.begin();

      int d_right = z[i].first + D;
      auto r_itr = lower_bound(z.begin(), z.end(), pair<int,int>{ d_right, -100000} );
      int rr = r_itr - z.begin();

      if( ll < i ){ // [ll,i)
        rec(ll, i, 0, k, 0, i+k );
      }
      if( rr > i){ // [i+1,rr)
        rec(i+1, rr, 0, k, 0, i+k );
      }
    }
    bool ok = sat.solve();
    return ok;
  };

  long long lb = 0;
  long long ub = 1000000000;
  while(ub-lb>1){
    long long mid = (lb+ub)/2;
    bool ok = check(mid);
    (ok? lb : ub) = mid;
  }
  println(lb);

  return 0;
}

