void con(int idx, int l, int r, int x, int p, int q) {
	//if(idx == 1) printf("con(x = %d, p = %d, q = %d)\n", x, p, q);
	if(p <= l && r <= q) {
		mkedge(x + 2 * MAXN, idx + 4 * MAXN);
	}
	else if(l <= q && p <= r) {
		int m = (l + r) / 2;
		con(idx * 2, l, m, x, p, q);
		con(idx * 2 + 1, m + 1, r, x, p, q);
	}
}

