                }
                else if (d1 < d && d2 >= d && d3 < d && d4 >= d) {
                        add_edge(j, j + n);
                }
                else if (d1 < d && d2 < d && d3 >= d && d4 >= d) {
                        add_edge(i, i + n);
                }
                else if (d1 >= d && d2 >= d && d3 >= d && d4 < d) {
                        add_edge(i + n, j);
                        add_edge(j + n, i);
                }
                else if (d1 >= d && d2 >= d && d3 < d && d4 >= d) {
                        add_edge(i + n, j + n);
                        add_edge(j, i);
                }
                else if (d1 >= d && d2 < d && d3 >= d && d4 >= d) {
                        add_edge(i, j);
                        add_edge(j + n, i + n);
                }
                else if (d1 < d && d2 >= d && d3 >= d && d4 >= d) {
                        add_edge(i, j + n);
                        add_edge(j, i + n);
                }
        }
        StronglyConnectedComponent();
