inline bool cmp (int i , int j) {
	return x[i] < x[j] ;
}

inline void add_edge (int u , int v) {
	g[u].push_back(v) ;
	h[v].push_back(u) ;
}	

inline void add_clause (int u , int v) {
	add_edge(u ^ 1 , v) ;
	add_edge(v ^ 1 , u) ;
}

inline int get_lower_bound (int i , int d) {
	int low = i , high = 2 * n ;

	while (high - low > 1) {
		int mid = (low + high) / 2 ;

		if (x[ord[mid]] - x[ord[i]] >= d) high = mid ;
		else low = mid ;
	}

	return high ;
}

inline int block_id (int b) { return 2 * n + 2 * b ; }

#define mid (s + e) >> 1
#define lc v << 1
#define rc lc | 1

void build (int v = 1 , int s = 0 , int e = 2 * n) {
	if (e - s == 1) {
		add_clause(block_id(v) ^ 1 , ord[s] ^ 1) ;
		return ;
	}

	add_clause(block_id(v) ^ 1 , block_id(lc)) ; 
	add_clause(block_id(v) ^ 1 , block_id(rc)) ; 

	build(lc , s , mid) ;
	build(rc , mid , e) ;
}

void find_edges (int val , int l , int r , int v = 1 , int s = 0 , int e = 2 * n) {
	if (r <= s || e <= l) return ;
	if (l <= s && e <= r) {
		add_clause(val ^ 1 , block_id(v)) ;
		return ;
	}

	find_edges(val , l , r , lc , s , mid) ;
	find_edges(val , l , r , rc , mid , e) ;
}

