		init(n);
	}
	void init(size_type n = 0){
		G.clear(); rG.clear(); nG.clear();
		G.resize(n); rG.resize(n);
	}

	void add_edge(size_type from, size_type to){
		G[from].push_back(to);
		rG[to].push_back(from);
	}

	void clause(size_type x, size_type y){
		size_type m = G.size() / 2;
		add_edge(x < m ? x + m : x - m, y);
		add_edge(y < m ? y + m : y - m, x);
	}

