		}
		vs.push_back(v);
	}
	void rdfs(int v, int k){
		used[v] = true;
		cmp[v] = k;

		size_type sz = rG[v].size();
		for(size_type i = 0; i < sz; ++i){
			if( !used[ rG[v][i] ] ) rdfs( rG[v][i], k );
		}
	}

