		for(int i = 0; i < n; ++i)
		for(int j = 0; j < n; ++j){
			if(i == j){ continue; }
			if(i < j && abs(xs[i] - xs[j]) < md){
				scc.clause(i + m, j + m);
			}
			if(abs(xs[i] - ys[j]) < md){
				scc.clause(i + m, j + n + m);
			}
			if(i < j && abs(ys[i] - ys[j]) < md){
				scc.clause(i + n + m, j + n + m);
			}
		}
		scc.compute();

		bool ok = true;
		for(int i = 0; i < m; ++i){
			if(scc.cmp[i] == scc.cmp[i + m]){
				ok = false;
				break;
			}
		}

		if(ok){
			lt = md;
		}
		else{
			rt = md - 1;
		}
	}
	printf("%d\n", lt);
}



