          while(cur > 1){
            sat.add_if(cur, cur / 2);
            cur /= 2;
          }

          int l = upper_bound(ALL(v), v[i] - d) - v.begin();
          int r = lower_bound(ALL(v), v[i] + d) - v.begin();

          {
            int L = l + k;
            int R = i + k;

            while(L < R){
              if(R & 1){
                --R;
                sat.not_coexist(i+k, R);
              }
              if(L & 1){
                sat.not_coexist(i+k, L);
                ++L;
              }
              R >>= 1;
              L >>= 1;
            }
          }

          {
            int L = i + 1 + k;
            int R = r + k;

            while(L < R){
              if(R & 1){
                --R;
                sat.not_coexist(i+k, R);
              }
              if(L & 1){
                sat.not_coexist(i+k, L);
                ++L;
              }
              R >>= 1;
              L >>= 1;
            }
          }
        }

        vector<bool> a;

        return sat.solve(a);
      };

    LLI lb = 0, ub = INT_MAX;
    while(abs(lb-ub) > 1){
      LLI mid = (lb+ub) / 2;

      if(check(mid)){
        lb = mid;
      }else{
        ub = mid;
      }
    }

    auto ans = lb;
    cout << ans << endl;
  }

  return 0;
}

