template <typename G = Graph> struct SCC {
    G g;
    Graph rg;
    vector<int> comp, ord;
    vector<bool> used;
    int num; // 連結成分の数

    SCC(G &g) : g(g), rg(g.size()), comp(g.size(), -1), used(g.size()) {
        rep(i, g.size()) for(auto &e : g[i]) rg[e].emplace_back(i);
        ord.reserve(g.size());
        build();
    };
    SCC(int n) : g(n), rg(n), comp(n, -1), used(n) { ord.reserve(n); };

    vector<pii> A;
    inline void add(int a, int b) {
        g[a].emplace_back(b);
        rg[b].emplace_back(a);
        A.eb(a, b);
    }

    inline void undo(int n = 1) {
        rep(_, n) {
            auto [a, b] = A.back();
            A.pop_back();
            g[a].pop_back(), rg[b].pop_back();
        }
    }
    int operator[](int k) { return comp[k]; }
    void dfs(int x) {
        if(used[x]) return;
        used[x] = true;
        for(auto &e : g[x])
            if(!used[e]) dfs(e);
        ord.emplace_back(x);
    }
    void rdfs(int x, int cnt) {
        if(comp[x] != -1) return;
        comp[x] = cnt;
        for(int &e : rg[x])
            if(comp[e] == -1) rdfs(e, cnt);
    }
    void build() {
        rep(i, g.size()) dfs(i);
        reverse(all(ord));
        num = 0;
        for(int &i : ord)
            if(comp[i] == -1) { rdfs(i, num), num++; }
    }

    void rebuild() {
        comp = vi(g.size(), -1), used = vector<bool>(g.size());
        num = 0;
        ord.clear();
        build();
    }

    // 強連結成分を潰した DAG を返す
    Graph getGraph() {
        Graph res(num);
        rep(i, g.size()) {
            for(auto &e : g[i]) {
                if(comp[e] == comp[i]) continue;
                res[comp[i]].emplace_back(comp[e]);
            }
        }
        rep(i, g.size()) UNIQUE(res[i]);
        return res;
    }
    // 強連結成分ごとに属する頂点を返す
    vector<vector<int>> belong() {
        vector<vector<int>> res(num);
        rep(i, g.size()) res[comp[i]].emplace_back(i);
        return res;
    }
};

struct TwoSat : SCC<Graph> {
    int n;
    using SCC::SCC;
    TwoSat(int n) : n(n), SCC(n * 2) {}
    // not i = i + n
    inline int rev(int x) { return x >= n ? x - n : x + n; }
    inline int revid(int x) { return rev(id(x)); }
    inline int id(int x) { return x < 0 ? n - x - 1 : x - 1; }
    inline void IF(int x, int y) {
        // x => y
        add(x, y), add(rev(y), rev(x));
    }
    void OR(int x, int y) { IF(rev(id(x)), id(y)); }
    vector<int> solve() {
        build();
        vector<int> res(n);
        rep(i, n) {
            if(comp[i] == comp[rev(i)]) return vector<int>();
            res[i] = comp[i] > comp[rev(i)];
        }
        return res;
    }
    bool can() {
        rebuild();
        rep(i, n) {
            if(comp[i] == comp[rev(i)]) return false;
        }
        return true;
    }
};

const int N = 100;
main() {
    INT(n);
    vi _x(n * 2 + 2), ord(n * 2);
    auto x = _x.begin() + n + 1;
    rep2(i, 1, n) cin >> x[i] >> x[-i];
    rep2(i, 1, n) ord[i * 2 - 2] = i, ord[i * 2 - 1] = -i;
    sort(all(ord), [&](int i, int j) { return x[i] < x[j]; });
    vi y(n * 2);
    rep2(i, 1, n) y[i * 2 - 2] = x[i], y[i * 2 - 1] = x[-i];
    sort(all(y));
    vi _rev(n * 2 + 2);
    auto rev = _rev.begin() + n + 1;
    rep(i, n * 2) rev[ord[i]] = i;
    TwoSat sat(n * 2 + (n * 2 + N - 1) / N * 2);
    int now = n * 2 - 1;
    vi TRUE(n * 2), FALSE(n * 2);
    rep(i, n * 2) {
        if(i % N == 0) now++, TRUE[i] = now;
        sat.add(sat.id(ord[i]), now);
    }
    rep(i, n * 2) {
        if(i % N == 0) now++, FALSE[i] = now;
        sat.add(now, sat.revid(ord[i]));
    }
    auto solve = [&](int d) {
        int cnt = 0;
        auto add_edge = [&](auto &&f, int now, int l, int r, int v) -> void {
            if(l <= v and v < r) f(f, now, l, v - 1, n * 2), f(f, now, v + 1, r, n * 2);
            while(l % N and l < r) {
                sat.OR(-now, -ord[l]);
                cnt += 2;
                l++;
            }
            while(l + N <= r) {
                sat.add(sat.id(now), FALSE[l]);
                ++cnt;
                sat.add(TRUE[l], sat.revid(now));
                ++cnt;
                l += N;
            };
            while(l < r) {
                sat.OR(-now, -ord[l]);
                cnt += 2;
                l++;
            }
        };
        rep2(i, -n, n) {
            if(!i) continue;
            int pos = x[i];
            int l = ub(y, pos - d);
            add_edge(add_edge, i, l, rev[i], rev[-i]);
            int r = lb(y, pos + d);
            add_edge(add_edge, i, rev[i] + 1, r, rev[-i]);
        }
        bool res = sat.can();
        sat.undo(cnt);
        return res;
    };

    int l = 0, r = 1e9 + 1;
    while(l < r - 1) {
        int mid = (l + r) >> 1;
        (solve(mid) ? l : r) = mid;
    }
    cout << l << endl;
}

