	int flags[2][n];
	for (int i = 0; i < n; ++i) {
		scanf("%d%d", &flags[0][i], &flags[1][i]);
	}
	int ok = 0, ng = 1000000001;
	int d;
	while (ng - ok > 1) {
		d = (ok + ng) / 2;
		two_sat ts(n);
		for (int i = 0; i < n; ++i) {
			for (int j = i + 1; j < n; ++j) {
				for (int k = 0; k < 4; ++k) {
					bool f = k / 2, g = k % 2;
					if (abs(flags[f][i] - flags[g][j]) < d) {
						ts.add_clause(i, f, j, g);
					}
				}
			}
		}
		if (ts.satisfiable()) ok = d;
		else ng = d;
	}
	printf("%d\n", ok);
	return 0;
}

