    while(h - l > 1){
        int mid = (l + h) / 2;
        scc_decomposition scc(2 * N);
        rep(i, N){
            rep(j, N){
                if(i == j) continue;
                if(abs(A[i].first - A[j].first) < mid) scc.add(i, j + N);
                if(abs(A[i].first - A[j].second) < mid) scc.add(i, j);
                if(abs(A[i].second - A[j].first) < mid) scc.add(i + N, j + N);
                if(abs(A[i].second - A[j].second) < mid) scc.add(i + N, j);
            }
        }
        scc.scc();
        bool ok = true;

        rep(i, N){
            if(scc.cmp[i] == scc.cmp[i + N]) ok = false;
        }

        if(ok) l = mid;
        else h = mid;

    }

    output(l);

    return 0;
}

