struct Data{
	int x,id;
	Data() {}
	Data(int x,int id):x(x),id(id) {}
	bool operator < (const Data &d) const {return x<d.x;}
}D[maxn<<1];

namespace SegTree{
	int id[maxnd];
#define lc (nd<<1)
#define rc (nd<<1|1)
#define mid ((s+t)>>1)

	void build(int nd,int s,int t)
	{
		if (s==t)
		{
			id[nd]=D[s].id^1;
			return;
		}
		id[nd]=++totnd;
		build(lc,s,mid);
		build(rc,mid+1,t);
	}

	void addedge0(int nd,int s,int t)
	{
		if (s==t) return;
		addedge(id[nd],id[lc]);
		addedge(id[nd],id[rc]);
		addedge0(lc,s,mid);
		addedge0(rc,mid+1,t);
	}

	void addedge1(int nd,int s,int t,int l,int r,int u)
	{
		bool flag=0;
		flag|=s<=pos[u]&&pos[u]<=t;
		flag|=s<=pos[u^1]&&pos[u^1]<=t;
		if (!flag&&l<=D[s].x&&D[t].x<=r)
		{
			addedge(u,id[nd]);
			return;
		}
		if (s==t) return;
		addedge1(lc,s,mid,l,r,u);
		addedge1(rc,mid+1,t,l,r,u);
	}
#undef lc
#undef rc
#undef mid
};

