	}
	totnd=n<<1|1;
	sort(D+1,D+n+n+1);
	for (i=1;i<=n+n;i++)
		pos[D[i].id]=i;
	SegTree::build(1,1,n+n);
}

bool search(int u)
{
	if (col[u]==1) return 1;
	if (col[u^1]==1&&u<=2*n+1) return 0;
	col[u]=1;
	S[++S[0]]=u;
	for (int p=FIR[u];p;p=NEXT[p])
		if (!search(TO[p])) return 0;
	return 1;
}

