int n,tot,num,scc,lc[maxn*4],rc[maxn*4],t[maxn*4],bre[maxn*4],dfn[maxn*4],low[maxn*4],bel[maxn*4];
stack<int> s;
void build(int &v,int l,int r)
{
	if(l==r)
	{
		v=l;return;
	}
	v=++tot;
	int mid=(l+r)/2;
	build(lc[v],l,mid);
	build(rc[v],mid+1,r);
	addedge(v,lc[v]);addedge(v,rc[v]);
}
void add(int v,int l,int r,int u,int tl,int tr)
{
	if(l>tr||r<tl)return;
	if(tl<=l&&r<=tr)
	{
		addedge(u,v);
		return;
	}
	int mid=(l+r)/2;
	add(lc[v],l,mid,u,tl,tr);
	add(rc[v],mid+1,r,u,tl,tr);
}
void dfs(int x)
{
	int y;
	dfn[x]=low[x]=++num;
	s.push(x);
	for(int i=h[x];i;i=e[i].next)
	{
		y=e[i].to;
		if(!dfn[y])
		{
			dfs(y);
			low[x]=min(low[x],low[y]);
		}
		else if(!bel[y])low[x]=min(low[x],dfn[y]);
	}
	if(low[x]==dfn[x])
	{
		bel[x]=++scc;
		while(s.top()!=x)bel[s.top()]=scc,s.pop();
		s.pop();
	}
}
void csh()
{
	int x;
	memset(h,0,sizeof(h));
	memset(bel,0,sizeof(bel));
	memset(low,0,sizeof(low));
	memset(dfn,0,sizeof(dfn));
	num=cnt=scc=0;tot=2*n;
	build(x,1,2*n);	
}
bool check(int mid)
{
	csh();
	int l,r;
	for(int i=1;i<=2*n;i++)
	{
		l=upper_bound(a+1,a+2*n+1,(node){a[i].x-mid,INT_MAX})-a;
		r=lower_bound(a+1,a+2*n+1,(node){a[i].x+mid,0})-a-1;
		if(l<i)add(2*n+1,1,2*n,bre[i],l,i-1);
		if(i<r)add(2*n+1,1,2*n,bre[i],i+1,r);
		if(l>i||r<i)add(2*n+1,1,2*n,bre[i],l,r);
	}
	for(int i=1;i<=2*n;i++)if(!dfn[i])dfs(i);
	for(int i=1;i<=2*n;i++)if(bel[i]==bel[bre[i]])return 0;
	return 1;
}
int main()
{
	int x,maxx=0;
	scanf("%d",&n);tot=2*n;
	for(int i=1;i<=n;i++)
	{
		scanf("%d %d",&a[i].x,&a[i+n].x);
		maxx=max(maxx,max(a[i].x,a[i+n].x)-min(a[i-1].x,a[i+n-1].x));
		a[i].id=a[i+n].id=i;
	}
	sort(a+1,a+2*n+1);
	for(int i=1;i<=2*n;i++)
	{
		if(!t[a[i].id])t[a[i].id]=i;
		else bre[i]=t[a[i].id],bre[t[a[i].id]]=i;
	}
	int l=1,r=maxx,mid,ans=0;
	while(l<=r)
	{
		mid=(l+r)/2;
		if(check(mid))ans=max(ans,mid),l=mid+1;
		else r=mid-1;
	}
	printf("%d\n",ans);
	return 0;
}

