		Y[i]=lower_bound(vx.begin(),vx.end(),Y[i])-vx.begin();
	}
	//if(solve(2)) puts("YES");
	//return 0;
	int l=-1,r=min(INF/(n-1))+1;
	while(r-l>1)
	{
		int m=(l+r)/2;
		if(solve(m)) l=m;
		else r=m;
		//printf("%d %d\n",l,r);
	}
	printf("%d\n",l);
	return 0;
}

