int sget(int lidx,int ridx) { int ret=INT_MAX; for(lidx+=2*n,ridx+=2*n;lidx<ridx;lidx>>=1,ridx>>=1) { if(lidx&1) ret=min(ret,sval[lidx++]); if(ridx&1) ret=min(ret,sval[--ridx]); } return ret; }

int other(int id) { return id==-1?-1:id<n?id+n:id-n; }
int getedge(int l,int h) {
	set<int>::iterator it=lft.lower_bound(l);
	return it==lft.end()||*it>h?-1:*it;
}
int getedge(int l,int m,int h) {
	if(m<l||m>h) return getedge(l,h);
	int ret=-1;
	if(ret==-1) ret=getedge(l,m-1);
	if(ret==-1) ret=getedge(m+1,h);
	return ret;
}
int getedge(int at) {
	int ret=-1;
	if(at<n) {
		if(ret==-1) ret=getedge(ala[at],pos[at],aha[at]);
		if(ret==-1) ret=getedge(alb[at],pos[at+n],ahb[at]);
	} else {
		if(ret==-1) ret=getedge(bla[at-n],pos[at-n],bha[at-n]);
		if(ret==-1) ret=getedge(blb[at-n],pos[at],bhb[at-n]);
	}
	if(ret==-1) return ret;
	ret=ret<n?aa[ret].idx:bb[ret-n].idx+n;
	return other(ret);
}
void update(int &ret,int l,int h) {
	if(l<=h) {
		int cur=sget(l,h+1);
		//printf("[updating %d..%d -> %d]\n",l,h,cur);
		ret=min(ret,cur);
	}
}
void update(int &ret,int l,int m,int h) {
	if(l<=m&&m<=h) update(ret,l,m-1),update(ret,m+1,h); else update(ret,l,h);
}
void update(int &ret,int at) {
	if(at<n) {
		update(ret,ala[at],pos[at],aha[at]);
		update(ret,alb[at],pos[at+n],ahb[at]);
	} else {
		update(ret,bla[at-n],pos[at-n],bha[at-n]);
		update(ret,blb[at-n],pos[at],bhb[at-n]);
	}
}
//int tmp=0;
void tarjan(int at,int dp=0) {
	key[at]=minkey[at]=nkey++; stck[nstck++]=at; sset(pos[other(at)],key[at]); lft.erase(pos[other(at)]);
	//REP(i,dp) printf("  "); printf("%d%c=%d (%d,%d)\n",at%n+1,at<n?'A':'B',key[at],pos[at],pos[other(at)]); if(++tmp>100) exit(0);
	while(true) {
		int to=getedge(at);
		if(to==-1) break;
		tarjan(to,dp+1);
		if(minkey[to]<minkey[at]) minkey[at]=minkey[to];
	}
	update(minkey[at],at);
	//REP(i,dp) printf("  "); printf("%d%c->%d\n",at%n+1,at<n?'A':'B',minkey[at]);
	if(minkey[at]==key[at]) {
		while(comp[at]==-1) { int to=stck[--nstck]; sset(pos[other(to)],INT_MAX); comp[to]=ncomp; } ++ncomp;
	}
}

