}
void build2(int u,int l=0,int r=nb-1) {
    if(l==r)return;
    build2(l(u),l,mid),build2(r(u),mid+1,r);
    twosat.link(u,l(u),0,0);
    twosat.link(u,r(u),0,0);
}
void upd1(int u,int v,int f,int L,int R,int l=0,int r=nb-1) {
    if(l>=L&&r<=R) {twosat.link(v,u,f,0); return;}
    if(l>R||r<L)return;
    upd1(l(u),v,f,L,R,l,mid),upd1(r(u),v,f,L,R,mid+1,r);
}
void upd2(int u,int v,int f,int x,int l=0,int r=nb-1) {
    if(l==r) {twosat.link(v,u,f,1); return;}
    x<=mid?upd2(l(u),v,f,x,l,mid):upd2(r(u),v,f,x,mid+1,r);
}
int lb(int x) {return lower_bound(b,b+nb, (D) {x,0,0})-b;}
int rb(int x) {return upper_bound(b,b+nb, (D) {x,0,0})-b-1;}
