void dfs(int v){
	if(u[v]) return;
	u[v] = 1;
	for(int i=0;i<edge[v].size();i++){
		if(!u[edge[v][i]]) dfs(edge[v][i]);
	}
	c[k++] = v;
}
void sfd(int v){
	if(u[v]) return;
	u[v] = 1; p[v] = k;
	for(int i=0;i<redge[v].size();i++){
		if(!u[redge[v][i]]) sfd(redge[v][i]);
	}
}
