	for(int i=(1<<16)+2*n-1;i>=0;i--){
		if(!u[c[i]]){
			sfd(c[i]); k++;
		}
	}
	for(int i=0;i<2*n;i++){
		if(p[(1<<15)-1+i] == p[(1<<16)+i]) return false;
	}
	return true;
}
