#define mid ((l + r) >> 1)
inline void build(int k, int l, int r) {
    if (l == r) {
        id[k] = ha[l].second;
        return ;
    }
    id[k] = ++cntNode;
    build(lSon, l, mid), g[id[k]].push_back(id[lSon]);
    build(rSon, mid + 1, r), g[id[k]].push_back(id[rSon]);
}
inline void modify(int k, int l, int r, int from, int x, int y) {
    if (x <= l && r <= y) {
        g[from].push_back(id[k]);
        return ;
    }
    if (x <= mid)
        modify(lSon, l, mid, from, x, y);
    if (mid < y)
        modify(rSon, mid + 1, r, from, x, y);
}
