int stk[maxT], top, dfn[maxT], low[maxT], tim, belong[maxT], cntSCC;
void tarjan(int x) {
    stk[++top] = x, dfn[x] = low[x] = ++tim;
    for (int y : g[x])
        if (!dfn[y])
            tarjan(y), low[x] = min(low[x], low[y]);
        else
            if (!belong[y])
                low[x] = min(low[x], dfn[y]);
    if (dfn[x] == low[x]) {
        int y;
        ++cntSCC;
        do
            y = stk[top--], belong[y] = cntSCC;
        while (y != x);
    }
}

