void build(int x,int l,int r)
{
	if (l==r)
	{
		id[l]=x;
		return;
	}
	int mid=l+r>>1;
	build(x<<1,l,mid),build(x<<1|1,mid+1,r),insert(x+n*2,(x<<1)+n*2),insert(x+n*2,(x<<1|1)+n*2);
}

void addedge(int x,int st,int en,int l,int r,int p)
{
	if (st==l&&en==r)
	{
		insert(p,x+n*2);
		return;
	}
	int mid=l+r>>1;
	if (en<=mid) addedge(x<<1,st,en,l,mid,p);
	else if (mid+1<=st) addedge(x<<1|1,st,en,mid+1,r,p);
	else addedge(x<<1,st,mid,l,mid,p),addedge(x<<1|1,mid+1,en,mid+1,r,p);
}

void tarjan(int x)
{
	DFN[x]=low[x]=++idx,st.push(x),exist[x]=1;
	for (int i=last[x],y;i;i=nxt[i])
		if (!DFN[y=tov[i]]) tarjan(y),low[x]=min(low[x],low[y]);
		else if (exist[y]) low[x]=min(low[x],DFN[y]);
	if (DFN[x]==low[x])
	{
		int y;++bcnt;
		do
		{
			exist[y=st.top()]=0,st.pop(),bid[y]=bcnt;
		}while (x!=y);
	}
}

bool judge(int dis)
{
	--dis,memset(last,0,sizeof last),memset(tov,0,sizeof tov),memset(nxt,0,sizeof nxt),tot=0;
	build(1,1,n<<1);
	for (int i=1;i<=n<<1;++i)
		if (srt[i].tp) insert(id[i]+n*2,srt[i].id*2-1);
		else insert(id[i]+n*2,srt[i].id*2);
	for (int i=1;i<=n<<1;++i)
	{
		int l=1,r=i,st=i,en=i;
		for (int mid;l<=r;)
		{
			mid=l+r>>1;
			if (srt[mid].key>=srt[i].key-dis) r=(st=mid)-1;
			else l=mid+1;
		}
		for (;en>=st&&srt[en].id==srt[i].id;--en);
		if (st<=en) addedge(1,st,en,1,n<<1,srt[i].id*2-(srt[i].tp^1));
		//for (int j=st;j<=en;++j) insert(srt[i].id*2-(srt[i].tp^1),srt[j].id*2-srt[j].tp);
		l=i,r=n<<1,st=i,en=i;
		for (int mid;l<=r;)
		{
			mid=l+r>>1;
			if (srt[mid].key<=srt[i].key+dis) l=(en=mid)+1;
			else r=mid-1;
		}
		for (;st<=en&&srt[st].id==srt[i].id;++st);
		if (st<=en) addedge(1,st,en,1,n<<1,srt[i].id*2-(srt[i].tp^1));
		//for (int j=st;j<=en;++j) insert(srt[i].id*2-(srt[i].tp^1),srt[j].id*2-srt[j].tp);
	}
	memset(DFN,0,sizeof DFN),bcnt=idx=0;
	for (int x=1;x<=(n<<1)+id[n<<1];++x) if (!DFN[x]) tarjan(x);
	for (int i=1;i<=n;++i) if (bid[i*2-1]==bid[i*2]) return 0;
	return 1;
}

void binary_search()
{
	int l=0,r=1000000000;
	for (int mid;l<=r;)
	{
		mid=l+r>>1;
		if (judge(mid)) l=(ans=mid)+1;
		else r=mid-1;
	}
}

