pair <int, int> close(int y) {
	int l = lower_bound(vec.begin(), vec.end(), make_pair(y - d, 0)) - vec.begin();
	int r = upper_bound(vec.begin(), vec.end(), make_pair(y + d, N)) - vec.begin();
	return {l, r};
}
bool mrk[N];
set <int> seg[N * 6];

void put(int p, int u, int tp) {
	 p += (1 << 15);
	 while (p) {
	 	if (tp == 1)
			seg[p].insert(u);
		else
			seg[p].erase(u);
		p /= 2;
	 }

}

int get(int l, int r) {
	if (r <= l)
		return 0;
	l += (1 << 15);
	r += (1 << 15) - 1;
	if (seg[l].size())
		return *seg[l].begin();
	if (seg[r].size())
		return *seg[r].begin();
	while (l / 2 != r / 2) {
		if (l % 2 == 0 && seg[l + 1].size())
			return *seg[l + 1].begin();
		if (r % 2 == 1 && seg[r - 1].size())
			return *seg[r - 1].begin();
		l /= 2;
		r /= 2;
	}
	return 0;
}
vector <int> st;

void dfs(int v) {
	if (mrk[v])
		cout << 1 / 0 << endl;
	mrk[v] = 1;
	bool ok = 1;
	while (ok) {
		ok = 0;
		int u = get(cl[v], plc[v]);
		if (u) {
			put(plc[u ^ 1], u, -1);
			dfs(u);
			ok = 1;
			continue;
		}
		u = get(plc[v] + 1, cr[v]);
		if (u) {
			put(plc[u ^ 1], u, -1);
			dfs(u);
			ok = 1;
		}
	}
	st.push_back(v);
}
int com[N];
int cnt;

void rev(int v) {
	if (com[v])
		cout << 1 / 0 << endl;
	com[v] = cnt;
	bool ok = 1;
	while (ok) {
		ok = 0;
		int u = get(cl[v ^ 1], plc[v ^ 1]);
		if (u) {
			put(plc[u], u, -1);
			rev(u);
			ok = 1;
			continue;
		}
		u = get(plc[v ^ 1] + 1, cr[v ^ 1]);
		if (u) {
			put (plc[u], u, -1);
			rev(u);
			ok = 1;
			continue;
		}
	}
}

bool can() {
	cnt = 0;
	memset(mrk, 0, sizeof mrk);
	for (int i = 2; i <= 2 * n + 1; i++) {
		cl[i] = close(x[i]).first;
		cr[i] = close(x[i]).second;
	}
	for (int i = 2; i <= 2 * n + 1; i++)
		put(plc[i ^ 1], i, 1);	
	for (int i = 2; i <= 2 * n + 1; i++) 
		if (!mrk[i]) {
			put(plc[i ^ 1], i, -1);
			dfs(i);
		}
	memset(com, 0, sizeof com);
	for (int i = 2; i <= 2 * n + 1; i++)
		put(plc[i], i, 1);
	while (st.size()) {	
		int v = st.back();
		st.pop_back();
		if (com[v])
			continue;
		cnt++;
		put(plc[v], v, -1);
		rev(v);
	}
	for (int i = 2; i <= 2 * n + 1; i++) 
		if (com[i] == com[i ^ 1]) {
			return 0;
		}
	return 1;
}

