namespace Tarjan
{
	int st[MAXM],top;
	int co[MAXM],co_cnt;
	int dfn[MAXM],low[MAXM],dfn_cnt;

	void tarjan(int x)
	{
		st[++top]=x;
		dfn[x]=low[x]=++dfn_cnt;
		for(auto y:v[x])
		{
			if(!dfn[y])
			{
				tarjan(y);
				Min(low[x],low[y]);
			}
			else if(!co[y])
				Min(low[x],dfn[y]);
		}
		if(dfn[x]==low[x])
		{
			++co_cnt;
			while(st[top]!=x)
				co[st[top--]]=co_cnt;
			co[st[top--]]=co_cnt;
		}
	}

	inline void clear()
	{
		top=co_cnt=dfn_cnt=0;
		memset(co,0,sizeof(co));
		memset(dfn,0,sizeof(dfn));
	}

	inline void tarjan()
	{
		clear();
		for(int i=1;i<=tree_cnt;i++)
			if(!dfn[i])
				tarjan(i);
	}

	inline bool check()
	{
		for(int i=1;i<=n;i++)
		{
			int x1=rev[i].first;
			int x2=rev[i].second;
			if(co[in[x1]]==co[out[x1]])
				return false;
			if(co[in[x2]]==co[out[x2]])
				return false;
		}
		return true;
	}
}

