class DirectedGraph
{
    int V; // 頂点数
    vector<vector<int> > to;
    vector<vector<int> > from;

    vector<bool> used;
    vector<int> vs;

    void dfs(int v)
    {
        used[v] = true;
        for (auto t : to[v]) if (!used[t]) dfs(t);
        vs.push_back(v);
    }
    void rdfs(int v, int k)
    {
        used[v] = true;
        cmp[v] = k;
        for (auto t : from[v]) if (!used[t]) rdfs(t, k);
    }

public:
    vector<int> cmp;
    DirectedGraph(int V) : V(V),
                           to(vector<vector<int> >(V)), 
                           from(vector<vector<int> >(V)),
                           cmp(vector<int>(V))
                           {}
    void add_edge(int from_, int to_)
    {
        to[from_].push_back(to_);
        from[to_].push_back(from_);
    }

    int scc()
    {
        used = vector<bool>(V, false);
        vs.clear();
        for (int v = 0; v < V; v++) if (!used[v]) dfs(v);

        used = vector<bool>(V, false);
        int k = 0;
        for (int i = vs.size() - 1; i >= 0; i--) if (!used[vs[i]]) rdfs(vs[i], k++);
        return k;
    }
};

int N;
vector<int> x, y;

bool nibun(int d)
{
    DirectedGraph g(N * 2);
    for (int i = 0; i < N; i++)
    {
        for (int j = 0; j < i; j++)
        {
            if (abs(x[i] - x[j]) < d)
            {
                g.add_edge(i, j + N);
                g.add_edge(j, i + N);
            }
            if (abs(y[i] - y[j]) < d)
            {
                g.add_edge(i + N, j);
                g.add_edge(j + N, i);
            }
            if (abs(x[i] - y[j]) < d)
            {
                g.add_edge(i, j);
                g.add_edge(j + N, i + N);
            }
            if (abs(y[i] - x[j]) < d)
            {
                g.add_edge(j, i);
                g.add_edge(i + N, j + N);
            }
        }
    }
    g.scc();
    for (int i = 0; i < N; i++) if (g.cmp[i] == g.cmp[i+N]) return false;

    return true;
}

