	for(int i=1;i<=n;i++) for(int j=0;j<2;j++) x[i][j]=lower_bound(t+1,t+m+1,(nod){x[i][j],i+j*n})-t,s[x[i][j]].push_back(i+j*n);
	for(int l=0,r=1000000000,mid=(l+r)>>1;l<=r;mid=(l+r)>>1) if(chk(mid)) l=mid+1,g=mid;else r=mid-1;
