struct edge{int to, cost, id;};

class Graph
{
public:
    int N;
    vector<vector<edge>> G;

    Graph(int N): N(N){
        G = vector<vector<edge>>(N, vector<edge>(0));
    }

    void add_Directed_edge(int from, int to, int cost = 1, int id = 0){
        G[from].push_back(edge({to, cost, id}));
    }

    void add_Undirected_edge(int v1, int v2, int cost = 1, int id = 0){
        add_Directed_edge(v1, v2, cost, id);
        add_Directed_edge(v2, v1, cost, id);
    }

    //SCC decomposition
    void dfs(int v, vector<bool> &used, vec &vs){
        used[v] = true;
        REP(i, G[v].size()){
            if(!used[G[v][i].to]) dfs(G[v][i].to, used, vs);
        }
        vs.push_back(v);
    }
    void rdfs(int v, int k, vector<bool> &used, vec &cmp){
        used[v] = true;
        cmp[v] = k;
        REP(i, G[v].size()){
            if(!used[G[v][i].to]) rdfs(G[v][i].to, k, used, cmp);
        }
    }
    //u->v => cmp[u]<cmp[v]
    vec scc(int &k){
        vector<bool> used(N, false);
        vec vs(0), cmp(N);
        REP(i, N){
            if(!used[i]) dfs(i, used, vs);
        }
        //reverse graph
        Graph rG(N);
        REP(v, N) REP(i, G[v].size()) rG.add_Directed_edge(G[v][i].to, v, G[v][i].cost);

        fill(used.begin(), used.end(), false);
        k = 0;
        IREP(i, vs.size()){
            if(!used[vs[i]]) rG.rdfs(vs[i], k++, used, cmp);
        }
        return cmp;
    }
    //2-SAT用
    //N=2nとして、0,...,n-1の否定をn,...,2n-1で表す
    int NOT(int X){ return (X + N / 2) % N; }
    void add_X(int X){
        add_Directed_edge(NOT(X), X);    
    } 
    void add_AorB(int A, int B){
        add_Directed_edge(NOT(A), B);
        add_Directed_edge(NOT(B), A);
    }
    void add_AisB(int A, int B){
        add_Directed_edge(A, B);
        add_Directed_edge(B, A);
        add_Directed_edge(NOT(A), NOT(B));
        add_Directed_edge(NOT(B), NOT(A));
    }
    void add_AthenB(int A, int B){
        add_Directed_edge(A, B);
        add_Directed_edge(NOT(B), NOT(A));
    }
    bool solve_2SAT(vector<bool> &ans){
        int k;
        int n = N / 2;
        vec cmp = scc(k);
        ans.resize(n);
        REP(i, n){
            if(cmp[i] == cmp[i + n]) return false;
            else if(cmp[i] < cmp[i + n]) ans[i] = false;
            else ans[i] = true;
        }
        return true;
    }

    void add_range(int v, int a, int b, int k, int l, int r){
        if(r <= a || b <= l) return;
        if(a <= l && r <= b){
            add_AthenB(v, NOT(k));
        }
        else{
            add_range(v, a, b, k * 2 + 1, l, (l + r) / 2);
            add_range(v, a, b, k * 2 + 2, (l + r) / 2, r);
        }
    }
    void add_range(int v, int a, int b) { add_range(v, a, b, 0, 0, (N / 2 + 1) / 2); }

};

