            int j = Lower_bound(v, v[i] + d);
            G.add_range(i + n - 1, i + 1, j);
        }
        REP(i, n - 1){
            G.add_AthenB(2 * i + 1, i);
            G.add_AthenB(2 * i + 2, i);
        }

        v_bool ans;
        if(G.solve_2SAT(ans)) d0 = d;
        else d1 = d;
    }
    Out(d0);

    return 0;
}

