const int INF = 1e9+7;

template <typename T>
class SegTree{
	// セグメントツリーをたどる
	void prop(int l, int r, T v, int a, int b, int k=1){
		if( l <= a && b <= r ){
			// 完全に範囲内の場合
			setRelation(k, N+v);
		}else if( l < b && a < r ){
			// 中途半端に含まれる場合
			int m = (a+b) / 2;
			prop(l,r,v, a, m, k*2);
			prop(l,r,v, m, b, k*2+1);
		}
	}

public:
	int N;
	SegTree(int _N){
		// _N <= (N = 2^k) を満たすNを見つける
		N = 1;
		while( N < _N ) N<<=1;
	}
	void pRelation(){
		// 子がTrueなら、親もTrue
		rep(i,N) if(i){
			//cout << "pRelation: " << (SegOff + i*2) << " " << (SegOff + i) << endl;
			sat.add_edge(SegOff + i*2,   SegOff + i);
			sat.add_edge(SegOff + i*2+1, SegOff + i);
		}
	}
	void cRelation(int i, int v){
		int p = SegOff + N+i;
		//cout << "cRelation: " << p << " " << v << endl;
		sat.add_edge( p, v );
		sat.add_edge( v, p );
		sat.add_edge( -p, -v );
		sat.add_edge( -v, -p );
	}
	// セグメントツリーの更新(範囲に加算)
	void add(int l, int r, T v){
		//cout << "sg.add(): " << l << " " << r << " :" << v << endl;
		prop(l,r,v,0,N);
	}
};


