inline void insert(int l,int r,int p,int z,int &y) {
    if(!y) y=++cnt;
    if(l==r) {lnk(y,z);return;}
    int mid=(l+r)>>1;
    if(p<=mid) insert(l,mid,p,z,ls[y]);
    else insert(mid+1,r,p,z,rs[y]);
}
inline void query(int l,int r,int L,int R,int z,int x) {
    if(!x) return;
    if(L<=l&&r<=R) {lnk(z,x);return;}
    int mid=(l+r)>>1;
    if(L<=mid) query(l,mid,L,R,z,ls[x]);
    if(R>mid) query(mid+1,r,L,R,z,rs[x]);
}
