	query(1,M,a[i]-k+1,a[i]-1,i*2,rt);
	query(1,M,a[i]+1,a[i]+k-1,i*2,rt);
	query(1,M,b[i]-k+1,b[i]-1,i*2+1,rt);
	query(1,M,b[i]+1,b[i]+k-1,i*2+1,rt);
    }
