bool check(int d){
	int len = 2 * n;
	vector<int> ids(2 * len);
	int cnt = 0;
	for(int i = 0; i < len; i++) ids[i + len] = cnt++;
	for(int i = len - 1; i > 0; i--) ids[i] = cnt++;
	TwoSat s(cnt);
	auto connect = [&](int l, int r, int p){
		for(l += len, r += len + 1; l < r; l >>= 1, r >>= 1){
			if(l & 1){
				s.add_or(2 * ids[l] + 1, p);
				l++;
			}
			if(r & 1){
				r--;
				s.add_or(2 * ids[r] + 1, p);
			}
		}
	};
	int l = 0, r = 0;
	for(int i = 0; i < len; i++){
		while(l < i && all[i] - all[l] >= d) l++;
		while(r < len && all[r] - all[i] < d) r++;
		if(l < i){
			connect(l, i - 1, 2 * ids[i + len] + 1);
		}
		if(i < r - 1){
			connect(i + 1, r - 1, 2 * ids[i + len] + 1);
		}
	}
	for(int i = 0; i < n; i++){
		s.add_or(2 * ids[wh[0][i] + len] + 1, 2 * ids[wh[1][i] + len] + 1);
		s.add_or(2 * ids[wh[0][i] + len], 2 * ids[wh[1][i] + len]);
	}
	for(int i = len - 1; i > 0; i--){
		// -p ^ s
		s.add_or(2 * ids[i], 2 * ids[2 * i] + 1);
		s.add_or(2 * ids[i], 2 * ids[2 * i + 1] + 1);
	}
	return s.solve();
}
