	low[u]=dfn[u]=++tim,sta[++tp]=u,insta[u]=1;
	for(int t=head[u];t;t=e[t].nxt)
		if(!dfn[e[t].r])tarjan(e[t].r),low[u]=min(low[u],low[e[t].r]);
