tuple<int, vi> strongly_connected_components(const vvi& graph) {
    const int N = graph.size();
    int C = 0, V = 0, top = 0;
    vi comp(N, -1), inx(N, -1), stack(N + 1, -1);

    auto tarjan = [&](auto&& self, int loc) -> int {
        stack[top++] = loc;
        int low = inx[loc] = V++;
        for (int nbr : graph[loc]) {
            if (inx[nbr] == -1) low = min(low, self(self, nbr));
            else if (comp[nbr] == -1) low = min(low, inx[nbr]);
        }
        if (low == inx[loc]) {
            while (stack[top] != loc)
                comp[stack[--top]] = C;
            C++;
        }
        return low;
    };

    for (int i = 0; i < N; i++) {
        if (inx[i] == -1)
            tarjan(tarjan, i);
    }
    return mt(C, comp);
}

int main() {
    setIO();

    int N; re(N); vpii locs(N); re(locs);

    vpii neg;
    F0R (i, N) {
        neg.eb(locs[i].f, 2 * i);
        neg.eb(locs[i].s, 2 * i + 1);
    }
    sort(all(neg));
    vi index(2 * N); F0R (i, 2 * N) index[neg[i].s] = i;

    int ans = 0, lo = 1, hi = 1e9;
    while (lo <= hi) {
        int mi = (lo + hi) / 2;

        vvi adj(4 * N);
        FOR (v, 1, 2 * N) {
            adj[v].pb(2 * v);
            adj[v].pb(2 * v + 1);
        }

        auto ins = [&](int i, int l, int r) {
            for (i += 2 * N, l += 2 * N, r += 2 * N; l < r; l /= 2, r /= 2) {
                if (l&1) adj[i].pb(l++);
                if (r&1) adj[i].pb(--r);
            }
        };

        F0R (f, 2 * N) {
            int l = neg[f].f;
            int i = lb(all(neg), mp(l - mi + 1, -1)) - neg.begin();
            int j = lb(all(neg), mp(l + mi, -1)) - neg.begin();
            ins(index[neg[f].s^1], i, f);
            ins(index[neg[f].s^1], f+1, j);
        }

        bool ok = true;
        vi scc = get<1>(strongly_connected_components(adj));
        F0R (f, N) ok &= scc[2 * N + index[2 * f]] != scc[2 * N + index[2 * f + 1]];

        if (ok) ans = mi, lo = mi + 1;
        else hi = mi - 1;
    }

    ps(ans);

    return 0;
}

