void sappend(int x,int l,int r,int L,int R,int I) {
	if(L<=l&&r<=R) { addedge(2*I+0,2*sz[x]+1); return; }
	int m=l+(r-l)/2;
	if(L<=m) sappend(2*x+1,l,m,L,R,I);
	if(m+1<=R) sappend(2*x+2,m+1,r,L,R,I);
}


