{
	if(l==r){ins(ind,op(b[l]));return;}int mid=(l+r)>>1;
	ins(ind,ls[ind]);ins(ind,rs[ind]);
	dfs(ls[ind],l,mid);dfs(rs[ind],mid+1,r);
}
void ade(int ind,int l,int r,int al,int ar,int x)
{
	if(al<=l&&r<=ar){ins(x,ind);return;}
	int mid=(l+r)>>1;
	if(al<=mid)ade(ls[ind],l,mid,al,ar,x);
	if(ar>mid)ade(rs[ind],mid+1,r,al,ar,x);
}
void tarjan(int x)
{
	dfn[x]=low[x]=++cn;inq[x]=1;st.push(x);
	for(int i=head[x];i;i=e[i].nxxt)
	{
		int j=e[i].to;
		if(!dfn[j]){tarjan(j);low[x]=min(low[x],low[j]);}
		else if(inq[j])low[x]=min(low[x],dfn[j]);
	}
	if(low[x]==dfn[x])
	{
		an++;
		while(!st.empty()&&st.top()!=x)
		{
			inq[st.top()]=0;f[st.top()]=an;st.pop();
		}inq[x]=0;f[x]=an;st.pop();
	}
}
