			if(s[b[i]]-s[b[mid]]<x)tas=mid,r=mid-1;
			else l=mid+1;
		}
		if(tas<i)ade(rt,1,2*n,tas,i-1,b[i]);
		l=i+1,r=2*n,tas=i;
		while(l<=r)
		{
			mid=(l+r)>>1;
			if(s[b[mid]]-s[b[i]]<x)tas=mid,l=mid+1;
			else r=mid-1;
		}
		if(tas>i)ade(rt,1,2*n,i+1,tas,b[i]);
	}cn=an=0;
	for(register int i=1;i<=js;i++)dfn[i]=low[i]=inq[i]=f[i]=0;
	while(!st.empty())st.pop();
	for(int i=1;i<=js;i++)if(!dfn[i])tarjan(i);
	for(int i=1;i<=n;i++)if(f[i]==f[i+n])return false;
	return true;
}
