void mt(int l,int r){
	int p=++sz,m=(l+r)>>1;
	t[p].l=l;t[p].r=r;
	if (l<r){
		t[p].ls=sz+1;mt(l,m);
		t[p].rs=sz+1;mt(m+1,r);
	}else t[p].ls=t[p].rs=0,w[l]=p;
}
void work(int p,int l,int r,int v){
	if (l<=t[p].l&&t[p].r<=r){
		addedge(v,sz+p);return;
	}
	int m=(t[p].l+t[p].r)>>1;
	if (l<=m) work(t[p].ls,l,r,v);
	if (r>=m+1) work(t[p].rs,l,r,v);
}
int bs1(int x,int v){
	int l=1,r=x,m,tmp=a[x].x-v+1;
	while (l<r-1){
		m=(l+r)>>1;
		if (a[m].x>=tmp) r=m;else l=m+1;
	}
	return (a[l].x>=tmp)?l:r;
}
int bs2(int x,int v){
	int l=x,r=2*n,m,tmp=a[x].x+v-1;
	while (l<r-1){
		m=(l+r)>>1;
		if (a[m].x<=tmp) l=m;else r=m-1;
	}
	return (a[r].x<=tmp)?r:l;
}
