		}
		if (v[g[i].t]) low[x]=min(low[x],dfn[g[i].t]);
	}
	if (dfn[x]==low[x]){
		bl[0]++;
		do{
			i=st[st[0]--];bl[i]=bl[0];v[i]=0;
		}while (i!=x);
	}
}
bool check(int x){
