	for (i=1;i<=2*sz;i++) h[i]=0,dfn[i]=0,v[i]=0;
	for (i=1;i<=2*n;i++){
		addedge(w[i],sz+w[po[i]]);addedge(sz+w[i],w[po[i]]);
		j=bs1(i,x);k=bs2(i,x);
		if (j<i) work(1,j,i-1,w[i]);
		if (i<k) work(1,i+1,k,w[i]);
	}
	for (i=1;i<=sz;i++)
	 if (t[i].ls) addedge(i,t[i].ls),addedge(i,t[i].rs),addedge(sz+i,sz+t[i].ls),addedge(sz+i,sz+t[i].rs);
	for (i=1,st[0]=bl[0]=now=0;i<=2*sz;i++)
