		id[i] = hh[i].second;
	}
	for (int nl = 0, nr = 1e9, md; nl <= nr; ) {
		md = (nl + nr) >> 1;
		if (Check(md)) {
			ans = md; nl = md + 1;
		} else {
			nr = md - 1;
		}
	}
	printf("%d\n", ans);

	return 0;
}

