void tpsort(int v, int prev)
{
	used[v] = true;
	for(int i = 0; i < G[v].size(); i++){
		if(used[G[v][i]]) continue;
		tpsort(G[v][i], v);
	}
	topo.push_back(v);
}

void dfs(int v, int prev, int id)
{
	used[v] = true;
	scc[v] = id;
	for(int i = 0; i < revG[v].size(); i++){
		if(used[revG[v][i]]) continue;
		dfs(revG[v][i], v, id);
	}
}

void query(int v, int a, int b, int k, int l, int r)
{
	if(b < l || r < a) return;
	if(a <= l && r <= b){
		G[v].push_back(k);
		return;
	}
	if(k*2 < V) query(v, a, b, k*2, l, (l+r)/2);
	if(k*2+1 < V) query(v, a, b, k*2+1, (l+r)/2+1, r);
}

void range(int v, int l, int r)
{
	if(l > r) return;
	 query(v, l, r, 1, 0, (1<<14)-1);
}

bool check(int d)
{
	for(int i = 1; i < V; i++) G[i].clear();
	for(int i = 1; i < Num; i++){
		if(i*2 < V) G[i].push_back(i*2);
		if(i*2+1 < V) G[i].push_back(i*2+1);
	}

	int l = 0, r = 0;
	for(int i = 0; i < 2*N; i++){
		int v = pos[vec[i].second.first][1-vec[i].second.second];
		while(vec[l].first < vec[i].first-(d-1)) l++;
		range(Num + v, l, i-1);
	}
	for(int i = 0; i < 2*N; i++){
		int v = pos[vec[i].second.first][1-vec[i].second.second];
		while(r < 2*N && vec[r].first <= vec[i].first+(d-1)) r++;
		range(Num + v, i+1, r-1);
	}

	for(int i = 1; i < V; i++) revG[i].clear();
	for(int i = 1; i < V; i++){
		for(int j = 0; j < G[i].size(); j++){
			revG[G[i][j]].push_back(i);
		}
	}

	for(int i = 1; i < V; i++) used[i] = false;
	topo.clear();
	for(int i = 1; i < V; i++) if(!used[i]) tpsort(i, -1);
	reverse(topo.begin(), topo.end());

	for(int i = 1; i < V; i++) used[i] = false;
	for(int i = 1; i < topo.size(); i++){
		if(!used[topo[i]]) dfs(topo[i], -1, i);
	}

	for(int i = 0; i < N; i++){
		if(scc[Num+pos[i][0]] == scc[Num+pos[i][1]]) return false;
	}
	return true;
}

