int n, comp[21000], vis[21000], vind[21000], l[11000], r[11000], maxd[21000];
stack< int > s;
vector< pi > v;

void forward(int index, int d) {
	vis[index] = 1;
	int x = v[vind[index]].first;
	for (int i = vind[index]-1; i >= 0; i--) {
		if (x-v[i].first >= d)
			break;
		int neigh = v[i].second + (v[i].second > n ? -n : n);
		if (!vis[neigh]) {
			//cout<<index<<" "<<neigh<<" "<<v[i].second<<endl;
			forward(neigh, d);
		}
	}	

	for (int i = vind[index]+1; i < v.size(); i++) {
		if (v[i].first-x >= d)
			break;
		int neigh = v[i].second + (v[i].second > n ? -n : n);
		if (!vis[neigh]) {
			//cout<<index<<" "<<neigh<<" "<<v[i].second<<endl;
			forward(neigh, d);
		}
	}	

	s.push(index);
}

void backward(int index, int d, int c) {
	comp[index] = c;
	index += (index > n ? -n : n);
	int x = v[vind[index]].first;
	for (int i = vind[index]-1; i >= 0; i--) {
		if (x-v[i].first >= d)
			break;
		int neigh = v[i].second;
		if (comp[neigh] == 0)
			backward(neigh, d, c);
	}

	for (int i = vind[index]+1; i < v.size(); i++) {
		if (v[i].first-x >= d)
			break;
		int neigh = v[i].second;
		if (comp[neigh] == 0)
			backward(neigh, d, c);
	}
}

bool solve(int d) {
	int cnum = 1;

	for (int i = 1; i <= 2*n; i++) {
		if (!vis[i]) {
			forward(i, d);
		}
	}

	while (!s.empty()) {
		int curr = s.top(); s.pop();
		if (comp[curr])
			continue;
		backward(curr, d, cnum);
		cnum++;
	}

	bool ok = true;
	for (int i = 1; i <= n; i++) {
		//cout<<i<<" "<<(i+n)<<" "<<comp[i]<<" "<<comp[i+n]<<endl;
		if (comp[i] == comp[i+n])
			ok = false;
		comp[i] = 0;
		comp[i+n] = 0;
		vis[i] = 0;
		vis[i+n] = 0;
	}

	return ok;
}

int main() {
	fastio;
	cin>>n;
	for (int i = 1; i <= n; i++) {
		cin>>l[i]>>r[i];
		v.pb(mp(l[i], i));
		v.pb(mp(r[i], i+n));
	}

	sort(v.begin(), v.end());

	int opt = 1e9;
	for (int i = 1; i <= n; i++) {
		int m1 = 1e9, m2 = 1e9;
		for (int j = 1; j <= n; j++) {
			if (i == j)
				continue;
			m1 = min({m1, max(abs(l[i]-l[j]), abs(l[i]-r[j]))});
			m2 = min({m2, max(abs(r[i]-l[j]), abs(r[i]-r[j]))});
		}

		opt = min(opt, max(m1, m2));
	}

	for (int i = 0; i < v.size(); i++) {
		vind[v[i].second] = i;
	}

	int beg = 1, end = opt, ans = 0;
	while (beg <= end) {
		int mid = avg(beg, end);
		bool ok = solve(mid);
		//cout<<mid<<" "<<ok<<endl;
		if (ok) {
			ans = mid;
			beg = mid+1;
		} else {
			end = mid-1;
		}
	}

	cout<<ans<<endl;

	return 0;
}

