			else
			{
				fo(j,l,R[ql]) link(b[a[i].id][1],b[a[j].id][0]);
				fo(j,ql+1,qi-1) link(b[a[i].id][1],tot+j);
				fo(j,L[qi],i-1) link(b[a[i].id][1],b[a[j].id][0]);
