			if(qi==qr)
				fo(j,i+1,r) link(b[a[i].id][1],b[a[j].id][0]);
			else
			{
				fo(j,i+1,R[qi]) link(b[a[i].id][1],b[a[j].id][0]);
				fo(j,qi+1,qr-1) link(b[a[i].id][1],tot+j);
				fo(j,L[qr],r) link(b[a[i].id][1],b[a[j].id][0]);
			}
