        int mid=(l+r)>>1;
        id[rt]=++mmp;
        build(l,mid,ls);
        build(mid+1,r,rs);
        add(id[rt],id[ls]),add(id[rt],id[rs]);
    }
    void update(int u,int L,int R,int l,int r,int rt) {
        if(L>R) return;
        if(L<=l&&r<=R) return add(u,id[rt]);
        int mid=(l+r)>>1;
        if(L<=mid) update(u,L,R,l,mid,ls);
        if(R>mid) update(u,L,R,mid+1,r,rs);
    }
}
