void scc_dfs(ll v, vector<bool>& used, vector<ll>& vs, const vector< vector<ll> >& G) {
    used[v] = true;
    each(to, G[v]) {
        if (!used[to]) scc_dfs(to, used, vs, G);
    }
    vs.pb(v);
}
void scc_rdfs(ll v, ll k, vector<bool>& used, vector<ll>& cmp, const vector< vector<ll> >& rG) {
    used[v] = true;
    cmp[v] = k;
    each(to, rG[v]) {
        if (!used[to]) scc_rdfs(to, k, used, cmp, rG);
    }
}
// cmpが返る
// 同じcmpは強連結成分
// cmp[i] < cmp[j] なら j から i に行けない
vector<ll> scc(const vector< vector<ll> >& G) {
    const ll n = G.size();
    vector<bool> used(n, false);
    vector<ll> vs;
    rep(i, n) {
        if (!used[i]) scc_dfs(i, used, vs, G);
    }
    used.assign(n, false);
    vector< vector<ll> > rG(n);
    rep(i, n) {
        each(to, G[i]) {
            rG[to].pb(i);
        }
    }
    vector<ll> res(n);
    ll k = 0;
    rrep(i, vs.size()) {
        if (!used[vs[i]]) scc_rdfs(vs[i], k++, used, res, rG);
    }
    return res;
}
vector< vector<ll> > get_scc_graph(const vector<ll>& cmp, const vector< vector<ll> >& G) {
    vector< vector<ll> > res(*max_element(all(cmp))+1);
    rep(i, G.size()) {
        each(to, G[i]) {
            if (cmp[i] != cmp[to]) {
                res[cmp[i]].pb(cmp[to]);
            }
        }
    }
    rep(i, res.size()) {
        sort(all(res[i]));
        res[i].erase(unique(all(res[i])), res[i].end());
    }
    return res;
}
// SegmentTree<int> seg(n, 0x7FFFFFFF, [](int a, int b){return min(a, b);});
class SegmentTree {
    const int n;
    vector<ll> result;
    ll dsz;
    void sub2(int node, int lb, int ub, vector<vector<ll>>& G) {
        if (ub - lb <= 1) return;
        ll lch = node * 2 + 0;
        ll rch = node * 2 + 1;
        G[node].pb(lch);
        G[node].pb(rch);
        sub2(lch, lb, (lb + ub) / 2, G);
        sub2(rch, (lb + ub) / 2, ub, G);
    }
    void sub(int l, int r, int node, int lb, int ub) {
        if (ub <= l || r <= lb) return;
        // cout << l << " " << r << " " << node << " " << lb << " " << ub << endl;
        if (l <= lb && ub <= r) {
            result.pb(node);
            return;
        }
        sub(l, r, node * 2 + 0, lb, (lb + ub) / 2);
        sub(l, r, node * 2 + 1, (lb + ub) / 2, ub);
    }
    int size(int n) {
        int res;
        for (res = 1; res < n; res <<= 1);
        return res;
    }
public:
    SegmentTree(int n) :
        n(size(n)), dsz(size(n) * 2) {}
    vector<ll> find(int l, int r) {
        result.clear();
        sub(l, r, 1, 0, n);
        return result;
    }
    void init(vector<vector<ll>>& G) {
        G.clear();
        G.resize(data_size());
        sub2(1, 0, n, G);
    }
    ll data_size() {
        return dsz;
    }
};

