	double T = 1e9;
	while (T >= 1e-5) {
		// cerr << T << endl;
		int k = rand() % n;
		int old = cur;
		ch(k);
		int delta = cur - old;
		if (delta < 0 && exp(delta / T) * RAND_MAX <= rand()) ch(k);
		T *= 1.0 - 3e-5; mx = max(mx, cur);
