void construct(int s, int e, int x) {
    if (s == e) {
        seg[s] = x;
    } else {
        int m = (s+e) / 2;
        construct(s, m, 2*x);
        construct(m+1, e, 2*x+1);
        og[x].push_back(2*x);
        og[x].push_back(2*x+1);
    }
}

void connect(int a, int s, int e, int x, int l, int r) {
    if (l <= s and e <= r) {
        g[a].push_back(x);
    } else if (l <= e and s <= r) {
        int m = (s+e) / 2;
        connect(a, s, m, 2*x, l, r);
        connect(a, m+1, e, 2*x+1, l, r);
    }
}

