segment s[MAXN];


bool comp(segment a, segment b) {
    return a.a < b.a;
}


int build(int l, int r) {
    int t = ++ tot;
    lb[t] = l; rb[t] = r;
    if (l < r)  {
        lc[t] = build(l, (l + r) / 2);
        rc[t] = build((l + r) / 2 + 1, r);
    } else {
        intr[s[l].b] = t;
    }
    return t;
}


void rmq(int t, int l, int r, int d) {
    if (l > r) {
        return;
    }
    if (l <= lb[t] && rb[t] <= r) {
        b[d].push_back(t);
        return;
    }
    if (l <= rb[lc[t]]) {
        rmq(lc[t], l, r, d);
    }
    if (r >= lb[rc[t]]) {
        rmq(rc[t], l, r, d);
    }
}


int uk, used[MAXN], low[MAXN], shed[MAXN], inshed[MAXN], top, cnt;
int ini[MAXN];



void init() {
    uk = 0;
    for (int i = 1; i <= tot * 2; i++) {
        used[i] = low[i] = shed[i] = inshed[i] = ini[i] = 0;
    }
    top = cnt = 0;
}


void dfs(int t) {
    used[t] = low[t] = ++uk; 
    shed[++top] = t; 
    inshed[t] = 1;
    for (int i = 0; i < (int)b[t].size(); i++)
        if (!used[b[t][i]]) {
            dfs(b[t][i]);
            low[t] = min(low[b[t][i]], low[t]);
        } else if (inshed[b[t][i]]) {
            low[t] = min(used[b[t][i]], low[t]);
        }

    if (low[t] == used[t]) {
        int p; 
        cnt++;
        do {
            p = shed[top--];
            inshed[p] = 0;
            ini[p] = cnt;
        }
        while (p != t);
    }
}


