                l = upper_bound(s + 1, s + n * 2 + 1, (segment){a[i] - mid, 0}, comp) - s;
            rmq(1, l, ins[i] - 1, intr[i <= n? i + n: i - n]);
            rmq(1, ins[i] + 1, r, intr[i <= n? i + n: i - n]);
