const int INF = 1e9+7;

template <typename T>
class SegTree{
	// セグメントツリーをたどる
	void prop(int l, int r, T v, int a, int b, int k=1){
		if( l <= a && b <= r ){
			// 完全に範囲内の場合
			setRelation(k, N+v);
		}else if( l < b && a < r ){
			// 中途半端に含まれる場合
			int m = (a+b) / 2;
			prop(l,r,v, a, m, k*2);
			prop(l,r,v, m, b, k*2+1);
		}
	}

public:
	int N;
	SegTree(int _N){
		// _N <= (N = 2^k) を満たすNを見つける
		N = 1;
		while( N < _N ) N<<=1;
	}
	void pRelation(){
		// 子がTrueなら、親もTrue
		rep(i,N) if(i){
			//cout << "pRelation: " << (SegOff + i*2) << " " << (SegOff + i) << endl;
			sat.add_edge(SegOff + i*2,   SegOff + i);
			sat.add_edge(SegOff + i*2+1, SegOff + i);
		}
	}
	void cRelation(int i, int v){
		int p = SegOff + N+i;
		//cout << "cRelation: " << p << " " << v << endl;
		sat.add_edge( p, v );
		sat.add_edge( v, p );
		sat.add_edge( -p, -v );
		sat.add_edge( -v, -p );
	}
	// セグメントツリーの更新(範囲に加算)
	void add(int l, int r, T v){
		//cout << "sg.add(): " << l << " " << r << " :" << v << endl;
		prop(l,r,v,0,N);
	}
};


// Atcoder ARC069 Flags (http://arc069.contest.atcoder.jp/tasks/arc069_d)
#include <map>
#include <algorithm>
typedef pair<int,int> pii;
int main(){
	int N;
	vector<pii> mp;
	SegTree<int> sg(20005);

	cin >> N;
	rep(i,N){
		int x, y;
		cin >> x >> y;
		mp.emplace_back( x, i+1 );
		mp.emplace_back( y, -(i+1) );
	}
	sort( mp.begin(), mp.end() );

	auto fn = [&](int m){
		//cout << "fn " << m << endl;
		sat.clear();
		sg.pRelation();
		rep(i, mp.size()) sg.cRelation(i, mp[i].second);
		// range relation
		rep(i, mp.size()){
			// down
			auto it = lower_bound(mp.begin(), mp.end(), pii(mp[i].first - m + 1, -INF));
			int pos = (it - mp.begin());
			sg.add( pos, i, i );
			// up
			it = lower_bound(mp.begin(), mp.end(),  pii(mp[i].first + m, -INF));
			pos = (it - mp.begin());
			sg.add( i+1, pos, i );
		}
		//cout << "setup finish" << endl;
		bool ret = sat.solve();
		//cout << "ret: " << ret << endl;
		return ret;
	};

	int l=0, r=1e9;
	while( r-l > 1 ){
		int m = (l+r) / 2;
		if( fn(m) ){
			l = m;
		}else{
			r = m;
		}
	}

	cout << l << endl;

	return 0;
}

