    }

    sort(events.begin(), events.end());

    int lo = 0;
    int hi = 1000000000;
    while (lo + 1 < hi) {
        int mid = (lo + hi) / 2;
        if (works(mid)) {
            lo = mid;
        } else {
            hi = mid;
        }
    }

    printf("%d\n", lo);

    return 0;
}

