void rdfs(int v,int k){
	cmp[v]=k;
	for(int u:G[v]){
		if(cmp[u]==-1)rdfs(u,k);
	}
	if(v>1&&cmp[v/2]==-1)rdfs(v/2,k);
}
void scc(){
