	init(2*n);
	rep(i,2*n){
		int s=lower_bound(p,p+i,P(p[i].first-d+1,-1))-p;
		int t=lower_bound(p+i,p+2*n,P(p[i].first+d,-1))-p;
		add_edge(s,i,id[p[i].second][id[p[i].second][0]==i]);
		add_edge(i+1,t,id[p[i].second][id[p[i].second][0]==i]);
	}
