const int N = 100005, M = 500005;

int n, tot, cnt, ans;
int va[N], po[N], id[N];
int dfn[N], low[N], sta[N], col[N], top, clk, colnm;
std::pair<int, int> hh[N];

int yun, to[M], pre[M], las[N];
inline void Add(int a, int b) {
	to[++yun] = b; pre[yun] = las[a]; las[a] = yun;
}

void Build(int t, int l, int r) {
	int md = (l + r) >> 1;
	if (l == r) {
		Add(t, id[l] + tot); return;
	}
	Add(t, t << 1); Add(t, t << 1 | 1);
	Build(t << 1, l, md); Build(t << 1 | 1, md + 1, r);
}

void Add_(int t, int l, int r, int L, int R, int x) {
	int md = (l + r) >> 1;
	if (L <= l && r <= R) {
		Add(x + tot, t); return;
	}
	if (L <= md) Add_(t << 1, l, md, L, R, x);
	if (md < R) Add_(t << 1 | 1, md + 1, r, L, R, x);
}

void Tarjan(int x) {
	sta[++top] = x; dfn[x] = low[x] = ++clk;
	for (int i = las[x]; i; i = pre[i]) {
		if (!dfn[to[i]]) {
			Tarjan(to[i]);
			low[x] = std::min(low[x], low[to[i]]);
		} else if (!col[to[i]]) {
			low[x] = std::min(low[x], dfn[to[i]]);
		}
	}
	if (dfn[x] == low[x]) {
		col[x] = ++colnm;
		for (; sta[top] != x; --top) col[sta[top]] = colnm;
	}
}

inline int Check(int d) {
	memset(col, 0, sizeof col);
	memset(dfn, 0, sizeof dfn);
	memset(low, 0, sizeof low);
	memset(las, 0, sizeof las);
	top = clk = colnm = yun = 0;
	Build(1, 1, n << 1);
	for (int i = 1; i <= n << 1; ++i) {
		int ip = std::lower_bound(hh + 1, hh + 1 + n * 2, std::make_pair(va[i], po[i])) - hh;
		int lp = std::upper_bound(hh + 1, hh + 1 + n * 2, std::make_pair(va[i] - d, (int)1e9)) - hh;
		int rp = std::lower_bound(hh + 1, hh + 1 + n * 2, std::make_pair(va[i] + d, 0)) - hh - 1;
		if (lp <= ip - 1) Add_(1, 1, n << 1, lp, ip - 1, i);
		if (ip + 1 <= rp) Add_(1, 1, n << 1, ip + 1, rp, i);
	}
	for (int i = 1; i <= tot + n * 2; ++i) {
		if (!dfn[i]) Tarjan(i);
	}
	for (int i = 1; i <= n; ++i) {
		if (col[i + tot] == col[i + n + tot]) return 0;
	}
	return 1;
}

int main() {
	scanf("%d", &n);
	tot = n * 8;
	for (int i = 1; i <= n; ++i) {
		scanf("%d%d", &va[i], &va[i + n]);
		hh[i * 2 - 1] = std::make_pair(va[i], i + n);
		hh[i * 2] = std::make_pair(va[i + n], i);
