int N;
class SAT2 {
public:
  int N;
  vector< vector<int> > G, R;
  vector<int> vs, used, ord;

  SAT2 (int N) : N(N) {
    G.resize(N);
    R.resize(N);
    used.resize(N);
    ord.resize(N);
  }

  void add_edge(int x, int y) {
    assert(x < N && y < N);
    G[x].pb(y);
    R[y].pb(x);
  }

  void dfs(int x) {
    if (used[x]) return;
    used[x] = true;
    for (int t : G[x]) dfs(t);
    vs.pb(x);
  }
  void rdfs(int x, int k) {
    if (used[x]) return;
    used[x] = true;
    ord[x] = k;
    for (int t : R[x]) rdfs(t, k);
  }

  int scc() {
    rep(i, N) used[i] = false;
    rep(i, N) dfs(i);
    rep(i, N) used[i] = false;
    int k = 0;
    for (int i=vs.size()-1; i>=0; i--) {
      if (!used[vs[i]]) rdfs(vs[i], k++);
    }
    return k;
  }
};


#define MAX_N (1<<16)

int seg(int x) {
  return x+2*N;
}
void add_edge(SAT2 &sat, int a, int b, int x, int k=0, int l=0, int r=MAX_N) {
  if (r <= a || b <= l) return;
  if (a <= l && r <= b) {
    sat.add_edge(x, seg(k));
    return;
  }
  add_edge(sat, a, b, x, k*2+1, l, (l+r)/2);
  add_edge(sat, a, b, x, k*2+2, (l+r)/2, r);
}

int flip(int x) {
  if (x >= N) return x-N;
  return x+N;
}

vector<P> xs;
bool f(int X) {
  SAT2 sat(2*N + 2*MAX_N-1);

  rep(i, 2*N) {
    sat.add_edge(seg(i+MAX_N-1), flip(xs[i]._2));
  }
  for (int i=MAX_N-2; i>=0; i--) {
    sat.add_edge(seg(i), seg(i*2+1));
    sat.add_edge(seg(i), seg(i*2+2));
  }
  rep(i, 2*N) {
    int x = xs[i]._1, xi = xs[i]._2;
    int l = lower_bound(all(xs), P(x-(X-1), -1)) - xs.begin(),
        r = upper_bound(all(xs), P(x+(X-1), INF)) - xs.begin() - 1;
    // [l, x), [x+1, r+1)
    add_edge(sat, l, i, xi);
    add_edge(sat, i+1, r+1, xi);
  }
  sat.scc();
  rep(i, N) {
    if (sat.ord[i] == sat.ord[i+N]) return false;
  }
  return true;
}

signed main() {
  ios::sync_with_stdio(false); cin.tie(0);
  cin >> N;

  rep(i, N) {
    int x, y;
    cin >> x >> y;
    xs.pb(P(x, i));
    xs.pb(P(y, i+N));
  }
  sort(all(xs));

  int lo = -1, hi = 1000000001;
  while (hi - lo > 1) {
    int mid = (lo + hi) / 2;
    if (f(mid)) lo = mid;
    else hi = mid;
  }
  cout << lo << "\n";
  return 0;
}

