		int V = 0;
		for(int i = 0; i < K; i++) {
			cnt_v[i] = (2*N+(1<<i)-1)/(1<<i);
			V += cnt_v[i];
			sumcnt_v[i+1] = sumcnt_v[i] + cnt_v[i];
		}
		vector< vector<int> > G(2*V);
		for(int i = 1; i < K; i++) for(int x = 0; x < N; x += (1<<i)) {
			int j = x/(1<<i);
			// if (i, j) false: (i-1, s1), (i-1, s2) false
			// if (i-1, s1) or (i-1, s2) has true: (i, j) has true
			G[2*(sumcnt_v[i]+j)].push_back(2*(sumcnt_v[i-1]+2*j));
			G[2*(sumcnt_v[i-1]+2*j)+1].push_back(2*(sumcnt_v[i]+j)+1);
			if(2*j+1 < cnt_v[i-1]) {
				G[2*(sumcnt_v[i]+j)].push_back(2*(sumcnt_v[i-1]+2*j+1));
