			// if (0, [L[i], i)) has true: (0, i) false
			l = L[i], r = i;
			for(int k = 0; k < K; k++) {
				if(l == r) break;
				if((l>>k)&1 && l+(1<<k) <= r) {
					G[2*i+1].push_back(2*(sumcnt_v[k]+l/(1<<k)));
					G[2*(sumcnt_v[k]+l/(1<<k))+1].push_back(2*i);
					l += 1<<k;
				}
				if((r>>k)&1 && l+(1<<k) <= r) {
					r -= 1<<k;
					G[2*i+1].push_back(2*(sumcnt_v[k]+r/(1<<k)));
					G[2*(sumcnt_v[k]+r/(1<<k))+1].push_back(2*i);
				}
			}
			// if (0, i) is true: (0, [i+1, R[i])) is false
			l = i+1, r = R[i];
			for(int k = 0; k < K; k++) {
				if(l == r) break;
				if((l>>k)&1 && l+(1<<k) <= r) {
					G[2*i+1].push_back(2*(sumcnt_v[k]+l/(1<<k)));
					G[2*(sumcnt_v[k]+l/(1<<k))+1].push_back(2*i);
					l += 1<<k;
				}
				if((r>>k)&1 && l+(1<<k) <= r) {
					r -= 1<<k;
					G[2*i+1].push_back(2*(sumcnt_v[k]+r/(1<<k)));
					G[2*(sumcnt_v[k]+r/(1<<k))+1].push_back(2*i);
				}
			}
		}
		for(int i = 0; i < 2*N; i++) {
			int j = Xpos[pos[i].ss][0]+Xpos[pos[i].ss][1]-i;
			// (0, i) xor (0, j) is true
			G[2*i].push_back(2*j+1);
			G[2*i+1].push_back(2*j);
		}
		// SAT
		vector<int> st, min_idx(2*V), idx(2*V, -1);
		vector<bool> in_st(2*V, false);
		vector< vector<int> > comp;
		int nxt_idx = 0;
