    }
    else {
        int mid = (lb + rb) >> 1;
        build(p << 1, lb, mid);
        build(p << 1 | 1, mid, rb);
        adde(id1[p], id1[p << 1]);
        adde(id1[p], id1[p << 1 | 1]);
        adde(id2[p << 1], id2[p]);
        adde(id2[p << 1 | 1], id2[p]);
    }
}

int opp(int x) { return x & 1 ? x + 1 : x - 1; }

void adde(int l, int r, int x, int p, int lb, int rb) {
    if (l >= r) return;
    if (l <= lb && rb <= r) {
        adde(x, id1[p]);
        adde(id2[p], opp(x));
    }
    else {
        int mid = (lb + rb) >> 1;
        if (l < mid) adde(l, r, x, p << 1, lb, mid);
        if (r > mid) adde(l, r, x, p << 1 | 1, mid, rb);
    }
}

