void add(int v,int l,int r,int L,int R,int u)   {
    if (l > R)  return;
    if (L > r)  return;

    if (L <= l && r <= R)   {
        g[v].pb(u);
        return;
    }
    int m = (l + r) / 2;

    add(tr[v].X,l,m,L,R,u); ++m;
    add(tr[v].Y,m,r,L,R,u);
}
void rem(int v,int l,int r,int L,int R) {
    if (l > R)  return;
    if (L > r)  return;

    if (L <= l && r <= R)   {
        g[v].pop_back();
        return;
    }
    int m = (l + r) / 2;

    rem(tr[v].X,l,m,L,R);   ++m;
    rem(tr[v].Y,m,r,L,R);
}
