const int NMAX = 10005;

int N;
vector <int> graph[2 * NMAX];
vector <int> graph_inv[2 * NMAX];

#define graph (graph + NMAX)
#define graph_inv (graph_inv + NMAX)

void add_edge(int a, int b) {
    graph[-a].push_back(b);
    graph[-b].push_back(a);

    graph_inv[a].push_back(-b);
    graph_inv[b].push_back(-a);
}

void clr() {
    for (int i = 1; i <= N; ++ i) {
        graph[i].clear();
        graph[-i].clear();
        graph_inv[i].clear();
        graph_inv[-i].clear();
    }
}

int h[2 * NMAX];

bool vis[3 * NMAX];
#define vis (vis + NMAX)

int pos;

void dfs_inv(int node) {
    vis[node] = true;
    for (auto it: graph_inv[node])
        if (!vis[it])
            dfs_inv(it);
    h[++ pos] = node;
}

int which_comp[2 * NMAX];
#define which_comp (which_comp + NMAX)

void dfs(int node, int comp) {
    vis[node] = true;
    which_comp[node] = comp;
    for (auto it: graph[node])
        if (!vis[it])
            dfs(it, comp);
}

bool works() {
    for (int i = -N; i <= N; ++ i)
        vis[i] = 0;
    pos = 0;
    for (int i = -N; i <= N; ++ i)
        if (i && !vis[i])
            dfs_inv(i);
    for (int i = -N; i <= N; ++ i)
        vis[i] = 0;

    int comp = 0;
    for (int i = pos; i; -- i)
        if (!vis[h[i]])
            dfs(h[i], ++ comp);

    for (int i = 1; i <= N; ++ i)
        if (which_comp[i] == which_comp[-i])
            return false;
    return true;
}

int x[NMAX];
int y[NMAX];

void build(int bound) {
    clr();
    for (int i = 1; i <= N; ++ i)
        for (int j = i + 1; j <= N; ++ j) {
            if (abs(x[i] - x[j]) < bound)
                add_edge(-i, -j);
            if (abs(x[i] - y[j]) < bound)
                add_edge(-i, j);
            if (abs(y[i] - x[j]) < bound)
                add_edge(i, -j);
            if (abs(y[i] - y[j]) < bound)
                add_edge(i, j);
        }
}

