    while (st <= dr) {
        int mid = (st + dr) >> 1;
        build(mid);

        if (works()) {
            ans = mid;
            st = mid + 1;
        }
        else
            dr = mid - 1;
    }

    cout << ans << '\n';
    return 0;
}

