inline bool judge(int dis){
	for(int i=0;i<n2;++i)
		g[i].clear();
	for(int i=0;i<n2;++i){
		int tmp=upper_bound(posi,posi+n2,posi[i]-dis)-posi;
		if(tmp<i)
			st::update(st::rt,0,n2-1,tmp,i-1,p[i].id);
	}
	for(int i=0;i<n2;++i){
		int tmp=lower_bound(posi,posi+n2,posi[i]+dis)-posi-1;
		if(tmp>i)
			st::update(st::rt,0,n2-1,i+1,tmp,p[i].id);
	}
	memset(pre,0,sizeof(pre));dfn=0;
	memset(scc,0,sizeof(scc));scccnt=0;
	for(int i=0;i<=st::cnt;++i)
		if(!pre[i])
