bool brute_check(int d) {
  memset(adj, 0, sizeof adj);
  REP(i, N) adj[i][i] = 1;

  REP(i, N) REP(j, N) {
    if (i == j) continue;
    REP(ii, 2) REP(jj, 2) {
      int I = 2 * i + ii;
      int J = 2 * j + jj;
      if (abs(pos[I] - pos[J]) < d) 
	adj[I][J^1] = 1;
    }
  }

  REP(k, 2 * N) REP(i, 2 * N) REP(j, 2 * N)
    adj[i][j] |= adj[i][k] && adj[k][j];

  REP(i, N)
    if (adj[2 * i][2 * i + 1] && adj[2 * i + 1][2 * i])
      return false;

  return true;
}

