bool dfs(int p){
	while(p<n && s[p]>=0) p++;
	if(p>=n) return true;
	int s2[N];
	memcpy(s2, s, sizeof(s));
	s[p] = 0;
	int cnt = bfs(p);
	if(cnt==0) return dfs(p+1);
	if(cnt>0 && dfs(p+1)) return true;
	memcpy(s, s2, sizeof(s));
	s[p] = 1;
	if(bfs(p)>=0) return dfs(p+1);
	memcpy(s, s2, sizeof(s));
	s[p] = -1;
	return false;
}

