void inse(int x,int y){e[++et].x=y;e[et].nxt=h[x];h[x]=et;}

void add(int now,int l,int r,int x,int y,int st){
	if (x<=l&&r<=y){inse(st,tree[now].id);return;}
	int mid=(l+r)/2;
	if (x<=mid)add(tree[now].l,l,mid,x,y,st);
	if (y>mid)add(tree[now].r,mid+1,r,x,y,st);
}

int min(int x,int y){return x<=y?x:y;}

int S[N*6],T;
int H[N*6],lst[N*6];

void tarjan(int st){
	S[T=1]=st;
	while(T){
		int x=S[T];
		if (!dfn[x]){
			dfn[x]=f[x]=++u;
			pd[sta[++top]=x]=1;
			H[x]=h[x];
			lst[x]=-1;
			continue;
		}
		if (H[x]){
			if (lst[x]==0)f[x]=min(f[x],f[e[H[x]].x]);
			if (lst[x]>-1)H[x]=e[H[x]].nxt;
			if (!dfn[e[H[x]].x]){
				S[++T]=e[H[x]].x;
				lst[x]=0;
			}
			else{
				if (pd[e[H[x]].x])f[x]=min(f[x],dfn[e[H[x]].x]);
				lst[x]=1;
			}
		}
		else{
			if (f[x]==dfn[x]){
				t++;
				for(;sta[top+1]!=x;top--){
					pd[sta[top]]=0;
					be[sta[top]]=t;
				}
			}
			T--;
		}
	}
}

