	for (int i = 1; i <= n; i++) {
		cin>>l[i]>>r[i];
		v.pb(mp(l[i], i));
		v.pb(mp(r[i], i+n));
	}

	sort(v.begin(), v.end());

	for (int i = 0; i < v.size(); i++) {
		vind[v[i].second] = i;
	}

	int beg = 1, end = 1e9, ans = 0;
	while (beg <= end) {
		int mid = avg(beg, end);
		bool ok = solve(mid);
		//cout<<mid<<" "<<ok<<endl;
		if (ok) {
			ans = mid;
			beg = mid+1;
		} else {
			end = mid-1;
		}
	}

	cout<<ans<<endl;

	return 0;
}

