inline void add_edge(int from,int to){
	G[from].push_back(to);
	rG[to].push_back(from);
}

void dfs(int v){
	used[v]=true;
	REP(i,(int)G[v].size()){
		if (!used[G[v][i]]){
			dfs(G[v][i]);
		}
	}
	vs.push_back(v);
}

void rdfs(int v,int k){
	used[v]=true;
	cmp[v]=k;
	REP(i,(int)rG[v].size()){
		if (!used[rG[v][i]]){
			rdfs(rG[v][i],k);
		}
	}
}

inline int scc(){
	memset(used,0,sizeof(used));
	vs.clear();
	REP(i,st_size*3-1){
		if (!used[i]){
			dfs(i);
		}
	}
	memset(used,0,sizeof(used));
	int k=0;
	reverse(vs.begin(),vs.end());
	REP(i,(int)vs.size()){
		if (!used[vs[i]]){
			rdfs(vs[i],k++);
		}
	}
	return k;
}

void dfs(int lft,int rgh,int from,int a,int b,int k){
	if (b<=lft || rgh<=a){
		return;
	}
	if (lft<=a && b<=rgh){
		add_edge(from,k);
	}else{
		int m=(a+b)>>1;
		dfs(lft,rgh,from,a,m,k*2+1);
		dfs(lft,rgh,from,m,b,k*2+2);
	}
}

inline bool C(ll d){
	REP(v,st_size*3-1){
		G[v].clear();
		rG[v].clear();
	}
//	fprintf(stderr,"done\n");
	REP(v,st_size-1){
		add_edge(v,2*v+1);
		add_edge(v,2*v+2);
	}
	vector<int> vec(N,-1);
	REP(v,2*N){
		if (vec[Z[v].second]!=-1){
			add_edge(vec[Z[v].second]+st_size-1,v+st_size*2-1);
			add_edge(v+st_size-1,vec[Z[v].second]+st_size*2-1);
		}else{
			vec[Z[v].second]=v;
		}
	}
	REP(v,N*2){
		if (d>0){
			int lb,ub;
			lb=lower_bound(Z,Z+N*2,P(Z[v].first-d+1,-1))-Z;
			ub=lower_bound(Z,Z+N*2,P(Z[v].first+d,-1))-Z;
			dfs(lb,v,v+st_size*2-1,0,st_size,0);
			dfs(v+1,ub,v+st_size*2-1,0,st_size,0);
		}
	}
	scc();
	/*
	REP(v,st_size*3-1){
		if (d==10){
			fprintf(stderr,"vertex %d: ",v);
			REP(i,(int)G[v].size()){
				fprintf(stderr,"%d ",G[v][i]);
			}
			fprintf(stderr,"\n");
		}
	}
	*/
	REP(i,N*2){
		if (cmp[i+st_size-1]==cmp[i+st_size*2-1]){
			return false;
		}
	}
	return true;
}

