    Build(mid + 1, r, rc, op);
    addEdge(id[pos][op], id[lc][op]);
    addEdge(id[pos][op], id[rc][op]);
}

void Link(int l, int r, int L, int R, int pos, int op, int s) {
    if (L <= l && r <= R) { addEdge(s, id[pos][op]); return ;}
    int mid = (l + r) >> 1;
    if (L <= mid) Link(l, mid, L, R, lc, op, s);
    if (mid < R) Link(mid + 1, r, L, R, rc, op, s);
}

