    src[m] = u; dest[m] = v; next[m] = head[u]; head[u] = m++;
}
// 1 ~ (2 * psz - 1): Segment tree nodes (false; node u represents not(lch[u]) and not(rch[u]))
// (2 * psz ~ 3 * psz - 1): Normal nodes (true)
inline std::vector<int> get_sgt_vertices(int L, int R)
{
    std::vector<int> ret;
    if (L >= R) return ret;
    L += psz, R += psz;
    for (; L < R; L >>= 1, R >>= 1) {
        if (L & 1) ret.push_back(L++);
        if (R & 1) ret.push_back(--R);
    }
    return ret;
}
int dfn[MAXN * 3], low[MAXN * 3];
std::stack<int> stk;
bool onstack[MAXN * 3];
int epoch, scc_ct;
int scc_id[MAXN * 3];
void dfs_scc(int u)
{
    dfn[u] = low[u] = epoch++;
    stk.push(u); onstack[u] = true;

    for (int w = head[u]; w != -1; w = next[w]) {
        if (dfn[dest[w]] == -1) {
            dfs_scc(dest[w]);
            low[u] = std::min(low[u], low[dest[w]]);
        } else if (onstack[dest[w]]) {
            low[u] = std::min(low[u], dfn[dest[w]]);
        }
    }

    if (low[u] == dfn[u]) {
        int v;
        do {
            v = stk.top(); stk.pop();
            onstack[v] = false;
            scc_id[v] = scc_ct;
        } while (v != u);
        ++scc_ct;
    }
}
bool check(int d)
{
    m = 0;
    for (int i = 1; i < psz * 3; ++i) head[i] = -1;
    for (int i = 1; i < psz; ++i) {
        add_edge(i, i * 2);
        add_edge(i, i * 2 + 1);
    }
    for (int i = 0; i < n; ++i) {
        int u = psz * 2 + pid(x[i]), not_u = u - psz,
            v = psz * 2 + pid(y[i]), not_v = v - psz;
        add_edge(u, not_v); add_edge(not_v, u);
        add_edge(v, not_u); add_edge(not_u, v);
    }
    for (int i = 0; i < psz; ++i) {
        int lb = pid_lb(p[i] - d + 1), ub = pid_ub(p[i] + d - 1);
        std::vector<int> verts = get_sgt_vertices(lb, i);
        for (int u : verts) add_edge(psz * 2 + i, u);
        verts = get_sgt_vertices(i + 1, ub);
        for (int u : verts) add_edge(psz * 2 + i, u);
    }

    std::fill(dfn, dfn + psz * 3, -1);
    epoch = scc_ct = 0;
    for (int i = 1; i < psz * 3; ++i) if (dfn[i] == -1) dfs_scc(i);

    for (int i = 0; i < psz; ++i) {
        if (scc_id[psz * 2 + i] == scc_id[psz + i]) return false;
    }
    return true;
}

