		for(int j=0;j<len;j++){
			a1[j]=++num;
			a2[j]=++num;
			addedge(a1[j],V[now][j]);
			addedge(a2[j],V[now][j]);
			if(j){
				addedge(a1[j-1],a1[j]);
				addedge(a2[j],a2[j-1]);
			}
		}
		for(int j=0;j<len;j++){
			if(j<len-1) addedge(V[now][j]>n ? V[now][j]-n : V[now][j]+n,a1[j+1]);
			if(j) addedge(V[now][j]>n ? V[now][j]-n : V[now][j]+n,a2[j-1]);
		}
