		Add(root,f(i,1),max(0,a[i][1]-avr+1),a[i][1]-1,0,0,maxx);
		Add(root,f(i,1),a[i][1]+1,min(a[i][1]+avr-1,maxx),0,0,maxx);
	}
	for(int i=1;i<=2*n;i++){
		if(!dfn[i]) dfs(i);
	}
	for(int i=1;i<=n;i++){
		if(col[f(i,0)]==col[f(i,1)]) return 0;
	}
	return 1;
}
