const int INF = 1e9+7;

template <typename T, typename NODE=node<T,INF> >
class SegTree{
	// 遅延分の適応と伝播(現在のノードの値を確定させてLazyを伝搬させる)
	void propLazy(int a, int b, int k, T v=0){
		setRelation(k, N+v);
		//T lazy = data[k].add(a, b, v);
		//if( k < N ){
		//	data[k*2+0].addLazy(lazy);
		//	data[k*2+1].addLazy(lazy);
		//}
	}
	// セグメントツリーをたどる
	T prop(int l, int r, T v, int a, int b, int k=1){
		// 今いるノードの値を確定させる
		//propLazy(a, b, k);
		// たどる
		NODE nd;	// 結果保存用(範囲外の場合は初期値が返る)
		if( l <= a && b <= r ){
			// 完全に範囲内の場合
			propLazy(a, b, k, v);
			return data[k].v;
		}else if( l < b && a < r ){
			// 中途半端に含まれる場合
			int m = (a+b) / 2;
			T vl = prop(l,r,v, a, m, k*2);
			T vr = prop(l,r,v, m, b, k*2+1);
			data[k].merge( data[k*2].v, data[k*2+1].v );
			nd.merge( vl, vr );
		}
		return nd.v;
	}

public:
	vector<NODE> data;
	int N;
	SegTree(int _N){
		// _N <= (N = 2^k) を満たすNを見つける
		N = 1;
		while( N < _N ) N<<=1;
		data.resize(N*2);
	}
	void pRelation(){
		// 子がTrueなら、親もTrue
		rep(i,N) if(i){
			//cout << "pRelation: " << (SegOff + i*2) << " " << (SegOff + i) << endl;
			sat.add_edge(SegOff + i*2,   SegOff + i);
			sat.add_edge(SegOff + i*2+1, SegOff + i);
			//sat.add_edge(SegOff + i, SegOff + i*2   );
			//sat.add_edge(SegOff + i, SegOff + i*2+1 );
		}
	}
	void cRelation(int i, int v){
		int p = SegOff + N+i;
		//cout << "cRelation: " << p << " " << v << endl;
		//sat.add_or( p, v );
		//sat.add_or( -p, -v );
		sat.add_edge( p, v );
		sat.add_edge( v, p );
		sat.add_edge( -p, -v );
		sat.add_edge( -v, -p );
	}
	// セグメントツリーの更新(指定した場所の値をvに変更)
	void update(int l, T v){
		prop(l, l+1, v-get(l), 0, N);
	}
	// セグメントツリーの更新(範囲に加算)
	T add(int l, int r, T v){
		//cout << "sg.add(): " << l << " " << r << " :" << v << endl;
		return prop(l,r,v,0,N);
	}
	// 値を取得 [l,r)
	T get(int l, int r){
		return prop(l,r,0,0,N);
	}
	// 値を取得 [l,l+1)
	T get(int l){
		return prop(l,l+1,0,0,N);
	}
};


