	if(l==r){
		g[idx+2*n].push_back(nor[xs[l].second]);
		g[idx+2*n+4*n].push_back(inv[xs[l].second]);
		g[idx+2*n+8*n].push_back(nor[ys[l].second]);
		g[idx+2*n+4*n+8*n].push_back(inv[ys[l].second]);
	}else{
		int mid=(l+r)>>1;
		build(l,mid,idx<<1);
		build(mid+1,r,idx<<1|1);
		g[idx+2*n].push_back((idx<<1)+2*n);
		g[idx+2*n].push_back((idx<<1|1)+2*n);
		g[idx+4*n+2*n].push_back((idx<<1)+4*n+2*n);
		g[idx+4*n+2*n].push_back((idx<<1|1)+4*n+2*n);
		g[idx+8*n+2*n].push_back((idx<<1)+8*n+2*n);
		g[idx+8*n+2*n].push_back((idx<<1|1)+8*n+2*n);
		g[idx+4*n+8*n+2*n].push_back((idx<<1)+4*n+8*n+2*n);
		g[idx+4*n+8*n+2*n].push_back((idx<<1|1)+4*n+8*n+2*n);
	}
}
void add_edge(int l,int r,int ql,int qr,int tar,bool is_inv,bool is_y,int idx){
	if(ql>qr) return;
	if(l==ql && r==qr){
		int id=idx+2*n;
		if(is_inv) id+=4*n;
		if(is_y) id+=8*n;
		g[tar].push_back(id);
	}else{
		int mid=(l+r)>>1;
		if(qr<=mid) add_edge(l,mid,ql,qr,tar,is_inv,is_y,idx<<1);
		else if(ql>mid) add_edge(mid+1,r,ql,qr,tar,is_inv,is_y,idx<<1|1);
		else{
			add_edge(l,mid,ql,mid,tar,is_inv,is_y,idx<<1);
			add_edge(mid+1,r,mid+1,qr,tar,is_inv,is_y,idx<<1|1);
		}
	}
}
inline int search(vector<pii>& vc,int tar){
	if(vc[vc.size()-1].first<=tar) return vc.size();
	int l=0,r=vc.size()-1;
	while(l!=r){
		int mid=(l+r)>>1;
		if(vc[mid].first>tar) r=mid;
		else l=mid+1;
	}
	return r;
}
inline int search2(vector<pii>& vc,int tar){
	if(vc[0].first>=tar) return -1;
	int l=0,r=vc.size();
	while(r-l>1){
		int mid=(l+r)>>1;
		if(vc[mid].first<tar) l=mid;
		else r=mid;
	}
	return l;
}
