bool mrk[N];
set <int> seg[N * 4];

void put(int p, int u, int tp, int v = 1, int s = 0, int e = N) {
	if (tp == 1)
		seg[v].insert(u);
	else
		seg[v].erase(u);
	if (e - s == 1)
		return;
	if (p < mid)
		put (p, u, tp, lc, s, mid);
	else
		put (p, u, tp, rc, mid, e);
}

int get(int l, int r, int v = 1, int s = 0, int e = N) {
	if (r <= s || e <= l)
		return 0;
	if (l <= s && e <= r) {
		if (seg[v].size())
			return *seg[v].begin();
		return 0;
	}
	int t = get(l, r, lc, s, mid);
	if (t)
		return t;
 	return get(l, r, rc, mid, e);
}
vector <int> st;

void dfs(int v) {
	mrk[v] = 1;
	bool ok = 1;
	while (ok) {
		ok = 0;
		int u = get(close(x[v]).first, plc[v]);
		if (u) {
			put(plc[u ^ 1], u, -1);
			dfs(u);
			ok = 1;
			continue;
		}
		u = get(plc[v] + 1, close(x[v]).second);
		if (u) {
			put(plc[u ^ 1], u, -1);
			dfs(u);
			ok = 1;
		}
	}
	st.push_back(v);
}
int com[N];
int cnt;

void rev(int v) {
	com[v] = cnt;
	bool ok = 1;
	while (ok) {
		ok = 0;
		int u = get(close(x[v ^ 1]).first, plc[v ^ 1]);
		if (u) {
			put(plc[u], u, -1);
			rev(u);
			ok = 1;
			continue;
		}
		u = get(plc[v ^ 1] + 1, close(x[v ^ 1]).second);
		if (u) {
			put (plc[u], u, -1);
			rev(u);
			ok = 1;
			continue;
		}
	}
}

