	for (int i = 2; i <= 2 * n + 1; i++) 
		if (!mrk[i]) {
			put(plc[i ^ 1], i, -1);
			dfs(i);
		}
	memset(com, 0, sizeof com);
	for (int i = 1; i < 4 * N; i++) {
		if (seg[i].size()) {
			cout << " sz " << endl;
			exit(0);
		}
	}
	for (int i = 2; i <= 2 * n + 1; i++)
		put(plc[i], i, 1);
	while (st.size()) {	
		int v = st.back();
		st.pop_back();
		if (com[v])
			continue;
		cnt++;
		put(plc[v], v, -1);
		rev(v);
	}
	for (int i = 2; i <= 2 * n + 1; i++) 
		if (com[i] == com[i ^ 1]) {
			return 0;
		}
	return 1;
}

