namespace BIT_chs
{
    int num[N];
    void init(){ FILL(num, 0); }
    inline int lowbit(int i){ return i & (-i); }
    inline void modify(int i, int x)
    {
        for(; i <= n; i += lowbit(i)) num[i] += x;
        return;
    }
    inline int query(int i)
    {
        int ret = 0;
        for(; i; i ^= lowbit(i)) ret += num[i];
        return ret;
    }
}

void MEI()
{
    int tot = 0;
    map<int, int> M; M.clear();

    scf(n); n <<= 1;
    rep(i, n)
    {
        scf(pos[i]);
        if(M.find(pos[i]) == M.end()) M[pos[i]] = 0;
        ++M[pos[i]];
    }

    for(auto it = M.begin(); it != M.end(); ++it) tot += it -> Y, it -> Y = tot;

    rep(i, n)
    {
        id[M[pos[i]]] = i;
        rnk[i] = M[pos[i]];
        M[pos[i]]--;
    }
    return;
}

vi pool_chs, pool_vis;
int MID;

inline int get_l(int i)
{
    int LB = pos[id[i]] - MID;
    int lb = 1, rb = n;
    while(lb <= rb)
    {
        int mid = lb + rb >> 1;
        int x = pos[id[mid]];
        if(x <= LB) lb = mid + 1;
        else rb = mid - 1;
    }
    return lb;
}

inline int get_r(int i)
{
    int RB = pos[id[i]] + MID;
    int lb = 1, rb = n;
    while(lb <= rb)
    {
        int mid = lb + rb >> 1;
        int x = pos[id[mid]];
        if(x >= RB) rb = mid - 1;
        else lb = mid + 1;
    }
    return rb;
}

inline int find_l(int i)
{
    auto it = svis.lower_bound(i);
    it--;
    return *it;
}

inline int find_r(int i)
{
    auto it = svis.lower_bound(i);
    if(*it == i) ++it;
    return *it;
}

inline bool chk(int i)
{
    if(chs[i]) return 1;

    int j = rnk[id[i] ^ 1];
    chs[i] = 1;
    BIT_chs::modify(i, 1);
    pool_chs.pb(i);

    int li = get_l(i), ri = get_r(i);
    if(BIT_chs::query(ri) - BIT_chs::query(li - 1) > 1) return 0;

    vis[i] = vis[j] = 1;
    svis.erase(i); svis.erase(j);
    pool_vis.pb(i); pool_vis.pb(j);

    j = find_l(i);
    while(j >= li)
    {
        if(!chk(rnk[id[j] ^ 1])) return 0;
        j = find_l(j);
    }

    j = find_r(i);
    while(j <= ri)
    {
        if(!chk(rnk[id[j] ^ 1])) return 0;
        j = find_r(j);
    }

    return 1;
}

bool check(int mid)
{
    MID = mid;
    FILL(vis, 0); FILL(chs, 0);
    BIT_chs::init();
    forn(i, 0, n + 1) svis.insert(i);
    for(;;)
    {
        auto it = svis.begin(); ++it;
        int i = *it;
        if(i > n) return 1;

        pool_chs.clear();
        pool_vis.clear();

        if(!chk(i))
        {
            for(int i: pool_chs) BIT_chs::modify(i, -1), chs[i] = 0;
            for(int i: pool_vis) svis.insert(i), vis[i] = 0;

            pool_chs.clear();
            pool_vis.clear();
            i = rnk[id[i] ^ 1];
            if(!chk(i)) return 0;
        }
    }
}

void ZI()
{
    int lb = 0, rb = (pos[id[n]] - pos[id[1]]) / (n / 2 - 1);
    while(lb <= rb)
    {
        int mid = lb + rb >> 1;
        if(check(mid)) lb = mid + 1;
        else rb = mid - 1;
    }
    printf("%d\n", rb);
    return;
}

