int cnt_scc,scc[maxn*4];
void tarjan(int x)
{
    dfn[x]=low[x]=++D;
    vis[x]=1;s.push(x);
    for(int i=head[x];i;i=nxt[i])
    {
        if(!dfn[to[i]])
        {
            tarjan(to[i]);
            low[x]=min(low[x],low[to[i]]);
        }
        else if(vis[to[i]])
        {
            low[x]=min(low[x],dfn[to[i]]);
        }
    }
    if(dfn[x]==low[x])
    {
        cnt_scc++;
        int tmp=0;
        while(tmp!=x)
        {
            tmp=s.top();s.pop();
            scc[tmp]=cnt_scc;
            vis[tmp]=0;
        }
    }
}
bool check(int x)
{
    tot=0;cnt=2*n;D=0;cnt_scc=0;
