inline void add_edge(int u, int v)
{
	to[tot] = v; 
	pre[tot] = lst[u]; 
	lst[u] = tot++;
}
void build(int &u, int l, int r)
{
	if (l == r)
	{
		u = app[l].idx < n ? app[l].idx + n : app[l].idx - n; 
		pos[app[l].idx] = l; 
		return; 
	}
	u = t_cnt++; 
	int m = l + r >> 1; 
	build(lson[u], l, m); 
	build(rson[u], m + 1, r); 
	add_edge(u, lson[u]); 
	add_edge(u, rson[u]); 
}
void modify(int u, int l, int r, int v, int L, int R)
{
	if (L > R)
		return; 
	if (L <= l && r <= R)
	{
		add_edge(v, u); 
		return; 
	}
	int m = l + r >> 1; 
	if (L <= m)
		modify(lson[u], l, m, v, L, R); 
	if (m < R)
		modify(rson[u], m + 1, r, v, L, R); 
}
void tarjan(int u)
{
	dfn[u] = low[u] = clk++; 
	st[tp++] = u; 
	in_st[u] = true; 
	for (int i = lst[u]; ~i; i = pre[i])
	{
		if (-1 == dfn[to[i]])
		{
			tarjan(to[i]); 
			low[u] = std::min(low[u], low[to[i]]); 
		}
		else if (in_st[to[i]])
			low[u] = std::min(low[u], dfn[to[i]]); 
	}
	if (low[u] == dfn[u])
	{
		comp_cnt++; 
		do
		{
			in_st[st[--tp]] = false; 
			comp[st[tp]] = comp_cnt; 
		}
		while (st[tp] != u); 
	}
}
inline bool chk(int d)
{
	for (int i = 0; i < n << 1; i++)
		lst[i] = -1;
	for (int i = 0; i < n; i++)
	{
		int l = std::lower_bound(app, app + cnt, (data){x[i] - d + 1, -1}) - app; 
		int r = std::upper_bound(app, app + cnt, (data){x[i] + d - 1, 1e9}) - app - 1; 
		if (l <= r)
		{
			modify(rt, 0, cnt - 1, i, l, pos[i] - 1); 
			modify(rt, 0, cnt - 1, i, pos[i] + 1, r); 
		}
		l = std::lower_bound(app, app + cnt, (data){y[i] - d + 1, -1}) - app; 
		r = std::upper_bound(app, app + cnt, (data){y[i] + d - 1, 1e9}) - app - 1; 
		if (l <= r)
		{
			modify(rt, 0, cnt - 1, i + n, l, pos[i + n] - 1); 
			modify(rt, 0, cnt - 1, i + n, pos[i + n] + 1, r); 
		}
	}
	memset(dfn, -1, sizeof(dfn)); 
	memset(in_st, 0, sizeof(in_st)); 
	tp = clk = comp_cnt = 0; 
	for (int i = 0; i < t_cnt; i++)
	{
		if (-1 == dfn[i])
			tarjan(i); 
	}
	for (int i = 0; i < n; i++)
	{
		if (comp[i] == comp[i + n])
			return false; 
	}
	return true;
}
