	std::sort(app, app + cnt); 
	t_cnt = cnt; 
	build(rt, 0, cnt - 1); 
	int l = 0, r = 1e9, ans = 0, orig = tot; 
	while (l <= r)
	{
		int m = l + r >> 1; 
		if (chk(m))
		{
			ans = m; 
			l = m + 1; 
		}
		else
			r = m - 1; 
		tot = orig; 
	}
	printf("%d\n", ans);
	return 0; 
}

