      if (d >= m) {
        f = true;
      } else {
        add(i<<1|k, (j<<1|(l^1)));
        add(j<<1|l, (i<<1|(k^1)));
      }
    }
    if (!f) return false;
  }
  directed(n<<1);
  return !ed;
}

