bool good(int d) {
  twosat::n = 2 * N;
  REP(i, 2*N) twosat::g[i].clear();
  REP(i,N) REP(j,i) REP(a,2) REP(b,2) {
    if (abs(X[i][a] - X[j][b]) < d) {
      twosat::add_constr(i, !a, j, !b);
    }
  }
  return twosat::solve_2sat();
}

