bool used[16*N];

void visit(int v, vector<vector<int>> &g, vector<int> &ord, vector<int> &num, int k){
	if(num[v]>=0) return;
	num[v] = k;
	rep(i, g[v].size()){
		visit(g[v][i], g, ord, num, k);
	}
	ord.pb(v);
}

bool twoSAT(int m, vector<P> &cs){
	int n = m*2;
	vector<vector<int>> g(n), h(n);
	rep(i, cs.size()){
		int u = cs[i].fst, v = cs[i].snd;
		g[NOT(u)].pb(v);
		g[NOT(v)].pb(u);
		h[v].pb(NOT(u));
		h[u].pb(NOT(v));
	}
	vector<int> num(n, -1), ord, dro;
	rep(i, n) visit(i, g, ord, num, i);
	reverse(all(ord));
	fill(all(num), -1);
	rep(i, n) visit(ord[i], h, dro, num, i);
	rep(i, n) if(num[i]==num[NOT(i)]) return false;
	return true;
}

int vark(int k){
	return k>=n2-1?v[k-n2+1].snd:VAR(k);
}

void query2(int k, vector<P> &cs){
	if(k>=n2-1||used[k]) return;
	used[k] = true;
	query2(k*2+1, cs);
	query2(k*2+2, cs);
	cs.pb(P(NOT(vark(k*2+1)), vark(k)));
	cs.pb(P(NOT(vark(k*2+2)), vark(k)));
	cs.pb(P(NOT(vark(k*2+1)), NOT(vark(k*2+2))));
}

vector<int> query(int a, int b, int k, int l, int r, vector<P> &cs){
	if(r<=a||b<=l) return vector<int>();
	if(a<=l&&r<=b){
		query2(k, cs);
		return vector<int>(1, vark(k));
	}
	vector<int> res, res2;
	res = query(a, b, k*2+1, l, (l+r)/2, cs);
	res2 = query(a, b, k*2+2, (l+r)/2, r, cs);
	if(res.size()<res2.size()) res.swap(res2);
	res.insert(res.end(), all(res2));
	return res;
}

