// head

struct SCC{
  int n, k;
  mi G, rG;
  vi vs, cmp;
  vb used;
  void init( int size ){
    n = size;
    G = rG = mi( n , vi(0) );
    cmp = vi( n );
    vs.clear();
  }
  void add_edge( int a , int b ){
    G[a].pb( b );
    rG[b].pb( a );
  }
  void dfs( int x ){
    used[x] = true;
    YYS( w , G[x] ) if( !used[w] ) dfs( w );
    vs.pb( x );
  }
  void rdfs( int x ){
    used[x] = true;
    cmp[x] = k;
    YYS( w , rG[x] ) if( !used[w] ) rdfs( w );
  }
  int scc(){
    used = vb( n , false );
    REP( i , n ) if( !used[i] ) dfs( i );
    REVERSE( vs );
    k = 0;
    used = vb( n , false );
    YYS( w , vs ) if( !used[w] ) rdfs( w ), k++;
    return k;
  }
};


int n;

int a[10010][2];

SCC scc;

vpi v;

bool f = false;

mt19937 mt;

bool check( int len ){
  if( f and mt() % 4 == 0){
    return mt()%2;
  }
  scc.init( 2*n );
  REP( i , 2*n ){
    int id = v[i].se;
    int l = lower_bound( ALL(v) , pi( v[i].fi - len , INF ) ) - v.begin();
    int r = upper_bound( ALL(v) , pi( v[i].fi + len , -INF  ) ) - v.begin();
    FOR( j , l , r ){
      int opid = v[j].se;
      if( opid == id ){
        continue;
      }
      if( opid % 2 == 0 ){
        scc.add_edge( id , opid + 1 );
      } else {
        scc.add_edge( id , opid - 1 );
      }
    }
  }
  int k = scc.scc();
  REP( i , n ){
    if( scc.cmp[2*i] == scc.cmp[2*i+1] ){
      return false;
    }
  }
  return true;
}

int main(){

  mt.seed( 727272 );

  n = in();
  REP( i , n ){
    a[i][0] = in();
    a[i][1] = in();
    v.pb( a[i][0] , 2*i );
    v.pb( a[i][1] , 2*i+1 );
  }

  SORT( v );

  int lb = 0, ub = INF / ( n - 1 ) + 10;

  REP( i , n ){
    REP( j , i ){
      int s = 0;
      REP( k , 2 ){
        REP( l , 2 ){
          chmin( lb , abs( a[i][k] - a[j][l] ) );
          chmax( s , abs( a[i][k] - a[j][l] ) );
        }
      }
      chmin( ub , s+1 );
    }
  }

  if( n > 5000 and ub - lb > 100 ){
    f = true;
  }

  while( ub - lb > 1 ){
    int md = ( lb + ub ) / 2;
    if( check( md ) ){
      lb = md;
    } else {
      ub = md;
    }
  }

  cout << lb << endl;

  return 0;
}

