// 強連結成分分解
class SCC {
    public:
        friend class TwoSat;
        SCC() {}
        SCC(int v) { Init(v); }
        void Init(int v) {
            m_V = v;
            m_G.assign(v, vector<int>());
            m_Rg.assign(v, vector<int>());
            m_Used.assign(v, false);
            m_Cmp.assign(v, 0);
        }
        void AddEdge(int from, int to) {
            m_G[from].push_back(to);
            m_Rg[to].push_back(from);
        }
        int Scc() {
            m_Used.assign(m_V, false);
            m_Vs.clear();
            for(int v = 0; v < m_V; ++v) {
                if(!m_Used[v]) { Dfs(v); }
            }
            m_Used.assign(m_V, false);
            int k = 0;
            for(int i = int(m_Vs.size() - 1); i >= 0; --i) {
                if(!m_Used[m_Vs[i]]) { Rdfs(m_Vs[i], k++); }
            }
            return k;
        }
    private:
        void Dfs(int v) {
            m_Used[v] = true;
            for(int i = 0; i < int(m_G[v].size()); ++i) {
                if(!m_Used[m_G[v][i]]) { Dfs(m_G[v][i]); }
            }
            m_Vs.push_back(v);
        }
        void Rdfs(int v, int k) {
            m_Used[v] = true;
            m_Cmp[v] = k;
            for(int i = 0; i < int(m_Rg[v].size()); ++i) {
                if(!m_Used[m_Rg[v][i]]) { Rdfs(m_Rg[v][i], k); }
            }
        }
    private:
        int m_V;                    // 頂点数
        vector< vector<int> >  m_G; // グラフの隣接リスト表現
        vector< vector<int> > m_Rg; // 辺の向きが逆のグラフ
        vector<int> m_Vs;           // 帰りがけ順の並び
        vector<bool> m_Used;        // すでに調べたか
        vector<int> m_Cmp;          // 属する強連結成分のトポロジカル順序
};

class TwoSat {
    public:
        friend class SCC;
        TwoSat() {}
        TwoSat(int v) { Init(v); }
        void Init(int v) {
            m_V = v;
            m_Scc.Init(m_V * 2);
        }
        void AddClause(int i, bool f, int j, bool g) {
            int i_n = (f) ? i : (i + m_V);
            int i_i = (f) ? (i + m_V) : i;
            int j_n = (g) ? j : (j + m_V);
            int j_i = (g) ? (j + m_V) : j;
            m_Scc.AddEdge(i_i, j_n);
            m_Scc.AddEdge(j_i, i_n);
        }
        bool Satisfiable() {
            m_Scc.Scc();
            for(int i = 0; i < m_V; ++i) {
                if(m_Scc.m_Cmp[i] == m_Scc.m_Cmp[i + m_V]) {
                    return false;
                }
            }
            return true;
        }
        vector<bool> Answer() {
            vector<bool> ret(m_V, false);
            for(int i = 0; i < m_V; ++i) {
                if(m_Scc.m_Cmp[i] > m_Scc.m_Cmp[i + m_V]) {
                    ret[i] = true;
                }
            }
            return ret;
        }
    private:
        int m_V;
        SCC m_Scc;
};

// d 以上の間隔で旗を立てられるなら true
bool check(int d) {
    TwoSat ts(N);
    // X を選択 := true
    // Y を選択 := false 
    REP(i, N) {
        for(int j = i + 1; j < N; ++j) {
            if(abs(X[i] - X[j]) < d) {
                // この 2 つは同時に立てられない
                // -> どちらかは false にならなければいけない
                ts.AddClause(i, false, j, false);
            }
            if(abs(X[i] - Y[j]) < d) {
                ts.AddClause(i, false, j, true);
            }
            if(abs(Y[i] - X[j]) < d) {
                ts.AddClause(i, true, j, false);
            }
            if(abs(Y[i] - Y[j]) < d) {
                ts.AddClause(i, true, j, true);
            }
        }
    }
    return ts.Satisfiable();
}

