    if(L <= l && r <= R){
        d[++cnt] = now; g[cnt] = k; return;
    }
    int mid = l + r >> 1;
    if(L <= mid) insert(now, k << 1, l, mid, L, R);
    if(R > mid) insert(now, k << 1 | 1, mid + 1, r, L, R); 
