void tarjan(int x){
    dfn[x] = low[x] = ++top; 
    st[++top1] = x; vis[x] = 1;
    for(int i = fi[x]; i; i = nt[i]){
        int v = go[i]; 
        if(!dfn[v]) tarjan(v);
        if(vis[v]) low[x] = min(low[x], low[v]);
    }
    if(low[x] == dfn[x]){
        while(int y = st[top1--]){
            tag[y] = x; vis[y] = 0;
            if(x == y) break;
        }
    }
}
