	sid[cur] = 4 * n + cur;
	build(cur << 1, b, b + e >> 1);
	add_edge(sid[cur], sid[cur << 1]);
	if ((b + e >> 1) + 1 <= e) {
		build(cur << 1 | 1, (b + e >> 1) + 1, e);
		add_edge(sid[cur], sid[cur << 1 | 1]);
	}
}
