void lk(int x, int l, int r, int ql, int qr, int p) {
	if(ql > qr) return ;
	if(ql <= l && qr >= r) { add(p, u); return; }
	int mid = l + r >> 1;
	if(ql <= mid) lk(ls, l, mid, ql, qr, p);
	if(qr > mid) lk(rs, mid + 1, r, ql, qr, p);
}
