int dfn[N << 2], bel[N << 2], belnum, tp, tim, stk[N << 2], low[N << 2];
bool instk[N << 2];

void dfs(int x, int f) {
	low[x] = dfn[x] = ++ tim;
	stk[++ tp] = x;
	instk[x] = 1;
	REPG(i, head, x) if((v = edge[i].v) != f){
		if(!dfn[v]) {
			dfs(v, x), low[x] = min(low[v], low[x]);
		}
		else if(instk[v]) {
			low[x] = min(dfn[v], low[x]);
		}
	}
	if(low[x] == dfn[x]) {
		++ belnum;
		int tmp = stk[tp];
		while(tmp != x) {
			bel[tmp] = belnum;
			instk[tmp] = 0;
			tmp = stk[-- tp];
		} 
		bel[stk[tp]] = belnum;
		instk[stk[tp --]] = 0;
	}
}

bool chk(int k) {
	cnt = 0, CLR(head, -1);
	ptot = len;
	build(1, 1, len);
	REP(i, 1, len) {
		int l = lower_bound(a + 1, a + len + 1, info(a[i].val - k + 1, 0)) - a;
		int r = upper_bound(a + 1, a + len + 1, info(a[i].val + k - 1, len + 3)) - a;
		-- r;
		lk(1, 1, len, l, pos[a[i].id] - 1, a[i].id);
		lk(1, 1, len, pos[a[i].id] + 1 , r, a[i].id);
	}
	CLR(instk, 0), CLR(bel, 0), CLR(dfn, 0), CLR(low, 0), belnum = tp = tim = 0;
	REP(i, 1, ptot) {
		if(!dfn[i]) dfs(i, 0);
	} 
	REP(i, 1, n) {
		if(bel[i] == bel[i + n]) return 0;
	}
	return 1;
}

