	int i , l , r , mid;
	scanf ( "%d" , &n );
	for ( i = 1 ; i <= n ; i++ ) {
		scanf ( "%d%d" , &x[i] , &y[i] );
		mix[i*2-1] = i; mix[i*2] = -i;
