struct Data{
	int x,id;
	Data() {}
	Data(int x,int id):x(x),id(id) {}
	bool operator < (const Data &d) const {return x<d.x;}
}D[maxn<<1];

namespace SegTree{
	int id[maxnd];
#define lc (nd<<1)
#define rc (nd<<1|1)
#define mid ((s+t)>>1)

	void build(int nd,int s,int t)
	{
		if (s==t)
		{
			id[nd]=D[s].id^1;
			return;
		}
		id[nd]=++totnd;
		build(lc,s,mid);
		build(rc,mid+1,t);
	}

	void addedge0(int nd,int s,int t)
	{
		if (s==t) return;
		addedge(id[nd],id[lc]);
		addedge(id[nd],id[rc]);
		addedge0(lc,s,mid);
		addedge0(rc,mid+1,t);
	}

	void addedge1(int nd,int s,int t,int l,int r,int u)
	{
//		fprintf(stderr,"%d %d %d\n",nd,s,t);
//		Oadd1++;
		if (l<=D[s].x&&D[t].x<=r)
		{
			bool flag=0;
			flag|=s<=pos[u]&&pos[u]<=t;
			flag|=s<=pos[u^1]&&pos[u^1]<=t;
			if (!flag)
			{
				addedge(u,id[nd]);
				return;
			}
			else
			{
				if (s==t) return;
				addedge1(lc,s,mid,l,r,u);
				addedge1(rc,mid+1,t,l,r,u);
			}
		}
		if (s==t) return;
		if (l<=D[mid].x) addedge1(lc,s,mid,l,r,u);
		if (r> D[mid].x) addedge1(rc,mid+1,t,l,r,u);
	}
#undef lc
#undef rc
#undef mid
};

void init()
{
	int i;
	for (i=1;i<=n;i++)
	{
		D[i*2-1]=Data(x[i],i<<1);
		D[i*2]=Data(y[i],i<<1|1);
	}
	totnd=n<<1|1;
	sort(D+1,D+n+n+1);
	for (i=1;i<=n+n;i++)
		pos[D[i].id]=i;
	SegTree::build(1,1,n+n);
}

bool search(int u)
{
	if (vis[u]==1) return 1;
	if (vis[u^1]==1&&u<=2*n+1) return 0;
	vis[u]=1;
	S[++S[0]]=u;
	for (int p=FIR[u];p;p=NEXT[p])
		if (!search(TO[p])) return 0;
	return 1;
}

bool solve(int lim)
{
	int i;
	tote=0;
	memset(FIR,0,sizeof(FIR));

	SegTree::addedge0(1,1,n+n);
	for (i=1;i<=n+n;i++)
		SegTree::addedge1(1,1,n+n,D[i].x-lim+1,D[i].x+lim-1,D[i].id);


//	for (i=1;i<=n+n;i++)
//	for (int j=1;j<=n+n;j++)
//		if (abs(D[i].x-D[j].x)<lim&&D[i].id/2!=D[j].id/2)
//			addedge(D[i].id,D[j].id^1);


	memset(vis,0,sizeof(vis));
	for (i=1;i<=n;i++)
		if (!vis[i<<1]&&!vis[i<<1|1])
		{
			if (!search(i<<1))
			{
				while (S[0]) vis[S[S[0]--]]=0;
				if (!search(i<<1|1)) return 0;
			}
		}
	return 1;

}

