    dfn[u]=low[u]=++dfs_cnt;  
    stk[++top]=u;  
    RAL(i,u) {  
        int v=e[i].to;  
        if(!vis[v]) {  
            dfs(v);  
            low[u]=min(low[u],low[v]);  
        } else if(ins[v])   
            low[u]=min(low[u],dfn[v]);  
    }  
    if(dfn[u]==low[u]) {  
        cnt++;
        int v=-1;  
        while(u!=v) {  
            v=stk[top--];  
