        }
    }
    if(dfn[x]==low[x])
    {
        cnt_scc++;
        int tmp=0;
        while(tmp!=x)
        {
            tmp=s.top();s.pop();
            scc[tmp]=cnt_scc;
            vis[tmp]=0;
        }
    }
}
