long long N, X[1 << 18], Y[1 << 18]; pair<long long, int> A[1 << 18];
long long SIZE_ = 1;

bool flag1 = false, flag2 = false, used[1 << 18];
int col[1 << 18], cnts;
vector<int> G[1 << 18], H[1 << 18], I;

void build_edge(int u, int v) {
	G[u ^ SIZE_].push_back(v);
	G[v ^ SIZE_].push_back(u);
}

void add_edge(int x, int l, int r, int a, int b, int u) {
	// x -> [l, r)
	if (l <= a && b <= r) {
		int u1 = x, v1 = u;
		if (flag1 == true) u1 ^= SIZE_;
		if (flag2 == true) v1 ^= SIZE_;
		build_edge(u1, v1);
		return;
	}
	if (r <= a || b <= l) return;

	add_edge(x, l, r, a, (a + b) >> 1, u * 2);
	add_edge(x, l, r, (a + b) >> 1, b, u * 2 + 1);
}

void dfs1(int pos) {
	used[pos] = true;
	for (int i : G[pos]) {
		if (used[i] == false) dfs1(i);
	}
	I.push_back(pos);
}

void dfs2(int pos) {
	col[pos] = cnts;
	for (int i : H[pos]) {
		if (col[i] == 0) dfs2(i);
	}
}

bool solve(int D) {
	// ---------------------- 初期化 -------------------------
	for (int i = 0; i < SIZE_ * 2; i++) { G[i].clear(); H[i].clear(); used[i] = false; col[i] = 0; }
	I.clear(); cnts = 0;

	// --------------------- 辺を張る ------------------------
	for (int i = 0; i < N; i++) {
		build_edge(X[i] + (1 * SIZE_ / 2), Y[i] + (1 * SIZE_ / 2));
		build_edge(X[i] + (3 * SIZE_ / 2), Y[i] + (3 * SIZE_ / 2));
	}
	for (int i = 0; i < 2 * N; i++) {
		int pos1 = lower_bound(A, A + N * 2, make_pair(A[i].first - D + 1, -1000000)) - A;
		int pos2 = lower_bound(A, A + N * 2, make_pair(A[i].first + D - 1, 1000000)) - A;
		flag1 = false; flag2 = false;
		add_edge(i + (SIZE_ / 2), pos1, i, 0, SIZE_ / 2, 1);
	}
	for (int i = 1; i < SIZE_ / 2; i++) {
		build_edge(i + SIZE_, i * 2);
		build_edge(i + SIZE_, i * 2 + 1);
	}

	// ------------------- SAT を求める --------------------
	for (int i = 0; i < SIZE_ * 2; i++) {
		for (int j : G[i]) H[j].push_back(i);
	}
	for (int i = 0; i < SIZE_ * 2; i++) {
		if (used[i] == true) continue;
		dfs1(i);
	}
	reverse(I.begin(), I.end());
	for (int i : I) {
		if (col[i] >= 1) continue;
		cnts++; dfs2(i);
	}

	// ------------------- 最終チェック --------------------
	for (int i = 0; i < SIZE_; i++) {
		if (col[i] == col[i + SIZE_]) return false;
	}
	return true;
}

int main() {
	cin >> N;
	for (int i = 0; i < N; i++) {
		cin >> X[i] >> Y[i];
		A[i * 2 + 0] = make_pair(X[i], i);
		A[i * 2 + 1] = make_pair(Y[i], i + (int)N);
	}
	sort(A, A + N * 2);
	for (int i = 0; i < N * 2; i++) {
		X[i] = lower_bound(A, A + N * 2, make_pair(X[i], i)) - A;
		Y[i] = lower_bound(A, A + N * 2, make_pair(Y[i], i + (int)N)) - A;
	}
	while (SIZE_ < N * 4) SIZE_ *= 2;

	int cl = 0, cr = 1000000009, cm, maxn = -1;
	for (int i = 1; i <= 35; i++) {
		cm = (cl + cr) / 2;
		if (solve(cm) == true) { maxn = max(maxn, cm); cl = cm; }
		else { cr = cm; }
	}
	cout << maxn << endl;
	return 0;
}

