    }
    void add_or(int u, int v){
        if (u == NOT(v)) return;
        scc.add_edge(NOT(u), v);
        scc.add_edge(NOT(v), u);
    }
    void add_true(int u){ add_or(u, u); }
    void add_false(int u) { add_or(NOT(u), NOT(u)); }
    void add_xor(int u, int v){
	add_or(u, v);
	add_or(NOT(u), NOT(v));
