	fill(gtct,gtct+2*N,0);
	twoSAT cc(N);

	M=2000;

	for (int a=0;a<2;a++) for (int b=a;b<2;b++) for (int i=0;i<N;i++) for (int j=a==b?i+1:0;j<N;j++)
		if (abs(x[a][i]-x[b][j])<d) {
			cc.add_or(VAR(i)^a,VAR(j)^b);
			if (M>2500-4) return 0;
		}

	return cc.solve().X;
}


