void init(int now=1,int l=0,int r=n-1)
{
	if(l==r)
	{
		if(~pos[a[l].y])
		{
			int u=pos[a[l].y];
			addedge3(u,now);
			addedge3(now,u);
			head[u<<1]=first[u<<1];
			head[u<<1|1]=first[u<<1|1];
			head[now<<1]=first[now<<1];
			head[now<<1|1]=first[now<<1|1];
			a[l].y=now;
		}
		else
			a[l].y=pos[a[l].y]=now;
		s[now].x=s[now].y=a[l].x;
		s[rc].x=2e9;
		return;
	}
	int m=(l+r)>>1;
	init(lc,l,m);
	init(rc,m+1,r);
	s[now].x=s[lc].x;
	s[now].y=s[rc].y;
	addedge2(now,lc);
	addedge2(now,rc);
	head[now<<1]=first[now<<1];
	head[now<<1|1]=first[now<<1|1];
}

void link(int u,int L,int R,int now=1,int l=0,int r=n-1)
{
	if(L<=l&&s[now].y<=R)return addedge(u,now);
	int m=(l+r)>>1;
	if(L<=m)link(u,L,R,lc,l,m);
	if(s[rc].x<=R)link(u,L,R,rc,m+1,r);
}

void paste(int now=1,int l=0,int r=n-1)
{
	first[now<<1]=head[now<<1];
	first[now<<1|1]=head[now<<1|1];
	if(l<r)
	{
		int m=(l+r)>>1;
		paste(lc,l,m);
		paste(rc,m+1,r);
	}
}

bool twosat(int now=1,int l=0,int r=n-1)
{
	if(!check(now))return false;
	if(l<r)
	{
		int m=(l+r)>>1;
		if(!twosat(lc,l,m))return false;
		if(!twosat(rc,m+1,r))return false;
	}
	return true;
}



bool work(int d)
{
	L=_L,paste();
	for(int i=0;i<n;i++)
		link(a[i].y,i+1,a[i].x+d-1);

	return ++timer,twosat();
}


