bool hantei(int d){

	two_sat ts(N);
	int n=1;
	while(n<(2*N)) n<<=1;
	two_sat sat(2*n);
	vector<pair<ll,int>> xys(2*N);
	rep(i,N){
		xys[i*2]={xy[i].first,i};
		xys[i*2+1]={xy[i].second,i};
	}

	sort(all(xys));
	vi memo(N,-1); 
	rep(i,2*N){
		int j = xys[i].second;
		if (memo[j]==-1) memo[j]=i;
		else {
			sat.add_clause(memo[j]+n,true,i+n,true);
			sat.add_clause(memo[j]+n,false,i+n,false);
		}
		int k=i+n;
		while (k>1){
			sat.add_clause(k,false,k>>1,true);
			k>>=1;
		}

		ll val=xys[i].first;
		int l=upper_bound(all(xys),mp(val-d,100000))-xys.begin();
		int r=i;
		k=i+n;
		for (l+=n,r+=n;l<r;l=l>>1,r=r>>1){
			if(l&1) sat.add_clause(k,false,l++,false);
			if(r&1) sat.add_clause(k,false,--r,false);
		}

		l=i+1;
		r=lower_bound(all(xys),mp(val+d,-1))-xys.begin();
		for (l+=n,r+=n;l<r;l>>=1,r>>=1){
			if(l&1) sat.add_clause(k,false,l++,false);
			if(r&1) sat.add_clause(k,false,--r,false);
		}
	}


	return sat.satisfiable();
}

