int x[10005], y[10005];

const int MAXN = 20001;

vector<int> graph[MAXN];
int up[MAXN], visit[MAXN], vtime;
vector<int> stk;
int scc_idx[MAXN], scc_cnt;
int gn, n;

void dfs(int nod) {
	up[nod] = visit[nod] = ++vtime;
	stk.push_back(nod);
	for (int next : graph[nod]) {
		if (visit[next] == 0) {
			dfs(next);
			up[nod] = min(up[nod], up[next]);
		}
		else if (scc_idx[next] == 0)
			up[nod] = min(up[nod], visit[next]);
	}
	if (up[nod] == visit[nod]) {
		++scc_cnt;
		int t;
		do {
			t = stk.back();
			stk.pop_back();
			scc_idx[t] = scc_cnt;
		} while (!stk.empty() && t != nod);
	}
}
// find SCCs in given directed graph
// O(V+E)
void get_scc() {
	vtime = 0;
	memset(visit, 0, sizeof(visit));
	scc_cnt = 0;
	memset(scc_idx, 0, sizeof(scc_idx));
	for (int i = 0; i < gn; ++i)
		if (visit[i] == 0) dfs(i);
}

bool check(int t)
{
	for (int i = 0; i < gn; i++) graph[i].clear();

	int gt = 0;

	for (int i = 0; i < n; i++) for (int j = i + 1; j < n; j++)
	{
		int cnt = 0;

		if (abs(x[i] - x[j]) < t)
		{
			cnt++;
			graph[i].push_back(j + n);
			graph[j].push_back(i + n);
		}

		if (abs(x[i] - y[j]) < t)
		{
			cnt++;
			graph[i].push_back(j);
			graph[j + n].push_back(i + n);
		}

		if (abs(y[i] - x[j]) < t)
		{
			cnt++;
			graph[i + n].push_back(j + n);
			graph[j].push_back(i);
		}

		if (abs(y[i] - y[j]) < t)
		{
			cnt++;
			graph[i + n].push_back(j);
			graph[j + n].push_back(i);
		}

		if (cnt == 4) return false;
		gt += cnt;

		if (gt > 1000000) return false;
	}

	get_scc();

	for (int i = 0; i < n; i++) if (scc_idx[i] == scc_idx[i + n]) return false;
	return true;
}

int main()
{
	scanf("%d", &n);
	gn = n * 2;
	for (int i = 0; i < n; i++) scanf("%d%d", &x[i], &y[i]);

	int lo = 1, hi = (max(*max_element(x, x + n), *max_element(y, y + n)) - min(*min_element(x, x + n), *min_element(y, y + n))) / (n - 1), ans = 0;

	for (int i = 0; i < n; i++) for (int j = i + 1; j < n; j++)
		hi = min(hi, max({
		abs(x[i] - x[j]),
		abs(x[i] - y[j]),
		abs(y[i] - x[j]),
		abs(y[i] - y[j]),
		}));

	while (lo <= hi)
	{
		int mid = (lo + hi) / 2;
		if (check(mid))
		{
			ans = mid;
			lo = mid + 1;
		}
		else hi = mid - 1;
	}

	printf("%d\n", ans);
}

#include<bits/stdc++.h>
const int N=100007;
int n,pw[N][2],pp=0,mx,L,R,M;
struct pos{
	int x,id,w;
	bool operator<(const pos&p)const{return x<p.x;}
}ps[N*2];
int dfn[N],low[N],scc[N],tk=0,ss[N],sp=0,I[N],tr1[N],tr2[N];
std::vector<int>e[N];
bool in[N];
void mins(int&a,int b){if(a>b)a=b;}
void tj(int w){
	dfn[w]=low[w]=++tk;
	in[ss[++sp]=w]=1;
	for(int i=0;i<e[w].size();++i){
		int u=e[w][i];
		if(!dfn[u]){
			tj(u);
			mins(low[w],low[u]);
		}else if(in[u])mins(low[w],dfn[u]);
	}
	if(dfn[w]==low[w]){
		int u;
		do in[u=ss[sp--]]=0,scc[u]=w;while(u!=w);
	}
}
void ae(int a,int b){
	e[a].push_back(b);
}
void ae1(int w,int l,int r){
	if(l>r)return;
	if(l<=w&&w<=r)ae1(w,l,w-1),ae1(w,w+1,r);
	else for(w+=mx,l+=mx-1,r+=mx+1;r-l>1;l>>=1,r>>=1){
		if(~l&1)ae(w,tr1[l+1]);
		if(r&1)ae(w,tr1[r-1]);
	}
}
void ae2(int w,int l,int r){
	if(l>r)return;
	if(l<=I[w]&&I[w]<=r)ae2(w,l,I[w]-1),ae2(w,I[w]+1,r);
	else for(w+=mx,l+=mx-1,r+=mx+1;r-l>1;l>>=1,r>>=1){
		if(~l&1)ae(tr2[l+1],w);
		if(r&1)ae(tr2[r-1],w);
	}
}
bool chk(){
	for(int i=0;i<mx*3;++i)dfn[i]=0,e[i].clear();
	for(int i=2;i<mx;++i)ae(i/2,i),ae(mx*2+i,mx*2+i/2);
	for(int i=1;i<=pp;++i){
		int j=I[i],l0,r0;
		ae(mx+i>>1,mx+j);
		ae(mx+i,mx*2+(mx+i>>1));
		l0=std::upper_bound(ps+1,ps+pp+1,(pos){ps[i].x-M})-ps;
		r0=std::lower_bound(ps+1,ps+pp+1,(pos){ps[i].x+M})-ps-1;
		ae1(i,l0,r0);
		ae2(j,l0,r0);
	}
	tj(1);
	for(int i=1;i<=n;++i)if(scc[mx+pw[i][0]]==scc[mx+pw[i][1]])return 0;
	return 1;
}
int main(){
	scanf("%d",&n);
	for(int i=1,x,y;i<=n;++i){
		scanf("%d%d",&x,&y);
		ps[++pp]=(pos){x,i,0};
		ps[++pp]=(pos){y,i,1};
	}
	std::sort(ps+1,ps+pp+1);
	for(mx=1;mx<pp+2;mx<<=1);
	for(int i=1;i<=pp;++i)pw[ps[i].id][ps[i].w]=i;
	for(int i=1;i<=pp;++i){
		int x=pw[i][0],y=pw[i][1];
		I[x]=y,I[y]=x;
	}
	for(int i=1;i<mx;++i)tr1[i]=i,tr2[i]=mx*2+i;
	for(int i=1;i<=pp;++i)tr1[mx+i]=mx+I[i],tr2[mx+i]=mx+i;
	L=0,R=1e9;
	while(L<R){
		M=L+R+1>>1;
		if(chk())L=M;
		else R=M-1;
	}
	printf("%d\n",L);
	return 0;
}

