const int N=2e5+10,inf=0x3f3f3f3f;
struct TWO_SAT {
    int n,hd[N],ne,mk[N],sta[N],tp;
    struct E {int v,nxt;} e[N*80];
    void link(int u,int v) {e[ne]= {v,hd[u]},hd[u]=ne++;}
    void link(int u,int v,int f1,int f2) {
        link(u<<1|f1,v<<1|f2);
        link(v<<1|(!f2),u<<1|(!f1));
    }
    void init(int _n) {
        n=_n,ne=tp=0;
        for(int i=0; i<=n; ++i)mk[i]=0,hd[i]=-1;
    }
    bool dfs(int u) {
        if(mk[u^1])return 0;
        if(mk[u])return 1;
        mk[u]=1,sta[tp++]=u;
        for(int i=hd[u]; ~i; i=e[i].nxt)if(!dfs(e[i].v))return 0;
        return 1;
    }
    bool check() {
        for(int i=1; i<=n; ++i)mk[i]=0;
        for(int i=1; i<=n; ++i)if(!mk[i<<1]&&!mk[i<<1|1]) {
                tp=0;
                if(!dfs(i<<1)) {
                    for(; tp; mk[sta[--tp]]=0);
                    if(!dfs(i<<1|1))return 0;
                }
            }
        return 1;
    }
} twosat;
#define ls (u<<1)
#define rs (u<<1|1)
#define mid ((l+r)>>1)
int n,tot,X[N],Y[N],nb,nd[N];
struct D {
    int x,i,f;
    bool operator<(const D& b)const {return x<b.x;}
} b[N];
void build(int u=1,int l=0,int r=nb-1) {
    if(l==r) {nd[l]=u; return;}
    build(ls,l,mid),build(rs,mid+1,r);
}
void build2(int u=1,int l=0,int r=nb-1) {
    if(l==r)return;
    build2(ls,l,mid),build2(rs,mid+1,r);
    twosat.link(u,ls,0,0),twosat.link(u,rs,0,0);
}
void upd(int v,int L,int R,int u=1,int l=0,int r=nb-1) {
    if(l>=L&&r<=R) {twosat.link(v,u,1,0); return;}
    if(l>R||r<L)return;
    upd(v,L,R,ls,l,mid),upd(v,L,R,rs,mid+1,r);
}
int lb(int x) {return lower_bound(b,b+nb, (D) {x,0,0})-b;}
int rb(int x) {return upper_bound(b,b+nb, (D) {x,0,0})-b-1;}
bool ok(int d) {
    twosat.init((n+10)<<3);
    build2();
    for(int i=1; i<=n; ++i) {
        upd(nd[X[i]],lb(b[X[i]].x-d+1),X[i]-1);
        upd(nd[X[i]],X[i]+1,rb(b[X[i]].x+d-1));
        upd(nd[Y[i]],lb(b[Y[i]].x-d+1),Y[i]-1);
        upd(nd[Y[i]],Y[i]+1,rb(b[Y[i]].x+d-1));
        twosat.link(nd[X[i]],nd[Y[i]],1,0);
        twosat.link(nd[X[i]],nd[Y[i]],0,1);
    }
    return twosat.check();
}
int bi(int l,int r) {
    int ret=l;
    while(l<=r) {
        if(ok(mid))ret=mid,l=mid+1;
        else r=mid-1;
    }
    return ret;
}
int main() {
    //FRER();
    scanf("%d",&n);
    for(int i=1; i<=n; ++i)scanf("%d%d",&X[i],&Y[i]);
    b[nb++]= {~inf,-1,-1},b[nb++]= {inf,-1,-1};
    for(int i=1; i<=n; ++i)b[nb++]= {X[i],i,0},b[nb++]= {Y[i],i,1};
    sort(b,b+nb);
    for(int i=1; i<nb-1; ++i) {
        if(b[i].f==0)X[b[i].i]=i;
        else Y[b[i].i]=i;
