using namespace std;
int n,tot,ans,cnt,top,kuai,maxx,minn,v1,v2,js;
const int N=1000010,inf=0x3f3f3f3f;
int dfn[N],low[N],zhan[N],c[N],head[N],pos[N];
bool vis[N];
struct bian
{
	int to,nt;
}e[N<<1];
