inline int read()
{
    int res=0;char ch=getchar();bool XX=false;
    for(;!isdigit(ch);ch=getchar())(ch=='-') && (XX=true);
    for(;isdigit(ch);ch=getchar())res=(res<<3)+(res<<1)+(ch^48);
    return XX?-res:res;
}
void add(int f,int t)
{
	e[++tot].to=t;
	e[tot].nt=head[f];
	head[f]=tot;
}
void tarjan(int x)
{
	dfn[x]=low[x]=++cnt;
	zhan[++top]=x;vis[x]=1;
	for(int i=head[x];i;i=e[i].nt)
	{
		if(!dfn[e[i].to])
		{
			tarjan(e[i].to);
			low[x]=min(low[x],low[e[i].to]);
		}
		else if(vis[e[i].to])low[x]=min(low[x],dfn[e[i].to]);
	}
	if(low[x]==dfn[x])
	{
		int k;++kuai;
		do
		{
			k=zhan[top--];
			vis[k]=0;
			c[k]=kuai;
		}while(k!=x);
	}
}
void build(int k,int l,int r)
{
	if(l==r)
	{
		add(k+(n<<1),z[l].p<=n?z[l].p+n:z[l].p-n);
		return;
	}
	build(lson,l,mid);
	build(rson,mid+1,r);
	add(k+(n<<1),lson+(n<<1));
	add(k+(n<<1),rson+(n<<1));
}
void Insert(int k,int l,int r,int x,int y,int p)
{
	if(x<=l&&r<=y)
	{
		add(p,k+(n<<1));
		return;
	}
	if(x<=mid)Insert(lson,l,mid,x,y,p);
	if(mid+1<=y)Insert(rson,mid+1,r,x,y,p);
}
bool check(int k)
{
	memset(dfn,0,sizeof(dfn));
	memset(head,0,sizeof(head));
	top=tot=kuai=0;
	build(1,1,n<<1);
	int l=1,r=1;
	for(int i=1;i<=(n<<1);++i)
	{
		int op,p=z[i].p;
		if(p<=n)op=pos[p+n];
		else op=pos[p-n];
		while(r<=i&&z[r].v<=z[i].v-k)r++;
		if(r<i&&r>=1&&z[r].v>z[i].v-k)
		{
			if(op>=r&&op<=i-1)
