namespace Segment_Tree
{
	int ls[MAXM],rs[MAXM],in[MAXM],out[MAXM],root,tree_cnt,to;

	void build(int l,int r,int &cur)
	{
		cur=++tree_cnt;
		if(l==r) return out[l]=cur,void();
		int mid=(l+r)>>1;
		build(l,mid,ls[cur]);
		build(mid+1,r,rs[cur]);
		v[cur].push_back(ls[cur]);
		v[cur].push_back(rs[cur]);
	}

	void modify(int l,int r,int ql,int qr,int cur)
	{
		if(ql<=l&&qr>=r)
			return v[to].push_back(cur);
		int mid=(l+r)>>1;
		if(ql<=mid) modify(l,mid,ql,qr,ls[cur]);
		if(qr>mid) modify(mid+1,r,ql,qr,rs[cur]);
	}

	inline void clear()
	{
		for(int i=1;i<=tree_cnt;i++)
			v[i].clear();
		tree_cnt=0;
	}

	inline void rebuild()
	{
		clear();
		for(int i=1;i<=tot;i++)
			in[i]=++tree_cnt;
		build(1,tot,root);
		for(int i=1;i<=tot;i++)
			v[out[i]].push_back(in[another[i]]);
	}

	inline void add(int cur,int l,int r)
	{
		to=cur; if(l>r) return;
		modify(1,tot,max(0,l),min(r,tot),root);
	}

	inline void add_edge(int mid)
	{
		for(int i=1;i<=tot;i++)
		{
			int pos=dat[i].first;
			int l=lower_bound(cnt+1,cnt+tot+1,pos-mid+1)-cnt;
			int r=upper_bound(cnt+1,cnt+tot+1,pos+mid-1)-cnt-1;
			add(in[i],l,i-1);
			add(in[i],i+1,r);
		}
	}
}

