void build(int k, int l, int r){
    if(l == r) {num[l] = k; return; } 
    int mid = l + r >> 1;
    build(k << 1, l, mid); 
    build(k << 1 | 1, mid + 1, r);
    d[++cnt] = k; g[cnt] = k << 1;
    d[++cnt] = k; g[cnt] = k << 1 | 1;
}
void insert(int now, int k, int l, int r, int L, int R){
    if(l > r) return;
    if(L <= l && r <= R){
        d[++cnt] = now; g[cnt] = k; return;
    }
    int mid = l + r >> 1;
    if(L <= mid) insert(now, k << 1, l, mid, L, R);
    if(R > mid) insert(now, k << 1 | 1, mid + 1, r, L, R); 
}
void tarjan(int x){
    dfn[x] = low[x] = ++top; 
    st[++top1] = x; vis[x] = 1;
    for(int i = fi[x]; i; i = nt[i]){
        int v = go[i]; 
        if(!dfn[v]) tarjan(v);
        if(vis[v]) low[x] = min(low[x], low[v]);
    }
    if(low[x] == dfn[x]){
        while(int y = st[top1--]){
            tag[y] = x; vis[y] = 0;
            if(x == y) break;
        }
    }
}
bool solve(int x){
    cntx = 0;
    for(int i = 1; i <= 100000; i++) tag[i] = i, dfn[i] = 0, fi[i] = 0;
    top = 0; top1 = 0;  cnt = 0; 
    build(1, 1, n << 1); 
    for(int i = 1; i <= n; i++){
        int o = (i & 1) ? 1 : -1;
        d[++cnt] = num[id[i]]; g[cnt] = num[id[i + o] + n];
        d[++cnt] = num[id[i + o] + n]; g[cnt] = num[id[i]];
        int R = lower_bound(c + 1, c + n + 1, c[id[i]] + x) - c - 1;
        int L = upper_bound(c + 1, c + n + 1, c[id[i]] - x) - c;
        insert(num[id[i]], 1, 1, n << 1, L + n, id[i] + n - 1);
        insert(num[id[i]], 1, 1, n << 1, id[i] + n + 1, R + n); 
    }
    for(int i = 1; i <= cnt; i++) add(d[i], g[i]);
    tarjan(1);
    for(int i = 1; i <= n; i++)
    for(int i = 1; i <= n; i++){
        if(tag[num[id[i]]] == tag[num[id[i] + n]]) return false;
    }
    return true;
}
