#define MAX_N 3030303
long long extgcd(long long a, long long b, long long& x, long long& y) {
    long long d = a;
    if (b != 0) {
        d = extgcd(b, a % b, y, x);
        y -= (a / b) * x;
    } else {
        x = 1; y = 0;
    }
    return d;
}
long long mod_inverse(long long a, long long m) {
    long long x, y;
    if(extgcd(a, m, x, y) == 1) return (m + x % m) % m;
    else return -1;
}
vector<long long> fact(MAX_N+1, inf);
long long mod_fact(long long n, long long& e) {
    if(fact[0] == inf) {
        fact[0]=1;
        if(MAX_N != 0) fact[1]=1;
        for(ll i = 2; i <= MAX_N; ++i) {
            fact[i] = (fact[i-1] * i) % mod;
        }
    }
    e = 0;
    if(n == 0) return 1;
    long long res = mod_fact(n / mod, e);
    e += n / mod;
    if((n / mod) % 2 != 0) return (res * (mod - fact[n % mod])) % mod;
    return (res * fact[n % mod]) % mod;
}
// return nCk
long long mod_comb(long long n, long long k) {
    if(n < 0 || k < 0 || n < k) return 0;
    long long e1, e2, e3;
    long long a1 = mod_fact(n, e1), a2 = mod_fact(k, e2), a3 = mod_fact(n - k, e3);
    if(e1 > e2 + e3) return 0;
    return (a1 * mod_inverse((a2 * a3) % mod, mod)) % mod;
}

using mi = modint;

mi mod_pow(mi a, ll n) {
    mi ret = 1;
    mi tmp = a;
    while(n > 0) {
        if(n % 2) ret *= tmp;
        tmp = tmp * tmp;
        n /= 2;
    }
    return ret;
}

struct edge {
    int src, dst;
};
using graph = vector<vector<edge>>;

#define VAR(x) ((x) << 1)
#define NOT(x) ((x) ^ 1)
void visit(int v, const graph &g,
    vector<int> &ord, vector<int> &num, int k) {
  if (num[v] >= 0) return;
  num[v] = k;
  for (int i = 0; i < g[v].size(); ++i)
    visit(g[v][i].dst, g, ord, num, k);
  ord.push_back(v);
}
typedef pair<int,int> clause;
bool two_satisfiability(int m, const vector<clause> &cs) {
  int n = m * 2; // m positive vars and m negative vars
  graph g(n), h(n);
  for (int i = 0; i < cs.size(); ++i) {
    int u = cs[i].first, v = cs[i].second;
    g[NOT(u)].push_back( edge{NOT(u), v} );
    g[NOT(v)].push_back( edge{NOT(v), u} );
    h[v].push_back( edge{v, NOT(u)} );
    h[u].push_back( edge{u, NOT(v)} );
  }
  vector<int> num(n, -1), ord, dro;
  for (int i = 0; i < n; ++i)
    visit(i, g, ord, num, i);
  reverse(ord.begin(), ord.end());
  fill(num.begin(), num.end(), -1);
  for (int i = 0; i < n; ++i)
    visit(ord[i], h, dro, num, i);
  for (int i = 0; i < n; ++i)
    if (num[i] == num[NOT(i)])
      return false;
  return true;
}

const int V = 10000, B = 400;
vector<pair<int, pair<int, bool>>> p(2 * V, {2 * inf + 314, {-1, false}});

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n;
    cin >> n;
    REP(i, n) {
        int x, y;
        cin >> x >> y;
        p[2 * i] = {x, {i, 0}};
        p[2 * i + 1] = {y, {i, 1}};
    }
    sort(ALL(p));
    int l = 0, r = inf + 1;
    while(r - l > 1) {
        int med = (l + r) / 2;
        vector<clause> cs;
        REP(i, 2 * V) {
            if(p[i].first == 2 * inf + 314) break;
            int t = VAR(p[i].second.first);
            if(p[i].second.second) t = NOT(t);
            cs.push_back({NOT(t), VAR(V + i / B)});
            for(int j = B * (i / B); j < B * (i / B + 1); j++) {
                if(i == j) continue;
                if(abs(p[i].first - p[j].first) < med) {
                    int u = VAR(p[j].second.first);
                    if(p[j].second.second) u = NOT(u);
                    cs.push_back({NOT(t), NOT(u)});
                }
            }
            REP(j, 2 * V / B) {
                if(j == i / B) continue;
                int a = j * B, b = (j + 1) * B - 1;
                if(abs(p[i].first - p[a].first) >= med
                   && abs(p[i].first - p[b].first) >= med) continue;
                else if(abs(p[i].first - p[a].first) < med
                        && abs(p[i].first - p[b].first) < med) {
                    cs.push_back({NOT(t), NOT(VAR(j))});
                } else {
                    for(int k = a; k <= b; k++) {
                        if(abs(p[i].first - p[k].first) < med) {
                            int u = VAR(p[k].second.first);
                            if(p[k].second.second) u = NOT(u);
                            cs.push_back({NOT(t), NOT(u)});
                        }
                    }
                }
            }

        }
        /*
        REP(i, cs.size()) {
            cout << cs[i].first / 2 << " " << cs[i].first % 2;
            cout << " ";
            cout << cs[i].second / 2 << " " << cs[i].second % 2 << endl;
        }
         */
        if(two_satisfiability(V + 2 * V / B, cs)) l = med;
        else r = med;
    }
    cout << l << endl;
    return 0;
}

