using namespace std;

int const MAXN = 2e7 + 5;
int MaxNode = 0, n, _2n;
struct Edges { int to, next; } e[MAXN * 2];
int head[MAXN], tot;
int Dfn[MAXN], Col[MAXN], col, Low[MAXN], cnt, stk[MAXN], top, vis[MAXN];
struct nodes { int x, y; } a[MAXN];
struct Nodes { int x, id; } t[MAXN];
inline bool cmp(Nodes x, Nodes y) { return x.x < y.x; }

inline void addedge(int from, int to) {
  e[++tot] = (Edges){to, head[from]};
  head[from] = tot;
}

void Get_MaxNode(int x, int l, int r) {
  MaxNode = max(MaxNode, x);
  if (l == r) return;
  int mid = (l + r) >> 1;
  Get_MaxNode(lc, l, mid);
  Get_MaxNode(rc, mid + 1, r);
}

void Build(int x, int l, int r, int opt) {
  if (!opt) addedge(x, x + MaxNode);
  if (l == r) return;
  if (!opt) addedge(x, lc), addedge(x, rc);
  else addedge(lc + MaxNode, x + MaxNode), addedge(rc + MaxNode, x + MaxNode);
  int mid = (l + r) >> 1;
  Build(lc, l, mid, opt);
  Build(rc, mid + 1, r, opt);
}

int Get(int x, int l, int r, int to) {
  if (l == r) return x;
  int mid = (l + r) >> 1;
  if (to <= mid) return Get(lc, l, mid, to);
  else return Get(rc, mid + 1, r, to);
}
void Link(int x, int l, int r, int i, int j, int node) {
  if (i > j) return;
  if (l == r) return addedge(x + MaxNode, node);
  int mid = (l + r) >> 1;
  if (i <= mid) Link(lc, l, mid, i, j, node);
  if (j > mid) Link(rc, mid + 1, r, i, j, node);
}

void Tarjan(int k) {
  Low[k] = Dfn[k] = ++cnt;
  vis[k] = stk[++top] = k;
  for (RI i = head[k]; i; i = e[i].next)
      if (!Dfn[e[i].to]) {
        Tarjan(e[i].to);
        Low[k] = min(Low[k], Low[e[i].to]);
      }
      else if (vis[e[i].to]) Low[k] = min(Low[k], Dfn[e[i].to]);
  if (Dfn[k] == Low[k]) {
    ++col;
    while (stk[top] != k) Col[stk[top]] = col, vis[stk[top]] = 0, --top;
    Col[stk[top]] = col, vis[stk[top]] = 0, --top;
  }
}

bool Check(int k) {
  for (RI i = 1; i <= MaxNode * 2; ++i)
    head[i] = Dfn[i] = Low[i] = Col[i] = 0;
  tot = cnt = col = top = 0;
  Build(1, 1, _2n, 0);
  Build(1, 1, _2n, 1);
  for (RI i = 1; i <= _2n; ++i) {
    int l = 1, r = i - 1, mid, ll = i;
    while (l <= r) {
      mid = (l + r) >> 1;
      if (t[i].x - t[mid].x >= k) l = mid + 1;
      else ll = mid, r = mid - 1;
    }
    l = i + 1, r = _2n; int rr = i;
    while (l <= r) {
      mid = (l + r) >> 1;
      if (t[mid].x - t[i].x >= k) r = mid - 1;
      else rr = mid, l = mid + 1;
    }
    Link(1, 1, _2n, ll, i - 1, Get(1, 1, _2n, a[t[i].id].x == i ? a[t[i].id].y : a[t[i].id].x));
    Link(1, 1, _2n, i + 1, rr, Get(1, 1, _2n, a[t[i].id].x == i ? a[t[i].id].y : a[t[i].id].x));
  }
  for (RI i = 1; i <= 2 * MaxNode; ++i)
    if (!Dfn[i]) Tarjan(i);
  for (RI i = 1; i <= n; ++i)
    if (Col[Get(1, 1, _2n, a[i].x)] == Col[Get(1, 1, _2n, a[i].y)])
      return 0;
  return 1;
}

