bool Twosat(int n)
{
	memset(vis,false,sizeof(vis));
	for(int i=0;i<n;i+=2)
	{
		if(vis[i]||vis[i^1])continue;
		top=0;
		if(!dfs(i))
		{
			while(top)vis[S[--top]]=false;
			if(!dfs(i^1)) return false;
		}
	}
	return true;
}
bool judge(int now)
{
	init();
	for(int i=0;i<n;i++)
	{
		for(int j=i+1;j<n;j++)
		{
			int u,v;
			if(i==j)
			{
				continue;
			}
			if(abs(sv[i].x-sv[j].x)<now)
			{
				u=i*2,v=j*2;
				addedge(u,v^1);
				addedge(v,u^1);
			}
			if(abs(sv[i].x-sv[j].y)<now)
			{
				u=i*2,v=(j*2)^1;
				addedge(u,v^1);
				addedge(v,u^1);
			}
			if(abs(sv[i].y-sv[j].x)<now)
			{
				u=(i*2)^1,v=j*2;
				addedge(u,v^1);
				addedge(v,u^1);
			}
			if(abs(sv[i].y-sv[j].y)<now)
			{
				u=(i*2)^1,v=(j*2)^1;
				addedge(u,v^1);
				addedge(v,u^1);
			}
			if(tot>MAX)
				return false;
		}
	}
	return Twosat(2*n);
