inline void base_link(int x,int l,int r) {
	const int lg = std::__lg(r - l);
	tj::link(st[lg][l], x);
	tj::link(st[lg][r - (1 << lg)], x);
}
inline void link(int x,int l,int r,int mid) {
	l = get(l), r = get(r + 1);
	if(l < mid) base_link(x, l, mid);
	if(mid + 1 < r) base_link(x, mid + 1, r);
}
inline bool can(int len) {
	tj::clear(); int tot = n + n;
	rep(i, 1, n + n) st[0][i] = rk[i];
	rep(i, 1, 19) for(int j = 1;j + (1 << i) - 1 <= n + n;++j) {
		st[i][j] = ++tot;
		tj::link(st[i - 1][j], st[i][j]);
		tj::link(st[i - 1][j + (1 << i - 1)], st[i][j]);
	}
	rep(i, 1, n) {
		link(i, x[i + n] - len + 1, x[i + n] + len - 1, irk[i + n]);
		link(i + n, x[i] - len + 1, x[i] + len - 1, irk[i]);
	}
	rep(i, 1, tot) if(!tj::dfn[i])
		tj::dfs(i);
	rep(i, 1, n) if(tj::block[i] == tj::block[i + n]) return 0;
	return 1;
}
