void solveRange(pt range[maxn], obj from[maxn],obj to[maxn], int d) {
	For(i,1,n) {
		{	
			int val = from[i].l - d + 1;
			int l = 1, r = n, res = n + 1;
			while (l <= r) {
				int mid = (l + r) >> 1;
				if (to[mid].l >= val) {
					res = mid;
					r = mid - 1;
				} else l = mid + 1;
			}
			range[from[i].id].first = res;
		}

		{
			int val = from[i].l + d - 1;
			int l = 1, r = n, res = 0;
			while (l <= r) {
				int mid = (l + r) >> 1;
				if (to[mid].l <= val) {
					res = mid;
					l = mid + 1;
				} else r = mid - 1;
			}
			range[from[i].id].second = res;
		}
	}
}

