using namespace std;

const int MAXN = 100000; // число вершин
const int INF = 1000000000; // константа-бесконечность

struct edge {
    int a, b, cap, flow;
};

int n, s, t, d[MAXN], ptr[MAXN], q[MAXN];
vector<edge> e;
vector<int> g[MAXN];

void add_edge (int a, int b, int cap) {
    edge e1 = { a, b, cap, 0 };
    edge e2 = { b, a, 0, 0 };
    g[a].push_back ((int) e.size());
    e.push_back (e1);
    g[b].push_back ((int) e.size());
    e.push_back (e2);
}

bool bfs() {
    int qh=0, qt=0;
    q[qt++] = s;
    memset (d, -1, n * sizeof d[0]);
    d[s] = 0;
    while (qh < qt && d[t] == -1) {
        int v = q[qh++];
        for (size_t i=0; i<g[v].size(); ++i) {
            int id = g[v][i],
                    to = e[id].b;
            if (d[to] == -1 && e[id].flow < e[id].cap) {
                q[qt++] = to;
                d[to] = d[v] + 1;
            }
        }
    }
    return d[t] != -1;
}

int dfs (int v, int flow) {
    if (!flow)  return 0;
    if (v == t)  return flow;
    for (; ptr[v]<(int)g[v].size(); ++ptr[v]) {
        int id = g[v][ptr[v]],
                to = e[id].b;
        if (d[to] != d[v] + 1)  continue;
        int pushed = dfs (to, min (flow, e[id].cap - e[id].flow));
        if (pushed) {
            e[id].flow += pushed;
            e[id^1].flow -= pushed;
            return pushed;
        }
    }
    return 0;
}

int dinic() {
    n = t + 1;
    int flow = 0;
    for (;;) {
        if (!bfs())  break;
        memset (ptr, 0, n * sizeof ptr[0]);
        while (int pushed = dfs (s, INF))
            flow += pushed;
    }
    return flow;
}

bool check(int x, int n, vector<pair<int, int> >& v) {
    e.clear();
    for(int i = 0; i < MAXN; i++)
        g[i].clear();
    for(int i = 1; i <= n; i++) {
        add_edge(0, i, 1);
    }
    vector<vector<int> > was(n + 1);
    for(int i = 0; i < (int)v.size(); i++) {
        was[v[i].second].push_back(i + 1);
    }
    for(int i = 1; i <= n; i++) {
        add_edge(i, n + was[i][0], 1);
        add_edge(i, n + was[i][1], 1);
    }
    for(int i = 2; i <= 2 * n; i++) {
        add_edge(3 * n + i, 3 * n + i - 1, INF);
    }
    for(int i = 1; i + 1 <= 2 * n; i++) {
        add_edge(5 * n + i, 5 * n + i + 1, INF);
    }
    for(int i = 1; i <= 2 * n; i++) {
        add_edge(3 * n + i, 7 * n + i, 1);
        add_edge(5 * n + i, 7 * n + i, 1);
        add_edge(7 * n + i, 9 * n + 1, 1);
    }
    int ptr = 0;
    for(int i = 1; i <= 2 * n; i++) {
        while(ptr + 1 < i && v[i - 1].first - v[ptr + 1 - 1].first >= x)
            ptr++;
        if(ptr > 0)
            add_edge(n + i, 3 * n + ptr, 1);
    }
    ptr = 2 * n + 1;
    for(int i = 2 * n; i >= 1; i--) {
        while(ptr - 1 > i && v[ptr - 1 - 1].first - v[i - 1].first >= x)
            ptr--;
        if(ptr <= 2 * n)
            add_edge(n + i, 5 * n + ptr, 1);
    }
    s = 0;
    t = 9 * n + 1;
    int r = dinic();
    //cout << x << " " << r << endl;
    return r == n;
}

