const int MAXN = 1e4 + 5;
const int off = 1 << 15;
const int ADD = 2 * off;
const int INF = 1e9;

int n;
int X[MAXN], Y[MAXN], scc[4 * off + 5], iks[MAXN], ips[MAXN];
vector <int> E[4 * off + 5], inv_E[4 * off + 5];
bool bio[4 * off + 5];
stack <int> stek;
vector <point> v;

struct Tournament{

    void addEdge(int x, int val){
        E[x].pb(val + ADD); inv_E[val + ADD].pb(x);
        E[val].pb(x + ADD); inv_E[x + ADD].pb(val);
    }

    void get(int x, int lo, int hi, int a, int b, int val){
        if(lo >= b || hi <= a) return;
        if(lo >= a && hi <= b){ addEdge(x, val); return; }
        int mid = (lo + hi) >> 1;
        get(x * 2, lo, mid, a, b, val);
        get(x * 2 + 1, mid, hi, a, b, val);
    }
}T;

void dfs1(int x){
    bio[x] = true;
    for(auto it : E[x])
        if(!bio[it])
            dfs1(it);
    stek.push(x);
}

void dfs2(int x, int val){
    scc[x] = val;
    for(auto it : inv_E[x])
        if(scc[it] == -1)
            dfs2(it, val);
}

bool check(int mid){
    REP(i, 4 * off + 5){
        E[i].clear(); inv_E[i].clear();
        bio[i] = false; scc[i] = -1;
    }
    for(int i = off - 1; i > 0; --i){
        E[i].pb(i * 2); inv_E[i * 2].pb(i);
        E[i].pb(i * 2 + 1); inv_E[i * 2 + 1].pb(i);
        E[i + ADD].pb(i * 2 + ADD); inv_E[i * 2 + ADD].pb(i + ADD);
        E[i + ADD].pb(i * 2 + 1 + ADD); inv_E[i * 2 + 1 + ADD].pb(i + ADD);
    }

    REP(i, n){
        E[iks[i] + ADD + off].pb(ips[i] + off); inv_E[ips[i] + off].pb(iks[i] + ADD + off);
        E[ips[i] + ADD + off].pb(iks[i] + off); inv_E[iks[i] + off].pb(ips[i] + ADD + off);
        int x = upper_bound(v.begin(), v.end(), point(X[i] - mid, INF)) - v.begin();
        int y = lower_bound(v.begin(), v.end(), point(X[i] + mid, -1)) - v.begin();
        if(x < iks[i]) T.get(1, 0, off, x, iks[i], iks[i] + off);
        if(iks[i] + 1 < y) T.get(1, 0, off, iks[i] + 1, y, iks[i] + off);

        x = upper_bound(v.begin(), v.end(), point(Y[i] - mid, INF)) - v.begin();
        y = lower_bound(v.begin(), v.end(), point(Y[i] + mid, -1)) - v.begin();
        if(x < ips[i]) T.get(1, 0, off, x, ips[i], ips[i] + off);
        if(ips[i] + 1 < y) T.get(1, 0, off, ips[i] + 1, y, ips[i] + off);
    }

    REP(i, 4 * off + 5)
        if(!bio[i])
            dfs1(i);
    int cnt = 0;
    while(!stek.empty()){
        if(scc[stek.top()] == -1)
            dfs2(stek.top(), cnt ++);
        stek.pop();
    }
    //cout << cnt << " cnt\n";
    REP(i, 2 * off + 1)
        if(scc[i] == scc[i + ADD])
            return false;
    return true;
}

int main(){
    ios_base::sync_with_stdio(false); cin.tie(0);

    cin >> n;
    REP(i, n){
        cin >> X[i] >> Y[i];
        v.pb(point(X[i], i)); v.pb(point(Y[i], i));
    }
    sort(v.begin(), v.end());
    REP(i, n){
        iks[i] = lower_bound(v.begin(), v.end(), point(X[i], i)) - v.begin();
        ips[i] = lower_bound(v.begin(), v.end(), point(Y[i], i)) - v.begin();
    }

    int lo = 0, hi = 1e9;
    while(lo < hi){
        int mid = (lo + hi + 1) >> 1;
        if(check(mid))
            lo = mid;
        else
            hi = mid - 1;
    }
    cout << lo;
}

#include <bits/stdc++.h>
using namespace std;
#define N 300000
int lc[N], rc[N], lb[N], rb[N];
int tot;
vector <int> bi[N];
int intr[N], inS[N];
struct pI
{
    int a, b;
} S[N];
int compa(pI a, pI b) {return a.a < b.a;}

int build_tree(int l, int r)
{
    int t = ++ tot;
    lb[t] = l; rb[t] = r;
    if (l < r)  lc[t] = build_tree(l, (l + r) / 2),
                rc[t] = build_tree((l + r) / 2 + 1, r);
    else intr[S[l].b] = t;
    return t;
}
void put(int t, int l, int r, int d)
{
    if (l > r) return;
    if (l <= lb[t] && rb[t] <= r)
    {
        bi[d].push_back(t);
        return;
    }
    if (l <= rb[lc[t]]) put(lc[t], l, r, d);
    if (r >= lb[rc[t]]) put(rc[t], l, r, d);
}


int dfsnum, dfn[N], low[N], shed[N], inshed[N], top, cnt;
int ini[N];
void init()
{
    dfsnum = 0;
    for (int i = 1; i <= tot * 2; ++ i)
        dfn[i] = low[i] = shed[i] = inshed[i] = ini[i] = 0;
    top = cnt = 0;
}
void dfs(int t)
{
    dfn[t] = low[t] = ++ dfsnum; shed[++ top] = t; inshed[t] = 1;
    for (int i = 0; i < (int)bi[t].size(); ++ i)
        if (!dfn[bi[t][i]])
        {
            dfs(bi[t][i]);
            low[t] = min(low[bi[t][i]], low[t]);
        }
        else if (inshed[bi[t][i]])
            low[t] = min(dfn[bi[t][i]], low[t]);

    if (low[t] == dfn[t])
    {
        int p; cnt ++;
        do
        {
            p = shed[top --];
            inshed[p] = 0;
            ini[p] = cnt;
        }
        while (p != t);
    }
}

int n;
int ai[N];
int main()
{
    cin >> n;
    for (int i = 1; i <= n; ++ i)
        cin >> ai[i] >> ai[i + n];
    for (int i = 1; i <= n * 2; ++ i)
        S[i] = (pI){ai[i], i};

    sort(S + 1, S + n * 2 + 1, compa);
    for (int i = 1; i <= n * 2; ++ i) inS[S[i].b] = i;

    build_tree(1, n * 2);
    int l = 0, r = S[n * 2].a;
    while (l < r)
    {
        int md = (l + r + 1) / 2;

        for (int i = 1; i <= tot * 2; ++ i) bi[i].clear();
        for (int i = 1; i <= tot; ++ i)
        {
            if (lc[i] || rc[i])
                bi[i].push_back(lc[i]),
                bi[i].push_back(rc[i]);
        }

        for (int i = 1; i <= n * 2; ++ i)
        {
            int r = lower_bound(S + 1, S + n * 2 + 1, (pI){ai[i] + md, 0}, compa) - S - 1,
                l = upper_bound(S + 1, S + n * 2 + 1, (pI){ai[i] - md, 0}, compa) - S;

            put(1, l, inS[i] - 1, intr[i <= n? i + n: i - n]);
            put(1, inS[i] + 1, r, intr[i <= n? i + n: i - n]);
        }

        init();
        for (int i = 1; i <= tot * 2; ++ i)
            if (!ini[i]) dfs(i);
        int ok = 1;
        for (int i = 1; i <= n; ++ i)
            if (ini[intr[i]] == ini[intr[i + n]]) ok = 0;

        if (ok) l = md; else r = md - 1;
    }
    cout << l;
}

