const int N=1000000;
const int M=5000000;

struct node{
	int val,id;
	bool operator < (const node &B) const {return val<B.val;}
} A[N];

struct Edge{
	int y,nxt;
} E[M];
int x[N],y[N],las[N],__las[N],Id[N],dfn[N],low[N],stk[N],scc[N],val[N],pos[N];
int n,l,r,res,cnt,__cnt,num,tot,sccnum;
int Ql,Qr,Qx,Qv;

void Add_Edge(int x,int y){
	E[cnt]=(Edge){y,las[x]};las[x]=cnt++;
}
void Build(int x,int L,int R){
	Id[x]=++num;
	if (L==R){
		int y=A[L].id;
		if (y>n){
			Add_Edge(Id[x],y-n);
		} else{
			Add_Edge(Id[x],y+n);
		}
		return;
	}
	Build(Lsn,L,Mid);
	Build(Rsn,Mid+1,R);
	Add_Edge(Id[x],Id[Lsn]);
	Add_Edge(Id[x],Id[Rsn]);
}
void Query(int x,int L,int R){
	if (Ql<=L&&R<=Qr){
		Add_Edge(Qv,Id[x]);
		return;
	}
	if (Ql<=Mid) Query(Lsn,L,Mid);
	if (Qr>Mid) Query(Rsn,Mid+1,R);
}
void Work(int i,int l,int r){
	l=lower_bound(val+1,val+2*n+1,l)-val;
	r=upper_bound(val+1,val+2*n+1,r)-val-1;
	Ql=l,Qr=pos[i]-1,Qv=i;
	if (Ql<=Qr) Query(1,1,2*n);
	Ql=pos[i]+1,Qr=r,Qv=i;
	if (Ql<=Qr) Query(1,1,2*n);
}
void dfs(int x){
	dfn[x]=low[x]=++tot;
	stk[++*stk]=x;
	for (int i=las[x],y;~i;i=E[i].nxt)
		if (!dfn[y=E[i].y]){
			dfs(y);
			low[x]=min(low[x],low[y]);
		} else{
			if (!scc[y]) low[x]=min(low[x],dfn[y]);
		}
	if (low[x]==dfn[x]){
		int u;sccnum++;
		do{
			u=stk[(*stk)--];
			scc[u]=sccnum;
		} while (u!=x);
	}
}
bool check(int d){
	memcpy(las,__las,sizeof(__las));
	cnt=__cnt;
	For(i,1,n+1){
		Work(i,x[i]-d,x[i]+d);
		Work(i+n,y[i]-d,y[i]+d);
	}
	memset(dfn,0,sizeof(dfn));
	memset(scc,0,sizeof(scc));
	tot=0;sccnum=0;
	For(i,1,num+1){
		if (!dfn[i]) dfs(i);
	}
	For(i,1,n+1){
		if (scc[i]==scc[i+n]) return 0;
	}
	return 1;
}

int main(){
	memset(las,-1,sizeof(las));
	n=IN();
	For(i,1,n+1){
		x[i]=IN(),y[i]=IN();
		A[i]=(node){x[i],i};
		A[i+n]=(node){y[i],i+n};
	}
	sort(A+1,A+2*n+1);
	For(i,1,2*n+1){
		val[i]=A[i].val;
		pos[A[i].id]=i;
	}
	num=2*n;
	Build(1,1,2*n);
	memcpy(__las,las,sizeof(las));
	__cnt=cnt;
	l=-1,r=int(1e9);
	while (l<=r){
		int mid=(l+r>>1);
		if (check(mid)) res=mid,l=mid+1;else r=mid-1;
	}
	printf("%d\n",res+1);
}

