}
void insert(int u,int l,int r,int L,int R,int id)
{
	if(L>r || R<l) return;
	if(L<=l && r<=R)
	{
		add(id,tree[u]);
		return ;
	}
	int mid=(l+r)>>1;
	if(L<=mid) insert(u<<1,l,mid,L,R,id);
	if(R>mid) insert(u<<1|1,mid+1,r,L,R,id);
}
