void buildtree(int p,int l,int r){
	b[p].l=l; b[p].r=r;
	b[p].down=++nodecnt; g[nodecnt].clear();
	b[p].up=++nodecnt; g[nodecnt].clear();
	if(l==r){
		g[b[p].down].push_back(a[l].id2);
		g[a[l].id1].push_back(b[p].up);
	}else{
		int mid=l+r>>1;
		buildtree(p<<1,l,mid); buildtree(p<<1|1,mid+1,r);
		g[b[p].down].push_back(b[p<<1].down);
		g[b[p].down].push_back(b[p<<1|1].down);
		g[b[p<<1].up].push_back(b[p].up);
		g[b[p<<1|1].up].push_back(b[p].up);
	}
}
void addedge(int p,int l,int r,int ptoseg,int segtop){
	if(b[p].l==l&&b[p].r==r){
		g[ptoseg].push_back(b[p].down);
		g[b[p].up].push_back(segtop);
	}else{
		int mid=b[p].l+b[p].r>>1;
		if(r<=mid) addedge(p<<1,l,r,ptoseg,segtop);
		else if(l>mid) addedge(p<<1|1,l,r,ptoseg,segtop);
		else{
			addedge(p<<1,l,mid,ptoseg,segtop);
			addedge(p<<1|1,mid+1,r,ptoseg,segtop);
		}
	}
}
