void dfs(int x){
	dfn[x]=low[x]=++dfscnt; stk.push(x);
	for(int i=0;i<g[x].size();++i){
		int e=g[x][i];
		if(!dfn[e]){
			dfs(e); low[x]=min(low[x],low[e]);
		}else if(!scc[e]) low[x]=min(low[x],dfn[e]);
	}
	if(dfn[x]==low[x]){
		++scccnt;
		for(;;){
			int t=stk.top(); stk.pop();
			scc[t]=scccnt; if(t==x) break;
		}
	}
}
bool check(int v){
	for(int i=1;i<=n<<1;++i) g[i].clear(); nodecnt=n<<1;
