			r=lower_bound(dis+1,dis+(n<<1)+1,a[i].pos+v)-dis-1;
		if(l<i) addedge(1,l,i-1,a[i].id1,a[i].id2);
		if(i<r) addedge(1,i+1,r,a[i].id1,a[i].id2);
	}
	for(int i=1;i<=nodecnt;++i) dfn[i]=scc[i]=0;
	dfscnt=scccnt=0;
	for(int i=1;i<=nodecnt;++i) if(!dfn[i]) dfs(i);
	for(int i=1;i<=n;++i) if(scc[i<<1]==scc[(i<<1)-1]) return 0;
	return 1;
}
