int n;
vi a;

bool f(int x) {
  int m = n*2;
  X xs;
  rep(i,m) xs.add(a[i]);
  rep(i,m) xs.add(a[i]-x+1);
  rep(i,m) xs.add(a[i]+x);
  xs.init();
  seg d(sz(xs)+3);
  rep(i,m) {
    d.add(xs[a[i]],i^1);
  }
  d.fil();
  seg pd = d;
  vi vs;
  {
    used = vi(m);
    q = vi();
    rep(i,m) if (!used[i]) {
      q.pb(i);
      while (sz(q)) {
        int v = q.back(); q.pop_back();
        if (v >= m) {
          vs.pb(v-m);
          continue;
        }
        if (used[v]) continue;
        used[v] = 1;
        q.pb(m+v);
        d.get(xs[a[v]-x+1],xs[a[v]+x],v>>1);
      }
      // cout<<vs<<endl;
    }
  }
  {
    used = vi(m);
    q = vi();
    int ui = 1;
    for (int i : vs) if (!used[i]) {
      q.pb(i);
      while (sz(q)) {
        int v = q.back(); q.pop_back();
        if (used[v]) continue;
        used[v] = ui;
        pd.get(xs[a[v]-x+1],xs[a[v]+x],v>>1);
      }
      ++ui;
    }
    // cout<<used<<endl;
  }
  rep(i,m) if (used[i] == used[i^1]) return false;
  return true;
}

