    vector<int> idx(N),idy(N);
    iota(all(idx),0); iota(all(idy),0);
    sort(all(idx),[&](int i, int j){return x[i] < x[j];});
    sort(all(idy),[&](int i, int j){return y[i] < y[j];});
    sort(all(x)); sort(all(y));
    vector<int> invx(N),invy(N);
    rep(i,N) {
        invx[idx[i]] = i;
        invy[idy[i]] = i;
    }

    auto check=[&](int mid) {
        RangeEdge<int> RE(2*N);
        rep(i,N) {
            //x[i],x[j]
            int l = upper_bound(all(x),x[i]-mid) - x.begin();
            int r = lower_bound(all(x),x[i]+mid) - x.begin();
            RE.addedge(l,i,N+invy[idx[i]],N+invy[idx[i]]+1,1);
            RE.addedge(i+1,r,N+invy[idx[i]],N+invy[idx[i]]+1,1);

            //x[i],y[j]
            l = upper_bound(all(y),x[i]-mid) - y.begin();
            r = lower_bound(all(y),x[i]+mid) - y.begin();
            RE.addedge(N+l,N+r,N+invy[idx[i]],N+invy[idx[i]]+1,1);

            //y[i],x[j]
            r = lower_bound(all(x),y[i]+mid) - x.begin();
            l = upper_bound(all(x),y[i]-mid) - x.begin();
            RE.addedge(l,r,invx[idy[i]],invx[idy[i]]+1,1);

            //y[i],y[j]
            l = upper_bound(all(y),y[i]-mid) - y.begin();
            r = lower_bound(all(y),y[i]+mid) - y.begin();
            RE.addedge(N+l,N+i,invx[idy[i]],invx[idy[i]]+1,1);
            RE.addedge(N+i+1,N+r,invx[idy[i]],invx[idy[i]]+1,1);
        }

        int M = RE.G.size();
        scc_graph scc(M);
        rep(i,M) {
            for (auto &e : RE.G[i]) {
                scc.add_edge(i,e.to);
            }
        }
        auto G = scc.scc();

        vector<int> pos(M);
        rep(i,SZ(G)) {
            for (auto j : G[i]) pos[j] = i;
        }
        rep(i,N) {
            int u = invx[i];
            int v = invy[i]+N;
            if (pos[u]==pos[v]) return false;
        }
        return true;
    };

    int ok = 0;
    int ng = 1e9;
    while (abs(ok-ng)>1) {
        int mid = (ok+ng)/2;
        if (check(mid)) ok = mid;
        else ng = mid;
    }

    cout << ok << ln;
}

