    auto is_x = [&](int i) { return   i+1; };
    auto is_y = [&](int i) { return -(i+1); };
    vector<int> ps;
    repeat (i,n) {
        ps.push_back(is_x(i));
        ps.push_back(is_y(i));
    }
    auto dist = [&](int p) { return p > 0 ? x[p-1] : y[-p-1]; };
    whole (sort, ps, [&](int p, int q) { return dist(p) < dist(q); });
    vector<pair<int, int> > cnf;
    auto pred = [&](int limit) {
        cnf.clear();
        int l = 0;
        repeat (r,2*n) {
            while (dist(ps[l]) + limit <= dist(ps[r])) ++ l;
            repeat_from (i,l,r) {
                if (i == - r) return false;
                cnf.emplace_back(- ps[r], - ps[i]);
                cnf.emplace_back(- ps[i], - ps[r]);
            }
        }
        return twosat(n, cnf);
    };
    int l = 0, r = 1e9+7;
    repeat (i,n) {
        repeat (j,n) if (i != j) {
            int acc = 0;
            setmax(acc, abs(x[i] - x[j]));
            setmax(acc, abs(x[i] - y[j]));
            setmax(acc, abs(y[i] - x[j]));
            setmax(acc, abs(y[i] - y[j]));
            setmin(r, acc+1);
        }
    }
    while (l + 1 < r) {
        int m = (l + r) / 2;
        (pred(m) ? l : r) = m;
    }
    printf("%d\n", l);
    return 0;
}

