int n, x[2][N], s[N], d;
P xx[2][N];

int bfs(int p0){
	queue<int> q;
	q.push(p0);
	int cnt = 0;
	while(!q.empty()){
		int p = q.front(); q.pop();
		int t = x[s[p]][p];
		rep(i, 2){
			P *l = lower_bound(xx[i], xx[i]+n, P(t-d+1, 0));
			P *r = upper_bound(xx[i], xx[i]+n, P(t+d-1, n));
			//cerr<<(r-l)<<endl;
			while(l<r){
				if(l->snd!=p){
					if(s[l->snd]==i) return -1;
					if(s[l->snd]==-1){
						s[l->snd] = !i;
						cnt++;
						q.push(l->snd);
					}
				}
				l++;
			}
		}
	}
	//cerr<<d<<" "<<p0<<" "<<cnt<<endl;
	return cnt;
}

bool dfs(int p){
	while(p<n && s[p]>=0) p++;
	if(p>=n) return true;
	int s2[N];
	memcpy(s2, s, sizeof(s));
	s[p] = 0;
	int cnt = bfs(p);
	if(cnt==0) return dfs(p+1);
	if(cnt>0 && dfs(p+1)) return true;
	memcpy(s, s2, sizeof(s));
	s[p] = 1;
	if(bfs(p)>=0) return dfs(p+1);
	memcpy(s, s2, sizeof(s));
	s[p] = -1;
	return false;
}

bool solve(){
	mset(s, -1);
	return dfs(0);
}

