  rep(i,n*2) scanf("%d",&a[i]);
  // cout<<f(1)<<endl; return 0;
  int l = 0, r = INF;
  while (l+1<r) {
    int c = (l+r)>>1;
    if (f(c)) l = c; else r = c;
  }
  cout<<l<<endl;
  return 0;
}

