        e[i + n].opt = -1; //y
        e[i].id = e[i + n].id = i; //记录各自的编号
    }
    sort(e + 1,e + 1 + 2 * n,cmp);  //按照坐标排序
    for (int i = 1; i <= 2 * n; i++)
    {
        int temp = e[i].id;
        if (e[i].opt == 1)
            temp += n;
        weizhi[temp] = i;
    }
    int l = 0,r = 1e9;
    while (l <= r)
    {
        int mid = (l + r) >> 1;
        if (check(mid))
        {
            ans = mid;
            l = mid + 1;
        }
        else
            r = mid - 1;
    }
    printf("%d\n",ans);

    return 0;
}

