namespace SCC {
  int totscc;
  int sccid[MAXN];
  int dfn[MAXN];
  int low[MAXN];

  int top;
  int st[MAXN];

  int dfc;

  void dfs(int u) {
    int e, v;
    dfn[u] = low[u] = dfc++;
    st[top++] = u;
    for (e=head[u]; ~e; e=E[e].next) {
      v = E[e].v;
      if (!~dfn[v]) {
	dfs(v);
	chkmin(low[u], low[v]);
      } else if (!~sccid[v])
	chkmin(low[u], dfn[v]);
    }
    if (low[u] == dfn[u]) {
      while (true) {
	sccid[st[top-1]] = totscc;
	--top;
	if (st[top] == u)
	  break;
      }
      ++ totscc;
    }
  }

  void exec() {
    int i;
    totscc = dfc = 0;
    memset(sccid, -1, sizeof sccid);
    memset(dfn, -1, sizeof dfn);
    for (i=0; i<MAXN; ++i)
      if (!~dfn[i])
