  for (i=0; i<tot; ++i) c[i] = a[i].X;
  for (i=0; i<n; ++i) {
    id[i][0] = std::lower_bound(a, a+tot, MK(in[i].X, i)) - a;
    id[i][1] = std::lower_bound(a, a+tot, MK(in[i].Y, i)) - a;    
  }

  l = 0, r = 1e9 + 1;

  while (l+1 < r)
    (check(MID)? l : r) = MID;

  printf("%d\n", l);
}

