const int MAXN = 300011;
const int INF = 1000000001;


struct segment
{   
    int a, b;
};


int lc[MAXN], rc[MAXN], lb[MAXN], rb[MAXN];
int tot;
vector<int> b[MAXN];
int intr[MAXN], ins[MAXN];
segment s[MAXN];


bool comp(segment a, segment b) {
    return a.a < b.a;
}


int build(int l, int r) {
    int t = ++ tot;
    lb[t] = l; rb[t] = r;
    if (l < r)  {
        lc[t] = build(l, (l + r) / 2);
        rc[t] = build((l + r) / 2 + 1, r);
    } else {
        intr[s[l].b] = t;
    }
    return t;
}


void rmq(int t, int l, int r, int d) {
    if (l > r) {
        return;
    }
    if (l <= lb[t] && rb[t] <= r) {
        b[d].push_back(t);
        return;
    }
    if (l <= rb[lc[t]]) {
        rmq(lc[t], l, r, d);
    }
    if (r >= lb[rc[t]]) {
        rmq(rc[t], l, r, d);
    }
}


int uk, used[MAXN], low[MAXN], shed[MAXN], inshed[MAXN], top, cnt;
int ini[MAXN];



void init() {
    uk = 0;
    for (int i = 1; i <= tot * 2; i++) {
        used[i] = low[i] = shed[i] = inshed[i] = ini[i] = 0;
    }
    top = cnt = 0;
}


void dfs(int t) {
    used[t] = low[t] = ++uk; 
    shed[++top] = t; 
    inshed[t] = 1;
    for (int i = 0; i < (int)b[t].size(); i++)
        if (!used[b[t][i]]) {
            dfs(b[t][i]);
            low[t] = min(low[b[t][i]], low[t]);
        } else if (inshed[b[t][i]]) {
            low[t] = min(used[b[t][i]], low[t]);
        }

    if (low[t] == used[t]) {
        int p; 
        cnt++;
        do {
            p = shed[top--];
            inshed[p] = 0;
            ini[p] = cnt;
        }
        while (p != t);
    }
}


int n;
int a[MAXN];


int main() {
    n = readInt();
    for (int i = 1; i <= n; i++) {
        a[i] = readInt(), a[i + n] = readInt();
    }
    for (int i = 1; i <= n * 2; i++) {
        s[i] = (segment){a[i], i};
    }
    sort(s + 1, s + n * 2 + 1, comp);
    for (int i = 1; i <= n * 2; i++) {
        ins[s[i].b] = i;
    }
    build(1, n * 2);
    int l = 0, r = s[n * 2].a;
    while (l < r) {
        int mid = (l + r + 1) >> 1;
        for (int i = 1; i <= tot * 2; i++) {
            b[i].clear();
        }
        for (int i = 1; i <= tot; i++) {
            if (lc[i] || rc[i]) {
                b[i].push_back(lc[i]),
                b[i].push_back(rc[i]);
            }
        }
        for (int i = 1; i <= n * 2; i++) {
            int r = lower_bound(s + 1, s + n * 2 + 1, (segment){a[i] + mid, 0}, comp) - s - 1,
                l = upper_bound(s + 1, s + n * 2 + 1, (segment){a[i] - mid, 0}, comp) - s;
            rmq(1, l, ins[i] - 1, intr[i <= n? i + n: i - n]);
            rmq(1, ins[i] + 1, r, intr[i <= n? i + n: i - n]);
        }
        init();
        for (int i = 1; i <= tot * 2; i++) {
            if (!ini[i]) {
                dfs(i);
            }
        }
        bool good = 1;
        for (int i = 1; i <= n; i++) {
            if (ini[intr[i]] == ini[intr[i + n]]) {
                good = 0;
                break;
            }
        }
        if (good) {
            l = mid;
        } else {
            r = mid - 1;
        }
    }
    writeInt(l, '\n');
    return 0;
}

