		a.push_back(ii(x, y));
		b.push_back(ii(x, i));
		b.push_back(ii(y, i));
	}
	//initialize
	sort(b.begin(), b.end());
	tree_pos.build(1, 1, SZ(b));
	tree_neg.build(1, 1, SZ(b));
	id_pos.resize(SZ(b) + 1);
	id_neg.resize(SZ(b) + 1);
	for (int i = 1; i <= SZ(b); ++i) {
		id_pos[i] = tree_pos.get_id(1, 1, SZ(b), i);
		id_neg[i] = tree_neg.get_id(1, 1, SZ(b), i);
	}
	for (int i = 0; i < n; ++i) {
		int posx = lower_bound(b.begin(), b.end(), ii(a[i].first, i)) - b.begin() + 1;
		int posy = lower_bound(b.begin(), b.end(), ii(a[i].second, i)) - b.begin() + 1;
		g2[id_neg[posx]].push_back(id_pos[posy]);
		g2[id_neg[posy]].push_back(id_pos[posx]);
		g2[id_pos[posx]].push_back(id_neg[posy]);
		g2[id_pos[posy]].push_back(id_neg[posx]);
	}
	int lo = 1, hi = (int)1e9, ans = 0, mid;
#ifdef debug
	int val = (int)1e9;
	hi = val;
#endif
	while (lo <= hi) {
		mid = (lo + hi) >> 1;
		if (check(mid)) {
			ans = mid, lo = mid + 1;
		} else {
			hi = mid - 1;
		}
	}
	printf("%d", ans);
	return 0;
}

