 // freopen("a.in", "r", stdin);
 // freopen("a.out", "w", stdout);
  ios :: sync_with_stdio(0);
  cin.tie(0), cout.tie(0);
  cin >> n; _2n = n + n;
  Get_MaxNode(1, 1, _2n);
  for (RI i = 1; i <= n; ++i)
    cin >> t[i * 2 - 1].x >> t[i * 2].x, t[i * 2 - 1].id = t[i * 2].id = i;
  sort(t + 1, t + 1 + _2n, cmp);
  for (RI i = 1; i <= _2n; ++i) {
    if (!a[t[i].id].x) a[t[i].id].x = i;
    else a[t[i].id].y = i;
  }
  int l = 1, r = 1e9, mid, ans = 0;
  while (l <= r) {
    mid = (l + r) >> 1;
    if (Check(mid)) ans = mid, l = mid + 1;
    else r = mid - 1;
  }
  cout << ans << endl;
  return 0;
}

