double gr()
{
    int x = rand() + 1;
    int y = rand() + 1;
    x %= y;
    return x / (double) y;
}

int get(const vector <int> &t)
{
    vector <int> e;
    for (int i = 0; i < (int) t.size(); i++)
    {
        e.push_back(t[i] ? x[i] : y[i]);
    }
    sort(e.begin(), e.end());
    int res = 1e9;
    for (int i = 1; i < (int) e.size(); i++)
    {
        res = min(res, e[i] - e[i - 1]);
    }
    return res;
}


