using namespace std;

const int MAXN = 20001;
int dn;
vector<pair<int, int>> graph[MAXN];
int up[MAXN], visit[MAXN], vtime;
vector<int> stk;
int scc_idx[MAXN], scc_cnt;
int lowerlimit;

void dfs(int nod) {
	up[nod] = visit[nod] = ++vtime;
	stk.push_back(nod);
	for (auto& e : graph[nod]) {
		if (e.second >= lowerlimit) continue;
		int next = e.first;
		if (visit[next] == 0) {
			dfs(next);
			up[nod] = min(up[nod], up[next]);
		}
		else if (scc_idx[next] == 0)
			up[nod] = min(up[nod], visit[next]);
	}
	if (up[nod] == visit[nod]) {
		++scc_cnt;
		int t;
		do {
			t = stk.back();
			stk.pop_back();
			scc_idx[t] = scc_cnt;
		} while (!stk.empty() && t != nod);
	}
}
// find SCCs in given directed graph
// O(V+E)
void get_scc() {
	vtime = 0;
	memset(visit, 0, sizeof(visit));
	scc_cnt = 0;
	memset(scc_idx, 0, sizeof(scc_idx));
	for (int i = 0; i < dn; ++i)
		if (visit[i] == 0) dfs(i);
}

int n;
int coord[10000][2];

bool chk() {
	get_scc();
	for (int i = 0; i < n; ++i) {
		if (scc_idx[i * 2] == scc_idx[i * 2 + 1]) {
			return false;
		}
	}
	return true;
}

void proc() {
	scanf("%d", &n);
	int mn = 1000000005, mx = -1;
	for (int i = 0; i < n; ++i) {
		scanf("%d %d", &coord[i][0], &coord[i][1]);
		mn = min(mn, coord[i][0]);
		mn = min(mn, coord[i][1]);
		mx = max(mx, coord[i][0]);
		mx = max(mx, coord[i][1]);
	}

	int left = 1000000000, right = 1000000000;

	dn = n * 2;
	for (int i = 0; i < n; ++i) {
		for (int j = i + 1; j < n; ++j) {
			int dfmn = 1000000009, dfmx = -1;

			for (int a = 0; a < 2; ++a) {
				for (int b = 0; b < 2; ++b) {
					int v = abs(coord[i][a] - coord[j][b]);
					dfmn = min(dfmn, v);
					dfmx = max(dfmx, v);
					//// v < lowerlimit 일 때만 유효한 간선
					int nodei = i * 2 + a, nodej = j * 2 + b;
					//// nodei -> !nodej , nodej -> !nodei
					graph[nodei].push_back({ nodej ^ 1, v });
					graph[nodej].push_back({ nodei ^ 1, v });
				}
			}

			right = min(right, dfmx);
			left = min(left, dfmn);
		}
	}

	while (left <= right) {
		int mid = ((long long)left + right) / 2;
		lowerlimit = mid;
		if (chk()) {
			left = mid + 1;
		}
		else {
			right = mid - 1;
		}
	}
	printf("%d", right);
}

int main() {
	//freopen("input.txt", "r", stdin);
	proc();
	return 0;
}

