    rnk[id[i]] = i;
    tab[i] = x[id[i]];
  }
  int l = 0, r = 1e9, mid, ans = -1;
  while (l <= r) {
    mid = (l + r) >> 1;
    if (check(mid)) {
      ans = mid;
      l = mid + 1;
    }
    else r = mid - 1;
  }
  printf("%d\n", ans + 1);
  return 0;
}

