    scanf("%d",&n);
    for(i=1;i<=n;i++){
        scanf("%d%d",&A[i],&B[i]);
        X[i]=A[i],X[n+i]=B[i];
    }
    while(b<=e){
        mid = (b+e)>>1;
        if(Pos()){
            b = mid + 1;
            res = mid;
        }
        else e = mid -1;
    }
