	E[Ecnt].y=a;E[Ecnt].next=V[b].FE;V[b].FE=Ecnt;
	E[Ecnt].i=true;
}

int Dfn[MAXV], DFN;

void DFS(int at){
	V[at].Vis=true;
	for(int k=V[at].FE, to;k;k=E[k].next){
		if(E[k].i)	continue;
		to=E[k].y;
		if(V[to].Vis)	continue;
		DFS(to);
	}
	Dfn[++DFN]=at;
}

void DFS(int at, int b){
	V[at].Vis=true;
	for(int k=V[at].FE, to;k;k=E[k].next){
		if(!E[k].i)	continue;
		to=E[k].y;
		if(V[to].Vis)	continue;
		DFS(to, b);
	}
	V[at].Bel=b;
}

int Bcnt;

void SCC(){
	#define n Vcnt
	DFN=0;Bcnt=0;
	for(int i=1;i<=n;++i)	V[i].Vis=false;
	for(int i=1;i<=n;++i)	if(!V[i].Vis)	DFS(i);
	for(int i=1;i<=n;++i)	V[i].Vis=false;
	for(int i=n;i>=1;--i)	if(!V[Dfn[i]].Vis)	DFS(Dfn[i], ++Bcnt);
	#undef n
}

