struct Pair{
	int p, v;
	Pair(){}
	Pair(int _p, int _v){p=_p;v=_v;}
};

inline bool operator < (const Pair &A, const Pair &B){
	return (A.v==B.v)?(A.p<B.p):A.v<B.v;
}

struct Node{
	int l, r;
	int pos;
};

struct Tree{
	Pair Pa[MAXN];
	Node T[MAXN<<2];
	void Build(int at, int l, int r){
		T[at].l=l;T[at].r=r;T[at].pos=++Vcnt;
		int m=(l+r)>>1;
		if(l==r){
			addE(T[at].pos, Pa[m].p);
			return;
		}
		Build(at<<1, l, m);
		addE(T[at].pos, T[at<<1].pos);
		Build((at<<1)|1, m+1, r);
		addE(T[at].pos, T[(at<<1)|1].pos);
	}
	int Pos;
	int L, R;
	int Findl(Pair v){
		if(!(v<Pa[N]))	return N+1;
		int l=1, r=N, m;
		while(l<r){
			m=(l+r)>>1;
			if(v<Pa[m])	r=m;
			else	l=m+1;
		}
		m=(l+r)>>1;
		return m;
	}
	int Findr(Pair v){
		if(!(Pa[1]<v))	return 0;
		int l=1, r=N, m;
		while(l<r){
			m=(l+r)>>1;
			if(Pa[m+1]<v)	l=m+1;
			else	r=m;
		}
		m=(l+r)>>1;
		return m;
	}
	bool Get(Pair vl, Pair vr){
		L=Findl(vl);
		R=Findr(vr);
		return L<=R;
	}
	void Link(int at){
		if(T[at].l>=L && T[at].r<=R){
			addE(Pos, T[at].pos);
			return;
		}
		int m=(T[at].l+T[at].r)>>1;
		if(L<=m)	Link(at<<1);
		if(R>m)	Link((at<<1)|1);
	}
} Tr[2];

void Clear(){
	for(int i=1;i<=Vcnt;++i)	V[i].FE=0;
	Vcnt=0;Ecnt=0;

}

bool Try(int k){

	Clear();

	for(int i=1;i<=N;++i){
		Pos[0][i]=++Vcnt;
		Pos[1][i]=++Vcnt;
	}

	for(int i=0;i<2;++i){
		for(int j=1;j<=N;++j){
			Tr[i].Pa[j]=Pair(Pos[!i][j], Val[i][j]);
		}
		sort(Tr[i].Pa+1, Tr[i].Pa+N+1);
		Tr[i].Build(1, 1, N);
	}

	for(int i=0;i<2;++i){
		for(int j=1;j<=N;++j){
			if(Tr[!i].Get(Pair(Vcnt+1, Val[i][j]-k), Pair(0, Val[i][j]+k))){
				Tr[!i].Pos=Pos[i][j];
				Tr[!i].Link(1);
			}
			if(Tr[i].Get(Pair(Vcnt+1, Val[i][j]-k), Pair(Pos[!i][j], Val[i][j]))){
				Tr[i].Pos=Pos[i][j];
				Tr[i].Link(1);
			}
			if(Tr[i].Get(Pair(Pos[!i][j], Val[i][j]), Pair(0, Val[i][j]+k))){
				Tr[i].Pos=Pos[i][j];
				Tr[i].Link(1);
			}
		}
	}

	SCC();
	return Test();

}

