	  P p=q.front();q.pop();
	  ll u=p.first,v=p.second;
	  //cout<<u<<" "<<v<<endl;
	  if(visit[!u][v]){
	    fff=0;
	    break;
	  }
	  for(ll j=0;j<n;j++){
	    if(v==j) continue;
	    for(ll y=0;y<2;y++){
	      //cout<<abs(x[y][j]-x[u][v])<<" "<<m<<endl;
	      if(abs(x[y][j]-x[u][v])<m){
		if(!visit[!y][j]){
		  if(visit[y][j]){
		    fff=0;
		    break;
		  }
		  visit[!y][j]=1;
		  q.push(P(!y,j));
		}
	      }
	    }
	    if(!fff) break;
	  }
	  if(!fff) break;
	}
	if(fff){
	  ff=1;
	  for(ll j=0;j<n;j++) used[j]|=visit[0][j]||visit[1][j];
	  break;
	}
      }
      f&=ff;
    }
    //cout<<m<<endl;
    if(f) l=m;
    else r=m;
  }
  cout<<l<<endl;
  return 0;
}

