class SAT {
private:
    void _dfs(int u){
		used[u] = true;
		for(int v : G[u]){
			if(!used[v]){
				_dfs(v);
			}
		}
		post_order.push_back(u);
	}
    void _rdfs(int u,int k){
		used[u] = true;
		cmp[u] = k;
		for(int v : rG[u]){
			if(!used[v]){
				_rdfs(v,k);
			}
		}
	}
    int _scc(){
        fill(used.begin(),used.end(),false);
        post_order.clear();
        for(int i = 0; i < 2 * V; i++){
            if(!used[i]){
                _dfs(i);
            }
        }
        fill(used.begin(),used.end(),false);
        int k = 0;
        for(int i = 2*V - 1; i >= 0; i--){
            if(!used[post_order[i]]){
                _rdfs(post_order[i],k++);
            }
        }
        return k;
    }

public:
	int V;	//頂点数
	vector<vector<int> > G,rG;
	vector<int> post_order; //帰りがけ順の並び
	vector<bool> used; //すでに調べたかどうか
	vector<int> cmp;	//属する強連結成分のトポロジカル順序

	SAT(int node_size) : V(node_size), G(2*V), rG(2*V), used(2*V), cmp(2*V){}
	inline void _add_edge(int from, int to){
		G[from].push_back(to), rG[to].push_back(from);
	}
    inline void add_edge(int from, int to){
		_add_edge(from, to), _add_edge((to+V)%(2*V),(from+V)%(2*V));
	}
	//充足可能性判定
	bool ok(){
	    _scc();
	    for(int i = 0; i < V; i++){
	        if(cmp[i] == cmp[V+i]){
	            return false;
	        }
	    }
	    return true;
	}
	//真のものは1,偽のものは0を返す(解の構成)
	void restore(vector<int>& ans){
		ans.resize(V);
	    for(int i = 0; i < V; i++){
			ans[i] = (cmp[i] > cmp[V+i]);
	    }
	}
};

int n, N, V;
vector<P> vec, num;

inline void query(const int id, int a, int b, SAT& st, int k = 0, int l = 0, int r = -1){
    if(r < 0) r = N;
    if(r <= a || b <= l){
        return;
    }
    if(a <= l && r <= b){
        st.add_edge(id, k+V);
        return;
    }else{
        query(id,a,b,st,2*k+1,l,(l+r)/2), query(id,a,b,st,2*k+2,(l+r)/2,r);
    }
}

bool possible(int d)
{
    SAT st(V);
    rep(i,n){
		st.add_edge(num[i].fi+N-1+V, num[i].se+N-1);
    }
    for(int i=N-2; i>=0; i--){
		st.add_edge(2*i+1, i), st.add_edge(2*i+2, i);
    }
    rep(i,2*n){
        int s = lower_bound(all(vec),P(vec[i].fi-d+1,-1)) - vec.begin();
        if(s < i) query(i+N-1, s, i, st);
        int e = upper_bound(all(vec),P(vec[i].fi+d-1,INF)) - vec.begin();
        if(i+1 < e) query(i+N-1, i+1, e, st);
    }
    return st.ok();
}

