long long N, X[1 << 18], Y[1 << 18]; pair<long long, int> A[1 << 18];

bool flag1 = false, flag2 = false, used[1 << 18];
int col[1 << 18], cnts;
vector<int> G[1 << 18], H[1 << 18], I;

void build_edge(int u, int v) {
	int sub_u = u + N * 2; if (u >= N * 2) sub_u = u - N * 2;
	int sub_v = v + N * 2; if (v >= N * 2) sub_v = v - N * 2;
	G[sub_u].push_back(v);
	G[sub_v].push_back(u);
}

void dfs1(int pos) {
	used[pos] = true;
	for (int i : G[pos]) {
		if (used[i] == false) dfs1(i);
	}
	I.push_back(pos);
}

void dfs2(int pos) {
	col[pos] = cnts;
	for (int i : H[pos]) {
		if (col[i] == 0) dfs2(i);
	}
}

bool solve(int D) {
	// ---------------------- 初期化 -------------------------
	for (int i = 0; i < N * 4; i++) { G[i].clear(); H[i].clear(); used[i] = false; col[i] = 0; }
	I.clear(); cnts = 0;

	// --------------------- 辺を張る ------------------------
	for (int i = 0; i < N; i++) {
		build_edge(X[i], Y[i]);
		build_edge(X[i] + N * 2, Y[i] + N * 2);
	}
	for (int i = 0; i < 2 * N; i++) {
		int pos1 = lower_bound(A, A + N * 2, make_pair(A[i].first - D + 1, -1000000)) - A;
		int pos2 = lower_bound(A, A + N * 2, make_pair(A[i].first + D - 1, 1000000)) - A;
		for (int j = pos1; j < i; j++) {
			build_edge(j + N * 2, i + N * 2);
		}
	}

	// ------------------- SAT を求める --------------------
	for (int i = 0; i < N * 4; i++) {
		for (int j : G[i]) H[j].push_back(i);
	}
	for (int i = 0; i < N * 4; i++) {
		if (used[i] == true) continue;
		dfs1(i);
	}
	reverse(I.begin(), I.end());
	for (int i : I) {
		if (col[i] >= 1) continue;
		cnts++; dfs2(i);
	}

	// ------------------- 最終チェック --------------------
	for (int i = 0; i < N * 2; i++) {
		if (col[i] == col[i + N * 2]) return false;
	}
	return true;
}

int main() {
