	}
	sort(A, A + N * 2);
	for (int i = 0; i < N * 2; i++) {
		X[i] = lower_bound(A, A + N * 2, make_pair(X[i], i)) - A;
		Y[i] = lower_bound(A, A + N * 2, make_pair(Y[i], i)) - A;
	}

	int cl = 0, cr = 1000000009, cm, maxn = -1;
	for (int i = 1; i <= 35; i++) {
		cm = (cl + cr) / 2; //cm = 4;
		if (solve(cm) == true) { maxn = max(maxn, cm); cl = cm; }
		else { cr = cm; }
	}
	cout << maxn << endl;
	return 0;
}

