void forward(int index, int d) {
	vis[index] = 1;
	int x = v[vind[index]].first;
	for (int i = vind[index]-1; i >= 0; i--) {
		if (x-v[i].first >= d)
			break;
		int neigh = v[i].second + (v[i].second > n ? -n : n);
		if (!vis[neigh]) {
			//cout<<index<<" "<<neigh<<" "<<v[i].second<<endl;
			forward(neigh, d);
		}
	}	

	for (int i = vind[index]+1; i < v.size(); i++) {
		if (v[i].first-x >= d)
			break;
		int neigh = v[i].second + (v[i].second > n ? -n : n);
		if (!vis[neigh]) {
			//cout<<index<<" "<<neigh<<" "<<v[i].second<<endl;
			forward(neigh, d);
		}
	}	

	s.push(index);
}

void backward(int index, int d, int c) {
	comp[index] = c;
	index += (index > n ? -n : n);
	int x = v[vind[index]].first;
	for (int i = vind[index]-1; i >= 0; i--) {
		if (x-v[i].first >= d)
			break;
		int neigh = v[i].second;
		if (comp[neigh] == 0)
			backward(neigh, d, c);
	}

	for (int i = vind[index]+1; i < v.size(); i++) {
		if (v[i].first-x >= d)
			break;
		int neigh = v[i].second;
		if (comp[neigh] == 0)
			backward(neigh, d, c);
	}
}

void tarjan(int index, int d) {
	minout[index] = cnt;
	cntind[index] = cnt++;
	vis[index] = 1;
	s.push(index);
	onstack[index] = 1;
	int x = v[vind[index]].first;

	for (int i = vind[index]-1; i >= 0; i--) {
		if (x-v[i].first >= d)
			break;
		int neigh = v[i].second + (v[i].second > n ? -n : n);
		if (!vis[neigh]) {
			//cout<<index<<" "<<neigh<<" "<<v[i].second<<endl;
			tarjan(neigh, d);
			minout[index] = min(minout[index], minout[neigh]);
		} else if (onstack[neigh]) {
			minout[index] = min(minout[index], cntind[neigh]);
		}
	}	

	for (int i = vind[index]+1; i < v.size(); i++) {
		if (v[i].first-x >= d)
			break;
		int neigh = v[i].second + (v[i].second > n ? -n : n);
		if (!vis[neigh]) {
			//cout<<index<<" "<<neigh<<" "<<v[i].second<<endl;
			tarjan(neigh, d);
			minout[index] = min(minout[index], minout[neigh]);
		} else if (onstack[neigh]) {
			minout[index] = min(minout[index], cntind[neigh]);
		}
	}	

	if (minout[index] == cntind[index]) {
		while (!s.empty()) {
			int curr = s.top(); s.pop();
			onstack[curr] = 0;
			comp[curr] = cnum;
			if (curr == index) break;
		}
		cnum++;
	}
}

bool solve(int d) {
	cnum = 1;
	cnt = 1;

	for (int i = 1; i <= 2*n; i++) {
		if (!vis[i]) {
			tarjan(i, d);
			while (!s.empty()) {
				int curr = s.top(); s.pop();
				comp[curr] = cnum;
				onstack[curr] = 0;
			}
			cnum++;
		}
	}

	bool ok = true;
	for (int i = 1; i <= n; i++) {
		//cout<<i<<" "<<(i+n)<<" "<<comp[i]<<" "<<comp[i+n]<<endl;
		if (comp[i] == comp[i+n])
			ok = false;
		vis[i] = 0;
		vis[i+n] = 0;
		//comp[i] = 0;
		//comp[i+n] = 0;
		//minout[i] = minout[i+n] = 0;
	}

	return ok;
}

