void bt(int l, int r, int p){
	int mid = (l+r)/2;
	if(l == mid) e_base[p].pb(lp[p] = arr[l].second ^ 1);
	else lp[p] = ++V, e_base[p].pb(V), bt(l, mid, V);
	if(mid+1 == r) e_base[p].pb(rp[p] = arr[r].second ^ 1);
	else rp[p] = ++V, e_base[p].pb(V), bt(mid+1, r, V);
}

void build(){
