}

int isang(int x){ return lower_bound(arr+1, arr+2*n+1, pp{x, -1}) - arr; }
int iha(int x){ return lower_bound(arr+1, arr+2*n+1, pp{x+1, -1}) - arr - 1; }

void draw(int l, int r, int from, int ml, int mr, int mp){
	if(l<=ml && mr<=r){
		e_temp[from].pb(mp);
		return;
	} else if(r<ml || mr<l) return;
	int mid=(ml+mr)/2;
	draw(l, r, from, ml, mid, lp[mp]);
	draw(l, r, from, mid+1, mr, rp[mp]);
}

int ind[65536];
int low[65536];
bool onstk[65536];
int stk[65536];
int cind[65536], cn;
int top;
int nt;

void dfs(int x){
	ind[x] = low[x] = ++nt;
	onstk[x]=1; stk[top++]=x;
	auto f=[&](int y){
		if(!ind[y]) dfs(y), low[x]=min(low[x], low[y]);
		else if(onstk[y]) low[x]=min(low[x], ind[y]);
	};
	for(int y:e_base[x]) f(y);
	for(int y:e_temp[x]) f(y);
	if(ind[x] == low[x]){
		++cn;
		while(top){
			int a=stk[--top];
			onstk[a]=0;
			cind[a]=cn;
			if(a == x) break;
		}
	}
}

bool can(int d){
	--d;
	for(int i=1; i<=V; ++i) e_temp[i].clear();
	for(int i=1; i<=2*n; ++i){
		int l=arr[i].first - d, r = arr[i].first + d;
		int me = arr[i].second;
		l = isang(l); r = iha(r);
		draw(l, i-1, me, 1, 2*n, 2*n+2);
		draw(i+1, r, me, 1, 2*n, 2*n+2);
	}
	nt=cn=top=0;
	for(int i=1; i<=V; ++i) ind[i]=0;
	for(int i=1; i<=V; ++i) if(!ind[i]) dfs(i);
	for(int i=1; i<=n; ++i){
		if(cind[2*i] == cind[2*i+1]) return 0;
	}
	return 1;
}

