int LB;
int UB;
int ord[1145141];
int seq[1145141];
bool vised[1145141];

bool DfsFb(int v, bool rev, vector<int> &r) {
  vised[v] = true;
  r.eb(ord[v]);

  bool ret = false;
  for (int u : es[rev][v]) {
    u = belong[u];
    if (ord[u] == UB) ret = true;
    if (!vised[u] && LB <= ord[u] && ord[u] <= UB) {
      ret |= DfsFb(u, rev, r);
    }
  }
  return ret;
}

void Decompose(vector<int> &Rf) {
  int d = Rf[0];

  reps(i, 1, Rf.size()) {
    int v = Rf[i];
    belong[v] = d;
  }

  rep(j, 2) {
    vector<int> tmp, idx(Rf.size());
    while (1) {
      int midx = -1;
      rep(i, Rf.size()) {
        int v = Rf[i];
        if (idx[i] == es[j][v].size()) continue;
        if (midx == -1) midx = i;
        else {
          if (es[j][Rf[midx]][idx[midx]] > es[j][v][idx[i]]) {
            midx = i;
          }
        }
      }
      if (midx == -1) break;
      tmp.eb(es[j][Rf[midx]][idx[midx]]);
      idx[midx]++;
    }
    es[j][d].swap(tmp);
  }
}

bool AddEdge(int x, int y) {
  x = belong[x];
  y = belong[y];

  LB = ord[y];
  UB = ord[x];
  vector<int> Rb, Rf, R;
  if (LB < UB) {
    if (DfsFb(y, false, Rf)) {
      Decompose(Rf);
      for (int v : Rf) {
        if (belong[v^1] == belong[v]) return true;
      }
      return false;
    }
  }

  DfsFb(x, true, Rb);

  vector<int> L;
  sort(all(Rb));
  for (int idx : Rb) {
    int v = seq[idx];
    vised[v] = false;
    L.eb(v);
  }

  sort(all(Rf));
  for (int idx : Rf) {
    int v = seq[idx];
    vised[v] = false;
    L.eb(v);
  }
  R.resize(Rb.size() + Rf.size());
  merge(all(Rb), all(Rf), R.begin());
  rep(i, L.size()) {
    int v = L[i];
    int idx = R[i];
    ord[v] = idx;
    seq[idx] = v;
  }
  vector<int> vvv(1, y), tmp;
  tmp.resize(es[0][x].size()+1);
  merge(all(es[0][x]), all(vvv), tmp.begin());
  es[0][x].swap(tmp);
  tmp.clear();
  tmp.resize(es[1][y].size()+1);
  vvv[0] = x;
  merge(all(es[1][y]), all(vvv), tmp.begin());
  es[1][y].swap(tmp);
