		build(l, i, 0, 0, sz, i + sz - 1);
		build(i + 1, r, 0, 0, sz, i + sz - 1);
	}

	scc();

	rep(i, B) {
		if (cmp[i] == cmp[i + B]) {
			return false;
		}
	}
	return true;
}

