bool hantei(int d){
	ll n=N;
	two_sat ts(N);
	for(int i = 0; i < n; i++) {
		int xi=xy[i].first,yi=xy[i].second;
        for (int j = i + 1; j < n; j++) {
			int xj=xy[j].first,yj=xy[j].second;
            if (abs(xi - xj) < d) {
                // cannot use both of x[i] and x[j]
                ts.add_clause(i, false, j, false);
            }
            if (abs(xi - yj) < d) {
                ts.add_clause(i, false, j, true);
            }
            if (abs(yi - xj) < d) {
                ts.add_clause(i, true, j, false);
            }
            if (abs(yi - yj) < d) {
                ts.add_clause(i, true, j, true);
            }
        }
    }
	return ts.satisfiable();
}

