#include<bits/stdc++.h>
#define pb push_back
#define fi first
#define se second

using namespace std;

typedef long long ll;
typedef pair<int,int> pi;

const int N=60005;

int n,m,op[N],vi[N];
pi b[N];

vector<int>e[N];
int nc,dfc,bcc,dfn[N],low[N],qu[N],bel[N],tp;
bool in[N];
int id[N<<1];

void build(int x,int l,int r){
	id[x]=++nc;
	if(l==r){e[id[x]].pb(op[l]);return;}
	int ls=x<<1,rs=ls|1,mid=(l+r)>>1;
	build(ls,l,mid);e[id[x]].pb(id[ls]);
	build(rs,mid+1,r);e[id[x]].pb(id[rs]);
}
void link(int x,int l,int r,int s,int t,int u){
	if(l==s&&r==t){e[u].pb(id[x]);return;}
	int ls=x<<1,rs=ls|1,mid=(l+r)>>1;
	if(t<=mid)link(ls,l,mid,s,t,u);
	else if(s>mid)link(rs,mid+1,r,s,t,u);
	else link(ls,l,mid,s,mid,u),link(rs,mid+1,r,mid+1,t,u);
}
void tarjan(int x){
	dfn[x]=low[x]=++dfc,qu[++tp]=x,in[x]=true;
	for(int v:e[x]){
		if(!dfn[v])tarjan(v),low[x]=min(low[x],low[v]);
		else if(in[v])low[x]=min(low[x],dfn[v]);
	}
	if(low[x]==dfn[x]){
		int v;++bcc;
		do bel[v=qu[tp]]=bcc,in[v]=false,qu[tp--]=0;while(v!=x);
	}
}
bool chk(int x){
	while(nc)dfn[nc]=low[nc]=bel[nc]=0,e[nc].clear(),nc--;
	nc=m;dfc=bcc=0;
	build(1,1,m);
	int l=1,r=1;
	for(int i=1;i<=m;i++){
		while(b[l].fi<=b[i].fi-x&&l<=m)l++;
		while(b[r].fi<b[i].fi+x&&r<=m)r++;
		if(l<i)link(1,1,m,l,i-1,i); 
		if(i<r-1)link(1,1,m,i+1,r-1,i); 
	}
	for(int i=1;i<=nc;i++)if(!dfn[i])tarjan(i);
	for(int i=1;i<=m;i++)if(bel[i]==bel[op[i]])return false;
	return true;
}

int main(){
	scanf("%d",&n);
	for(int i=1,x;i<=n;i++)for(int j:{0,1})scanf("%d",&x),b[++m]={x,i};
	sort(b+1,b+m+1);
	for(int i=1,j;i<=m;i++)if(!vi[j=b[i].se])vi[j]=i;else op[vi[j]]=i,op[i]=vi[j];
	int l=0,r=(b[m].fi-b[1].fi)/(n-1),mid=(l+r+1)>>1;
	while(l<r){
		if(chk(mid))l=mid;else r=mid-1;
		mid=(l+r+1)>>1;
	}
	printf("%d\n",mid);
	return 0;
}

#include <bits/stdc++.h>
#define inf (1e9 + 7)
#define mem(a, b) memset(a, b, sizeof(a))
using namespace std;

int mxsum[40105], misum[40105], n, mx, mi, mxsum2[40105], misum2[40105];

struct node
{
    int a, b;
}nd[10005], nd2[10005];

bool cmp(const struct node & a, const struct node & b)
{
    return a.a < b.a;
}

bool cmp2(const struct node & a, const struct node & b)
{
    return a.b < b.b;
}

void build(int l, int r, int nn)
{
    mxsum[nn] = -inf;
    misum[nn] = inf;
    if(l == r)
    {
        mxsum[nn] = nd[l].b;
        misum[nn] = nd[l].b;
        return;
    }
    int mid = (l + r) / 2;
    build(l, mid, nn * 2);
    build(mid + 1, r, nn * 2 + 1);
    mxsum[nn] = max(mxsum[nn * 2], mxsum[nn * 2 + 1]);
    misum[nn] = min(misum[nn * 2], misum[nn * 2 + 1]);
}

void build2(int l, int r, int nn)
{
    mxsum2[nn] = -inf;
    misum2[nn] = inf;
    if(l == r)
    {
        mxsum2[nn] = nd[l].a;
        misum2[nn] = nd[l].a;
        return;
    }
    int mid = (l + r) / 2;
    build2(l, mid, nn * 2);
    build2(mid + 1, r, nn * 2 + 1);
    mxsum2[nn] = max(mxsum2[nn * 2], mxsum2[nn * 2 + 1]);
    misum2[nn] = min(misum2[nn * 2], misum2[nn * 2 + 1]);
}

void get(int l, int r, int nn, int ll, int rr)
{
    if(l >= ll&&r <= rr)
    {
        mi = min(mi, misum[nn]);
        mx = max(mx, mxsum[nn]);
        return;
    }
    if(l > rr||r < ll)
        return;
    int mid = (l + r) / 2;
    get(l, mid, nn * 2, ll, rr);
    get(mid + 1, r, nn * 2 + 1, ll, rr);
}

void get2(int l, int r, int nn, int ll, int rr)
{
    if(l >= ll&&r <= rr)
    {
        mi = min(mi, misum2[nn]);
        mx = max(mx, mxsum2[nn]);
        return;
    }
    if(l > rr||r < ll)
        return;
    int mid = (l + r) / 2;
    get2(l, mid, nn * 2, ll, rr);
    get2(mid + 1, r, nn * 2 + 1, ll, rr);
}

int getpos(int l, int v)
{
    int r = n, res = -1;
    while(l <= r)
    {
        int mid = (l + r) / 2;
        if(nd[mid].a < v)
            l = mid + 1, res = max(res, mid);
        else
            r = mid - 1;
    }
    return res;
}

int getpos2(int l, int v)
{
    int r = n, res = -1;
    while(l <= r)
    {
        int mid = (l + r) / 2;
        if(nd[mid].b < v)
            l = mid + 1, res = max(res, mid);
        else
            r = mid - 1;
    }
    return res;
}

bool jg(int a)
{
    bool ff = 0;
    for(int i = 1;i <= n;i++)
    {
        int pos = getpos(i + 1, nd[i].a + a);
        if(pos == -1)
            continue;
        mx = -inf;
        mi = inf;
        get(1, n, 1, i + 1, pos);
        if(abs(mx - nd[i].a) < a||abs(mi - nd[i].a) < a)
        {
            ff = 1;
            break;
        }
    }
    if(!ff)
        return true;
    for(int i = 1;i <= n;i++)
    {
        int pos = getpos(i + 1, nd[i].b + a);
        if(pos == -1)
            continue;
        mx = -inf;
        mi = inf;
        get2(1, n, 1, i + 1, pos);
        if(abs(mx - nd[i].b) < a||abs(mi - nd[i].b) < a)
            return false;
    }
    return true;
}

int main()
{
    scanf("%d", &n);
    for(int i = 1;i <= n;i++)
        scanf("%d%d", &nd[i].a, &nd[i].b), nd2[i].a = nd[i].a, nd2[i].b = nd[i].b;
    sort(nd + 1, nd + 1 + n, cmp);
    sort(nd2 + 1, nd2 + 1 + n, cmp2);
    build(1, n, 1);
    build2(1, n, 1);
    int l = 0, r = 1e9, ans = 0;
    while(l <= r)
    {
        int mid = (l + r) / 2;
        if(jg(mid))
            l = mid + 1, ans = max(ans, mid);
        else
            r = mid - 1;
    }
    printf("%d\n", ans);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

#pragma GCC optimize("O3")

int x[10005], y[10005];
pair<int, int> dat[10005];

const int MAXN = 20001;

vector<int> graph[MAXN];
int up[MAXN], visit[MAXN], vtime;
vector<int> stk;
int scc_idx[MAXN], scc_cnt;
int gn, n;
int perm[MAXN];

bool dfs(int nod) {
	up[nod] = visit[nod] = ++vtime;
	stk.push_back(nod);
	for (int next : graph[nod]) {
		if (visit[next] == 0) {
			if (dfs(next) == false) return false;
			up[nod] = min(up[nod], up[next]);
		}
		else if (scc_idx[next] == 0)
			up[nod] = min(up[nod], visit[next]);
	}
	if (up[nod] == visit[nod]) {
		++scc_cnt;
		int t;
		do {
			t = stk.back();
			stk.pop_back();
			scc_idx[t] = scc_cnt;
			if (t < n)
			{
				if (scc_idx[t + n] == scc_idx[t]) return false;
			}
			else
			{
				if (scc_idx[t - n] == scc_idx[t]) return false;
			}
		} while (!stk.empty() && t != nod);
	}

	return true;
}
// find SCCs in given directed graph
// O(V+E)
bool get_scc() {
	vtime = 0;
	memset(visit, 0, sizeof(visit));
	scc_cnt = 0;
	memset(scc_idx, 0, sizeof(scc_idx));
	for (int i = 0; i < 500; ++i)
		if (visit[perm[i]] == 0 && dfs(perm[i]) == false) return false;
	return true;
}

bool check(int t)
{
	for (int i = 0; i < gn; i++) graph[i].clear();
	int gt = 0;

	if (n <= 5000) {
		for (int i = 0; i < n; i++) for (int j = i + 1; j < n; j++)
		{
			int cnt = 0;

			if (abs(x[i] - x[j]) < t)
			{
				cnt++;
				graph[i].push_back(j + n);
				graph[j].push_back(i + n);
			}

			if (abs(x[i] - y[j]) < t)
			{
				cnt++;
				graph[i].push_back(j);
				graph[j + n].push_back(i + n);
			}

			if (abs(y[i] - x[j]) < t)
			{
				cnt++;
				graph[i + n].push_back(j + n);
				graph[j].push_back(i);
			}

			if (abs(y[i] - y[j]) < t)
			{
				cnt++;
				graph[i + n].push_back(j);
				graph[j + n].push_back(i);
			}

			if (cnt == 4) return false;
			gt += cnt * 4;
		}
	}
	else
	{
		for (int i = 0; i < n; i++) for (int j = i + 1; j < i + 1000; j++)
		{
			int cnt = 0;

			if (abs(x[i] - x[j]) < t)
			{
				cnt++;
				graph[i].push_back(j + n);
				graph[j].push_back(i + n);
			}

			if (abs(x[i] - y[j]) < t)
			{
				cnt++;
				graph[i].push_back(j);
				graph[j + n].push_back(i + n);
			}

			if (abs(y[i] - x[j]) < t)
			{
				cnt++;
				graph[i + n].push_back(j + n);
				graph[j].push_back(i);
			}

			if (abs(y[i] - y[j]) < t)
			{
				cnt++;
				graph[i + n].push_back(j);
				graph[j + n].push_back(i);
			}

			if (cnt == 4) return false;
			gt += cnt * 4;
		}
	}

	return get_scc();
}

int main()
{
	scanf("%d", &n);
	gn = n * 2;
	for (int i = 0; i < n; i++)
	{
		scanf("%d%d", &dat[i].first, &dat[i].second);
		if (dat[i].first > dat[i].second) swap(dat[i].first, dat[i].second);
	}
	sort(dat, dat + n);
	for (int i = 0; i < n; i++) x[i] = dat[i].first, y[i] = dat[i].second;

	for (int i = 0; i < gn; i++) perm[i] = i;
	shuffle(perm, perm + gn, mt19937{});

	int lo = 1, hi = (max(*max_element(x, x + n), *max_element(y, y + n)) - min(*min_element(x, x + n), *min_element(y, y + n))) / (n - 1), ans = 0;

	for (int i = 0; i < n; i++) for (int j = i + 1; j < n; j++)
		hi = min(hi, max({
		abs(x[i] - x[j]),
		abs(x[i] - y[j]),
		abs(y[i] - x[j]),
		abs(y[i] - y[j]),
		}));

	while (lo <= hi)
	{
		int mid = (lo + hi) / 2;
		if (check(mid))
		{
			ans = mid;
			lo = mid + 1;
		}
		else hi = mid - 1;
	}

	printf("%d\n", ans);
}

#include <bits/stdc++.h>
#define rep(i,n)for(int i=0;i<(n);i++)
using namespace std;
typedef pair<int,int>P;

int n;
int x[20000],y[20000];
P p[40000];
vector<int>id[20000];

vector<int>E[80000],G[80000];
int N;

void init(int n){
	N=1;while(N<n)N<<=1;
	rep(i,2*N-1){
		E[i].clear();
		G[i].clear();
	}
}
void add_edge(int a,int b,int x,int k=0,int l=0,int r=N){
	if(b<=l||r<=a)return;
	if(a<=l&&r<=b){
		E[x+N-1].push_back(k);
		G[k].push_back(x+N-1);
		return;
	}
	add_edge(a,b,x,k*2+1,l,(l+r)/2);
	add_edge(a,b,x,k*2+2,(l+r)/2,r);
}

bool used[80000];
vector<int>vs;
int cmp[80000];

void dfs(int v){
	used[v]=true;
	for(int u:E[v]){
		if(!used[u])dfs(u);
	}
	if(v<N-1&&!used[v*2+1])dfs(v*2+1);
	if(v<N-1&&!used[v*2+2])dfs(v*2+2);
	vs.push_back(v);
}
void rdfs(int v,int k){
	cmp[v]=k;
	for(int u:G[v]){
		if(cmp[u]==-1)rdfs(u,k);
