		int r; { int L=i,R=2*n; while(L+1<R) { int M=L+(R-L)/2; if(p[M].x-p[i].x<d) L=M; else R=M; } r=L; }
		if(l<=i-1) sappend(0,0,2*n-1,l,i-1,i);
		if(i+1<=r) sappend(0,0,2*n-1,i+1,r,i);
	}
