}A[N];

int n, m, top, clk;
int dfn[N], low[N], bel[N], stk[N];

void Tarjan(int o){
	low[o] = dfn[o] = ++clk;
	stk[++top] = o;
	for(int i = Begin[o]; i; i = Next[i]){
		int u = to[i];
		if(!dfn[u]){
			Tarjan(u);
			low[o] = min(low[u], low[o]);
		}
		else if(!bel[u]) low[o] = min(low[o], dfn[u]);
	}
	if(low[o] == dfn[o]){
		bel[o] = ++m;
		while(stk[top] ^ o) bel[stk[top--]] = m;
		--top;
	}
}

vector<int> G[N], dif[N];
int deg[N], val[N];

bool Topsort(){
	queue<int> q;
	For(i, 1, m) if(!deg[i]) q.push(i);
	while(!q.empty()){
		int o = q.front(), sz; q.pop();
		sz = int(dif[o].size()) - 1;
		val[o] = 1;
		For(i, 0, sz) if(val[dif[o][i]] == 1){
			val[o] = 0;
			break;
		}
		if(!val[o]) For(i, 0, sz) if(val[dif[o][i]] == 0) return false;
		sz = int(G[o].size()) - 1;
		For(i, 0, sz){
			int v = G[o][i];
			if(!--deg[v]) q.push(v);
		}
	}
	return true;
}

bool check(int lim){
	e = m = top = 0;
	For(i, 2, n * 2 + 1) Begin[i] = dfn[i] = bel[i] = 0;
	For(i, 1, n) For(j, i + 1, n){
		if(abs(A[i].x - A[j].y) < lim) add(i, 0, j, 0), add(j, 1, i, 1);
		if(abs(A[i].x - A[j].x) < lim) add(i, 0, j, 1), add(j, 0, i, 1);
		if(abs(A[i].y - A[j].y) < lim) add(i, 1, j, 0), add(j, 1, i, 0);
		if(abs(A[i].y - A[j].x) < lim) add(i, 1, j, 1), add(j, 0, i, 0);
	}

	clk = 0;
	For(i, 2, n * 2 + 1) if(!dfn[i]) Tarjan(i);

	For(i, 1, m) G[i].clear(), dif[i].clear(), deg[i] = 0, val[i] = -1;
	For(i, 1, n){
		int u = bel[i << 1], v = bel[i << 1 | 1];
		if(u == v) return false;
		dif[u].pb(v), dif[v].pb(u);
	}

	For(i, 2, n * 2 + 1) for(int j = Begin[i]; j; j = Next[j])
		if(bel[i] ^ bel[to[j]]) G[bel[to[j]]].pb(bel[i]), deg[bel[i]]++;
	return Topsort();
}

int main(){
	scanf("%d", &n);
	For(i, 1, n){
		scanf("%d%d", &A[i].x, &A[i].y);
		if(A[i].x > A[i].y) swap(A[i].x, A[i].y);
	}

	int Maxd = 1e9 / n + 1;
	For(i, 1, n) For(j, i + 1, n) Maxd = min(Maxd, max(abs(A[j].y - A[i].x), abs(A[i].y - A[j].x)));

	int L = 0, R = Maxd;
	while(L < R){
		int mid = (L + R + 1) >> 1;
		if(check(mid)) L = mid;
		else R = mid - 1;
	}

	printf("%d\n", L);

	return 0;
}

