vector<int> tout;
vector<int> temper;
int cur_t = 1;

int dfs_time = 0;

int& get(int x) {
    if (cur_t != temper[x]) {
        tout[x] = -1;
        temper[x] = cur_t;
    }
    return tout[x];
}

int MI;

vector<pair<int, int>> in;
int n;

bool dfs(int v) {
    if (get(v) != -1)
        return true;

    int base = (v >= n ? v - n : v);
    int coord = (base == v ? in[base].first : in[base].second);

    bool scs = true;

    for (int i = 0; i != n; ++i)
        if (base != i) {
            auto b1 = std::abs(in[i].first - coord) >= MI; // good
            auto b2 = std::abs(in[i].second - coord) >= MI; // good

            if (not b1 and not b2)
                return false;
            if (b1 and not b2)
                scs = scs and dfs(i);
            if (not b1 and b2)
                scs = scs and dfs(i + n);
        }
    get(v) = dfs_time++;
    return scs;
}

