    temper.resize(2 * n);
    for (int i = 0; i != n; ++i) {
        in[i].first = input<int>();
        in[i].second = input<int>();

        if (not (in[i].first <= in[i].second))
            std::swap(in[i].first, in[i].second);
    }

    int lo = TYPEMIN(int); // can
    int hi = TYPEMAX(int); // not can.

    for (int i = 0; i != n; ++i)
        for (int j = i + 1; j != n; ++j) {
            int mx = TYPEMIN(int);
            int mn = TYPEMAX(int);

            for (int fst: {in[i].first, in[i].second})
                for (int snd: {in[j].first, in[j].second}) {
                    int d = std::abs(snd - fst);
                    mx = max(mx, d);
                    mn = min(mn, d);
                }

            lo = max(lo, mn);
            hi = min(hi, mx + 1);
        }

    auto check = []() {
        cur_t += 1;
        dfs_time = 0;
        for (int i = 0; i != 2 * n; ++i)
            if (not dfs(i))
                return false;
//        for (int i = 0; i != n; ++i)
//            state[i] = tout[i + n] < tout[i];

        for (int i = 0; i != n; ++i)
            for (int j = i + 1; j != n; ++j) {
                int c1 = (tout[i + n] < tout[i]) ? in[i].second : in[i].first;
                int c2 = (tout[j + n] < tout[j]) ? in[j].second : in[j].first;
                if (std::abs(c1 - c2) < MI)
                    return false;
            }
        return true;
    };

    while (hi - lo > 1) {
        MI = lo + (hi - lo) / 2;
        if (check)
            lo = MI;
        else
            hi = MI;
    }

    cout << lo << "\n";

    return 0;
}

