    ts.init();
    for (i=0;i<n;i++) {
        ts.add(YES(rrd[i*2]+key),YES(rrd[i*2+1]+key));
        ts.add(NO(rrd[i*2]+key),NO(rrd[i*2+1]+key));
    }
    init();
