using namespace std;

typedef pair<int,int> ii;

const int MAXN = 10004;

int n,k;
int p[MAXN*2];
stack<int> s;
set<ii> nodes;
bool visited[MAXN*2];
int scc[MAXN*2];

int other(int a){
    if(a>=MAXN) return a-MAXN;
    return a+MAXN;
}

void dfs1(int node){
    if(visited[node]) return;
    visited[node]=true;
    auto it=nodes.upper_bound(ii(p[node]-k, 2*MAXN));
    for(;it!=nodes.end() && it->first<p[node]+k;){
        if(it->second==node){
            it++;
        }else{
            int nxt=it->second;
            nodes.erase(it);
            dfs1(other(nxt));
            it=nodes.upper_bound(ii(p[node]-k, 2*MAXN));
        }
    }
    s.push(node);
}

void dfs2(int node, int start){
    if(scc[node]!=-1) return;
    scc[node]=start;
    auto it=nodes.upper_bound(ii(p[other(node)]-k, 2*MAXN));
    for(;it!=nodes.end() && it->first<p[other(node)]+k;){
        if(it->second==other(node)){
            it++;
        }else{
            int nxt=it->second;
            nodes.erase(it);
            dfs2(nxt, start);
            it=nodes.upper_bound(ii(p[other(node)]-k, 2*MAXN));
        }
    }
}


bool ok(int g){
    k=g;
    nodes.clear();
    for(int i=0;i<n;++i){
        nodes.emplace(p[i], i);
        nodes.emplace(p[MAXN+i], MAXN+i);
    }
    fill(visited, visited+MAXN*2, false);
    fill(scc, scc+MAXN*2, -1);
    for(int i=0;i<n;++i){
        if(!visited[i]){
            dfs1(i);
        }
        if(!visited[i+MAXN]){
            dfs1(i+MAXN);
        }
    }
    nodes.clear();
    for(int i=0;i<n;++i){
        nodes.emplace(p[i], i);
        nodes.emplace(p[MAXN+i], MAXN+i);
    }
    while(!s.empty()){
        int i=s.top();
        s.pop();
        if(scc[i]==-1) dfs2(i, i);
    }
    for(int i=0;i<n;++i){
        if(scc[i]==scc[MAXN+i]){
            return false;
        }
    }
    return true;
}


