            }
            if (cnt >= 1e6) return 0;
        }
    }
    st.clear();
    for (int i = 1;i <= 2 * n;i++){
        if (vis[i] == 0){
            vis[i] = 1;
            dfsout(i);
        }
    }
    reverse(st.begin(),st.end());
    for (int i = 1;i <= 2 * n;i++) vis[i] = 0;
    int cscc = 0;
    for (int i = 1;i <= 2 * n;i++){
        int u = st[i - 1];
        if (vis[u] == 0){
            cscc++;
            vis[u] = 1;
            dfsin(u,cscc);
        }
    }
    for (int i = 1;i <= n;i++){
        if (scc[i] == scc[i + n]) return 0;
    }
    return 1;
}
