#define lson (o << 1)
#define rson (o << 1 | 1)
int id[N], bel[N];
int build(int o, int l, int r) {
	if (l == r) return id[o] = b[l].second;
	int mid = (l + r) >> 1;
	id[o] = ++cnt; add(id[o], build(lson, l, mid)); add(id[o], build(rson, mid + 1, r));
	return id[o];
}
void link(int o, int l, int r, int L, int R, int p) {
	if (L <= l && r <= R) return add(p, id[o]);
	int mid = (l + r) >> 1;
	if (L <= mid) link(lson, l, mid, L, R, p);
	if (R > mid) link(rson, mid + 1, r, L, R, p);
}
bool in[N];
stack<int> stk;
void tarjan(int u) {
	dfn[u] = low[u] = ++tim;
	in[u] = 1; stk.push(u);
	for (int i = lst[u]; i; i = g[i].nxt) {
		int v = g[i].to;
		if (!dfn[v]) tarjan(v), low[u] = min(low[u], low[v]);
		else if (in[v]) low[u] = min(low[u], dfn[v]);
	}
	if (low[u] == dfn[u]) {
		scc++;
		while (in[u]) {
			bel[stk.top()] = scc;
			in[stk.top()] = 0; stk.pop();
		}
	}
	return ;
}
bool check(int d) {
	clear();
	build(1, 1, n * 2);
	for (int i = 1; i <= n; i++)
		for (int j = 0; j < 2; j++) {
			int l = lower_bound(b + 1, b + 1 + 2 * n, make_pair(a[i][j] - d + 1, -inf)) - b;
			int r = upper_bound(b + 1, b + 1 + 2 * n, make_pair(a[i][j] + d - 1, inf)) - b - 1;
			int x = lower_bound(b + 1, b + 1 + 2 * n, make_pair(a[i][j], (j ^ 1) * n + i)) - b;
			if (l < x) link(1, 1, 2 * n, l, x - 1, j * n + i);
			if (x < r) link(1, 1, 2 * n, x + 1, r, j * n + i);
		}
	for (int i = 1; i <= cnt; i++)
		if (!dfn[i]) tarjan(i);
	for (int i = 1; i <= n; i++)
		if (bel[i] == bel[n + i]) return 0;
	return 1;
}
