int n,m,bc,sm,tm,x[N],y[N],v[N*2],o[N*2],f[1<<16],dfn[M],low[M],st[M],bl[M];

inline pii get(int l,int r)
{
	return mp(std::lower_bound(v,v+n*2,l)-v+1,std::upper_bound(v,v+n*2,r)-v);
}

inline void build(int x,int l,int r)
{
	if(l==r)f[x]=o[l];
	else
	{
		f[x]=0;
		int t=(l+r)>>1;
		build(x<<1,l,t);
		build(x<<1|1,t+1,r);
	}
}

inline int qry(int x,int l,int r,int ql,int qr)
{
	if(l>=ql&&r<=qr&&f[x])return f[x];
	int t=(l+r)>>1,s=++m;
	if(ql<=t)add(qry(x<<1,l,t,ql,qr),s);
	if(qr>t)add(qry(x<<1|1,t+1,r,ql,qr),s);
	if(l>=ql&&r<=qr)f[x]=s;
	return s;
}

inline void dfs(int x)
{
	dfn[x]=low[x]=++tm;
	st[sm++]=x;
	for(edge*i=p[x];i;i=i->ne)
	{
		if(!dfn[i->to])
		{
			dfs(i->to);
			repl(low[x],low[i->to]);
		}
		else if(!bl[i->to])
		{
			repl(low[x],dfn[i->to]);
		}
	}
	if(low[x]==dfn[x])
	{
		for(bc++;;)
		{
			bl[st[--sm]]=bc;
			if(st[sm]==x)break;
		}
	}
}

inline bool chk(int l)
{
	build(1,1,n*2);
	m=n*2;
	fo1(i,n)
	{
		pii t;
		t=get(v[x[i]-1]-l+1,v[x[i]-1]+l-1);
		//out,'\n';out,t.xx,' ',x[i],' ',t.yy,'\n';
		if(t.xx!=x[i])add(qry(1,1,n*2,t.xx,x[i]-1),i+n);
		if(x[i]!=t.yy)add(qry(1,1,n*2,x[i]+1,t.yy),i+n);
		t=get(v[y[i]-1]-l+1,v[y[i]-1]+l-1);
		//out,t.xx,' ',y[i],' ',t.yy,'\n';
		if(t.xx!=y[i])add(qry(1,1,n*2,t.xx,y[i]-1),i);
		if(y[i]!=t.yy)add(qry(1,1,n*2,y[i]+1,t.yy),i);
	}
	fo1(i,m)if(!dfn[i])dfs(i);
	bool res=1;
	fo1(i,n)res&=bl[i]!=bl[i+n];
	fo1(i,m)p[i]=0;
	fo1(i,m)dfn[i]=low[i]=bl[i]=0;
	e=_e;
	bc=tm=0;
	return res;
}

int main()
{
	in,n;
	fo1(i,n)in,x[i],y[i];
	fo1(i,n)v[i-1]=x[i],v[i+n-1]=y[i];
	std::sort(v,v+n*2);
	fo1(i,n)x[i]=std::upper_bound(v,v+n*2,x[i])-v;
	fo1(i,n)y[i]=std::upper_bound(v,v+n*2,y[i])-v;
	fo1(i,n)x[i]-=f[x[i]]++;
	fo1(i,n)y[i]-=f[y[i]]++;
	//fo1(i,n)out,x[i],' ';out,'\n';
	//fo1(i,n)out,y[i],' ';out,'\n';
	fo1(i,n)o[x[i]]=i,o[y[i]]=i+n;
	int l=0,r=1e9;
	while(l+1<r)
	{
		int mid=(l+r)>>1;
		if(chk(mid))l=mid;
		else r=mid;
	}
	out,l,'\n';
}

