int id[maxn*4];
int head[maxn*4],nxt[maxn*40],to[maxn*40],tot;
void add(int u,int v)
{
    tot++;
    nxt[tot]=head[u];
    head[u]=tot;
    to[tot]=v;
}
void build(int k,int l,int r)
{
    if(l==r)
    {
        id[k]=b[l].y;
        return;
    }
    id[k]=++cnt;
    int mid=(l+r)/2;
    build(k*2,l,mid);
    build(k*2+1,mid+1,r);
    add(id[k],id[k*2]);
    add(id[k],id[k*2+1]);
}
void find(int k,int l,int r,int x,int y,int z)
{
    if(x>y)  return;
    if(l>=x&&r<=y)
    {
        add(z,id[k]);
        return;
    }
    int mid=(l+r)/2;
    if(mid>=x)  find(k*2,l,mid,x,y,z);
    if(mid<y)   find(k*2+1,mid+1,r,x,y,z);
}
void work(int x,int mid,int y,int z)
{
    int L=lower_bound(b+1,b+2*n+1,(P){x-mid+1,0})-b;
    int R=upper_bound(b+1,b+2*n+1,(P){x+mid-1,2*n+1})-b-1;
    int MID=lower_bound(b+1,b+2*n+1,(P){x,y})-b;
    find(1,1,2*n,L,MID-1,z);
    find(1,1,2*n,MID+1,R,z);
}
stack<int>s;
int dfn[maxn*4],low[maxn*4],vis[maxn*4],D;
int cnt_scc,scc[maxn*4];
void tarjan(int x)
{
    dfn[x]=low[x]=++D;
    vis[x]=1;s.push(x);
    for(int i=head[x];i;i=nxt[i])
    {
        if(!dfn[to[i]])
        {
            tarjan(to[i]);
            low[x]=min(low[x],low[to[i]]);
        }
        else if(vis[to[i]])
        {
            low[x]=min(low[x],dfn[to[i]]);
        }
    }
    if(dfn[x]==low[x])
    {
        cnt_scc++;
        int tmp=0;
        while(tmp!=x)
        {
            tmp=s.top();s.pop();
            scc[tmp]=cnt_scc;
            vis[tmp]=0;
        }
    }
}
bool check(int x)
{
    tot=0;cnt=2*n;D=0;cnt_scc=0;
    memset(scc,0,sizeof(scc));
    memset(head,0,sizeof(head));
    memset(dfn,0,sizeof(dfn));
    memset(low,0,sizeof(low));
    build(1,1,2*n);
    for(int i=1;i<=n;i++)
    {
        work(a[i].x,x,i,i+n);
        work(a[i].y,x,i+n,i);
    }
    for(int i=1;i<=cnt;i++)
      if(!dfn[i])  tarjan(i);
    for(int i=1;i<=n;i++)
      if(scc[i]==scc[i+n])  return false;
    return true;
}
int main()
{
    n=read();
    for(int i=1;i<=n;i++)  a[i].x=read(),a[i].y=read();
    for(int i=1;i<=n;i++)  b[i*2-1].x=a[i].x,b[i*2].x=a[i].y;
    for(int i=1;i<=n;i++)  b[i*2-1].y=i,b[i*2].y=i+n;
    sort(b+1,b+2*n+1,cmp);
    int l=0,r=1000000000;
    while(l<=r)
    {
        int mid=(l+r)/2;
        if(check(mid))
        {
            res=mid;
            l=mid+1;
        }
        else r=mid-1;
    }
    printf("%d\n",res);
    return 0;
}

