void modify(int u, int l, int r, int L, int R, int from)
{
	if (L > R)
		return; 
	if (L <= l && r <= R)
	{
		add_edge(from, u); 
		return; 
	}
	int m = l + r >> 1; 
	if (L <= m)
		modify(lson[u], l, m, L, R, from); 
	if (m < R)
		modify(rson[u], m + 1, r, L, R, from); 
}
void tarjan(int u)
{
	dfn[u] = low[u] = clk++; 
	st[tp++] = u; 
	in[u] = true; 
	for (int i = lst[u]; ~i; i = pre[i])
	{
		if (-1 == dfn[to[i]])
		{
			tarjan(to[i]); 
			low[u] = std::min(low[u], low[to[i]]); 
		}
		else if (in[to[i]])
			low[u] = std::min(low[u], dfn[to[i]]); 
	}
	if (low[u] == dfn[u])
	{
		do
		{
			comp[st[--tp]] = comp_cnt; 
			in[st[tp]] = false; 
		}
		while (st[tp] != u); 
		comp_cnt++; 
	}
}
inline bool chk(int mid)
{
	for (int i = 0; i < n << 1; i++)
		lst[i] = -1; 
	for (int i = 0; i < n; i++)
	{
		int l = std::lower_bound(arr, arr + (n << 1), (data){x[i] - mid + 1, -1}) - arr; 
		int r = std::upper_bound(arr, arr + (n << 1), (data){x[i] + mid - 1, 1e9}) - arr - 1; 
		if (l <= r)
		{
			modify(rt, 0, (n << 1) - 1, l, pos[i] - 1, i); 
			modify(rt, 0, (n << 1) - 1, pos[i] + 1, r, i); 
		}
		l = std::lower_bound(arr, arr + (n << 1), (data){y[i] - mid + 1, -1}) - arr; 
		r = std::upper_bound(arr, arr + (n << 1), (data){y[i] + mid - 1, 1e9}) - arr - 1; 
		if (l <= r)
		{
			modify(rt, 0, (n << 1) - 1, l, pos[i + n] - 1, i + n); 
			modify(rt, 0, (n << 1) - 1, pos[i + n] + 1, r, i + n); 
		}
	}
	memset(dfn, -1, sizeof(dfn)); 
	memset(in, false, sizeof(in)); 
	clk = comp_cnt = tp = 0; 
	for (int i = 0; i < t_cnt; i++)
	{
		if (-1 == dfn[i])
			tarjan(i); 
	}
	for (int i = 0; i < n; i++)
	{
		if (comp[i] == comp[i + n])
			return false; 
	}
	return true;
}
