void Tarjan(int x)
{
	dfn[x] = low[x] = ++tot; sta[++top] = x; vis[x] = true;
	for(int i = head[x] ; i ; i = e[i].nex)
	{
		int to = e[i].to;
		if(!dfn[to]) Tarjan(to) , low[x] = min(low[x] , low[to]);
		else if(vis[to]) low[x] = min(low[x] , dfn[to]);
	}
	if(low[x] == dfn[x])
	{
		num++;
		int t;
		do{
			t = sta[top--];
			col[t] = num; vis[t] = false;
		}while(t != x);
	}
}

