#define ls i<<1
#define rs i<<1|1
void build(int i,int l,int r){
	tree[i].l=l;
	tree[i].r=r;
	seg[i]=++segtot;
	if(l==r){
		add(seg[i],((pos[l]+n-1)%(2*n)+1));
		return;
	}
	int mid=(l+r)>>1;
	build(ls,l,mid);
	build(rs,mid+1,r);
	add(seg[i],seg[ls]);
	add(seg[i],seg[rs]);
}
int low[N],dfn[N],num,tot,col[N],vis[N];
stack<int> st;
void Tarjan(int u){
	low[u]=dfn[u]=++num;
	st.push(u);
	vis[u]=1;
	for(int i=head[u];i;i=edge[i].nxt){
		int v=edge[i].to;
		if(!dfn[v]){
			Tarjan(v);
			low[u]=min(low[u],low[v]);
		}
		else if(vis[v]){
			low[u]=min(low[u],dfn[v]);
		}
	}
	if(low[u]==dfn[u]){
		int t=0;
		++tot;
		while(u^t){
			t=st.top();
			st.pop();
			vis[t]=0;
			col[t]=tot;
		}
	}
} 
void Change(int i,int l,int r,int u){
	if(l>r)return;
	if(tree[i].l>=l&&tree[i].r<=r){
		add(u,seg[i]);
		return;
	}
	int mid=(tree[i].l+tree[i].r)>>1;
	if(l<=mid){
		Change(ls,l,r,u);
	}
	if(r>mid){
		Change(rs,l,r,u);
	}
}
