    block = sqrt( n << 1 ) ; 
    for(Rg int i=1; i<=(n<<1); i++) pos[i] = (i-1)/block+1 ; 
    Rg int l = 1 , r = a[n<<1].whe - a[1].whe , mid , Ans = 0  ;  
    while( l <= r ) { 
    	mid = l+r >> 1 ; 
