struct halfEdge
{
	int v;
	halfEdge *next;
};
halfEdge adj_pool[MaxNE], *adj_tail = adj_pool;
halfEdge *adj[MaxNV + 1];

inline void addEdge(const int &u, const int &v)
{
	adj_tail->v = v, adj_tail->next = adj[u];
	adj[u] = adj_tail++;
}

int dfs_clock = 0;
int dfn[MaxNV + 1], low[MaxNV + 1];

int sta_n = 0, sta[MaxNV + 1];

int scc_n = 0;
int sccNum[MaxNV + 1];

void dfs(const int &u)
{
	dfn[u] = low[u] = ++dfs_clock;
	sta[++sta_n] = u;

	for (halfEdge *e = adj[u]; e; e = e->next)
	{
		if (!dfn[e->v])
		{
			dfs(e->v);
			tense(low[u], low[e->v]);
		}
		else if (!sccNum[e->v])
			tense(low[u], dfn[e->v]);
	}

	if (dfn[u] == low[u])
	{
		++scc_n;

		int v = -1;
		while (v != u)
			sccNum[v = sta[sta_n--]] = scc_n;
	}
}

int seg_n = 1;
int lc[MaxNV + 1], rc[MaxNV + 1];

int ver[MaxM + 1];

void seg_build(int p, int pL, int pR)
{
	if (pL == pR)
		ver[pL] = p;
	else
	{
		int pM = pL + pR >> 1;
		lc[p] = ++seg_n;
		rc[p] = ++seg_n;
		seg_build(lc[p], pL, pM);
		seg_build(rc[p], pM + 1, pR);
	}
}

void seg_add(int p, int pL, int pR, int qL, int qR, int v)
{
	if (qL <= pL && qR >= pR)
	{
		addEdge(v, p);
		return;
	}

	int pM = pL + pR >> 1;
	if (qL <= pM)
		seg_add(lc[p], pL, pM, qL, qR, v);
	if (qR > pM)
		seg_add(rc[p], pM + 1, pR, qL, qR, v);
}

