{
	int x, v;
	node() {}
	node(const int &_x, const int &_v)
		: x(_x), v(_v) {}

	friend inline bool operator<(const node &lhs, const node &rhs)
	{
		if (lhs.x != rhs.x)
			return lhs.x < rhs.x;
		return lhs.v < rhs.v;
	}
};
node p[MaxM + 1];

inline bool validate(int d)
{
	adj_tail = adj_pool;
	for (int u = 1; u <= seg_n; ++u)
		adj[u] = NULL;

	for (int u = 1; u <= seg_n; ++u)
	{
		if (lc[u] > 0)
			addEdge(u, lc[u]);
		if (rc[u] > 0)
			addEdge(u, rc[u]);
	}

	int l = 1, r = 1;
	for (int i = 1; i <= m; ++i)
	{
		while (p[i].x - p[l].x >= d)
			++l;
		while (r < m && p[r + 1].x - p[i].x < d)
			++r;

		int v = ver[p[i].v];
		if (l < i)
			seg_add(1, 1, m, l, i - 1, v);
		if (i < r)
			seg_add(1, 1, m, i + 1, r, v);
	}

	scc_n = sta_n = dfs_clock = 0;
	for (int u = 1; u <= seg_n; ++u)
		dfn[u] = low[u] = sccNum[u] = 0;
	for (int u = 1; u <= seg_n; ++u)
		if (!dfn[u])
			dfs(u);

	for (int i = 1; i <= n; ++i)
		if (sccNum[ver[vl[i]]] == sccNum[ver[vr[i]]])
			return false;
	return true;
}

