map<int, int> opposite;


void build(int node, int s, int e){
	if(s > e)	return;
	totnodes = max(totnodes, node);
	if(s == e){
		seg_idx[arr[s].ss.ff][arr[s].ss.ss] = node;
		return;
	}
	int mid = (s+e)/2;
	build(LEFT(node), s, mid);
	build(RIGHT(node), mid+1, e);
}

int get_opposite(int n){
	return opposite[n];
}


void add_edge(int node, int s, int e, int lo, int hi, int idx){
	if(s > e || lo > e || s > hi)	return;
	if(s >= lo && e <= hi){
// cout<<"found incompatibility between nodes "<<node<<" "<<idx<<endl;
// cout<<"so added edges "<<node<<" to "<<get_opposite(idx)<<" and "<<idx<<" to "<<get_opposite(node)<<endl;
		adj[node].pb(get_opposite(idx));
		adj[idx].pb(get_opposite(node));
		return;
	}
	int mid = (s+e)/2;
	add_edge(LEFT(node), s, mid, lo, hi, idx);
	add_edge(RIGHT(node), mid+1, e, lo, hi, idx);
}


void tarjan(int v){

	disc[v] = low[v] = ++ticks;
	instack[v] = true;
	st.push(v);

	for(auto vv : adj[v])
		if(disc[vv] == -1){
			tarjan(vv);
			low[v] = min(low[v], low[vv]);
		}
		else if(instack[vv]){
			low[v] = min(low[v], disc[vv]);
		}


	if(low[v] == disc[v]){
		++sccnum;
		while(!st.empty() && st.top() != v){
			instack[st.top()] = false;
			scc_idx[st.top()] = sccnum;
			st.pop();
		}
		instack[st.top()] = false;
		scc_idx[st.top()] = sccnum;
		st.pop();
	}
}



