	ios_base::sync_with_stdio(false);
	cin.tie(0);

	int n;
	cin >> n;
	vector<ll> x(n), y(n);
	for (int i = 0; i < n; ++i) {
		cin >> x[i] >> y[i];
	}

	ll lf = 0, rg = inf;
	while (rg - lf > 1) {
		ll md = (lf + rg) >> 1;
		g = vector<vector<int> >(2 * n);
		for (int i = 0; i < n; ++i) {
			for (int j = 0; j < n; ++j) {
				if (i == j) {
					continue;
				}
				if (abs(x[i] - x[j]) < md) {
					g[i].pb(j + n);
				}
				if (abs(x[i] - y[j]) < md) {
					g[i].pb(j);
				}
				if (abs(y[i] - x[j]) < md) {
					g[i + n].pb(j + n);
				}
				if (abs(y[i] - y[j]) < md) {
					g[i + n].pb(j);
				}
			}
		}
		gr = vector<vector<int> >(2 * n);
		for (int i = 0; i < 2 * n; ++i) {
			for (int to : g[i]) {
				gr[to].pb(i);
			}
		}
		used = vector<char>(2 * n, false);
		order.clear();
		for (int i = 0; i < 2 * n; ++i) {
			if (!used[i]) {
				dfs1(i);
			}
		}
		reverse(all(order));
		compId.assign(2 * n, -1);
		int cc = 0;
		for (int v : order) {
			if (compId[v] == -1) {
				dfs2(v, cc);
				++cc;
			}
		}
		bool ok = true;
		for (int i = 0; i < n; ++i) {
			if (compId[i] == compId[i + n]) {
				ok = false;
				break;
			}
		}
		if (ok) {
			lf = md;
		} else {
			rg = md;
		}
	}

	cout << lf << "\n";

}

