int it[maxn * 4], L[maxn * 4], R[maxn * 4];
int nid = 0;
int pos[maxn];

inline int neg(int x) {
    return x <= N + nid ? x + N + nid : x - N - nid;
}

void buildTree(int x, int low, int high) {
    L[x] = low; R[x] = high;
    if (low == high) {
        it[x] = low;
        return;
    }
    int mid = (low + high) / 2;
    buildTree(x<<1, low, mid);
    buildTree(x<<1|1, mid + 1, high);
    ++nid;
    it[x] = N + nid;
    pos[it[x]] = x;
}

void createNode(int x, int low, int high, int p) {
    if (L[x] > high || R[x] < low) return;
    if (low <= L[x] && R[x] <= high) {
        if (L[x] == R[x]) {
            ver[p].push_back(neg(it[x]));
            rev[neg(it[x])].push_back(p);
        }
        else {
            ver[p].push_back(it[x]);
            rev[it[x]].push_back(p);
        }
        return;
    }
    createNode(x<<1, low, high, p);
    createNode(x<<1|1, low, high, p);
}

void buildEdge() {
    for (int i = 1; i <= (N + nid) * 2; ++i) {
        ver[i].clear();
        rev[i].clear();
    }

    // x -> not y
    // not x -> y
    // y -> not x
    // not y -> x

    for (int i = 1; i <= N; ++i) {
        ver[i].push_back(neg(a[i].y));
        rev[neg(a[i].y)].push_back(i);
//        dbs(i, neg(a[i].y));
        ver[neg(i)].push_back(a[i].y);
        rev[a[i].y].push_back(neg(i));
//        dbs(neg(i), a[i].y);
    }

    for (int i = N + 1; i <= N + nid; ++i) {
        int x = pos[i];
        int lef = L[x], rig = R[x];
        for (int j = lef; j <= rig; ++j) {
            ver[i].push_back(neg(j));
            rev[neg(j)].push_back(i);
        }
    }
}

