const int N=2e5+50;
vector <int> e[N];
vector <int> e2[N];
int n,tot,a[N],b[N],p0[N],p1[N],id[N];
struct data{
	int p,id;
	friend inline bool operator <(data a,data b) {
		return a.p<b.p || (a.p==b.p && a.id<b.id);
	}
}u[N];
inline void build(int k,int l,int r) {
	p0[k]=++tot; p1[k]=++tot;
	if(l==r) {
		add(p0[k],(a[id[l]]==l?b[id[l]]:a[id[l]]));
		add((a[id[l]]==l?b[id[l]]:a[id[l]]),p0[k]);
		add(l,p1[k]); add(p1[k],l);
		return;
	}
	int mid=(l+r)>>1;
	build(k<<1,l,mid); build(k<<1|1,mid+1,r);
	e[p0[k]].push_back(p0[k<<1]);
	e[p0[k]].push_back(p0[k<<1|1]);
	e[p1[k<<1]].push_back(p1[k]);
	e[p1[k<<1|1]].push_back(p1[k]);
}
inline void inc(int k,int l,int r,int L,int R,int v1,int v2) {
	if(L<=l&&r<=R) {
		e2[v1].push_back(p0[k]); e2[p1[k]].push_back(v2);
		return;
	} int mid=(l+r)>>1;
	if(R<=mid) inc(k<<1,l,mid,L,R,v1,v2);
	else if(L>mid) inc(k<<1|1,mid+1,r,L,R,v1,v2);
	else inc(k<<1,l,mid,L,R,v1,v2),inc(k<<1|1,mid+1,r,L,R,v1,v2);
}
int bl[N],scc,st[N],top,low[N],dfn[N],ins[N],ind;
inline int find1(int l,int r,int v) {
	int ans=r+1;
	while(l<=r) {
		int mid=(l+r)>>1;
		if(u[mid].p>=v) ans=mid, r=mid-1;
		else l=mid+1;
	} return ans;
}
inline int find2(int l,int r,int v) {
	int ans=l-1;
	while(l<=r) {
		int mid=(l+r)>>1;
		if(u[mid].p<=v) ans=mid,l=mid+1;
		else r=mid-1;
	} return ans;
}
inline void dfs(int x) {
	dfn[x]=++ind; low[x]=ind;
	st[++top]=x; ins[x]=1;
	for(auto v:e[x]) {
		if(!dfn[v]) dfs(v), low[x]=min(low[x],low[v]);
		else if(ins[v]) low[x]=min(low[x],dfn[v]);
	}
	for(auto v:e2[x]) {
		if(!dfn[v]) dfs(v), low[x]=min(low[x],low[v]);
		else if(ins[v]) low[x]=min(low[x],dfn[v]);
	}
	if(low[x]==dfn[x]) {
		int u; ++scc;
		do {
			u=st[top--];
			ins[u]=0; bl[u]=scc;
		} while(u!=x);
	}
}
inline bool check(int v) {
	ind=0; scc=0; top=0;
	for(int i=1;i<=tot;i++) e2[i].clear(), dfn[i]=0;
	for(int i=1;i<=n;i++) {
		int l=find1(1,a[i]-1,u[a[i]].p-v+1), r=find2(a[i]+1,2*n,u[a[i]].p+v-1);
