const int OFF = (1 << 15);
vector <int> ve[OFF * 2];
int bio[2 * OFF], low[2 * OFF], scc[2 * OFF];
int cnt = 0, ind = 0, n;
stack <int> st;
int on_stack[2 * OFF];
int index[2 * OFF];
vector <pii> tmp;

void dfs(int x) {
  bio[x] = low[x] = cnt++;
  st.push(x);
  on_stack[x] = 1;

  for (int y : ve[x]) {
    if (bio[y] == -1) {
      dfs(y);
      low[x] = min(low[x], low[y]); 
    } else if (on_stack[y]) {
      low[x] = min(low[x], bio[y]);
    }
  }

  if (low[x] == bio[x]) {
    while (st.size()) {
      int y = st.top();
      st.pop();
      on_stack[y] = 0;
      scc[y] = ind;
      if (y == x) break;
    }
    ind++;
  }

  return;
}

void tarjan(int N) {
  cnt = 1, ind = 0;
  memset(scc, -1, sizeof scc);
  memset(bio, -1, sizeof bio);

  REP(i, N) {
    if (bio[i] == -1) dfs(i);
  }

  return;
}

void connect(int a, int b, int k, int lo = 0, int hi = OFF, int x = 1) {
  if (b <= lo || hi <= a) return;
  if (a <= lo && hi <= b) {
    ve[k].push_back(x);
    return;
  }

  int mi = (lo + hi) / 2;
  connect(a, b, k, lo, mi, x * 2);
  connect(a, b, k, mi, hi, x * 2 + 1);

  return;
}

void generate(int D) {
  REP(i, OFF) ve[i + OFF].clear();

  int l = 0, r = 0;
  REP(i, 2 * n) {
    while (tmp[l].X < tmp[i].X - D) l++;
    while (r < 2 * n && tmp[r].X <= tmp[i].X + D) r++;

    connect(l + 2 * n, i + 2 * n, i + OFF);
    connect(i + 1 + 2 * n, r + 2 * n, i + OFF);
  }

  REP(i, n) {
    int a = index[2 * i];
    int b = index[2 * i + 1];

    ve[a + OFF].push_back(b + 2 * n + OFF);
    ve[b + OFF].push_back(a + 2 * n + OFF);
    ve[b + 2 * n + OFF].push_back(a + OFF);
    ve[a + 2 * n + OFF].push_back(b + OFF);
  }

  return;
}

