struct SCC
{
	const int INF = int(1e9);
	vector<vector<int> > vec;
	int index;
	vector<int> idx;
	vector<int> lowlink;
	vector<bool> onstack;
	stack<int> s;
	vector<int> sccidx;
	int scccnt;
	vi topo;

	//lower sccidx means appear later
	void init(int n)
	{
		idx.assign(n,-1);
		index = 0;
		onstack.assign(n,0);
		lowlink.assign(n,INF);
		while(!s.empty()) s.pop();
		sccidx.assign(n,-1);
		scccnt = 0;
		vec.clear();
		vec.resize(n);
	}

	void addedge(int u, int v) //u -> v
	{
		vec[u].pb(v);
	}

	void connect(int u)
	{
		idx[u] = index;
		lowlink[u] = index;
		index++;
		s.push(u);
		onstack[u] = true;
		for(int i = 0; i < vec[u].size(); i++)
		{
			int v = vec[u][i];
			if(idx[v] == -1)
			{
				connect(v);
				lowlink[u] = min(lowlink[u], lowlink[v]);
			}
			else if(onstack[v])
			{
				lowlink[u] = min(lowlink[u], idx[v]);
			}
		}
		if(lowlink[u] == idx[u])
		{
			while(1)
			{
				int v = s.top();
				s.pop();
				onstack[v] = false;
				sccidx[v] = scccnt;
				if(v == u) break;
			}
			scccnt++;
		}
	}

	void tarjan()
	{
		for(int i = 0; i < vec.size(); i++)
		{
			if(idx[i] == -1)
			{
				connect(i);
			}
		}
	}

	void toposort() //if graph is a DAG and i just want to toposort
	{
		tarjan();
		int n = vec.size();
		topo.resize(n);
		vector<ii> tmp;
		for(int i = 0; i < n; i++)
		{
			tmp.pb(mp(sccidx[i],i));
		}
		sort(tmp.begin(),tmp.end());
		reverse(tmp.begin(),tmp.end());
		for(int i = 0; i < n; i++)
		{
			topo[i]=tmp[i].se;
			if(i>0) assert(tmp[i].fi!=tmp[i-1].fi);
		}
	}
};

int n; 
SCC scc; 

void build() 
{  // build the tree
	for (int i = 2*n - 1; i > 0; --i) 
	{
		scc.addedge(2*(2*n+(i<<1)), 2*(2*n+i));
		scc.addedge(2*(2*n+i)+1, 2*(2*n+(i<<1))+1);
		scc.addedge(2*(2*n+(i<<1)+1), 2*(2*n+i));
		scc.addedge(2*(2*n+i)+1, 2*(2*n+(i<<1)+1)+1);
	  //t[i] = t[i<<1] + t[i<<1|1];
	}
}

void add(int v, int l, int r) 
{  // add on interval [l, r)
	//cerr<<"DO : "<<v<<' '<<l<<' '<<r<<'\n';
	v+=2*n;
  for (l += 2*n, r += 2*n; l < r; l >>= 1, r >>= 1) {
	  //cerr<<"NODE : "<<l<<' '<<r<<' '<<v<<'\n';
    if (l&1) 
    {
		//cerr<<"ADD : "<<2*n+v<<' '<<2*n+l<<'\n';
		scc.addedge(2*(2*n+v), 2*(2*n+l)+1);
		//res += t[l++];
		l++;
	}
    if (r&1) 
    {
		r--;
		//cerr<<"ADD : "<<2*n+v<<' '<<2*n+r<<'\n';
		scc.addedge(2*(2*n+v), 2*(2*n+r)+1);
	}
  }
}

