const int N = 20000;
const int oo = 0x3f3f3f3f;

template<typename T> T read() {
    T n(0), f(1);
    char ch = getchar();
    for(;!isdigit(ch); ch = getchar()) if(ch == '-') f = -1;
    for(; isdigit(ch); ch = getchar()) n = n * 10 + ch - 48; 
    return n * f;
}

int n, cnt;
pii t[N + 5];
int x[N + 5], y[N + 5];

vector<int> G[(N << 1) + 5];
void addedge(int u, int v) { G[u].pb(v); }

int stk[(N << 1) + 5], top;
int bel[(N << 1) + 5], scc_cnt;
int dfn[(N << 1) + 5], low[(N << 1) + 5], dfs_clock;

void dfs(int u) {

    stk[top ++] = u;
    low[u] = dfn[u] = ++ dfs_clock;

    for(int i = 0; i < int(G[u].size()); ++i) {
        int v = G[u][i];
        if(!dfn[v]) {
            dfs(v);
            chkmin(low[u], low[v]);
        }else if(!bel[v]) {
            chkmin(low[u], dfn[v]);
        }
    }

    if(low[u] == dfn[u]) {
        ++ scc_cnt;
        do {
            bel[stk[top - 1]] = scc_cnt;
        } while(stk[-- top] != u);
    }
}

bool scc_chk() {
    memset(bel, 0, sizeof bel);
    memset(dfn, 0, sizeof dfn);
    top = scc_cnt = dfs_clock = 0;

    for(int i = 0; i <= (N << 1); ++i) if(!dfn[i]) { dfs(i); }
    for(int i = 1; i <= n; ++i) if(bel[N - i] == bel[N + i]) return false;
    return true;
}

bool chk(int len) {
    for(int i = 0; i <= (N << 1); ++i) G[i].clear();
    for(int i = 0; i < cnt; ++i) {
        int K = 0;
        for(int j = i-1; j >= 0 && t[i].fst - t[j].fst < len; --j) {
            addedge(N + t[i].snd, N - t[j].snd);
            addedge(N + t[j].snd, N - t[i].snd);
            if(++ K >= 100) break;
        }
        K = 0;
        for(int j = i+1; j < cnt && t[j].fst -t[i].fst < len; ++j) {
            addedge(N + t[i].snd, N - t[j].snd);
            addedge(N + t[j].snd, N - t[i].snd);
            if(++ K >= 100) break;
        }
    }
    return scc_chk();
}

int main() {


    scanf("%d", &n);
    int lim = oo / (n - 1);
    for(int i = 1; i <= n; ++i) {
        scanf("%d%d", x + i, y + i);

        t[cnt ++] = mp(x[i], i);
        t[cnt ++] = mp(y[i], -i);
    }
    for(int i = 1; i <= n; ++i) 
        for(int j = i + 1; j <= n; ++j) {
            int a = abs(max(x[i], y[i]) - min(x[j], y[j]));
            int b = abs(max(x[j], y[j]) - min(x[i], y[i]));
            chkmin(lim, max(a, b));
        }

    sort(t, t + cnt);

    int l = 0, r = lim, ans = -1;
    while(l <= r) {
        int mid = (l + r) >> 1;
        if(chk(mid)) ans = mid, l = mid + 1; else r = mid - 1;
    }

    printf("%d\n", ans);
    return 0;
}

