typedef pair<int,int> P;
const int MAXN=1e6+10;
int L[MAXN],R[MAXN];
int head[MAXN],preh[MAXN],pret,tot;
int n,x[MAXN],y[MAXN],nd;P dsp[MAXN];
struct edge{int nxt,to;}e[MAXN<<2];
void add(int x,int y)
{e[++tot]=(edge){head[x],y};head[x]=tot;}

int cnt,top,st[MAXN],bel[MAXN];
int idx,low[MAXN],dfn[MAXN],vis[MAXN],ist[MAXN];
void tarjan(int x)
{
    st[++top]=x;
    ist[x]=vis[x]=1;
    low[x]=dfn[x]=++idx;

    for(int i=head[x];i;i=e[i].nxt)
        if(!vis[e[i].to]) 
            tarjan(e[i].to),low[x]=min(low[x],low[e[i].to]);
        else if(ist[e[i].to])
            low[x]=min(low[x],low[e[i].to]);
    if(low[x]==dfn[x])
    {
        cnt++;
        while(st[top]!=x)
            bel[st[top]]=cnt,ist[st[top]]=0,top--;
        bel[st[top]]=cnt;ist[st[top]]=0;top--;
    }
}

#define mid ((l+r)>>1)
#define ls k<<1
#define rs k<<1|1
#define lc k<<1,l,mid
#define rc k<<1|1,mid+1,r
int id[MAXN];
void build(int k,int l,int r)
{
    if(l==r)
    {id[k]=(dsp[l].Y)>n?dsp[l].Y-n:dsp[l].Y+n;return;}
    id[k]=++nd;build(lc);build(rc);
    add(id[k],id[ls]);add(id[k],id[rs]);
}
void upd(int a,int b,int x,int k,int l,int r)
{
    if(a>b) return;
    if(a<=l&&r<=b){add(x,id[k]);return;}
    if(a<=mid) upd(a,b,x,lc);
    if(b>mid) upd(a,b,x,rc);
}

bool check(int itv)
{
    int cur=1;
    for(int i=1;i<=2*n;i++)
    {
        while(cur<=2*n&&dsp[cur].X-dsp[i].X<itv) cur++;
        R[dsp[i].Y]=cur-1;
    }
    cur=2*n;
    for(int i=2*n;i>=1;i--)
    {
        while(cur>=1&&dsp[i].X-dsp[cur].X<itv) cur--;
        L[dsp[i].Y]=cur+1;
    }
    // for(int i=1;i<=2*n;i++)
    //     cout<<i<<" "<<L[dsp[i].Y]<<" "<<R[dsp[i].Y]<<endl;

    tot=pret;cnt=top=idx=0;
    for(int i=1;i<=nd;i++) 
        head[i]=preh[i],vis[i]=ist[i]=bel[i]=low[i]=dfn[i]=0;
    for(int i=1;i<=2*n;i++)
        upd(L[i],i-1,i,1,1,2*n),upd(i+1,R[i],i,1,1,2*n);
    for(int i=1;i<=nd;i++)
        if(!vis[i]) tarjan(i);
    // for(int i=1;i<=nd;i++) cout<<bel[i]<<" ";
    // cout<<endl;

    for(int i=1;i<=n;i++)
        if(bel[i]==bel[i+n]) return false;
    return true;
}

int main()
{
    scanf("%d",&n);
    for(int i=1;i<=n;i++)
        scanf("%d%d",&x[i],&y[i]),
        dsp[++nd]=P(x[i],i),dsp[++nd]=P(y[i],i+n);
    sort(dsp+1,dsp+nd+1);nd=2*n;build(1,1,2*n);
    pret=tot;for(int i=1;i<=nd;i++) preh[i]=head[i];

    int l=0,r=1e9;
    while(l<=r)
    {
        int m=(l+r)>>1;
        if(check(m)) l=m+1;
        else r=m-1;
    }
    printf("%d",r);
    return 0;
}

#include <cstdio>
#include <algorithm>
#include <cstring>
using namespace std;

#define clear(x) memset(x, 0, sizeof(x))
#define op(x) ((x) <= n ? (x) + n : (x) - n)
// op可以求出一个点x的对立点
#define mid ((l + r) / 2)
#define ls now * 2
#define rs now * 2 + 1

const int N = 4e4 + 10, M = N * 20;

int hd[N * 5], nxt[M], t[M], ec;
void addEdge(int u, int v)
{
	t[++ec] = v;
	nxt[ec] = hd[u];
	hd[u] = ec;
}
struct Flag {
	int pos, id;
	bool operator<(const Flag& f) const {
		return pos < f.pos;
	}
	Flag(int pos = 0): pos(pos) {}
} flgs[N * 2];

int n;
int cnt;
int id[N * 5];

void build(int now, int l, int r)
{
	id[now] = ++cnt;
	if (l == r) {
		addEdge(id[now], op(flgs[l].id));
		// 由“占位符”向真实点的对立点连边
		return;
	}
	build(ls, l, mid);
	build(rs, mid + 1, r);
	addEdge(id[now], id[ls]);
	addEdge(id[now], id[rs]);
	// 由父亲向儿子连边
}

void link(int now, int l, int r, int x, int y, int point)
{
	// 由point向区间[x,y]连边
	if (y < x) return;
	if (l == x && y == r) addEdge(point, id[now]);
	else if (y <= mid) link(ls, l, mid, x, y, point);
	else if(x > mid) link(rs, mid + 1, r, x, y, point);
	else link(ls, l, mid, x, mid, point), link(rs, mid + 1, r, mid + 1, y, point);
}

#undef mid

int dfn[N * 5], low[N * 5], tim;
int stk[N * 5], tp;
int scc[N * 5], sc;
bool in[N * 5];

void dfs(int u)   // Tarjan算法 强连通分量
{
	in[u] = 1;
	dfn[u] = low[u] = ++tim;
	stk[++tp] = u;
	int v;
	for (int i = hd[u]; i; i = nxt[i]) {
		if (!dfn[v = t[i]]) dfs(v), low[u] = min(low[u], low[v]);
		else if (in[v]) low[u] = min(low[u], dfn[v]);
	}
	if (dfn[u] == low[u]) {
		++sc;
		do {
			scc[v = stk[tp--]] = sc;
			in[v] = 0;
		} while (v != u);
	}
}

bool check(int v)
{
	tp = tim = ec = 0;
	clear(hd), clear(dfn), clear(low);
	build(1, 1, cnt = 2 * n);
	int l, r;
	for (int i = 1; i <= 2 * n; i++) {
		l = upper_bound(flgs + 1, flgs + 1 + 2 * n, Flag(flgs[i].pos - v)) - flgs;
		r = upper_bound(flgs + 1, flgs + 1 + 2 * n, Flag(flgs[i].pos + v - 1)) - flgs - 1;
		link(1, 1, 2 * n, l, i - 1, flgs[i].id), link(1, 1, 2 * n, i + 1, r, flgs[i].id);
	}
	for (int i = 1; i <= 2 * n; i++) if (!dfn[i]) dfs(i);
	for (int i = 1; i <= n; i++) if(scc[i] == scc[i + n]) return 0;
	// 判断x与y是否在同一个强连通分量内
	return 1;
}

int main()
{
	scanf("%d", &n);
	for (int i = 1; i <= n; i++) {
		scanf("%d%d", &flgs[i].pos, &flgs[i + n].pos);
		flgs[i].id = i, flgs[i + n].id = i + n;
	}

	sort(flgs + 1, flgs + n * 2 + 1);

	int l = 0, r = flgs[2 * n].pos - flgs[1].pos + 1, mid, ans;
	while (l <= r) { // 二分
		mid = (l + r) / 2;
		if (check(mid)) l = mid + 1, ans = mid;
		else r = mid - 1;
	}

	printf("%d", ans);
}

