#include <bits/stdc++.h>

const int N = 100005, M = 9999999;
typedef std::pair<int, int> pair;

int n, idx, lc[N], rc[N], root;
pair p[N];

int head[N], tot; struct edge { int to, nxt; } e[M];
void link(int x, int y) {e[++tot] = (edge) {y, head[x]}, head[x] = tot;}
void implies(int x, int y) {link(x, y), link(y ^ 1, x ^ 1);}

int build(int l = 0, int r = n * 2 - 1) {
	if (l == r) return p[l].second;
	int mid = l + r >> 1, now = idx; idx += 2;
	implies(lc[now] = build(l, mid), now);
	implies(rc[now] = build(mid + 1, r), now);
	return now;
}

void query(int L, int R, int p, int rt = root, int l = 0, int r = n * 2 - 1) {
	if (L <= l && R >= r) return implies(rt, p);
	int mid = l + r >> 1;
	if (L <= mid) query(L, R, p, lc[rt], l, mid);
	if (R > mid) query(L, R, p, rc[rt], mid + 1, r);
}

int _tot, _head[N];
void save() {_tot = tot, std::memcpy(_head, head, idx << 2);}
void load() {tot = _tot, std::memcpy(head, _head, idx << 2);}

int dfn[N], low[N], clk, stack[N], top, scc, bel[N]; bool ins[N];

void init() {std::memset(dfn, 0, idx << 2), clk = scc = 0;}
void tarjan(int x) {
	dfn[x] = low[x] = ++clk, ins[stack[++top] = x] = 1;
	for (int i = head[x]; i; i = e[i].nxt)
		if (!dfn[e[i].to])
			tarjan(e[i].to), low[x] = std::min(low[x], low[e[i].to]);
		else if (ins[e[i].to])
			low[x] = std::min(low[x], dfn[e[i].to]);
	if (dfn[x] == low[x]) {
		int v; ++scc;
		do ins[v = stack[top--]] = 0, bel[v] = scc; while (v != x);
	}
}

int x[N], y[N];
bool check(int mid) {
	--mid, load(), init();
	int L = 0, R = 0;
	for (int i = 0; i < n + n; ++i) {
		while (R + 1 < n + n && p[R + 1].first - p[i].first <= mid) ++R;
		while (p[i].first - p[L].first > mid) ++L;
		if (L < i) query(L, i - 1, p[i].second ^ 1);
		if (i < R) query(i + 1, R, p[i].second ^ 1);
	}
	for (int i = 0; i < idx; ++i) if (!dfn[i]) tarjan(i);
	for (int i = 0; i < idx; i += 2) if (bel[i] == bel[i ^ 1]) return 0;
	return 1;
}

int main() {
	std::ios::sync_with_stdio(0), std::cin.tie(0);
	std::cin >> n, idx = n * 2;
	for (int i = 0; i < n; ++i)
		std::cin >> x[i] >> y[i], p[i << 1] = pair(x[i], i << 1), p[i << 1 | 1] = pair(y[i], i << 1 | 1);
	std::sort(p, p + idx), root = build(), save();
	int l = 1, r = 1e9, ans = 0;
	while (l <= r) {
		int mid = l + r >> 1;
		if (check(mid)) ans = mid, l = mid + 1;
		else r = mid - 1;
	}
	std::cout << ans << '\n';
	return 0;
}

