const int MAXN = 20001;
int dn;
vector<int> graph[MAXN];
int up[MAXN], visit[MAXN], vtime;
vector<int> stk;
int scc_idx[MAXN], scc_cnt;

void dfs(int nod) {
	up[nod] = visit[nod] = ++vtime;
	stk.push_back(nod);
	for (int next : graph[nod]) {
		if (visit[next] == 0) {
			dfs(next);
			up[nod] = min(up[nod], up[next]);
		}
		else if (scc_idx[next] == 0)
			up[nod] = min(up[nod], visit[next]);
	}
	if (up[nod] == visit[nod]) {
		++scc_cnt;
		int t;
		do {
			t = stk.back();
			stk.pop_back();
			scc_idx[t] = scc_cnt;
		} while (!stk.empty() && t != nod);
	}
}
// find SCCs in given directed graph
// O(V+E)
void get_scc() {
	vtime = 0;
	memset(visit, 0, sizeof(visit));
	scc_cnt = 0;
	memset(scc_idx, 0, sizeof(scc_idx));
	for (int i = 0; i < dn; ++i)
		if (visit[i] == 0) dfs(i);
}

int n;
int coord[10000][2];

bool chk(int lowerlimit) {
	for (int i = 0; i < n * 2; ++i) {
		graph[i].clear();
	}
	for (int i = 0; i < n; ++i) {
		for (int j = i + 1; j < n; ++j) {

			for (int a = 0; a < 2; ++a) {
				for (int b = 0; b < 2; ++b) {
					if (abs(coord[i][a] - coord[j][b]) < lowerlimit) {
						int nodei = i * 2 + a, nodej = j * 2 + b;
						//// nodei -> !nodej , nodej -> !nodei
						graph[nodei].push_back(nodej ^ 1);
						graph[nodej].push_back(nodei ^ 1);
					}
				}
			}
		}
	}

	dn = n * 2;
	get_scc();
	for (int i = 0; i < n; ++i) {
		if (scc_idx[i * 2] == scc_idx[i * 2 + 1]) {
			return false;
		}
	}
	return true;
}

