typedef pair<int, int> pii;
typedef pair<int, pii> piii;

int n, x[10010], y[10010], chk[10010];
priority_queue<piii> pq;

bool can(int k){
	while(!pq.empty()) pq.pop();
	fill(chk + 1, chk + n + 1, 0);
	for(int i = 1; i <= n; i++){
		pq.push({x[i], {1, i}});
		pq.push({y[i], {2, i}});
	}
	int cnt = 0, lst = 2e9;
	while(!pq.empty()){
        piii cur = pq.top(); pq.pop();
        if(chk[cur.second.second]) continue;
        if(cur.first > lst - k) continue;
        chk[cur.second.second] = 1;
        cnt++;
        lst = cur.first;
	}
	return (cnt == n);
}

