inline int Get() {
	char ch;
	while ((ch = getchar()) < '0' || ch > '9');
	int Num = ch - '0';
	while ((ch = getchar()) >= '0' && ch <= '9')
		Num = (Num << 3) + (Num << 1) + ch - '0';
	return Num;
}
int n, cnt, a[CNT], to[CNT], idx[CNT];
int dfn[CNT], pre[CNT], dfs_clock, belong[CNT], total, stack[CNT], stn;
int id[CNT << 2];
int tot, first[CNT], next[CNT * 60], end[CNT * 60];
inline void AddEdge(int x, int y) {
	next[++tot] = first[x], first[x] = tot, end[tot] = y;
}
void build(int k, int l, int r) {
	id[k] = ++cnt;
	if (l == r) {
		AddEdge(id[k], idx[l]);
		return;
	}

	int mid = l + r >> 1;
	build(k << 1, l, mid), AddEdge(id[k], id[k << 1]);
	build((k << 1) | 1, mid + 1, r), AddEdge(id[k], id[(k << 1) | 1]);
}
void add(int k, int l, int r, int x, int y, int z) {
	if (x <= l && r <= y) {
		AddEdge(z, id[k]);
		return;
	}

	int mid = l + r >> 1;
	if (x <= mid) add(k << 1, l, mid, x, y, z);
	if (y > mid) add((k << 1) | 1, mid + 1, r, x, y, z);
	return;
}
void Dfs(int x) {
	dfn[x] = pre[x] = ++dfs_clock, stack[++stn] = x;
	for (int k = first[x], v; v = end[k], k; k = next[k]) 
		if (!dfn[v]) Dfs(v), pre[x] = std :: min(pre[x], pre[v]);
		else 
			if (!belong[v]) pre[x] = std :: min(pre[x], dfn[v]);

	if (dfn[x] == pre[x]) {
		++total;
		while (stack[stn] != x) 
			belong[stack[stn--]] = total;
		belong[stack[stn--]] = total;
	}
}
bool check(int x) {
	cnt = n * 2, tot = 0, dfs_clock = total = stn = 0;
	std :: memset(first, 0, sizeof(first));

	build(1, 1, n * 2);

	for (int i = 1, l = 1, r = 1; i <= n * 2; ++i) {
		while (l < i && a[idx[l]] + x <= a[idx[i]]) ++l;
		while (r < n * 2 && a[idx[r + 1]] < a[idx[i]] + x) ++r;
		if (l < i) add(1, 1, n * 2, l, i - 1, to[idx[i]]);
		if (i < r) add(1, 1, n * 2, i + 1, r, to[idx[i]]);
	}

	std :: memset(dfn, 0, sizeof(dfn));
	std :: memset(belong, 0, sizeof(belong));

	for (int i = 1; i <= cnt; ++i) if (!dfn[i]) Dfs(i);
	for (int i = 1; i <= n; ++i) 
		if (belong[i * 2] == belong[i * 2 - 1]) return false;

	return true;
}
inline bool cmp(const int &x, const int &y) {
	return a[x] < a[y];
}
int main() {
	n = Get();
	for (int i = 1; i <= n * 2; ++i) a[i] = i & 1, idx[i] = i;
	for (int i = 1; i <= n; ++i, cnt += 2) 
		to[cnt + 1] = cnt + 2, to[cnt + 2] = cnt + 1; 

	std :: sort(idx + 1, idx + n * 2 + 1, cmp);

	int l = 0, r = inf, ans = 0;
	while (l <= r) {
		int mid = l + r >> 1;
		if (check(mid)) ans = mid, l = mid + 1;
		else r = mid - 1;
	}
	printf("%d\n", ans);
}

#include <bits/stdc++.h>
using namespace std;

#define int long long

const int inf = 1e18;

struct T {
	int val, sum, mn;
	int fix, siz;
	T *lson, *rson;
	T(int v) {
		val = sum = mn = v;
		fix = rand(); siz = 1;
		lson = rson = NULL;
	}
};

void del_T(T *&x) {
	if (x -> lson) del_T(x -> lson);
	if (x -> rson) del_T(x -> rson);
	delete x; x = NULL;
}

void pushup(T *x) {
	x -> sum = x -> val;
	if (x -> lson) x -> sum += x -> lson -> sum;
	if (x -> rson) x -> sum += x -> rson -> sum;
	x -> mn = x -> val;
	if (x -> lson) x -> mn = min(x -> mn, x -> lson -> mn);
	if (x -> rson) x -> mn = min(x -> mn, x -> rson -> mn);
	x -> siz = 1;
	if (x -> lson) x -> siz += x -> lson -> siz;
	if (x -> rson) x -> siz += x -> rson -> siz;
}

void split(T *x, int k, T *&a, T *&b) {
	if (!x) {a = b = NULL; return ;}
	int lsiz = x -> lson ? x -> lson -> siz : 0;
	if (lsiz + 1 <= k) {
		a = x;
		split(x -> rson, k - lsiz - 1, a -> rson, b);
		pushup(a);
	} else {
		b = x;
		split(x -> lson, k, a, b -> lson);
		pushup(b);
	}
}

T *merge(T *a, T *b) {
	if (!a || !b) return a ? a : b;
	if (a -> fix < b -> fix) {
		a -> rson = merge(a -> rson, b);
		pushup(a);
		return a;
	} else {
		b -> lson = merge(a, b -> lson);
		pushup(b);
		return b;
	}
}

int find(T *x, int v) {
	int lsum = x -> lson ? x -> lson -> sum : 0;
	int lsiz = x -> lson ? x -> lson -> siz : 0;
	if (lsum >= v) return find(x -> lson, v);
	if (lsum + x -> val >= v) return 1 + lsiz;
	return 1 + lsiz + find(x -> rson, v - lsum - x -> val);
}

T *root;

void prt(T *x) {
	if (!x) return ;
	prt(x -> lson);
	cerr << x -> val << " ";
	prt(x -> rson);
}

void wait() {for (int i = 0; i < 1e8; ++ i) i <<= 1, i >>= 1;}
#define dbg(x) {cerr << #x << ": "; prt(x); cerr << endl; wait();}

const int N = 1e4 + 5;
int n, x[N][2], use[N];
int cur;

void del(int k) {
	// cerr << "del " << k << endl;
	T *a, *b, *c;
	int rnk = find(root, x[k][use[k]] + inf);
	split(root, rnk + 1, b, c);
	split(b, rnk - 1, a, b);
	// dbg(a); dbg(b); dbg(c);
	T *nw = new T(b -> sum);
	del_T(b); b = nw;
	root = merge(merge(a, b), c);
	// dbg(root);
}

void add(int k) {
	// cerr << "add " << k << endl;
	T *a, *b, *c;
	int rnk = find(root, x[k][use[k]] + inf);
	split(root, rnk, b, c);
	split(b, rnk - 1, a, b);
	// dbg(a); dbg(b); dbg(c);
	T *d = new T(x[k][use[k]] + inf - (a ? a -> sum : 0));
	T *e = new T((a ? a -> sum : 0) + b -> sum - x[k][use[k]] - inf);
	T *nw = merge(d, e);
	del_T(b); b = nw;
	root = merge(merge(a, b), c);
	// dbg(root);
}

void ch(int k) {
	del(k);
	use[k] ^= 1;
	add(k);
	cur = root -> mn;
}

signed main() {
	// freopen("in", "r", stdin);
	ios :: sync_with_stdio(0);
	cin.tie(0); cout.tie(0);
	cin >> n;
	for (int i = 0; i < n; ++ i)
		cin >> x[i][0] >> x[i][1];
	for (int i = 0; i < n; ++ i)
		use[i] = rand() % 2;
	multiset <int> st;
	st.insert(-inf); st.insert(inf);
	for (int i = 0; i < n; ++ i)
		st.insert(x[i][use[i]]);
	for (set <int> :: iterator it = st.begin(), oit; it != st.end(); ++ it) {
		if (it != st.begin()) root = merge(root, new T(*it - *oit));
		oit = it;
	}
	// dbg(root);
	cur = root -> mn;
	int mx = 0;
	double T = 1e5;
	while (T >= 1e-35) {
		// cerr << T << endl;
		int k = rand() % n;
		int old = cur;
		ch(k);
		int delta = cur - old;
		if (delta <= 0 && exp(delta / T) * RAND_MAX <= rand()) ch(k);
		T *= 1.0 - 3e-3; mx = max(mx, cur);
		// dbg(root);
	}
	// dbg(root);
	cout << mx << endl;
	return 0;
}

