		pos[a[i].id]=i+sz;
	}

	int lo=0,hi=1e9,mid;
	while(lo+1<hi){
		mid=(lo+hi)/2;
		if(chk(mid))lo=mid;
		else hi=mid;
	}
	printf("%d\n",lo);

	return 0;
}

