	}
	if(tl <= mid) link(u<<1, l, mid, tl, tr, p);
	if(mid < tr) link(u<<1|1, mid+1, r, tl, tr, p);
}
void tarjan(int u) {
	st[++top] = u, ins[u] = 1;
	dfn[u] = low[u] = ++idcnt;
	all_edge(u) {
		if(!dfn[*it]) tarjan(*it), low[u] = min(low[u], low[*it]);
		else if(ins[*it]) low[u] = min(low[u], dfn[*it]);
	}
	if(low[u] == dfn[u]) {
		int cur; ++ccnt;
		do {
			cur = st[top--], ins[cur] = 0;
			col[cur] = ccnt;
		} while(cur != u);
	}
}
