vector<int> S;
bool inS[MAX_N * 2];
int mark[MAX_N * 2];
int lowlink[MAX_N * 2];
int sccid[MAX_N * 2];
int sccnum;
void tarjan(int v, int &index) {
  mark[v] = lowlink[v] = index;
  index++;
  S.push_back(v); inS[v] = true;
  for(int i = 0; i < (int)g[v].size(); i++) {
    int w = g[v][i];
    if( mark[w] == -1 ) {
      tarjan(w, index);
      lowlink[v] = min(lowlink[v], lowlink[w]);
    } else if( inS[w] ) {
      lowlink[v] = min(lowlink[v], mark[w]);
    }
  }
  if( lowlink[v] == mark[v] ) {
    while( 1 ) {
      int w = S.back(); S.pop_back(); inS[w] = false;
      sccid[w] = sccnum;
      if( w == v ) break;
    }
    ++sccnum;
  }
}

void scc(int N) {
  S.clear();
  memset(sccid, -1, sizeof(sccid));
  memset(inS, 0, sizeof(inS));
  memset(mark, -1, sizeof(mark));
  sccnum = 0;
  int index = 0;
  for(int i = 0; i < 2*N; i++)
    if( mark[i] == -1 )
      tarjan(i, index);
}

