struct TwoSAT {
    int N;
    SCC scc;
    vector<int> ls;
    TwoSAT(){}
    TwoSAT(int n):N(n),scc(n*2){}
    void init(int n){
        N = n;
        scc.init(n*2);
    }
    int neg(int a){return (a+N)%(N*2);}
    void add_edge(int a, int b){
        scc.add_edge(a,b);
    }
    void add_if(int a, int b){
        // a -> b <=> !b -> !a
        add_edge(a,b);
        add_edge(neg(b),neg(a));
    }
    void add_iff(int a, int b){
        // (a <=> b) <=> a -> b and b -> a
        add_edge(a,b);
        add_edge(b,a);
    }
    void add_or(int a, int b){
        // a or b <=> !a -> b and !b -> a
        add_if(neg(a),b);
    }
    void add_nand(int a, int b){
        // a nand b <=> a -> !b and b -> !a
        add_if(a, neg(b));
    }
    void add_xor(int a, int b){
        add_nand(a, b);
        add_or(a,b);
    }
    void set_true(int a){
        // a <=> !a -> a
        add_edge(neg(a), a);
    }
    void set_false(int a){
        // !a <=> a -> !a
        add_edge(a, neg(a));
    }
    bool build(){
        scc.build();
        bool ok = true;
        for(int i=0;i<N;i++){
            ok &= scc.i2g[i] != scc.i2g[neg(i)];
        }
        if(ok){
            for(int i=0;i<N;i++){
                if(scc.i2g[i] > scc.i2g[neg(i)]){
                    ls.push_back(1);
                }
                else{
                    ls.push_back(0);
                }
            }
        }
        return ok;
    }
};

int n, m = 1;
vector<P> pos;

void add(int a, int b, int x, int l, int r, int k, TwoSAT &ts){
    if(r <= a || b <= l) return;
    else if(a <= l && r <= b){
        ts.add_nand(x, k);
    }
    else{
        add(a,b,x,l,(l+r)/2,k*2+1,ts);
        add(a,b,x,(l+r)/2,r,k*2+2,ts);
    }
    return;
}

bool f(ll mid, TwoSAT ts){
    // i番目の葉の頂点から[i+1,j)にNANDの辺を張る
    for(int i=0;i<n*2;i++){
        int j = lower_bound(pos.begin(),pos.end(),P(pos[i].first+mid,-1)) - pos.begin();
        add(i+1,j,i+m-1,0,m,0,ts);
    }
    return ts.build();
}



