bool cmp ( int x1 , int x2 ) {
	int y1 , y2;
	if ( x1 < 0 ) y1 = y[-x1];
	else y1 = x[x1];
	if ( x2 < 0 ) y2 = y[-x2];
	else y2 = x[x2];
