}
void add ( int u , int v ) {
	node *tmp = &pooln[++topn];
	tmp -> v = v; tmp -> next = g[u]; g[u] = tmp;
	//printf ( "%d  %d\n" , u , v );
}
void buildtree ( tree *id , int l , int r ) {
	id -> l = l; id -> r = r;
	if ( l == r ) {
		if ( mix[l] > 0 ) add ( 2 * n + id -> i , mix[l] * 2 );
		else add ( 2 * n + id -> i , (-mix[l]) * 2 - 1 );
		return ;
	}
	int mid = (l+r)/2;
	id -> ll = &poolt[++topt]; id -> ll -> i = topt;
	id -> rr = &poolt[++topt]; id -> rr -> i = topt;
	buildtree ( id -> ll , l , mid );
	buildtree ( id -> rr , mid + 1 , r );
	add ( 2 * n + id -> i , 2 * n + id -> ll -> i );
	add ( 2 * n + id -> i , 2 * n + id -> rr -> i );
}
void change ( tree *id , int l , int r , int from ) {
	if ( id -> l == l && id -> r == r ) {
		add ( from , 2 * n + id -> i );
		return ;
	}
	int mid = (id->l+id->r)/2;
	if ( r <= mid ) change ( id -> ll , l , r , from );
	else {
		if ( l > mid ) change ( id -> rr , l , r , from );
		else {
			change ( id -> ll , l , mid , from );
			change ( id -> rr , mid + 1 , r , from );
		}
	}
}
void tarjan ( int i ) {
	dfn[i] = low[i] = ++index;
	stack[++tops] = i;
	ins[i] = 1;
	for ( node *j = g[i] ; j ; j = j -> next ) {
		if ( dfn[j->v] ) {
			if ( ins[j->v] )low[i] = min ( low[i] , dfn[j->v] );
		}
		else {
			tarjan ( j -> v );
			low[i] = min ( low[i] , low[j->v] );
		}
	}
	if ( low[i] == dfn[i] ) {
		color++;
		while ( stack[tops] != i ) {
			col[stack[tops]] = color;
			ins[stack[tops]] = 0;
			tops--;
		}
		col[i] = color;
		ins[i] = 0;
		tops--;
	}
}
int check ( int ans ) {
