	scanf("%d",&n);
	for(int i=0;i<n;i++)
	{
		scanf("%d%d",&sv[i].x,&sv[i].y);
		tmp[cnt++]=sv[i].x,tmp[cnt++]=sv[i].y;
	}
	sort(tmp,tmp+cnt);
	int l=1,r=1e9,ans=0;
	for(int i=0;i<n-1;i++)
	{
		r=min(r,tmp[i+n+1]-tmp[i]);
	}
	while(l<=r)
	{
		int mid=(l+r)>>1;
		if(judge(mid))
		{
			ans=max(ans,mid);
			l=mid+1;
		}
		else
		{
			r=mid-1;
		}
	}
	printf("%d\n",ans);
	return 0;
}

