namespace twosat{
	int k,clk,nscc,low[PNUM],dfn[PNUM],isc[PNUM],fi[PNUM],b[M],ne[M];
	stack<int> s;
	void clear(){
		k=clk=nscc=0; for (int i=1; i<=pnum; i++) dfn[i]=isc[i]=low[i]=fi[i]=0;
	}
	void add(int x,int y){
		b[++k]=y; ne[k]=fi[x]; fi[x]=k;
	}
	namespace zkw{
		int st[N<<2];
		void init(){
			for (u=1; u<(n<<1); u<<=1); --u;
		}
		void link(int now,int s,int t){
			if (s>t) return;
			now+=u;
			for (s+=u-1,t+=u+1; s^t^1; s>>=1,t>>=1){
				if (~s&1) add(now,s^1);
				if (t&1) add(now,t^1);
			}
		}
	}
	void tajan(int x){
		dfn[x]=low[x]=++clk;
		s.push(x);
		for (int j=fi[x]; j; j=ne[j]){
			if (!dfn[b[j]]) tajan(b[j]);
			if (!isc[b[j]]) low[x]=min(low[x],low[b[j]]);
		}
		if (dfn[x]==low[x]){
			++nscc;
			while (1){
				int u=s.top(); s.pop();
				isc[u]=nscc;
				if (u==x) break;
			}
		}
	}
}
void unite(int ovo){
	for (int i=1; (i<<1)<=pnum; i++){
		twosat::add(i,i<<1);
		if ((i<<1|1)<=pnum) twosat::add(i,i<<1|1);
	}
	for (vit i=g.begin(); i!=g.end(); ++i){
		int lp=upper_bound(g.begin(),g.end(),make_pair(i->first-ovo,C))-g.begin()+1;
		int rp=lower_bound(g.begin(),g.end(),make_pair(i->first+ovo,0))-g.begin();
		twosat::zkw::link(po[i-g.begin()+1],lp,i-g.begin());
		twosat::zkw::link(po[i-g.begin()+1],i-g.begin()+2,rp);
	}
}
