template <typename T>
struct TopologicalSort{
  bool is_dag;
  std::vector<int> result;

  TopologicalSort(const Graph<T> &g){
    int n = g.size();
    std::vector<int> indeg(n);

    for(int i = 0; i < n; ++i){
      for(auto &e : g[i]){
        ++indeg[e.to];
      }
    }

    std::queue<int> q;
    for(int i = n-1; i >= 0; --i){
      if(indeg[i] == 0) q.push(i);
    }

    while(!q.empty()){
      int cur = q.front(); q.pop();
      result.push_back(cur);
      for(auto &e : g[cur]){
        --indeg[e.to];
        if(indeg[e.to] == 0){
          q.push(e.to);
        }
      }
    }

    is_dag = (int)result.size() == n;
  }

  const int operator[](int i) const {return result[i];}
};


template <typename T>
struct SCC{
  const int n;
  std::vector<int> component;
  int scc_size;

private:
  std::vector<bool> visit;
  std::vector<int> check;

  void dfs(int cur, const Graph<T> &graph){
    visit[cur] = true;
    for(auto &e : graph[cur]){
      if(not visit[e.to]) dfs(e.to,graph);
    }
    check.push_back(cur);
  }

  void rdfs(int cur, int i, const Graph<T> &rgraph){
    component[cur] = i;
    for(auto &e : rgraph[cur]){
      if(component[e.to] == -1) rdfs(e.to,i,rgraph);
    }
  }

public:
  SCC(const Graph<T> &graph): n(graph.size()), component(n,-1), visit(n){
    for(int i = 0; i < n; ++i) if(!visit[i]) dfs(i,graph);
    std::reverse(check.begin(), check.end());

    Graph<T> rgraph(n);
    for(int i = 0; i < n; ++i) for(auto &e : graph[i]) rgraph[e.to].push_back(e.rev());

    int i = 0;
    for(auto c : check) if(component[c] == -1) {rdfs(c,i,rgraph); ++i;}
    scc_size = i;
  }

  const int operator[](int i) const {return component[i];}
};


class TwoSat{
  const int n;
  Graph<int> g;

  int f(int i){
    assert(i != 0);
    assert(abs(i) <= n);
    if(i > 0) return i-1;
    else return abs(i)-1 + n;
  }

public:
  TwoSat(int n): n(n), g(2*n){}

  /**
   * @brief a→bを導入する
   */
  void add_if(int a, int b){
    add_edge(g, f(a), f(b), 1);
    add_edge(g, f(-b), f(-a), 1);
  }

  /**
   * @brief a∨bを導入する
   * @note a ∨ b <=> (!a => b) ∧ (!b => a)
   */
  void add_or(int a, int b){
    add_if(-a, b);
    //add_if(-b, a);
  }

  /**
   * @brief ¬(a∧b)を導入する
   * @note !(A ∧ B) <=> (!A ∨ !B)
   */
  void not_coexist(int a, int b){
    add_or(-a, -b);
  }

public:
  bool solve(std::vector<bool> &ret) const {
    auto scc = SCC<int>(g);

    for(int i = 0; i < n; ++i){
      if(scc[i] == scc[i+n]) return false;
    }

    int m = scc.scc_size;

    Graph<int> g2(m);

    for(int i = 0; i < 2*n; ++i){
      for(auto &e : g[i]){
        if(scc[e.from] != scc[e.to]){
          add_edge(g2, scc[e.from], scc[e.to], 1);
        }
      }
    }

    auto ts = TopologicalSort<int>(g2);

    std::vector<int> r(m);
    for(int i = 0; i < m; ++i) r[ts[i]] = i;

    ret.assign(n, false);
    for(int i = 0; i < n; ++i) ret[i] = r[scc[i]] > r[scc[i+n]];

    return true;
  }
};





