class SAT {
public:
  static const int MAX_V = 20480;
  vector<int> g[MAX_V], rg[MAX_V], vs;
  bool used[MAX_V];
  int cmp[MAX_V], V, N;

  SAT (int n) : V(2 * n), N(n) {;}

  //(X_2 | !X_5) -> add_closure(2, 1, 5, 0)
  void add_closure(int i, bool bi, int j, bool bj) {
    add_edge(i + N * !bi, j + N * bj);
    add_edge(j + N * !bj, i + N * bi);
  }

  void add_edge(int from, int to) {
    g[from].push_back(to);
    rg[to].push_back(from);
  }

  void dfs(int v) {
    used[v] = true;
    for (int i : g[v]) if (!used[i]) dfs(i);
    vs.push_back(v);
  }

  void rdfs(int v, int k) {
    used[v] = true; cmp[v] = k;
    for (int i : rg[v]) if (!used[i]) rdfs(i, k);
  }

  //no solution: {}, else {1, 0, 1,...}
  bool solve() {
    memset(used, 0, sizeof(used));
    vs.clear();
    REP(v, V) if (!used[v]) dfs(v);
    memset(used, 0, sizeof(used));
    reverse(ALL(vs));
    int k = 0;
    for (int i : vs) if (!used[i]) rdfs(i, k++);
    vector<bool> res;
    REP(i, N) if (cmp[i] == cmp[i + N]) return false;
    return true;
  }
};

void solve(ll N, vector<ll> x, vector<ll> y) {
  vector<tuple<ll,int,bool,int,bool>> costs;
  costs.reserve(N * N * 4);
  REP(i,N) REP(j,i) {
    costs.emplace_back(abs(x[i] - x[j]), i, true, j, true);
    costs.emplace_back(abs(x[i] - y[j]), i, true, j, false);
    costs.emplace_back(abs(y[i] - x[j]), i, false, j, true);
    costs.emplace_back(abs(y[i] - y[j]), i, false, j, false);
  }
  sort(ALL(costs));
  int lb = 0, ub = costs.size();
  while (ub - lb > 1) {
    SAT sat(N);
    int mid = (lb + ub) / 2;
    REP(p,mid) {
      int i, j;
      bool bi, bj;
      tie(ignore, i, bi, j, bj) = costs[p];
      sat.add_closure(i, bi, j, bj);
    }
    if (sat.solve()) lb = mid; else ub = mid;
  }
  // cout << ub << endl;
  // cout << costs.size() << endl;
  cout << get<0>(costs[ub]) << endl;
}

