int n,X[20005],C[20005];
bool v[20005];
std::set<pii> S;
std::vector<int> T;

void DFS1(int p,int d)
{
    bool Flag=false;
    for(v[p]=1;;)
    {
        auto it=S.lower_bound(pii(X[p]-d+1,-1));
        if(Flag)
        {
            if(it==S.end())break;
            else ++it;
        }
        if(it==S.end()||it->first>=X[p]+d)break;
        int t=it->second;
        if(t==p)Flag=true;
        else if(S.erase(it),!v[t^1])DFS1(t^1,d);
    }
    T.push_back(p);
}

void DFS2(int p,int d,int s)
{
    bool Flag=false;
    for(v[p]=1,C[p]=s;;)
    {
        auto it=S.lower_bound(pii(X[p^1]-d+1,-1));
        if(Flag)
        {
            if(it==S.end())break;
            else ++it;
        }
        if(it==S.end()||it->first>=X[p^1]+d)break;
        int t=it->second;
        if(t==(p^1))Flag=true;
        else if(S.erase(it),!v[t])DFS2(t,d,s);
    }
}

bool Check(int d)
{
    S.clear();
    for(int i=0;i<(n<<1);++i)S.insert(pii(X[i],i)),v[i]=0;
    for(int i=0;i<(n<<1);++i)if(!v[i])DFS1(i,d);
    S.clear();
    for(int i=0;i<(n<<1);++i)S.insert(pii(X[i],i)),v[i]=0;
    for(int s=0;!T.empty();T.pop_back())if(!v[T.back()])DFS2(T.back(),d,++s);
    for(int i=0;i<n;++i)if(C[i<<1]==C[i<<1|1])return false;
    return true;
}

