pair<int,int>p[21000];

vector<int>scc_g[100100];
vector<int>scc_rev[100100];
int v[100100]; // used twice
int num[100100]; // inverse of conv
int conv[100100]; // dfs order of i-th vertex. note that it's kaerigake ordered
int scc[100100]; // the index of scc containing i-th vertex
int fi[100100]; // the first element of each scc
int ss[100100]; // size of each scc
int cur;
void dfs(int a){
	for(int i=0;i<scc_g[a].size();i++){
		if(v[scc_g[a][i]])continue;
		v[scc_g[a][i]]=1;
		dfs(scc_g[a][i]);
	}
	conv[a]=cur;
	num[cur++]=a;
}
void dfs2(int a){
	scc[a]=cur;
	ss[cur]++;
	for(int i=0;i<scc_rev[a].size();i++){
		if(v[scc_rev[a][i]])continue;
		v[scc_rev[a][i]]=1;
		dfs2(scc_rev[a][i]);
	}
}
void query(int a,int b,int c,int d,int e,int f){
	if(c>d)return;
	if(d<a||b<c)return;
	if(c<=a&&b<=d){
		scc_g[f].push_back(e+20000);
		scc_rev[e+20000].push_back(f);
		return;
	}
	query(a,(a+b)/2,c,d,e*2,f);
	query((a+b)/2+1,b,c,d,e*2+1,f);
}
void add_edge(int a,int b){
	a+=32768;
	while(a){
		scc_g[20000+a].push_back(b^1);
		scc_rev[b^1].push_back(20000+a);
		a/=2;
	}
}
