	}
	std::sort(p,p+a*2);
	int left=0;
	int right=1000000000;
	while(left+1<right){
		int M=(left+right)/2;
		for(int i=0;i<100100;i++){
			scc_g[i].clear();
			scc_rev[i].clear();
			v[i]=num[i]=conv[i]=scc[i]=fi[i]=ss[i]=0;
		}
		for(int i=0;i<a*2;i++){
			add_edge(i,p[i].second);
		}
		for(int i=0;i<a*2;i++){
			int L=upper_bound(p,p+a*2,make_pair(p[i].first-M,(int)mod))-p;
			query(0,32767,L,i-1,1,p[i].second);
			int R=lower_bound(p,p+a*2,make_pair(p[i].first+M,0))-p-1;
			query(0,32767,i+1,R,1,p[i].second);
		}
		cur=0;
		for(int i=0;i<100100;i++){
			if(v[i])continue;
			v[i]=1;
			dfs(i);
		}
		cur=0;
		for(int i=0;i<100100;i++)v[i]=0;
		for(int i=100100-1;i>=0;i--){
			if(v[num[i]])continue;
			v[num[i]]=1;
			fi[cur]=num[i];
			dfs2(num[i]);
			cur++;
		}
		bool ok=true;
		for(int i=0;i<a;i++){
			if(scc[i*2]==scc[i*2+1])ok=false;
		}
		if(ok)left=M;
		else right=M;
	}
	printf("%d\n",left);
}

