using namespace std;

struct data {
    data() {}
    data(int x) : x(x) {}
    data(int x, int i, int j) : x(x), i(i), j(j) {}
    int x, i, j;

    bool operator< (const data& b) const { return x < b.x; }
};

int n, ind[10004][2], seg[20004];
data a[20004];

const int maxv = 70000;
vector<int> og[maxv], g[maxv], h[maxv];

void construct(int s, int e, int x) {
    if (s == e) {
        seg[s] = x;
    } else {
        int m = (s+e) / 2;
        construct(s, m, 2*x);
        construct(m+1, e, 2*x+1);
        og[x].push_back(2*x);
        og[x].push_back(2*x+1);
    }
}

void connect(int a, int s, int e, int x, int l, int r) {
    if (l <= s and e <= r) {
        g[a].push_back(x);
    } else if (l <= e and s <= r) {
        int m = (s+e) / 2;
        connect(a, s, m, 2*x, l, r);
        connect(a, m+1, e, 2*x+1, l, r);
    }
}

bool vis[maxv];
int ord[maxv], t;
void dfs1(int x) {
    if (vis[x]) return;
    vis[x] = true;

    for (int i : g[x]) dfs1(i);

    ord[t++] = x;
}

int col[maxv];
void dfs2(int x, int c) {
    if (vis[x]) return;
    vis[x] = true; col[x] = c;

    for (int i : h[x]) dfs2(i, c);
}

bool check(int d) {
    for (int i=0; i<maxv; i++) g[i] = og[i];

    for (int i=0; i<n; i++) for (int j=0; j<2; j++) {
        int x = ind[i][j], y = ind[i][!j];

        connect(seg[x], 0, 2*n-1, 1, upper_bound(a, a+2*n, data(a[y].x - d)) - a, y-1);
        connect(seg[x], 0, 2*n-1, 1, y+1, lower_bound(a, a+2*n, data(a[y].x + d)) - a - 1);
    }

    for (int i=0; i<maxv; i++) h[i].clear();
    for (int i=0; i<maxv; i++) for (int j : g[i]) h[j].push_back(i);

    fill(vis, vis+maxv, 0); t = 0;
    for (int i=0; i<maxv; i++) dfs1(i);

    reverse(ord, ord+maxv);
    fill(vis, vis+maxv, 0);
    for (int i=0, c=1; i<maxv; i++) dfs2(ord[i], c++);

    for (int i=0; i<n; i++) if (col[seg[ind[i][0]]] == col[seg[ind[i][1]]]) return false;
    return true;
}

int main() {
    cin >> n;

    for (int i=0; i<n; i++) {
        int x, y;
        cin >> x >> y;
        a[2*i] = data(x, i, 0);
        a[2*i+1] = data(y, i, 1);
    }

    sort(a, a+2*n);

    for (int i=0; i<2*n; i++) ind[a[i].i][a[i].j] = i;

    construct(0, 2*n-1, 1);

    int l = 0, r = 1e9 + 7;

    while (r-l > 1) {
        int m = (l+r) / 2;
        if (check(m)) l = m;
        else r = m;
    }

    cout << l << '\n';
}

