const int N = 100000 + 5;

int n, m, top, idx, dfn_idx, cnt_scc;
int id[N], cor[N], dfn[N], low[N];
int bel[N], s[N], ins[N], st[N];
pair<int, int> c[N];

std::vector<int> v[N];

struct node {int x, p;} a[N];

int cmp(const node &a, const node &b) {return a.x < b.x;}

void addedge(int x, int y) {v[x].push_back(y);}

void build(int x, int l, int r) {
	id[x] = ++idx;
	v[id[x]].clear();
	if (l == r) {
		addedge(id[x], cor[l]);
		return;
	}
	int m = (l + r) >> 1;
	build(lc, l, m);
	build(rc, m + 1, r);
	addedge(id[x], id[lc]);
	addedge(id[x], id[rc]);
}

void modify(int x, int l, int r, int s, int t, int p) {
	if (s <= l && r <= t) {addedge(p, id[x]); return;}
	int m = (l + r) >> 1;
	if (s <= m) modify(lc, l, m, s, t, p);
	if (m < t) modify(rc, m + 1, r, s, t, p);
}

void tarjan(int x) {
	dfn[x] = low[x] = ++dfn_idx;
	ins[x] = 1; st[++top] = x;
	for (int i = 0; i < v[x].size(); i++) {
		int y = v[x][i];
		if (!dfn[y]) {
			tarjan(y);
			low[x] = min(low[x], low[y]);
		} else if (ins[y]) low[x] = min(low[x], dfn[y]);
	}
	if (dfn[x] == low[x]) {
		int p; cnt_scc++;
		do {
			p = st[top--];
			bel[p] = cnt_scc;
			ins[p] = 0;
		} while (p != x);
	}
}

int check(int d) {
	idx = 2 * n;
	build(1, 1, 2 * n);
	for (int i = 1; i <= 2 * n; i++) {
		v[i].clear();
		int pl = upper_bound(s + 1, s + 2 * n + 1, s[i] - d) - s;
		int pr = lower_bound(s + 1, s + 2 * n + 1, s[i] + d) - s; pr--;
		if (pl <= i - 1) modify(1, 1, 2 * n, pl, i - 1, i);
		if (i + 1 <= pr) modify(1, 1, 2 * n, i + 1, pr, i);
	}
	cnt_scc = dfn_idx = 0;
	for (int i = 1; i <= idx; i++) dfn[i] = 0;
	for (int i = 1; i <= 2 * n; i++) if (!dfn[i]) tarjan(i);
	for (int i = 1; i <= 2 * n; i++) if (bel[i] == bel[cor[i]]) return 0;
	return 1;
}

int main() {
	read(n);
	for (int i = 1; i <= n; i++) {
		read(a[2 * i - 1].x), read(a[2 * i].x);
		a[2 * i - 1].p = i; a[2 * i].p = i;
	}
	sort(a + 1, a + 2 * n + 1, cmp);
	for (int i = 1; i <= n; i++) c[i] = make_pair(0, 0);
	for (int i = 1; i <= 2 * n; i++) {
		int x = a[i].p;
		if (!c[x].first) c[x].first = i;
		else c[x].second = i;
		s[i] = a[i].x;
	}
	for (int i = 1; i <= n; i++) {
		cor[c[i].first] = c[i].second;
		cor[c[i].second] = c[i].first;
	}
	//for (int i = 1; i <= 2 * n; i++) printf("%d ", s[i]); printf("\n");
	//for (int i = 1; i <= n; i++) printf("%d %d\n", c[i].first, c[i].second);
	//for (int i = 1; i <= 2 * n; i++) printf("%d ", cor[i]); printf("\n");
	int l = 0, r = a[2 * n].x, ans = 0;
	while (l <= r) {
		m = (l + r) >> 1;
		if (check(m)) {
			ans = m;
			l = m + 1;
		} else r = m - 1;
	}
	printf("%d\n", ans);
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN=2e4+5;
const int MAXM=20000010;
int n;
struct node
{
	int x,y;
}sv[MAXN];
struct Edge
{
	int to,next;
}edge[MAXM];
int head[MAXN],tot;
void init()
{
	tot=0;
	memset(head,-1,sizeof(head));
}
void addedge(int u,int v)
{
	edge[tot].to=v;edge[tot].next=head[u];head[u]=tot++;
} 
bool vis[MAXN];//染色标记，为true表示选择
int S[MAXN],top;//栈
bool dfs(int u)
{
	if(vis[u^1])return false;
	if(vis[u])return true;
	vis[u]=true;
	S[top++]=u;
	for(int i=head[u];i!=-1;i=edge[i].next)
		if(!dfs(edge[i].to))
			return false;
	return true;
}
bool Twosat(int n)
{			
	memset(vis,false,sizeof(vis));
	for(int i=0;i<n;i+=2)
	{
		if(vis[i]||vis[i^1])continue;
		top=0;
		if(!dfs(i))
		{
			while(top)vis[S[--top]]=false;
			if(!dfs(i^1)) return false;
		}
	}
	return true;
}
bool judge(int now)
{
	init();
	for(int i=0;i<n;i++)
	{
		for(int j=i+1;j<n;j++)
		{
			int u,v;
			if(i==j)
			{
				continue;
			}
			if(abs(sv[i].x-sv[j].x)<now)
			{
				u=i*2,v=j*2;
				addedge(u,v^1);
				addedge(v,u^1);
			}
			if(abs(sv[i].x-sv[j].y)<now)
			{
				u=i*2,v=(j*2)^1;
				addedge(u,v^1);
				addedge(v,u^1);
			}
			if(abs(sv[i].y-sv[j].x)<now)
			{
				u=(i*2)^1,v=j*2;
				addedge(u,v^1);
				addedge(v,u^1);
			}
			if(abs(sv[i].y-sv[j].y)<now)
			{
				u=(i*2)^1,v=(j*2)^1;
				addedge(u,v^1);
				addedge(v,u^1);
			}
		}
	}
	return Twosat(2*n);
}
int cnt=0;
int tmp[MAXN];
int main()
{
	//freopen("in.txt","r",stdin);
	//freopen("out.txt","w",stdout);
	scanf("%d",&n);
	for(int i=0;i<n;i++)
	{
		scanf("%d%d",&sv[i].x,&sv[i].y);
		tmp[cnt++]=sv[i].x,tmp[cnt++]=sv[i].y;
	}
	sort(tmp,tmp+cnt);
	int l=1,r=1e9,ans=0;
	for(int i=0;i<n;i++)
	{
		r=min(r,tmp[i+n]-tmp[i]);
	}
	while(l<=r)
	{
		int mid=(l+r)>>1;
		if(judge(mid))
		{
			ans=max(ans,mid);
			l=mid+1;
		}
		else
		{
			r=mid-1;
		}
	}
	printf("%d\n",ans);
	return 0;
}

