using namespace std;

#define MAX 10002

int n;

vector<pair<int, int> > v;

unsigned int randxor()
{
	static unsigned int x = 123456789, y = 362436069, z = 521288629, w = 88675123;
	unsigned int t;
	t = (x ^ (x << 11)); x = y; y = z; z = w; return(w = (w ^ (w >> 19)) ^ (t ^ (t >> 8)));
}

int main(){
	cin >> n;
	for (int i = 0; i < n; i++){
		int x, y;
		scanf("%d%d", &x, &y);
		v.push_back(make_pair(x, y));
	}
	srand(time(NULL));
	sort(v.begin(), v.end());
	int ans = INT_MAX;
	while (clock() / (double)(CLOCKS_PER_SEC) < 4.5){
		vector<int> V;
		for (int i = 0; i < v.size(); i++){
			if (randxor() % 2){
				V.push_back(v[i].first);
			}
			else{
				V.push_back(v[i].second);
			}
		}
		sort(V.begin(), V.end());
		int mint = INT_MAX;
		for (int i = 0; i + 1 < V.size(); i++){
			mint = min(mint, V[i + 1] - V[i]);
		}
		ans = min(ans, mint);
	}
	cout << ans << endl;
	return 0;
}

