const int maxn=1000010;
const int maxm=2000010;
struct Solver {
	int m,first[maxn],nxt[maxm],to[maxm];
	void init() {
		m=0;memset(first,0,sizeof(first));
	}
	void AddEdge(int u,int v) {
		if((!u)||(!v)) return;
		to[++m]=v;nxt[m]=first[u];first[u]=m;
	}
	int low[maxn],pre[maxn],num[maxn],S[maxn],top,clo,cnt;
	void tarjan(int x) {
		low[x]=pre[x]=++clo;S[++top]=x;
		for(int i=first[x];i;i=nxt[i]) {
			if(!pre[to[i]]) tarjan(to[i]),low[x]=min(low[x],low[to[i]]);
			else if(!num[to[i]]) low[x]=min(low[x],pre[to[i]]);
		}
		if(low[x]==pre[x]) {
			cnt++;for(;;) {
				int y=S[top--];
				num[y]=cnt;
				if(x==y) break;
			}
		}
	}
	int solve(int n,int N) {
		memset(pre,0,sizeof(pre));
		memset(num,0,sizeof(num));
		clo=cnt=top=0;
		rep(i,1,n) if(!pre[i]) tarjan(i);
		rep(i,1,N) if(num[i]==num[i+N]) return 0;
		return 1;
	}
}sol;
int cntt,ls[maxn],rs[maxn];
void build(int& y,int x,int l,int r,int p,int v) {
	sol.AddEdge(y=++cntt,x);
	if(l==r) sol.AddEdge(y,v);
	else {
		ls[y]=ls[x];rs[y]=rs[x];
		int mid=l+r>>1;
		if(p<=mid) build(ls[y],ls[x],l,mid,p,v),sol.AddEdge(y,ls[y]);
		else build(rs[y],rs[x],mid+1,r,p,v),sol.AddEdge(y,rs[y]);		
	}
}
void query(int y,int l,int r,int ql,int qr,int v) {
	if(!y) return;
	if(ql<=l&&r<=qr) sol.AddEdge(v,y);
	else {
		int mid=l+r>>1;
		if(ql<=mid) query(ls[y],l,mid,ql,qr,v);
		if(qr>mid) query(rs[y],mid+1,r,ql,qr,v);
	}
}
int root[maxn],proot[maxn];
int n,x[maxn],y[maxn],tmp[maxn];
int check(int lim) {
	lim--;
	sol.init();cntt=n*2;
	rep(i,1,n) {
		root[i]=root[i-1];
		build(root[i],root[i],1,n*2,lower_bound(tmp+1,tmp+2*n+1,x[i])-tmp,i+n);
		build(root[i],root[i],1,n*2,lower_bound(tmp+1,tmp+2*n+1,y[i])-tmp,i);
	}
	dwn(i,n,1) {
		proot[i]=proot[i+1];
		build(proot[i],proot[i],1,n*2,lower_bound(tmp+1,tmp+2*n+1,x[i])-tmp,i+n);
		build(proot[i],proot[i],1,n*2,lower_bound(tmp+1,tmp+2*n+1,y[i])-tmp,i);
	}
	rep(i,1,n) {
		int ql,qr;
		ql=lower_bound(tmp+1,tmp+2*n+1,x[i]-lim)-tmp;
		qr=upper_bound(tmp+1,tmp+2*n+1,x[i]+lim)-1-tmp;
		query(root[i-1],1,n*2,ql,qr,i);
		query(proot[i+1],1,n*2,ql,qr,i);
		ql=lower_bound(tmp+1,tmp+2*n+1,y[i]-lim)-tmp;
		qr=upper_bound(tmp+1,tmp+2*n+1,y[i]+lim)-1-tmp;
		query(root[i-1],1,n*2,ql,qr,i+n);
		query(proot[i+1],1,n*2,ql,qr,i+n);
	}
	return sol.solve(cntt,n);
}
