            if (abs(X[i] - X[j]) < D)
                ts.add_clause(i, 0, j, 0);
            if (abs(X[i] - Y[j]) < D)
                ts.add_clause(i, 0, j, 1);
            if (abs(Y[i] - X[j]) < D)
                ts.add_clause(i, 1, j, 0);
            if (abs(Y[i] - Y[j]) < D)
                ts.add_clause(i, 1, j, 1);
        }
    }
    if (ts.satisfiable())
        return true;
    else
        return false;
}
