		{
			if(!o) o = ++cnt;
			if(l == r) return Graph :: adde(o, op(p[l].id)); 
			int mid = (l + r) >> 1; 
			build(t[o].l, l, mid), build(t[o].r, mid + 1, r); 
			Graph :: adde(o, t[o].l), Graph :: adde(o, t[o].r); 
		}
	void add(int p, int l, int r, int ql, int qr, int x)
		{
			if(ql <= l && r <= qr) return Graph :: adde(x, p); 
			int mid = (l + r) >> 1;
			if(ql <= mid) add(t[p].l, l, mid, ql, qr, x); 
			if(mid < qr) add(t[p].r, mid + 1, r, ql, qr, x); 
		}
} T; 

