{
    scanf("%d", &N);
    _UP = 0;
    for(int i=1; i<=N; i++) { scanf("%d%d", &a[i][0], &a[i][1]); lsan[++_UP] = a[i][0]; lsan[++_UP] = a[i][1]; }
    sort(lsan + 1, lsan + _UP + 1);
    _UP = (int)(unique(lsan + 1, lsan + _UP + 1) - lsan - 1);
    for(int i=1; i<=N; i++)
    {
        a[i][0] = (int)(lower_bound(lsan + 1, lsan + _UP + 1, a[i][0]) - lsan);
        same[a[i][0]].push_back(2 * i);
        a[i][1] = (int)(lower_bound(lsan + 1, lsan + _UP + 1, a[i][1]) - lsan);
        same[a[i][1]].push_back(2 * i - 1);
    }
    G_init();
    l = 1; r = 1e9 + 1;
    ans = 0;
    while(l <= r)
    {
        lim = HalF;
        if(check())
        {
            l = lim + 1;
            ans = lim;
        }
        else r = lim - 1;
    }
//    if(ans == 1e9 + 1) ans = 0;
    printf("%d\n", ans);
    return 0;
