const int maxN = 1e4 + 5;
typedef bitset < 2 * maxN > bs;
int n;
int x[maxN], y[maxN];
bs g[2 * maxN];
vector < pair < int, int > > f;
bs not_used;
int his_pos[2 * maxN];
bs pref_ones[2 * maxN];
vector < int > order;
int comp[2 * maxN];
void dfs1(int v) {
    not_used[his_pos[v ^ 1]] = false;
    while (true) {
        int p = (not_used & g[v])._Find_first();
        if (p == 2 * maxN) break;
//        cout << " EDGE " << v << " " << (f[p].second ^ 1) << endl;
        dfs1(f[p].second ^ 1);
    }
    order.emplace_back(v);
}
void dfs2(int v, int cl) {
    comp[v] = cl;
    not_used[his_pos[v]] = false;
    while (true) {
        int p = (not_used & g[v ^ 1])._Find_first();
        if (p == 2 * maxN) break;
        dfs2(f[p].second, cl);
    }
}
bool ok(int d) {
    not_used = pref_ones[2 * n - 1];
    for (int i = 0; i < f.size(); i++) {
        int ourcord = f[i].first;
        auto it = lower_bound(f.begin(), f.end(), make_pair(ourcord + d, -1)) - f.begin();
        int r = it - 1;
        it = lower_bound(f.begin(), f.end(), make_pair(ourcord - d + 1, -1)) - f.begin();
        int l = it;
        //add edges from l .. r
        g[f[i].second] = pref_ones[r];
        if (l > 0) g[f[i].second] ^= pref_ones[l - 1];
        g[f[i].second][i] = false;
    }
    order.clear();
    for (int i = 0; i < 2 * n; i++) {
        if (not_used[his_pos[i ^ 1]]) dfs1(i);
    }
    for (int i = 0; i < 2 * n; i++) {
        comp[i] = -1;
    }
    reverse(order.begin(), order.end());
    int sz = 0;
    not_used = pref_ones[2 * n - 1];
    for (int v : order) {
        if (comp[v] == -1) {
            dfs2(v, sz++);
        }
    }
    for (int i = 0; i < 2 * n; i++) {
        if (comp[i] == comp[i ^ 1]) return false;
    }
    return true;
}
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
//    freopen("input.txt", "r", stdin);
    cin >> n;
    pref_ones[0][0] = true;
    for (int i = 1; i <= 2 * n; i++) {
        pref_ones[i] = pref_ones[i - 1];
        pref_ones[i][i] = true;
    }
    for (int i = 0; i < n; i++) {
        cin >> x[i] >> y[i];
        f.emplace_back(x[i], 2 * i);
        f.emplace_back(y[i], 2 * i + 1);
    }
    sort(f.begin(), f.end());
    for (int i = 0; i < f.size(); i++) {
        his_pos[f[i].second] = i;
    }
    int l = 0;
    int r = 1e9 + 10;
//    cout << ok(1) << endl;
//    exit(0);
//    cout << ok(4) << endl;
//    exit(0);
    while (r - l > 1) {
        int mid = (l + r) / 2;
        if (ok(mid)) l = mid;
        else r = mid;
    }
    cout << l;
    return 0;
}

