int N,M;
const int MAX_N = 20010;
const int MAX_M = 100010;

struct pt{
	int x,id;
	pt(){}
	pt(int x_,int id_):x(x_),id(id_){}
	bool operator<(const pt& r)const{
		return x<r.x;
	}
}a[MAX_N];

int pos[MAX_N];
int sz;

mat path,rpath;

bool vsi[MAX_M];
int ID[MAX_M];
vec st;

void add_edge(int x,int y){
	path[x].push_back(y);
	rpath[y].push_back(x);
}

void init(int len){
	st.clear();
	memset(vsi,0,sizeof(vsi));
	memset(ID,-1,sizeof(ID));
	path.assign(M*2,vec());
	rpath.assign(M*2,vec());

	for(int i=0;i<N;i+=2){
		add_edge(pos[i],pos[i+1]+M);
		add_edge(pos[i]+M,pos[i+1]);
		add_edge(pos[i+1],pos[i]+M);
		add_edge(pos[i+1]+M,pos[i]);
	}

	int L=0,R=0;
	for(int i=0;i<N;i++){
		while(L<i&&a[i].x-a[L].x>=len)L++;
		while(R<N&&a[R].x-a[i].x<len)R++;
		for(int j=L;j<R;j++){
			if(i==j)continue;
			add_edge(j+sz,i+sz+M);
			add_edge(i+sz,j+sz+M);
		}
	}
}

void dfs(int v){
	vsi[v]=1;
	for(auto& u:path[v]){
		if(vsi[u])continue;
		dfs(u);
	}
	st.push_back(v);
}

void rdfs(int v,int c){
	ID[v]=c;
	for(auto& u:rpath[v]){
		if(ID[u]>=0)continue;
		rdfs(u,c);
	}
}

bool chk(int len){
	init(len);
	for(int i=0;i<M*2;i++){
		if(vsi[i])continue;
		dfs(i);
	}
	int v,c=0;
	while(!st.empty()){
		v=st.back();st.pop_back();
		if(ID[v]>=0)continue;
		rdfs(v,c++);
	}
	for(int i=sz;i<N+sz;i++){
		if(ID[i]==ID[i+M])return 0;
	}
	return 1;
}

