void Tarjan(int x){
	low[x]=dfn[x]=++l;
	Stack[++tot]=x;
	flag[x]=1;
	for (int i=fi[x];i;i=ne[i]){
		if (!dfn[zz[i]])Tarjan(zz[i]),low[x]=min(low[x],low[zz[i]]);
