struct StronglyConnectedComponent {
    //T:強連結成分をトポロジカルソートしたグラフ C:強連結成分の内訳
    vector<vector<int>> G,R,T,C;
    vector<int> vs,used,blg;
    StronglyConnectedComponent() {}
    StronglyConnectedComponent(int N) : G(N), R(N), used(N), blg(N) {}

    void add_edge(int u,int v) {
        G[u].emplace_back(v);
        R[v].emplace_back(u);
    }

    void dfs(int v){
        used[v] = 1;
        for(int u:G[v]) {
            if(!used[u]) dfs(u);
        }
        vs.emplace_back(v);
    }

    void rdfs(int v, int k) {
        used[v] = 1;
        blg[v] = k;
        C[k].emplace_back(v);
        for(int u:R[v]) {
            if(!used[u]) rdfs(u,k);
        }
    }

    int build() {
        int N = G.size();
        for(int v = 0; v < N; v++) {
            if(!used[v]) dfs(v);
        }

        fill(used.begin(),used.end(),0);
        int k = 0;
        for(int i = N-1; i >= 0; i--) {
            if(!used[vs[i]]) {
                T.emplace_back();
                C.emplace_back();
                rdfs(vs[i], k++);
            }
        }

        for(int v = 0; v < N; v++) {
            for(int u:G[v]) {
                if(blg[v] != blg[u]) T[blg[v]].emplace_back(blg[u]);
            }
        }

        for(int i = 0; i < k; i++) {
            sort(T[i].begin(),T[i].end());
            T[i].erase(unique(T[i].begin(),T[i].end()),T[i].end());
        }
        return k;
    }

    int operator[](int k) const{return blg[k];}
};

template<typename T>
struct RangeEdge {
    vector<vector<edge<T>>> G;
    int N,sz,to,from;

    RangeEdge() {}
    RangeEdge(int N) : N(N) {
        sz = 1;
        while (sz < N) sz <<= 1;
        to = N;
        from = N+sz*2;
        G.resize(N+sz*4);
        for (int i = 0; i < N; ++i) {
            G[to+i+sz].emplace_back(i,0);
            G[i].emplace_back(from+i+sz,0);
        }
        for (int i = 1; i < sz; ++i) {
            G[to+i].emplace_back(to+(i<<1|0),0);
            G[to+i].emplace_back(to+(i<<1|1),0);
            G[from+(i<<1|0)].emplace_back(from+i,0);
            G[from+(i<<1|1)].emplace_back(from+i,0);
        }
    }

private:

    void update(int l, int r, int v, int flag) {
        l += sz; r += sz;
        while (l < r) {
            if (l & 1) {
                if (flag) G[v].emplace_back(to+l,0);
                else G[from+l].emplace_back(v,0);
                ++l;
            }
            l >>= 1;
            if (r & 1) {
                --r;
                if (flag) G[v].emplace_back(to+r,0);
                else G[from+r].emplace_back(v,0);
            }
            r >>= 1; 
        }
    }

public:

    void addedge(int fromL, int fromR, int toL, int toR, T cost) {
        if (fromL >= fromR or toL >= toR) return;
        int M = G.size();
        G.emplace_back();
        G.emplace_back();
        G[M].emplace_back(M+1,cost);
        update(fromL,fromR,M,0);
        update(toL,toR,M+1,1);
    }
};

