bool check(int d) {
    for (int i = 0; i < n * 4; ++i) {
        adj2[i].clear();
        adj[i].clear();
        comp[i] = -1;
    }

    for (int i = 0; i < n; ++i) {
        int a = mm[i].fi;
        int b = mm[i].se;

        addEdge(a, b + 2 * n);
        addEdge(b, a + 2 * n);

        addEdge(a + 2 * n, b);
        addEdge(b + 2 * n, a);
    }

    for (int i = 0; i < n * 2; ++i) {
        for (int j = 0; j < n * 2; ++j) {
            if (i == j) {
                continue;
            }

            if (abs(vv[i].fi - vv[j].fi) < d) {
                int a = i, b = j;
                addEdge(a, b + 2 * n);
            }
        }
    }

    for (int i = 0; i < n * 4; ++i) {
        u[i] = 0;
    }

    order.clear();
    cur = 0;

    for (int i = 0; i < n * 4; ++i) {
        if (u[i]) {
            continue;
        }

        dfs(i);
    }

    for (int i = 0; i < n * 4; ++i) {
        int v = order[n * 4 - i - 1];

        if (comp[v] == -1) {
            dfs2(v); ++cur;
        }
    }

    for (int i = 0; i < n * 2; ++i) {
        if (comp[i] == comp[i + 2 * n]) {
            return 0;
        }
    }

    return 1;
}

