{
	int res;char ch;
	while(!isdigit(ch=getchar()));
	res=ch-'0';
	while(isdigit(ch=getchar()))res=res*10-'0'+ch;
	return res;
}
int main()
{	n=read();
	for(RI i=1;i<=n;++i)
	{
		a[i]=read();b[i]=read();
		insert(p[0][i],b[i]);insert(p[1][i],a[i]);
	}
	for(RI i=1;i<=sz;++i)sort(ch[i].begin(),ch[i].end());
	int left=0,mid,right=MX,ans=0;
	while(left<=right)
	{
		mid=(left+right)>>1;
		if(check(mid))
		{
			ans=mid;
			left=mid+1;
		}
		else right=mid-1;
	}
	printf("%d",ans);
	return 0;
}

