#define ALL(v) v.begin(), v.end()
vector<vector<int>> G;
vector<vector<int>> rG;
vector<int> vs, cmp;
vector<bool> used;
int x[10000], y[10000];
int len, seg_size;
void add_edge(int from, int to) {
	G[from].push_back(to);
	rG[to].push_back(from);
}
void dfs(int v) {
	used[v] = true;
	for (int to : G[v]) {
		if (!used[to]) dfs(to);
	}
	vs.push_back(v);
}
void rdfs(int v, int k) {
	used[v] = true;
	cmp[v] = k;
	for (int to : rG[v]) {
		if (!used[to]) rdfs(to, k);
	}
}
int scc() {
	fill(ALL(used), 0);
	vs.clear();
	rep(i,G.size()) {
		if (!used[i]) dfs(i);
	}
	fill(ALL(used), 0);
	int k = 0;
	for (int i = vs.size() - 1; i >= 0; i--) {
		if (!used[vs[i]]) rdfs(vs[i], k++);
	}
	return k;
}
//b[i]→not b[j] | l ≦ j < r
void add(int i, int a, int b, int k, int l, int r) {
	if (a <= l && r <= b) {
		add_edge(i + len - 1, k + seg_size);
		add_edge(k, (i + len - 1) + seg_size);
		return;
	}
	if (b <= l || r <= a) return;
	add(i, a, b, k * 2 + 1, l, (l + r) / 2);
	add(i, a, b, k * 2 + 2, (l + r) / 2, r);
}

int main() {
	int N;
	cin >> N;
