			int p = lower_bound(ALL(v), P(x[i], i * 2)) - v.begin();
			int q = lower_bound(ALL(v), P(y[i], i * 2 + 1)) - v.begin();
			add_edge(p + len - 1, (q + len - 1) + seg_size);
			add_edge(q + len - 1, (p + len - 1) + seg_size);
			add_edge((p + len - 1) + seg_size, q + len - 1);
			add_edge((q + len - 1) + seg_size, p + len - 1);
		}
		REP(i, 1, seg_size) {
			int par = (i - 1) / 2;
			add_edge(i, par);
			add_edge(par + seg_size, i + seg_size);
		}
		rep(i, v.size()) {
			int L = upper_bound(ALL(v), P(v[i].first - m, 1 << 30)) - v.begin();
			add(i, L, i, 0, 0, len);
			int R = lower_bound(ALL(v), P(v[i].first + m, -1)) - v.begin();
			add(i, i + 1, R, 0, 0, len);
		}
		int k = scc();
