vector<int> g[maxn];
// stack<int> S;
int st[20010], sz;
int pre[maxn], low[maxn], timer;
bool ed;
int dfs(int x) {
  pre[x] = low[x] = ++timer;
  // S.push(x);
  st[sz++] = x;
  for (int y : g[x]) {
    if (!pre[y])
      low[x] = min(low[x], dfs(y));
    else if (!sccno[y])
      low[x] = min(low[x], pre[y]);
  }
  if (low[x] == pre[x]) {
    scc_cnt++;
    for (;;) {
      // int t = S.top();
      // S.pop();
      int t = st[--sz];
      sccno[t] = scc_cnt;
      if (sccno[t] == sccno[t^1]) {
        ed = true;
        return 0;
      }
      if (t == x)
        break;
    }
  }
  return low[x];
}
void directed(int n) {
  memset(pre, 0, sizeof pre);
  memset(sccno, 0, sizeof sccno);
  timer = scc_cnt = 0;
  sz = 0;
  ed = false;
  for (int i = 0; i < n && !ed; ++i)
    if (!pre[i])
      dfs(i);
}

bool ok(int m) {
  REP(i, n<<1) g[i].clear();
  REP(i, n) for (int j = i + 1; j < n; ++j) {
    if (a[j][0] - a[i][1] >= m) break;
    bool f = false;
    REP(k, 2) REP(l, 2) {
      int d = abs(a[i][k] - a[j][l]);
      if (d >= m) {
        f = true;
      } else {
        g[i<<1|k].PB(j<<1|(l^1));
        g[j<<1|l].PB(i<<1|(k^1));
      }
    }
    if (!f) return false;
  }
  directed(n<<1);
  return !ed;
}

int main() {
  scanf("%d", &n);
  REP(i, n) {
    scanf("%d%d", &a[i][0], &a[i][1]);
    if (a[i][0] > a[i][1]) swap(a[i][0], a[i][1]);
  }
  sort(a, a + n);
  int l = 0, r = 1000000000 / (n - 1), ans = 0;
  REP(i, n - 1) {
    int aa = abs(a[i][0] - a[i+1][1]);
    int bb = abs(a[i][1] - a[i+1][0]);
    r = min(r, max(aa, bb));
  }
  // printf("%d %d\n", l, r);
  while (l <= r) {
    int m = (l + r) >> 1;
   //  printf("%d - %d\n", l, r);
    if (ok(m)) ans = m, l = m + 1;
    else r = m - 1;
  }
  printf("%d\n", ans);
  return 0;
}

