	for(int i=1;i<=n*2;++i)s.insert(mp(X[i],i));
	for(int i=n*2;i;--i){
		if(!scc[ord[i]]){
			++cnt;
			dfs2(ord[i],X[ord[i]]);
		}
	}
	for(int i=1;i<=n;++i)if(scc[i]==scc[i+n])return 0;
	return 1;
}
