using namespace std;

const int MAXN = 2 * 66000 + 10;
int tot;

vector<int> arr[MAXN];
int ors[MAXN];

int dis[MAXN];
stack<int> stk;
int tim;

int low[MAXN];
int num[MAXN];
int siz;

void f(int x)
{
    dis[x] = ++tim;
    low[x] = dis[x];
    stk.push(x);

    for(int &y : arr[x])
    {
        if(!dis[y])
        {
            f(y);
            low[x] = min(low[x], low[y]);
        }
        else if(!num[y])
            low[x] = min(low[x], dis[y]);
    }

    if(low[x] == dis[x])
    {
        siz++;
        while(1)
        {
            int t = stk.top();
            stk.pop();

            num[t] = siz;
            if(t == x)
                break;
        }
    }
}

struct str
{
    int x, y;
};

void init()
{
    tim = 0;
    siz = 0;
    while(!stk.empty())
        stk.pop();
    for(int i = 2; i <= 2 * tot + 1; i++)
    {
        arr[i].resize(ors[i]);
        dis[i] = 0;
        low[i] = 0;
        num[i] = 0;
    }
}

void add_clause(int x, int y)
{
    printf("add_c %d %d\n", x, y);
    int p = x < 0 ? -2 * x : 2 * x;
    int q = y < 0 ? -2 * y : 2 * y;
    arr[x < 0 ? p : p + 1].push_back(y < 0 ? q + 1 : q);
    arr[y < 0 ? q : q + 1].push_back(x < 0 ? p + 1 : p);
}

void add_edge(int x, int y)
{
    add_clause(-x, y);
}

void add(int val[], int b, int x, int l, int r, int s, int g, int v)
{
    if(r < l)
        return;

    int lv = val[l];
    int rv = val[r];
    if(g < lv || rv < s)
        return;

    if(s <= lv && rv <= g)
    {
        add_edge(v, -(b + x));
        return;
    }

    add(val, b, 2 * x, l, (l + r) / 2, s, g, v);
    add(val, b, 2 * x + 1, (l + r) / 2 + 1, r, s, g, v);
}

int n;
int sizx, sizy;
str inp[10010];
int idxx[10010];
int idxy[10010];
int valx[10010];
int valy[10010];

bool solve(int m)
{
    if(m == 0)
        return 1;

    init();

    for(int i = 1; i <= n; i++)
    {
        add(valx, 0, 1, 1, n, inp[i].x - (m - 1), inp[i].x + (m - 1), idxx[i]);
        add(valy, sizx, 1, 1, n, inp[i].x - (m - 1), inp[i].x + (m - 1), idxx[i]);

        add(valx, 0, 1, 1, n, inp[i].y - (m - 1), inp[i].y + (m - 1), idxy[i]);
        add(valy, sizx, 1, 1, n, inp[i].y - (m - 1), inp[i].y + (m - 1), idxy[i]);
    }

    for(int i = 2; i <= 2 * tot + 1; i++)
        if(!dis[i])
            f(i);

    for(int i = 1; i <= tot; i++)
        if(num[2 * i] == num[2 * i + 1])
            return 0;

    return 1;
}

int cons(int mem[], int b, int x, int l, int r)
{
    if(r < l)
        return 0;

    if(l == r)
    {
        mem[l] = b + x;
        return 1;
    }

    int res = 1;
    {
        int t = cons(mem, b, 2 * x, l, (l + r) / 2);
        if(t)
        {
            add_edge(b + x, b + 2 * x);
            add_edge(-(b + x), -(b + 2 * x));
            res += t;
        }
    }
    {
        int t = cons(mem, b, 2 * x + 1, (l + r) / 2 + 1, r);
        if(t)
        {
            add_edge(b + x, b + 2 * x + 1);
            add_edge(-(b + x), -(b + 2 * x + 1));
            res += t;
        }
    }
    return res;
}

int memx[10010];
int memy[10010];

void pre()
{
    sizx = cons(memx, 0, 1, 1, n);
    sizy = cons(memy, sizx, 1, 1, n);

    vector<pair<int, int>> vx, vy;
    for(int i = 1; i <= n; i++)
    {
        vx.push_back({ inp[i].x, i });
        vy.push_back({ inp[i].y, i });
    }

    sort(vx.begin(), vx.end());
    sort(vy.begin(), vy.end());

    for(int i = 1; i <= n; i++)
    {
        idxx[vx[i - 1].second] = memx[i];
        idxy[vy[i - 1].second] = memy[i];
        valx[i] = vx[i - 1].first;
        valy[i] = vy[i - 1].first;
    }

    for(int i = 1; i <= n; i++)
    {
        add_clause(idxx[i], idxy[i]);
        add_clause(-idxx[i], -idxy[i]);
    }

    tot = sizx + sizy;

    for(int i = 2; i <= 2 * tot + 1; i++)
        ors[i] = arr[i].size();
}

int main()
{
    //freopen("in", "r", stdin);
    //freopen("out", "w", stdout);

    scanf("%d", &n);
    for(int i = 1; i <= n; i++)
        scanf("%d%d", &inp[i].x, &inp[i].y);

    pre();

    int s = 0;
    int g = 1e9;
    while(s < g)
    {
        int m = (s + g + 1) / 2;
        if(solve(m))
            s = m;
        else
            g = m - 1;
    }

    printf("%d\n", s);
    return 0;
}

