    build1(x*2,l,mid);
    build1(x*2+1,mid+1,r);
    sat::Add((n+x)*2-1,(n+x*2)*2-1);
    sat::Add((n+x*2)*2,(n+x)*2);
    sat::Add((n+x)*2-1,(n+x*2+1)*2-1);
    sat::Add((n+x*2+1)*2,(n+x)*2);
}
void build2(int x,int l,int r) {
    t2[x].l=l;
    t2[x].r=r;
    if (l==r) {
        sat::Add((n+N+x)*2-1,c[l].num*2-1);
        sat::Add(c[l].num*2,(n+N+x)*2);
        return;
    }
    int mid=(l+r)/2;
    build2(x*2,l,mid);
    build2(x*2+1,mid+1,r);
    sat::Add((n+N+x)*2-1,(n+N+x*2)*2-1);
    sat::Add((n+N+x*2)*2,(n+N+x)*2);
    sat::Add((n+N+x)*2-1,(n+N+x*2+1)*2-1);
    sat::Add((n+N+x*2+1)*2,(n+N+x)*2);
}
void Add1(int i,LL l,LL r,LL x,LL y) {
    LL nowl=b[t1[i].l].x,nowr=b[t1[i].r].x;
    if (nowl>r||nowr<l) return;
    if (nowl>=l&&nowr<=r) {
        sat::Add(x,(n+i)*2-1);
        sat::Add((n+i)*2,y);
        return;
    }
    Add1(i*2,l,r,x,y);
    Add1(i*2+1,l,r,x,y);
}
void Add2(int i,LL l,LL r,LL x,LL y) {
    LL nowl=c[t2[i].l].y,nowr=c[t2[i].r].y;
    if (nowl>r||nowr<l) return;
    if (nowl>=l&&nowr<=r) {
        sat::Add(x,(n+N+i)*2-1);
        sat::Add((n+N+i)*2,y);
        return;
    }
    Add2(i*2,l,r,x,y);
    Add2(i*2+1,l,r,x,y);
}
bool check(LL x) {
    if (x==0) return 1;
    N=0;
    sat::clear();
    build1(1,1,n);
    build2(1,1,n);
    for (int i=1;i<=n;i++) {
        LL nowx=a[i].x,nowy=a[i].y;
        LL nowl=nowx-x,nowr=nowx+x;
        Add1(1,nowl,nowx-1,a[i].num*2-1,a[i].num*2);
        Add1(1,nowx+1,nowr,a[i].num*2-1,a[i].num*2);
        Add2(1,nowl,nowr,a[i].num*2-1,a[i].num*2);
        nowl=nowy-x+1,nowr=nowy+x-1;
        Add1(1,nowl,nowr,a[i].num*2,a[i].num*2-1);
        Add2(1,nowl,nowy-1,a[i].num*2,a[i].num*2-1);
        Add2(1,nowy+1,nowr,a[i].num*2,a[i].num*2-1);
    }
    sat::n=n+N*2;
    if (sat::work()) return 1;
    return 0;
}
