int rd(){
	int x=0;
	char c;
	do c=getchar();
	while(!isdigit(c));
	do{
		x=(x<<1)+(x<<3)+(c^48);
		c=getchar();
	}while(isdigit(c));
	return x;
}
void add_edge(int u,int v){
	nxt[++tot]=head[u];
	to[tot]=v;
	head[u]=tot;
	return;
}
void build(int o,int l,int r){
	if(l==r){
		idx[o]=a[l].idx+(n<<1);
		return;
	}
	idx[o]=++etot;
	int mid=(l+r)>>1;
	build(o<<1,l,mid);
	build(o<<1|1,mid+1,r);
	add_edge(idx[o],idx[o<<1]);
	add_edge(idx[o],idx[o<<1|1]);
	return;
}
void update(int o,int l,int r,int L,int R,int u){
	if(L<=l&&r<=R){
		add_edge(u,idx[o]);
		return;
	}
	int mid=(l+r)>>1;
	if(L<=mid)
		update(o<<1,l,mid,L,R,u);
	if(R>mid)
		update(o<<1|1,mid+1,r,L,R,u);
	return;
}
void tarjan(int u){
	low[u]=dfn[u]=++_clock;										   
	Stack.push(u);
	for(int i=head[u];~i;i=nxt[i]){
		int v=to[i];
		if(!dfn[v]){
			tarjan(v);
			low[u]=min(low[u],low[v]);
		}
		else
			if(!scc[v])
				low[u]=min(low[u],dfn[v]);
	}
	if(low[u]==dfn[u]){
		cnt++;
		int x;
		do{
			x=Stack.top();
			Stack.pop();
			scc[x]=cnt;
		}while(x!=u);
	}
	return;
}
bool check(int m){
	memset(head,-1,sizeof(head));
	memset(scc,0,sizeof(scc));
	memset(low,0,sizeof(low));
	memset(dfn,0,sizeof(dfn));
	tot=0; 
	_clock=0;
	cnt=0;
	etot=(n<<2);
	build(1,1,n<<1);
	int l=1,r=1;
	for(int i=1;i<=n;i++){
		add_edge(i,i+n+(n<<1));
		add_edge(i+n+(n<<1),i);
		add_edge(i+(n<<1),i+n);
		add_edge(i+n,i+(n<<1));
	}
	for(int i=1;i<=(n<<1);i++){
		while(a[i].val-a[l].val+1>m&&l<i)
			l++;
		while(a[r+1].val-a[i].val+1<=m&&r<(n<<1))
			r++;
		if(l<i)
			update(1,1,(n<<1),l,i-1,a[i].idx);
		if(i<r)
			update(1,1,(n<<1),i+1,r,a[i].idx);
	}
	for(int i=1;i<=(n<<1);i++)
		if(!scc[i])
			tarjan(i);
	for(int i=1;i<=(n<<1);i++)
		if(scc[i]==scc[i+(n<<1)])
			return 0;
	return 1;
}
