class SAT {
private:
	void _dfs(int u){
		used[u] = true;
		for(int v : G[u]){
			if(!used[v]){
				_dfs(v);
			}
		}
		post_order.push_back(u);
	}
	void _rdfs(int u, const int k){
		used[u] = true;
		cmp[u] = k;
		for(int v : rG[u]){
			if(!used[v]){
				_rdfs(v,k);
			}
		}
	}
	int _scc(){
		fill(used.begin(),used.end(),false);
		post_order.clear();
		rep(u,2*V){
			if(!used[u]){
				_dfs(u);
			}
		}
		fill(used.begin(),used.end(),false);
		int k=0;
		for(int i=V-1;i>=0;i--){
			if(!used[post_order[i]]){
				_rdfs(post_order[i],k++);
			}
		}
		return k;
	}

public:
	int V;	//頂点数
	vector<vector<int> > G,rG;
	vector<int> post_order; //帰りがけ順の並び
	vector<bool> used; //すでに調べたかどうか
	vector<int> cmp;	//属する強連結成分のトポロジカル順序
	set<P> es;

	SAT(int node_size) : V(node_size), G(2*V), rG(2*V), used(2*V), cmp(2*V){}
	void _add_edge(int from, int to){
		G[from].push_back(to), rG[to].push_back(from);
	}
    void add_edge(int from, int to){
		es.insert(P(from, to)), es.insert(P((to+V)%(2*V),(from+V)%(2*V)));
	}
	//充足可能性判定
	bool ok(){
		each(val, es){
			_add_edge(val.fi, val.se);
		}
	    _scc();
	    rep(i,V){
	        if(cmp[i] == cmp[V+i]){
	            return false;
	        }
	    }
	    return true;
	}
	//真のものは1,偽のものは0を返す(解の構成)
	void restore(vector<int>& ans){
		ans.resize(V);
	    rep(i,V){
			ans[i] = (cmp[i] > cmp[V+i]);
	    }
	}
};

