void query(const int id, int a, int b, SAT& st, int k = 0, int l = 0, int r = -1){
    if(r < 0) r = N;
    if(r <= a || b <= l){
        return;
    }
    if(a <= l && r <= b){
        st.add_edge(id, k+V);
        return;
    }else{
        query(id,a,b,st,2*k+1,l,(l+r)/2), query(id,a,b,st,2*k+2,(l+r)/2,r);
    }
}

bool possible(int d)
{
    SAT st(V);
    rep(i,n){
		st.add_edge(num[i].fi+N-1+V, num[i].se+N-1);
    }
    for(int i=N-2; i>=0; i--){
		st.add_edge(2*i+1, i), st.add_edge(2*i+2, i);
    }
    rep(i,2*n){
        int s = lower_bound(all(vec),P(vec[i].fi-d+1,-1)) - vec.begin();
        if(s < i) query(i+N-1, s, i, st);
        int e = upper_bound(all(vec),P(vec[i].fi+d-1,INF)) - vec.begin();
        if(i+1 < e) query(i+N-1, i+1, e, st);
    }
    return st.ok();
}

