	}
	int m=l+r>>1;
	if(m>=b)update(o<<1,l,m,a,b,x);
	else if(m<a)update(o<<1|1,m+1,r,a,b,x);
	else update(o<<1,l,m,a,m,x),update(o<<1|1,m+1,r,m+1,b,x);
}

