            S.erase (it);
            it = it2;
            continue;
        }
        if (e) S.insert (make_pair (val[nu_vreau], nu_vreau));
        return it->second;
    }
    it = S.lower_bound (make_pair (x, 0));
    if (it == S.begin ())
    {
