            add_edge(n1+k,v[(k<<1|1)-n1+1].second);
            return;
        }
        int mid=l+r>>1;
        add_edge(n1+k,n1+(k<<1));
        add_edge(n1+k,n1+(k<<1|1));
        build(k<<1,l,mid);
        build(k<<1|1,mid+1,r);
    }

