bool solve (int d) {
    REP (i, n*2) {
        edg[i].clear();
        rev[i].clear();
    }

    REP (i, n) {
        REP (j, i) {
            bool flag = false;
            REP (s1, 2) {
                REP (s2, 2) {
                    if (abs(p[i][s1] - p[j][s2]) < d) {
                        add_edge(i<<1|s1, j<<1|(s2^1));
                        add_edge(j<<1|s2, i<<1|(s1^1));
                    } else {
                        flag = true;
                    }
                }
            }
            if (!flag) {
                return false;
            }
        }
    }

    MEM(vis, 0);
    topo.clear();

    REP (i, n*2) {
        if (!vis[i]) {
            dfs1(i);
        }
    }

    for (int i=SZ(topo)-1; i>=0; i--) {
        if (vis[topo[i]]) {
            dfs2(topo[i]);
            ccnt++;
        }
    }

    REP (i, n) {
        if (cc[i<<1] == cc[i<<1|1]) {
            return false;
        }
    }

    return true;
}
