inline int gi() {
    int x=0,o=1;
    char ch=getchar();
    while(ch!='-'&&(ch<'0'||ch>'9')) ch=getchar();
    if(ch=='-') o=-1,ch=getchar();
    while(ch>='0'&&ch<='9') x=x*10+ch-'0',ch=getchar();
    return x*o;
}
inline void tarjan(int x) {
    dfn[x]=low[x]=++tim;
    w[x]=1,v[++tp]=x;
    for(int i=head[x];i;i=nxt[i]) {
	int y=to[i];
	if(!dfn[y]) {
	    tarjan(y);
	    low[x]=min(low[x],low[y]);
	}
	else if(w[y])
	    low[x]=min(low[x],dfn[y]);
    }
    if(dfn[x]==low[x]) {
	int y;++gg;
	do c[y=v[tp--]]=gg,w[y]=0; while(x!=y);
    }
}
inline void lnk(int x,int y) {
    to[++tt]=y,nxt[tt]=head[x],head[x]=tt;
}
inline void insert(int l,int r,int p,int z,int &y) {
    if(!y) y=++cnt;
    if(l==r) {lnk(y,z);return;}
    int mid=(l+r)>>1;
    if(p<=mid) insert(l,mid,p,z,ls[y]);
    else insert(mid+1,r,p,z,rs[y]);
}
inline void query(int l,int r,int L,int R,int z,int x) {
    if(!x||L>R) return;
    if(L<=l&&r<=R) {lnk(z,x);return;}
    int mid=(l+r)>>1;
    if(L<=mid) query(l,mid,L,R,z,ls[x]);
    if(R>mid) query(mid+1,r,L,R,z,rs[x]);
}
inline int find(int x) {return lower_bound(st+1,st+1+pt,x)-st;}
inline bool check(int k) {
    int rt=0;
    cnt=n+n+1,tt=0;
    memset(ls,0,sizeof(ls));
    memset(rs,0,sizeof(rs));
    memset(dfn,0,sizeof(dfn));
    memset(head,0,sizeof(head));
    for(int i=1;i<=n;i++) {
	insert(1,pt,a[i],i*2+1,rt);
	insert(1,pt,b[i],i*2,rt);
    }
    for(int i=1;i<=n;i++) {
	query(1,pt,find(st[a[i]]-k+1),a[i]-1,i*2,rt);
	query(1,pt,a[i]+1,find(st[a[i]]+k)-1,i*2,rt);
	query(1,pt,find(st[b[i]]-k+1),b[i]-1,i*2+1,rt);
	query(1,pt,b[i]+1,find(st[b[i]]+k)-1,i*2+1,rt);
    }
    for(int i=1;i<=cnt;i++) {
	if(ls[i]) lnk(i,ls[i]);
	if(rs[i]) lnk(i,rs[i]);
    }
    for(int i=2;i<=cnt;i++)
	if(!dfn[i]) tarjan(i);
    for(int i=2;i<=n+n;i+=2)
	if(c[i]==c[i+1]) return 0;
    return 1;
}
int main() {
    cin>>n;
    for(int i=1;i<=n;i++) {
	int x=gi(),y=gi();
	st[++pt]=x,st[++pt]=y;
	a[i]=x,b[i]=y;
    }
    sort(st+1,st+1+pt);
    for(int i=1;i<=pt;i++) sc[i]=i;
    for(int i=1;i<=n;i++) {
	a[i]=sc[find(a[i])]++;
	b[i]=sc[find(b[i])]++;
    }
    int l=1,r=M/n;
    while(l<=r) {
	int mid=(l+r)>>1;
	if(check(mid)) l=mid+1;
	else r=mid-1;
    }
    cout<<r;
    return 0;
}

