inline void build(int x,int l,int r)
{
	if(l==r)
		return;
	build(x<<1,l,mid);
	build(x<<1|1,mid+1,r);
	add((x<<1)+ptop,x+ptop);
	add((x<<1|1)+ptop,x+ptop);
}

inline void adds(int x,int l,int r,int dl,int dr,int id)
{
	if(dl==l && r==dr)
	{
		add(id,x+ptop);
		return;
	}
	if(dr<=mid)
		adds(x<<1,l,mid,dl,dr,id);
	else if(mid<dl)
		adds(x<<1|1,mid+1,r,dl,dr,id);
	else
	{
		adds(x<<1,l,mid,dl,mid,id);
		adds(x<<1|1,mid+1,r,mid+1,dr,id);
	}
}

inline bool judge(int k)
{
	dfn=scccnt=0;
	for(int i=0;i<ptop;i++)
		g[i].clear();
	memset(low,0,sizeof(low));
	memset(scc,0,sizeof(scc));

