	for(int i=0;i<ptop;i++)
	{
		for(int j=i-1,cnt=1;~j && pt[j].x+k>pt[i].x && cnt<=50;j--,cnt++)
		{
			add(pt[i].id,pt[j].id^1);
			add(pt[j].id,pt[i].id^1);
		}
	}


	for(int i=0;i<ptop;i++)
		if(!low[i])
			dfs(i);
	for(int i=0;i<n;i++)
		if(scc[i<<1]==scc[i<<1|1])
			return false;
	return true;
}

