struct twosat{
    int n;
    vector<vector<int> > adj, radj, scc;
    vector<int> sid, vis;
    stack<int> st;
    int cnt;

    void init(int m){
        n = m;
        adj.clear();
        radj.clear();
        sid.clear();
        vis.clear();
        scc.clear();

        adj.resize(m);
        radj.resize(m);
        sid.resize(m);
        vis.resize(m);
    }

    void impl(int x, int y){
        adj[x].push_back(y);
        radj[y].push_back(x);
    }
    void vee(int x, int y){
        impl(x^1, y);
        impl(y^1, x);
    }
    void nand(int x, int y){
        vee(x^1, y^1);
    }
    void xoro(int x, int y){
        vee(x, y);
        vee(x^1, y^1);
    }

    void dfs1(int x){
        if(vis[x]++) return;
        for(int i=0;i<adj[x].size();i++) dfs1(adj[x][i]);
        st.push(x);
    }
    void dfs2(int x){
        if(!vis[x]) return;
        vis[x] = 0;
        sid[x] = cnt;
        scc.back().push_back(x);
        for(int i=0;i<radj[x].size();i++) dfs2(radj[x][i]);
    }
    bool two_sat(){
        cnt = 0;
        for(int i=0;i<n;i++) dfs1(i);
        while(!st.empty()){
            int v = st.top();
            st.pop();
            if(vis[v]){
                scc.push_back(vector<int>());
                dfs2(v);
                cnt++;
            }
        }
        for(int i=0;i<n;i+=2){
            if(sid[i] == sid[i+1]) return false;
        }
        return true;
    }
};

twosat sat;

void build(int n, int s, int e){
    if(s == e) return;
    else{
        int mid = (s+e)/2;
        build(n+n, s, mid);
        build(n+n+1, mid+1, e);

        sat.impl((n+n)*2, n*2);
        sat.impl((n+n+1)*2, n*2);
    }
}
void query(int n, int s, int e, int l, int r, vector<int> &Q){
    if(s > r || l > e) return;
    if(l <= s && e <= r){
        Q.eb(n);
        return;
    }
    int mid = (s+e)/2;
    query(n+n, s, mid, l, r, Q);
    query(n+n+1, mid+1, e, l, r, Q);
}
