        ++R;
      }
      vector<int> vers;
      function<void(int, int, int)> Mark = [&](int x, int l, int r) {
        if (marked[x] || l == r) {
          return;
        }
        marked[x] = true;
        int y = (l + r) >> 1;
        int z = x + 2 * (y - l + 1);
        ts.add(x + 1, 0, z, 0);
        ts.add(x + 1, 0, x, 1);
        ts.add(z, 0, x, 1);
        Mark(x + 1, l, y);
        Mark(z, y + 1, r);
      };
      function<void(int, int, int, int, int)> Go = [&](int x, int l, int r, int ll, int rr) {
        if (ll <= l && r <= rr) {
          vers.push_back(x);
          Mark(x, l, r);
          return;
        }
        int y = (l + r) >> 1;
        int z = x + 2 * (y - l + 1);
        if (ll <= y) {
          Go(x + 1, l, y, ll, rr);
        }
        if (rr > y) {
          Go(z, y + 1, r, ll, rr);
        }
      };
      Go(0, 0, 2 * n - 1, L, R);
      int sz = (int) vers.size();
      int off = ts.n;
      ts.n += sz - 1;
      ts.g.n += 2 * (sz - 1);
      ts.g.g.resize(ts.g.n);
      for (int i = 0; i < sz - 1; i++) {
        ts.add(off + i, 1, vers[i], 0);
        if (i > 0) {
          ts.add(off + i, 1, off + (i - 1), 0);
        }
        ts.add(off + i, 0, vers[i + 1], 0);
      }
    }
    for (int i = 0; i < n; i++) {
      ts.add(single[pos[i][0]], 0, single[pos[i][1]], 0);
      ts.add(single[pos[i][0]], 1, single[pos[i][1]], 1);
    }
    debug(mid, ts.g.edges.size());
    if (!ts.solve().empty()) {
      low = mid;
    } else {
      high = mid - 1;
    }
  }
  cout << low << '\n';
  return 0;
}

