struct NODE {
	int id , wh , val , ano;
	friend bool operator < (NODE xxx , NODE yyy) {
		return xxx.val < yyy.val;
	}
}P[N];

#define lc(x) (x << 1)
#define rc(x) (x << 1 | 1)

void add(int x , int y) {
	ne[++ cnt] = fir[x]; fir[x] = cnt; to[cnt] = y;
}

void link(int x , int y) {
	add(x , y); add(y ^ 1 ,  x ^ 1);
}

int abs(int x) {
	return (x < 0) ? - x : x;
}

void addtag(int it , short l , short r) {
	if(l > r) return;
	if(r - l <= 2 * Size) {
		for(int i = l;i <= r;i ++) {
			link(it , P[i].id ^ 1);
		}
		return;
	}

	for(int i = whe[l] + 1 - (l ==mi[whe[l]]);i <= whe[r] - 1 + (r == mx[whe[r]]);i ++) link(it , lc(i));
	if(l != mi[whe[l]])for(int i = l;i <= mx[whe[l]];i ++) link(it , P[i].id ^ 1);
	if(r != mx[whe[r]])for(int i = mi[whe[r]];i <= r;i ++) link(it , P[i].id ^ 1);
}

void build(int cur) {
	memset(fir , 0 , sizeof(fir));
	cnt = 0;
	for(int i = 1;i <= tot;i ++) {
		link(lc(whe[i]) , P[i].id ^ 1);
	}
	int l = 1 , r = 1;
	for(int i = 1;i <= tot;i ++) {
		while(abs(P[l].val - P[i].val) >= cur && l < i) l ++;
		while(r < tot && abs(P[r + 1].val - P[i].val) < cur) r ++;
		addtag(P[i].id , l , i - 1);
		addtag(P[i].id , i + 1 , r);
	}
}

#define Foreachson(i , x) for(int i = fir[x];i;i = ne[i])
bool die = 0;

void dfs(int x) {
	if(die) return;
	low[x] = dfn[x] = ++ dfs_clock; stk[++ top] = x;
	Foreachson(i , x) {
		int V = to[i];
		if(dfn[V]) {
			if(!scc_no[V])low[x] = min(low[x] , low[V]);
		}
		else {
			dfs(V); low[x] = min(low[x] , low[V]);
		}
	}
	if(low[x] == dfn[x]) {
		col ++;
		for(;;) {
			scc_no[stk[top --]] = col;
			if(scc_no[stk[top + 1]] == scc_no[stk[top + 1] ^ 1]) {
				die = 1; return;
			}
			if(stk[top + 1] == x) break;
		}
	}
}

bool SAT(void) {
	die = 0;
	memset(dfn , 0 , sizeof(dfn)); memset(low , 0 , sizeof(low)); memset(scc_no , 0 , sizeof(scc_no)); top = col = dfs_clock = 0;
	for(int i = 2;i <= rc(whe[tot]);i ++) {
		if(!dfn[i]) dfs(i);
		if(die) return 0;
	}
	for(int i = 1;i <= whe[tot];i ++) {
		if(scc_no[lc(i)] == scc_no[rc(i)]) return 0;
	}
	return 1;
}

bool pd(int x) {
	build(x);
	return SAT();
}

