void add_edge(int from, int to)
{
    G[from].pb(to);
    rG[to].pb(from);
}

void dfs(int v)
{
    vis[v] = true;

    for (int to : G[v]) {
	if (!vis[to]) dfs(to);
    }

    vs.push_back(v);
}

void rdfs(int v, int k)
{
    vis[v] = true;
    cmp[v] = k;

    for (int to : rG[v]) {
	if (!vis[to]) rdfs(to, k);
    }
}

int scc()
{
    memset(vis, 0, sizeof(vis));
    vs.clear();

    rep(v, V) if (!vis[v]) dfs(v);

    memset(vis, 0, sizeof(vis));

    int k = 0;
    reverse(ALL(vs));

    for (int v : vs) if (!vis[v]) rdfs(v, k++);

    return k;
}

int N;
