void Build (int &x, int l, int r, int *id, int tj) {
	if (l == r) return void(x = id[l] + tj);
	x = ++cnt;
	int mid = (l + r) >> 1;
	Build(L, l, mid, id, tj);
	Build(R, mid + 1, r, id, tj);
	V[x].emplace_back(L);
	V[x].emplace_back(R);
}

