        d[++cnt] = num[id[i]]; g[cnt] = num[id[i + o] + n];
        d[++cnt] = num[id[i + o] + n]; g[cnt] = num[id[i]];
        int R = lower_bound(c + 1, c + n + 1, c[id[i]] + x) - c - 1;
        int L = upper_bound(c + 1, c + n + 1, c[id[i]] - x) - c;
        insert(num[id[i]], 1, 1, n << 1, L + n, id[i] + n - 1);
        insert(num[id[i]], 1, 1, n << 1, id[i] + n + 1, R + n); 
    }
    for(int i = 1; i <= cnt; i++) add(d[i], g[i]);
    tarjan(1);
    for(int i = 1; i <= n; i++){
        if(tag[num[id[i]]] == tag[num[id[i] + n]]) return false;
    }
    return true;
}
