using namespace std;

const int MAX_N = 10005, MAX_V = 100005;

class Edge {
public:
  int nxt, to;
} e[2000006];

class Data {
public:
  int pos, id, rid;
  inline friend bool operator < (const Data &a, const Data &b) {
    return a.pos < b.pos;
  }
} da[MAX_N << 1];

int head[MAX_V], cnt;
void addedge(int u, int v) {
  e[++cnt] = (Edge){head[u], v}, head[u] = cnt;
}

int N, X[MAX_N], Y[MAX_N], tot, in[MAX_V], out[MAX_V];
int dfn[MAX_V], dfs_clock, scc[MAX_V], scc_cnt, low[MAX_V];

void dfs(int u, int v) {
  static int st[MAX_N], top;
  dfn[u] = low[u] = ++dfs_clock;
  st[++top] = u;
  for (int i = head[u]; i; i = e[i].nxt)
    if (e[i].to != v) {
      if (!dfn[e[i].to]) {
	dfs(e[i].to, u);
	low[u] = min(low[u], low[e[i].to]);
      } else if (!scc[e[i].to]) {
	low[u] = min(low[u], dfn[e[i].to]);
      }
    }
  if (low[u] == dfn[u]) {
    ++scc_cnt;
    while (true) {
      scc[st[top--]] = scc_cnt;
      if (st[top + 1] == u) break;
    }
  }
}

void tarjan() {
  memset(scc, 0, sizeof scc);
  memset(dfn, 0, sizeof dfn);
  scc_cnt = dfs_clock = 0;
  for (int i = 1; i <= tot; ++i)
    if (!dfn[i]) dfs(i, 0);
}

void build(int l, int r, int x) {
  in[x] = ++tot, out[x] = ++tot;
  if (l == r) {
    in[x] = da[l].rid, out[x] = da[l].id;
    return;
  }
  int mid = (l + r) >> 1;
  build(l, mid, x << 1), build(mid + 1, r, x << 1 | 1);
  addedge(in[x], in[x << 1]), addedge(in[x], in[x << 1 | 1]);
  addedge(out[x << 1], out[x]), addedge(out[x << 1 | 1], out[x]);
}

void work(int l, int r, int L, int R, int x, int id, int rid) {
  if (L <= l && r <= R) {
    addedge(id, in[x]), addedge(out[x], rid);
    return;
  }
  int mid = (l + r) >> 1;
  if (mid >= L) work(l, mid, L, R, x << 1, id, rid);
  if (mid < R) work(mid + 1, r, L, R, x << 1 | 1, id, rid);
}

bool check(int mid) {
static int cp[MAX_V], temp;
  memcpy(cp, head, sizeof head), temp = cnt;

  for (int i = 1; i <= N << 1; ++i) {
    int l = upper_bound(da + 1, da + i + 1, (Data){da[i].pos - mid, 0, 0}) - da;
    int r = lower_bound(da + 1, da + N + N + 1, (Data){da[i].pos + mid, 0, 0}) - da - 1;
    if (l <= 0) l = 1;
    if (r > N + N) r = N + N;
    if (l < i) work(1, N + N, l, i - 1, 1, da[i].id, da[i].rid);
    if (r > i) work(1, N + N, i + 1, r, 1, da[i].id, da[i].rid);
  }

  bool flag = 1;
  tarjan();
  for (int i = 1; i <= N; ++i)
    if (scc[i] == scc[i + N]) flag = 0;
  memcpy(head, cp, sizeof head), cnt = temp;
  return flag;
}

int main() {
  scanf("%d", &N);
  for (int i = 1; i <= N; ++i) {
    scanf("%d%d", &X[i], &Y[i]);
    da[i] = (Data){X[i], i, i + N};
    da[i + N] = (Data){Y[i], i + N, i};
  }

  sort(da + 1, da + N + N + 1);
  tot = N << 1;
  build(1, N + N, 1);

  int l = 0, r = 1000000000, res = 0;
  while (l <= r) {
    int mid = (l + r) >> 1;
    if (check(mid)) res = mid, l = mid + 1;
    else r = mid - 1;
  }

  printf("%d\n", res);
  return 0;
}

