inline void add(int x, int y) { edge[++ cnt] = (qwq) { y, head[x] }, head[x] = cnt; }

struct info { 
	int val, id; 
	info() {}
	info(int _val, int _id) : val(_val), id(_id) {} 
	bool operator <(const info y)const { 
		return val == y.val ? id < y.id : val < y.val; 
	}
} a[N];

