inline int id(int x, int op) { return op ? x + n : x; }

void lk(int x, int l, int r, int ql, int qr, int p) {
	if(ql > qr) return ;
	if(ql <= l && qr >= r) { add(p, u); return; }
	int mid = l + r >> 1;
	if(ql <= mid) lk(ls, l, mid, ql, qr, p);
	if(qr > mid) lk(rs, mid + 1, r, ql, qr, p);
}
bool fl = 0;
void build(int x, int l, int r) {
	if(l == r) { 
		u = a[l].id > n ? a[l].id - n : a[l].id + n; 
//		if(fl) printf("%d:[%d,%d]\n", u, l, r);
		return ; 
	}
	u = ++ ptot;
//	if(fl) printf("%d:[%d,%d]\n", u, l, r);
	int mid = l + r >> 1;
	build(ls, l, mid), build(rs, mid + 1, r);
	add(u, uls), add(u, urs);
}

int dfn[N << 1], bel[N << 1], belnum, tp, tim, stk[N << 1], low[N << 1];
int instk[N << 1], vtim;

void dfs(int x, int f) {
	low[x] = dfn[x] = ++ tim;
	stk[++ tp] = x;
	instk[x] = vtim;
	REPG(i, head, x) if((v = edge[i].v) != f){
		if(!dfn[v]) {
			dfs(v, x), low[x] = min(low[v], low[x]);
		}
		else if(instk[v] == vtim) {
			low[x] = min(dfn[v], low[x]);
		}
	}
	if(low[x] == dfn[x]) {
		++ belnum;
		int tmp = stk[tp];
		while(tmp != x) {
			bel[tmp] = belnum;
			instk[tmp] = 0;
			tmp = stk[-- tp];
		} 
		bel[stk[tp]] = belnum;
		instk[stk[tp --]] = 0;
	}
}

bool chk(int k) {
	cnt = 0, CLR(head, -1);
	ptot = len;
	build(1, 1, len);
	REP(i, 1, len) {
		int l = lower_bound(a + 1, a + len + 1, info(a[i].val - k + 1, 0)) - a;
		int r = upper_bound(a + 1, a + len + 1, info(a[i].val + k - 1, len + 3)) - a - 1;
		lk(1, 1, len, l, pos[a[i].id] - 1, a[i].id);
		lk(1, 1, len, pos[a[i].id] + 1 , r, a[i].id);
	}
	CLR(bel, 0), CLR(dfn, 0), CLR(low, 0), belnum = tp = tim = 0, ++ vtim;
	REP(i, 1, ptot) {
		if(!dfn[i]) dfs(i, 0);
	} 
	REP(i, 1, n) {
		if(bel[i] == bel[i + n]) return 0;
	}
	return 1;
}

