int seg[MAX * 4];

int SZ;

int ids[MAX];

vector < pair<int, int> > ed;

inline void init(int b, int l, int r){
	if (l + 1 == r){
		ids[l] = b;
		SZ = max(SZ, b);
		return;
	}
	init(b * 2 + 1, l, (l + r) >> 1);
	init(b * 2 + 2, (l + r) >> 1, r);
	ed.push_back(make_pair(b, b * 2 + 1));
	ed.push_back(make_pair(b, b * 2 + 2));
}

inline void query(int b, int l, int r, int ll, int rr, int x,SAT2 &sat){
	if (rr <= l || r <= ll){
		return;
	}
	if (ll <= l&&r <= rr){
		sat.add_edge(x, true, b, false);
		sat.add_edge(b, true, x, false);
		return;
	}
	query(b * 2 + 1, l, (l + r) >> 1, ll, rr, x, sat);
	query(b * 2 + 2, (l + r) >> 1, r, ll, rr, x, sat);
}

int add[MAX * 2];


bool ok(long long int d){
	if (d == 0){
		return true;
	}
	SAT2 sat;
	sat.resize(SZ);
	int sz = ed.size();
	for (int i = 0; i < sz; i++){
		sat.add_edge(ed[i].first, 0, ed[i].second, 0);
		sat.add_edge(ed[i].second, 1, ed[i].first, 1);
	}
	for (int i = 0; i < n; i++){
		sat.add_edge(add[i],0, add[i + n],1);
		sat.add_edge(add[i], 1, add[i+n], 0);
		sat.add_edge(add[i + n], 1, add[i], 0);
		sat.add_edge(add[i + n], 0, add[i], 1);
	}
	for (int i = 0; i < val.size(); i++){
		int lef = i + 1;
		int rig = lower_bound(val.begin(), val.end(), make_pair(val[i].first + d,-1) )-val.begin();
		if (lef < rig){
			query(0, 0, n*2, lef, rig, ids[i], sat);
		}
		rig = i;
		lef = upper_bound(val.begin(), val.end(), make_pair(val[i].first - d,INT_MAX)) - val.begin();
		if (lef < rig){
			query(0, 0, n*2, lef, rig, ids[i], sat);
		}
	}
	if (sat.can()){
		return true;
	}
	return false;
}
