    Build(L, mid);
    add(no, rc);
    Build(mid + 1, R);
  }

  inline void Init() {
    memset(fir, 0, sizeof fir);
    cnt = 0;
    Build(0, t - 1);
  }

  inline void Add_edge(int L, int R, int x, int l, int r) {
    if (l > r) return;
    if (r < L || l > R) return;
    if (l <= L && R <= r) {
      add(x, no);
      return;
    }
    if (L == R) return;
