  }

  inline void Tarjan() {
    memset(bel, 0, sizeof bel);
    memset(dfn, 0, sizeof dfn);
    memset(vis, 0, sizeof vis);
    clo = top = cnt_bcc = 0;
    for (int i = 0; i <= ID(t - 1, t - 1); i ++)
