struct Graph {
    VI pos;

    set <pii> vert;
    set <pii> negVert;

    VB vis;

    int d;
    bool rev = false;

    Graph(int d): d(d) {}

    void addVertex(int p) {
        int id = SIZE(pos);

        pos.pb(p);
        vert.insert({p, id});
        negVert.insert({p, id ^ 1});
        vis.pb(false);
    }

    int neigh(int v) {
        int p = pos[v ^ rev];

        if (rev) {
            auto it = vert.lower_bound({p - d, -1});

            if (it != vert.end() && it->nd == (v ^ 1)) {
                it++;
            }

            if (it != vert.end() && it->st <= p + d) {
                return it->nd;
            }        
        } else {
            auto it = negVert.lower_bound({p - d, -1});

            if (it != negVert.end() && it->nd == (v ^ 1)) {
                it++;
            }

            if (it != negVert.end() && it->st <= p + d) {
                return it->nd;
            }
        }

        return -1;
    }

    void visit(int v) {
        vis[v] = true;
        vert.erase({pos[v], v});
        negVert.erase({pos[v ^ 1], v});
    }
};

