struct SAT2 {
    int n;
    Graph G; VI t;

    SAT2(int n, Graph &G): n(2 * n), G(G), t(2 * n,-1) {}

    void sccV1(int v, Graph &G, VI &V) {
        G.visit(v);

        int u;
        while ((u = G.neigh(v)) != -1) {
            sccV1(u, G, V);
        }

        V.pb(v);
    }

    void sccV2(int v, int nr, Graph &G) {
        G.visit(v);

        t[v] = nr;

        int u;
        while ((u = G.neigh(v)) != -1) {
            sccV2(u, nr, G);
        }
    }

    int scc() {
        int nr = -1;

        VI V;

        Graph Gt = G;
        Gt.rev = true;

        FOR(i,0,n-1) if (!Gt.vis[i]) {
            sccV1(i, Gt, V);
        }

        FORDE(i,V) if (!G.vis[V[i]]) {
            nr++;
            sccV2(V[i], nr, G);
        }

        return nr + 1;
    }

    bool solveSat() {
        int cnt = scc();

        FOR(i,0,n/2-1) if (t[2 * i] == t[2 * i + 1]) {
            return false;
        }

        return true;
    }
};

/*************************************************************************/

bool check(int n, int d, VI &x, VI &y) {
    Graph g(d);

    FOR(i,0,n-1) {
        g.addVertex(x[i]);
        g.addVertex(y[i]);
    }

    SAT2 sat(n, g);
    return sat.solveSat();
}

