void init()  // 输入
{
    r = 0 ;
    int i ;
    for(i = 0 ; i < n ; i ++)
    {
        int a , b ;
        scanf("%d%d" , &a , &b) ;
        tm[i << 1] = a ;  // tm[i * 2] 代表第 i 架飞机的早着陆时间
        r = max(a , r) ;
        tm[(i << 1) + 1] = b ; // tm[i * 2 + 1] 代表 第 i 架飞机的晚着陆时间
        r = max(b , r) ;
    }
}
void chu() // 清空图
{
    int i ;
    for(i = 0 ; i < n * 2 ; i ++)
    {
        G[i].clear() ;
    }
}
void add_e(int x , int y)  // 向图中添加边
{
    G[x].push_back(y ^ 1) ;
    G[y].push_back(x ^ 1) ;
}
void build_G(int t)  // 建图
{
    chu() ;
    int i , j ;
    for(i = 0 ; i < n * 2 ; i ++)
    {
        for(j = i + 1 ; j < n * 2 ; j ++)
        {
            if(j == (i ^ 1) )
                continue ;
            if(abs(tm[i] - tm[j]) < t)
            {
                add_e(i , j) ;
            }
        }
    }
}
bool dfs(int x)
{
    if(mark[x ^ 1]) return false ;
    if(mark[x]) return true ;
    mark[x] = true ;
    S[c ++] = x ;
    int i ;
    for(i = 0 ; i < G[x].size() ; i ++)
    {
        if(!dfs(G[x][i]))
        return false ;
    }
    return true ;
}
int can(int t)
{
    build_G(t) ;
    mem(mark , 0) ;
    int i ;
    for(i = 0 ; i < n ; i ++)
    {
        if(!mark[i * 2] && !mark[i * 2 + 1])
        {
            c = 0 ;
            if(!dfs(i * 2))
            {
                while (c > 0)
                {
                    mark[S[-- c]] = false ;
                }
                if(!dfs(i * 2 + 1))
                {
                    return 0 ;
                }
            }
        }
    }
    return 1 ;
}
void solve()
{
    le = 0 ;
    while (le < r)
    {
        mid = le + (r - le + 1) / 2 ; 
        if(can(mid))
        {
            le = mid ;
        }
        else
        {
            r = mid - 1 ;
        }
    }
    printf("%d\n" , le) ;
}
int main()
{
    while (scanf("%d" , &n) != EOF)
    {
        init() ;
        solve() ;
    }
    return 0 ;
}

