	for(int i=0;i<n*2;i++){
		int id=a[i].second;
		pair<int,int> x=get(i,d);
		if(i<x.second)link(1,0,n*2,i+1,x.second+1,id);
		if(x.first<i)link(1,0,n*2,x.first,i,id);
	}
	C=cnt=0;
	for(int i=0;i<n*2;i++)if(!dfn[i])tarjan(i);
	for(int i=0;i<n*2;i++)
		if(scc[a[i].second]==scc[a[i].second^1])return false;
	return true;
}

