    int mid=l+r>>1;
    if(mid>=b)update(nod<<1,l,mid,a,b,x);
	else if(mid<a)update(nod<<1|1,mid+1,r,a,b,x);
	else update(nod<<1,l,mid,a,mid,x),update(nod<<1|1,mid+1,r,mid+1,b,x);
}
