// Labels strongly connected components in reverse topological order.
// That means for any edge u-->v comp[u] >= comp[v].
pair<int, vi> strongly_connected_components(const vvi& graph) {
    const int N = graph.size();
    int C = 0, V = 0, top = 0;
    vi comp(N, -1), inx(N, -1), stack(N + 1, -1);

    auto tarjan = [&](auto&& self, int loc) -> int {
        stack[top++] = loc;
        int low = inx[loc] = V++;
        for (int nbr : graph[loc]) {
            if (inx[nbr] == -1) low = min(low, self(self, nbr));
            else if (comp[nbr] == -1) low = min(low, inx[nbr]);
        }
        if (low == inx[loc]) {
            while (stack[top] != loc)
                comp[stack[--top]] = C;
            C++;
        }
        return low;
    };

    for (int i = 0; i < N; i++) {
        if (inx[i] == -1)
            tarjan(tarjan, i);
    }
    return { C, comp };
}

struct two_sat {
    vvi graph;
    two_sat() {}

    inline int neg(int a) { return a^1; }

    void implies(int a, int b) {
        if (a < 0 || b < 0) return;
        graph[a].pb(b);
        graph[neg(b)].pb(neg(a));
    }

    void assign(int a, int v) {
        if (v) implies(neg(a), a);
        else implies(a, neg(a));
    }
    void equal(int a, int b) {
        implies(a, b);
        implies(neg(a), neg(b));
    }
    void not_equal(int a, int b) {
        implies(a, neg(b));
        implies(neg(a), b);
    }
    void at_most_one(int a, int b) {
        implies(a, neg(b)); // contrapositive is automatic
    }
    void at_least_one(int a, int b) {
        implies(neg(a), b); // contrapositive is automatic
    }

    int new_var() {
        graph.pb({});
        graph.pb({});
        return sz(graph) - 1;
    }

    int make_or(int a, int b) {
        if (a < 0) return b;
        if (b < 0) return a;
        int v = new_var();
        implies(a, v);
        implies(b, v);
        return v;
    }

    int make_and(int a, int b) {
        if (a < 0) return b;
        if (b < 0) return a;
        int v = new_var();
        implies(v, a);
        implies(v, b);
        return v;
    }

    vb solve() {
		auto x = strongly_connected_components(graph);
		int C = x.f; vi comp = x.s;
        vb res(sz(graph));
        for (int v = 0; v < sz(res); v++) {
            if (comp[v] == comp[neg(v)]) return {};
            res[v] = comp[v] < comp[neg(v)];
        }
        return res;
    }
};

bool test(vpii pts, int d) {
	int n = pts.size();
	two_sat g;
	vi els(n);
	FOR(i,0,n) {
		els[i] = g.new_var();
		FOR(j,0,i) {
			if(abs(pts[i].f - pts[j].f) < d) {
				g.implies(els[i], els[j]^1);
				g.implies(els[j], els[i]^1);
			}
			if(abs(pts[i].f - pts[j].s) < d) {
				g.implies(els[i], els[j]);
				g.implies(els[j]^1, els[i]^1);
			}
			if(abs(pts[i].s - pts[j].f) < d) {
				g.implies(els[i]^1, els[j]^1);
				g.implies(els[j], els[i]);
			}
			if(abs(pts[i].s - pts[j].s) < d) {
				g.implies(els[i]^1, els[j]);
				g.implies(els[j]^1, els[i]);
			}
		}
	}
	return sz(g.solve());
}

