namespace twosat_Tarjan {
    int n2;
    vector<int> g[mn];
    int pre[mn], lowlink[mn], sccno[mn], dfs_clock, scc_cnt;
    stack<int> s;

    void dfs(int u) {
        pre[u] = lowlink[u] = ++dfs_clock;
        s.push(u);
        for (int i = 0; i < g[u].size(); i++) {
            int v = g[u][i];
            if (!pre[v]) {
                dfs(v);
                lowlink[u] = min(lowlink[u], lowlink[v]);
            } else if (!sccno[v]) {
                lowlink[u] = min(lowlink[u], pre[v]);
            }
        }
        if (lowlink[u] == pre[u]) {
            scc_cnt++;
            while (1) {
                int x = s.top();
                s.pop();
                sccno[x] = scc_cnt;
                if (x == u) break;
            }
        }
    }

    void add_edge(int x, int xval, int y, int yval) {
        g[x << 1 | xval].pb(y << 1 | yval);
    }

    void add_edge(int x,int y){ //x->y 表示 x 能推导出 y
        //printf("add_edge %d->%d\n",x,y);
        g[x].pb(y);
    }

#define mem(a) memset(a,0,sizeof(a))

    void find_scc() {
        dfs_clock = scc_cnt = 0;
        mem(sccno);
        mem(pre);
        for (int i = 1; i <= n2; i++) if (!pre[i]) dfs(i);
    }

    bool solvable() {//是否有解
        find_scc();
        for (int i = 1; i < v.size(); i++) {
            if (sccno[i] == sccno[v[i].second]) {
                //printf("failed on :%d %d\n",i,v[i].second);
                return 0;
            }
        }
        return 1;
    }
}

using namespace twosat_Tarjan;

namespace segment_tree{
    int n1;

    void build(int k,int l,int r){
        if (l==r-1){
            add_edge(n1+k,v[(k<<1)-n1+1].second);
            add_edge(n1+k,v[(k<<1|1)-n1+1].second);
            return;
        }
        int mid=l+r>>1;
        add_edge(n1+k,n1+(k<<1));
        add_edge(n1+k,n1+(k<<1|1));
        build(k<<1,l,mid);
        build(k<<1|1,mid+1,r);
    }

    void tinit(){
        n2=n*2;
        n1=1;
        while(n1<n2) n1<<=1;
        build(1,1,n1);
    }

    vector<int> temp;
    void reinit(){
        for(auto &i:temp){
            g[i].pop_back();
        }
        temp.clear();
    }

    int ql,qr,qs;
    void paint(int k,int l,int r){
        if (ql>r||qr<l) return;
        if (ql<=l&&r<=qr) {
            if (l==r) add_edge(qs,v[k-n1+1].second);
            else add_edge(qs,n1+k);
            temp.pb(qs);
        }
        else{
            int mid=r+l>>1;
            paint(k<<1,l,mid);
            paint(k<<1|1,mid+1,r);
        }
    }
}

