        int l=upper_bound(v.begin(),v.end(),pii(i.first-x,100000000))-v.begin();
        int r=lower_bound(v.begin(),v.end(),pii(i.first+x,-1))-v.begin()-1;
        l=max(l,1);
        if (l<j){
            ql=l,qr=j-1,qs=j;
            paint(1,1,n1);
        }
        if (r>j){
            ql=j+1,qr=r,qs=j;
            paint(1,1,n1);
        }
        //printf("%d paint: %d %d\n",j,l,r);
    }
    return solvable();
}


