		build(root[i],root[i],1,n*2,lower_bound(tmp+1,tmp+2*n+1,x[i])-tmp,i+n);
		build(root[i],root[i],1,n*2,lower_bound(tmp+1,tmp+2*n+1,y[i])-tmp,i);
	}
	dwn(i,n,1) {
