struct LazySegmentTree {
private:
    int n;
    UnWeightedGraph g;

public:
    LazySegmentTree() {
        int sz = 2 * N;
        n = 1; while(n < sz) n *= 2;
        g.resize(2 * n - 1);
        //cerr << "SIZE: " << 2 * n - 1 << endl;
        for(int i=n-2; i>=0; i--) {
            g[i].push_back(i*2+1);
            g[i].push_back(i*2+2);
            //cerr << "from " << i << " to " << i *2 + 1 << endl;
            //cerr << "from " << i << " to " << i *2 + 2 << endl;
        }
    }

/*
    // k 番目のノードについて遅延評価を行う
    void eval(int k, int l, int r) {

    // 遅延配列が空でない場合、自ノード及び子ノードへの
    // 値の伝播が起こる
        if(lazy[k] != 0) {
            node[k] += lazy[k];

        // 最下段かどうかのチェックをしよう
        // 子ノードは親ノードの 1/2 の範囲であるため、
        // 伝播させるときは半分にする
            if(r - l > 1) {
                lazy[2*k+1] += lazy[k] / 2;
                lazy[2*k+2] += lazy[k] / 2;
            }

        // 伝播が終わったので、自ノードの遅延配列を空にする
            lazy[k] = 0;
        }
    }
*/
    void add(int a, int b, ll from, int k=0, int l=0, int r=-1) {
        if(r < 0) r = n;

    // 範囲外なら何もしない
        if(b <= l || r <= a) return;

    // 完全に被覆しているならば、遅延配列に値を入れた後に評価
        if(a <= l && r <= b) {
            g[from + n - 1].push_back(k);
            //cerr << "from: " << from+n-1 << " to " << k << endl;
        }

    // そうでないならば、子ノードの値を再帰的に計算して、
    // 計算済みの値をもらってくる
        else {
            add(a, b, from, 2*k+1, l, (l+r)/2);
            add(a, b, from, 2*k+2, (l+r)/2, r);
        }
    }

    bool run() {
        UnWeightedGraph tmp(2 * n - 1);
        StronglyConnectedComponents<UnWeightedGraph> SCC(g);
        SCC.build(tmp);
        for(int i = 1; i <= N; i++) {
            if(SCC[indexes[i].first + n-1] == SCC[indexes[i].second + n-1]) return false;
        }
        return true;
    }
};

