void tarjan(int x) {
    low[x] = dfn[x] = ++dfntot; vis[x] = true; s[++Top] = x;
    for (Edge *i = head[x]; i; i = i->nxt) {
        if(!dfn[i->to]) tarjan(i->to), low[x] = std::min(low[x], low[i->to]);
        else if(vis[i->to]) low[x] = std::min(low[x], dfn[i->to]);
    }
    if(dfn[x] == low[x]) {
        ++scctot; int k;
        do {
            k = s[Top --];
            scc[k] = scctot;
            vis[k] = false;
        } while(Top && k != x);
    }
}

