        int r = std::upper_bound(v + 1, v + (n << 1) + 1, (node){v[i].val + mid - 1, 0}) - v - 1;
        if (l <= i - 1) add(root, 1, n << 1, l, i - 1, x);
        if (r >= i + 1) add(root, 1, n << 1, i + 1, r, x);
    }
    memset(dfn, 0, sizeof (dfn));
    tarjan(root);
    for (int i = 1; i <= n; ++i) {
        if (scc[i] == scc[i + n]) return false;
    }
    return true;
}

