namespace segment_tree{
    int n1;

    void build(int k,int l,int r){
        if (l==r-1){
            add_edge(n1+k,v[(k<<1)-n1+1].second);
            add_edge(n1+k,v[(k<<1|1)-n1+1].second);
            return;
        }
        int mid=l+r>>1;
        add_edge(n1+k,n1+(k<<1));
        add_edge(n1+k,n1+(k<<1|1));
        build(k<<1,l,mid);
        build(k<<1|1,mid+1,r);
    }

    void tinit(){
        n2=n*2;
        n1=1;
        while(n1<n2) n1<<=1;
        build(1,1,n1);
    }

    vector<int> temp;
    void reinit(){
        for(auto &i:temp){
            g[i].pop_back();
        }
        temp.clear();
    }

    int ql,qr,qs;
    void paint(int k,int l,int r){ // 染色，考虑把区间染成不可取
        if (ql>r||qr<l) return;
        if (ql<=l&&r<=qr) {
            if (l==r) add_edge(qs,v[k-n1+1].second);
            else add_edge(qs,n1+k);
            temp.pb(qs);
        }
        else{
            int mid=r+l>>1;
            paint(k<<1,l,mid);
            paint(k<<1|1,mid+1,r);
        }
    }
}
