        int r=lower_bound(v.begin(),v.end(),pii(i.first+x,-1))-v.begin()-1;
        l=max(l,1);
        if (l<j){// 注意不要一不小心把自己给染了，后果严重
            ql=l,qr=j-1,qs=j;
            paint(1,1,n1);
        }
        if (r>j){
            ql=j+1,qr=r,qs=j;
            paint(1,1,n1);
        }
    }
    return solvable();
}


