using namespace std;
const int N=10010,INF=0x3f3f3f3f;
template<class T>void read(T &x){
	x=0;register char c=getchar();
	while(!isdigit(c))c=getchar();
	while( isdigit(c))x=x*10+c-48,c=getchar();
}
int n,X[N<<1],K,Lim,id[N<<1],sz[N<<2],m,Low;
vector<int>G[N<<2];
inline void add(int x,int y){G[y].push_back(x);}
inline void Add(int x,int y){add(x,y),add(y,x);}
inline void link(int x,int y){
	Add(x*2+1,y*2),Add(y*2+1,x*2);
}
inline void Link(int x,int y){
	add(x*2+1,y*2),add(y*2+1,x*2);
}
inline bool cmp(int a,int b){return X[a]<X[b];}
int pre[N<<2],sccno[N<<2],scc[N<<2],scc_cnt,low[N<<2],dfs_cnt;
stack<int>s;
void dfs(int u){
	low[u]=pre[u]=++dfs_cnt;
	sccno[u]=1;s.push(u);
	int S=G[u].size();
	For(i,0,S-1){
		int v=G[u][i];
		if(!pre[v])dfs(v),low[u]=min(low[u],low[v]);
		else if(sccno[v])low[u]=min(low[u],pre[v]);
	}
	if(pre[u]==low[u]){
		++scc_cnt;
		int w;
		do{
			w=s.top();s.pop();
			scc[w]=scc_cnt;sccno[w]=0;
		}while(w!=u);
	}
}
bool check(int dis){
	For(i,0,m)G[i].resize(sz[i]);
	For(i,0,2*n-1){
		For(j,max(i-9,0),min(i+9,2*n-1)){
			if(j==i)continue;
			if(abs(X[id[j]]-X[id[i]])>=dis)continue;
			if(abs(id[i]-id[j])==n)continue;
			Link(id[i],id[j]);
		}
	}
	dfs_cnt=0;scc_cnt=0;
	For(i,0,m)pre[i]=0,scc[i]=0;
	For(i,0,m)if(!pre[i])dfs(i);
	For(i,0,2*n-1)if(scc[i*2]==scc[i*2+1])return 0;
	return 1;
}
inline bool Check(int dis){
	int cnt=0,last=-INF;
	For(i,0,2*n-1){
		if(X[id[i]]-last>=dis)cnt++,last=X[id[i]];
		if(cnt==n)break;
	}
	return cnt==n;
}
void solveLim(){
	int L=0,R=Lim,ans=0;
	while(L<=R){
		int Mid=(L+R)>>1;
		if(Check(Mid))ans=Mid,L=Mid+1;
		else R=Mid-1;
	}
	Lim=ans;
}
int main(){
	read(n);Low=INF;
	For(i,0,n-1){
		read(X[i]),read(X[i+n]);
		link(i,i+n);
		Lim=max(Lim,max(X[i],X[i+n]));
		if(i)Low=min(Low,X[i]-X[i-1]);
	}
	m=4*n-1;
	For(i,0,2*n-1)id[i]=i;
	For(i,0,m)sz[i]=G[i].size();
	sort(id,id+2*n,cmp);
	solveLim();
	int L=Low,R=Lim,ans=0;
	while(L<=R){
		int Mid=(L+R)>>1;
		if(check(Mid))L=Mid+1,ans=Mid;
		else R=Mid-1;
	}
	printf("%d\n",ans);
	return 0;
}

#include<bits/stdc++.h>
using namespace std;

typedef pair<int, int> pii;

int N, M;
vector<pii> flag;
vector<pii> ord;
vector<int> inv;
vector<vector<int> > adj;
vector<int> F;

void build(int l, int r, int n) {
    if(l == r) {
        F[l] = n;
        return;
    }
    int m = (l + r)>>1;
    build(l, m, 2*n);
    build(m + 1, r, 2*n + 1);
    adj[2*(2*n) + 1].push_back(2*n + 1);
    adj[2*n].push_back(2*(2*n));
    adj[2*(2*n + 1) + 1].push_back(2*n + 1);
    adj[2*n].push_back(2*(2*n + 1));
}
void add(int p, int a, int b, int l, int r, int n) {
    if(b < l || r < a) return;
    if(a <= l && r <= b) {
        adj[ 2*F[p] + 1 ].push_back(2*n);
        adj[2*n + 1].push_back(2*F[p]);
        return;
    }
    int m = (l + r)>>1;
    add(p, a, b, l, m, 2*n);
    add(p, a, b, m + 1, r, 2*n + 1);
}

vector<int> tin, bck, id;
stack<int> stk;
int timer, scnt;

void dfs(int u) {
    tin[u] = timer++;
    bck[u] = tin[u];
    stk.push(u);

    for(int i = 0; i < adj[u].size(); i++) {
        int v = adj[u][i];
        if(tin[v] == -1) {
            dfs(v);
            bck[u] = min(bck[u], bck[v]);
        }
        else if(id[v] == -1) {
            bck[u] = min(bck[u], tin[v]);
        }
    }
    if(bck[u] == tin[u]) {
        while(1) {
            int t = stk.top(); stk.pop();
            id[t] = scnt;
            if(t == u) break;
        }
        scnt++;
    }
}

bool f(int d) {
    M = 2*N;
    adj.clear();
    adj.resize(8*M);
    F.resize(M);
    build(0, M - 1, 1);
    for(int i = 0; i < N; i++) {
        adj[2*F[ inv[2*i] ] + 1].push_back(2*F[ inv[2*i + 1] ]);
        adj[2*F[ inv[2*i + 1] ] + 1].push_back(2*F[ inv[2*i] ]);
        adj[2*F[ inv[2*i] ] ].push_back(2*F[ inv[2*i + 1] ] + 1);
        adj[2*F[ inv[2*i + 1] ] ].push_back(2*F[ inv[2*i] ] + 1);
    }
    for(int i = 0; i < M; i++) {
        int x = ord[i].first;
        int id = ord[i].second;

        int s = i + 1, e = M - 1;
        int p = -1;
        while(s <= e) {
            int m = (s + e)>>1;

            if(ord[m].first < x + d) {
                p = m;
                s = m + 1;
            }
            else e = m - 1;
        }
        if(p != -1) add(i, i + 1, p, 0, M - 1, 1);

        s = 0, e = i - 1;
        p = -1;
        while(s <= e) {
            int m = (s + e)>>1;

            if(ord[m].first > x - d) {
                p = m;
                e = m - 1;
            }
            else s = m + 1;
        }
        if(p != -1) add(i, p, i - 1, 0, M - 1, 1);
    }

    tin = bck = id = vector<int>(8*M, -1);
    timer = scnt = 0;
    for(int i = 0; i < 8*M; i++) if(tin[i] == -1) dfs(i);
    for(int i = 0; i < 4*M; i++) if(id[2*i] == id[2*i + 1]) return false;
    return true;
}

int main() {
    scanf("%d", &N);

    flag.resize(N);

    for(int i = 0; i < N; i++) {
        scanf("%d %d", &flag[i].first, &flag[i].second);
        ord.push_back(pii(flag[i].first, 2*i));
        ord.push_back(pii(flag[i].second, 2*i + 1));
    }

    sort(ord.begin(), ord.end());

    inv.resize(2*N);
    for(int i = 0; i < 2*N; i++) inv[ ord[i].second ] = i;

    int s = 0, e = 1e9;
    int p = -1;
    while(s <= e) {
        int m = (s + e)>>1;

        if(f(m)) {
            p = m;
            s = m + 1;
        }
        else e = m - 1;
    }
    printf("%d", p);
}

