	for(int i=0,j=0,k=-1;i<L;++i){
		for(;k<L-1&&a[k+1].first<a[i].first+m;++k,vis[a[k].second]=now[a[k].second^1]=1);
		for(;a[j].first+m<=a[i].first;vis[a[j].second]=now[a[j].second^1]=0,++j);
		G[a[i].second]=now;revG[a[i].second^1]=vis;
	}
	for(int i=0;i<L;++i)G[i][i^1]=revG[i][i^1]=G[i][i]=revG[i][i]=0,now[i]=1;
	while(!stk.empty())stk.pop();
	for(int i=0;i<L;++i)if(now[i])dfs(i);
	for(int i=0;i<L;++i)now[i]=1;
	for(;!stk.empty();){
		int x=stk.top();stk.pop();if(!now[x])continue;vis.reset();
		dfs2(x);if(((vis&(vis<<1))&odd).any())return 0;
	}
	return 1;
}


