struct Two_SAT {
	int n;
	int Head[maxn], Next[maxm], to[maxm], e;
	int S[maxn], c;
	bitset<maxn> mark;

	void Init() { Set(Head, 0); e = 0; mark.reset();}

	void add_edge (int u, int v) { to[++ e] = v; Next[e] = Head[u]; Head[u] = e; }

	void Add(int x, int xv, int y, int yv) {
		x = x << 1 | xv;
		y = y << 1 | yv;
		add_edge (x ^ 1, y);
		add_edge (y ^ 1, x);
	}

	bool Dfs(int x) {
		if (mark[x ^ 1]) return false;
		if (mark[x]) return true;
		mark[x] = true; S[++ c] = x;
		for (int i = Head[x]; i; i = Next[i])
			if (!Dfs(to[i])) return false;
		return true;
	}

	bool Solve() {
		for (int i = 2; i <= 2 * n; i += 2)
			if (!mark[i] && !mark[i ^ 1]) {
				c = 0;
				if (!Dfs(i)) {
					while (c) mark[S[c --]] = false;
					if (!Dfs(i ^ 1)) return false;
				}
			}
		return true;
	}
} T;

