bool ok(LL d) {
    S.clear();
    REP (i, N+N) {
	int j = i + 1;
	for (; j<N+N && j < i + 300; j++) {
	    if (P[j].first - P[i].first < d) {
		int x = P[i].second / 2, xb = P[i].second & 1;
		int y = P[j].second / 2, yb = P[j].second & 1;
		if (x == y) continue;

		S.IMP(xb ? S.inv(x) : x, yb ? y : S.inv(y));
		S.IMP(yb ? S.inv(y) : y, xb ? x : S.inv(x));
	    } else break;
	}
	for (; j<N+N && j < i + 600; j+=2) {
	    if (P[j].first - P[i].first < d) {
		int x = P[i].second / 2, xb = P[i].second & 1;
		int y = P[j].second / 2, yb = P[j].second & 1;
		if (x == y) continue;

		S.IMP(xb ? S.inv(x) : x, yb ? y : S.inv(y));
		S.IMP(yb ? S.inv(y) : y, xb ? x : S.inv(x));
	    } else break;
	}
    }

    return S.SAT();
}

