void DFS_SCC(int R, auto & G, auto & comp, auto & st, auto & in_st, auto & idx, auto & min_idx, int & nxt_idx) {
	in_st[R] = true;
	st.push_back(R);
	idx[R] = min_idx[R] = nxt_idx++;
	ALL_THE(G[R], it) {
		if(idx[*it] == -1) {
			DFS_SCC(*it, G, comp, st, in_st, idx, min_idx, nxt_idx);
			min_idx[R] = min(min_idx[R], min_idx[*it]);
		}
		else if(in_st[*it])
			min_idx[R] = min(min_idx[R], min_idx[*it]);
	}
	if(idx[R] == min_idx[R]) {
		vector<int> nxt_comp;
		while(true) {
			int x = st.back();
			st.pop_back();
			in_st[x] = false;
			nxt_comp.push_back(x);
			if(x == R) break;
		}
		comp.push_back(nxt_comp);
	}
}

