      int i3=upper_bound(px, px+n, P(py[i].first-d, 1e5))-px;
      int i4=lower_bound(px, px+n, P(py[i].first+d, -1))-px;
      segtree2(3, 0, indy[i], i3, i4, 0, 0, n0);
    }
    scc();
    bool nuee=0;
    for(int i=0; i<n; i++){
      if(cmp[i]==cmp[i+n0]){
        nuee=1;
        break;
      }
    }
    if(nuee) d2=d-1;
    else d1=d;
  }
