void tpsort(int v, int prev)
{
	used[v] = true;
	for(int i = 0; i < G[v].size(); i++){
		if(used[G[v][i]]) continue;
		tpsort(G[v][i], v);
	}
	topo.push_back(v);
}

void dfs(int v, int prev, int id)
{
	used[v] = true;
	scc[v] = id;
	for(int i = 0; i < revG[v].size(); i++){
		if(used[revG[v][i]]) continue;
		dfs(revG[v][i], v, id);
	}
}

void query(int v, int a, int b, int k, int l, int r)
{
	if(b < l || r < a) return;
	if(a <= l && r <= b){
		G[v].push_back(k);
		return;
	}
	if(k*2 < V) query(v, a, b, k*2, l, (l+r)/2);
	if(k*2+1 < V) query(v, a, b, k*2+1, (l+r)/2+1, r);
}

void range(int v, int l, int r)
{
	if(l > r) return;
	 query(v, l, r, 1, 0, (1<<14)-1);
}

