	for(int i = 0; i < 2*N; i++){
		int v = pos[vec[i].second.first][1-vec[i].second.second];
		while(r < 2*N && vec[r].first <= vec[i].first+(d-1)) r++;
		range(Num + v, i+1, r-1);
	}

	for(int i = 1; i < V; i++) revG[i].clear();
	for(int i = 1; i < V; i++){
		for(int j = 0; j < G[i].size(); j++){
			revG[G[i][j]].push_back(i);
		}
	}

	for(int i = 1; i < V; i++) used[i] = false;
	topo.clear();
	for(int i = 1; i < V; i++) if(!used[i]) tpsort(i, -1);
	reverse(topo.begin(), topo.end());

