			low[x] = min(dfn[v], low[x]);
		}
	}
	if(low[x] == dfn[x]) {
		++ belnum;
		int tmp = stk[tp];
		while(tmp != x) {
			bel[tmp] = belnum;
			instk[tmp] = 0;
			tmp = stk[-- tp];
		} 
		bel[stk[tp]] = belnum;
		instk[stk[tp --]] = 0;
	}
