	build(ls,l,mid);build(rs,mid+1,r);
	adde(T(ls),T(x));adde(F(x),F(ls));
	adde(T(rs),T(x));adde(F(x),F(rs));
}
int query(int x,int l,int r,int pos){
	if(l==r)return x;
	if(pos<=mid)return query(ls,l,mid,pos);
	return query(rs,mid+1,r,pos);
}
void addedge(int x,int l,int r,int ll,int rr,int y){
	if(ll>rr)return;
	if(l==ll&&r==rr){
		adde(T(x),F(y));adde(T(y),F(x));
		return;
	}
	if(rr<=mid)addedge(ls,l,mid,ll,rr,y);
	else if(ll>mid)addedge(rs,mid+1,r,ll,rr,y);
	else addedge(ls,l,mid,ll,mid,y),addedge(rs,mid+1,r,mid+1,rr,y);
}
