	for(int i=0;i<rG[v].size();i++){
		if(!used[rG[v][i]])rdfs(rG[v][i],k);
	}
}

int scc(){
	memset(used,false,sizeof(used));
	vs.clear();
	for(int v=0;v<V;v++){
		if(!used[v])dfs(v);
	}
	memset(used,false,sizeof(used));
	int k=0;
	for(int i=vs.size()-1;i>=0;i--){
		if(!used[vs[i]])rdfs(vs[i],k++);
	}
	return k;
}
int n_=1;

void update(int a,int b,int v,int k=0,int l=0,int r=n_){
	if(r<=a || b<=l)return;
	if(a<=l && r<=b){
		add_edge(n_*2-1+v,k);
		return;
	}
	update(a,b,v,k*2+1,l,(l+r)/2);
	update(a,b,v,k*2+2,(l+r)/2,r);
}

bool C(ll d){
	n_=1;
	while(n_<n*2)n_*=2;
	V=n_*3;
	for(int i=0;i<V;i++){
		G[i].clear();
		rG[i].clear();
	}
	for(int i=0;i+1<n_;i++){
		add_edge(i,i*2+1);
		add_edge(i,i*2+2);
	}
	for(int i=0;i<n*2;i++){
		if(fs[i]){
			add_edge(n_-1+sc[p[i].second],n_*2-1+i);
			add_edge(n_-1+i,n_*2-1+sc[p[i].second]);
		}
		int l=lower_bound(p,p+2*n,P(p[i].first-d+1,0))-p;
		update(l,i,i);
		int r=lower_bound(p,p+2*n,P(p[i].first+d,0))-p;
		update(i+1,r,i);
	}
	scc();
	for(int i=0;i<n;i++){
		if(cmp[n_-1+i]==cmp[n_*2-1+i])return false;
	}
	return true;
}

