class SCC {
public:
	static const int MV = 21000;
	int NV,GR[MV],rev[MV];
private:
	vector<int> E[MV], RE[MV], NUM; int vis[MV];
public:
	void init(int NV) { this->NV=NV; for(int i=0;i<MV;i++) { E[i].clear(); RE[i].clear();}}
	void add_edge(int x,int y) { E[x].push_back(y); RE[y].push_back(x); }
	void dfs(int cu) { vis[cu]=1; for(int i=0;i<E[cu].size();i++) if(!vis[E[cu][i]]) dfs(E[cu][i]); NUM.push_back(cu); }
	void revdfs(int cu, int ind) { int i; vis[cu]=1; GR[cu]=ind;  rev[cu]=ind;
		FOR(i,RE[cu].size()) if(!vis[RE[cu][i]]) revdfs(RE[cu][i],ind);}
	void scc() {
		int c=0; NUM.clear();
		ZERO(vis); for(int i=0;i<NV;i++) if(!vis[i]) dfs(i);
		ZERO(vis); for(int i=NUM.size()-1;i>=0;i--) if(!vis[NUM[i]]){
			revdfs(NUM[i],c); c++;
		}
	}
};

class TwoSat {
	int NV;
	SCC sc;
public:
	vector<int> val;
	void init(int NV) { this->NV=NV*2; sc.init(NV*2); val.resize(NV);}
	void add_edge(int x,int y) { // k+0:normal k+NV:inverse
		sc.add_edge((x+NV/2)%NV,y);
		sc.add_edge((y+NV/2)%NV,x);
	}
	bool sat() { // empty:false 
		sc.scc();
		for(int i=0;i<NV/2;i++) if(sc.GR[i]==sc.GR[i+NV/2]) return false;
		for(int i=0;i<NV/2;i++) val[i]=sc.GR[i]>sc.GR[i+NV/2];
		return true;
	}
};

int ok(int v) {
	int i,j;
	if(v>mi) return 0;
	TwoSat ts;
	ts.init(N);

	int y,x;
	FOR(y,N) FOR(x,y) {
		if(abs(X[y]-X[x])<v) ts.add_edge(y+N,x+N);
		if(abs(X[y]-Y[x])<v) ts.add_edge(y+N,x);
		if(abs(Y[y]-X[x])<v) ts.add_edge(y,x+N);
		if(abs(Y[y]-Y[x])<v) ts.add_edge(y,x);
	}
	return ts.sat();


}

void solve() {
	int i,j,k,l,r,x,y; string s;

	cin>>N;
	FOR(i,N) {
		cin>>X[i]>>Y[i];
		if(X[i]>Y[i]) swap(X[i],Y[i]);
	}

	mi=1<<30;
	FOR(y,N) FOR(x,y) {
		int ma=max({abs(X[y]-X[x]),abs(X[y]-Y[x]),abs(Y[y]-X[x]),abs(Y[y]-Y[x])});
		mi=min(mi,ma);
	}

	int ret=0;
	for(i=29;i>=0;i--) if(ok(ret+(1<<i))) ret+=1<<i;
	cout<<ret<<endl;
}


