int id[2][N], siz;
int tot;

void init(int tp, int n, const vector <pair <int, int> > &v) {
	memset(id[tp], -1, sizeof(id[tp]));
	siz = 1;
	while (siz <= n) siz <<= 1;
	for (int i = 1; i < siz; ++ i)
		id[tp][i] = tot ++;
	for (int i = 0; i < n; ++ i)
		id[tp][i + siz] = v[i].second;
	for (int i = 2; i < (siz << 1); ++ i) {
		if (!~id[tp][i]) continue;
		if (!tp) g[id[tp][i >> 1]].push_back(id[tp][i]);
		else g[id[tp][i]].push_back(id[tp][i >> 1]);
	}
}

void Add(int tp, int i, int a, int b, int l, int r, int v) {
	if (l <= a && b <= r) {
		if (!tp) g[v].push_back(id[tp][i]);
		else g[id[tp][i]].push_back(v);
		return ;
	}
	if (r <= a || b <= l) return ;
	int m = (a + b) >> 1;
	Add(tp, i << 1, a, m, l, r, v);
	Add(tp, i << 1 | 1, m, b, l, r, v);
}

int dfn[N], cnt;
int scc[N], cc;
vector <int> rg[N];
bool vis[N];

void dfs(int u) {
	vis[u] = 1;
	for (int i = 0; i < g[u].size(); ++ i) {
		int v = g[u][i];
		if (!vis[v]) dfs(v);
	}
	dfn[-- cnt] = u;
}

void rdfs(int u) {
	scc[u] = cc;
	for (int i = 0; i < rg[u].size(); ++ i) {
		int v = rg[u][i];
		if (!~scc[v]) rdfs(v);
	}
}

void Scc() {
	for (int i = 0; i < tot; ++ i) rg[i].clear();
	for (int i = 0; i < tot; ++ i)
		for (int j = 0; j < g[i].size(); ++ j)
			rg[g[i][j]].push_back(i);
	memset(vis, 0, sizeof(vis));
	cnt = tot;
	for (int i = 0; i < tot; ++ i)
		if (!vis[i]) dfs(i);
	cc = 0;
	memset(scc, -1, sizeof(scc));
	for (int i = 0; i < tot; ++ i) {
		int u = dfn[i];
		if (!~scc[u]) {
			rdfs(u);
			++ cc;
		}
	}
}

bool check(int d) {
	tot = n * 2;
	vector <pair <int, int> > v;
	for (int i = 0; i < n; ++ i) {
		v.push_back(make_pair(x[i][0], i));
		v.push_back(make_pair(x[i][1], i + n));
	}
	sort(v.begin(), v.end());
	init(0, n * 2, v); init(1, n * 2, v);
	for (int i = 0; i < n; ++ i) {
		int l = lower_bound(v.begin(), v.end(), make_pair(x[i][0] - d + 1, -inf)) - v.begin();
		int r = upper_bound(v.begin(), v.end(), make_pair(x[i][0] + d - 1, inf)) - v.begin();
		int m = lower_bound(v.begin(), v.end(), make_pair(x[i][0], i)) - v.begin();
		Add(0, 1, 0, siz, l, m, i + n); Add(0, 1, 0, siz, m + 1, r, i + n);
	}
	for (int i = 0; i < n; ++ i) {
		int l = lower_bound(v.begin(), v.end(), make_pair(x[i][1] - d + 1, -inf)) - v.begin();
		int r = upper_bound(v.begin(), v.end(), make_pair(x[i][1] + d - 1, inf)) - v.begin();
		int m = lower_bound(v.begin(), v.end(), make_pair(x[i][1], i + n)) - v.begin();
		Add(0, 1, 0, siz, l, m, i); Add(0, 1, 0, siz, m + 1, r, i);
	}
	Scc();
	for (int i = 0; i < tot; ++ i)
		g[i].clear();
	for (int i = 0; i < n; ++ i)
		if (scc[i] == scc[i + n]) return 0;
	return 1;
}

int main() {
	ios :: sync_with_stdio(0);
	cin.tie(0); cout.tie(0);
	cin >> n;
	for (int i = 0; i < n; ++ i)
		cin >> x[i][0] >> x[i][1];
	int lb = 0, rb = inf;
	while (lb < rb) {
		int md = (lb + rb + 1) >> 1;
		if (check(md)) lb = md;
		else rb = md - 1;
	}
	cout << lb << endl;
	return 0;
}

