void SelectEdge(int d) {
  rep(i, N*2) {
    es[i].clear();
    res[i].clear();
  }

  if (toomany) {
    rep(i, d) {
      for (auto &p : evs[i]) {
        int u, v;
        tie(u, v) = p;
        es[u].eb(v);
        res[v].eb(u);
      }
    }
  } else {
    rep(i, N) {
      reps(j, i+1, N) {
        rep(k, 2) {
          rep(l, 2) {
            if (abs(X[j][l]-X[i][k]) < d) {
              es[i*2+k].eb(j*2+1-l);
              res[j*2+1-l].eb(i*2+k);
              es[j*2+l].eb(i*2+1-k);
              res[i*2+1-k].eb(j*2+l);
            }
          }
        }
      }
    }
  }
}

bool used[21451];
int belong[21451];
vector<int> vis;

void Dfs(int v) {
  used[v] = true;
  for (int u : es[v]) {
    if (used[u]) continue;
    Dfs(u);
  }
  vis.eb(v);
}

void RDfs(int v, int grp) {
  used[v] = true;
  belong[v] = grp;
  for (int u : res[v]) {
    if (used[u]) continue;
    RDfs(u, grp);
  }
}

bool DoScc() {
  vis.clear();
  fill(used, used+2*N, false);
  rep(v, 2*N) {
    if (!used[v]) Dfs(v);
  }
  reverse(all(vis));
  fill(used, used+2*N, false);
  int grp = 0;
  for (int v : vis) {
    if (!used[v]) RDfs(v, grp++);
  }

  rep(i, N) {
    if (belong[i*2] == belong[i*2+1]) return false;
  }
  return true;
}

bool check(int x) {
  SelectEdge(x);
  return DoScc();
}

int ans;
int num[1145141];
int memo[1145141];

bool check2(int x, int md) {
  int low = -1;
  int high = md+1;
  while (high - low > 1) {
    int mid = (low+high)/2;
    if (num[mid] <= x) low = mid;
    else high = mid;
  }

  ans = low+1;
  if (memo[ans] >= 0) return memo[ans];

  SelectEdge(ans);
  return memo[ans] = DoScc();
}

int main() {
  scanf("%d", &N);
  rep(i, N) {
    rep(j, 2) {
      scanf("%d", &X[i][j]);
    }
  }

  if (N >= 1000) toomany = true;

  if (toomany) {
    int lim = MOD/(N-1) + 10;
    assert(lim <= 1145041);

    int md = 0;
    rep(i, N) {
      reps(j, i+1, N) {
        rep(k, 2) {
          rep(l, 2) {
            int d = abs(X[i][k] - X[j][l]);
            if (d > lim) continue;
            evs[d].eb(pii(2*i+k, 2*j+1-l));
            evs[d].eb(pii(2*j+l, 2*i+1-k));
            MX(md, d);
          }
        }
      }
    }

    num[0] = evs[0].size();
    reps(d, 1, md+1) {
      num[d] = num[d-1] + evs[d].size();
    }

    fill(memo, memo+md+1, -1);
    int low = -1;
    int high = num[md]+1;
    while (high - low > 1) {
      int mid = (low+high)/2;
      if (check2(mid, md)) low = mid;
      else high = mid;
    }
    check2(low, md);
    printf("%d\n", ans);
  } else {
    int low = -1;
    int high = MOD;
    while (high - low > 1) {
      int mid = (low+high)/2;
      if (check(mid)) low = mid;
      else high = mid;
    }
    printf("%d\n", low);
  }
}

