using namespace std;
typedef pair<int, int> pii;

struct SCC {
	static const int MAXN = 131100;

	vector<int> G[MAXN];
	int A[MAXN], An;
	bitset<MAXN> chk;

	vector<pii> EV;
	vector<int> V;

	void dfs(int i) {
		chk[i] = true;
		for(int v : G[i]) if(!chk[v]) dfs(v);
		V.eb(i);
	}
	void dfslabel(int i) {
		chk[i] = true;
		for(int v : G[i]) if(!chk[v]) {
			A[v] = A[i];
			dfslabel(v);
		}
	}

	void init() {
		EV.clear();
		An = 0;
	}
	void add(int a, int b) { EV.eb(a, b); }
	void run() {
		for(int i = 0; i < MAXN; i++) G[i].clear();
		for(auto &e : EV) G[e.first].eb(e.second);
		chk.reset();
		for(int i = 0; i < MAXN; i++) if(!chk[i]) dfs(i);
		for(int i = 0; i < MAXN; i++) G[i].clear();
		chk.reset();
		for(auto &e : EV) G[e.second].eb(e.first);
		reverse(V.begin(), V.end());
		for(int v : V) if(!chk[v]) {
			A[v] = ++An;
			dfslabel(v);
		}
		V.clear();
	}
};

struct SAT {
	SCC scc;

	void init() { scc.init(); }
	void add(int a, bool av, int b, bool bv) {
		scc.add(a<<1|int(!av), b<<1|int(bv));
		scc.add(b<<1|int(!bv), a<<1|int(av));
	}
	bool solve() {
		scc.run();
		for(int i = 0; i < SCC::MAXN; i += 2)
			if(scc.A[i] == scc.A[i|1])
				return false;
		return true;
	}
} sat;

const int MAXN = 10055;
const int MX = 32768;

int O[MAXN*2], RO[MAXN*2];
int A[MAXN], B[MAXN];

int N;

int f(int i) { return (i&1) ? B[i>>1] : A[i>>1]; }

void make(int i, int s, int e) {
	if(s < 0) s = 0; if((N<<1) <= e) e = (N<<1)-1;
	for(i += MX, s += MX, e += MX; s <= e; s >>= 1, e >>= 1) {
		if(s&1) sat.add(i, true, s++, true);
		if(~e&1) sat.add(i, true, e--, true);
	}
}

bool isp(int L) {
	if(!L) return true;
	sat.init();

	for(int i = 1; i < MX; i++) {
		sat.add(i, false, i<<1, true);
		sat.add(i, false, i<<1|1, true);
	}
	for(int i = 0; i < N; i++)
		sat.add(RO[i<<1]+MX, false, RO[i<<1|1]+MX, false);
	for(int i = N<<1, x, oi, s, e; i--;) {
		x = (i&1) ? B[i>>1] : A[i>>1];
		oi = RO[i];
		if(oi && x-L < f(O[oi-1])) {
			s = 0; e = oi-1; for(int m, y = x-L; s < e;) {
				m = (s+e) >> 1;
				if(y < f(O[m])) e = m;
				else s = m+1;
			}
			make(oi, s, oi-1);
		}
		if(oi+1 < (N<<1) && f(O[oi+1]) < x+L) {
			s = oi+1; e = (N<<1)-1; for(int m, y = x+L; s < e;) {
				m = (s+e+1) >> 1;
				if(f(O[m]) < y) s = m;
				else e = m-1;
			}
			make(oi, oi+1, s);
		}
	}

	return sat.solve();
}

int getAns() {
	int s = 0, e = INF; for(int m; s < e;) {
		m = (s+e+1) >> 1;
		if(isp(m)) s = m;
		else e = m-1;
	}
	return s;
}

int main() {
	ios::sync_with_stdio(false);

	cin >> N;
	for(int i = 0; i < N; i++) cin >> A[i] >> B[i];
	iota(O, O+(N<<1), 0); sort(O, O+(N<<1), [&](int a, int b) {
			return f(a) < f(b);
			});
	for(int i = N<<1; i--;) RO[O[i]] = i;

	cout << getAns() << endl;
	return 0;
}

