struct TWO_SAT{
    TWO_SAT() {}
    vector<vector<int>> e;
    vector<pii> edges;
    int cnt, k;
    vector<int> num, low, lab, st;
    TWO_SAT(int n) {
        e.resize(n * 2);
        num.resize(e.size());
        low.resize(e.size());
        lab.resize(e.size());
        cnt = k = 0;
    }
    void del(int rem) {
        fill(num.begin(), num.end(), 0);
        fill(low.begin(), low.end(), 0);
        fill(lab.begin(), lab.end(), 0);
        int x, y; st.clear(); cnt = k = 0;
        while(edges.size() > rem) {
            tie(x, y) = edges.back(); edges.pop_back();
            e[x ^ 1].pop_back(); e[y ^ 1].pop_back();
        }
    }
    void add(int x, int tx, int y, int ty){
        x = x << 1 ^ tx;
        y = y << 1 ^ ty;
        edges.pb(x, y);
        e[x ^ 1].pb(y);
        e[y ^ 1].pb(x);
    }
    void dfs(int x){
        num[x] = low[x] = ++cnt;
        st.pb(x);
        for (int y : e[x]) if (!lab[y]){
            if (num[y]) low[x] = min(low[x], num[y]);
            else {
                dfs(y);
                low[x] = min(low[x], low[y]);
            }
        }
        if (num[x] == low[x]){
            ++k;
            while(1){
                int y = st.back();
                st.pop_back();
                lab[y] = k;
                if (x == y) break;
            }
        }
    }
    vector<int> solve(){
        for (int x = 0; x < e.size(); ++x) if (!num[x]) dfs(x);
        int n = e.size() >> 1;
        vector<int> ans(n);
        for (int x = 0; x < n; ++x){
            if (lab[x << 1 ^ false] == lab[x << 1 ^ true]) return vector<int>(0);
            ans[x] = lab[x << 1 ^ false] > lab[x << 1 ^ true];
        }
        return ans;
    }
} G;

