				dsuA.lab[z] = dsuA.f(z + 1);
				z = dsuA.f(z);
			} else {
				dsuA.lab[z] = dsuA.f(z + 1);
				dfsKosa(a[z].id * 2 + 1, typ);
				z = dsuA.f(z);
