				dsuB.lab[z] = dsuB.f(z + 1);
				dfsKosa(id * 2, typ);
				z = dsuB.f(z);
			}
		}
	} else {
		from = RtoL[u / 2].first, to = RtoL[u / 2].second;
		int z = dsuA.f(from);
