				dsuA.lab[z] = dsuA.f(z + 1);
				dfsKosa(a[z].id * 2 + 1, typ);
				z = dsuA.f(z);
			}
		}

		from = RtoR[u / 2].first, to = RtoR[u / 2].second;
	    z = dsuB.f(from);
