int tr[maxn*8],tot;
void build(int l,int r,int x){
    if(l==r){
        tr[x]=nd[l].pos;
        return;
    }
    tr[x]=++tot;
    build(l,mid,ls);
    build(mid+1,r,rs);
    add(tr[x],tr[ls]);
    add(tr[x],tr[rs]);
}
void Add(int l,int r,int x,int L,int R,int u){
    if(L<=l&&r<=R){
        add(u,x);
        return;
    }
    if(L<=mid)
        Add(l,mid,ls,L,R,u);
    if(R>mid)
        Add(mid+1,r,rs,L,R,u);
}

int dfn[maxn*8],low[maxn*8],sta[maxn*8],col[maxn*8];
int num,dfs,top;
bool vis[maxn*8];
void tarjan(int x){
    vis[x]=1;
    sta[++top]=x;
    dfn[x]=low[x]=++dfs;
    for(int i=head[x];i;i=ed[i].next){
        int to=ed[i].to;
        if(!dfn[to]){
            tarjan(to);
            low[x]=min(low[x],low[to]);
        }
        else if(vis[to])
            low[x]=min(low[x],dfn[to]);
    }
    if(low[x]==dfn[x]){
        vis[x]=0;
        col[x]=++num;
        while(sta[top]!=x){
            col[sta[top]]=num;
            vis[sta[top--]]=0;
        }
        top--;
    }
}

int n;
int val[maxn][2];
bool check(int x){
    build(1,2*n,1);
    for(int i=1;i<=n;i++){
        for(int j=0;j<=1;j++){
            int l=lower_bound(nd+1,nd+1+2*n,node(val[i][j]-x+1,0),cmp)-nd;
            int r=upper_bound(nd+1,nd+1+n*2,node(val[i][j]+x-1,2*n+1),cmp)-nd-1;
            int m=lower_bound(nd+1,nd+1+n*2,node(val[i][j^1],i+(j^1)*n),cmp)-nd;
            if(l<=r&&m<l||m>r)
                Add(1,2*n,1,l,r,i+j*n);
            else{
                if(l<m)
                    Add(1,2*n,1,l,m-1,i+j*n);
                if(r>m)
                    Add(1,2*n,1,m+1,r,i+j*n);
            }
        }
    }
    for(int i=1;i<=2*n;i++){
        if(!dfn[i])
            tarjan(i);
    }
    for(int i=1;i<=n;i++)
        if(col[i]==col[i+n])
            return 0;
    return 1;
}
