inline void addedge(int u,int a,int v,int b)
{
	u=u<<1|a,v=v<<1|b;
	e[L].to=v,e[L].nx=first[u],first[u]=L++;
	u^=1,v^=1;
	e[L].to=u,e[L].nx=first[v],first[v]=L++;
}


int st[131073],top;
int b[131073],timer;
bool dfs(int u)
{
	if(b[u^1]==timer)
		return false;

	b[u]=timer;
	st[top++]=u;

	for(int j=first[u];j;j=e[j].nx)
		if(!(b[e[j].to]==timer||dfs(e[j].to)))
			return false;
	return true;
}


bool check(int u)
{
	top=0;
	if(dfs(u<<1|1))return true;
	while(top)b[st[--top]]=0;
	return dfs(u<<1);
}


#define x first
