bool vis[MAXN * 2];
vector<int> topo;

vector<int> edg[MAXN * 2], rev[MAXN * 2];

void dfs1 (int nd) {
    vis[nd] = true;
    for (auto v : edg[nd]) {
        if (!vis[v]) {
            dfs1(v);
        }
    }
    topo.eb(nd);
}

void dfs2 (int nd) {
    cc[nd] = ccnt;
    vis[nd] = false;
    for (auto v : rev[nd]) {
        if (vis[v]) {
            dfs2(v);
        }
    }
}

void add_edge (int f, int t) {
    edg[f].eb(t);
    rev[t].eb(f);
}

bool solve (int d) {
    REP (i, n*2) {
        edg[i].clear();
        rev[i].clear();
    }

    REP (i, n) {
        REP (j, i) {
            REP (s1, 2) {
                REP (s2, 2) {
                    if (abs(p[i][s1] - p[j][s2]) < d) {
                        add_edge(i<<1|s1, j<<1|(s2^1));
                        add_edge(j<<1|s2, i<<1|(s1^1));
                    }
                }
            }
        }
    }

    MEM(vis, 0);
    topo.clear();

    REP (i, n*2) {
        if (!vis[i]) {
            dfs1(i);
        }
    }

    for (int i=SZ(topo)-1; i>=0; i--) {
        if (vis[topo[i]]) {
            dfs2(topo[i]);
            ccnt++;
        }
    }

    REP (i, n) {
        if (cc[i<<1] == cc[i<<1|1]) {
            return false;
        }
    }

    return true;
}
