inline void build(int p,int l,int r){
	if(l==r){
		tr[p]=lsh[l].s;
		return;
	}
	tr[p]=++tot;
	int mid=l+r>>1;
	build(p<<1,l,mid),build(p<<1|1,mid+1,r);
	add(tr[p],tr[p<<1]),add(tr[p],tr[p<<1|1]);
}
inline void add(int p,int l,int r,int x,int y,int v){
	if(x>y)return;
	if(l>=x&&r<=y){add(v,tr[p]);return;}
	int mid=l+r>>1;
	if(x<=mid)add(p<<1,l,mid,x,y,v);
	if(y>mid)add(p<<1|1,mid+1,r,x,y,v);
}
inline void tj(int x){
	stk.push(x);
	low[x]=dfn[x]=++tim;
	for(int i=head[x];i;i=e[i].next)
		if(!dfn[e[i].to]){
			tj(e[i].to);
			low[x]=min(low[x],low[e[i].to]);
		}
		else if(!scc[e[i].to])low[x]=min(low[x],dfn[e[i].to]);
	if(dfn[x]==low[x]){
		int p;++cnt;
		do{
			scc[p=stk.top()]=cnt;
			stk.pop();
		}while(p^x);
	}
}
inline bool check(int x){
	cnte=tim=cnt=0;
	memset(head,0,sizeof(head));build(1,1,tot=2*n);
	for(int i=1;i<=n;++i)
		for(int k=0;k<2;++k){
			int l=lower_bound(lsh+1,lsh+1+2*n,pii(a[k][i]-x+1,0))-lsh,r=upper_bound(lsh+1,lsh+1+2*n,pii(a[k][i]+x-1,2*n+1))-lsh-1,m=lower_bound(lsh+1,lsh+1+2*n,pii(a[k][i],(k^1)*n+i))-lsh;
			add(1,1,2*n,l,m-1,k*n+i);
			add(1,1,2*n,m+1,r,k*n+i);
		}
	while(!stk.empty())stk.pop();
	memset(dfn,0,sizeof(dfn)),memset(low,0,sizeof(low)),memset(scc,0,sizeof(scc));
	for(int i=1;i<=tot;++i)if(!dfn[i])tj(i);
	for(int i=1;i<=n;++i)if(scc[i]==scc[i+n])return 0;
	return 1;
}
