struct DGraph{
    int n, m;
    vector<vector<int>> conn;
    vpii edges;
    DGraph(){
        m = -1;
    }
    DGraph(int nsize):DGraph(){
        n = nsize;
        conn.resize(n + 1);
    }
    DGraph(int nsize, int _m):DGraph(nsize){
        m = _m;
    }
    void add_edge(int u, int v){
        conn[u].push_back(v);
        edges.pb({u, v});
    }
    void _topsort_dfs(int pos, vector<int>& result, vector<bool>& explr, vector<vector<int>>& revconn){
        if(explr[pos])
            return;
        explr[pos] = true;
        for(auto next : revconn[pos])
            _topsort_dfs(next, result, explr, revconn);
        result.push_back(pos);
    }
    vector<int> topsort(){
        vector<vector<int>> revconn(n + 1);
        for(int u = 0; u <= n; u++)
            for(auto v : conn[u])
                revconn[v].push_back(u);
        vector<int> result;
        vector<bool> explr(n + 1, false);
        for(int i = 0; i <= n; i++)
            _topsort_dfs(i, result, explr, revconn);
        reverse(result.begin(), result.end());
        return result;
    }
    void dfs(int pos, vector<int>& result, vector<bool>& explr){
        if(explr[pos])
            return;
        explr[pos] = true;
        for(auto next : conn[pos])
            dfs(next, result, explr);
        result.push_back(pos);
    }
    vector<vector<int>> scc(){
        vector<int> order = topsort();
        reverse(order.begin(), order.end());
        vector<bool> explr(n + 1, false);
        vector<vector<int>> results;
        for(auto it = order.rbegin(); it != order.rend(); ++it){
            vector<int> component;
            _topsort_dfs(*it, component, explr, conn);
            sort(component.begin(), component.end());
            if(!component.empty())
                results.push_back(component);
        }
        sort(results.begin(), results.end());
        return results;
    }
};
istream& operator>>(istream& stream, DGraph& g){
    if(g.m == -1){
        stream >> g.n >> g.m;
        g = DGraph(g.n, g.m);
    }
    for(int i = 0; i < g.m; ++i){
        int u, v;
        stream >> u >> v;
        g.add_edge(u, v);
    }
    return stream;
}
ostream& operator<<(ostream& stream, const DGraph &g){
    stream << g.n << ' ' << g.m << '\n';
    for(auto cur : g.edges)
        stream << cur.first << " " << cur.second << '\n';
    return stream;
}
