#define inf (1e9 + 7)
#define mem(a, b) memset(a, b, sizeof(a))
using namespace std;

int mxsum[40105], misum[40105], n, mx, mi;

struct node
{
    int a, b;
}nd[10005];

bool cmp(const struct node & a, const struct node & b)
{
    return a.a < b.a;
}

void build(int l, int r, int nn)
{
    mxsum[nn] = -inf;
    misum[nn] = inf;
    if(l == r)
    {
        mxsum[nn] = nd[l].b;
        misum[nn] = nd[l].b;
        return;
    }
    int mid = (l + r) / 2;
    build(l, mid, nn * 2);
    build(mid + 1, r, nn * 2 + 1);
    mxsum[nn] = max(mxsum[nn * 2], mxsum[nn * 2 + 1]);
    misum[nn] = min(misum[nn * 2], misum[nn * 2 + 1]);
}

void get(int l, int r, int nn, int ll, int rr)
{
    if(l >= ll&&r <= rr)
    {
        mi = min(mi, misum[nn]);
        mx = max(mx, mxsum[nn]);
        return;
    }
    if(l > rr||r < ll)
        return;
    int mid = (l + r) / 2;
    get(l, mid, nn * 2, ll, rr);
    get(mid + 1, r, nn * 2 + 1, ll, rr);
}

int getpos(int l, int v)
{
    int r = n, res = -1;
    while(l <= r)
    {
        int mid = (l + r) / 2;
        if(nd[mid].a < v)
            l = mid + 1, res = max(res, mid);
        else
            r = mid - 1;
    }
    return res;
}

bool jg(int a)
{
    for(int i = 1;i <= n;i++)
    {
        int pos = getpos(i + 1, nd[i].a + a);
        if(pos == -1)
            continue;
        mx = -inf;
        mi = inf;
        get(1, n, 1, i + 1, pos);
        if(abs(mx - nd[i].a) < a||abs(mi - nd[i].a) < a)
            return false;
    }
    return true;
}

int main()
{
    scanf("%d", &n);
    for(int i = 1;i <= n;i++)
        scanf("%d%d", &nd[i].a, &nd[i].b);
    sort(nd + 1, nd + 1 + n, cmp);
    build(1, n, 1);
    int l = 0, r = 1e9, ans = 0;
    while(l <= r)
    {
        int mid = (l + r) / 2;
        if(jg(mid))
            l = mid + 1, ans = max(ans, mid);
        else
            r = mid - 1;
    }
    printf("%d\n", ans);
    return 0;
}

