typedef vector<VI> Adj;
struct SCC {
    vector<int> scc;
    int cnt;
    SCC(const Adj &G) {
	int n = G.size();
	scc.assign(n, 0);
	vector<int> ord; ord.reserve(n);
	REP (k, n) if (scc[k] == 0) {
	    stack<int> S;
	    S.push(k);
	    while (!S.empty()) {
		int v = S.top(); S.pop();
		if (v >= 0) {
		    if (scc[v]) continue;
		    scc[v] = -1;
		    S.push(v-n);
		    EACH (e, G[v]) S.push(*e);
		} else {
		    ord.push_back(v+n);
		}
	    }
	}
	Adj R(n);
	REP (v, n) EACH (e, G[v]) R[*e].push_back(v);
	cnt = 0;
	for (int i=n; i--; ) if (scc[ord[i]] == -1) {
	    stack<int> S;
	    S.push(ord[i]); scc[ord[i]] = cnt;
	    while (!S.empty()) {
		int v = S.top(); S.pop();
		scc[ord[i]] = cnt;
		EACH (e, R[v]) if (scc[*e] == -1) {
		    S.push(*e); scc[*e] = cnt;
		}
	    }
	    cnt++;
	}
    }
    Adj shrink(const Adj &G) { // may have loop edges, doesn't have parallel edges
	Adj S(cnt);
	REP (v, G.size()) EACH (e, G[v]) S[scc[v]].push_back(scc[*e]);
	REP (i, cnt) {
	    sort(S[i].begin(), S[i].end());
	    S[i].erase(unique(S[i].begin(), S[i].end()), S[i].end());
	}
	return S;
    }
};
struct TwoSAT {
    int N, n;
    Adj G;
    vector<int>truth;
    bool sat;
    TwoSAT() {}
    TwoSAT(int n):n(n) { // n = number of variables
	N = n*2;
	G = Adj(N);
    }
    void add(int p, int q) { // p -> q
	G[p].push_back(q);
    }
    int inv(int p) { // id of ~p
	return (p+n)%N;
    }
    void IMP(int p, int q) { // p -> q
	add(p, q);
	add(inv(q), inv(p));
    }
    void T(int p) { // p is true : ~p -> p
	add(inv(p), p);
    }
    void OR(int p, int q) {
	IMP(inv(p), q);
    }
    void XOR(int p, int q) {
	IMP(p, inv(q));
	IMP(inv(p), q);
    }
    void EQ(int p, int q) {
	IMP(p, q);
	IMP(inv(p), inv(q));
    }
    bool SAT() {
	SCC scc(G);
	sat = true; truth = vector<int>(n, 0);
	for (int i=0; i<n; i++) {
	    if (scc.scc[i] == scc.scc[i+n]) sat = false;
	    if (scc.scc[i] > scc.scc[i+n]) truth[i] = 1;
	}
	return sat;
    }
    void clear() {
	REP (i, N) G[i].clear();
    }
};
int N;

TwoSAT S;
int X[10111], Y[10111];
pair<int, int> P[20111];

bool ok(LL d) {
    S.clear();
    REP (i, N+N) {
	for (int j=i+1; j<N+N && j < i + 600; j++) {
	    if (P[j].first - P[i].first < d) {
		int x = P[i].second / 2, xb = P[i].second & 1;
		int y = P[j].second / 2, yb = P[j].second & 1;
		if (x == y) continue;

		S.IMP(xb ? S.inv(x) : x, yb ? y : S.inv(y));
		S.IMP(yb ? S.inv(y) : y, xb ? x : S.inv(x));
	    } else break;
	}
    }

    return S.SAT();
}

int main() {
    scanf("%d", &N);
    REP (i, N) scanf("%d%d", X+i, Y+i);
    REP (i, N) {
	P[i] = make_pair(X[i], i+i);
	P[i+N] = make_pair(Y[i], i+i+1);
    }
    sort(P, P+N+N);

    LL lo = 0, hi = (1e9 + 7) / (N-1);
    lo = hi;
    REP (i, N+N-1) amin(lo, (LL)P[i+1].first - P[i].first);
    S = TwoSAT(N);
    while (hi - lo > 1) {
//	eprintf("%lld %lld\n", lo, hi);
	LL m = (lo + hi) / 2;
	if (ok(m)) lo = m;
	else hi = m;
    }

    printf("%lld\n", lo);
    return 0;
}

