bitset<20002> G[20002];
bitset<20002> rG[20002];

vector<int> vs;
bitset<20002> alive;
bitset<20002> nex;
void dfs(int v){
	if(!alive[v])return;
	alive[v] = false;
	while(1){
		nex = alive & G[v];
		int x = nex._Find_first();
		if(x == 20002)break;
		dfs(x);
	}
	vs.push_back(v);
}

bitset<20002> c;
void scc(int v){
	if(!alive[v])return;
	alive[v] = false;
	while(1){
		nex = alive & rG[v];
		int x = nex._Find_first();
		if(x == 20002)break;
		scc(x);
	}
	c[v] = true;
}

bitset<20002> mask;

bool f(int d){
	vector<P> vec;
	for(int i = 0 ; i < n ; i ++){
		vec.push_back(P(x[i],2*i));
		vec.push_back(P(y[i],2*i+1));
	}
	sort(vec.begin(),vec.end());

	bitset<20002> a,b;
	int l = 0, r = 0;
	for(int i = 0 ; i < vec.size() ; i ++){
		while(r < vec.size() && vec[r].fr < vec[i].fr+d){
			a[vec[r].sc^1] = true;
			b[vec[r].sc] = true;
			r ++;
		}
		while(l < vec.size() && vec[l].fr <= vec[i].fr-d){
			a[vec[l].sc^1] = false;
			b[vec[l].sc] = false;
			l ++;
		}
		G[vec[i].sc] = a;
		G[vec[i].sc][vec[i].sc^1] = false;
		rG[vec[i].sc^1] = b;
		rG[vec[i].sc^1][vec[i].sc] = false;
	}

	vs.clear();
	alive.set();
	for(int i = 0 ; i < 2*n ; i ++){
		if(alive[i])dfs(i);
	}
	reverse(vs.begin(),vs.end());
	alive.set();
	for(int i = 0 ; i < vs.size() ; i ++){
		c.reset();
		scc(vs[i]);
		c &= c>>1;
		c &= mask;
		if(c.any())return false;
	}
	return true;
}

