int main()
{
    int n, d;
    cin >> n;
    vector<int> x(n), y(n);
    for (int i = 0; i < n; i++)
    {
        cin >> x[i] >> y[i];
        x[i]--;
        y[i]--;
    }
    int left = 0, right = 1e9;
    // ts[i] = (i-th flag is located on x[i])

    while (right - left > 1)
    {
        int mid = left + (right - left) / 2; // 区間の真ん中
        two_sat ts(n);
        for (int i = 0; i < n; i++)
        {
            for (int j = i + 1; j < n; j++)
            {
                if (abs(x[i] - x[j]) < mid)
                {
                    // cannot use both of x[i] and x[j]
                    ts.add_clause(i, false, j, false);
                }
                if (abs(x[i] - y[j]) < mid)
                {
                    ts.add_clause(i, false, j, true);
                }
                if (abs(y[i] - x[j]) < mid)
                {
                    ts.add_clause(i, true, j, false);
                }
                if (abs(y[i] - y[j]) < mid)
                {
                    ts.add_clause(i, true, j, true);
                }
            }
        }

        /* 回答の応じて、年齢を絞る */
        if (ts.satisfiable())
            left = mid; // mid 歳以上なら、mid 歳以上 right 歳以下になるように
        else
            right = mid; // mid 歳未満なら、left 歳以上 mid 歳未満になるように

        //cout << left << mid << right << endl;
    }
    cout << left << endl;
    return 0;
}

