void buildTree(int x, int low, int high) {
    L[x] = low; R[x] = high;
    if (low == high) {
        it[x] = low;
        return;
    }
    int mid = (low + high) / 2;
    buildTree(x<<1, low, mid);
    buildTree(x<<1|1, mid + 1, high);
    ++nid;
    it[x] = N + nid;
    pos[N + nid] = x;
}

void createNode(int x, int low, int high, int p) {
    if (L[x] > high || R[x] < low) return;
    if (low <= L[x] && R[x] <= high) {
        if (L[x] == R[x]) {
            vertex[p].push_back(neg(L[x]));
            revtex[neg(L[x])].push_back(p);
        }
        else {
            vertex[p].push_back(it[x]);
            revtex[it[x]].push_back(p);
        }
        return;
    }
    createNode(x<<1, low, high, p);
    createNode(x<<1|1, low, high, p);
}

