        revtex[neg(a[i].y)].push_back(i);
//        dbs(i, neg(a[i].y));
        vertex[neg(i)].push_back(a[i].y);
        revtex[a[i].y].push_back(neg(i));
//        dbs(neg(i), a[i].y);
    }

    for (int i = N + 1; i <= N + nid; ++i) {
        int x = pos[i];
        int lef = L[x], rig = R[x];
        for (int j = lef; j <= rig; ++j) {
            vertex[i].push_back(neg(j));
            revtex[neg(j)].push_back(i);
        }
    }
}

bool vis[maxn];
int scc[maxn];
vector<int> st;

void dfs(int u) {
    vis[u] = true;
    for (int v : vertex[u]) {
        if (!vis[v]) {
            dfs(v);
        }
    }
    st.push_back(u);
}

void sfd(int u, int cnt) {
    vis[u] = true;
    scc[u] = cnt;
    for (int v : revtex[u]) {
        if (!vis[v]) {
            sfd(v, cnt);
        }
    }
}

bool check(int distance) {
    buildEdge();
//    db(N + nid);
//    for (int i = 1; i <= N; ++i) {
//        cout << a[i].x << " ";
//    }
//    cout << endl;

    for (int i = 1; i <= N; ++i) {
        int lef = lower_bound(all.begin(), all.end(), a[i].x - distance) - all.begin() + 1;
        int rig = upper_bound(all.begin(), all.end(), a[i].x + distance) - all.begin();
//        db(a[i].x);
//        db(lef); db(rig);
        createNode(1, lef, i - 1, i);
        createNode(1, i + 1, rig, i);
    }

    st.clear();
    fill_n(vis, maxn, 0);
    for (int i = 1; i <= N; ++i) {
        if (!vis[i]) {
            dfs(i);
        }
        if (!vis[neg(i)]) {
            dfs(neg(i));
        }
    }
    fill_n(vis, maxn, 0);
    int cnt = 0;
    while (!st.empty()) {
        int x = st.back(); st.pop_back();
        if (!vis[x]) {
            sfd(x, ++cnt);
        }
    }

    for (int i = 1; i <= N; ++i) {
        if (scc[i] == scc[neg(i)]) {
//            db(a[i].x); db(a[i].y);
            return false;
        }
    }
    return true;
}

