    build(x<<1|1,mid+1,r,bi[x]);
}

void add(int x,int l,int r,int s,int t,int v) {
    if(s<=l && r<=t) {
        addedge(v,bi[x]);return;
    }
    int mid=(l+r)>>1;
    if(s<=mid) add(x<<1,l,mid,s,t,v);
    if(mid<t) add(x<<1|1,mid+1,r,s,t,v);
}

