inline int chk(int now) {
    memset(fr,-1,sizeof(fr));tote=0;
    idx=2*tot;build(1,1,tot,0);
    memset(vi,0,sizeof(vi));
    REP(i,1,n) {
        if(x[i]==y[i]) {
            addedge(x[i]+tot,x[i]);
            if(vi[x[i]] || vi[y[i]]) {
                return 0;
            } else vi[x[i]]=1;
        } else if(vi[x[i]] && vi[y[i]]) {
            return 0;
        } else if(vi[x[i]]) {
            addedge(y[i]+tot,y[i]);vi[y[i]]=1;
        } else if(vi[y[i]]) {
            addedge(x[i]+tot,x[i]);vi[x[i]]=1;
        } else {
            addedge(x[i]+tot,y[i]);
            addedge(y[i]+tot,x[i]);
            addedge(x[i],y[i]+tot);
            addedge(y[i],x[i]+tot);
        }
    }
    int ps=1;
    REP(i,1,tot) {
        while(ps<=tot && tb[i]+now>tb[ps]) ps++;
        if(i+1<=ps-1) add(1,1,tot,i+1,ps-1,i);
    }
    ps=tot;
    PER(i,tot,1) {
        while(ps>=1 && tb[i]-now<tb[ps]) ps--;
        if(ps+1<=i-1) add(1,1,tot,ps+1,i-1,i);
    }
    memset(vis,0,sizeof(vis));cnt=dfs_cnt=0;
    REP(i,1,idx) if(!vis[i]) dfs(i);
    REP(i,1,tot) if(id[i]==id[i+tot]) return 0;
    return 1;
}

