int dfn[MAXN*5],low[MAXN*5],stk[MAXN*5],blk[MAXN*5];
int top=0,clk=0,scccnt=0;
inline void tarjan(int x) {
    dfn[x]=low[x]=++clk;
    stk[++top]=x;
    for(int i=head[x];~i;i=E[i].nxt) {
        int to=E[i].y;
        if(!dfn[to]) {
            tarjan(to);
            low[x]=min(low[x],low[to]);
        } else if(!blk[to]) {
            low[x]=min(low[x],dfn[to]);
        }
    }
    if(low[x]==dfn[x]) {
        scccnt++;
        while(1) {
            int now=stk[top--];
            blk[now]=scccnt;
            if(now==x) break;
        }
    }
