inline void build(int rt,int l,int r) {
    seg[rt].l=l, seg[rt].r=r;
    seg[rt].u=++ndcnt, seg[rt].d=++ndcnt;
    if(l==r) {
        addedge(a[l].id,seg[rt].u);
        addedge(seg[rt].d,a[l].oth);
        return;
    }
    int mid=(l+r)>>1;
    addedge(seg[rt].d,seg[lson].d);
    addedge(seg[rt].d,seg[rson].d);
    build(lson,l,mid);
    addedge(seg[lson].u,seg[rt].u);
    addedge(seg[rson].u,seg[rt].u);
    build(rson,mid+1,r);
}

inline void link(int rt,int l,int r,int x,int y,int id) {
    if(x<=l&&r<=y) {
        addedge(a[id].id,seg[rt].d);
        addedge(seg[rt].u,a[id].oth);
        return;
    }
    int mid=(l+r)>>1;
    if(x<=mid) link(lson,l,mid,x,y,id);
    if(mid<y) link(rson,mid+1,r,x,y,id);
}

inline void PushEdges(int v) {
    tot=0;
    build(1,1,sz);
    int st=1,en=0;
    for(int i=1;i<=sz;i++) {
        while(st<=sz&&a[i].x-a[st].x>=v) st++;
        while(en<sz&&a[en+1].x-a[i].x<v) en++;
        if(st<i) link(1,1,sz,st,i-1,i);
        if(i<en) link(1,1,sz,i+1,en,i);
    }
}

inline bool check(int v) {
    memset(head,-1,sizeof head);
    ndcnt=sz;
    PushEdges(v);
    top=clk=scccnt=0;
    memset(dfn,0,sizeof dfn);
    memset(low,0,sizeof low);
    memset(blk,0,sizeof blk);
    for(int i=1;i<=ndcnt;i++) {
        if(!dfn[i]) tarjan(i);
    }
    for(int i=1;i<=n;i++) {
        if(blk[mp[i][0]]==blk[mp[i][1]]) {
            return 0;
        }
    }
    return 1;
}

