///Cây dương có con đi lên cha.
void xayCayDuong (int id, int curL, int curR) {
    if (curL == curR) {
        nodeId[curL] = id;
        return;
    }
    int mid=(curL+curR)/2;
    adj[2*id].push_back(id); adj[2*id+1].push_back(id);
    xayCayDuong(2*id, curL, mid); xayCayDuong(2*id+1, mid+1, curR);
}
///Cây âm có cha đi xuống các con.
void xayCayAm (int id, int curL, int curR) {
    if (curL == curR) {
        nodeId[neg(curL)] = gocCayAm+id;
        return;
    }
    int mid=(curL+curR)/2;
    adj[gocCayAm+id].push_back(2*id+gocCayAm); adj[gocCayAm+id].push_back(2*id+1+gocCayAm);
    xayCayAm(2*id, curL, mid); xayCayAm(2*id+1,mid+1,curR);
}
///Cung (dauCung, -[uL..uR])
void cungVaoAm (int id, int curL, int curR, int dauCung, int uL, int uR) {
    if (curL>curR || uL>curR || uR<curL) return;
    if (uL<=curL && curR<=uR) {
        adj[dauCung].push_back(gocCayAm+id);
        return;
    }
    int mid=(curL+curR)/2;
    cungVaoAm(2*id, curL, mid, dauCung, uL, uR);
    cungVaoAm(2*id+1, mid+1, curR, dauCung, uL, uR);
}
///Cung ([uL..uR], duoiCung)
void cungRaDuong (int id, int curL, int curR, int uL, int uR, int duoiCung) {
    if (curL>curR || uL>curR || uR<curL) return;
    if (uL<=curL && curR<=uR) {
        adj[id].push_back(duoiCung); return;
    }
    int mid=(curL+curR)/2;
    cungRaDuong(2*id, curL, mid, uL, uR, duoiCung);
    cungRaDuong(2*id+1, mid+1, curR, uL, uR, duoiCung);
}
///cung i -> j như bình thường.
