        if (nguyHiem < i)
            taoQuanHe_koCungTrue(i, ii(nguyHiem, i-1));
    }
}
void xoaDoThi () {
    for (int i=1; i<= sodinh; i++)
        adj[i].clear();
}

int scc_id[18*N], disc[18*N], low[18*N], cnt, scc_n;
bool deleted[18*N];
stack<int> S;
void visit (int u) {
    low[u]=disc[u]=++cnt;
    S.push(u);
    for (int v : adj[u])
    if (!deleted[v]) {
        if (disc[v] == 0) {
            visit(v);
            low[u] = min(low[u], low[v]);
        }
        else low[u] = min(low[u], disc[v]);
    }

    if (low[u] == disc[u]) {
        scc_n++;
        do {
            int v=S.top(); S.pop();
            scc_id[v] = scc_n; deleted[v]=1;
            if (v==u) break;
        } while (1);
    }
}
bool TwoSAT (int kcAnToan) {
    dungDoThi(kcAnToan);
    fill(low+1, low+sodinh+1, 0); fill(disc+1, disc+sodinh+1, 0); cnt=scc_n=0;
    fill(deleted+1, deleted+sodinh+1, 0);
    fill(scc_id+1, scc_id+sodinh+1, 0);

    for (int i=1; i<=sodinh; i++)
        if (disc[i]==0)
            visit(i);
    bool ans = 1;
    for (int i=1; i<=m; i++) {
        int u=nodeId[i], v=nodeId[neg(i)];
        if (scc_id[u] == scc_id[v]) {
            ans=0;
            break;
        }
    }
    xoaDoThi();
    return ans;
}
int answer () {
    int l=1, r=a[m].first-a[1].first, ans=0;
    while (l <= r) {
        int mid=(l+r)/2;
        if (TwoSAT(mid)) {
            ans = mid;
            l = mid+1;
        }
        else r=mid-1;
    }
    return ans;
}
