      if( opid % 2 == 0 ){
        scc.add_edge( id , opid + 1 );
      } else {
        scc.add_edge( id , opid - 1 );
      }
    }
  }
  int k = scc.scc();
  REP( i , n ){
    if( scc.cmp[2*i] == scc.cmp[2*i+1] ){
      return false;
    }
  }
  return true;
}

