void dfs1(int p, int d)
{
	chk[p] = 1;

	for(; ; ){
		auto it = S.lower_bound(pii(X[p] - d + 1, -1));
		if(it == S.end() || it -> first >= X[p] + d) break;
		int t = it -> second; S.erase(it);
		if(t != p && !chk[t ^ 1]) dfs1(t ^ 1, d);
	}

	T.push_back(p);
}

void dfs2(int p, int d, int s)
{
	chk[p] = 1; C[p] = s;

	for(; ; ){
		auto it = S.lower_bound(pii(X[p ^ 1] - d + 1, -1));
		if(it == S.end() || it -> first >= X[p ^ 1] + d) break;
		int t = it -> second; S.erase(it);
		if(t != (p ^ 1) && !chk[t]){
			dfs2(t, d, s);
		}
	}
}

bool check(int d)
{
	int i, s;

	S.clear();

	for(i=0; i<n+n; i++){
		S.insert(pii(X[i], i));
		chk[i] = 0;
	}

	for(i=0; i<n+n; i++){
		if(!chk[i]) dfs1(i, d);
	}

