bool DfsFb(int v, bool rev, vector<int> &r) {
  vised[v] = true;
  r.eb(ord[v]);

  bool ret = false;
  for (int u : es[rev][v]) {
    u = belong[u];
    if (ord[u] == UB) ret = true;
    if (!vised[u] && LB <= ord[u] && ord[u] <= UB) {
      ret |= DfsFb(u, rev, r);
    }
  }
  return ret;
}

void Decompose(vector<int> &Rf) {
  int d = Rf[0];
  vector<int> tmp;

  reps(i, 1, Rf.size()) {
    int v = Rf[i];
    belong[v] = d;
    rep(j, 2) {
      tmp.resize(es[j][v].size() + es[j][d].size());
      merge(all(es[j][v]), all(es[j][d]), tmp.begin());
      es[j][d].swap(tmp);
    }
  }
}

bool AddEdge(int x, int y) {
  x = belong[x];
  y = belong[y];

  LB = ord[y];
  UB = ord[x];
  vector<int> Rb, Rf, R;
  if (LB < UB) {
    if (DfsFb(y, false, Rf)) {
      Decompose(Rf);
      for (int v : Rf) {
        if (belong[v^1] == belong[v]) return true;
      }
      return false;
    }
  }

  DfsFb(x, true, Rb);

  vector<int> L;
  sort(all(Rb));
  for (int idx : Rb) {
    int v = seq[idx];
    vised[v] = false;
    L.eb(v);
  }

  sort(all(Rf));
  for (int idx : Rf) {
    int v = seq[idx];
    vised[v] = false;
    L.eb(v);
  }
  R.resize(Rb.size() + Rf.size());
  merge(all(Rb), all(Rf), R.begin());
  rep(i, L.size()) {
    int v = L[i];
    int idx = R[i];
    ord[v] = idx;
    seq[idx] = v;
  }
  return false;
}

