int findl(int ave) { // >=
	int l = 1, r = d[0], ret = d[0];
	for ( ; l <= r; ) {
		int mid = (l + r) / 2;
		if (d[mid] >= ave) ret = mid, r = mid - 1;
			else l = mid + 1;
	} 
	return ret;
}
int findr(int ave) { // <=
	int l = 1, r = d[0], ret = 0;
	for ( ; l <= r; ) {
		int mid = (l + r) / 2;
		if (d[mid] <= ave) ret = mid, l = mid + 1;
			else r = mid - 1;
	}
	return ret;
}
void pre() {
	c[0] = d[0] = 0;
	rep(i, 1, n) c[++ c[0]] = a[i].x, c[++ c[0]] = a[i].y;
	sort(c + 1, c + c[0] + 1);
	for (int i = 1, j; i <= c[0]; i = j) {
		d[++ d[0]] = c[i];
		for (j = i + 1; j <= c[0] && c[i] == c[j]; ++ j);
	}
	rep(i, 1, n) a[i].x = findl(a[i].x), a[i].y = findl(a[i].y);
}
void add(int x, int y) { ter[++ e] = y, nxt[e] = lnk[x], lnk[x] = e; }
void build(int p, int l, int r) {
	tr[p] = ++ cnt;
	if (l == r) { add(tr[p], l<<1|1); return ; }
	int mid = (l + r) / 2;
	build(p << 1, l, mid), build((p << 1) + 1, mid + 1, r);
	add(tr[p], tr[p << 1]), add(tr[p], tr[(p << 1) + 1]);
}
void modify(int p, int l, int r, int lx, int rx, int fr) {
	if (l == lx && r == rx) { add(fr, tr[p]); return ; }
	int mid = (l + r) / 2;
	if (rx <= mid) modify(p << 1, l, mid, lx, rx, fr); else
	if (lx > mid) modify((p << 1) + 1, mid + 1, r, lx, rx, fr); else
	modify(p << 1, l, mid, lx, mid, fr), modify((p << 1) + 1, mid + 1, r, mid + 1, rx, fr);
}
void tarjan(int p) {
	dfn[p] = low[p] = ++ tot, vis[p] = false;
	st[++ top] = p, ins[p] = true;
	for (int i = lnk[p]; i; i = nxt[i]) {
		if (vis[ter[i]]) tarjan(ter[i]), low[p] = min(low[p], low[ter[i]]);
			else if (ins[ter[i]]) low[p] = min(low[p], dfn[ter[i]]);
	}
	if (low[p] == dfn[p]) {
		for ( ; st[top] != p; -- top) bel[st[top]] = p, ins[st[top]] = false;
		bel[st[top]] = p, ins[st[top]] = false, -- top;
	}
}
bool solve(int ave) {
	memset(nxt, 0, sizeof(nxt));
	memset(lnk, 0, sizeof(lnk)); e = 0;
	cnt = 2 * d[0] + 1;
	build(1, 1, d[0]);
	rep(i, 1, d[0]) {
		int l = findl(d[i] - ave + 1), r = findr(d[i] + ave - 1);
		if (l < i && i > 1) modify(1, 1, d[0], l, i - 1, i<<1);
		if (i < r && i < d[0]) modify(1, 1, d[0], i + 1, r, i<<1);
	} 
	rep(i, 1, n) add(a[i].x<<1|1, a[i].y<<1), add(a[i].y<<1|1, a[i].x<<1);
	memset(vis, true, sizeof(vis));
	memset(ins, false, sizeof(ins));
	tot = top = 0;
	rep(i, 2, cnt) if (vis[i]) tarjan(i);
	rep(i, 1, d[0]) if (bel[i<<1] == bel[i<<1|1]) { return false; }
	return true;
}
