namespace GRAPH
{
	const int MAXV = (int) 2e6;

	int N = 0;
	vector<int> adj[MAXV + 5];

	int dfn[MAXV + 5], low[MAXV + 5], dfn_cur, id[MAXV + 5], cnt;
	int stk[MAXV + 5], top, in_stk[MAXV + 5];

	inline void dfs(int u)
	{
		dfn[u] = low[u] = ++dfn_cur;

		in_stk[stk[++top] = u] = 1;
		for(auto v : adj[u])
			if(!dfn[v])
			{
				dfs(v);
				chkmin(low[u], low[v]);
			}
			else if(in_stk[v] && dfn[v] < dfn[u]) chkmin(low[u], dfn[v]);

		if(low[u] >= dfn[u])
		{
			++cnt;
			while(top > 0)
			{
				int p = stk[top--];
				in_stk[p] = 0;
				id[p] = cnt;
				if(p == u) break;
			}
		}
	}

	inline void find_SCC()
	{
		dfn_cur = top = cnt = 0;
		for(int i = 1; i <= N; ++i) dfn[i] = low[i] = id[i] = in_stk[i] = 0;
		for(int i = 1; i <= N; ++i) if(!dfn[i]) dfs(i);
	}
}
