namespace SEGT
{
	const int MAX_NODE = MAXN * 4 * 2;

	int nd[MAX_NODE + 5], lc[MAX_NODE + 5], rc[MAX_NODE + 5], cnt;

	inline int build(int l, int r)
	{
		int u = ++cnt;
		nd[u] = ++N;
		if(l == r) return u;

		int mid = (l + r) / 2;
		adj[nd[u]].push_back(nd[lc[u] = build(l, mid)]);
		adj[nd[u]].push_back(nd[rc[u] = build(mid + 1, r)]);
		return u;
	}

	inline void insert(int u, int l, int r, int pos, int v)
	{
		if(l == r)
		{
			adj[nd[u]].push_back(v);
			return;
		}

		int mid = (l + r) / 2;
		if(pos <= mid) insert(lc[u], l, mid, pos, v);
		else insert(rc[u], mid + 1, r, pos, v);
	}

	inline void update(int u, int l, int r, int ql, int qr, int v)
	{
		if(ql <= l && r <= qr)
		{
			adj[v].push_back(nd[u]);
			return;
		}

		int mid = (l + r) / 2;
		if(ql <= mid) update(lc[u], l, mid, ql, qr, v);
		if(mid < qr) update(rc[u], mid + 1, r, ql, qr, v);
	}
}

int rt;

inline bool check(int lim)
{
	for(int i = 1; i <= n; ++i) adj[x[i]].clear(), adj[y[i]].clear();
	for(int i = 1; i <= n; ++i)
	{
		int l, r;

		l = lower_bound(vals + 1, vals + M + 1, mp(vals[a[i].x].fst - lim + 1, -n)) - vals;
		r = upper_bound(vals + 1, vals + M + 1, mp(vals[a[i].x].fst + lim - 1, +n)) - vals - 1;
		if(l < a[i].x) SEGT::update(rt, 1, M, l, a[i].x - 1, x[i]);
		if(a[i].x < r) SEGT::update(rt, 1, M, a[i].x + 1, r, x[i]);

		l = lower_bound(vals + 1, vals + M + 1, mp(vals[a[i].y].fst - lim + 1, -n)) - vals;
		r = upper_bound(vals + 1, vals + M + 1, mp(vals[a[i].y].fst + lim - 1, +n)) - vals - 1;
		if(l < a[i].y) SEGT::update(rt, 1, M, l, a[i].y - 1, y[i]);
		if(a[i].y < r) SEGT::update(rt, 1, M, a[i].y + 1, r, y[i]);
	}

	GRAPH::find_SCC();
	for(int i = 1; i <= n; ++i) if(id[x[i]] == id[y[i]]) return 0;
	return 1;
}

inline void solve()
{
	discrete();

	rt = SEGT::build(1, M);
	for(int i = 1; i <= n; ++i)
	{
		x[i] = ++N, y[i] = ++N;
		SEGT::insert(rt, 1, M, a[i].x, y[i]);
		SEGT::insert(rt, 1, M, a[i].y, x[i]);
	}

	int l = 0, r = (int) 1e9;
	while(l < r)
	{
		int mid = (l + r + 1) / 2;
		if(check(mid)) l = mid;
		else r = mid - 1;
	}
	printf("%d\n", l);
}

