    void build(int &rt, int fa, int l, int r)
    {
        rt = ++tot;
        if(fa) E[fa].push_back(rt);
        if(l == r) return;
        int mid = HalF;
        build(lc[rt], rt, l, mid);
        build(rc[rt], rt, mid + 1, r);
