pr D[N];

inline void down(int &x, const int y) {x > y ? x = y : 0;}

namespace Graph {
	const int N = 500054, M = 1000054;

	struct edge {
		int u, v;
		edge (int u0 = 0, int v0 = 0) : u(u0), v(v0) {}
	} e[M];

	int V, E = 0;
	int first[N], next[M];
	int cnt = 0, id[N], low[N];
	int stc = 0, stack[N], top[N];
	bool in_stack[N];

	inline void addedge(int u, int v) {e[++E] = edge(u, v), next[E] = first[u], first[u] = E;}
	inline void deledge(int end) {for (; E > end; --E) first[e[E].u] = next[E];}

	void dfs(int x) {
		int i, y; id[x] = low[x] = ++cnt, in_stack[x] = true, stack[stc++] = x;
		for (i = first[x]; i; i = next[i])
			if (!id[y = e[i].v])
				dfs(y), down(low[x], low[y]);
			else if (in_stack[y])
				down(low[x], id[y]);
		if (id[x] == low[x])
			for (y = 0; y != x; y = stack[--stc], in_stack[y] = false, top[y] = x);
	}

	inline bool _2_SAT() {
		int i, u, v; cnt = stc = 0;
		memset(id, 0, (V + 1) << 2);
		for (i = 1; i <= V; ++i) if (!id[i]) dfs(i);
		for (i = 1; i <= n; ++i)
			if ((u = Graph::top[i]) == (v = Graph::top[i + n])) return false;
		return true;
	}
}

namespace ST {
	struct node {int lc, rc;} x[N * 2];
	int cnt = 0, leaf[N];

	int build(int L, int R) {
		int id = ++cnt;
		if (L == R) return leaf[L] = id;
		int M = (L + R - 1) >> 1;
		x[id].lc = build(L, M), x[id].rc = build(M + 1, R);
		Graph::addedge(sg(id), sg(x[id].lc)), Graph::addedge(sg(id), sg(x[id].rc));
		return id;
	}

	void locate(int id, int L, int R, int ql, int qr, int vertex) {
		if (qr < L || R < ql || qr < ql) return;
		if (ql <= L && R <= qr) return Graph::addedge(vertex, sg(id));
		int M = (L + R - 1) >> 1;
		if (ql <= M) locate(x[id].lc, L, M, ql, qr, vertex);
		if (qr > M) locate(x[id].rc, M + 1, R, ql, qr, vertex);
	}
}

inline int LB(int val) {return std::lower_bound(D, D + 2 * n, pr(val, INT_MIN)) - D - 1;}
inline int UB(int val) {return std::lower_bound(D, D + 2 * n, pr(val, INT_MAX)) - D;}

inline bool check(int v) {
	Graph::deledge(Estd);
	for (int i = 0; i < n; ++i)
		ST::locate(1, 0, 2 * n - 1, UB(l[i] - v), lp[i] - 1, i + 1),
		ST::locate(1, 0, 2 * n - 1, lp[i] + 1, LB(l[i] + v), i + 1),
		ST::locate(1, 0, 2 * n - 1, UB(r[i] - v), rp[i] - 1, i + n + 1),
		ST::locate(1, 0, 2 * n - 1, rp[i] + 1, LB(r[i] + v), i + n + 1);
	return Graph::_2_SAT();
}

int main() {
