	Estd = Graph::E, Graph::V = 6 * n - 1;
	for (R = std::max(r[1] - *l, *r - l[1]); L < R; check(M = (L + R + 1) / 2) ? L = M : (R = M - 1));
	printf("%d\n", L);
	return 0;
}

