int X[MAXN], Y[MAXN];
pii A[MAXN<<1];
bool mark[MAXM];
int comp[MAXM], cid;
int seg[MAXN<<3], N;
vector<int> G[MAXM], GR[MAXM], topol;

inline void add_edge(int u, int v){
	G[u].pb(v);
	GR[v].pb(u);
}

inline void add_clause(int u, int v){
	add_edge(u^1, v);
	add_edge(v^1, u);
}

void Set(int id, int tl, int tr, int pos, int val){
	if (pos<tl || tr<=pos) return ;
	if (tr-tl==1){
		seg[id]=val;
		return ;
	}
	int mid=(tl+tr)>>1;
	Set(id<<1, tl, mid, pos, val);
	Set(id<<1 | 1, mid, tr, pos, val);
	if (seg[id<<1]!=-1 && seg[id<<1 | 1]!=-1){
		seg[id]=(N++)<<1;
		add_clause(seg[id<<1]^1, seg[id]);
		add_clause(seg[id<<1 | 1]^1, seg[id]);
		add_clause(seg[id<<1]^1, seg[id<<1 | 1]^1);
	}
	else seg[id]=seg[id<<1]+seg[id<<1 | 1]+1;
}

inline void Add(int pos){
	Set(1, 0, n<<1, pos, pos);
}
inline void Rem(int pos){
	Set(1, 0, n<<1, pos, -1);
}

void dfs1(int node){
	mark[node]=1;
	for (int v:G[node]) if (!mark[v]) dfs1(v);
	topol.pb(node);
}

void dfs2(int node, int cid){
	comp[node]=cid;
	for (int v:GR[node]) if (!comp[v]) dfs2(v, cid);
}

inline bool check(int val){
	for (int i=0; i<2*N; i++){
		mark[i]=0;
		comp[i]=0;
		G[i].clear();
		GR[i].clear();
	}
	N=n;
	cid=0;
	topol.clear();
	memset(seg, -1, sizeof(seg));
	int j=0;
	for (int i=0; i<2*n; i++){
		while (A[i].first-A[j].first>=val) Rem(A[j++].second);
		Add(A[i].second);
	}
	for (int i=0; i<2*N; i++) if (!mark[i]) dfs1(i);
	reverse(all(topol));
	for (int v:topol) if (!comp[v]) dfs2(v, ++cid);
	for (int i=0; i<N; i++) if (comp[i<<1]==comp[i<<1 | 1]) return 0;
	return 1;
}

