using namespace std;

constexpr int MAXN = 10005;
constexpr int INF = 1000000009;

struct Node{
    int id;
    int val;
    bool operator < (const Node &b) const{
        return val < b.val;
    }
};

int n;
int tot;
Node s[MAXN << 1];
vector<int> myStack;
int mark[MAXN << 1];
int label[MAXN << 1];
vector<int> graph[MAXN << 1];
vector<int> nGraph[MAXN << 1];

void getGraph(int mid){
    tot = 0;
    myStack.clear();
    for(int i = 0; i < 2 * n; ++i){
        graph[i].clear();
        nGraph[i].clear();
        mark[i] = label[i] = 0;
    }
    for(int i = 0 ; i < 2 * n; ++i){
        int j = i + 1;
        while(j < 2 * n && abs(s[j].val - s[i].val) < mid){
            if((s[i].id ^ 1) != s[j].id){
                graph[s[i].id].push_back(s[j].id ^ 1);
                graph[s[j].id].push_back(s[i].id ^ 1);
                nGraph[s[j].id ^ 1].push_back(s[i].id);
                nGraph[s[i].id ^ 1].push_back(s[j].id);
            }
            ++j;
        }
    }
}

void getAns(int u, vector<int> g[], bool flag) {
	if (flag) {
		mark[u] = 1;
	}
	else {
		label[u] = tot;
	}
	for (int i = 0; i < (int)g[u].size(); ++i) {
		int v = g[u][i];
		if (flag && !mark[v]) {
			getAns(v, g, flag);
		}
		if (!flag && !label[v]) {
			getAns(v, g, flag);
		}
	}
	if (flag) {
		myStack.push_back(u);
	}
}

bool check(int mid){
	getGraph(mid);
	for (int i = 0; i < 2 * n; ++i) {
		if (!mark[i]) {
			getAns(i, graph, true);
		}
	}
	while (!myStack.empty()) {
		int u = myStack.back();
		myStack.pop_back();
		if (!label[u]) {
			++tot;
			getAns(u, nGraph, false);
		}
	}
	for (int i = 0; i < n; ++i) {
		if (label[2 * i] == label[2 * i + 1]) {
			return false;
		}
	}
	return true;
}

int main(){
    scanf("%d", &n);
    for(int i = 0; i < n; ++i){
        scanf("%d%d", &s[i * 2].val, &s[i * 2 + 1].val);
        s[i * 2].id = i * 2;
        s[i * 2 + 1].id = i * 2 + 1;
    }
    sort(s, s + 2 * n);
    int left = 0;
    int right = INF;
    while(left < right){
        int mid = (left + right + 1) >> 1;
        if(check(mid)){
            left = mid;
        }
        else{
            right = mid - 1;
        }
    }
    printf("%d\n", left);
    return 0;
}

#include <bits/stdc++.h>
