        pos[i * 2 - 1] = { x[i], pii(i * 2 - 1, i * 2) };
        pos[i * 2] = { y[i], pii(i * 2, i * 2 - 1) };
    }

    sort(pos + 1, pos + 2 * n + 1);

    int l = 1, r = inf;
    while (l <= r) {
        int mid = (l + r) >> 1;
        if (!check(mid, n)) r = mid - 1;
        else l = mid + 1;
    }

