const int maxn=1e4+5;

int n;
pair < int, int > l[maxn];
set < pair < int, int > > s;
int boja[maxn*2];
int sad;
stack < pair < int, int > > red;
int mid;

void dfs(pair < int, int > x){
	s.erase(x);
	pair < int, int > p={x.first-mid+1, 0};
	set < pair < int, int > >::iterator it=s.lower_bound(p);
	while(it!=s.end() && (*it).first<x.first+mid){
		p=*it;
		if(p.second<n){
			p={l[p.second].second, p.second+n};
		}
		else{
			p={l[p.second-n].first, p.second-n};
		}
		if(s.find(p)!=s.end()){
			dfs(p);
		}
		if(s.empty()){
			break;
		}
		it=s.upper_bound(*it);
	}
	red.push(x);
}

void dfs1(pair < int, int > x){
	s.erase(x);
	boja[x.second]=sad;
	pair < int, int > p=x;
	if(p.second<n){
		p={l[p.second].second, p.second+n};
	}
	else{
		p={l[p.second-n].first, p.second-n};
	}
	pair < int, int > z={p.first-mid+1, 0};
	set < pair < int, int > >::iterator it=s.lower_bound(z);
	while(it!=s.end() && (*it).first<p.first+mid){
//		cout << "pod " << p.first << " je " << (*it).first << endl;
		if(p.second!=(*it).second){
			dfs1(*it);
		}
		if(s.empty() || it==s.end()){
			break;
		}
		it=s.upper_bound(*it);
	}
}

bool provjeri(int x){
	for(int i=0; i<n; i++){
		s.insert({l[i].first, i});
		s.insert({l[i].second, i+n});
	}
	while(!s.empty()){
		dfs(*s.begin());
	}
	for(int i=0; i<n; i++){
		s.insert({l[i].first, i});
		s.insert({l[i].second, i+n});
	}
	sad=1;
//	cout << red.size() << endl;
 	while(!red.empty()){
		if(s.find(red.top())!=s.end()){
//			cout << "ide se " << red.top().first << " " << red.top().second << endl;
			dfs1(red.top());
			sad++;
		}
		red.pop();
	}
	bool p=1;
	for(int i=0; i<n; i++){
		if(boja[i]==boja[i+n]){
			p=0;
			break;
		}
	}
	memset(boja, 0,  sizeof(boja));
	return p;
}

int binary(){
	int lo=0, hi=maxn;
	while(lo<hi){
		mid=(lo+hi)/2+1;
//		cout << mid << endl;
		if(provjeri(mid)){
			lo=mid;
		}
		else{
			hi=mid-1;
		}
	}
	return lo;
}

