void add(int l, int r, int from) {
    from += SIZE;
    l += SIZE;
    r += SIZE;
    for (; l<r; l>>=1, r>>=1) {
	if (l&1) { G[from].push_back(l); l++; }
	if (r&1) { r--; G[from].push_back(r); }
    }
}

bool ok(int mid) {
    REP (i, SIZE*2) G[i].clear();

    int l = 0;
    int r = 0;
    REP (i, N2) {
	while (r < N2 && P[r].first - P[i].first < mid) r++;
	while (l < i && P[i].first - P[l].first >= mid) l++;
	if (i+1 < r) {
	    add(i+1, r, buddy[i]);
	}
	if (l < i) {
	    add(l, i, buddy[i]);
	}
    }

    for (int v=SIZE; --v;) {
	G[v].push_back(v*2);
	G[v].push_back(v*2+1);
    }

    SCC::build(G, SIZE*2);
    REP (i, N2) if (SCC::scc[i+SIZE] == SCC::scc[buddy[i]+SIZE]) return false;
    return true;
}

