    int get(int x) { return x < 0 ? -x + N : x; }

    void init(int _N)
    {
        N = _N;
        for(int i = 1; i <= 2 * N; i++) edg[i].clear(), redg[i].clear();
    }

    void addEdge(int x, int y) { edg[x].push_back(y); redg[y].push_back(x); }

    void addCondition(int x, int y) { x = get(x); y = get(y); addEdge(x, y); addEdge( rev(y), rev(x) ); }

    void DFS(int nod)
    {
        if(f[nod])  return;
        f[nod] = 1;
        for(auto nxt: edg[nod])
            DFS(nxt);
        ord[++K] = nod;
    }

    void DFS2(int nod)
    {
        if(f[nod])  return;
        f[nod] = K;
        for(auto nxt: redg[nod])
            DFS2(nxt);
    }

    void printGraph()
    {
        for(int i = 1; i <= 2 * N; i++)
            for(auto x: edg[i])
                printf("%d %d\n", i, x);
    }

    bool solve()
    {
        for(int i = 1; i <= 2 * N; i++) f[i] = 0;

        K = 0;
        for(int i = 1; i <= 2 * N; i++)
            if(!f[i])
                DFS(i);

        for(int i = 1; i <= 2 * N; i++) f[i] = 0;
        reverse(ord + 1, ord + K + 1);

        K = 0;
        for(int i = 1; i <= 2 * N; i++)
            if(!f[ ord[i] ])
                K++, DFS2(ord[i]);

        for(int i = 1; i <= N; i++)
            if(f[i] == f[i + N])
                return false;

        return true;
    }
}sat;

bool can(int dst)
{
    sat.init(M);
    for(int i = 1; i <= M; i += 2)
    {
        sat.addCondition(i, -(i + 1));
        sat.addCondition(-(i + 1), i);
    }

    int dr = 1;
    for(int i = 1; i <= M; i++)
    {
        dr = max(dr, i + 1);
        while(dr <= M && pos[ ord[dr] ] - pos[ ord[i] ] < dst)  dr++;
        for(int j = i + 1; j < dr; j++)    sat.addCondition(ord[i], -ord[j]);
    }

    return sat.solve();
}

