int dfn[N], low[N], num, ins[N], stk[N], top, bel[N], cnt;

void tarjan(int x) {
  dfn[x] = low[x] = ++num;
  ins[stk[++top] = x] = 1;
  for (int y : G[x]) {
    if (!dfn[y]) {
      tarjan(y);
      low[x] = std::min(low[x], low[y]);
    } else if (ins[y])
      low[x] = std::min(low[x], dfn[y]);
  }
  if (low[x] == dfn[x]) {
    int y; ++cnt;
    do {
      ins[y = stk[top--]] = 0;
      bel[y] = cnt;
    } while (x != y);
  }
}

