	for(int i = 0; i < 2*N; i++){
		int v = vec[i].second.first + (1-vec[i].second.second)*N;
		G[2*N+i/B].push_back(v);
	}
	for(int i = 0; i < 2*N; i++){
		int v = vec[i].second.first + vec[i].second.second*N;
		int l = lower_bound(vec.begin(), vec.end(), make_pair(vec[i].first - (d-1), make_pair(-1, -1))) - vec.begin();
		int r = lower_bound(vec.begin(), vec.end(), make_pair(vec[i].first + d, make_pair(-1, -1))) - vec.begin() - 1;
		range(v, l, i-1);
		range(v, i+1, r);
	}

	for(int i = 0; i < V; i++) revG[i].clear();
	for(int i = 0; i < V; i++){
		for(int j = 0; j < G[i].size(); j++){
			revG[G[i][j]].push_back(i);
		}
	}

	for(int i = 0; i < V; i++) used[i] = false;
	topo.clear();
	for(int i = 0; i < V; i++) if(!used[i]) tpsort(i, -1);
	reverse(topo.begin(), topo.end());

