using namespace std;

typedef long long i64;

const int NMAX = 40005;

vector<int> G[NMAX], Gt[NMAX];
vector<pair<int, int>> A;

int n;

int non(int x) {
    return x < n ? x + n : x - n;
}

void addEdge(int from, int to) {
    G[non(from)].push_back(to);
    Gt[to].push_back(non(from));
    G[non(to)].push_back(from);
    Gt[from].push_back(non(to));
}

bool used[NMAX];
int minDist;
int order[NMAX], orderInd;

multiset<pair<int, int>> var, negVar;

template<class Container, class T>
int getPos(Container a, T e) {
    return lower_bound(a.begin(), a.end(), e) - a.begin();
}

void dfs1(int node) {
    used[node] = true;
    for (int to: G[node]) {
        if (!used[to]) {
            dfs1(to);
        }
    }
    multiset<pair<int, int>>& adj = negVar;
    if (node < n) {
        while (true) {
            auto it = adj.upper_bound(A[node]);
            if (it == adj.end() || it->first - A[node].first >= minDist) {
                break;
            }
            int to = getPos(A, *it);
            adj.erase(it);
            if (!used[to + n]) {
                dfs1(to + n);
            }
        }
        while (true) {
            auto it = adj.lower_bound(A[node]);
            if (it == adj.begin()) {
                break;
            }
            --it;
            if (A[node].first - it->first >= minDist) {
                break;
            }
            int to = getPos(A, *it);
            adj.erase(it);
            if (!used[to + n]) {
                dfs1(to + n);
            }
        }
    }
    order[orderInd++] = node;
}

int cc[NMAX];

void dfs2(int node, int ccc) {
    cc[node] = ccc;
    used[node] = false;
    for (int to: Gt[node]) {
        if (used[to]) {
            dfs2(to, ccc);
        }
    }
    multiset<pair<int, int>>& adj = var;
    if (node >= n) {
        while (true) {
            auto it = adj.upper_bound(A[node - n]);
            if (it == adj.end() || it->first - A[node - n].first >= minDist) {
                break;
            }
            int to = getPos(A, *it);
            adj.erase(it);
            if (used[to]) {
                dfs2(to, ccc);
            }
        }
        while (true) {
            auto it = adj.lower_bound(A[node - n]);
            if (it == adj.begin()) {
                break;
            }
            --it;
            if (A[node - n].first - it->first >= minDist) {
                break;
            }
            int to = getPos(A, *it);
            adj.erase(it);
            if (used[to]) {
                dfs2(to, ccc);
            }
        }
    }
}

bool works(int minDist) {
    ::minDist = minDist;
    orderInd = 0;
    var = multiset<pair<int, int>>(A.begin(), A.end());
    negVar = multiset<pair<int, int>>(A.begin(), A.end());
    fill(used, used + 2 * n, false);
    for (int i = 0; i < 2 * n; ++i) {
        if (!used[i]) {
            dfs1(i);
        }
    }
    int ccc = 0;
    for (int i = 2 * n - 1; i >= 0; --i) {
        int node = order[i];
        if (used[node]) {
            dfs2(node, ccc++);
        }
    }
    for (int i = 0; i < n; ++i) {
        if (cc[i] == cc[i + n]) {
            return false;
        }
    }
    return true;
}

