			{
				cnt++;
				graph[i].push_back(j);
				graph[j + n].push_back(i + n);
			}

			if (abs(y[i] - x[j]) < t)
			{
				cnt++;
				graph[i + n].push_back(j + n);
				graph[j].push_back(i);
			}

