void dfs(int p, const Graph &G, vector<int> &cmp, vector<int> &ord, int k) {
    if(cmp[p] >= 0) return;
    cmp[p] = k;
    for(size_t i=0; i<G[p].size(); i++) {
        dfs(G[p][i], G, cmp, ord, k);
    }
    ord.push_back(p);
}

vector<int> scc(const Graph &G) {
    int n = G.size();
    Graph H(n);
    for(int i=0; i<n; i++) {
        for(size_t j=0; j<G[i].size(); j++) {
            int from = i, to = G[i][j];
            H[to].push_back(from);
        }
    }
    vector<int> cmp(n, -1), ord, dro;
    for(int i=0; i<n; i++) dfs(i, G, cmp, ord, i);
    reverse(ord.begin(), ord.end());
    fill(cmp.begin(), cmp.end(), -1);
    for(int i=0; i<n; i++) dfs(ord[i], H, cmp, dro, i);
    return cmp;
}

Graph makeg(int k) {
    Graph G(2*N);
    for(int i=0; i<N; i++) {
        for(int j=0; j<i; j++) {
            if(abs(x[i] - x[j]) < k) {
                G[i].push_back(j+N);
                G[j].push_back(i+N);
            }
            if(abs(x[i] - y[j]) < k) {
                G[i].push_back(j);
                G[j+N].push_back(i+N);
            }
            if(abs(y[i] - x[j]) < k) {
                G[i+N].push_back(j+N);
                G[j].push_back(i);
            }
            if(abs(y[i] - y[j]) < k) {
                G[i+N].push_back(j);
                G[j+N].push_back(i);
            }
        }
    }
    return G;
}

bool d(Graph &G) {
    vector<int> ret = scc(G);
    for(int i=0; i<N; i++) {
        if(ret[i] == ret[i+N]) return false;
    }
    return true;
}

