            int a = p[i].F,b = p[i].S,c = p[j].F,d = p[j].S;
           cnt = 0;
            if (abs(a - c) < m){
                addedge(i,j + n);
                addedge(j,i + n);
                cnt += 1;
            }
            if (abs(a - d) < m){
                addedge(i,j);
