                addedge(i + n,j + n);
                addedge(j,i);
                cnt += 4;
            }
            if (abs(b - d) < m){
                addedge(i + n,j);
                addedge(j + n,i);
                cnt += 8;
            }
            if (cnt == 15) return 0;
        }
    }
    st.clear();
    for (int i = 1;i <= 2 * n;i++){
        if (vis[i] == 0){
            vis[i] = 1;
            dfsout(i);
        }
    }
    reverse(st.begin(),st.end());
