    for(int i=1;i<=n;i++){
        scanf("%d%d", &x[i], &y[i]);
        a[i] = mp(x[i], i);
        a[i+n] = mp(y[i], i);
    }
    sort(a+1, a+2*n+1);
    for(int i=1;i<=2*n;i++){
        if(idx[a[i].se][0] == 0) idx[a[i].se][0] = i;
        else idx[a[i].se][1] = i;
    }
    int lo = 1, hi = 1e9, ans = 0;
    while(lo <= hi){
        int mid = (lo+hi)/2;

        twosat sat(16*n+2);
        vector<pii> clause;
        build(1, 1, 2*n, clause);
        for(int i=0;i<sz(clause);i++){
            int x = clause[i].fi*2, y = clause[i].se*2;
            sat.impl(y, x);
        }

        int l = 1, r = 1;
        for(int i=1;i<=2*n;i++){
            l = min(l, i);
            r = max(r, i);
            while(a[i].fi-a[l].fi >= mid) l++;
            while(r+1 <= 2*n && a[r+1].fi-a[i].fi < mid) r++;
            vector<int> Q1, Q2, Q3;

            query(1, 1, 2*n, i, i, Q1);
            if(i != l) query(1, 1, 2*n, l, i-1, Q2);
            if(i != r) query(1, 1, 2*n, i+1, r, Q3);

            for(int i=0;i<sz(Q2);i++){
                int x = Q2[i]*2, y = Q1[0]*2;
                sat.nand(x, y);
            }
            for(int i=0;i<sz(Q3);i++){
                int x = Q3[i]*2, y = Q1[0]*2;
                sat.nand(x, y);   
            }
        }
        for(int i=1;i<=n;i++){
            int x = idx[i][0], y = idx[i][1];
            vector<int> Q1, Q2;
            query(1, 1, 2*n, x, x, Q1);
            query(1, 1, 2*n, y, y, Q2);
            sat.xoro(Q1[0]*2, Q2[0]*2);
        }
        int ok = sat.two_sat();
        if(ok == 1) ans = mid, lo = mid+1;
        else hi = mid-1;
    }
    printf("%d\n", ans);
}

