	for(int l,r,i=1;i<=m;++i){
		l=lowerbound(i,s[i].v-x);
		r=upperbound(i,s[i].v+x);
		for(;l<i;++l) G.adj(i,l+m);
		for(;r>i;--r) G.adj(i,r+m);
	}
}
