struct RangeGraph{
  vector<vector<edge>>g;
  ll n,sz;
  ll cnt;
  RangeGraph(ll n,ll m):n(n){
    sz=1;
    cnt=0;
    while(sz<n)sz <<= 1;
    g.assign(4*sz+n+m,vector<edge>());
    for(ll i=1;i<sz;i++){
      g[i].EB(2*i,0);
      g[i].EB(2*i+1,0);
      g[2*i+2*sz].EB(i+2*sz,0);
      g[2*i+1+2*sz].EB(i+2*sz,0);
    }
    for(ll i=0;i<n;i++){
      g[i+sz].EB(i+4*sz,0);
      g[i+4*sz].EB(i+3*sz,0);
    }
  }
  void add_edge(ll l1,ll r1,ll l2,ll r2,ll w){//[l1,r1)->[l2,r2)
    if(l1>=r1||l2>=r2)return;
    auto v=range(l1,r1);
    ll via=4*sz+n+cnt;
    for(auto z:v)g[z+2*sz].EB(via,w);
    v=range(l2,r2);
    for(auto z:v)g[via].EB(z,0);
    cnt++;
  }
  vector<ll>range(ll l,ll r){
    vector<ll>ret;
    l+=sz,r+=sz;
    while(l!=r){
      if(l&1)ret.PB(l++);
      if(r&1)ret.PB(--r);
      l>>=1,r>>=1;
    }
    return ret;
  };
  ll add(){
    return 4*sz;
  }
};

struct SCC{
  ll n;
  vector<vector<struct edge>>G,Gr;
