const int N = 1e4 + 20 , SQ = 150 , MX = 2 * N + 2 * SQ , inf = 1e9 + 20 ;
int n , x[2 * N] , ord[2 * N] ;
vector <int> g[MX] , h[MX] ;

inline bool cmp (int i , int j) {
	return x[i] < x[j] ;
}

inline void add_edge (int u , int v) {
	g[u].push_back(v) ;
	h[v].push_back(u) ;
}	

inline void add_clause (int u , int v) {
	add_edge(u ^ 1 , v) ;
	add_edge(v ^ 1 , u) ;
}

inline int get_lower_bound (int i , int d) {
	int low = i , high = 2 * n ;

	while (high - low > 1) {
		int mid = (low + high) / 2 ;

		if (x[ord[mid]] - x[ord[i]] >= d) high = mid ;
		else low = mid ;
	}

	return high ;
}

inline int block_id (int b) { return 2 * n + 2 * b ; }

inline void find_edges (int v , int l , int r) {
	while (l % SQ && l < r)
		add_clause(v ^ 1 , ord[l ++] ^ 1) ;

	while (r % SQ && l < r)
		add_clause(v ^ 1 , ord[-- r] ^ 1) ;

	for (int b = l / SQ ; b < r / SQ ; b ++)
		add_clause(v ^ 1 , block_id(b)) ;
}

vector <int> tpl ;
bool vis[MX] ;
int comp[MX] ;

void dfs (int v) {
	vis[v] = 1 ;
	for (int u : g[v]) if (!vis[u]) dfs(u) ;
	tpl.push_back(v) ;
}

void sfd (int v , int C) {
	comp[v] = C ;
	for (int u : h[v]) if (!comp[u]) sfd(u , C) ;
}

