	for (int i = 0 ; i < n ; i ++) cin >> x[2 * i] >> x[2 * i + 1] ;

	iota(ord , ord + 2 * n , 0) ;
	sort(ord , ord + 2 * n , cmp) ;

	int m = 2 * n + 2 * SQ ;

	int low = 0 , high = inf ;

	low = 0 , high = inf ;

	while (high - low > 1) {
		int mid = (low + high) / 2 ;

		tpl.clear() ;
		for (int i = 0 ; i < m ; i ++) {
			g[i].clear() ;
			h[i].clear() ;
			comp[i] = 0 ;
			vis[i] = 0 ;
		}

		for (int i = 0 ; i < 2 * n ; i ++) {
			int u = block_id(i / SQ) , v = ord[i] ;
			add_clause(u ^ 1 , v ^ 1) ;
		}

		for (int i = 0 ; i < 2 * n ; i ++) {
			int id = get_lower_bound(i , mid) ;
			find_edges(ord[i] , i + 1 , id) ;
		}

		for (int i = 0 ; i < m ; i ++)
			if (!vis[i]) dfs(i) ;

		reverse(tpl.begin() , tpl.end()) ;

		int C = 0 ;
		for (int x : tpl) 
			if (!comp[x]) sfd(x , ++C) ;

		bool ok = 1 ;
		for (int i = 0 ; i < m ; i ++)
			ok &= (comp[i] != comp[i ^ 1]) ;

		if (ok) low = mid ;
		else high = mid ;
	}

	cout << low << '\n' ;
}

