	vis[v] = 1 ;
	for (int u : g[v]) if (!vis[u]) dfs(u) ;
	tpl.push_back(v) ;
}

void sfd (int v , int C) {
	comp[v] = C ;
	for (int u : h[v]) if (!comp[u]) sfd(u , C) ;
