int deg[N], val[N];

bool Topsort(){
	queue<int> q;
	For(i, 1, m) if(!deg[i]) q.push(i);
	while(!q.empty()){
		int o = q.front(), sz; q.pop();
		sz = int(dif[o].size()) - 1;
		val[o] = 1;
		For(i, 0, sz) if(val[dif[o][i]] == 1){
			val[o] = 0;
			break;
		}
		if(!val[o]) For(i, 0, sz) if(val[dif[o][i]] == 0) return false;
		sz = int(G[o].size()) - 1;
		For(i, 0, sz){
			int v = G[o][i];
			if(!--deg[v]) q.push(v);
		}
	}
	return true;
}

