		j = posy[i];
		while(j < c && B[j + 1].x - A[i].y < lim && j - posy[i] < 20) ++j, add(i << 1 | 1, B[j].o ^ 1), add(B[j].o, i << 1);
	}

	clk = 0;
	For(i, 2, n * 2 + 1) if(!dfn[i]) Tarjan(i);

	For(i, 1, m) G[i].clear(), dif[i].clear(), deg[i] = 0, val[i] = -1;
