struct Segment_Tree {
	struct node {
		int l, r, val;
		node *ch[2];
		node(int l, int r) : l(l), r(r) {
			val = 0;
			ch[0] = ch[1] = NULL;
		}
		int mid() { return (l + r) >> 1; }
	} *root;
	void build(node *&o, int l, int r) {
		o = new node(l, r);
		if(l == r) {
			o->val = e[l].second;
			return;
		}
		o->val = ++ node_cnt;
		build(o->ch[0], l, o->mid());
		build(o->ch[1], o->mid() + 1, r);
		add(o->val, o->ch[0]->val);
		add(o->val, o->ch[1]->val);
	}
	void link(node *o, int l, int r, int u) {
		if(r < l) return;
		if(l <= o->l && o->r <= r) {
			add(u, o->val);
			return;
		}
		if(l <= o->mid()) link(o->ch[0], l, r, u);
		if(r > o->mid()) link(o->ch[1], l, r, u);
	}
} tr;

void Tarjan(int x) {
    low[x] = dfn[x] = ++ tot;
    sta[++ tp] = x;
    for(int i = head[x]; i; i = nxt[i]) {
        if(! dfn[to[i]]) {
            Tarjan(to[i]);
            low[x] = Min(low[x], low[to[i]]);
        }
        else if(scc[to[i]] == 0) {
        	low[x] = Min(low[x], dfn[to[i]]);
		}
    }
    if(dfn[x] == low[x]) {
    	int t; scc_cnt ++;
    	do {
    		t = sta[tp --];
    		scc[t] = scc_cnt;
    	} while(t != x);
    }
}

bool check(int x) {
    cnt = tot = scc_cnt = tp = 0; node_cnt = 2 * n;
    memset(head, 0, sizeof(head));
    tr.build(tr.root, 1, 2 * n);
    for(int i = 1; i <= n; ++ i) {
        for(int k = 0; k <= 1; ++ k) {
            int l = lower_bound(e + 1, e + 2*n + 1,make_pair(a[i][k]-x+1, 0)) - e;
            int r = upper_bound(e + 1, e + 2*n + 1,make_pair(a[i][k]+x-1, 2*n+1)) - e - 1;
            int m = lower_bound(e + 1, e + 2*n + 1,make_pair(a[i][k], (k^1)*n+i)) - e;
            tr.link(tr.root, l, m - 1, k * n + i);
            tr.link(tr.root, m + 1, r, k * n + i);
        }
    }
    memset(dfn,0,sizeof(dfn));
    memset(low,0,sizeof(low));
    memset(scc,0,sizeof(scc));
    for(int i=1;i<=node_cnt;i++) {
        if(!dfn[i]) Tarjan(i);
    }
    for(int i=1;i<=n;i++) {
        if(scc[i]==scc[i+n]) return 0;
    }
    return 1;
}

