const LL P=1e8;
int n,N=0;
struct data {
    LL x,y;
    int num;
}a[K+10],b[K+10],c[K+10];
bool cmpx(data p,data q) {
    return p.x<q.x;
}
bool cmpy(data p,data q) {
    return p.y<q.y;
}
bool cmp(data p,data q) {
    return p.num<q.num;
}
LL Abs(LL x) {
