        if (i!=1&&a[i].x==a[i-1].x/P) a[i].x=a[i-1].x+1;
        else a[i].x*=P;
    sort(a+1,a+n+1,cmpy);
    for (int i=1;i<=n;i++)
        if (i!=1&&a[i].y==a[i-1].y/P) a[i].y=a[i-1].y+1;
        else a[i].y*=P;
    sort(a+1,a+n+1,cmpx);
    for (int i=1;i<=n;i++) b[i]=a[i];
    sort(a+1,a+n+1,cmpy);
    for (int i=1;i<=n;i++) c[i]=a[i];
    sort(a+1,a+n+1,cmp);
    LL l=0,r=1e9;
    if (!check(1000000ll*P-1e4)) r=1e6;
