/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		FastScanner in = new FastScanner(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		TaskF solver = new TaskF();
		solver.solve(1, in, out);
		out.close();
	}

	static class TaskF {
		int n;
		Point[] ps;
		SAT2Solver solver;
		int maxNodeId;

		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			// n <= 10^4, TL 5 sec.
			n = in.nextInt();
			int min = Integer.MAX_VALUE;
			int max = Integer.MIN_VALUE;
			ps = new Point[2 * n];
			for (int i = 0; i < n; i++) {
				int x = in.nextInt();
				int y = in.nextInt();
				min = Math.min(min, x);
				min = Math.min(min, y);
				max = Math.max(max, x);
				max = Math.max(max, y);
				ps[2 * i] = new Point(x, i, true);
				ps[2 * i + 1] = new Point(y, i, false);
			}
			Arrays.sort(ps);
			{
				maxNodeId = 0;
				initTree(0, 0, ps.length - 1, true);
				solver = new SAT2Solver(n + (maxNodeId + 1));
			}
			int l = 0;
			int r = max - min + 1;
			while (r - l > 1) {
				int m = l + (r - l) / 2;
				if (can(m)) {
					l = m;
				} else {
					r = m;
				}
			}
			out.println(l);
		}

		private boolean can(int d) {
			solver.clear();
			initTree(0, 0, ps.length - 1, false);
			int j = 0;
			for (int i = 0; i < ps.length; i++) {
				while (j < ps.length && ps[j].x - ps[i].x < d) {
					++j;
				}
				block(0, 0, ps.length - 1, i + 1, j - 1, i);
			}
			return solver.solve();
		}

		private void block(int root, int l, int r, int L, int R, int condition) {
			if (l > r || l > R || L > r || L > R) {
				return;
			}
			if (l == L && r == R) {
				// If the conditioned point takes on its .f value, the root is blocked.
				solver.addClause(ps[condition].id, n + root, ps[condition].f, true);
				solver.addClause(n + root, ps[condition].id, false, !ps[condition].f);
				return;
			}
			int m = (l + r) / 2;
			block(2 * root + 1, l, m, L, Math.min(m, R), condition);
			block(2 * root + 2, m + 1, r, Math.max(m + 1, L), R, condition);
		}

		private void initTree(int root, int l, int r, boolean countOnly) {
			maxNodeId = Math.max(maxNodeId, root);
			if (l == r) {
				// If a leaf node is blocked, the corresponding point cannot take on its .f value.
				if (countOnly) {
					return;
				}
				solver.addClause(n + root, ps[l].id, true, !ps[l].f);
				solver.addClause(ps[l].id, n + root, ps[l].f, false);
				return;
			}
			int m = (l + r) / 2;
			initTree(2 * root + 1, l, m, countOnly);
			initTree(2 * root + 2, m + 1, r, countOnly);
			if (countOnly) {
				return;
			}
			for (int child = 2 * root + 1; child <= 2 * root + 2; child++) {
				// If the root is blocked, so are its children.
				solver.addClause(n + root, n + child, true, true);
				solver.addClause(n + child, n + root, false, false);
			}
		}

		class Point implements Comparable<Point> {
			int x;
			int id;
			boolean f;

			Point(int x, int id, boolean f) {
				this.x = x;
				this.id = id;
				this.f = f;
			}

			public int compareTo(Point o) {
				return x - o.x;
			}

		}

		class SAT2Solver {
			boolean[] isTrue;
			int n;
			int numComps;
			int[] low;
			int[] vis;
			int[] comp;
			boolean[] onStack;
			int[] stack;
			int sp;
			int globalTime;
			int numEdges;
			int[] firstEdge;
			int[] edgeDst = new int[10];
			int[] edgeNxt = new int[10];

			SAT2Solver(int n) {
				this.n = n;
				isTrue = new boolean[2 * n];
				vis = new int[2 * n];
				low = new int[2 * n];
				stack = new int[2 * n];
				comp = new int[2 * n];
				onStack = new boolean[2 * n];
				firstEdge = new int[2 * n];
			}

			public void clear() {
				Arrays.fill(firstEdge, -1);
				numEdges = 0;
			}

			public void addClause(int v1, int v2, boolean neg1, boolean neg2) {
				if (neg1) {
					v1 = negate(v1);
				}
				if (neg2) {
					v2 = negate(v2);
				}
				addEdge(v1, v2);
			}

			private void addEdge(int a, int b) {
				int e = numEdges++;
				if (e >= edgeDst.length) {
					int k = edgeDst.length;
					int[] dst = new int[3 * k / 2 + 1];
					System.arraycopy(edgeDst, 0, dst, 0, k);
					edgeDst = dst;
					int[] nxt = new int[3 * k / 2 + 1];
					System.arraycopy(edgeNxt, 0, nxt, 0, k);
					edgeNxt = nxt;
				}
				edgeDst[e] = b;
				edgeNxt[e] = firstEdge[a];
				firstEdge[a] = e;
			}

			public boolean solve() {

				Arrays.fill(vis, -1);
				Arrays.fill(onStack, false);
				sp = 0;
				globalTime = 0;
				numComps = 0;
				for (int i = 0; i < 2 * n; i++) {
					if (vis[i] < 0) {
						dfsTarjan(i);
					}
				}
				int[] firstInComp = new int[numComps];
				Arrays.fill(firstInComp, -1);
				int[] nextSameComp = new int[2 * n];
				for (int i = 0; i < 2 * n; i++) {
					int c = comp[i];
					nextSameComp[i] = firstInComp[c];
					firstInComp[c] = i;
				}
				List<Integer>[] invertedCompEdges = new List[numComps];
				for (int i = 0; i < numComps; i++) {
					invertedCompEdges[i] = new ArrayList<>();
				}
				for (int i = 0; i < 2 * n; i++) {
					for (int e = firstEdge[i]; e >= 0; e = edgeNxt[e]) {
						int j = edgeDst[e];
						invertedCompEdges[comp[j]].add(comp[i]);
					}
				}
				boolean[] compIsTrue = new boolean[numComps];
				Arrays.fill(compIsTrue, true);
				for (int c = 0; c < numComps; c++) {
					if (!compIsTrue[c]) {
						continue;
					}
					for (int i = firstInComp[c]; i >= 0; i = nextSameComp[i]) {
						int nc = comp[negate(i)];
						if (c == nc) {
							return false;
						}
					}
					for (int i = firstInComp[c]; i >= 0; i = nextSameComp[i]) {
						int nc = comp[negate(i)];
						dfsReject(nc, invertedCompEdges, compIsTrue);
					}
				}
				for (int i = 0; i < 2 * n; i++) {
					isTrue[i] = compIsTrue[comp[i]];
				}
				for (int i = 0; i < n; i++) {
					if (isTrue[i] && isTrue[negate(i)]) {
						throw new AssertionError();
					}
					if (!isTrue[i] && !isTrue[negate(i)]) {
						return false;
					}
				}
				return true;
			}

			private int negate(int i) {
				return i + (i < n ? n : -n);
			}

			private void dfsReject(int c, List<Integer>[] invertedCompEdges, boolean[] compIsTrue) {
				if (!compIsTrue[c]) {
					return;
				}
				compIsTrue[c] = false;
				for (int p : invertedCompEdges[c]) {
					dfsReject(p, invertedCompEdges, compIsTrue);
				}
			}

			void dfsTarjan(int v) {
				vis[v] = globalTime;
				low[v] = globalTime;
				++globalTime;
				stack[sp++] = v;
				onStack[v] = true;
				for (int e = firstEdge[v]; e >= 0; e = edgeNxt[e]) {
					int u = edgeDst[e];
					if (vis[u] < 0) {
						dfsTarjan(u);
						if (low[v] > low[u]) {
							low[v] = low[u];
						}
					} else if (onStack[u] && low[v] > vis[u]) {
						low[v] = vis[u];
					}
				}
				if (low[v] == vis[v]) {
					while (true) {
						int u = stack[--sp];
						onStack[u] = false;
						comp[u] = numComps;
						if (u == v) {
							break;
						}
					}
					++numComps;
				}
			}

		}

	}

	static class FastScanner {
		private BufferedReader in;
		private StringTokenizer st;

		public FastScanner(InputStream stream) {
			in = new BufferedReader(new InputStreamReader(stream));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					String rl = in.readLine();
					if (rl == null) {
						return null;
					}
					st = new StringTokenizer(rl);
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return st.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

	}
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;
import java.util.Scanner;

class Main {
	public static void main(String[] args) {
		new Main().run();
	}

	void run() {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int[][] x = new int[N][2];
		for (int i = 0; i < N; ++i) {
			x[i][0] = sc.nextInt();
			x[i][1] = sc.nextInt();
		}

		int ng = 1_000_000_000 + 1;
		int ok = 0;
		while (ng - ok > 1) {
			int middle = (ok + ng) / 2;
			if (f(N, x, middle)) {
				ok = middle;
			} else {
				ng = middle;
			}
		}
		System.out.println(ok);
	}

	Comparator<int[]> comp = new Comparator<int[]>() {
		@Override
		public int compare(int[] o1, int[] o2) {
			if (o1[0] != o2[0]) {
				return Integer.compare(o1[0], o2[0]);
			} else {
				return Integer.compare(o1[1], o2[1]);
			}

		}
	};

	boolean f(int N, int[][] x, int d) {
		int sz = 1;
		while (sz < 2 * N)
			sz *= 2;
		int[][] arr = new int[2 * N][];
		for (int i = 0; i < N; ++i) {
			arr[i] = new int[] { x[i][0], i };
			arr[i + N] = new int[] { x[i][1], i };
		}
		Arrays.sort(arr, comp);
		ArrayList<Integer>[] lis = new ArrayList[N];
		for (int i = 0; i < N; ++i) {
			lis[i] = new ArrayList<>();
		}
		for (int i = 0; i < 2 * N; ++i) {
			lis[arr[i][1]].add(i);
		}
		ArrayList<Integer>[] g = new ArrayList[2 * sz + sz - 1];
		for (int i = 0; i < g.length; ++i) {
			g[i] = new ArrayList<>();
		}
		for (int i = 0; i < N; ++i) {
			int xId = lis[i].get(0);
			int yId = lis[i].get(1);
			g[xId + sz - 1].add(yId + 2 * sz - 1);
			g[xId + 2 * sz - 1].add(yId + sz - 1);
			g[yId + sz - 1].add(xId + 2 * sz - 1);
			g[yId + 2 * sz - 1].add(xId + sz - 1);
		}
		for (int i = 0; i < sz - 1; ++i) {
			g[i].add(2 * i + 1);
			g[i].add(2 * i + 2);
		}

		for (int i = 0; i < arr.length; ++i) {
			arr[i][1] = i;
		}
		for (int i = 0; i < arr.length; ++i) {
			int v = arr[i][0];
			IntervalConnect(new int[] { v - d + 1, -Integer.MAX_VALUE }, new int[] { v, i - 1 }, 0, sz - 1, 0, g, arr,
					i + 2 * sz - 1);
			IntervalConnect(new int[] { v, i + 1 }, new int[] { v + d - 1, Integer.MAX_VALUE }, 0, sz - 1, 0, g, arr,
					i + 2 * sz - 1);
		}

		int[] col = new int[2 * sz + sz - 1];
		stronglyConnectedComponent(g, col);
		System.gc();
		for (int i = 0; i < 2 * N; ++i) {
			if (col[i + sz - 1] == col[i + 2 * sz - 1]) {
				return false;
			}
		}
		return true;
	}

	// [a,b],[L,R]
	void IntervalConnect(int[] a, int[] b, int l, int r, int k, ArrayList<Integer>[] g, int[][] arr, int src) {
		if (l >= arr.length) {
			return;
		} else if (r >= arr.length) {
			IntervalConnect(a, b, l, (l + r) / 2, 2 * k + 1, g, arr, src);
			IntervalConnect(a, b, (l + r) / 2 + 1, r, 2 * k + 2, g, arr, src);
			return;
		}
		int[] L = arr[l];
		int[] R = arr[r];
		if (comp.compare(a, L) <= 0 && comp.compare(R, b) <= 0) {
			g[src].add(k);
			return;
		} else if (comp.compare(b, L) < 0 || comp.compare(R, a) < 0) {
			return;
		} else {
			IntervalConnect(a, b, l, (l + r) / 2, 2 * k + 1, g, arr, src);
			IntervalConnect(a, b, (l + r) / 2 + 1, r, 2 * k + 2, g, arr, src);
			return;
		}
	}

	class State {
		int i;
		int j;
		int parent;

		public State(int i_, int j_, int parent_) {
			i = i_;
			j = j_;
			parent = parent_;
		}
	}

	int stronglyConnectedComponent(ArrayList<Integer>[] g, int[] col) {
		int n = g.length;
		int order = 0;
		int cols = 0;
		int[] ord = new int[n];
		int[] low = new int[n];
		Arrays.fill(col, -1);
		Arrays.fill(ord, -1);
		Arrays.fill(low, -1);
		ArrayDeque<State> stk = new ArrayDeque<>();
		ArrayDeque<Integer> pnd = new ArrayDeque<>();
		for (int ii = 0; ii < n; ++ii) {
			if (ord[ii] != -1) {
				continue;
			}
			stk.add(new State(ii, 0, -1));
			while (!stk.isEmpty()) {
				State s = stk.pollFirst();
				if (ord[s.i] == -1) {
					low[s.i] = (ord[s.i] = order++);
					pnd.addFirst(s.i);
				}
				if (s.j - 1 >= 0 && g[s.i].get(s.j - 1) != s.parent && col[g[s.i].get(s.j - 1)] == -1) {
					low[s.i] = Math.min(low[s.i], low[g[s.i].get(s.j - 1)]);
				}
				if (s.j == g[s.i].size() && low[s.i] == ord[s.i]) {
					while (true) {
						int v = pnd.pollFirst();
						col[v] = cols;
						if (v == s.i)
							break;
					}
					++cols;
					continue;
				}
				if (s.j == g[s.i].size()) {
					continue;
				}
				stk.addFirst(new State(s.i, s.j + 1, s.parent));
				int dst = g[s.i].get(s.j);
				if (ord[dst] == -1) {
					stk.addFirst(new State(dst, 0, s.i));
				} else if (col[dst] == -1) {
					low[s.i] = Math.min(low[s.i], low[dst]);
				}
			}
		}
		return cols;
	}

	void tr(Object... objects) {
		System.out.println(Arrays.deepToString(objects));
	}
}

