class TwoSat
{
    StronglyConnectedComponents scc;
    public bool[] Answer { get; private set; }
    public TwoSat(int N)
    {
        scc = new StronglyConnectedComponents(N << 1);
        Answer = new bool[N];
    }
    //(x_i=f)V(x_j=g) <-> !(x_i=f)->(x_j=g) <-> !(x_j=g)->(x_i=f)の追加
    public void AddClosure(int i, bool f, int j, bool g)
    {
        scc.AddEdge((i << 1) | (f ? 0 : 1), (j << 1) | (g ? 1 : 0));
        scc.AddEdge((j << 1) | (g ? 0 : 1), (i << 1) | (f ? 1 : 0));
    }
    public bool Execute()
    {
        scc.Execute();
        var gp = scc.Group;
        var len = gp.Length >> 1;
        for (int i = 0; i < len; i++)
        {
            if (gp[i << 1] == gp[(i << 1) | 1]) return false;
            Answer[i] = gp[i << 1] < gp[(i << 1) | 1];//DAG
        }
        return true;
    }
}

public class StronglyConnectedComponents
{
    int size;
    List<Edge> edges;
    private int[][] scc;
    public int Count { get; private set; }
    public int[] Group { get; private set; }
    public int[] GroupAt(int k) => scc[k];
    public StronglyConnectedComponents(int count)
    {
        size = count;
        edges = new List<Edge>();
    }
    public void AddEdge(int from, int to)
    {
        edges.Add(new Edge(from, to));
    }
    /// <summary>
    /// O(V+E)
    /// </summary>
    /// <returns>scc[i]:i番目の強連結成分の頂点</returns>
    public int[][] Execute()
    {
        //e.fromでe.toをソート
        var start = new int[size + 1];
        var toList = new int[edges.Count];
        foreach (var e in edges) start[e.from + 1]++;
        for (int i = 0; i < start.Length - 1; i++) start[i + 1] += start[i];
        var count = start.ToArray();
        foreach (var e in edges) toList[count[e.from]++] = e.to;
        //lowlink
        int nowOrd = 0;
        int[] low = new int[size], ord = new int[size];
        Group = new int[size];
        var stack = new Stack<int>(size);
        for (int i = 0; i < ord.Length; i++) ord[i] = -1;
        Action<int> dfs = null;
        dfs = v =>
        {
            low[v] = ord[v] = nowOrd++;
            stack.Push(v);
            for (int i = start[v]; i < start[v + 1]; i++)
            {
                var to = toList[i];
                if (ord[to] == -1)
                {
                    dfs(to);
                    low[v] = Min(low[v], low[to]);
                }
                else low[v] = Min(low[v], ord[to]);
            }
            if (low[v] == ord[v])
            {
                while (true)
                {
                    var u = stack.Pop();
                    ord[u] = size;
                    Group[u] = Count;
                    if (u == v) break;
                }
                Count++;
            }
        };
        for (int i = 0; i < ord.Length; i++)
        {
            if (ord[i] == -1) dfs(i);
        }
        for (int i = 0; i < Group.Length; i++)
        {
            Group[i] = Count - 1 - Group[i];
            count[i] = 0;
        }
        scc = new int[Count][];
        foreach (var g in Group) count[g]++;
        for (int i = 0; i < scc.Length; i++) scc[i] = new int[count[i]];
        for (int i = 0; i < Group.Length; i++) scc[Group[i]][--count[Group[i]]] = i;
        return scc;
    }
    struct Edge { public int from, to; public Edge(int f, int t) { from = f; to = t; } }
}
public class FastScanner
{
    //0x0a:LF 0x20:SPC 0x2d:- 0x30 ~ 0x39: 0 ~ 9
    static System.IO.Stream str = System.Console.OpenStandardInput();
    const int size = 1 << 10;
    static byte[] buffer = new byte[size];
    static int ptr;
    static int len;
    public int Int
    {
        get
        {
            var c = Read();
            while (c < 0x21)
            {
                c = Read();
            }
            var n = false;
            if (c == '-')
            {
                n = true;
                c = Read();
            }
            var ret = 0;
            while (c >= 0x30)
            {
                ret = ret * 10 + (c & 15);
                c = Read();
            }
            return n ? -ret : ret;
        }
    }
    public long Long
    {
        get
        {
            var c = Read();
            while (c < 0x21)
            {
                c = Read();
            }
            var n = false;
            if (c == '-')
            {
                n = true;
                c = Read();
            }
            var ret = 0L;
            while (c >= 0x30)
            {
                ret = ret * 10 + (c & 15);
                c = Read();
            }
            return n ? -ret : ret;
        }
    }
    byte Read()
    {
        if (ptr == len)
        {
            len = str.Read(buffer, 0, size);
            if (len == 0) return 0;
            ptr = 0;
        }
        return buffer[ptr++];
    }
}
