public class Tsat{
	public List<int>[] li,lir,lid;
	public int[] zt;
	private int n;
	public Tsat(int n){
		this.n=n<<1;
		li=new List<int>[this.n];
		lir=new List<int>[this.n];
		for(int i=0;i<this.n;i++){
			li[i]=new List<int>();
			lir[i]=new List<int>();
		}
	}
	public void Edge(int a,int b){
		li[a].Add(b);
		lir[b].Add(a);
	}
	public void Edge(int a,int c,int b,int d){
		a=(a<<1)+c;b=(b<<1)+d;
		li[a].Add(b);
		lir[b].Add(a);
	}
	public int Ck(int a){
		a<<=1;
		return zt[a]==zt[a+1]?-1:(zt[a]>zt[a+1]?0:1);
	}
	public void Scc(){
		var h=new int[n];
		var b=new bool[n];
		zt=new int[n];
		int kk=n-1,km=0;
		for(int i=0;i<n;i++){if(!b[i]){Fud1(i);}}
		for(int i=0;i<n;i++){
			if(b[h[i]]){
				Fud2(h[i]);
				km++;
			}
		}
		lid=new List<int>[km];
		for(int i=0;i<km;i++){lid[i]=new List<int>();}
		for(int i=0;i<n;i++){
			for(int j=0;j<li[i].Count;j++){if(zt[i]!=zt[li[i][j]]){lid[zt[i]].Add(zt[li[i][j]]);}}
		}
		for(int i=0;i<km;i++){
			lid[i]=lid[i].Distinct().ToList();
		}
		void Fud1(int a){
			b[a]=true;
			for(int i=0;i<li[a].Count;i++){if(!b[li[a][i]]){Fud1(li[a][i]);}}
			h[kk--]=a;
		}
		void Fud2(int a){
			zt[a]=km;
			b[a]=false;
			for(int i=0;i<lir[a].Count;i++){if(b[lir[a][i]]){Fud2(lir[a][i]);}}
		}
	}
}
