public class Stg{
	public List<int>[] li;
	public int n,o;
	public Stg(List<int>[] li,int o,int n,bool b){
		this.li=li;
		this.n=n;
		this.o=o;
		for(int i = 1;i<n;i++) {
			li[i+o-1].Add((i<<1)+o-1);
			li[i+o-1].Add((i<<1)+o);
		}
	}
	public void Edge(int a,int l,int r){
		l+=n;r+=n;
		while(l<=r){
			if((l&1)==1){li[a].Add(l+++o-1);}
			if((r&1)==0){li[a].Add(r--+o-1);}
			l>>=1;r>>=1;
		}
	}
	public int Get(int a){return a+n+o-1;}
}
