public struct TwoSatVariable
{
    public int Index;
    public bool TrueOfFalse;
}

public class TwoSatImplication
{
    public TwoSatVariable Variable1;
    public TwoSatVariable Variable2;
}

public class TwoSat
{
    private readonly int N;
    private readonly List<TwoSatImplication> Implications = new List<TwoSatImplication>();

    public TwoSat(int n) { N = n; }

    /// <summary>
    /// P OR Q
    /// </summary>
    public void AddOrClause(int variable1, bool trueOrFalse1, int variable2, bool trueOrFalse2)
    {
        // P or Q === (~P => Q) and (~Q =>P)
        AddImplication(variable1, !trueOrFalse1, variable2, trueOrFalse2);
        AddImplication(variable2, !trueOrFalse2, variable1, trueOrFalse1);
    }

    /// <summary>
    /// ~(P AND Q) (=== ~P OR ~Q)
    /// </summary>
    public void AddNandClause(int variable1, bool trueOrFalse1, int variable2, bool trueOrFalse2)
    {
        AddOrClause(variable1, !trueOrFalse1, variable2, !trueOrFalse2);
    }

    /// <summary>
    /// P (=== P OR P)
    /// </summary>
    public void AddIsTrueClause(int variable1, bool trueOrFalse1)
    {
        AddOrClause(variable1, trueOrFalse1, variable1, trueOrFalse1);
    }

    /// <summary>
    /// (P XOR Q) (=== (P OR Q) AND (~P OR ~Q))
    /// </summary>
    public void AddXorClause(int variable1, bool trueOrFalse1, int variable2, bool trueOrFalse2)
    {
        AddOrClause(variable1, trueOrFalse1, variable2, trueOrFalse2);
        AddOrClause(variable1, !trueOrFalse1, variable2, !trueOrFalse2);
    }

    /// <summary>
    /// P -> Q
    /// </summary>
    public void AddImplication(int variable1, bool trueOrFalse1, int variable2, bool trueOrFalse2)
    {
        Implications.Add(new TwoSatImplication
        {
            Variable1 = new TwoSatVariable { Index = variable1, TrueOfFalse = trueOrFalse1 },
            Variable2 = new TwoSatVariable { Index = variable2, TrueOfFalse = trueOrFalse2 },
        });
    }

    private int ToIndex(TwoSatVariable v)
    {
        return v.TrueOfFalse ? v.Index : v.Index + N;
    }

    public bool Solve(out bool[] value)
    {
        value = null;
        var adj = Enumerable.Range(0, N * 2).Select(_ => new List<int>()).ToArray();
        foreach (var c in Implications)
        {
            adj[ToIndex(c.Variable1)].Add(ToIndex(c.Variable2));
        }
        var scc = new StronglyConnectedComponent(adj);
        var groupIndex = scc.GetGroupArray();

        for (int i = 0; i < N; i++) if (groupIndex[i] == groupIndex[i + N]) return false;
        value = new bool[N];
        for (int i = 0; i < N; i++) if (groupIndex[i] > groupIndex[i + N]) value[i] = true;
        return true;
    }
}

public class StronglyConnectedComponent
{
    readonly int n;
    readonly bool[] isVisited;
    private readonly List<int>[] adjacent;
    private readonly List<int>[] inverseAdjacent;
    private readonly Stack<int> stack = new Stack<int>();

    public StronglyConnectedComponent(List<int>[] adj)
    {
        this.adjacent = adj;
        this.n = adj.Length;
        this.isVisited = new bool[n];
        this.inverseAdjacent = new List<int>[n];
        for (int i = 0; i < n; i++) inverseAdjacent[i] = new List<int>();
        for (int i = 0; i < n; i++)
        {
            foreach (var x in adj[i])
            {
                inverseAdjacent[x].Add(i);
            }
        }
    }

    void Traverse(int k, List<int>[] adjacent, List<int> label)
    {
        if (isVisited[k]) return;
        var order = new List<int>();
        stack.Push(k);
        while (stack.Count > 0)
        {
            var top = stack.Pop();
            if (isVisited[top]) continue;
            isVisited[top] = true;
            order.Add(top);
            foreach (var x in adjacent[top]) stack.Push(x);
        }
        order.Reverse();
        label.AddRange(order);
    }

    public List<List<int>> Run()
    {
        var label = new List<int>();
        for (int i = 0; i < n; i++)
            Traverse(i, adjacent, label);
        label.Reverse();
        Array.Clear(isVisited, 0, isVisited.Length);
        var components = new List<List<int>>();
        foreach (var x in label)
        {
            if (!isVisited[x])
            {
                var group = new List<int>();
                Traverse(x, inverseAdjacent, group);
                components.Add(group);
            }
        }
        return components;
    }

    public int[] GetGroupArray()
    {
        var component = Run();
        var group = new int[n];
        for (int i = 0; i < component.Count; i++)
        {
            foreach (var x in component[i])
            {
                group[x] = i;
            }
        }
        return group; // group index is topological order
    }
}
