public class Tsat{
	public List<int>[] li,lir,lid;
	public int[] zt;
	private int n;
	public Tsat(int n){
		this.n=n<<1;
		li=new List<int>[this.n];
		lir=new List<int>[this.n];
		for(int i=0;i<this.n;i++){
			li[i]=new List<int>();
			lir[i]=new List<int>();
		}
	}
	public void Edge(int a,int b){
		li[a].Add(b);
		lir[b].Add(a);
	}
	public void Edge(int a,int c,int b,int d){
		a=(a<<1)+c;b=(b<<1)+d;
		li[a].Add(b);
		lir[b].Add(a);
	}
	public int Ck(int a){
		a<<=1;
		return zt[a]==zt[a+1]?-1:(zt[a]>zt[a+1]?0:1);
	}
	public void Scc(){
		var h=new int[n];
		var b=new bool[n];
		zt=new int[n];
		int kk=n-1,km=0;
		for(int i=0;i<n;i++){if(!b[i]){Fud1(i);}}
