		}
		lid=new List<int>[km];
		for(int i=0;i<km;i++){lid[i]=new List<int>();}
		for(int i=0;i<n;i++){
			for(int j=0;j<li[i].Count;j++){if(zt[i]!=zt[li[i][j]]){lid[zt[i]].Add(zt[li[i][j]]);}}
		}
		for(int i=0;i<km;i++){
			lid[i]=lid[i].Distinct().ToList();
		}
		void Fud1(int a){
			b[a]=true;
			for(int i=0;i<li[a].Count;i++){if(!b[li[a][i]]){Fud1(li[a][i]);}}
			h[kk--]=a;
		}
		void Fud2(int a){
			zt[a]=km;
			b[a]=false;
			for(int i=0;i<lir[a].Count;i++){if(b[lir[a][i]]){Fud2(lir[a][i]);}}
		}
	}
}
