// module dcomp.graph.scc;

struct SCC {
    int[] id; // vertex id -> scc id
    int[][] groups; // scc id -> scc vertexs
    int count; // scc count
    this(int n) {
        id = new int[n];
    }
}

SCC scc(T)(T g) {
    import std.array : appender;
    import std.range;
    import std.algorithm : each;
    import std.conv : to;
    int n = g.length.to!int;
    //make reverse graph
    struct Edge {int to;}
    Edge[][] rg = new Edge[][](n);
    g.each!((i, v) => v.each!(e => rg[e.to] ~= Edge(i.to!int)));

    auto sccInfo = SCC(n);
    with (sccInfo) {
        auto used = new bool[n];

        //make backorder list
        auto vs = appender!(int[])();
        void dfs(int v) {
            used[v] = true;
            foreach (e; g[v]) {
                if (used[e.to]) continue;
                dfs(e.to);
            }
            vs ~= v;
        }
        foreach (i; 0..n) {
            if (used[i]) continue;
            dfs(i);
        }

        used[] = false;        
        count = 0;
        auto buf = appender!(int[])();
        void rdfs(int v) {
            used[v] = true;
            id[v] = count;
            buf ~= v;
            foreach (e; rg[v]) {
                if (used[e.to]) continue;
                rdfs(e.to);
            }
        }
        foreach_reverse (i; vs.data) {
            if (used[i]) continue;
            rdfs(i);
            groups ~= buf.data().dup;
            buf.clear();
            count++;
        }
    }
    return sccInfo;
}

