import core.bitop : bsr;

immutable INF = 10^^9 + 10^^7;

int n;
int[] pos;

//md より大きくは出来ない
bool solve(int md) {
    int[] v;
    pos.each!((x){
        v ~= x-md;
        v ~= x+md+1;
        v ~= x;
        v ~= x+1;
    });
    v = v.sort!"a<b".uniq.array;
    int m = v.length.to!int;
    int lg = m.bsr;
    if ((2^^lg) < m) lg++;
    m = 1<<lg;
    int getI(int x) {
        return binSearch!(i => v[i] >= x)(-1, v.length.to!int);
    }

    auto sat = TwoSat(2*n + 2*m);
    foreach (i; 0..n) {
        // exactly 1 true
        sat.addCond(2*i, true, 2*i+1, true);
        sat.addCond(2*i, false, 2*i+1, false);
    }
    //make segtree
    foreach (i; 1..m) {
        sat.addCond(2*n+2*i, false, 2*n+i, true);
        sat.addCond(2*n+2*i+1, false, 2*n+i, true);
    }

    void query(int a, int b, int i, int l = 0, int r = m, int k = 1) {
        if (b <= l || r <= a) return;
        if (a <= l && r <= b) {
            sat.addCond(i, false, 2*n+k, false);
            return;
        }
        int md = (l+r)/2;
        query(a, b, i, l, md, 2*k);
        query(a, b, i, md, r, 2*k+1);
    }
//    writeln(v);
    foreach (int i, x; pos) {
        query(getI(x-md), getI(x), i);
        query(getI(x+1), getI(x+md+1), i);
        sat.addCond(i, false, 2*n + m + getI(x), true);
        sat.addCond(i, true, 2*n + m + getI(x), false);
    }
/*    foreach (i; 0..2*n) {
        foreach (j; i+1..2*n) {
            if (abs(pos[i]-pos[j]) <= md) {
                sat.addCond(i, false, j, false);
            }
        }
    }*/
    return sat.exec() == false;
}

int main() {
    auto sc = new Scanner(stdin);
    sc.read(n);
    pos = new int[2*n];
    pos.each!((ref x) => sc.read(x));
    writeln(binSearch!(md => solve(md))(-1, INF));
    return 0;
}
