fn can(m: i32, p: &[(i32, i32)], z: &[(i32, usize)]) -> bool {
    let size = z.len().next_power_of_two();
    let seg: Vec<usize> = (0..(2 * size)).collect();
    let mut sat = SAT2::new(2 * size + 2 * p.len());
    for i in 1..size {
        sat.add(seg[i], !seg[2 * i]);
        sat.add(seg[i], !seg[2 * i + 1]);
    }
    for (i, &(x, y)) in p.iter().enumerate() {
        let a = z.binary_search(&(x, i + 1)).unwrap();
        let b = z.binary_search(&(y, i + 1)).unwrap();
        sat.add(seg[a + size], seg[b + size]);
        for &(x, a, q) in [(x, a, seg[a + size]), (y, b, seg[b + size])].iter() {
            let l = z.binary_search(&(x - (m - 1), 0)).unwrap_err();
            let r = z.binary_search(&(x + (m - 1), p.len() + 1)).unwrap_err();
            for &(mut l, mut r) in [(l, a), (a + 1, r)].iter() {
                l += size;
                r += size;
                while l < r {
                    if l & 1 == 1 {
                        sat.add(!q, !seg[l]);
                        l += 1;
                    }
                    if r & 1 == 1 {
                        r -= 1;
                        sat.add(!q, !seg[r]);
                    }
                    l >>= 1;
                    r >>= 1;
                }
            }
        }
    }
    sat.solve().is_some()
}

