    fn build_graph<'a>(&self, buf: &'a mut [u32], cnt: &[u32], inv: bool) -> Vec<&'a mut [u32]> {
        let size = self.size;
        let mut index = vec![0; self.size];
        for e in self.edge.iter() {
            let (f, t) = if inv { (e.1, e.0) } else { *e };
            buf[self.edge.len() - cnt[f as usize] as usize + index[f as usize]] = t;
            index[f as usize] += 1;
        }
        let mut buf = Some(buf);
        let mut ans = Vec::with_capacity(size);
        for i in 0..size {
            let len = cnt[i] - cnt[i + 1];
            let x = buf.take().unwrap();
            let (x, y) = x.split_at_mut(len as usize);
            ans.push(x);
            buf = Some(y);
        }
        ans
    }
