        z.push((x, i + 1));
        z.push((y, i + 1));
    }
    z.sort();
    z.dedup();
    let size = z.len().next_power_of_two();
    let seg: Vec<usize> = (0..(2 * size)).collect();
    let ng_seg: Vec<usize> = seg.iter().map(|p| !*p).collect();
    let mut index = vec![];
    for i in 0..p.len() {
