use std::io::Read;

fn can(m: i32, p: &[(i32, i32)]) -> bool {
    let mut z = vec![];
    for &(x, y) in p.iter() {
        for &x in [x, y].iter() {
            let mut v = x - m;
            for _ in 0..3 {
                z.push(v);
                v += m;
            }
        }
    }
    z.sort();
    z.dedup();
    let size = z.len().next_power_of_two();
    let seg: Vec<usize> = (0..(2 * size)).collect();
    let ng_seg: Vec<usize> = seg.iter().map(|p| !*p).collect();
    let mut index = vec![];
    for i in 0..p.len() {
        index.push((2 * size + i, 2 * size + p.len() + i));
    }
    let mut sat = SAT2::new(2 * size + 2 * p.len());
    for i in 1..size {
        sat.add(seg[i], ng_seg[2 * i]);
        sat.add(seg[i], ng_seg[2 * i + 1]);
    }
    for (i, &(x, y)) in p.iter().enumerate() {
        sat.add(index[i].0, index[i].1);
        let p = z.binary_search(&x).unwrap();
        let q = z.binary_search(&y).unwrap();
        sat.add(!index[i].0, seg[p + size]);
        sat.add(!index[i].1, seg[q + size]);
        for &(x, p, q) in [(x, p, index[i].0), (y, q, index[i].1)].iter() {
            let l = z.binary_search(&(x - m)).unwrap();
            let r = z.binary_search(&(x + m)).unwrap();
            for &(mut l, mut r) in [(l, p), (p + 1, r + 1)].iter() {
                l += size;
                r += size;
                while l < r {
                    if l & 1 == 1 {
                        sat.add(!q, ng_seg[l]);
                        l += 1;
                    }
                    if r & 1 == 1 {
                        r -= 1;
                        sat.add(!q, ng_seg[r]);
                    }
                    l >>= 1;
                    r >>= 1;
                }
            }
        }
    }
    sat.solve().is_some()
}

fn run() {
    let mut s = String::new();
    std::io::stdin().read_to_string(&mut s).unwrap();
    let mut it = s.trim().split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let mut p = vec![];
    for _ in 0..n {
        let x: i32 = it.next().unwrap().parse().unwrap();
        let y: i32 = it.next().unwrap().parse().unwrap();
        p.push((x, y));
    }
    let mut ok = -1;
    let mut ng = 1_000_000_000i32;
    while ng - ok > 1 {
        let m = (ok + ng) / 2;
        if can(m, &p) {
            ok = m;
        } else {
            ng = m;
        }
    }
    println!("{}", ok + 1);
}

