        for v in 0..size {
            let len = cnt[v] - cnt[v + 1];
            let x = buf.take().unwrap();
            let (x, y) = x.split_at_mut(len);
            graph.push(x);
            buf = Some(y);
        }
        let mut q = Vec::with_capacity(size);
        let mut visited = vec![false; size];
        let mut stack = vec![];
        for v in 0..size {
            if visited[v] {
                continue;
            }
            stack.clear();
            visited[v] = true;
            stack.push((v, graph[v].iter()));
            while let Some((v, mut it)) = stack.pop() {
                let mut finish = true;
                while let Some(&u) = it.next() {
                    if !visited[u] {
                        visited[u] = true;
                        finish = false;
                        stack.push((v, it));
                        stack.push((u, graph[u].iter()));
                        break;
                    }
                }
                if finish {
                    q.push(v);
                }
            }
        }
        q
    }
    fn dfs2(&mut self, cnt: &[usize], q: &[usize]) {
        let size = self.size;
        let mut buf = vec![0; self.edge.len()];
        let mut buf = Some(buf.as_mut_slice());
        let mut index = vec![0; self.size];
        for e in self.edge.iter() {
            buf.as_mut().unwrap()[self.edge.len() - cnt[e.1] + index[e.1]] = e.0;
            index[e.1] += 1;
        }
        let mut inv_graph = Vec::with_capacity(size);
        for v in 0..size {
            let len = cnt[v] - cnt[v + 1];
            let x = buf.take().unwrap();
            let (x, y) = x.split_at_mut(len);
            inv_graph.push(x);
            buf = Some(y);
        }
        self.id.clear();
        self.id.resize(size, size);
        let mut counter = 0;
        let mut stack = vec![];
        for &v in q.iter().rev() {
            if self.id[v] < size {
                continue;
            }
            self.id[v] = counter;
            stack.clear();
            stack.push(v);
            while let Some(v) = stack.pop() {
                self.id[v] = counter;
                for &u in inv_graph[v].iter() {
                    if self.id[u] == size {
                        self.id[u] = counter;
                        stack.push(u);
                    }
                }
            }
            counter += 1;
        }
    }
    pub fn build(&mut self) {
        let size = self.size;
        let mut cnt = vec![0; size + 1];
        let mut inv_cnt = vec![0; size + 1];
        for e in self.edge.iter() {
            cnt[e.0] += 1;
            inv_cnt[e.1] += 1;
        }
        for i in (0..size).rev() {
            cnt[i] += cnt[i + 1];
            inv_cnt[i] += inv_cnt[i + 1];
        }
        let q = self.dfs1(&cnt);
        self.dfs2(&inv_cnt, &q);
    }
    pub fn get_array(&self) -> Vec<usize> {
        self.id.clone()
    }
}
// ---------- end Strongly Connected Components ----------
// ---------- begin 2-SAT ----------
struct SAT2 {
    size: usize,
    scc: SCCforSAT2,
}

impl SAT2 {
    fn new(size: usize) -> Self {
        SAT2 {
            size: size,
            scc: SCCforSAT2::new(2 * size),
        }
    }
    fn add(&mut self, a: usize, b: usize) {
        let size = self.size;
        let (x, ix) = if a >= size {
            (!a + size, !a)
        } else {
            (a, a + size)
        };
        let (y, iy) = if b >= size {
            (!b + size, !b)
        } else {
            (b, b + size)
        };
        self.scc.add_edge(ix, y);
        self.scc.add_edge(iy, x);
    }
    fn solve(&mut self) -> Option<Vec<bool>> {
        self.scc.build();
        let id = self.scc.get_array();
        let mut ans = vec![];
        for i in 0..self.size {
            if id[i] == id[i + self.size] {
                return None;
            } else if id[i] < id[i + self.size] {
                ans.push(false);
            } else {
                ans.push(true);
            }
        }
        Some(ans)
    }
}
// ---------- end 2-SAT ----------

use std::io::Read;

fn can(m: i32, p: &[(i32, i32)], z: &[(i32, usize)]) -> bool {
    let size = z.len().next_power_of_two();
    let seg: Vec<usize> = (0..(2 * size)).collect();
    let mut sat = SAT2::new(2 * size + 2 * p.len());
    for i in 1..size {
        sat.add(seg[i], !seg[2 * i]);
        sat.add(seg[i], !seg[2 * i + 1]);
    }
    for (i, &(x, y)) in p.iter().enumerate() {
        let a = z.binary_search(&(x, i + 1)).unwrap();
        let b = z.binary_search(&(y, i + 1)).unwrap();
        sat.add(seg[a + size], seg[b + size]);
        for &(x, a, q) in [(x, a, seg[a + size]), (y, b, seg[b + size])].iter() {
            let l = z.binary_search(&(x - (m - 1), 0)).unwrap_err();
            let r = z.binary_search(&(x + (m - 1), p.len() + 1)).unwrap_err();
            for &(mut l, mut r) in [(l, a), (a + 1, r)].iter() {
                l += size;
                r += size;
                while l < r {
                    if l & 1 == 1 {
                        sat.add(!q, !seg[l]);
                        l += 1;
                    }
                    if r & 1 == 1 {
                        r -= 1;
                        sat.add(!q, !seg[r]);
                    }
                    l >>= 1;
                    r >>= 1;
                }
            }
        }
    }
    sat.solve().is_some()
}

fn run() {
    let mut s = String::new();
    std::io::stdin().read_to_string(&mut s).unwrap();
    let mut it = s.trim().split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let mut p = vec![];
    let mut z = vec![];
    for i in 0..n {
        let x: i32 = it.next().unwrap().parse().unwrap();
        let y: i32 = it.next().unwrap().parse().unwrap();
        p.push((x, y));
        z.push((x, i + 1));
        z.push((y, i + 1));
    }
    z.sort();
    z.dedup();
    let mut ok = 0;
    let mut ng = 1_000_000_000i32;
    while ng - ok > 1 {
        let m = (ok + ng) / 2;
        if can(m, &p, &z) {
            ok = m;
        } else {
            ng = m;
        }
    }
    println!("{}", ok);
}

fn main() {
    run();
}
